		Mark.artHide()
	end
	if Mark.gkPool then
		Mark.gkPool.finish()
	end
	if Mark.blkPool then
		Mark.blkPool.finish()
	end
	hideLines(ourPath)
	hideLines(enemyPath)
	hideLines(fovLines)
	hideLines(resLines)
	hideLines(slidePath)
