end

Mark.hideSight = function()
	for i = 1, #Mark.sight do
		Mark.sight[i].Visible = false
	end
	hideLines(Mark.stitchUs)
	if Mark.aimGlow then
		hideLines(Mark.aimGlow)
	end
end

Mark.fillTri = function(tri, a, b, c, col)
	local sa, oa, za = worldTo(a)
	local sb, ob, zb = worldTo(b)
	local sc, oc, zc = worldTo(c)
	if oa and ob and oc and za > 0 and zb > 0 and zc > 0 then
		tri.PointA = sa
		tri.PointB = sb
		tri.PointC = sc
		tri.Color = col
		tri.Transparency = 1
		tri.Visible = true
	else
		tri.Visible = false
	end
end

Mark.stepReel = function()
	local now = os.clock()
	if Mark.reelAt and now - Mark.reelAt < 0.008 then
		return Mark.reel
	end
	local dt = math.clamp(now - (Mark.reelAt or now), 0, 0.05)
	Mark.reelAt = now
	local r = Mark.reel
	if not r then
		r = {
			fastAng = 0,
			fastGoal = 0,
			fastWait = 0.04,
			fastDir = 1,
			fastN = 0,
			fastVel = 0,
			drumAng = 0,
			drumVel = 0.6,
			drumDir = 1,
			drumMode = "flick",
			drumT = 0,
			drumN = 0,
			drumPeak = 24,
			roll = 0,
			rollV = 0,
			fastRoll = 0,
			fastRollV = 0,
		}
		Mark.reel = r
	end
	local function kick(amount)
		r.rollV = r.rollV + amount
	end
	local function kickFast(amount)
		r.fastRollV = r.fastRollV + amount
	end
	r.rollV = r.rollV + (-20 * r.roll - 4.6 * r.rollV) * dt
	r.roll = r.roll + r.rollV * dt
	r.fastRollV = r.fastRollV + (-16 * r.fastRoll - 3.8 * r.fastRollV) * dt
	r.fastRoll = r.fastRoll + r.fastRollV * dt
	local err = r.fastGoal - r.fastAng
	if math.abs(err) < 0.06 and math.abs(r.fastVel) < 0.45 then
		r.fastWait = r.fastWait - dt
		r.fastVel = r.fastVel * math.exp(-9 * dt)
		if r.fastWait <= 0 then
			r.fastN = r.fastN + 1
			local n = r.fastN
			if n % 4 == 0 or n % 7 == 5 then
				r.fastDir = -r.fastDir
			end
			local turn = math.pi * 0.5
			local k = n % 6
			if k == 2 then
				turn = math.pi
			elseif k == 5 then
				turn = math.pi * 0.25
			end
			r.fastGoal = r.fastAng + r.fastDir * turn
			r.fastWait = 0.06 + (n * 17) % 5 * 0.04
			kickFast(r.fastDir * 3.4)
		end
	else
		r.fastVel = r.fastVel + (err * 42 - r.fastVel * 8.5) * dt
		r.fastAng = r.fastAng + r.fastVel * dt
	end
	r.drumT = r.drumT + dt
	if r.drumMode == "flick" then
		local a = math.clamp(r.drumT / 0.2, 0, 1)
		local target = r.drumDir * r.drumPeak * (a * a)
		r.drumVel = r.drumVel + (target - r.drumVel) * math.min(1, dt * 16)
		r.drumAng = r.drumAng + r.drumVel * dt
		if r.drumT > 0.22 then
			r.drumMode = "coast"
			r.drumT = 0
			kick(r.drumDir * 6)
		end
	elseif r.drumMode == "coast" then
		r.drumVel = r.drumVel * math.exp(-8 * dt)
		r.drumAng = r.drumAng + r.drumVel * dt
		if math.abs(r.drumVel) < 1.5 or r.drumT > 0.28 then
			local step = math.pi * 0.5
			local snapped = math.floor(r.drumAng / step + 0.5) * step
			r.drumAng = r.drumAng + (snapped - r.drumAng) * math.min(1, dt * 16)
			r.drumMode = "heel"
			r.drumT = 0
			r.drumN = r.drumN + 1
			kick(-r.drumDir * 2.8)
		end
	else
		r.drumVel = r.drumVel * math.exp(-12 * dt)
		r.drumAng = r.drumAng + r.drumVel * dt
		if r.drumT > 0.08 then
			r.drumMode = "flick"
			r.drumT = 0
			if r.drumN % 3 ~= 0 then
				r.drumDir = -r.drumDir
			end
			r.drumPeak = 20 + (r.drumN % 4) * 5
			kick(r.drumDir * 4.5)
		end
	end
	return r
end

Mark.chamberAt = function(p, gy, hot, withStitch, style)
	local reel = Mark.stepReel()
	local origin = Vector3.new(p.X + reel.fastRoll * 0.22, gy, p.Z)
	local ang0 = style == "glow" and reel.drumAng or reel.fastAng
	local scale = hot and 1 or 0.9
	local pool = nil
	if style == "glow" or style == "route" then
		local key = style == "glow" and "aimGlow" or "aimLip"
		pool = Mark[key]
		if not pool then
			pool = {}
			for i = 1, 36 do
				local ln = newDraw("Line", 42)
				ln.Visible = false
				pool[i] = ln
			end
			Mark[key] = pool
		end
		for i = 1, #pool do
			pool[i].Visible = false
		end
	end
	local n = 1
	local function strokeEdge(a, b)
		if not pool or not pool[n] then
			return
		end
		if style == "glow" then
			pool[n].Thickness = 8
			applyLine(pool[n], a, b, COL.Tackle, 0.2)
			n = n + 1
			if not pool[n] then
				return
			end
			pool[n].Thickness = 3.6
			applyLine(pool[n], a, b, COL.Tackle, 0.45)
			n = n + 1
			if not pool[n] then
				return
			end
			pool[n].Thickness = 1.3
			applyLine(pool[n], a, b, COL.Paper, 1)
			n = n + 1
		else
			pool[n].Thickness = 3.2
			applyLine(pool[n], a, b, COL.Ink, 1)
			n = n + 1
			if not pool[n] then
				return
			end
			pool[n].Thickness = 1.45
			applyLine(pool[n], a, b, Mark.routeInk or COL.Line, 1)
			n = n + 1
		end
	end
	local tris = style == "route" and Mark.routeSight or Mark.sight
	for i = 1, 4 do
		local ang = ang0 + (i - 1) * math.pi * 0.5
		local warp = 1 + reel.fastRoll * math.cos(ang) * 0.05
		local outward = Vector3.new(math.cos(ang), 0, math.sin(ang))
		local right = Vector3.new(-outward.Z, 0, outward.X)
		local apexDist = 0.5 * scale * warp
		local len = 1.52 * scale
		local halfW = 0.21 * scale
		local apex = origin + outward * apexDist
		local base = apex + outward * len
		tris[i].Filled = true
		Mark.fillTri(tris[i], apex, base + right * halfW, base - right * halfW, COL.Paper)
		if style then
			strokeEdge(apex, base + right * halfW)
			strokeEdge(base + right * halfW, base - right * halfW)
			strokeEdge(base - right * halfW, apex)
		end
		if withStitch and style ~= "route" then
			local o = 1.12
			local apexO = origin + outward * (apexDist * 0.9)
			local baseO = apexO + outward * len * o
			local halfO = halfW * o
			local a = baseO + right * halfO
			local b = baseO - right * halfO
			local li = (i - 1) * 3
			Mark.stitchUs[li + 1].Thickness = 1.7
			Mark.stitchUs[li + 2].Thickness = 1.7
			Mark.stitchUs[li + 3].Thickness = 1.7
			applyLine(Mark.stitchUs[li + 1], apexO, a, COL.Line, 1)
			applyLine(Mark.stitchUs[li + 2], a, b, COL.Line, 1)
			applyLine(Mark.stitchUs[li + 3], b, apexO, COL.Line, 1)
		end
	end
end

Mark.sightAt = function(p, gy, col, hot, aim)
	if CFG.SightStyle == "reticle" and Mark.sightArt then
		Mark.sightArt(Mark.pen, p, gy, hot, aim, os.clock())
		return
	end
	Mark.chamberAt(p, gy, hot, true, nil)
end

-- The tackle solve drops predict.hit for a frame and the mark blinked off. Keep the last hit ~0.35 s.
Mark.sightKeep = function(gy)
	local hold = Mark.sightHold
	if hold and os.clock() - hold.at < 0.35 then
		Mark.sightAt(hold.p, gy, COL.Paper, true, hold.aim)
		Mark.sightP = hold.p
	else
		Mark.hideSight()
	end
end

Mark.hideGate = function(tris)
	if not tris then
		return
	end
	for i = 1, #tris do
		tris[i].Visible = false
	end
end

Mark.bodyFill = function(p, dir, gy, col, scale)
	local right = xzRight(dir)
	local c = Vector3.new(p.X, gy, p.Z)
	local front = 0.7 * scale
	local back = 0.38 * scale
	local wide = 0.2 * scale
	local narrow = 0.12 * scale
	applyQuad(Mark.usQuad, c + dir * front + right * wide, c + dir * front - right * wide, c - dir * back - right * narrow, c - dir * back + right * narrow, col, 1)
end

Mark.bodyLine = function(p, dir, gy, col, scale)
	local right = xzRight(dir)
	local c = Vector3.new(p.X, gy, p.Z)
	local front = 0.78 * scale
	local back = 0.42 * scale
	local wide = 0.24 * scale
	local narrow = 0.14 * scale
	local loop = {
		c + dir * front + right * wide,
		c + dir * front - right * wide,
		c - dir * back - right * narrow,
		c - dir * back + right * narrow,
	}
	for i = 1, 4 do
		Mark.ghostEdge[i].Thickness = 1.5
		applyLine(Mark.ghostEdge[i], loop[i], loop[i % 4 + 1], col, 1)
	end
end

Mark.diamond = function(tris, p, gy, col, r)
	local c = Vector3.new(p.X, gy, p.Z)
	local n = c + Vector3.new(0, 0, r)
	local e = c + Vector3.new(r * 0.7, 0, 0)
	local s = c + Vector3.new(0, 0, -r)
	local w = c + Vector3.new(-r * 0.7, 0, 0)
	tris[1].Filled = true
	tris[2].Filled = true
	tris[1].Thickness = 1
	tris[2].Thickness = 1
	Mark.fillTri(tris[1], n, e, s, col)
	Mark.fillTri(tris[2], n, w, s, col)
	tris[3].Visible = false
	tris[4].Visible = false
end

local function flat(v)
	return Vector3.new(v.X, 0, v.Z)
end

Mark.approach = function(quads, head, from, to, gy, col)
	for i = 1, #quads do
		quads[i].Visible = false
	end
	if head then
		head.Visible = false
	end
	if not (from and to) then
		return
	end
	local delta = flat(to - from)
	local dist = delta.Magnitude
	if dist < 0.4 then
		return
	end
	local dir = delta.Unit
	local cap = 6.5
	local vis = math.min(dist, cap)
	local a = Vector3.new(from.X, gy, from.Z)
	local tip = a + dir * vis
	local right = xzRight(dir)
	local tailW = 0.22 * (0.45 + 0.55 * vis / cap)
	local noseW = 0.08
	applyQuad(quads[1], a + right * tailW, a - right * tailW, tip - right * noseW, tip + right * noseW, col, 1)
	local u = (os.clock() * 0.8) % 1
	u = u * u * (3 - 2 * u)
	local notch = a:Lerp(tip, 0.12 + 0.72 * u)
	local nw = 0.1 + 0.06 * (1 - u)
	applyQuad(quads[2], notch - dir * 0.28 + right * nw, notch - dir * 0.28 - right * nw, notch + dir * 0.12 - right * nw * 0.35, notch + dir * 0.12 + right * nw * 0.35, COL.Paper, 1)
	if head then
		local back = tip - dir * 0.7
		head.Filled = true
		Mark.fillTri(head, tip + dir * 0.28, back + right * 0.36, back - right * 0.36, col)
	end
end


Mark.frontSeg = function(a, b)
	local _, _, za = worldTo(a)
	local _, _, zb = worldTo(b)
	if za and za > 0.2 and zb and zb > 0.2 then
		return a, b
	end
	if zb and zb > 0.2 then
		return a:Lerp(b, 0.62), b
	end
	if za and za > 0.2 then
		return a, a:Lerp(b, 0.38)
	end
	return a, b
end

Mark.drawFlight = function(pts, col)
	hideLines(Mark.flight)
	Mark.flightTip.Visible = false
	Mark.flightTail.Visible = false
	if not pts or #pts < 2 then
		return
	end
	local vis = pts
	if #vis < 2 then
		vis = pts
	end
	local function point(tri, tail, nose, half)
		local dir = nose - tail
		if dir.Magnitude < 0.08 then
			tri.Visible = false
			return
		end
		dir = dir.Unit
		local right = Vector3.new(-dir.Z, 0, dir.X)
		if right.Magnitude < 0.05 then
			right = Vector3.new(1, 0, 0)
		else
			right = right.Unit
		end
		local base = nose - dir * 0.85
		Mark.fillTri(tri, nose, base + right * half, base - right * half, col)
	end
	local last = #vis
	point(Mark.flightTail, vis[2], vis[1], 0.1)
	point(Mark.flightTip, vis[last - 1], vis[last], 0.16)
	local segs = #Mark.flight
	for i = 1, segs do
		local a = math.floor(1 + (i - 1) * (last - 1) / segs)
		local b = math.floor(1 + i * (last - 1) / segs)
		if b <= a then
			b = math.min(last, a + 1)
		end
		if b > last then
			b = last
		end
		if b > a then
			local pa, pb = Mark.frontSeg(vis[a], vis[b])
			local u = i / segs
			local taper = math.min(u, 1 - u) * 2
			taper = 0.15 + 0.85 * taper
			Mark.flight[i].Thickness = 0.8 + 1.6 * taper
			applyLine(Mark.flight[i], pa, pb, col, 0.55 + 0.45 * taper)
		end
	end
end

Mark.drawShadow = function(pts, gy, col)
	hideLines(Mark.shadow)
	if not pts or #pts < 2 then
		return
	end
	local n = #Mark.shadow
	local last = #pts
	for i = 1, n do
		local a = math.floor(1 + (i - 1) * (last - 1) / n)
		local b = math.floor(1 + i * (last - 1) / n)
		if b <= a then
			b = math.min(last, a + 1)
		end
		if b > a then
			local pa = Vector3.new(pts[a].X, gy + 0.08, pts[a].Z)
			local pb = Vector3.new(pts[b].X, gy + 0.08, pts[b].Z)
			Mark.shadow[i].Thickness = 1.1
			applyLine(Mark.shadow[i], pa, pb, col, 0.28)
		end
	end
end

Mark.drawScar = function(hit, face, along, gy, col)
	hideLines(Mark.box)
	if typeof(hit) ~= "Vector3" then
		return
	end
	local n = (face and face.Magnitude > 0.5) and face.Unit or Vector3.new(0, 0, 1)
	local side = (along and along.Magnitude > 0.5) and along.Unit or Vector3.new(1, 0, 0)
	local pulse = 1
	local w = 0.62
	local tip = hit - n * (0.28 + 0.22 * pulse)
	Mark.box[1].Thickness = 1.8
	Mark.box[2].Thickness = 1.4
	Mark.box[3].Thickness = 1.4
	applyLine(Mark.box[1], hit - side * w, hit + side * w, col, 1)
	applyLine(Mark.box[2], hit - side * w * 0.72, tip, col, 0.9)
	applyLine(Mark.box[3], hit + side * w * 0.72, tip, col, 0.9)
	local foot = Vector3.new(hit.X, gy + 0.08, hit.Z)
	Mark.box[4].Thickness = 1.1
	applyLine(Mark.box[4], hit, foot, COL.Chalk, 0.4)
	local cross = 0.28 + 0.12 * pulse
	Mark.box[5].Thickness = 1.3
	Mark.box[6].Thickness = 1.3
	applyLine(Mark.box[5], foot - side * cross, foot + side * cross, COL.Paper, 0.85)
	applyLine(Mark.box[6], foot - n * cross, foot + n * cross, COL.Paper, 0.85)
end

Mark.ballSeam = function(p, col)
	Mark.hex(Mark.ballHex, p, p.Y, 0.4, col, 1.6)
end

local function unitOrNil(v)
	local m = v.Magnitude
	if m < 0.08 then
		return nil
	end
	return v / m
end

local flickOwner = nil
local flickUntil = 0

local function ownerIdOk(id)
	return type(id) == "number" and id ~= 0
end

local function liveOwnerId()
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if root and Renderer.GetNearestPracticeBallId then
		local id = Renderer.GetNearestPracticeBallId(root.Position)
		if id then
			local rend = Renderer.GetOrCreateRenderer(id)
			local owner = rend and rend.GetOwnedUserId and rend.GetOwnedUserId()
			if ownerIdOk(owner) then
				local pos = rend.GetPosition and rend.GetPosition()
				local near = typeof(pos) == "Vector3" and flat(pos - root.Position).Magnitude < 48
				if near or owner == LocalPlayer.UserId then
					if owner == LocalPlayer.UserId then
						if Renderer.SetMatchBallId and Renderer.GetMatchBallId and Renderer.GetMatchBallId() ~= id then
							Renderer.SetMatchBallId(id)
						end
					end
					return owner
				end
			end
		end
	end
	local bound = Renderer.GetOwnedUserId()
	if ownerIdOk(bound) then
		return bound
	end
	local a = Renderer.GetMainMatchOwnerUserId()
	if ownerIdOk(a) then
		return a
	end
	if flickOwner and os.clock() < flickUntil then
		return flickOwner
	end
	return nil
end

local function playerOf(userId)
	if type(userId) ~= "number" then
		return nil
	end
	return Actors.GetByUserId(userId)
end

local function actorName(actor)
	if not actor then
		return "-"
	end
	if typeof(actor) == "Instance" and actor:IsA("Player") then
		return actor.Name
	end
	return actor.DisplayName or actor.Name or tostring(Actors.GetUserId(actor))
end

local function isGoalkeeperRaw(actor)
	local character = Actors.GetCharacter(actor)
	return character ~= nil and MatchSettings.IsGoalkeeperCharacter(character)
end
-- role / team lookups ran per actor per caller per frame (tickBall alone walks the roster 3 times; sameTeam also
-- resolved OUR team every call). Both change on respawn / team swap only: 0.3 s cache per actor.
local roleCache = setmetatable({}, { __mode = "k" })
local function isGoalkeeper(actor)
	local now = os.clock()
	local c = roleCache[actor]
	if c and now - c[1] < 0.3 then
		return c[2]
	end
	local v = isGoalkeeperRaw(actor)
	if c then
		c[1], c[2] = now, v
	else
		roleCache[actor] = { now, v }
	end
	return v
end

local teamKey
local sameCache = setmetatable({}, { __mode = "k" })
local sameTeamRaw
local function sameTeam(actor)
	if actor == LocalPlayer then
		return true
	end
	local now = os.clock()
	local c = sameCache[actor]
	if c and now - c[1] < 0.3 then
		return c[2]
	end
	local v = sameTeamRaw(actor)
	if c then
		c[1], c[2] = now, v
	else
		sameCache[actor] = { now, v }
	end
	return v
end
sameTeamRaw = function(actor)
	local a = teamKey(ActorTeams.GetActorTeamName(LocalPlayer))
	local b = teamKey(ActorTeams.GetActorTeamName(actor))
	if not a or not b then
		return true
	end
	return a == b
end

teamKey = function(name)
	if name == "Team1" or name == "Team2" then
		return name
	end
	local display = MatchSettings.Constants.TeamDisplayNames
	if display then
		for k, v in display do
			if v == name then
				return k
			end
		end
	end
	return name
end

local function enemyGoalPart()
	local c = Mark.goalCacheE
	if c and os.clock() - c.at < 0.5 and c.g and c.g.Parent then
		return c.g
	end
	local ours = teamKey(ActorTeams.GetActorTeamName(LocalPlayer))
	local map = Workspace:FindFirstChild("Map")
	local data = map and map:FindFirstChild("Data")
	if ours == "Team1" or ours == "Team2" then
		local opp = MatchSettings.GetOpposingTeamName(ours)
		local folder = data and data:FindFirstChild(opp)
		local g = folder and folder:FindFirstChild("Goal")
		if g and g:IsA("BasePart") then
			Mark.goalCacheE = { at = os.clock(), g = g }
			return g
		end
	end
	local lobby = Workspace:FindFirstChild("Lobby")
	local practice = lobby and lobby:FindFirstChild("Practice")
	local goals = practice and practice:FindFirstChild("Goals")
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local pos = root and root.Position
	if goals and pos then
		local best, bestD = nil, 1e9
		for _, child in goals:GetChildren() do
			local g = child:IsA("Model") and child:FindFirstChild("Goal")
			if g and g:IsA("BasePart") then
				local d = (g.Position - pos).Magnitude
				if d < bestD then
					best, bestD = g, d
				end
			end
		end
		if best then
			return best
		end
	end
	if not data then
		return nil
	end
	local best, bestD = nil, -1
	for _, folder in data:GetChildren() do
		if folder.Name ~= ours then
			local g = folder:FindFirstChild("Goal")
			if g and g:IsA("BasePart") then
				local d = pos and (g.Position - pos).Magnitude or 0
				if d > bestD then
					best, bestD = g, d
				end
			end
		end
	end
	return best
end

local function ourGoalPart()
	local c = Mark.goalCacheO
	if c and os.clock() - c.at < 0.5 and c.g.Parent then
		return c.g
	end
	local ours = teamKey(ActorTeams.GetActorTeamName(LocalPlayer))
	local map = Workspace:FindFirstChild("Map")
	local data = map and map:FindFirstChild("Data")
	if data and (ours == "Team1" or ours == "Team2") then
		local folder = data:FindFirstChild(ours)
		local g = folder and folder:FindFirstChild("Goal")
		if g and g:IsA("BasePart") then
			Mark.goalCacheO = { at = os.clock(), g = g }
			return g
		end
	end
	local function green(part)
		local c = part.Color
		return c.G > 0.45 and c.G > c.R + 0.08 and c.G > c.B
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local pos = root and root.Position
	local best, bestD = nil, 1e9
	local function consider(g)
		if g and g:IsA("BasePart") and green(g) and pos then
			local d = (g.Position - pos).Magnitude
			if d < bestD then
				best, bestD = g, d
			end
		end
	end
	if data then
		for _, folder in data:GetChildren() do
			consider(folder:FindFirstChild("Goal"))
		end
	end
	local lobby = Workspace:FindFirstChild("Lobby")
	local practice = lobby and lobby:FindFirstChild("Practice")
	local goals = practice and practice:FindFirstChild("Goals")
	if goals then
		for _, child in goals:GetChildren() do
			consider(child:FindFirstChild("Goal"))
		end
	end
	return best
end


local function goalMouthCorners(part)
	local cf = part.CFrame
	local s = part.Size
	local hx, hy, hz = s.X * 0.5, s.Y * 0.5, s.Z * 0.5
	local mid = FieldMarkers.GetCenterPosition()
	if part:FindFirstAncestor("Practice") then
		local root = ActorTargeting.GetActorRoot(LocalPlayer)
		mid = root and root.Position or mid
	end
	local toField = mid and flat(mid - part.Position) or flat(cf.LookVector)
	if toField.Magnitude < 1 then
		toField = flat(cf.LookVector)
	else
		toField = toField.Unit
	end
	local depthZ = hz <= hx
	local faces = depthZ and {
		{ n = cf.LookVector, u = cf.UpVector, v = cf.RightVector, e = hz, w = hx },
		{ n = -cf.LookVector, u = cf.UpVector, v = cf.RightVector, e = hz, w = hx },
	} or {
		{ n = cf.RightVector, u = cf.UpVector, v = cf.LookVector, e = hx, w = hz },
		{ n = -cf.RightVector, u = cf.UpVector, v = cf.LookVector, e = hx, w = hz },
	}
	local best, bestDot = faces[1], -1e9
	for i = 1, #faces do
		local d = faces[i].n:Dot(toField)
		if d > bestDot then
			bestDot = d
			best = faces[i]
		end
	end
	local origin = part.Position + best.n * best.e
	local u, v = best.u, best.v
	local lt = origin + u * hy - v * best.w
	local rt = origin + u * hy + v * best.w
	local lb = origin - u * hy - v * best.w
	local rb = origin - u * hy + v * best.w
	local along = unitOrNil(flat(rt - lt)) or v
	return lb, lt, rb, rt, along, best.n
end

local function enemyCarrier(oid)
	if type(oid) ~= "number" then
		return nil, "no owner"
	end
	if oid == LocalPlayer.UserId then
		return nil, "have ball"
	end
	local actor = playerOf(oid)
	if not actor then
		return nil, "no actor"
	end
	if sameTeam(actor) then
		return nil, "ally"
	end
	if isGoalkeeper(actor) then
		return nil, "gk"
	end
	local root = ActorTargeting.GetActorRoot(actor)
	if not root then
		return nil, "no root"
	end
	return actor, root
end

-- ENEMY DRIBBLE CLOCK (every enemy, every frame - not only the carrier the tackle solver looked at). The game sets the
-- replicated "Dribbling" attribute (Dodge.DribblingAttributeName) for ActiveSeconds 1 at the server start of a dribble;
-- the next one is allowed RepeatDelaySeconds 4 - ServerCooldownGrace 0.15 later (dodgeEnforced). The attribute reaches us
-- ~ping/2 after the server start, so the start is put ping/2 back. A dribble needs the ball (Dodge client:
-- SetAvailabilityBlocked("Dribble", "NotOwner")). Never seen = ready.
Mark.dribWatch = function()
	local now = os.clock()
	if now - (Mark.dribWatchAt or 0) < 0.02 then
		return
	end
	Mark.dribWatchAt = now
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) then
			local key = actor.UserId
			local rec = dribbleSeen[key]
			if Dodge.IsDribbling(model) then
				if not (rec and now < rec.cdUntil) then
					local start = now - ping * 0.5
					rec = { start = start, untilT = start + Dodge.Constants.ActiveSeconds, cdUntil = start + dodgeEnforced, on = true }
					dribbleSeen[key] = rec
					dribbleSeen[model] = rec
					logFile("foe dribble", actorName(actor), "next in", string.format("%.2f", rec.cdUntil - now))
				end
			elseif rec then
				if rec.on then
					rec.on = false
					rec.untilT = math.min(rec.untilT, now)
				end
				if now > rec.cdUntil + 0.5 then
					dribbleSeen[key] = nil
					dribbleSeen[model] = nil
				end
			end
		end
	end
end

-- What his dribble does to a slide box live at hitAt (os.clock): "iframe" (inside his dribble), "spent" (used, cooldown
-- still running at hitAt + 0.15), "noball" (he will not own the ball while the box is live: no dribble without it),
-- "ready" (he owns it and can dribble).
Mark.foeCharging = function(uid)
	local rec = Mark.charges and Mark.charges[uid]
	return rec ~= nil and rec.live and os.clock() - (rec.seen or 0) < 0.6
end

-- A state where a dribble is impossible or hard at hitAt (os.clock) though he is not "spent" (Perfect Mode):
--   "slide"  his own slide tackle is on (SlideTackle.GetSlidingUntil beyond the hit; Dodge is locked by the SlideTackle lock),
--   "locked" an action lock / stun on him that blocks Dodge right now (ActionLocks.HasDodgeBlock: jetpack, go-kart, item ball
--            controls, tackle-kick). Not air: a body in the air is outside the slide box height anyway.
Mark.dribBlocked = function(actor, model, hitAt)
	local untilT = SlideTackle.GetSlidingUntil(model)
	if untilT and untilT > Workspace:GetServerTimeNow() + (hitAt - os.clock()) + 0.02 then
		return "slide"
	end
	if ActionLocks.HasDodgeBlock(actor) then
		return "locked"
	end
	return nil
end

Mark.dribState = function(actor, model, hitAt, hasBall)
	-- stunned / ragdolled / frozen: no dribble and no movement - the most predictable state there is
	if model and Mark.mateDown(actor, model) then
		return "down", nil
	end
	local rec = dribbleSeen[actor.UserId] or (model and dribbleSeen[model])
	if rec and hitAt < rec.untilT + 0.03 then
		return "iframe", rec
	end
	if rec and hitAt + 0.15 < rec.cdUntil then
		return "spent", rec
	end
	if not hasBall then
		return "noball", rec
	end
	local blocked = model and Mark.dribBlocked(actor, model, hitAt)
	if blocked then
		return blocked, rec
	end
	return "ready", rec
end

local function tackleTuning()
	local speed = math.max(0.4, CFG.TackleSpeed)
	return {
		speed = speed,
		reach = CFG.TackleReach,
		dashDist = C.StartupDashDistance,
		dashDur = 0.5 / speed,
		handoff = C.StartupDashHandoffSeconds / speed,
		mainDist = C.Distance,
		mainDur = C.MotionSeconds / speed,
		totalT = C.TotalMotionSeconds / speed,
		landing = C.AssistLandingStuds,
	}
end

local Wire = {
	MAX = 60,
	t = table.create(60),
	p = table.create(60),
	n = 0,
	head = 1,
}

MovementStreamTap.Subscribe(function(ch, stamp, cf)
	if ch ~= LocalPlayer.Character then
		return
	end
	if type(stamp) ~= "number" or typeof(cf) ~= "CFrame" then
		return
	end
	if Wire.n < Wire.MAX then
		Wire.n = Wire.n + 1
		Wire.t[Wire.n] = stamp
		Wire.p[Wire.n] = cf.Position
		return
	end
	Wire.t[Wire.head] = stamp
	Wire.p[Wire.head] = cf.Position
	Wire.head = Wire.head % Wire.MAX + 1
end)

local function wireIndex(i)
	if Wire.n < Wire.MAX then
		return i
	end
	return (Wire.head + i - 2) % Wire.MAX + 1
end

local function wireAt(stamp)
	if Wire.n == 0 then
		return nil
	end
	local i0 = wireIndex(1)
	local i1 = wireIndex(Wire.n)
	if stamp <= Wire.t[i0] then
		return Wire.p[i0]
	end
	if stamp >= Wire.t[i1] then
		return Wire.p[i1]
	end
	for i = 1, Wire.n - 1 do
		local a = wireIndex(i)
		local b = wireIndex(i + 1)
		if stamp <= Wire.t[b] then
			local span = Wire.t[b] - Wire.t[a]
			local u = span <= 1e-4 and 1 or (stamp - Wire.t[a]) / span
			return Wire.p[a]:Lerp(Wire.p[b], u)
		end
	end
	return Wire.p[i1]
end

local function ourRewindPosition(root, enemyActor, mode)
	if mode == "live" then
		return root.Position, 0
	end
	local otherOw = 0
	if typeof(enemyActor) == "Instance" and enemyActor:IsA("Player") then
		otherOw = CommandTime.GetPlayerOneWaySeconds(enemyActor)
	end
	local rewind = CommandTime.GetPlayerVictimRewindSeconds(LocalPlayer, otherOw)
	local stamp = CharacterMotionSmoothing.GetSmoothedServerTime() - rewind
	local p = wireAt(stamp)
	if p then
		return p, rewind
	end
	local ch = LocalPlayer.Character
	local vel = flat((ch and CharacterMotion.GetVelocity(ch)) or Vector3.new())
	return root.Position - CommandTime.ClampExtrapolationOffset(vel * rewind), rewind
end

-- Slide origin is dash travel, not vel*delay. Packet: GetPosition + heading * dumpTravel(displayDelay).
Mark.enemySlideOrigin = function(root, ch, heading, elapsed)
	elapsed = elapsed or 0
	local live = root.Position
	if ch then
		live = CharacterMotion.GetPosition(ch) or live
	end
	local delay = 0
	if ch then
		delay = math.clamp(CharacterMotion.GetDisplayDelaySeconds(ch) or 0, 0, 0.25)
	end
	if not heading then
		return live, delay, live
	end
	local pose = live + heading * Mark.dumpTravel(delay)
	return pose - heading * Mark.dumpTravel(elapsed), delay, live
end

local function headingOf(character, root)
	local vel = unitOrNil(flat((character and CharacterMotion.GetVelocity(character)) or Vector3.new()))
	if vel then
		return vel
	end
	return unitOrNil(flat(root.CFrame.LookVector))
end


-- Dump HitboxSettings.SlideTackle: box CFrameOffset Z -3, Size Z 5 -> covers 0.5..5.5 studs ahead of our root.
-- Box is live from HitboxDelaySeconds for HitboxSeconds. Travel at multiplier m is m * dumpTravel(t):
-- GetStartupDashDistance and GetDistance both scale by SetSpeedMultiplier, durations do not.
Mark.slideBox = function()
	local box = HitboxSettings.SlideTackle
	local mid = -box.CFrameOffset.Z
	local half = box.Size.Z * 0.5
	return mid, mid - half, mid + half
end

-- Carrier pose = CharacterMotion.GetPosition/GetVelocity (what SlideTackleInput.getAssistedTackleTargetPosition reads).
Mark.carrierPose = function(carrierRoot, carrierChar)
	local livePos = carrierRoot.Position
	local pos = (carrierChar and CharacterMotion.GetPosition(carrierChar)) or livePos
	local worldVel = carrierChar and (CharacterMotion.GetVelocity(carrierChar) or Vector3.zero) or Vector3.zero
	local rawVel = flat(worldVel)
	if carrierChar then
		Mark.motion = Mark.motion or setmetatable({}, { __mode = "k" })
		local now = os.clock()
		local rec = Mark.motion[carrierChar]
		if not rec or now - (rec.t or 0) > 0.22 then
			Mark.motion[carrierChar] = { t = now, p = livePos, v = rawVel }
		else
			local dt = now - rec.t
			if dt >= 0.025 and rec.p then
				local step = flat(livePos - rec.p) / dt
				local motion = flat(worldVel)
				local spike = step.Magnitude > 32 or (motion.Magnitude > 2 and step.Magnitude > motion.Magnitude * 1.7 + 6)
				if spike then
					rawVel = motion.Magnitude > 0.4 and motion or (rec.v and rec.v.Magnitude <= 32 and rec.v or rawVel)
				elseif step.Magnitude > 0.8 then
					rawVel = step
				end
				rec.t = now
				rec.p = livePos
				rec.v = rawVel
			elseif rec.v and rec.v.Magnitude > 0.4 then
				rawVel = rec.v
			end
		end
		if Dodge.IsDribbling(carrierChar) then
			local u = unitOrNil(rawVel)
			rawVel = u and u * math.min(rawVel.Magnitude, Dodge.Constants.WalkSpeed) or rawVel
		elseif Mark.charges then
			-- A carrier whose KickChargeStarted/Updated is live walks at ActionMovement.GetChargingWalkSpeed (0.5 x jog)
			-- and cannot sprint: the displayed velocity is a few frames stale (display delay + ping) and still shows the
			-- run-up, which is what made the block spot and the slide lead overshoot a charging carrier.
			local pl = Players:GetPlayerFromCharacter(carrierChar)
			local rec = pl and Mark.charges[pl.UserId]
			if rec and rec.live and os.clock() - (rec.seen or 0) < 0.6 then
				Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
				local cw = Mark.mover.GetChargingWalkSpeed(Mark.mover.GetBaseWalkSpeed(carrierChar), true)
				local u = unitOrNil(rawVel)
				if type(cw) == "number" and u and rawVel.Magnitude > cw then
					rawVel = u * cw
				end
			end
		end
	end
	return pos, rawVel, worldVel, livePos
end

-- his highest flat speed over the last 3 s (the boosted run speed once he has been running): per-model ring of maxima
Mark.foeTopRec = setmetatable({}, { __mode = "k" })
Mark.foeTop = function(model, spd)
	local now = os.clock()
	local r = Mark.foeTopRec[model]
	if not r or now - r.at > 3 then
		r = { at = now, top = spd }
		Mark.foeTopRec[model] = r
	end
	if spd > r.top then
		r.top = spd
	end
	return r.top
end

-- displacement after t s of a man at velocity v (speed spd) whose speed eases up to vTop over `ramp` s, then holds
Mark.boostLead = function(v, spd, vTop, ramp, t)
	if ramp <= 0 or vTop <= spd then
		return v * t
	end
	local e = math.min(t, ramp)
	-- extra distance beyond the walker's: integral of (vTop - spd) * min(s / ramp, 1) ds
	local d = (vTop - spd) * ((e * e) / (2 * ramp) + math.max(t - ramp, 0))
	return v * t + (unitOrNil(flat(v)) or Vector3.zero) * d
end

local function solveIntercept(ourRoot, carrierRoot, carrierChar, tune)
	local origin = ourRoot.Position
	local enemyPos, rawVel, worldVel, livePos = Mark.carrierPose(carrierRoot, carrierChar)
	local delay = 0
	if carrierChar then
		delay = math.clamp(CharacterMotion.GetDisplayDelaySeconds(carrierChar) or 0, 0, 0.25)
	end
	local nowDist = flat(enemyPos - origin).Magnitude
	local liveDist = flat(livePos - origin).Magnitude
	if nowDist > CFG.TrackStuds and liveDist > CFG.TrackStuds then
		return nil
	end
	local spd = rawVel.Magnitude
	local t0 = C.HitboxDelaySeconds
	local t1 = C.HitboxDelaySeconds + C.HitboxSeconds
	local wait = nil
	local iframe = 0
	if carrierChar and Dodge.IsDribbling(carrierChar) then
		-- Server time, not what we see: the Dribbling attribute reached us ping/2 after the server set it (untilT is that
		-- late) and our press reaches the server ping/2 after we send it, so the iframe left at the server when our slide
		-- starts is untilT - now - ping. The old value waited out the whole client-side dribble.
		local rec = dribbleSeen[carrierChar]
		local pingI = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		iframe = (rec and rec.untilT) and math.max(0, rec.untilT - os.clock() - pingI) or Dodge.Constants.ActiveSeconds
		if iframe >= t1 - 0.02 then
			wait = "iframe"
		end
	end
	local tAir = 0
	local hum = carrierChar and carrierChar:FindFirstChildOfClass("Humanoid")
	if not wait and hum and not CharacterControllers.IsLanded(carrierChar, hum) then
		tAir = Mark.fallT(enemyPos.Y, worldVel.Y, origin.Y)
		if tAir > t1 then
			wait = "air"
		end
	end
	if not wait and hum and CFG.CounterJump and not CharacterControllers.IsLanded(carrierChar, hum) and nowDist <= (CFG.CounterJumpRange or 10) + 4 then
		wait = "counter" -- he left the ground with the ball: Mark.tickCounterJump jumps, a slide under a flying kick is wasted
	end
	-- Ball ABOVE a grounded carrier (above his Receive box top + ball radius): he jumps for it, a slide under a jump is
	-- wasted - the ball is the target (AutoBlock intercept / AutoBall / CounterJump), not him.
	if not wait then
		local ballP = Renderer.GetPosition()
		if typeof(ballP) == "Vector3" then
			local rcvH = HitboxSettings.Receive.CFrameOffset.Y + HitboxSettings.Receive.Size.Y * 0.5 + (Physics.BallRadius or 1)
			if ballP.Y - enemyPos.Y > rcvH + 0.6 and flat(ballP - enemyPos).Magnitude <= 10 and not Mark.isLobber(carrierChar) then
				wait = "ball high"
			end
		end
	end
	-- (no "flick" wait any more: a slide on the flicker before the detach steals the ball, one after it stuns him and his
	-- own lob - RainbowFlick self-delivery - comes down loose. Waiting was the "reacts only when he jumps for it" bug.)
	local mid, near, far = Mark.slideBox()
	local mHi = math.max(0.4, CFG.TackleSpeed)
	local mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6)
	local bestT, bestPred, bestMult = nil, nil, nil
	local edgeT, edgePred, edgeMult = nil, nil, nil
	local mMin, mMax = math.huge, -math.huge
	-- A SUCCESSFUL dribble gives him a speed boost (Dodge.Constants.SuccessfulDodgeSpeedMultiplier x1.3 for 1.5 s, the
	-- replicated SprintDodgeBoostUntil attribute) that ramps in over SpeedBoostRecoverySeconds 0.25: the velocity we
	-- measure is still the slow one while he is already accelerating - the slide was aimed at where a walker would be
	-- and fell short of a runner (user: kick -> his dribble -> he runs -> our tackle misses). Predict the ramp, and
	-- hold ~TackleBoostWait s while the measured speed is still catching up so the aim is taken from the real velocity.
	local ramp, vTop = 0, spd
	if carrierChar then
		Mark.sprintMod = Mark.sprintMod or require(Modules.Actions.Sprint)
		local bu = Mark.sprintMod.GetDodgeBoostUntil(carrierChar)
		local nowS = Workspace:GetServerTimeNow()
		if type(bu) == "number" and bu > nowS and spd > 1 then
			local age = Dodge.Constants.SuccessfulDodgeSpeedBoostSeconds - (bu - nowS)
			local top = Mark.foeTop(carrierChar, spd)
			vTop = math.max(spd, top)
			ramp = math.clamp(0.25 - math.max(age, 0), 0, 0.25)
			if ramp > 0 and spd < vTop * 0.93 and not wait and nowDist <= (CFG.TackleBoostNear or 16) then
				wait = "boost"
			end
		end
	end
	local function lead(t)
		return Mark.boostLead(rawVel, spd, vTop, ramp, t)
	end
	if not wait then
		local t = math.max(t0, iframe, tAir)
		while t <= t1 + 1e-4 do
			local pred = enemyPos + lead(t)
			local d = flat(pred - origin).Magnitude
			local T = Mark.dumpTravel(t)
			local mC = (d - mid) / T
			mMin = math.min(mMin, mC)
			mMax = math.max(mMax, mC)
			if mC >= mLo and mC <= mHi then
				bestT, bestPred, bestMult = t, pred, mC
				break
			end
			if not edgeT then
				local lo = math.max((d - far + 1) / T, mLo)
				local hi = math.min((d - near - 1) / T, mHi)
				if lo <= hi then
					edgeT, edgePred = t, pred
					edgeMult = (mC < mLo) and lo or hi
				end
			end
			t += 0.02
		end
		if not bestT and edgeT then
			bestT, bestPred, bestMult = edgeT, edgePred, edgeMult
		end
		if not bestT then
			if mMax < mLo then
				wait = "close"
			elseif nowDist > mHi * Mark.dumpTravel(t1) + far + 8 then
				wait = "track"
			else
				wait = "outrun"
			end
		end
	end
	local aim = bestPred and unitOrNil(flat(bestPred - origin))
	local ourPts, enemyPts = {}, {}
	if aim and bestT then
		for i = 0, 8 do
			local t = bestT * (i / 8)
			ourPts[i + 1] = origin + aim * (bestMult * Mark.dumpTravel(t))
			enemyPts[i + 1] = enemyPos + lead(t)
		end
	end
	local fire = aim ~= nil and bestT ~= nil and wait == nil
	local conf = 0
	if fire then
		local okN, allN, tt = 0, 0, t0
		local tMin = math.max(t0, iframe, tAir)
		while tt <= t1 + 1e-4 do
			allN += 1
			if tt >= tMin - 1e-4 then
				local mC = (flat(enemyPos + lead(tt) - origin).Magnitude - mid) / Mark.dumpTravel(tt)
				if mC >= mLo and mC <= mHi then
					okN += 1
				end
			end
			tt += 0.02
		end
		conf = math.max(okN / math.max(allN, 1), edgeT and 0.02 or 0)
	end
	return {
		hit = bestPred,
		eta = bestT,
		aim = aim,
		mult = bestMult,
		our = ourPts,
		enemy = enemyPts,
		dist = nowDist,
		catch = fire,
		short = nil,
		stable = true,
		behind = false,
		must = fire,
		cover = 0,
		marks = {},
		spd = spd,
		instSpd = flat(worldVel).Magnitude,
		meanSpd = spd,
		recentSpd = spd,
		accel = Vector3.zero,
		yaw = 0,
		livePos = livePos,
		serverPos = enemyPos,
		delay = delay,
		delta = flat(enemyPos - livePos).Magnitude,
		distLive = liveDist,
		samples = 0,
		track = wait == "track",
		conf = conf,
		fire = fire,
		wind = 0,
		wait = wait,
		iframe = iframe,
	}
end

local slideLock = setmetatable({}, { __mode = "k" })

local function slideElapsed(model)
	local untilT = SlideTackle.GetSlidingUntil(model)
	local now = Workspace:GetServerTimeNow()
	if not (untilT and now < untilT) then
		return nil
	end
	return math.max(0, C.TotalMotionSeconds - (untilT - now))
end

local function lockEnemySlide(model, root)
	local elapsed = slideElapsed(model)
	local lock = slideLock[model]
	if not elapsed then
		if lock and lock.hold and os.clock() < lock.hold then
			return lock, lock.elapsed or 0
		end
		slideLock[model] = nil
		return nil
	end
	if not lock then
		local heading = headingOf(model, root)
		if not heading then
			return nil
		end
		local origin = Mark.enemySlideOrigin(root, model, heading, elapsed)
		lock = {
			heading = heading,
			origin = origin,
			feet = root.Position,
			startPos = origin,
			fromPacket = false,
			t0 = os.clock() - elapsed,
		}
		slideLock[model] = lock
	else
		-- Re-anchor on his CURRENT motion: a PC tackler steers the whole slide (main dash reads GetDirection =
		-- MoveCommand every frame), the chord from the start point lags every bend. Direction = his displacement
		-- over the last ~0.08 s; origin = shifted so origin + heading * travel(elapsed) = his current server pose.
		-- Packet locks keep the AimDirection for the first 0.12 s (display still lags the packet there).
		local now = os.clock()
		local pose = CharacterMotion.GetPosition(model) or root.Position
		local hist = lock.hist or {}
		lock.hist = hist
		hist[#hist + 1] = { t = now, p = pose }
		while #hist > 2 and now - hist[2].t >= 0.08 do
			table.remove(hist, 1)
		end
		local old = hist[1]
		local moved = flat(pose - old.p)
		if now - old.t >= 0.03 and moved.Magnitude > 0.8 and (not lock.fromPacket or elapsed >= 0.12) then
			local heading = moved.Unit
			lock.heading = heading
			lock.origin = Mark.enemySlideOrigin(root, model, heading, elapsed)
		end
	end
	lock.elapsed = elapsed
	return lock, elapsed
end

local function slideFuture(lock, elapsed)
	local pts = {}
	local n = 12
	local t1 = C.TotalMotionSeconds
	local t0 = elapsed
	if t1 <= t0 then
		return pts
	end
	for i = 0, n do
		local t = t0 + (t1 - t0) * (i / n)
		pts[i + 1] = lock.origin + lock.heading * Mark.dumpTravel(t)
	end
	return pts
end

local function slidePathClosest(lock, elapsed, ourPos)
	if not (lock and lock.heading and lock.origin and ourPos) then
		return nil, 1e9
	end
	local t0 = math.max(elapsed or 0, C.HitboxDelaySeconds)
	local t1 = C.HitboxDelaySeconds + C.HitboxSeconds
	local a = lock.origin + lock.heading * Mark.dumpTravel(t0)
	local b = lock.origin + lock.heading * Mark.dumpTravel(t1)
	local ab = flat(b - a)
	local denom = ab:Dot(ab)
	local u = 0
	if denom > 1e-4 then
		u = math.clamp(flat(ourPos - a):Dot(ab) / denom, 0, 1)
	end
	local pt = a + ab * u
	return pt, flat(ourPos - pt).Magnitude
end

-- Real assisted-tackle steering (SlideTackleInput GetDirection, touch players with AssistedTackles): during the
-- startup dash (< HitboxDelaySeconds) the direction turns toward getAssistedTackleTargetPosition at
-- u4 = 1.5*pi / HitboxDelaySeconds rad/s (rotateFlatDirectionToward); the target is the BALL OWNER (SetOwnerUserId),
-- predicted as pos + vel * (i - now) at the first i in the hitbox window his landing reach covers (reach =
-- travel(i) - travel(now) + AssistLandingStuds), else the closest one if within 4. Homing stops once the target is
-- behind him inside AssistLandingStuds. After the hand-off the direction is frozen. Returns the hit time (seconds
-- from now) of his real box on target + targetVel*tau with `pad`, or nil.
Mark.assistPath = function(body, heading, elapsed, targetAt)
	local HD, HS = C.HitboxDelaySeconds, C.HitboxSeconds
	local landing = C.AssistLandingStuds or 5.5
	local rate = 1.5 * math.pi / HD
	local pos, dir, t = body, heading, elapsed
	local homing = true
	local function aimAt(now)
		local best, bestErr = nil, math.huge
		local trNow = Mark.dumpTravel(now)
		local i = HD
		while i <= HD + HS + 0.001 do
			local p = targetAt(i)
			local err = flat(p - pos).Magnitude - (Mark.dumpTravel(i) - trNow + landing)
			if err <= 0 then
				return p
			end
			if err < bestErr then
				best, bestErr = p, err
			end
			i += 0.05
		end
		return bestErr <= 4 and best or nil
	end
	while t < HD - 1e-4 do
		local dt = math.min(0.03, HD - t)
		if homing then
			local aim = aimAt(t)
			local to = aim and flat(aim - pos)
			if not to then
				homing = false
			elseif to.Magnitude > 0.001 then
				local u = to.Unit
				if u:Dot(dir) < 0 and to.Magnitude < landing then
					homing = false
				else
					local ang = math.acos(math.clamp(dir:Dot(u), -1, 1))
					local turn = rate * dt
					if ang <= turn then
						dir = u
					else
						if dir.Z * u.X - dir.X * u.Z < 0 then
							turn = -turn
						end
						local c, s = math.cos(turn), math.sin(turn)
						dir = Vector3.new(dir.X * c + dir.Z * s, 0, -dir.X * s + dir.Z * c)
					end
				end
			end
		end
		pos += dir * (Mark.dumpTravel(t + dt) - Mark.dumpTravel(t))
		t += dt
	end
	local t0 = math.max(t, elapsed)
	return function(bt)
		return pos + dir * (Mark.dumpTravel(bt) - Mark.dumpTravel(t0)), dir
	end
end

Mark.assistSweep = function(body, heading, elapsed, target, targetVel, pad)
	local HD, HS = C.HitboxDelaySeconds, C.HitboxSeconds
	local box = HitboxSettings.SlideTackle
	local hx, hz, boxMid = box.Size.X * 0.5, box.Size.Z * 0.5, -box.CFrameOffset.Z
	local rootAt = Mark.assistPath(body, heading, elapsed, function(i)
		return target + targetVel * (i - elapsed)
	end)
	local tb = math.max(elapsed, HD)
	while tb <= HD + HS + 1e-4 do
		local rootPos, dir = rootAt(tb)
		local rel = flat(target + targetVel * (tb - elapsed) - rootPos)
		local lon = rel:Dot(dir) - boxMid
		local lat = rel.X * dir.Z - rel.Z * dir.X
		if math.max(math.abs(lon) - hz, math.abs(lat) - hx, 0) <= pad then
			return tb - elapsed
		end
		tb += 0.03
	end
	return nil
end

-- Does his slide hit us. ONE physical test: the server checks our HRP point against his slide box
-- (SlideTackle.IsInsideHitbox: |x|,|y|,|z| <= 2.5 around root + 3 studs ahead), live from HitboxDelaySeconds for
-- HitboxSeconds. His path = lock.origin + lock.heading * travel(t), re-anchored every frame on his CURRENT position and
-- direction (lockEnemySlide): a PC tackler steers the whole slide with MoveCommand (SlideTackle main dash reads
-- GetDirection every frame), so the packet heading alone misses bent slides. Our server pose = ghost (and live)
-- moving with our current step, both packet-delay hypotheses. Pads: strong 0.35 + our motion over ping/2;
-- weak +1.0 before his hand-off. Assisted actors (learned by Mark.slideAudit) with us as ball owner: the real
-- homing (Mark.assistSweep). Removed: predNear / corridor / rear / bent / close / onLine reads - they fired up to
-- 4.5-8.25 studs off his line and on slides already behind us; the old "own ball -> any slide in reach fires"
-- (slideHoming) is gone too.
Mark.slideAtUs = function(lock, elapsed, root, actor)
	if not (lock and lock.heading and lock.origin and root) then
		return nil
	end
	elapsed = elapsed or 0
	local HD = C.HitboxDelaySeconds
	local tEnd = HD + C.HitboxSeconds
	local ghost = ourRewindPosition(root, actor)
	local live = root.Position
	local ch = LocalPlayer.Character
	local vel = flat((ch and CharacterMotion.GetVelocity(ch)) or Vector3.zero)
	local stick = nil
	if ch then
		local cmd = CharacterControllers.GetMoveCommand(ch)
		if typeof(cmd) == "Vector3" then
			stick = unitOrNil(flat(cmd))
		end
	end
	local step = stick and (stick * math.max(vel.Magnitude, 16)) or vel
	local heading = lock.heading
	local body = lock.origin + heading * Mark.dumpTravel(math.min(elapsed, C.TotalMotionSeconds))
	local window = elapsed <= tEnd + 0.04
	local pingS = math.clamp(LocalPlayer:GetNetworkPing() or 0, 0, 0.25)
	local box = HitboxSettings.SlideTackle
	local hx, hz, boxMid = box.Size.X * 0.5, box.Size.Z * 0.5, -box.CFrameOffset.Z
	local motionPad = math.min(step.Magnitude * pingS * 0.5, 1.2)
	local assistOn = Mark.assistOK(actor)
	local padStrong = 0.35 + motionPad
	local padWeak = padStrong + ((elapsed < HD and not assistOn) and 1.0 or 0.3)
	local minOut, outG, outL = 1e9, 1e9, 1e9
	local closest, hitIn = nil, nil
	local nowIn = false
	local function sweep(pad)
		local found = false
		for _, d in { 0, pingS } do
			local tb = math.max(elapsed + d, HD)
			while tb <= tEnd + 1e-4 do
				local tau = math.max(tb - elapsed - d, 0)
				local rootPos = lock.origin + heading * Mark.dumpTravel(tb)
				for k, base in { ghost, live } do
					local rel = flat(base + step * tau - rootPos)
					local lon = rel:Dot(heading) - boxMid
					local lat = rel.X * heading.Z - rel.Z * heading.X
					local out = math.max(math.abs(lon) - hz, math.abs(lat) - hx, 0)
					if out < minOut then
						minOut = out
						closest = rootPos + heading * boxMid
					end
					if k == 1 and out < outG then
						outG = out
					elseif k == 2 and out < outL then
						outL = out
					end
					if out <= 0 and tau <= 0.04 then
						nowIn = true
					end
					if out <= pad then
						if not hitIn or tau < hitIn then
							hitIn = tau
						end
						found = true
					end
				end
				tb += 0.03
			end
		end
		return found
	end
	local hitS = window and sweep(padStrong)
	local hitW = hitS or (window and sweep(padWeak))
	local assistP = false
	if assistOn and window and elapsed < HD and liveOwnerId() == LocalPlayer.UserId then
		local tau = Mark.assistSweep(body, heading, elapsed, ghost, step, padStrong)
		if tau then
			assistP = true
			hitIn = math.min(hitIn or tau, tau)
		end
	end
	local fire = (hitW or assistP) and true or false
	local strong = (hitS or assistP) and true or false
	local toG, toL = flat(ghost - body), flat(live - body)
	local uG, uL = unitOrNil(toG), unitOrNil(toL)
	local side = math.abs(toL.X * heading.Z - toL.Z * heading.X)
	return {
		fire = fire,
		force = fire,
		strong = strong,
		approach = false,
		why = (hitS and "box," or (hitW and "pad," or "")) .. (assistP and "assist," or "") .. string.format("out%.1f,pad%.1f", minOut, padStrong),
		hitIn = fire and hitIn or nil,
		hits = nowIn,
		boxed = nowIn,
		fut = hitW and true or false,
		defend = hitS and true or false,
		walkIn = hitW and true or false,
		predHit = hitS and true or false,
		closest = closest,
		hitP = closest,
		lat = minOut,
		latG = outG,
		latL = outL,
		side = side,
		body = toL.Magnitude,
		srv = toG.Magnitude,
		dist = math.min(toG.Magnitude, toL.Magnitude),
		ghost = ghost,
		dotG = uG and heading:Dot(uG) or nil,
		dotL = uL and heading:Dot(uL) or nil,
	}
end

Mark.assistOK = function(actor)
	local k = actor and actor.UserId
	local r = k and Mark.assistKnow and Mark.assistKnow[k]
	return r ~= nil and r.home > r.straight
end

-- Tracks every enemy slide near us: (a) learns whether that actor's dash homes on us (bend toward us after the
-- packet heading) -> Mark.assistKnow; (b) audits the reaction: did his real slide box ever contain our server pose.
-- Log: "tackle audit <name> fired <why> dist <d> result hit|miss minLat <l> bend <deg> homing <b> dribble <b> dodge <b>".
Mark.slideAudit = function(root)
	local list = Mark.audits
	if not list or #list == 0 then
		return
	end
	local now = os.clock()
	for i = #list, 1, -1 do
		local a = list[i]
		local el = now - a.t0
		local theirRoot = a.root
		if not (theirRoot and theirRoot.Parent) or el > 1.2 then
			table.remove(list, i)
		else
			local pe = theirRoot.Position
			local d = flat(pe - a.p0)
			if d.Magnitude > 3 then
				a.dirNow = d.Unit
				a.travel = d.Magnitude
			end
			if el >= C.HitboxDelaySeconds - 0.05 and el <= C.HitboxDelaySeconds + C.HitboxSeconds + 0.1 then
				local dir = a.dirNow or a.heading
				local ghost = ourRewindPosition(root, a.actor)
				local rel = flat(ghost - pe)
				local ax = rel:Dot(dir)
				if ax > -3 then
					local lat = (rel - dir * ax).Magnitude
					if lat < a.minLat then
						a.minLat = lat
					end
				end
				local proxy = { CFrame = CFrame.lookAt(pe, pe + dir) }
				if SlideTackle.IsInsideHitbox(proxy, Vector3.new(ghost.X, pe.Y, ghost.Z)) then
					a.hit = true
				end
			end
			if el >= C.HitboxDelaySeconds + C.HitboxSeconds + 0.12 then
				table.remove(list, i)
				local bend, homing = 0, false
				if a.dirNow and (a.travel or 0) > 6 then
					bend = math.deg(math.acos(math.clamp(a.heading:Dot(a.dirNow), -1, 1)))
					local toUs = unitOrNil(flat(a.us0 - a.p0))
					if toUs and bend > 6 and a.dirNow:Dot(toUs) > a.heading:Dot(toUs) + 0.06 then
						homing = true
					end
					local key = a.actor and a.actor.UserId
					if key then
						Mark.assistKnow = Mark.assistKnow or {}
						local r = Mark.assistKnow[key] or { home = 0, straight = 0 }
						Mark.assistKnow[key] = r
						if homing then
							r.home += 1
						elseif bend < 4 then
							r.straight += 1
						end
					end
				end
				logFile("tackle audit", a.name, "fired", tostring(a.fired), a.why or "-", "dist", string.format("%.1f", a.dist), "result", a.hit and "hit" or "miss", "minLat", a.minLat < 1e8 and string.format("%.1f", a.minLat) or "-", "bend", string.format("%.0f", bend), "homing", tostring(homing), "dribble", tostring(a.dribble == true), "dodge", tostring(a.dodge == true))
			end
		end
	end
end

-- AgentAddon during / right before our dribble. The dribble only pays (SuccessfulDodgeSpeedBoost 1.5 s, crowd
-- DodgeSucceeded) when his box lands on us INSIDE the iframe (Dodge.ActiveSeconds 1). Plan on his re-anchored path
-- (lockEnemySlide follows his current direction): box centre c(t) = origin + heading * (travel(t) + 3) over the rest
-- of his window; pick the earliest t the dribble walk (Dodge WalkSpeed 12) reaches c(t) by, inside the iframe, and go
-- there. No holding of a final point: once we are in his box (or past the chosen point) keep walking at HIM until his
-- window closes - the box comes at us anyway and staying on his line keeps us in it. Window over or the iframe cannot
-- cover the rest of it -> nil (the user gets the controls back).
-- returns dir, phase ("meet" | "into"), target
Mark.dribblePlan = function(root, iframeEnd)
	local threat = dribbleDanger
	if not (threat and threat.sliding) then
		return nil
	end
	local lock = threat.character and slideLock[threat.character]
	if not lock and threat.actor then
		local ch = Actors.GetCharacter(threat.actor)
		lock = ch and slideLock[ch]
	end
	if not (lock and lock.heading and lock.origin and lock.t0) then
		return nil
	end
	local now = os.clock()
	local e = now - lock.t0
	local HD, tEnd = C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds
	if e > tEnd then
		return nil
	end
	iframeEnd = iframeEnd or (lastDodgeAt + Dodge.Constants.ActiveSeconds)
	if iframeEnd - now < (tEnd - math.max(e, HD)) * 0.5 + 0.05 then
		return nil -- the iframe ends before most of his window: walking in would just eat the hit
	end
	local us = flat(root.Position)
	local mid = Mark.slideBox()
	local spd = Dodge.Constants.WalkSpeed or 12
	local body = lock.origin + lock.heading * Mark.dumpTravel(e)
	local t = math.max(e, HD)
	local first = nil
	while t <= tEnd + 1e-4 do
		local c = lock.origin + lock.heading * (Mark.dumpTravel(t) + mid)
		local need = math.max((flat(c) - us).Magnitude - 2.0, 0) / spd -- 2.0: inside the 5x5 box before its centre
		if not first then
			first = c
		end
		if need <= t - e and now + (t - e) <= iframeEnd - 0.05 then
			local to = flat(c) - us
			if to.Magnitude <= 1.0 then
				break -- already there: go at him
			end
			return to.Unit, "meet", c
		end
		t += 0.03
	end
	local toHim = unitOrNil(flat(body) - us)
	return toHim, "into", body
end

-- kept name: every caller (tryDribble dash, approach walk) gets the planned direction
local function dribbleInterceptDir(root, forDash)
	local dir = Mark.dribblePlan(root, (not ClientDodge.IsDribbling()) and (os.clock() + Dodge.Constants.ActiveSeconds) or nil)
	return dir
end

local function dribbleThreat(root)
	if not Mark.playLive() then
		return nil
	end
	local best
	local maxReach = Mark.dumpTravel(C.HitboxDelaySeconds + C.HitboxSeconds) + 5.9
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r then
				local lock, elapsed = lockEnemySlide(model, r)
				if lock and elapsed then
					local at = Mark.slideAtUs(lock, elapsed, root, actor)
					if at and at.fire and (at.dist <= CFG.DribbleReact or at.dist <= maxReach) then
						if not best or at.dist < best.dist then
							best = {
								root = r,
								dist = at.dist,
								character = model,
								actor = actor,
								ourPos = at.ghost,
								heading = lock.heading,
								origin = lock.origin,
								sliding = true,
								fire = at.fire,
								strong = at.strong and true or false,
								why = at.why,
								approach = at.approach,
								force = at.fire,
								future = slideFuture(lock, elapsed),
								hitIn = at.hitIn,
								hitT = at.hitT,
								hitP = at.hitP,
								closest = at.closest,
								lat = at.lat,
								elapsed = elapsed,
							}
						end
					end
				end
			end
		end
	end
	return best
end

-- Enemy kick charge (ActionPresentationUpdate KickChargeStarted/Updated: userId + aim). The hit is resolved at his
-- release with HitboxSettings.Kick (6x7x7, CFrameOffset Z -1.5) on AimFacing.GetAimedRoot(root, aim): a box laid
-- along his FLAT aim. He may release any time after KickCore.GetMinimumReleaseSeconds. A dribble (Dodge
-- ActiveSeconds 1 iframe) started once that window opens covers every release up to a second later and earns
-- SuccessfulDodgeSpeedMultiplier when the kick lands on the iframe.
-- Enemy kick box art. One renderer for the live overlay, so what is tuned here is
-- what shows in a match. Concept: the box is BUILT by his charge. Edges draw themselves in construction order
-- (floor -> posts -> roof) as the charge climbs to KickCore minimum release; a sweep bar crosses the floor at the
-- same rate. At release-ready the floor takes three hatch strokes that land staggered (fast attack, small overshoot,
-- settle) and chevrons run along the floor toward the front face: the direction the kick will throw us. On the
-- strike the box folds onto its front face. LIP strokes only (ink under, colour on top), weight carries depth.
-- near-plane clipped segment writer over a Drawing line pool
Mark.segPool = function(lines)
	local pool = { i = 1 }
	pool.seg = function(a, b, color, alpha, thick, z)
		local ln = lines[pool.i]
		if not ln then
			return
		end
		-- camera state is read once per frame (Mark.frameCam, set at the top of RenderStepped); polyline callers
		-- (rings, arcs) reuse the projection of the previous segment's end point instead of projecting it twice
		local cam, cp, lk = Mark.frameCam, Mark.framePos, Mark.frameLook
		if not cam then
			cam = Workspace.CurrentCamera
			local cf = cam.CFrame
			cp, lk = cf.Position, cf.LookVector
		end
		local da, db = (a - cp):Dot(lk), (b - cp):Dot(lk)
		if da < 0.15 and db < 0.15 then
			return
		end
		local ob = b
		local pa, pb
		if da < 0.15 then
			a = a:Lerp(b, (0.15 - da) / (db - da))
		elseif db < 0.15 then
			b = b:Lerp(a, (0.15 - db) / (da - db))
		end
		if pool.lastB == a and pool.lastFrame == Mark.frameId then
			pa = pool.lastP
		else
			pa = cam:WorldToViewportPoint(a)
		end
		pb = cam:WorldToViewportPoint(b)
		if db >= 0.15 then
			pool.lastB, pool.lastP, pool.lastFrame = ob, pb, Mark.frameId
		else
			pool.lastB = nil
		end
		pool.i += 1
		ln.From, ln.To, ln.Color, ln.Transparency, ln.Thickness, ln.ZIndex, ln.Visible =
			Vector2.new(pa.X, pa.Y), Vector2.new(pb.X, pb.Y), color, alpha, thick, z, true
	end
	-- hide only what the previous frame drew past this one (pool.hw): an idle overlay costs nothing per frame
	pool.hw = #lines
	pool.finish = function()
		for n = pool.i, pool.hw do
			lines[n].Visible = false
		end
		pool.hw = pool.i - 1
		pool.i = 1
	end
	return pool
end

-- Kick charge as a ripple: rings born at the centre of his kick box on the floor, growing out to the box footprint
-- and fading as they grow, like a drop in water. Born every 0.45 s, three alive at once, ease-out growth. Each ring
-- is 28 segments with a gradient that flows around it (phase moves with time), palette by state: blue (we're out),
-- amber (inside, he cannot release yet), red (inside, release possible). Charge progress speeds the birth rate up.
Mark.kickPalette = {
	safe = { Color3.fromRGB(90, 200, 255), Color3.fromRGB(150, 120, 255), Color3.fromRGB(80, 255, 220) },
	armed = { Color3.fromRGB(255, 190, 70), Color3.fromRGB(255, 110, 150), Color3.fromRGB(255, 240, 140) },
	live = { Color3.fromRGB(255, 60, 70), Color3.fromRGB(255, 70, 200), Color3.fromRGB(255, 150, 60) },
}
-- phase is accumulated per caller (Mark.ripplePhase): the old version derived the ring index from os.clock()/period
-- with a period that changed every frame, so ring ages jumped around -> the blue windup state flickered wildly.
Mark.ripplePhase = {}
Mark.rippleRates = { live = 1 / 0.5, armed = 1 / 0.6, safe = 1 / 0.6 } -- rings per second; windup a bit slower than live
Mark.rippleStep = function(key, rate)
	local now = os.clock()
	local st = Mark.ripplePhase[key]
	if not st then
		st = { phase = 0, at = now }
		Mark.ripplePhase[key] = st
	end
	local dt = math.clamp(now - st.at, 0, 0.1)
	st.at = now
	st.phase += dt * rate
	return st.phase
end
Mark.kickRipple = function(seg, center, maxR, palette, phase, t, shape)
	local N = 28
	-- shape: superellipse exponent (2 = circle, 4 = rounded square that still reads as a circle)
	-- unit superellipse points are a constant per shape: built once, not 3 x 29 pow() pairs every frame
	Mark.squircleLut = Mark.squircleLut or {}
	local lut = Mark.squircleLut[shape or 2]
	if not lut then
		local ex = 2 / (shape or 2)
		lut = {}
		for s = 0, N do
			local a = s / N * math.pi * 2
			local c, sn = math.cos(a), math.sin(a)
			lut[s] = Vector3.new((c >= 0 and 1 or -1) * math.abs(c) ^ ex, 0, (sn >= 0 and 1 or -1) * math.abs(sn) ^ ex)
		end
		Mark.squircleLut[shape or 2] = lut
	end
	local function grad(f)
		-- 3-stop loop gradient, f in [0,1)
		local x = (f % 1) * 3
		local i = math.floor(x)
		local u = x - i
		local a, b = palette[i + 1], palette[(i + 1) % 3 + 1]
		u = u * u * (3 - 2 * u)
		return a:Lerp(b, u)
	end
	local born = math.floor(phase)
	for k = 0, 2 do
		local u = math.clamp((phase - (born - k)) / 3, 0, 1)
		local grow = 1 - (1 - u) ^ 3
		local r = 0.35 + (maxR - 0.35) * grow
		local alpha = (1 - u) ^ 1.6
		local thick = 1 + 2.2 * (1 - u)
		local flow = t * 0.35 + k * 0.17
		if alpha > 0.03 then
			local prev = nil
			for s = 0, N do
				local p = center + lut[s] * r
				if prev then
					seg(prev, p, grad(s / N + flow), alpha, thick, 43)
				end
				prev = p
			end
		end
	end
end

Mark.drawKickBox = function(kt, root)
	Mark.kickBoxLines = Mark.kickBoxLines or makeLines(96, 1.4, 42)
	Mark.kickPool = Mark.kickPool or Mark.segPool(Mark.kickBoxLines)
	local pool = Mark.kickPool
	if kt and kt.aimed and CFG.Draw and CFG.DrawKickBox ~= false and Workspace.CurrentCamera then
		local now = os.clock()
		if kt.open and not Mark.kickOpenAt then
			Mark.kickOpenAt = now
		elseif not kt.open then
			Mark.kickOpenAt = nil
		end
		local k = HitboxSettings.Kick
		local maxR = math.sqrt((k.Size.X * 0.5) ^ 2 + (k.Size.Z * 0.5) ^ 2)
		local P = Mark.kickPalette
		local key = (kt.inside and kt.open) and "live" or (kt.inside and "armed" or "safe")
		local phase = Mark.rippleStep("live-overlay", Mark.rippleRates[key])
		Mark.kickRipple(pool.seg, Vector3.new(kt.center.X, root.Position.Y - 2.9, kt.center.Z), maxR, P[key], phase, now)
	end
	pool.finish()
end

-- Seconds until a script Dribble press is actually accepted. The script's own `lastDodgeAt` only knows presses IT sent; the
-- game's Dodge.HandleInputBegan also refuses (returns true, no iframe: log "dodge gate dribble refused no-iframe cdLeft 0.00")
-- after the PLAYER's own dribble (module clock u6 -> Controls cooldown "Dribble"), without stamina (Dodge.Constants.StaminaCost
-- 0.25 via Sprint.SpendStamina) and in the air (CharacterControllers.IsLanded).
Mark.dribbleLeft = function()
	local left = math.max(0, dodgeEnforced - (os.clock() - lastDodgeAt))
	if Controls.IsOnCooldown("Dribble") then
		return Controls.GetCooldownRemaining("Dribble")
	end
	local cd = 0
	if cd > left then
		left = cd
	end
	if left <= 0 then
		local ch = LocalPlayer.Character
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hum and not CharacterControllers.IsLanded(ch, hum) then
			left = 0.25
			Mark.dribbleBlock = "air"
		else
			Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
			local can = Mark.sprint.CanSpendStamina(Dodge.Constants.StaminaCost, true)
			if can == false then
				left = 0.6
				Mark.dribbleBlock = "stamina"
			else
				Mark.dribbleBlock = nil
			end
		end
	else
		Mark.dribbleBlock = "cd"
	end
	return left
end

Mark.kickThreat = function(root)
	if not Mark.charges then
		return nil
	end
	local now = os.clock()
	local ping = LocalPlayer:GetNetworkPing()
	local minRel = KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds() or 0.15
	local best = nil
	for uid, rec in Mark.charges do
		if rec.live and now - (rec.seen or 0) < 1.5 and rec.dir then
			local actor = playerOf(uid)
			local r = actor and not sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
			if r then
				local ch = Actors.GetCharacter(actor)
				local pos = (ch and CharacterMotion.GetPosition(ch)) or r.Position
				local vel = flat(ch and CharacterMotion.GetVelocity(ch) or Vector3.zero)
				-- while the Kick charges he walks at ActionMovement.GetChargingWalkSpeed (log: ws 27 -> 8), not at the jog the
				-- displayed velocity still shows: the old sweep put him metres past the real box, `inside` never came true and
				-- the dribble never fired for a kick (no "dribble kick sent" in the log, only kick into/no threat flicker)
				if ch then
					Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
					local cw = Mark.mover.GetChargingWalkSpeed(Mark.mover.GetBaseWalkSpeed(ch), false)
					if type(cw) == "number" and vel.Magnitude > cw then
						vel = vel.Unit * cw
					end
				end
				local lead = 0.1 + ping
				local P = pos + vel * lead
				local aimed = AimFacing.GetAimedRoot({ Position = P }, rec.dir)
				local us = root.Position + flat(root.AssemblyLinearVelocity) * lead
				-- Sweep the possible release times instead of one fixed lead. He may release any time between the minimum
				-- release and the full charge; the server tests OUR pose from `ping` ago against HIS pose at that moment.
				-- With one fixed lead (0.1 + ping, both sides projected forward) a kick we had already run past still
				-- counted ("dribbles a shot I basically ran through"), and one we were about to run into was missed.
				local inside = false
				do
					local pad = math.min(CFG.HitPad or 0.8, 0.8) -- 1.6 on a 6x7 box fired for kicks a body-width off us
					local elapsedK = now - rec.at
					local rMin = math.max(minRel - elapsedK, 0)
					local rMax = math.max((KickCore.Constants.MaximumChargeSeconds or 0.4) - elapsedK, 0) + 0.12
					local dly = ch and math.clamp(CharacterMotion.GetDisplayDelaySeconds(ch) or 0, 0, 0.25) or 0
					local vUs = flat(root.AssemblyLinearVelocity)
					for ki = 0, 5 do
						local rr = rMin + (rMax - rMin) * (ki / 5)
						local Pk = pos + vel * (dly + rr)
						local usK = root.Position + vUs * (rr - ping)
						local aimedK = AimFacing.GetAimedRoot({ Position = Pk }, rec.dir)
						local hit = HitboxSettings.ContainsPoint(aimedK, HitboxSettings.Kick, usK)
						if not hit then
							for _, o in { { pad, 0 }, { -pad, 0 }, { 0, pad }, { 0, -pad } } do
								if HitboxSettings.ContainsPoint(aimedK, HitboxSettings.Kick, usK + Vector3.new(o[1], 0, o[2])) then
									hit = true
									break
								end
							end
						end
						if hit then
							inside = true
							P, us, aimed = Pk, usK, aimedK
							break
						end
					end
				end
				local k = HitboxSettings.Kick
				local center = (aimed.CFrame * k.CFrameOffset).Position
				local d = flat(us - P).Magnitude
				local elapsed = now - rec.at
				local toUs = unitOrNil(flat(us - P))
				local fd = unitOrNil(flat(rec.dir))
				local th = { us = us, minRel = minRel, aimed = aimed, facing = (toUs and fd) and toUs:Dot(fd) or 0, uid = uid, actor = actor, inside = inside, center = Vector3.new(center.X, root.Position.Y, center.Z), dist = d, elapsed = elapsed, open = elapsed >= minRel - ping - 0.05 }
				if d <= 14 and (not best or d < best.dist) then
					best = th
				end
			end
		end
	end
	return best
end

local function tryDribble(force)
	if Mark.dribbleLeft() > 0 then
		return false, Mark.dribbleBlock or "cd"
	end
	-- A scripted sidestep (dodge tp) is in progress: it already took us out of this slide. The dribble cooldown ends
	-- a moment later and the per-frame threat (read from our lagging server pose) still says "fire": the dribble
	-- was spent after the danger had passed.
	if not force and Mark.move and Mark.move.mode == "dodge" and Mark.dodgeAt and os.clock() - Mark.dodgeAt < 1.0 then
		return false, "evading"
	end
	if ClientDodge.IsDribbling() then
		return false, "active"
	end
	if liveOwnerId() == LocalPlayer.UserId then
		ClientDodge.SetOwnerUserId(LocalPlayer.UserId)
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local dashDir = root and dribbleInterceptDir(root, true)
	local dir = root and dribbleInterceptDir(root)
	if not dashDir then
		dashDir = root and unitOrNil(flat(root.CFrame.LookVector))
	end
	if CFG.AgentAddon and dir and Mark.moveSteer then
		Mark.moveSteer(dir, "dribble")
	end
	ClientDodge.HandleInputBegan(Controls.CreateInput("Dribble"), false)
	local active = ClientDodge.IsDribbling()
	if not active then
		if not (dashDir or dir) then
			return false, "game-reject"
		end
		ActionRemoteProtocol.Send(ActionCommands.Dodge({
			AimDirection = dashDir or dir,
			ShotTime = Workspace:GetServerTimeNow(),
		}))
		active = ClientDodge.IsDribbling()
	end
	if not active then
		return false, "no-iframe"
	end
	lastDodgeAt = os.clock()
	do
		local th = dribbleDanger
		local ch = th and th.character
		local lk = ch and slideLock[ch]
		if lk then
			lk.usedDribble = true
		end
	end
	logFile("dribble sent")
	Log.pending[#Log.pending + 1] = {
		kind = "dribble",
		at = os.clock(),
		oid = liveOwnerId(),
	}
	return true, "sent"
end

local slideAim = nil
local slideAimUntil = 0
-- The slide holds the BODY only until the jump is restored: SlideTackleInput.lockLocalPlayer unblocks the jump at
-- TotalVelocityReleaseStartsAt + VelocityReleaseSeconds - ActionMotion.JumpRestoreLeadSeconds (1.02 + 0.5 - 0.25 = 1.27 s)
-- and releases the walk speed from 1.02 s. ClientSlide.IsSlideTackling() stays true for TotalMotionSeconds + EndLagSeconds
-- (2.415 s): every agent gated on it stood dead for ~1.15 s with a free body (log: state "slide=true ws=25.6 jh=7.2
-- jblock=-"), which is exactly the flick over our slide. Agents gate on this; the slide cooldown / input hooks keep
-- IsSlideTackling.
Mark.slideFree = C.TotalVelocityReleaseStartsAt + C.VelocityReleaseSeconds - ActionMotion.Constants.JumpRestoreLeadSeconds
Mark.slideBody = function()
	return ClientSlide.IsSlideTackling() and os.clock() - (Mark.slideStartAt or -9) < Mark.slideFree
end
local origGetMove = CharacterControllers.GetMoveCommand
local origSetMove = CharacterControllers.SetMoveCommand
CharacterControllers.GetMoveCommand = function(ch)
	if slideAim and ch == LocalPlayer.Character and os.clock() < slideAimUntil then
		return slideAim
	end
	if ch == LocalPlayer.Character and Mark.slideBody() then
		return origGetMove(ch)
	end
	-- the player's own stick (no agent mode live): AutoDodge keeps it out of a blast about to go off and off mines
	if ch == LocalPlayer.Character and CFG.AutoDodge and not Mark.moveLive(Mark.move) then
		local haz, mines = next(Mark.hazEv) ~= nil, Mark.mines ~= nil and #Mark.mines() > 0
		local proj = Mark.projDanger ~= nil and next(Mark.projDanger) ~= nil
		if haz or mines or proj then
			local cc = origGetMove(ch)
			if proj and typeof(cc) == "Vector3" and cc.Magnitude > 0.2 then
				cc = Mark.projDir(cc)
			end
			if haz then
				cc = Mark.blastClamp(ch, cc)
			end
			local root = mines and typeof(cc) == "Vector3" and cc.Magnitude > 0.2 and ActorTargeting.GetActorRoot(LocalPlayer)
			if root then
				cc = Mark.mineDir(root, cc)
			end
			if typeof(cc) == "Vector3" then
				return cc
			end
		end
	end
	local move = Mark.move
	if move and move.dir and move.mode and ch == LocalPlayer.Character and move.dir.Magnitude > 0.2 and Mark.moveLive(move) then
		Mark.coast = nil
		return move.dir
	end
	-- air coast: the controller still holds our last agent direction (moveStop did not zero it mid-air); on landing it
	-- is cleared unless the player has put his own stick in since
	local co = Mark.coast
	if co and ch == LocalPlayer.Character then
		local hum = ch:FindFirstChildOfClass("Humanoid")
		if not hum or CharacterControllers.IsLanded(ch, hum) or os.clock() - co.at > 1.5 then
			Mark.coast = nil
			local cur = origGetMove(ch)
			if typeof(cur) == "Vector3" and (cur - co.dir).Magnitude < 0.05 then
				origSetMove(ch, Vector3.zero, Vector3.zero, false)
			end
		end
	end
	return origGetMove(ch)
end
-- A steer mode is owned by whoever calls moveSteer. If that caller stops (error, early return, state change, a branch
-- of stepLogic that never reaches moveStop) the mode used to stay: GetMoveCommand kept returning move.dir and moveTick
-- kept replaying it = the agent held a direction and walked you in it (tester). Path modes (m.pts) end at their last
-- point; dodge has its own cap; everything else expires 0.5 s after its last real steer.
Mark.moveLive = function(m)
	if not (m and m.mode) then
		return false
	end
	if m.mode == "dodge" then
		-- the dodge has its own end (dodgeSteer: slide over / threat gone), and when that end is never reached - a stale threat
		-- table, a Mark.dodgeDone left over from the last dodge so dodgeSteer returns at once, a mode set by a step-walk - the
		-- old "always live" held the stick for 30 s (log: move=dodge from 11386 to 11416, through a kick and two jumps). 1.4 s from
		-- the start of the dodge is the hard cap the keeper half always had (dodgeTend); the watchdog in moveTick ends it.
		return os.clock() - (Mark.dodgeAt or m.at or 0) < 1.4
	end
	-- (m.pts is a drawn route for ball / block / dribble too, not proof that anybody is still driving the mode;
	-- walk / take paths are driven by moveTick, which steers every frame and refreshes m.at)
	return os.clock() - (m.at or 0) < 0.5
end
-- Dive input. origSetMove writes the controller's MoveCommand directly and the game does not rewrite it while the
-- player holds no stick, so every keeper dive left the dive direction in the controller: the keeper kept walking that
-- way after landing (tester: "the script holds a direction and leads me", always keeper-related). The command is cleared
-- 0.15 s after the dive unless something else (the player, a live agent mode) has written a different one since.
Mark.diveSet = function(character, wd, fwd)
	origSetMove(character, wd, fwd, true)
end
Mark.diveRestore = function(character, wd)
	task.delay(0.15, function()
		if not (character and character.Parent) or Mark.moveLive(Mark.move) then
			return
		end
		local cur = origGetMove(character)
		if typeof(cur) == "Vector3" and typeof(wd) == "Vector3" and (cur - wd).Magnitude < 0.05 then
			origSetMove(character, Vector3.zero, Vector3.zero, false)
		end
	end)
end
Mark.cutSlide = function(move)
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local mv = unitOrNil(flat(move))
	if not (root and mv) then
		return nil
	end
	local ghost = ourRewindPosition(root, nil)
	for _, lock in slideLock do
		if lock and lock.heading and lock.origin and lock.t0 then
			local elapsed = os.clock() - lock.t0
			if elapsed <= C.HitboxDelaySeconds + C.HitboxSeconds + 0.04 then
				local at = Mark.slideAtUs(lock, elapsed, root, nil)
				local soon = ghost + mv * 10
				local _, soonLat = slidePathClosest(lock, elapsed, soon)
				local into = mv:Dot(lock.heading) > 0.2
				if at and (at.defend or at.walkIn or (into and soonLat <= 3.2 and (at.srv or 99) <= 26)) then
					local side = Vector3.new(-lock.heading.Z, 0, lock.heading.X)
					if side:Dot(ghost - lock.origin) < 0 then
						side = -side
					end
					if not Mark.cutLog or os.clock() - Mark.cutLog > 0.4 then
						Mark.cutLog = os.clock()
						logFile("cut walk", fmtV(side), "srv", at.srv and string.format("%.1f", at.srv) or "-")
					end
					return side
				end
			end
		end
	end
	return nil
end
CharacterControllers.SetMoveCommand = function(ch, move, look, rot)
	if ch == LocalPlayer.Character and typeof(move) == "Vector3" and move.Magnitude > 0.2 and Mark.cutSlide and not ClientDodge.IsDribbling() then
		local cut = Mark.cutSlide(move)
		if cut then
			move = cut
			look = Mark.move.look or cut
		end
	end
	if ch == LocalPlayer.Character and Mark.slideBody() and not (slideAim and os.clock() < slideAimUntil) then
		return origSetMove(ch, move, look, rot)
	end
	if Mark.move.dir and Mark.move.mode and ch == LocalPlayer.Character and Mark.move.dir.Magnitude > 0.2 and Mark.moveLive(Mark.move) then
		move = Mark.move.dir
		if Mark.move.mode == "dodge" or Mark.move.mode == "block" then
			look = Mark.move.look or Mark.move.dir
			rot = true
		end
	end
	if ch == LocalPlayer.Character and Mark.chargeFace and ChargedKick.IsCharging and ChargedKick.IsCharging() then
		look = Mark.chargeFace
		rot = true
	end
	return origSetMove(ch, move, look, rot)
end
Mark.origSlideBegan = ClientSlide.HandleInputBegan
-- Gameplay_Script routes every InputBegan through slideTackleInput.HandleInputBegan; only a real Tackle press
-- from the player may cancel the agent, not W/Shift/Space.
-- ManualSupport: the player's own Tackle (keyboard, pad or the touch button all land here via Controls.IsInput) is
-- redirected onto the AutoTackle solution when the solver has a confirmed hit for this frame (Mark.manualTackle,
-- fresh < 0.15 s). No solution -> the press goes through untouched. Our own synthetic press (tryTackle) sets slideAim
-- first, so it is never re-captured here.
ClientSlide.HandleInputBegan = function(input, processed, ...)
	if not slideAim and not processed and Controls.IsInput("Tackle", input) then
		local character = LocalPlayer.Character
		local root = ActorTargeting.GetActorRoot(LocalPlayer)
		if CFG.ManualTackle and character and root and Mark.tryTackle and not ClientSlide.IsSlideTackling() then
			-- Solved at the moment of the press (the old path used the tick's solution only when it was a confirmed hit
			-- younger than 0.15 s: a press while the carrier was still "outrun"/"close"/"track" went out unaimed).
			-- Enemy carrier within ManualRadius -> the slide is aimed at him; nobody there -> the press is untouched and
			-- the game takes the player's own direction (stick, else where he faces).
			local aim, mult, tgt, how = Mark.manualAim(character, root)
			if not aim then
				local m = Mark.manualTackle
				if m and os.clock() - m.at < 0.15 then
					aim, mult, tgt, how = m.aim, m.mult, { char = m.char, root = m.root }, "tick"
				end
			end
			if aim then
				local _, why = Mark.tryTackle(character, root, aim, mult, tgt)
				logFile("tackle manual", tostring(why), "src", how, "aim", fmtV(aim), "mult", string.format("%.2f", mult or 0))
				if ClientSlide.IsSlideTackling() then
					return true
				end
			elseif not Mark.manualOwnLog or os.clock() - Mark.manualOwnLog > 1 then
				Mark.manualOwnLog = os.clock()
				logFile("tackle manual", "own dir", "no carrier within", tostring(CFG.ManualRadius))
			end
		end
		if Mark.moveStop then
			Mark.moveStop()
		end
	end
	return Mark.origSlideBegan(input, processed, ...)
end

-- Manual Tackle from a UI keybind / mobile button: the same aimed slide the game's own Tackle press gets above.
Mark.manualFire = function()
	local character = LocalPlayer.Character
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not (character and root and Mark.tryTackle) or ClientSlide.IsSlideTackling() then
		return
	end
	local aim, mult, tgt, how = Mark.manualAim(character, root)
	if not aim then
		local m = Mark.manualTackle
		if m and os.clock() - m.at < 0.15 then
			aim, mult, tgt, how = m.aim, m.mult, { char = m.char, root = m.root }, "tick"
		end
	end
	if not aim then
		logFile("tackle manual", "key", "no carrier within", tostring(CFG.ManualRadius))
		return
	end
	local _, why = Mark.tryTackle(character, root, aim, mult, tgt)
	logFile("tackle manual", tostring(why), "key", how or "-", "aim", fmtV(aim), "mult", string.format("%.2f", mult or 0))
end

Mark.chargeInst = function()
	local fn = ChargedKick.IsCharging
	if type(fn) ~= "function" then
		return nil
	end
	local inst = upvalue(fn, 1)
	if type(inst) == "table" and type(inst.IsLocalOwner) == "function" then
		return inst
	end
	return nil
end

-- The real auto-release moment of OUR kick charge: ChargedKick.StartCharge task.delay(MaximumChargeSeconds) ->
-- ReleaseFullCharge (no HandleInputEnded, so no hook sees it). A kick powerup (KickPowerups.GetMultiplier > 1) cuts it
-- by PoweredUpChargeReductionSeconds: 0.4 -> 0.3 s.
Mark.chargeMax = function()
	local maxC = KickCore.Constants.MaximumChargeSeconds or 0.4
	Mark.kickPow = Mark.kickPow or require(Modules.Actions.KickPowerups)
	local mul = Mark.kickPow.GetMultiplier and Mark.kickPow.GetMultiplier(LocalPlayer)
	if type(mul) == "number" and mul > 1 then
		local cut = (Mark.kickPow.Constants and Mark.kickPow.Constants.PoweredUpChargeReductionSeconds) or 0.1
		maxC = math.max((KickCore.Constants.MinimumChargeSeconds or 0.2) + 0.001, maxC - cut)
	end
	return maxC
end

Mark.weOwn = function()
	if liveOwnerId() == LocalPlayer.UserId then
		return true
	end
	local inst = Mark.chargeInst()
	if inst and inst.IsLocalOwner() then
		return true
	end
	return false
end

Mark.yieldKick = function()
	local cmd = Mark.kickCmd
	if cmd and not ClientSlide.IsSlideTackling() and ActionRemoteProtocol.IsCurrentSession(cmd) then
		ActionRemoteProtocol.Cancel(cmd)
	end
	if ChargedKick.CancelCharge then
		ChargedKick.CancelCharge()
	end
	Mark.dropKick()
end

Mark.dropKick = function()
	Mark.kickCmd = nil
end

-- A slide that would cross a puddle stuns us (HazardZoneKind Oil). Over the first ~14 studs a jump covers it: the slide is
-- pressed from the air (jump first, slide second - the other order is impossible, SetJumpStateBlocked("SlideTackle")). A
-- crossing that the air time does not cover, or a mine on the path, cancels the slide.
Mark.slidePathHazard = function(root, dir, mult)
	local m = mult or 1
	local function timeAt(d)
		for t = 0.02, 1.2, 0.02 do
			if Mark.dumpTravel(t) * m >= d then
				return t
			end
		end
		return 1.2
	end
	local reach = Mark.dumpTravel(1.0) * m
	local mineAt = Mark.mineAhead(root.Position, dir, reach)
	if mineAt then
		return "mine"
	end
	local run = Mark.oilAhead(root.Position, dir, reach)
	if not run then
		return nil
	end
	return "oil", timeAt(run.enter), timeAt(run.exit)
end

Mark.oilSlideTick = function(character, root)
	local p = Mark.oilSlide
	if not p then
		return
	end
	local now = os.clock()
	local hum = character:FindFirstChildOfClass("Humanoid")
	if now - p.at > 0.6 or not hum then
		Mark.oilSlide = nil
		return
	end
	if not CharacterControllers.IsLanded(character, hum) and now - p.at >= 0.1 then
		Mark.oilSlide = nil
		local sent, why = Mark.tryTackle(character, root, p.dir, p.mult, p.target, true)
		logFile("oil slide", "air", sent and "sent" or ("no " .. tostring(why)))
	end
end

local tryTackle
-- A carrier who is popping the ball up (flick wind-up, or the ball already above his Receive box) JUMPS after it: a ground slide
-- under him is wasted (the log: slide at the keeper-side carrier, he flicked and jumped). Returns "flick" | "ball high" | nil.
-- Another player's flick wind-up (see the RainbowFlickStarted note in onFx): true + seconds until the ball detaches
Mark.enemyWind = function(actor)
	local uid = actor and actor.UserId
	local rec = uid and Mark.flickRec and Mark.flickRec[uid]
	if not rec then
		return false, 0
	end
	local left = rec.detachSrv - Workspace:GetServerTimeNow()
	if left < -0.1 then
		Mark.flickRec[uid] = nil
		return false, 0
	end
	return true, math.max(left, 0)
end

Mark.lofting = function(ch, enemyRoot)
	if not ch then
		return nil
	end
	local pl = Players:GetPlayerFromCharacter(ch)
	Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
	if pl and Mark.enemyWind(pl) then
		return "flick"
	end
	local ballP = Renderer.GetPosition()
	local r = enemyRoot or ch:FindFirstChild("HumanoidRootPart")
	if typeof(ballP) == "Vector3" and r then
		local rcvH = HitboxSettings.Receive.CFrameOffset.Y + HitboxSettings.Receive.Size.Y * 0.5 + (Physics.BallRadius or 1)
		if ballP.Y - r.Position.Y > rcvH + 0.6 and flat(ballP - r.Position).Magnitude <= 12 then
			return "ball high"
		end
	end
	return nil
end


tryTackle = function(character, root, dir, mult, target, skipHazard, bend)
	if MatchSettings.IsGoalkeeperCharacter(character) then
		return false, "keeper" -- the keeper has no slide: the key is the dive
	end
	if os.clock() - lastTackleAt < tackleEnforced then
		return false, "cd"
	end
	-- the game refused the last press for a reason we do not mirror: do not hammer it every frame (log: 5 rejects in 50 ms)
	if os.clock() - (Mark.tackleRejectAt or -9) < 0.3 then
		return false, "reject-wait"
	end
	if Ragdoll.IsActorRagdolled(LocalPlayer) then
		return false, "ragdoll"
	end
	-- SlideTackleInput.HandleInputBegan returns early while the kick charges (u8 = IsKickCharging).
	if ChargedKick.IsCharging and ChargedKick.IsCharging() then
		return false, "charging"
	end
	if ActionLocks.HasTackleBlock(LocalPlayer) then
		return false, "lock"
	end
	if SlideTackle.IsRepeatBlocked(character, false) then
		return false, "repeat"
	end
	-- the two checks of SlideTackleInput.HandleInputBegan this function did not mirror: we hold the ball (u6 == our id) and
	-- Sprint.SpendStamina(StaminaCost). Log 7125.15: walk speed 7.2 = no stamina, "tackle reject game-reject" EVERY frame, and
	-- each of them stopped the ball chase below.
	if liveOwnerId() == LocalPlayer.UserId then
		return false, "own ball"
	end
	Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
	if Mark.sprint.CanSpendStamina(SlideTackle.Constants.StaminaCost, true) == false then
		return false, "stamina"
	end
	if not dir then
		return false, "dir"
	end
	-- a lofting carrier (flick wind-up / ball above him): a ground slide under him is wasted. No blind jump here: the
	-- flick is slid in time or left to AutoBall's lob plan, an airborne carrier is the air duel's (Mark.tickCounterJump).
	if type(target) == "table" and target.char then
		local lw = Mark.lofting(target.char, target.root)
		local humJ = character:FindFirstChildOfClass("Humanoid")
		-- the air duel planned this exact contact against his path (a hook man next to the high ball is "ball high" too)
		if lw and humJ and CharacterControllers.IsLanded(character, humJ) and not Mark.duelPress and not Mark.isLobber(target.char) then
			return false, "lofting"
		end
	end
	local wallRoot = ActorTargeting.GetActorRoot(LocalPlayer)
	local wallReach = math.min(Mark.dumpTravel(C.HitboxDelaySeconds) + 4, 14)
	if wallRoot and Mark.wallHit and Mark.wallHit(wallRoot.Position, dir, wallReach) then
		return false, "wall"
	end
	if ClientSlide.IsSlideTackling() then
		return false, "active"
	end
	if not skipHazard and not (Mark.oilSlide and os.clock() - Mark.oilSlide.at < 0.6) then
		local kind, tEnter, tExit = Mark.slidePathHazard(root, dir, mult or math.max(0.4, CFG.TackleSpeed))
		if kind == "mine" then
			return false, "mine"
		elseif kind == "oil" then
			local hum0 = character:FindFirstChildOfClass("Humanoid")
			local airT = Mark.jumpAir()
			-- jump now, slide ~0.1 s later: airborne from about 0.12 to airT - 0.06 after the jump
			if hum0 and CharacterControllers.IsLanded(character, hum0) and 0.1 + tEnter >= 0.12 and 0.1 + tExit <= airT - 0.06 then
				if Mark.doJump("oilslide") then
					Mark.oilSlide = { at = os.clock(), dir = dir, mult = mult, target = target }
					logFile("oil slide", "jump first", "enter", string.format("%.2f", tEnter), "exit", string.format("%.2f", tExit), "air", string.format("%.2f", airT))
					return false, "oil-jump"
				end
			end
			return false, "oil"
		end
	elseif Mark.oilSlide and not skipHazard then
		return false, "oil-pending"
	end
	if next(Mark.hazEv) ~= nil then
		local O0 = wallRoot and wallRoot.Position or root.Position
		local hzEv = Mark.hazardHits(function(t)
			return O0 + dir * Mark.dumpTravel(t)
		end, 1.2)
		if hzEv and hzEv.kind == "blast" then
			return false, "blast"
		end
	end
	Mark.yieldKick()
	local hi = math.max(0.4, CFG.TackleSpeed)
	local mul = (type(mult) == "number") and math.clamp(mult, math.min(hi, CFG.TackleMinSpeed or 0.6), hi) or hi
	SlideTackle.SetSpeedMultiplier(mul)
	slideAim = dir
	slideAimUntil = os.clock() + C.TotalVelocityReleaseStartsAt
	origSetMove(character, dir, dir, true)
	ClientSlide.HandleInputBegan(Controls.CreateInput("Tackle"), false)
	SlideTackle.SetSpeedMultiplier(CFG.TackleSpeed)
	if ClientSlide.IsSlideTackling() then
		lastTackleAt = os.clock()
		-- the slide took the body: the chase / block order ends NOW, not before the game had accepted the input (a rejected
		-- slide used to drop the chase every frame)
		if Mark.moveStop then
			Mark.moveStop()
		end
		origSetMove(character, dir, dir, true)
		Mark.slideBend = bend and { at = os.clock(), a2 = bend.a2, t = Mark.bendT } or nil
		Mark.slideTrack = { at = os.clock(), O = root.Position, dir = dir, m = mul, bent = bend ~= nil, pc = Mark.slidePlanTc, tag = (type(target) == "table" and target.char) and "carrier" or "ball" }
		Mark.slideHome = (type(target) == "table" and target.char) and {
			at = os.clock(),
			last = os.clock(),
			char = target.char,
			root = target.root,
			mult = mul,
			turns = 0,
		} or nil
		local p = predict
		logFile(
			"tackle sent",
			"mult",
			string.format("%.2f", mul),
			"distSrv",
			p and string.format("%.2f", p.dist) or "-",
			"distLive",
			p and string.format("%.2f", p.distLive or 0) or "-",
			"delay",
			p and string.format("%.3f", p.delay or 0) or "-",
			"live",
			p and fmtV(p.livePos) or "-",
			"srv",
			p and fmtV(p.serverPos) or "-",
			"eta",
			p and p.eta and string.format("%.3f", p.eta) or "-",
			"spd",
			p and string.format("%.2f", p.spd or 0) or "-",
			"hit",
			p and fmtV(p.hit) or "-",
			"aim",
			fmtV(dir),
			"usLive",
			fmtV(root.Position),
			"iframe",
			p and string.format("%.2f", p.iframe or 0) or "-",
			"bend",
			bend and fmtV(bend.a2) or "-"
		)
		Log.pending[#Log.pending + 1] = {
			kind = "tackle",
			at = os.clock(),
			oid = liveOwnerId(),
			dist = p and p.dist,
			hit = p and p.hit,
			aim = dir,
			livePos = p and p.livePos,
			serverPos = p and p.serverPos,
			delay = p and p.delay,
			delta = p and p.delta,
			yaw = p and p.yaw,
		}
		return true, "sent"
	end
	slideAim = nil
	slideAimUntil = 0
	Mark.tackleRejectAt = os.clock()
	logFile("tackle reject", "aim", fmtV(dir), "mult", string.format("%.2f", mul), "state", Mark.stateLine(), "sinceLast", string.format("%.2f", os.clock() - lastTackleAt), "stamina", tostring(Mark.sprint.CanSpendStamina(SlideTackle.Constants.StaminaCost, true)), "kickCharge", tostring(ChargedKick.IsCharging and ChargedKick.IsCharging()), "dribbling", tostring(ClientDodge.IsDribbling()))
	return false, "game-reject"
end

-- Startup dash reads GetDirection every frame until handoff (StartupDashHandoffSeconds); the main dash direction is
-- locked at handoff (runSplitCFrameAction -> runCFrameAction gets a fixed Direction). Our GetDirection source is the
-- MoveCommand hook (slideAim), so re-aim slideAim at the carrier until handoff, at most the dump's assist turn rate
-- (SlideTackleInput u4 = 1.5*pi / HitboxDelaySeconds rad/s).
Mark.homeSlide = function(root)
	local bd = Mark.slideBend
	if bd then
		local el = os.clock() - bd.at
		if el >= bd.t and slideAim then
			slideAim = bd.a2
			Mark.slideBend = nil
			logFile("tackle bend", "turned at", string.format("%.2f", el), "to", fmtV(bd.a2))
		elseif el > 0.5 or not slideAim then
			Mark.slideBend = nil
		end
	end
	local h = Mark.slideHome
	if not h then
		return
	end
	local now = os.clock()
	local e = now - h.at
	local handoff = C.StartupDashHandoffSeconds
	if e >= handoff or not slideAim or not h.char or not h.char.Parent then
		if h.turns and h.turns > 0 then
			logFile("tackle home", "turns", tostring(h.turns), "e", string.format("%.2f", e))
		end
		Mark.slideHome = nil
		return
	end
	if e > 0.05 and not ClientSlide.IsSlideTackling() then
		Mark.slideHome = nil
		return
	end
	local p = CharacterMotion.GetPosition(h.char) or (h.root and h.root.Position)
	if typeof(p) ~= "Vector3" then
		return
	end
	local v = flat(CharacterMotion.GetVelocity(h.char) or Vector3.zero)
	if Dodge.IsDribbling(h.char) then
		local u = unitOrNil(v)
		v = u and u * math.min(v.Magnitude, Dodge.Constants.WalkSpeed) or v
	end
	local mid = Mark.slideBox()
	local done = h.mult * Mark.dumpTravel(e)
	local origin = root.Position
	local best, bestErr = nil, math.huge
	local t = math.max(C.HitboxDelaySeconds, e)
	local t1 = C.HitboxDelaySeconds + C.HitboxSeconds
	while t <= t1 + 1e-4 do
		local pred = p + v * (t - e)
		local d = flat(pred - origin).Magnitude
		local err = math.abs(d - (h.mult * Mark.dumpTravel(t) - done + mid))
		if err < bestErr then
			bestErr = err
			best = pred
		end
		t += 0.02
	end
	local want = best and unitOrNil(flat(best - origin))
	if not want then
		return
	end
	local dt = math.max(now - (h.last or h.at), 0)
	h.last = now
	local cur = unitOrNil(flat(slideAim)) or want
	local maxTurn = (1.5 * math.pi / C.HitboxDelaySeconds) * dt
	local ang = math.acos(math.clamp(cur:Dot(want), -1, 1))
	if ang <= maxTurn then
		slideAim = want
	else
		local turn = maxTurn
		if cur.Z * want.X - cur.X * want.Z < 0 then
			turn = -turn
		end
		slideAim = CFrame.fromAxisAngle(Vector3.yAxis, turn):VectorToWorldSpace(cur)
	end
	if ang > 0.02 then
		h.turns = (h.turns or 0) + 1
	end
end

local function note(kind, why)
	if kind == "t" then
		if why ~= lastDbgT then
			lastDbgT = why
			dbg("tackle", why)
		end
	elseif why ~= lastDbgD then
		lastDbgD = why
		dbg("dribble", why)
	end
end

local Shoot = { busy = false, gen = 0, last = -1e9 }

local function setShootWhy(why)
	if Shoot.why ~= why then
		Shoot.why = why
		dbg("shoot", why)
	end
end

local function sampleFlight(origin, velocity, spin, floorY, planePoint, planeNormal, tuning, doBounce)
	local pts = { origin }
	local times = { 0 }
	local pos, vel, sp = origin, velocity, spin or Vector3.zero
	local step = 0.09
	local t = 0
	local hit = nil
	local hitT = nil
	local bounced = 0
	local upN = Vector3.new(0, 1, 0)
	for stepI = 1, 40 do
		if stepI % 8 == 0 then
			Shoot.slice()
		end
		local prev = pos
		local np, nv, ns = Physics.GetAirFlight(pos, vel, sp, step, tuning)
		if typeof(np) ~= "Vector3" then
			break
		end
		pos = np
		vel = nv or vel
		sp = ns or sp
		t = t + step
		if t > 3.0 and not hit and bounced < 1 then
			break
		end
		if doBounce and bounced < 1 and pos.Y <= floorY and vel.Y < -0.5 then
			local drop = prev.Y - pos.Y
			local alpha = drop > 1e-4 and (prev.Y - floorY) / drop or 1
			alpha = math.clamp(alpha, 0, 1)
			pos = prev:Lerp(pos, alpha)
			pos = Vector3.new(pos.X, floorY + 0.02, pos.Z)
			local bouncedVel = Physics.BounceVelocity(vel, upN, nil, upN, tuning)
			if typeof(bouncedVel) == "Vector3" then
				vel = bouncedVel
			else
				vel = Vector3.new(vel.X, -vel.Y * 0.6, vel.Z)
			end
			bounced = bounced + 1
			pts[#pts + 1] = pos
			times[#times + 1] = t
		else
			local insertedHit = false
			if planePoint and planeNormal and not hit and (not doBounce or bounced >= 1) then
				local da = (prev - planePoint):Dot(planeNormal)
				local db = (pos - planePoint):Dot(planeNormal)
				if da * db <= 0 and math.abs(da - db) > 1e-4 then
					local alpha = da / (da - db)
					if alpha < 0 then
						alpha = 0
					elseif alpha > 1 then
						alpha = 1
					end
					hit = prev:Lerp(pos, alpha)
					hitT = t - step + step * alpha
					pts[#pts + 1] = hit
					times[#times + 1] = hitT
					insertedHit = true
				end
			end
			if not insertedHit then
				pts[#pts + 1] = pos
				times[#times + 1] = t
			end
			if hit then
				local depth = (hit - pos):Dot(planeNormal)
				if depth >= 4 or t - (hitT or t) >= 0.12 then
					break
				end
			elseif pos.Y <= floorY then
				break
			end
		end
	end
	return pts, hit or pts[#pts], hit ~= nil, times, hitT, bounced
end

local function wallBlocks(a, b, ignore)
	local parts = BarricadeStrikes.GetReplicatedBoundaryParts()
	if type(parts) ~= "table" then
		return false
	end
	local pad = Physics.BallRadius
	for i = 1, #parts do
		local part = parts[i]
		if typeof(part) == "Instance" and part:IsA("BasePart") then
			if ignore and (part == ignore or part:IsDescendantOf(ignore)) then
				continue
			end
			local half = part.Size * 0.5 + Vector3.new(pad, pad, pad)
			if Physics.GetSegmentOrientedBoxEnterAlpha(a, b, part.CFrame, half) then
				return true
			end
		end
	end
	return false
end

local function flightBlocked(pts, ignore)
	if not pts or #pts < 2 then
		return false
	end
	local parts = Mark.boundParts
	if not parts or os.clock() - (Mark.boundAt or 0) > 0.5 then
		parts = BarricadeStrikes.GetReplicatedBoundaryParts()
		Mark.boundParts = parts
		Mark.boundAt = os.clock()
	end
	-- replicated boundary parts + placed barricades (workspace.Misc.Items PlacedItemId=barricades); every segment
	-- (the old stride 3 skipped two of three ~11-stud segments, walls in between were invisible)
	local all = {}
	if type(parts) == "table" then
		table.move(parts, 1, #parts, 1, all)
	end
	if Mark.wallParts then
		local placed = Mark.wallParts()
		table.move(placed, 1, #placed, #all + 1, all)
	end
	parts = all
	-- the placed barricade MODELS themselves (any part, any size): a ball-radius spherecast along every segment.
	-- Boundary parts alone missed low floor-skimming DIPs into a barricade.
	local models = Mark.wallModels
	if models and #models > 0 then
		local sp = Mark.wallSphere
		if not sp or Mark.wallSphereFor ~= models then
			sp = RaycastParams.new()
			sp.FilterType = Enum.RaycastFilterType.Include
			sp.FilterDescendantsInstances = models
			Mark.wallSphere = sp
			Mark.wallSphereFor = models
		end
		local r = Physics.BallRadius
		for i = 2, #pts do
			local a, b = pts[i - 1], pts[i]
			local d = b - a
			if d.Magnitude > 0.05 and Workspace:Spherecast(a, r, d, sp) then
				return true
			end
		end
	end
	if #parts == 0 then
		return false
	end
	local pad = Physics.BallRadius
	for i = 2, #pts do
		local a, b = pts[i - 1], pts[i]
		local segHalf = (b - a).Magnitude * 0.5
		for j = 1, #parts do
			local part = parts[j]
			if typeof(part) == "Instance" and part:IsA("BasePart") then
				if not (ignore and (part == ignore or part:IsDescendantOf(ignore))) then
					local mid = (a + b) * 0.5
					if (part.Position - mid).Magnitude <= part.Size.Magnitude * 0.5 + segHalf + pad + 1 then
						local half = part.Size * 0.5 + Vector3.new(pad, pad, pad)
						if Physics.GetSegmentOrientedBoxEnterAlpha(a, b, part.CFrame, half) then
							return true
						end
					end
				end
			end
		end
	end
	return false
end

local function keeperSide(mid, lateral, allowAlly)
	local side, best, y = 0, 1e9, nil
	Mark.gkRoot = nil
	local function take(model, r)
		if not (model and r) or model == LocalPlayer.Character then
			return
		end
		local tagged = model:GetAttribute("ActiveGoalkeeper") == true
		local actor = Actors.GetFromCharacter(model)
		if not tagged and actor then
			local ch = Actors.GetCharacter(actor)
			tagged = ch and ch:GetAttribute("ActiveGoalkeeper") == true
		end
		if actor and actor ~= LocalPlayer and not allowAlly and sameTeam(actor) then
			return
		end
		local rel = flat(r.Position - mid)
		if not tagged then
			-- NPC / bot keepers may not carry ActiveGoalkeeper: anyone standing in the mouth area counts, but a tagged
			-- keeper always wins (fallback is ranked behind by +100)
			local okF = rel.Magnitude < 14 and math.abs(rel:Dot(lateral)) < 24
			if not okF then
				return
			end
			rel = rel
			if rel.Magnitude + 100 >= best then
				return
			end
			best = rel.Magnitude + 100
			side = rel:Dot(lateral)
			y = r.Position.Y
			Mark.gkRoot = r
			Mark.gkTag = false
			return
		end
		if (best >= 100 or rel.Magnitude < best) and rel.Magnitude < 40 then
			Mark.gkTag = true
			best = rel.Magnitude
			side = rel:Dot(lateral)
			y = r.Position.Y
			Mark.gkRoot = r
		end
	end
	for _, model in Mark.models() do
		local r = model:FindFirstChild("HumanoidRootPart")
		take(model, r)
	end
	local npcs = Workspace:FindFirstChild("Characters")
	npcs = npcs and npcs:FindFirstChild("NPCs")
	if npcs then
		for _, model in npcs:GetChildren() do
			if model:IsA("Model") then
				take(model, model:FindFirstChild("HumanoidRootPart"))
			end
		end
	end
	return side, y
end

local function shotLaunch(character, aim, reported, curve, launchPos)
	if not (character and aim) then
		return nil
	end
	local preview = Mark.pathPreview or require(Client.Gameplay.Actions.ChargePathPreview)
	Mark.pathPreview = preview
	local boundary = preview.GetChargeBoundaryWorld(LocalPlayer)
	local origin = launchPos or aim.Origin
	if origin and boundary and not (aim and aim.IsAirborne) then
		origin = Physics.GetContainedGroundPosition(origin, Physics.BallRadius, boundary) or origin
	end
	local kickDir = AimFacing.GetFlatDirection(aim.Direction)
	Shoot.solving = true
	local bound = if aim and aim.IsAirborne then nil else boundary -- was `and nil or`: always boundary, airborne shots got clamped
	local vel = ChargePathVelocity.Get(character, KickCore.Constants.MaximumChargeSeconds, "Shot", aim, origin, reported, kickDir, nil, bound, curve)
	Shoot.solving = nil
	if typeof(vel) ~= "Vector3" then
		return nil, origin
	end
	return vel, origin
end

local solveShotRaw
-- Time slicing. A full solve costs ~15-20 ms (log: shoot cost max 20.0ms) and ran every 0.12 s while we walk = a
-- frame hitch 8 times a second. Preview solves now run as a coroutine that yields inside packShot once the frame
-- slice (CFG.ShootSliceMs) is spent and resumes next frame; the old aim stays on screen meanwhile. Forced solves
-- (charge / release / G / flick) drop any running job and run synchronously: they need the exact current origin.
-- QUICK SOLVE. The full solve builds EVERY candidate (15-20 aimAndPack calls, 3-5 flight sims each, then validation and keeper
-- reach for all of them) and only then picks one by a weighted roll. On a weak device (10x the CPU time of a PC: 150-300 ms of
-- work) that is seconds before the first aim. The roll decides almost everything, so the roll goes FIRST: the enumeration runs
-- once in COLLECT mode (aimAndPack only records { h, side, curve, band } - zero simulations), the specs are put in a weighted
-- random order (Efraimidis-Spirakis keys, seeded by Shoot.roll so the same spot gives the same order), and they are solved one
-- by one until the first OPEN shot (the keeper cannot reach it in time). Weighted order + first feasible = weighted pick among
-- the feasible ones, the same distribution as the old pick, for 1-3 candidates instead of all.
-- SHOT WEIGHTS (AutoShoot > Shot Types > Weights). Key of a candidate for the user's weight: the lob is "chip", a "mid"
-- is "high", and a CURLED "high" (packHighCurves / the primary 0.85 curl into the top corner) is its own type "curl":
-- under one "high" key the user could not weigh the top-corner curl apart from the straight high shot, and the
-- per-family pick (cornerGap) always kept the curl (it ends closer to the corner) - "corners even at 0 %".
Mark.shotWKey = function(p)
	if p.lob then
		return "chip"
	end
	local b = p.band or ""
	if b == "mid" then
		b = "high"
	end
	if b == "high" and type(p.curve) == "number" and math.abs(p.curve) > 0.05 then
		return "curl"
	end
	return b
end
Mark.shotUserW = function(p)
	local sw = CFG.ShotWeight
	local w = sw and sw[Mark.shotWKey(p)]
	return type(w) == "number" and w or 1
end
-- any slider moved off 100 %: the user's mix replaces the built-in family preferences (curve x4..8 / straight x0.08 /
-- "only curled when a curl exists" / "only types within 0.15 s of the most open one"). Those were hard filters in
-- front of the weighted roll, so the weights only ever chose between corner curls.
Mark.shotMixCustom = function()
	local sw = CFG.ShotWeight
	if type(sw) ~= "table" then
		return false
	end
	for _, v in sw do
		if type(v) == "number" and math.abs(v - 1) > 0.01 then
			return true
		end
	end
	return false
end

Mark.quickPrior = function(sp, c)
	local band = sp.band or ""
	local w = (c.typeW[band] or 0.6) * Mark.shotUserW(sp)
	local userMix = c.userMix
	local s = sp.side
	local ap = c.approach
	if math.abs(ap) > 6 then
		local tight = math.clamp((math.abs(ap) - 6) / 10, 0, 1)
		w *= (s * ap > 0) and (1 - 0.75 * tight) or (1 + 0.8 * tight)
	end
	if math.abs(c.keeper) > 1.5 then
		w *= (s * c.keeper > 0) and 0.45 or 1.4
	end
	if s * c.openSign > 1.5 then
		w *= 1.6
	elseif s * c.openSign < -1.5 then
		w *= 0.7
	end
	if sp.curve then
		if math.abs(s) >= 2 then
			local onRight = s * c.rightDot >= 0
			if (onRight and sp.curve > 0) or (not onRight and sp.curve < 0) then
				return 0.001 -- the curl would bend away from the aim side (the old weigh() veto)
			end
		end
		if not userMix then
			w *= 4 + c.farW * 4
		end
	elseif c.haveCurves and band ~= "flat" and not userMix then
		w *= 0.08
	end
	local hist = Mark.shotHist
	if hist then
		local ps = s >= 0 and 1 or -1
		for hi = 1, #hist do
			local hh = hist[hi]
			if hi > #hist - 3 and hh.band == sp.band then
				w *= 0.55
				if hh.side == ps then
					w *= 0.8
				end
			end
		end
	end
	if sp.tier == 2 then
		w *= 0.12 -- the old "only when the pool is empty" families
	end
	return w
end

Mark.quickShot = function(c)
	local items = {}
	for i = 1, #c.specs do
		local sp = c.specs[i]
		local u = math.clamp((c.roll * (11.17 + i * 7.31) + i * 0.6180339) % 1, 1e-3, 1 - 1e-3)
		items[i] = { sp = sp, key = u ^ (1 / math.max(Mark.quickPrior(sp, c), 1e-3)) }
	end
	table.sort(items, function(a, b)
		return a.key > b.key
	end)
	local slow = (Mark.dtAvg or 0) > 0.028
	local maxTry, simMax = slow and 4 or 6, slow and 10 or 16
	local tried, openN = 0, 0
	Shoot.sims = 0
	for k = 1, #items do
		if tried >= maxTry or (Shoot.sims or 0) >= simMax then
			break
		end
		local sp = items[k].sp
		local n0 = #c.pool
		c.aimAndPack(sp.h, sp.side, sp.curve, sp.band, sp.fromBall)
		tried += 1
		for j = n0 + 1, #c.pool do
			local p = c.pool[j]
			if c.reachMargin(p) >= CFG.ShotReachMargin and c.weigh(p) > 0 then
				openN += 1
			end
		end
		if openN >= 1 then
			break
		end
	end
	return tried, openN
end

Shoot.slice = function()
	-- budget per frame; halved when the frame is already slow (Heartbeat dt > 12.5 ms = under 80 fps)
	if Shoot.inJob then
		-- A full solve costs ~15-20 ms. The per-frame slice (halved under 80 fps) is fine at 100+ fps, but at 30 fps
		-- 10 frames x 0.45 ms never add up: the job went stale at 0.35 s and restarted forever (tester log: "shoot solving"
		-- all session, no "shoot start", AutoShoot dead). The budget now grows so the job lands in ~0.25 s at any fps.
		local base = (CFG.ShootSliceMs or 0.9) * (Shoot.sliceBoost or 1) * ((Mark.dt or 0) > 0.0125 and 0.5 or 1)
		local framesLeft = math.max(0.25 / math.max(Mark.dtAvg or 0.017, 0.004), 1)
		local need = (Shoot.fullCost or 15) / framesLeft
		if os.clock() - Shoot.sliceAt > math.clamp(math.max(base, need), base, 6) / 1000 then
			coroutine.yield()
		end
	end
end
local function solveSliced(root, forced)
	if forced == "async" then
		if Shoot.job then
			Shoot.jobForced = true -- a running preview job becomes the forced one (its origin is still fresh)
		else
			Shoot.jobForced = true
		end
		forced = false
	elseif forced then
		Shoot.job = nil
		Shoot.inJob = false
		return solveShotRaw(root, true)
	else
		Shoot.jobForced = Shoot.jobForced and Shoot.job ~= nil
	end
	if Shoot.job and (os.clock() - Shoot.jobAt > ((Mark.dtAvg or 0) > 0.025 and 0.6 or 0.35) or (Shoot.jobArgs and Shoot.jobArgs ~= root)) then
		if os.clock() - (Shoot.staleLog or 0) > 3 then
			Shoot.staleLog = os.clock()
			logFile("shoot", "job stale", string.format("%.2f", os.clock() - Shoot.jobAt), "cost", string.format("%.1f", Shoot.jobMs or 0), "full", string.format("%.1f", Shoot.fullCost or 15))
		end
		Shoot.job = nil -- origin went stale before the job finished: start over from the current pose
		Shoot.jobMs = 0
	end
	if not Shoot.job then
		Shoot.fullPass, Shoot.collect = nil, nil
		Shoot.job = coroutine.create(solveShotRaw)
		Shoot.jobArgs = root
		Shoot.jobAt = os.clock()
	end
	Shoot.inJob = true
	Shoot.sliceAt = os.clock()
	local boost = Shoot.jobForced and 2.2 or 1
	Shoot.sliceBoost = boost
	local ok, a, b, c, d = coroutine.resume(Shoot.job, Shoot.jobArgs, Shoot.jobForced == true)
	Shoot.inJob = false
	Shoot.jobMs = (Shoot.jobMs or 0) + (os.clock() - Shoot.sliceAt) * 1000
	if not ok then
		Shoot.job = nil
		Shoot.jobForced = false
		logFile("shoot", "job-err", tostring(a))
		return nil, nil, nil, "err"
	end
	if coroutine.status(Shoot.job) == "dead" then
		Shoot.fullCost = (Shoot.fullCost or 15) * 0.6 + math.clamp(Shoot.jobMs or 15, 2, 60) * 0.4
		Shoot.jobMs = 0
		Shoot.job = nil
		Shoot.jobFrames = 0
		Shoot.jobForced = false
		return a, b, c, d
	end
	-- still running: keep showing the previous result
	if Shoot.aim then
		return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
	end
	return nil, nil, nil, Shoot.lastWhy or "solving"
end
local function solveShot(root, forced, ...)
	local t0 = os.clock()
	local a, b, c, d = solveSliced(root, forced)
	local ms = (os.clock() - t0) * 1000
	if CFG.Perf then
		Mark.perfAdd(forced == "async" and "solve-async" or (forced and "solve-forced" or "solve-slice"), ms)
	end
	if ms > 0.3 then
		Shoot.costN = (Shoot.costN or 0) + 1
		Shoot.costSum = (Shoot.costSum or 0) + ms
		Shoot.costMax = math.max(Shoot.costMax or 0, ms)
	end
	if os.clock() - (Shoot.costLog or 0) > 3 and (Shoot.costN or 0) > 0 then
		Shoot.costLog = os.clock()
		logFile("shoot cost", string.format("n %d avg %.1fms max %.1fms memo %d warm %d full %.1f quick %d", Shoot.costN, Shoot.costSum / Shoot.costN, Shoot.costMax, Shoot.memoHit or 0, Shoot.warmHit or 0, Shoot.fullCost or 0, Shoot.quickN or 0))
		Shoot.costN, Shoot.costSum, Shoot.costMax, Shoot.memoHit, Shoot.warmHit, Shoot.quickN = 0, 0, 0, 0, 0, 0
	end
	return a, b, c, d
end
solveShotRaw = function(root, forced)
	Shoot.lob = nil
	local goal = enemyGoalPart()
	if not goal then
		Shoot.preview = nil
		return nil, nil, nil, "no goal"
	end
	local lb, lt, rb, rt, _, face = goalMouthCorners(goal)
	if not lb or not lt then
		Shoot.preview = nil
		return nil, nil, nil, "no mouth"
	end
	local bottom = (lb + rb) * 0.5
	local bar = (lt + rt) * 0.5
	local rise = bar - bottom
	local ball = Renderer.GetPosition() or Renderer.GetMainMatchPosition()
	local origin = ball or (root.Position + Vector3.new(0, 2, 0))
	local up = rise.Magnitude > 0.4 and rise.Unit or Vector3.new(0, 1, 0)
	local mouth = bottom + up * math.min(1.35, math.max(rise.Magnitude * 0.2, 1.2))
	local delta = mouth - origin
	local flatD = flat(delta)
	local dist = flatD.Magnitude
	Shoot.dist = dist
	if dist < 6 then
		Shoot.preview = nil
		Shoot.aim = nil
		Shoot.point = nil
		Shoot.curve = nil
		return nil, nil, nil, "too close"
	end
	if dist > (CFG.ShootMaxDist or 160) then
		Shoot.preview = nil
		Shoot.aim = nil
		Shoot.point = nil
		Shoot.curve = nil
		Shoot.wire = nil
		return nil, nil, nil, "far"
	end
	local forward = flatD.Unit
	local character = LocalPlayer.Character
	local reported = flat(root.AssemblyLinearVelocity)
	local lateral = unitOrNil(flat(rt - lt)) or Vector3.new(1, 0, 0)
	local radius = Physics.BallRadius
	local tuning = character and Physics.GetCharacterTuning(character) or nil
	local mouthHalf = flat(rt - lt).Magnitude * 0.5
	local mouthH = math.max(rise.Magnitude, 1)
	local post = mouthHalf - radius - 0.3 -- +0.3 inset: two shots in the log hit the post / bar
	local low = bottom + up * math.clamp(mouthH * 0.4, radius + 1.1, math.max(mouthH - radius - 0.8, radius + 1.1))
	local keeper = keeperSide(low, lateral, goal:FindFirstAncestor("Practice") ~= nil)
	Mark.gkAhead = Mark.gkRoot and (Mark.gkRoot.Position - bottom):Dot(face) or 0
	local function at(h, side)
		return bottom + up * h + lateral * side
	end
	local hum = character and character:FindFirstChildOfClass("Humanoid")
	local bicycle = Mark.forceBike or (hum and BicycleKick.CanBicycleKick(character, hum)) or false
	local wantBand = "high"
	Shoot.wantBand = wantBand
	local moved = Shoot.solveAt and (origin - Shoot.solveAt).Magnitude or 99
	if not forced and not Shoot.fullPass and Shoot.aim and Shoot.preview and moved < 0.2 and math.abs((Shoot.solveKeeper or 0) - keeper) < 2 then
		return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
	end
	local slowF = (Mark.dtAvg or 0) > 0.025
	if not forced and not Shoot.fullPass and Shoot.aim and Shoot.preview and moved < (slowF and 2.5 or 1.2) and os.clock() - (Shoot.solveT or 0) < (slowF and 0.3 or 0.12) then
		return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
	end
	-- Throttle. A failed solve left Shoot.aim nil, which bypassed both caches above: with a moving player keeper
	-- (keeper side changes -> cache miss) and an empty pool the full candidate set ran EVERY frame. Plain solves at
	-- most every 0.12 s (0.25 s after a failure), forced re-solves every 0.08 s. One-shot G / flick plans are exempt.
	do
		local nowS = os.clock()
		local oneShot = Mark.forceBike or Mark.aerialContact
		local gapS = forced and 0.08 or (Shoot.aim and 0.2 or 0.3)
		if not oneShot and not Shoot.fullPass and nowS - (Shoot.lastSolveAt or 0) < gapS then
			if Shoot.aim then
				return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
			end
			return nil, nil, nil, Shoot.lastWhy or "no vel"
		end
		Shoot.lastSolveAt = nowS
		Shoot.solveStart = nowS
	end
	if not Shoot.rollAt or (origin - Shoot.rollAt).Magnitude >= 4 then
		Shoot.roll = math.random()
		Shoot.fakeRoll = math.random()
		Shoot.fakeFirst = math.random()
		Shoot.bounceRoll = math.random()
		Shoot.rollAt = origin
	end
	local function inGoal(hit, crossed)
		if not (crossed and hit) then
			return false
		end
		local side = math.abs(flat(hit - low):Dot(lateral))
		local y = (hit - bottom):Dot(up)
		return side <= post and y >= 0.3 and y <= mouthH - radius
	end
	local function onKeeper(hit)
		if not hit then
			return true
		end
		local pointSide = flat(hit - low):Dot(lateral)
		if math.abs(pointSide) > post * 0.7 then
			return math.abs(pointSide - keeper) < 2
		end
		if math.abs(keeper) < 1.2 and math.abs(pointSide) < 3.2 then
			return true
		end
		return math.abs(pointSide - keeper) < 4.2
	end
	local pool = {}
	local fail = { vel = 0, cross = 0, block = 0, keeper = 0 }
	local stat = {}
	Mark.shotStat = stat
	Mark.shotFail = fail
	local function logFail()
		if os.clock() - (Shoot.failLog or 0) < 1.2 then
			return
		end
		Shoot.failLog = os.clock()
		logFile("shoot", "fail", "dist", string.format("%.0f", dist), "pool", tostring(#pool), "vel", tostring(fail.vel), "cross", tostring(fail.cross), "block", tostring(fail.block), "frame", tostring(fail.frame or 0), "keeper", tostring(fail.keeper), "bands", Mark.bandStat(stat))
	end
	local function holdShot()
		return Shoot.aim and (Shoot.locked or os.clock() - (Shoot.goodT or 0) < 0.5)
	end
	local approach = flat(origin - bottom):Dot(lateral)
	local shooterRight = Vector3.new(0, 1, 0):Cross(forward)
	shooterRight = shooterRight.Magnitude > 0.2 and shooterRight.Unit or lateral
	local rightDot = lateral:Dot(shooterRight)
	local nearSign = approach >= 0 and 1 or -1
	local farSign = -nearSign
	local angled = math.abs(approach) > 6
	Shoot.ang = approach
	local sides = { post, -post }
	local keeperSign = keeper > 1.2 and 1 or (keeper < -1.2 and -1 or 0)
	local awaySign = keeperSign ~= 0 and -keeperSign or farSign
	local flipSide = (Shoot.roll or 0.5) < 0.16
	local openSign = flipSide and -awaySign or awaySign
	local chargeSec = KickCore.Constants.MaximumChargeSeconds
	local start = origin
	if character then
		local Carry = Mark.carry or require(Modules.Ball.Carry)
		Mark.carry = Carry
		local launched = Carry.GetLaunchPosition(character, "Shot", nil, bicycle == true, 0)
		if typeof(launched) == "Vector3" then
			start = launched
		end
	end
	if Mark.volleyContact then
		-- legit volley / bicycle: shoot from the meet point of the incoming ball (tickVolley)
		start = Mark.volleyContact
	elseif Mark.aerial and Mark.aerialContact then
		-- planned airborne contact point from tickAerial (falling ball, after the no-touch apex)
		start = Mark.aerialContact
	elseif (Mark.flickAim or Mark.aerial) and character then
		Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
		local pop = Mark.flick.GetCharacterLaunch(character)
		if pop and typeof(pop.Position) == "Vector3" and typeof(pop.Velocity) == "Vector3" then
			local nt = Mark.flick.GetLaunchNoTouchSeconds(character) or 0.48
			local airPos = Physics.GetAirFlight(pop.Position, pop.Velocity, Vector3.zero, nt, tuning)
			if typeof(airPos) == "Vector3" then
				start = airPos
			end
		end
	end
	local cam = workspace.CurrentCamera
	local camPos = cam and cam.CFrame.Position or start
	local function serverAim(dir, curve, fromBall)
		local aimOrigin = fromBall and start or camPos
		if typeof(dir) ~= "Vector3" or dir.Magnitude < 0.2 then
			return nil, nil, start
		end
		local look = dir.Unit
		local aimTry = {
			Origin = aimOrigin,
			Direction = look,
			CameraCFrame = CFrame.lookAt(aimOrigin, aimOrigin + look),
			CameraFieldOfView = cam and cam.FieldOfView or nil,
			IsAirborne = bicycle == true or Mark.flickAim == true or Mark.aerial ~= nil,
		}
		local vel, launch = shotLaunch(character, aimTry, reported, curve, start)
		return aimTry, vel, launch or start
	end
	local function curveFor(side)
		if math.abs(side) < 2 then
			return (keeper * rightDot) >= 0 and 1 or -1
		end
		local onRight = side * rightDot >= 0
		return onRight and -1 or 1
	end
	local function packShot(dir, curve, bandName, fromBall)
		if (Shoot.sims or 0) >= (Shoot.simCap or 2) then
			return nil
		end
		curve = Mark.curveScale(curve)
		Shoot.slice()
		Shoot.sims = (Shoot.sims or 0) + 1
		local aimTry, vel, launch = serverAim(dir, curve, fromBall)
		local isBounce = type(bandName) == "string" and string.sub(bandName, 1, 6) == "bounce"
		local isDip = bandName == "trickLow" or bandName == "dipCorner"
		local floorOk = isBounce or isDip or bandName == "flat" or bandName == "corner" or bandName == "fake"
		-- downward launches are legal from the air (G contact point) and for the floor-skimming dip
		local downOk = floorOk or Mark.aerial ~= nil or Mark.flickAim == true or Mark.forceBike == true
		if typeof(vel) ~= "Vector3" or vel.Magnitude <= 40 or (vel.Y < 1 and not downOk) then
			fail.vel = fail.vel + 1
			return nil
		end
		local spinTry = ShootMod.GetSpin(character, vel, reported, curve, chargeSec) or Vector3.zero
		local pts, hitTry, crossed, timesTry, hitT, bouncedN
		-- Game physics (Physics.NewState -> GoalkeeperPrediction.GetAnyGoalCrossing / Physics.GetStateAtTime through the
		-- charge boundary world): exact entry into the goal box with floor bounces, rolling and world solids. Our old
		-- 0.09 s linear sampler crossed the plane a stud off near the frame and could not do floor contact at all.
		local gameSim = false -- (the GetAnyGoalCrossing generator returned no crossing for every candidate and was removed: the sampler is the generator, GetAnyGoalCrossing only validates in insert())
		local memo = nil
		if not gameSim then
			local skim = isBounce or isDip
			-- Flight memo. The flight is a pure function of (launch, vel, spin, floor mode, goal plane): a moving player
			-- keeper invalidated the solve cache every frame and re-simulated identical flights. Keeper-dependent
			-- scoring (reach, onKeeper, earlyIntercept) still runs fresh on every solve.
			local function q(v)
				return string.format("%.2f,%.2f,%.2f", v.X, v.Y, v.Z)
			end
			local key = q(launch) .. "|" .. q(vel) .. "|" .. q(spinTry) .. (skim and "s" or "a") .. q(bottom)
			local store = Shoot.flightMemo
			if not store or Shoot.flightMemoN > 900 then
				store = {}
				Shoot.flightMemo = store
				Shoot.flightMemoN = 0
			end
			memo = store[key]
			if memo then
				Shoot.memoHit = (Shoot.memoHit or 0) + 1
				pts, hitTry, crossed, timesTry, hitT, bouncedN = memo.pts, memo.hit, memo.crossed, memo.times, memo.hitT, memo.bounced
			else
				pts, hitTry, crossed, timesTry, hitT, bouncedN = sampleFlight(launch, vel, spinTry, skim and bottom.Y or (root.Position.Y - 4), bottom, face, tuning, skim)
				memo = { pts = pts, hit = hitTry, crossed = crossed, times = timesTry, hitT = hitT, bounced = bouncedN }
				store[key] = memo
				Shoot.flightMemoN += 1
			end
		end
		if isBounce and (bouncedN or 0) < 1 then
			fail.cross = fail.cross + 1
			return nil
		end
		if not crossed or not hitTry then
			fail.cross = fail.cross + 1
			return nil
		end
		local y = (hitTry - bottom):Dot(up)
		local heightU = y / mouthH
		local band = bandName or (y >= 7.75 and "high" or (heightU >= 0.45 and "mid" or "low"))
		local pack = {
			aim = aimTry,
			vel = vel,
			from = launch,
			pts = pts,
			land = hitTry,
			times = timesTry,
			crossT = hitT or (timesTry and timesTry[#timesTry]),
			spin = spinTry,
			curve = curve,
			target = hitTry,
			band = band,
			hFrac = heightU,
			gap = (bar - hitTry):Dot(up),
			side = flat(hitTry - low):Dot(lateral),
			inside = inGoal(hitTry, crossed),
			bounced = bouncedN or 0,
			gameChecked = gameSim,
			memo = memo,
			fineTop = memo and memo.fineTop,
		}
		local peakY = launch.Y
		for i = 1, #pts do
			if pts[i].Y > peakY then
				peakY = pts[i].Y
			end
		end
		pack.peakY = peakY
		return pack
	end
	local function earlyIntercept(pack)
		local gk = Mark.gkRoot
		if not (gk and pack and pack.pts and pack.times) then
			return false
		end
		local gpos = gk.Position
		local hitT = pack.crossT or 9
		for i = 1, #pack.pts do
			local t = pack.times[i] or 0
			if t >= hitT - 0.08 then
				break
			end
			local p = pack.pts[i]
			if (p - bottom):Dot(face) > 5 then
				local d = flat(p - gpos).Magnitude
				if d < 3.2 and p.Y < gpos.Y + 7 then
					return true
				end
			end
		end
		return false
	end
	local function postOverflow(pack)
		if not (pack and pack.curve and pack.pts and pack.crossT) then
			return 0
		end
		local extra = 0
		for i = 1, #pack.pts do
			local t = pack.times and pack.times[i] or 0
			if t + 1e-4 >= pack.crossT then
				local s = math.abs(flat(pack.pts[i] - low):Dot(lateral))
				if s > post - 0.05 then
					extra = math.max(extra, s - (post - 0.05))
				end
			end
		end
		return extra
	end
	-- The game's own on-target test (Shoot getOnTargetColor): Physics.NewState + GoalkeeperPrediction.GetAnyGoalCrossing
	-- through the charge boundary world. Exact physics incl. world solids, so bar/post bounces and walls fail here
	-- instead of in our 0.09 s linear samples.
	Mark.pathPreview = Mark.pathPreview or require(Client.Gameplay.Actions.ChargePathPreview)
	local chkWorld = Mark.pathPreview.GetChargeBoundaryWorld(LocalPlayer)
	if not chkWorld then
		local _, w = Renderer.GetMovementState()
		chkWorld = w
	end
	Mark.gkPredMod = Mark.gkPredMod or require(Modules.Gameplay.GoalkeeperPrediction)
	local gameOnTargetRaw
	local function gameOnTarget(pack)
		local m = pack.memo
		if m and m.game ~= nil and m.gameBand == pack.band then
			return m.game
		end
		local r = gameOnTargetRaw(pack)
		if m then
			m.game, m.gameBand = r, pack.band
		end
		return r
	end
	gameOnTargetRaw = function(pack)
		if pack.gameChecked then
			return true
		end
		if not (chkWorld and pack.from and pack.vel) then
			return true
		end
		local t0 = Workspace:GetServerTimeNow()
		local st = Physics.NewState(pack.from, pack.vel, Physics.BallRadius, t0, pack.spin or Vector3.zero)
		if type(st) ~= "table" then
			return true
		end
		st.LastKickerUserId = LocalPlayer.UserId
		local p, t, afterFloor = Mark.gkPredMod.GetAnyGoalCrossing(st, chkWorld, { goal }, t0, 3)
		if typeof(p) ~= "Vector3" then
			-- unreliable: the same call returned no crossing for every candidate when used as the generator
			return true
		end
		local dipish = pack.band == "trickLow" or pack.band == "dipCorner"
		local bounceish = pack.band == "bounceHigh" or pack.band == "bounceLow" or dipish
		if afterFloor and not bounceish then
			return false
		end
		if dipish and not afterFloor then
			Mark.dipWhy = "game-nofloor"
			return false
		end
		return true
	end
	-- Exact bar test: re-integrate the flight with Physics.GetAirFlight (same call as the sampler) at 0.02 s, then
	-- 0.004 s within a stud of the plane, and take the highest ball centre while the ball overlaps the plane
	-- (|depth| <= radius + 0.5). The 0.09 s chord + one-slope estimate let straight backspin shots (Magnus lift
	-- right at the line) pass under a bar they then hit.
	local function fineTop(pack)
		if pack.fineTop ~= nil then
			return pack.fineTop
		end
		if not (pack.from and pack.vel) or (pack.bounced or 0) > 0 then
			pack.fineTop = false
			return false
		end
		local pos, vel, sp = pack.from, pack.vel, pack.spin or Vector3.zero
		local top = nil
		local t = 0
		local limit = (pack.crossT or 2) + 0.3
		while t < limit do
			local depth = (pos - bottom):Dot(face)
			local dt = math.abs(depth) < radius + 4 and 0.004 or 0.02
			local np, nv, ns = Physics.GetAirFlight(pos, vel, sp, dt, tuning)
			if typeof(np) ~= "Vector3" then
				break
			end
			pos, vel, sp = np, nv or vel, ns or sp
			t += dt
			local d2 = (pos - bottom):Dot(face)
			if math.abs(d2) <= radius + 0.5 then
				local y = (pos - bottom):Dot(up)
				top = top and math.max(top, y) or y
			elseif d2 < -(radius + 0.5) then
				break
			end
		end
		pack.fineTop = top or false
		if pack.memo then
			pack.memo.fineTop = pack.fineTop
		end
		return pack.fineTop
	end
	-- DIP runs along the floor: anyone (not the keeper, reach model owns him) who can get his receive hitbox onto a
	-- low path sample before the ball does knocks it off. Time for him = reaction + run to (distance - body reach).
	local dipFoes = nil
	local function dipBlocked(pack)
		if not (pack.pts and pack.times) then
			return false
		end
		if not dipFoes then
			dipFoes = {}
			Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
			for _, model in Mark.models() do
				local actor = Actors.GetFromCharacter(model)
				local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
				if r and r ~= Mark.gkRoot then
					local s = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false)
					dipFoes[#dipFoes + 1] = { p = r.Position, v = flat(r.AssemblyLinearVelocity), s = s, name = actorName(actor) }
				end
			end
		end
		if #dipFoes == 0 then
			return false
		end
		local rcv = HitboxSettings.Receive
		local reachXZ = rcv.Size.X * 0.5 + radius
		local reachTop = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + radius + 1.5 -- small hop / stretch
		-- the foe has to see the kick (display delay + ping, ~0.1) and read a dipping ball, and nobody runs the straight
		-- line at full speed: 0.2 s / 100% made every low ball "blocked" in a crowd (log: dip:foe ... d4.6)
		local react = 0.32
		for i = 2, #pack.pts do
			local t = pack.times[i] or 0
			if pack.crossT and t >= pack.crossT then
				break
			end
			local q = pack.pts[i]
			if (q - bottom):Dot(face) > 2 then
				for _, f in dipFoes do
					local h = q.Y - f.p.Y
					if h <= reachTop then
						local guess = f.p + f.v * math.min(t, react)
						local need = math.max(flat(q - guess).Magnitude - reachXZ, 0)
						if need <= f.s * 0.85 * math.max(t - react, 0) then
							Mark.dipWhy = string.format("foe %s t%.2f d%.1f", tostring(f.name), t, flat(q - f.p).Magnitude)
							return true
						end
					end
				end
			end
		end
		return false
	end
	local function insert(pack)
		if not pack or not pack.inside then
			return false
		end
		-- Closed corner: a ball that crosses the plane at an angle and is moving back towards the centre came from OUTSIDE
		-- the post line, so its centre passes the post axis at (mouthHalf - |side|) * cos(angle), not at the plane distance
		-- the post inset (radius + 0.3) assumed. Log: side 16.0-16.3 (the inset limit) at 22-37 degrees hit the frame.
		if pack.pts and pack.land then
			local pts, k = pack.pts, #pack.pts
			for idx = 1, #pts do
				if pts[idx] == pack.land then
					k = idx
					break
				end
			end
			local d = pack.land - pts[math.max(k - 1, 1)]
			local dd = math.abs(d:Dot(face))
			local s = (pack.land - bottom):Dot(lateral)
			local dl = d:Dot(lateral)
			if dd > 0.05 and dl * s < 0 then
				local cosA = dd / math.sqrt(dd * dd + dl * dl)
				local c = (mouthHalf - math.abs(s)) * cosA
				if c < radius + 0.6 then
					Mark.cornerWhy = string.format("corner s %.1f ang %.0f clr %.2f", s, math.deg(math.acos(cosA)), c)
					fail.corner = (fail.corner or 0) + 1
					return false
				end
			end
		end
		local blocked
		local m = pack.memo
		if m and m.blockStamp == Mark.wallSig then
			blocked = m.blocked
		else
			blocked = pack.pts and flightBlocked(pack.pts, goal) or false
			if m then
				m.blocked, m.blockStamp, m.blockAt = blocked, Mark.wallSig, os.clock()
			end
		end
		if blocked then
			fail.block = fail.block + 1
			return false
		end
		if (pack.band == "trickLow" or pack.band == "dipCorner" or pack.band == "bounceLow") and dipBlocked(pack) then
			fail.foe = (fail.foe or 0) + 1
			return false
		end
		do
			local hb = pack.band
			if hb == "high" or hb == "trick" or hb == "airHigh" or hb == "mid" then
				local top = fineTop(pack)
				-- + what the last shots of this class proved: they flew HIGH by this much over what the solver predicted (Mark.calBias)
				local margin = (Mark.forceBike and 1.5 or 1.05) - (hb == "trick" and 0.3 or 0)
					+ Mark.calBias(Mark.shotClass(pack.curve, Mark.flickAim or Mark.aerial or Mark.flickStrike or Mark.forceBike))
				if top and mouthH - top < radius + margin then
					Mark.barWhy = string.format("fine %s %s top %.2f", hb, pack.curve and "spin" or "straight", mouthH - top)
					fail.bar = (fail.bar or 0) + 1
					return false
				end
			end
		end
		if not gameOnTarget(pack) then
			fail.frame = (fail.frame or 0) + 1
			return false
		end
		local bounceish = pack.band == "bounceHigh" or pack.band == "bounceLow"
		if bounceish or pack.band == "trickLow" or pack.band == "dipCorner" then
			local pointSide = flat(pack.land - low):Dot(lateral)
			local pad = bounceish and 1.2 or 2.2
			local gkY = Mark.gkRoot and Mark.gkRoot.Position.Y or 0
			local overDive = pack.land.Y - gkY > 7.75
			if not overDive and math.abs(pointSide - keeper) < pad then
				fail.keeper = fail.keeper + 1
				return false
			end
		elseif onKeeper(pack.land) then
			fail.keeper = fail.keeper + 1
			return false
		end
		if pack.curve and (pack.band == "trick" or pack.band == "trickLow") and not (pack.land and Mark.gkRoot and pack.land.Y - Mark.gkRoot.Position.Y > 7.75) and earlyIntercept(pack) then
			return false
		end
		pool[#pool + 1] = pack
		return true
	end
	local aimAndPackRaw
	local function aimAndPack(h, side, curve, band, fromBall)
		if Shoot.collect then
			-- collect pass of the quick solve: record the spec, simulate nothing (see Mark.quickShot)
			local sc = Shoot.collect
			sc[#sc + 1] = { h = h, side = side, curve = curve, band = band, fromBall = fromBall, tier = Shoot.collectTier or 1 }
			return false
		end
		-- slow frame rate (< ~36 fps / < ~50 fps): a smaller total sim budget and an early stop once the pool is big
		-- enough to pick from; a late, complete answer beats the perfect one that never arrives (tester: AutoShoot dead at 30 fps)
		local dtA = Mark.dtAvg or 0
		if (Shoot.sims or 0) >= (dtA > 0.028 and 36 or (dtA > 0.02 and 52 or 70)) then
			return false
		end
		if not forced and #pool >= (dtA > 0.028 and 5 or (dtA > 0.02 and 8 or 1e9)) then
			return false
		end
		-- bicycle launch: a curled floor shot breaks (curl + bounce), floor shots go straight there
		if Mark.forceBike and (band == "trickLow" or band == "dipCorner") then
			return false
		end
		local st0 = stat[band or "-"] or { 0, 0 }
		stat[band or "-"] = st0
		st0[1] += 1
		local n0 = #pool
		-- own sim budget per candidate: the shared cap was eaten by the first iterating candidates, later HIGH / TRICK
		-- calls got packShot = nil (high0/3, trick0/4 with no fail reason) and DIP won by being alone in the pool
		local capSaved = Shoot.simCap
		local dipB = band == "trickLow" or band == "dipCorner" or band == "trick"
		Shoot.simCap = (Shoot.sims or 0) + (dist > 70 and 7 or (dipB and 7 or 5))
		local res = aimAndPackRaw(h, side, curve, band, fromBall)
		Shoot.simCap = math.max(capSaved or 0, Shoot.sims or 0)
		if #pool > n0 then
			st0[2] += 1
		end
		return res
	end
	aimAndPackRaw = function(h, side, curve, band, fromBall)
		local aimSide = side
		-- Long range: the ball drops ~0.5 * g * (dist / v)^2 (ball gravity 100, shot ~120 st/s) before the plane. The
		-- correction started at h and climbed +1.2 per miss under a mouthH + 14 ceiling, so past ~80 studs no
		-- iteration ever reached the plane and the pool stayed empty. Pre-lift the aim point by the extra drop beyond
		-- 70 studs and scale the ceiling / miss step with it.
		local lift = 0
		if dist > 70 and band ~= "trickLow" and band ~= "dipCorner" then
			lift = 0.5 * 100 * ((dist / 120) ^ 2 - (70 / 120) ^ 2)
		end
		local ceilH = mouthH + 14 + lift * 1.5
		local aimH = h + lift
		-- Warm start. Every candidate converges its aim point by 3-5 full simulations; between two solves the ball moved a
		-- few studs and the converged correction is nearly the same, so it is the starting point now (usually one
		-- simulation instead of 3-5). Key: band, side, height, curl. Stale after 4 s or 12 studs of distance change.
		Shoot.warm = Shoot.warm or {}
		local wkey = string.format("%s|%s|%.0f|%.0f|%.2f|%s", band or "-", side >= 0 and "+" or "-", h, side, curve or 0, fromBall and "b" or "c")
		local warm = Shoot.warm[wkey]
		if warm and os.clock() - warm.at < 4 and math.abs(dist - warm.dist) < 12 then
			aimH = math.clamp(aimH + warm.dH, -16, ceilH)
			aimSide = side + warm.dS
			Shoot.warmHit = (Shoot.warmHit or 0) + 1
		end
		local last = nil
		local prevAim, prevLand = nil, nil
		local tight = math.abs(side) >= post * 0.8
		local function take(pack)
			if not (pack and pack.inside) then
				return false
			end
			local ly = (pack.land - bottom):Dot(up)
			if band == "high" and ly < 7.75 then
				pack.band = "mid"
				return insert(pack)
			end
			-- bar contact is judged by the game sim now (packShot): only keep the ball centre under the bar
			-- ball size at the bar: any sample within (radius + 1.5) of the goal plane whose centre is above
			-- bar - radius - margin touches the crossbar, even if the plane-crossing point itself is lower
			if (band == "high" or band == "trick" or band == "airHigh" or band == "bounceHigh") and pack.pts then
				-- TRICK is a dropping curl: v35 margin; the +0.3 of v36/v37 was for the straight HIGH shots that hit the bar
				-- and it closed the TRICK window (lo 9.0 .. hi bar - radius - 0.15 shrank under the bar check: trick0/N)
				local margin = (Mark.forceBike and 1.5 or 1.05) - (band == "trick" and 0.3 or 0)
				-- samples are ~11 studs apart: take the flight slope at the plane and the highest centre within
				-- +-(radius + 0.5) of the plane (a rising ball touches the bar just past the line)
				local k = #pack.pts
				for idx = 1, #pack.pts do
					if pack.pts[idx] == pack.land then
						k = idx
						break
					end
				end
				local prev = pack.pts[math.max(k - 1, 1)]
				local dd = math.abs((pack.land - prev):Dot(face))
				local slope = dd > 0.05 and ((pack.land - prev):Dot(up) / dd) or 0
				local topY = (pack.land - bottom):Dot(up) + math.max(slope, 0) * (radius + 0.5)
				if (mouthH - topY) < radius + margin then
					Mark.barWhy = string.format("%s top %.2f slope %.2f", band, mouthH - topY, slope)
					return false
				end
			end
			-- sampler error at the bar (0.09 s steps, ~11 studs) + bicycle launch uncertainty: keep a real margin
			if band == "high" and pack.gap and pack.gap < radius + (Mark.forceBike and 1.35 or 0.85) then
				return false
			end
			if band == "high" and math.abs(pack.side or 0) < post * 0.72 then
				return false
			end
			if band == "trick" then
				-- (old gate land.Y - keeperRootY > 7.75 left a ~0.1-stud window under the bar: TRICK never passed)
				if (pack.peakY or 0) < ly + 1.4 then
					Mark.trickWhy = string.format("peak %.1f ly %.1f", pack.peakY or 0, ly)
					return false
				end
				local lo = dist >= 58 and 7.8 or 8.8
				local hi = mouthH - radius - (Mark.forceBike and 1.5 or 0.75) - 0.05
				if ly < lo or ly > hi then
					Mark.trickWhy = string.format("win ly %.1f lo %.1f hi %.1f", ly, lo, hi)
					return false
				end
			end
			if band == "trick" and pack.gap and pack.gap < radius + (Mark.forceBike and 1.35 or 0.55) then
				return false
			end
			-- long range: the high curl may drop in wide of centre too
			-- TRICK is the central family now (user: "closer to the centre"): the old 0.45 / 0.8 let wide drops through
			if band == "trick" and math.abs(pack.side or 0) > post * (dist >= 55 and 0.5 or 0.32) then
				Mark.trickWhy = string.format("side %.1f", pack.side or 0)
				return false
			end
			-- trickLow (DIP): a curl driven into the floor, it skips up and enters low (game sim: entry after floor contact)
			if band == "trickLow" and (pack.bounced or 0) < 1 then
				Mark.dipWhy = string.format("nobounce vy%.0f", pack.vel and pack.vel.Y or -1)
				return false
			end
			if band == "trickLow" and (ly < 0.3 or ly > mouthH * 0.45) then
				Mark.dipWhy = string.format("h%.1f", ly)
				return false
			end
			-- DIP corner: same floor skim, but into the corner (open side, curl brings it in from outside the post)
			-- (the aim target is now post*0.92 - 0.5..1.2 inset, so the old |side| >= post*0.75 gate rejected the converged shot)
			if band == "dipCorner" and ((pack.bounced or 0) < 1 or ly < 0.3 or ly > mouthH * 0.45 or math.abs(pack.side or 0) < post * 0.62) then
				Mark.dipWhy = string.format("corner b%d h%.1f s%.1f", pack.bounced or 0, ly, pack.side or 0)
				return false
			end
			if band == "trickLow" and (math.abs(pack.side or 0) < post * 0.2 or math.abs(pack.side or 0) > post * 0.7) then
				Mark.dipWhy = string.format("side%.1f", pack.side or 0)
				return false
			end
			if band == "bounceHigh" and ly < 7.2 then
				return false
			end
			if band == "bounceLow" and (ly < 0.3 or ly > 5) then
				return false
			end
			if CFG.PreferCornerCurl and pack.curve and band ~= "trick" and math.abs(pack.side or 0) < post * 0.7 then
				return false
			end
			return insert(pack)
		end
			for _ = 1, ((curve or band == "trick" or band == "trickLow" or band == "dipCorner") and 5 or 3) + (lift > 0 and 2 or 0) do
			local point = at(aimH, aimSide)
			local org = fromBall and start or camPos
			local look = point - org
			if look.Magnitude < 1 then
				return false
			end
			local pack = packShot(look.Unit, curve, band, fromBall)
			if pack then
				-- the world point the ray was aimed THROUGH (+ where it started): lets Mark.rebaseAim keep the same
				-- shot geometry while the player moves between full re-solves
				pack.aimPoint = point
				pack.fromBall = fromBall
			end
			if not pack or not pack.land then
				if band == "trickLow" or band == "dipCorner" then
					-- no floor contact before the goal: drive it lower
					aimH = math.clamp(aimH - 2.5, -16, 3)
				else
					aimH = math.clamp(aimH + 1.2 + lift * 0.3, 0.6, ceilH)
				end
				continue
			end
			last = pack
			if take(pack) then
				Shoot.warm[wkey] = { dH = aimH - (h + lift), dS = aimSide - side, dist = dist, at = os.clock() }
				return true
			end
			local y = (pack.land - bottom):Dot(up)
			local err = side - pack.side
			local extra = pack.curve and band ~= "trick" and postOverflow(pack) or 0
			local sgn = side >= 0 and 1 or -1
			-- slope of landing side vs aim side from the last two sims (a curl and a floor skim do not map 1:1: with the
			-- fixed gain 1 the DIP candidates stalled at 6.8 / 15.9 from the target in 3-5 sims = the dip:corner/side rejects)
			local gain = 1
			if prevAim and math.abs(aimSide - prevAim) > 0.05 then
				local sl = (pack.side - prevLand) / (aimSide - prevAim)
				if sl > 0.25 and sl < 4 then
					gain = 1 / sl
				end
			end
			prevAim, prevLand = aimSide, pack.side
			aimSide = aimSide + err * gain
			if extra > 0 then
				aimSide = aimSide - sgn * extra
			end
			if band == "trick" then
				-- aim at the middle of the window take() accepts (lo 7.8 / 9.0 .. bar - radius - 0.15)
				local want = ((dist >= 58 and 7.8 or 8.8) + (mouthH - radius - (Mark.forceBike and 1.5 or 0.75) - 0.05)) * 0.5
				aimH = math.clamp(aimH + (want - y) * 0.65, 0.6, mouthH + 3.2 + lift * 1.5)
			elseif band == "trickLow" or band == "dipCorner" then
				if (pack.bounced or 0) < 1 then
					aimH = math.clamp(aimH - 2.5, -16, 3)
				else
					aimH = math.clamp(aimH + (1.6 - y) * 0.7, -16, 3)
				end
			elseif band == "high" or tight then
				-- no ceiling on the AIM point: a long shot drops, aiming above the bar is what lands it in the top corner
				-- h sits inside the accept window: full-gain correction converges onto it
				aimH = math.clamp(aimH + (h - y), 0.6, ceilH)
			end
		end
		return take(last)
	end
	if character then
		-- 0.25 under the old target: server flight scatter put gap-1.6 shots on the bar (log: dist 76, gap 1.6, band high)
		-- target INSIDE the acceptance window: the old target (gap 1.35) sat under the reject line (radius + 0.85,
		-- bicycle radius + 1.35) so the correction converged onto rejects (G log: high0/3, bar:high top 1.6)
		local topH = mouthH - radius - (Mark.forceBike and 2.2 or 1.6)
		local curveH = topH - Mark.calBias("curve")
		local dipH = -4 -- aim point below the goal line: the curl hits the floor first (see take trickLow)
		local dipS = post * 0.45
		local function straightSide(sideSign)
			local closed = (sideSign * approach) > 0
			local add = 0.2
			if closed then
				add = add + math.clamp(math.abs(approach) * 0.12, 0, 1.2)
			else
				add = add + math.clamp(math.abs(approach) * 0.03, 0, 0.4)
			end
			return math.max(radius + 0.6, post - add)
		end
		local function curveWide(sideSign, amount)
			local add = 0.03 + math.abs(amount) * 0.06 + (dist >= 62 and 0.05 or 0) + (dist >= 70 and 0.05 or 0)
			if (sideSign * approach) > 0 then
				add = add + 0.05 + math.clamp(math.abs(approach) * 0.025, 0, 0.3)
			end
			return math.max(radius, post - add)
		end
		local amounts = (not Mark.flickAim and not Mark.aerial and not Mark.flickStrike) and CurvedKicks.IsEnabled() and dist > 16 and { 0.85, 0.65 } or nil
		local air = Mark.flickAim or Mark.aerial
		local far = dist >= 80
		Shoot.sims = 0
		Shoot.simCap = 8
		-- quick solve (see Mark.quickShot): collect the specs first. A full pass (after a quick miss, or when the last quick result
		-- was not an open shot) enumerates and simulates everything, exactly as before.
		Shoot.collect = nil
		if Shoot.fullPass then
			Shoot.fullPass = nil
		elseif CFG.ShootQuick ~= false and not Shoot.wantFull and not air and not Mark.flickStrike and not Mark.forceBike then
			Shoot.collect, Shoot.collectTier = {}, nil
		end
		Shoot.wantFull = nil
		local roll = Shoot.roll or 0
		local sign = roll > 0.72 and -openSign or openSign
		if air then
			-- from the airborne contact point: straight shots into the four corners first (downward launches allowed)
			Shoot.simCap = 24
			local airTop = topH - Mark.calBias("flick")
			aimAndPack(airTop, sign * post * 0.85, nil, "airHigh", true)
			aimAndPack(airTop, -sign * post * 0.85, nil, "airHigh", true)
			aimAndPack(1.6, sign * post * 0.85, nil, "airLow", true)
			aimAndPack(1.6, -sign * post * 0.85, nil, "airLow", true)
			if #pool == 0 then
				local depth = math.clamp(dist * 0.35, 8, 22)
				local band = roll < 0.45 and "bounceHigh" or "bounceLow"
				local aimFwd = unitOrNil(flat(bottom - start)) or forward
				local g = start + aimFwd * depth + lateral * sign * (post * 0.92)
				g = Vector3.new(g.X, bottom.Y + radius, g.Z)
				local look = g - start
				if look.Magnitude > 1 and look.Y < -0.08 then
					local pack = packShot(look.Unit, nil, band, true)
					if pack and pack.inside then
						insert(pack)
					end
				end
				if #pool == 0 and (Shoot.sims or 0) < 3 then
					local g2 = start + aimFwd * math.clamp(depth + 8, 12, 28) + lateral * -sign * (post * 0.92)
					g2 = Vector3.new(g2.X, bottom.Y + radius, g2.Z)
					local look2 = g2 - start
					if look2.Magnitude > 1 and look2.Y < -0.08 then
						local pack2 = packShot(look2.Unit, nil, band == "bounceHigh" and "bounceLow" or "bounceHigh", true)
						if pack2 and pack2.inside then
							insert(pack2)
						end
					end
				end
			end
		else
			local band = Shoot.wantBand or "high"
			local h = mouthH - radius - 0.3 - Mark.calBias(amounts and "curve" or "straight")
			local curve = amounts and (0.85 * curveFor(sign * post)) or nil
			local sideAmt = post * 0.92
			if band == "trickLow" and amounts then
				h = dipH
				sideAmt = dipS
			elseif band == "trick" and amounts then
				h = math.clamp(mouthH * 0.72, 7.2, mouthH - radius - 0.2)
				sideAmt = post * 0.2
			elseif band == "corner" and amounts then
				h = 1.2
				curve = 0.65 * curveFor(sign * post)
				sideAmt = post * 0.94
			elseif not amounts then
				band = "high"
				curve = nil
			end
			aimAndPack(h, sign * sideAmt, curve, band, false)
			if amounts and (Shoot.sims or 0) < (Shoot.simCap or 8) then
				aimAndPack(dipH, -sign * dipS, 0.85 * curveFor(-sign * post), "trickLow", false)
			end
			if #pool == 0 and (Shoot.sims or 0) < 5 then
				Shoot.collectTier = 2
				local alt = (band == "trickLow" or band == "corner") and "high" or "trickLow"
				aimAndPack(alt == "trickLow" and dipH or topH, -sign * (alt == "trickLow" and dipS or post * 0.92), amounts and (0.85 * curveFor(-sign * post)) or nil, alt, false)
			end
		end
		if #pool == 0 then
			Shoot.sims = 0
			Shoot.simCap = 4
		else
			-- the primary pair found shots: still give the high TRICK curls their own sims (they were starved: cap 0)
			Shoot.simCap = (Shoot.sims or 0) + ((amounts and not air) and 6 or (air and 10 or 0))
		end
		local function packHighCurves(amount)
			if not amounts then
				return
			end
			for s = 1, #sides do
				local sign = sides[s] >= 0 and 1 or -1
				local cw = curveWide(sign, amount)
				if cw then
					aimAndPack(curveH, sign * cw, amount * curveFor(sign * post), "high", false)
				end
			end
		end
		if not air then
			if amounts then
				local tSign = openSign
				local trickH = math.clamp(mouthH * 0.72, 7.2, mouthH - radius - 0.2)
				local trickBend = 0.85 * curveFor(tSign * post)
				-- DIP corner into the open side (the far side from a tight angle / away from the keeper)
				-- DIP corner: 0.5 further from the post, and more when the corner is CLOSED for us (we stand on the same
				-- side as the target corner: the ball runs along the post line; log: DIP hit the post from that side)
				local dipInset = 0.5 + 0.7 * math.clamp(openSign * approach / 15, 0, 1)
				aimAndPack(dipH, openSign * math.max(post * 0.92 - dipInset, post * 0.5), 0.85 * curveFor(openSign * post), "dipCorner", false)
				if dist >= 55 then
					-- long range: launched over the bar height, the curl drops it into the upper part wide of centre
					aimAndPack(mouthH + 2, tSign * post * 0.36, trickBend, "trick", false)
					aimAndPack(mouthH + 2, -tSign * post * 0.36, -trickBend, "trick", false)
				end
				aimAndPack(trickH, tSign * post * 0.2, trickBend, "trick", false)
				aimAndPack(math.min(trickH + 2.4, mouthH + 1.5), -tSign * post * 0.15, -trickBend, "trick", false)
			end
			packHighCurves(0.85)
			if amounts then
				for s = 1, #sides do
					local sign = sides[s] >= 0 and 1 or -1
					aimAndPack(dipH, sign * dipS, 0.85 * curveFor(sign * post), "trickLow", false)
				end
			end
			if #pool == 0 then
					Shoot.collectTier = 2
					if not amounts then -- the trickLow pass above only ran with amounts
						for s = 1, #sides do
							local sign = sides[s] >= 0 and 1 or -1
							aimAndPack(dipH, sign * dipS, 0.85 * curveFor(sign * post), "trickLow", false)
						end
					end
					for s = 1, #sides do
						local sign = sides[s] >= 0 and 1 or -1
						local cw0 = curveWide(sign, 0.65)
						if cw0 then
							aimAndPack(1.2, sign * cw0, 0.65 * curveFor(sign * post), "corner", false)
						end
						end
						if not far or #pool == 0 then
					packHighCurves(0.65)
					for s = 1, #sides do
						local sign = sides[s] >= 0 and 1 or -1
						local sw = straightSide(sign)
						aimAndPack(topH, sign * sw, nil, "high", false)
						if dist < 28 then
							aimAndPack(0.9, sign * sw, nil, "flat", true)
						end
					end
				end
			end
		end
		Shoot.collectTier = nil
		if Mark.flickAim or Mark.aerial or Mark.forceBike then
			local fwd = unitOrNil(flat(bottom - start))
			-- floor-bounce shots get their own sims (they were starved by the shared cap)
			Shoot.simCap = (Shoot.sims or 0) + 22
			if fwd then
				-- Floor ricochets, scanned relative to the distance (old fixed 5..46-stud floor points bounced most shots
				-- far short of a 50+ stud goal: second floor contact, no crossing). Straight only (curl + bounce breaks).
				-- Entry height decides the label: upper half bounceHigh, lower part bounceLow.
				local gDist = flat(bottom - start).Magnitude
				-- The game lifts every shot (aim -0.09 -> launch vdir +0.31 in the log), so a floor point aimed from the
				-- ball never gets hit (bounce0/18, all c). Aim the camera ray below the goal line like DIP: the scan
				-- over aim depth finds where the lifted shot lands short of the goal and skips in. Straight only.
				local function packBounces(towardSign)
					local offsets = { towardSign * post * 0.8, -towardSign * post * 0.8 }
					for _, aimDown in { -3, -6, -9, -13, -18 } do
						for o = 1, #offsets do
							local point = at(aimDown, offsets[o])
							local look = point - camPos
							if look.Magnitude > 1 then
								local pack = packShot(look.Unit, nil, "bounceLow", false)
								local sb = stat.bounce or { 0, 0 }
								stat.bounce = sb
								sb[1] += 1
								if pack and pack.inside and (pack.bounced or 0) >= 1 then
									local ly = (pack.land - bottom):Dot(up)
									local ok = false
									if ly >= mouthH * 0.55 and (mouthH - ly) >= radius + (Mark.forceBike and 1.35 or 0.85) then
										pack.band = "bounceHigh"
										ok = insert(pack)
									elseif ly >= 0.3 and ly <= mouthH * 0.45 then
										ok = insert(pack)
									end
									if ok then
										sb[2] += 1
									end
								end
							end
						end
					end
				end
				local _ = gDist
				packBounces(openSign)
				if #pool == 0 then
					local farW = straightSide(openSign)
					local nearW = straightSide(-openSign)
					aimAndPack(topH, openSign * farW, nil, "high", true)
					aimAndPack(topH, -openSign * nearW, nil, "high", true)
				end
			end
		end
		if not air and dist <= 50 and #pool == 0 and not Shoot.collect then
		Mark.passMod = Mark.passMod or require(Modules.Actions.Pass)
		local lobTimes = { 0.22 }
		local lobSide = openSign * post
		local lobPoint = bottom + up * math.clamp(mouthH * 0.55, 4.5, topH - 2.2) + lateral * lobSide
		local lobDir = unitOrNil(flat(lobPoint - start))
		if lobDir then
			local lobAim = {
				Origin = start,
				Direction = lobDir,
				CameraCFrame = CFrame.lookAt(start, start + lobDir),
			}
			for i = 1, #lobTimes do
				local secs = lobTimes[i]
				local lobVel = Mark.passMod.GetVelocity(character, secs, "FreeLobPass", lobAim, nil, reported, nil)
				if typeof(lobVel) == "Vector3" and lobVel.Magnitude > 20 then
					local lobSpin = Mark.passMod.GetSpin(character, lobVel, "FreeLobPass", reported) or Vector3.zero
					local lobPts, lobHit, lobIn, lobFlight = sampleFlight(start, lobVel, lobSpin, root.Position.Y - 4, bottom, face, tuning)
					local prev = lobPts and lobPts[#lobPts - 1]
					local dropping = prev and lobHit and prev.Y > lobHit.Y + 0.6
					local gap = lobHit and (bar - lobHit):Dot(up) or 0
					if dropping and gap >= radius + 1.6 and not flightBlocked(lobPts, goal) and inGoal(lobHit, lobIn) then
						local y = (lobHit - bottom):Dot(up)
						pool[#pool + 1] = {
							aim = lobAim,
							vel = lobVel,
							from = start,
							pts = lobPts,
							land = lobHit,
							times = lobFlight,
							spin = lobSpin,
							curve = nil,
							target = lobHit,
							lob = true,
							chipSec = secs,
							band = "chip",
							hFrac = y / mouthH,
							gap = gap,
							side = flat(lobHit - low):Dot(lateral),
							inside = true,
						}
						break
					end
				end
			end
		end
		end
		Shoot.lobWhy = "no"
		for i = 1, #pool do
			if pool[i].lob then
				Shoot.lobWhy = "in"
				break
			end
		end
		local farW = math.clamp((dist - 28) / 55, 0, 1)
		local closeW = math.clamp((24 - dist) / 14, 0, 1)
		local userMix = Mark.shotMixCustom()
		local hasCurve = false
		for i = 1, #pool do
			if pool[i].curve then
				hasCurve = true
				break
			end
		end
		-- Keeper reach along the WHOLE flight (he sees the trajectory preview, so assume perfect read after a human
		-- reaction). For every flight sample before the goal plane: the fastest way he can touch it
		--   walk  : Receive hitbox (grounded) at Humanoid.WalkSpeed
		--   jump  : walk + rise, GoalkeeperAirReceive (Receiving.GetReceiveHitbox for an airborne keeper)
		--   dive  : GoalkeeperDive.GetCurveSecondsForTravel(gap - SaveReachStuds, GetDistance), height capped by
		--           GoalkeeperDiveAssist.GetReachableContactHeight and MaximumSaveHeight
		-- margin = min over samples (react + need - t). > 0: no sample is reachable in time.
		local diveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
		Mark.gkDiveMod = diveMod
		local assist = Mark.gkAssist
		if assist == nil then
			local assist = require(Modules.Actions.GoalkeeperDiveAssist)
			Mark.gkAssist = assist
		end
		local gkRoot = Mark.gkRoot
		local gkModel = gkRoot and gkRoot.Parent
		local gkHum = gkModel and gkModel:FindFirstChildOfClass("Humanoid")
		local gkWalk = gkHum and gkHum.WalkSpeed or 16
		if gkWalk < 8 then
			gkWalk = 16
		end
		local gkD = diveMod.Constants.Distance
		local gkActor = gkModel and Actors.GetFromCharacter(gkModel)
		if gkActor then
			local d = diveMod.GetDistance(gkActor)
			if type(d) == "number" then
				gkD = d
			end
		end
		local saveReach = diveMod.Constants.SaveReachStuds
		local maxSave = diveMod.Constants.MaximumSaveHeight
		local rcv = HitboxSettings.Receive
		local airR = HitboxSettings.GoalkeeperAirReceive
		local bodyR = rcv.Size.X * 0.5 + radius
		local groundTop = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + radius
		local airTop = airR.CFrameOffset.Y + airR.Size.Y * 0.5 + radius
		local jumpH = Mark.jumpH or 7.2
		local gkReact = CFG.GkReactSeconds
		local function reachMargin(p)
			if p.reach then
				return p.reach
			end
			if not (gkRoot and p.pts and p.times) then
				p.reach = 1
				return 1
			end
			local g0 = gkRoot.Position + flat(gkRoot.AssemblyLinearVelocity) * gkReact
			local hitT = p.crossT or math.huge
			local worst = math.huge
			for i = 1, #p.pts do
				local t = p.times[i] or 0
				if t > hitT + 0.02 then
					break
				end
				local q = p.pts[i]
				if (q - bottom):Dot(face) > -0.5 then
					local g = flat(q - g0).Magnitude
					local h = q.Y - gkRoot.Position.Y
					local walk = math.max(g - bodyR, 0) / gkWalk
					local need = math.huge
					if h >= -3 and h <= groundTop then
						need = walk
					elseif h > groundTop and h <= airTop + jumpH then
						need = walk + Mark.riseT(math.max(h - airTop + 0.5, 0.3))
					end
					if h >= -2 then
						-- dive from where he stands, or walk until the point is inside dive range and then dive
						local walkIn = math.max(g - (gkD + saveReach), 0) / gkWalk
						local curve = diveMod.GetCurveSecondsForTravel(math.clamp(g - saveReach, 0, gkD), gkD)
						local top = assist and assist.GetReachableContactHeight(curve, h) or maxSave
						if h <= math.min(top, maxSave) then
							need = math.min(need, walkIn + curve)
						end
					end
					worst = math.min(worst, gkReact + need - t)
				end
			end
			p.reach = (worst == math.huge) and 1 or worst
			return p.reach
		end
		local function weigh(p)
			if onKeeper(p.land) then
				return 0
			end
			local hitY = p.land and (p.land - bottom):Dot(up) or 0
			local hitSide = p.side or 0
			if p.curve and math.abs(hitSide) >= 2 then
				local onRight = hitSide * rightDot >= 0
				local same = (onRight and p.curve > 0) or ((not onRight) and p.curve < 0)
				if same then
					return 0
				end
			end
			if dist > 50 and hitY < 7.2 and not p.lob and not p.curve and p.band ~= "bounceLow" and p.band ~= "trickLow" then
				return 0
			end
			local w = 1
			if dist >= 50 and p.gap and p.gap < 2.2 then
				w = w * 0.2
			end
			if p.curve then
				w = w + 3 + farW * 4
			elseif hasCurve and not p.lob and p.band ~= "flat" and not userMix then
				return 0
			elseif hasCurve and dist > 40 then
				w = w * 0.08
			end
			if closeW > 0 and hitY > 7.75 and p.gap and p.gap < 1.6 then
				w = w + 8 * closeW
			end
			if math.abs(hitSide) < post * 0.55 and p.band ~= "trick" and p.band ~= "trickLow" then
				w = w * 0.22
			elseif math.abs(hitSide) > post * 0.78 then
				w = w + 18
			end
			if p.curve and p.band == "high" and math.abs(hitSide) > post * 0.75 then
				w = w + 12
				if math.abs(approach) > 10 and keeper * approach > 0 and hitSide * approach < 0 then
					w = w + (Shoot.roll > 0.42 and 16 or 5)
				end
			elseif math.abs(hitSide) > post * 0.9 and (hitY > 7.75 or hitY < 2.2) then
				w = w + 1.5
			end
			if CFG.PreferCornerCurl and p.curve and math.abs(hitSide) > post * 0.7 then
				w = w + 22
			end
			if p.band == "corner" and p.curve then
				w = w + 10
			end
			if hitY > 2.8 and hitY < 7.75 and p.band ~= "bounceLow" and p.band ~= "trickLow" and p.band ~= "trick" then
				w = w * 0.08
			end
			if hitSide * openSign > 1.5 then
				w = w + 16
			elseif hitSide * openSign < -1.5 and hitY < 8.2 then
				w = w * 0.32
			end
			if Shoot.lastSide and hitSide * Shoot.lastSide > 1.5 and hitSide * openSign < 0 then
				w = w * 0.7
			end
			if p.lob then
				w = w + ((Mark.gkAhead or 0) > 2 and 9 or 0.4)
			end
			if p.band == "flat" then
				w = w + (dist > 50 and 0 or 2)
			end
			if p.band == "trick" then
				w = w + 6
			end
			if p.band == "trickLow" then
				w = w + 5
			end
			if hitY > 7.75 then
				w = w + 6
			end
			if Shoot.band and p.band == Shoot.band and p.band ~= "high" and p.band ~= "trick" then
				w = w * 0.2
			end
			if p.band == "bounceHigh" then
				if angled and hitSide * nearSign > 1 then
					return 0
				end
				w = w + 22
				if hitSide * openSign > 0 then
					w = w + 10
				end
			end
			if p.band == "bounceLow" then
				w = w + 20
			end
			if p.band == "over" and math.abs(hitSide) < post * 0.8 then
				w = w * 0.15
			end
			return math.max(w, 0.05)
		end
		if Shoot.collect then
			local specs = Shoot.collect
			Shoot.collect = nil
			local tried, openN = Mark.quickShot({
				specs = specs, pool = pool, aimAndPack = aimAndPack, reachMargin = reachMargin, weigh = weigh, roll = Shoot.roll or 0,
				approach = approach, keeper = keeper, openSign = openSign, rightDot = rightDot, farW = farW, haveCurves = amounts ~= nil, userMix = userMix,
				typeW = { high = 1, airHigh = 1, dipCorner = 0.6, trickLow = 0.45, trick = 0.8, bounceHigh = 0.9, bounceLow = 0.9, corner = 0.65, airLow = 0.8 },
			})
			Shoot.quickN = (Shoot.quickN or 0) + 1
			if os.clock() - (Shoot.quickLog or 0) > 2 then
				Shoot.quickLog = os.clock()
				logFile("shoot quick", "specs", #specs, "tried", tried, "open", openN, "pool", #pool, "sims", Shoot.sims or 0, "ms", string.format("%.1f", (os.clock() - (Shoot.solveStart or os.clock())) * 1000))
			end
			if #pool == 0 then
				-- nothing valid among the first few: the full pass (every family, the chip lob, all the old fallbacks)
				logFile("shoot quick", "miss", "specs", #specs, "tried", tried, "sims", Shoot.sims or 0)
				Shoot.fullPass = true
				Shoot.lastSolveAt = 0
				return solveShotRaw(root, forced)
			end
			Shoot.wantFull = openN == 0 -- valid but not open: the next solve looks at everything
			hasCurve = false
			for i = 1, #pool do
				if pool[i].curve then
					hasCurve = true
					break
				end
			end
		end
		pool = Mark.shotFilter(pool)
		local weights = {}
		local pickFrom = pool
		if Mark.flickAim then
			local highs = {}
			local lows = {}
			for i = 1, #pool do
				if pool[i].band == "bounceHigh" then
					highs[#highs + 1] = pool[i]
				elseif pool[i].band == "bounceLow" then
					lows[#lows + 1] = pool[i]
				end
			end
			if #highs > 0 then
				pickFrom = highs
			elseif #lows > 0 then
				pickFrom = lows
			else
				local directs = {}
				for i = 1, #pool do
					if pool[i].band ~= "bounceHigh" and pool[i].band ~= "bounceLow" then
						directs[#directs + 1] = pool[i]
					end
				end
				pickFrom = directs
			end
		elseif CFG.OnlyTrick then
			local tricks = {}
			for i = 1, #pool do
				if pool[i].band == "trick" or pool[i].band == "trickLow" then
					tricks[#tricks + 1] = pool[i]
				end
			end
			if #tricks > 0 then
				pickFrom = tricks
			end
		elseif CFG.PreferCornerCurl then
			local wide = {}
			local bestS = -1
			local widest = {}
			for i = 1, #pool do
				local p = pool[i]
				if p.curve then
					local s = math.abs(p.side or 0)
					if (p.band == "high" or p.band == "corner") and s > post * 0.7 then
						wide[#wide + 1] = p
					end
					if s > bestS + 0.05 then
						bestS = s
						widest = { p }
					elseif s >= bestS - 0.05 then
						widest[#widest + 1] = p
					end
				end
			end
			pickFrom = #wide > 0 and wide or widest
			if #pickFrom == 0 then
				pickFrom = pool
			end
		else
			pickFrom = pool
		end
		-- weigh() vetoes (explicit 0: wrong-way curve, keeper body, ...). Among the rest keep the full 0.85 bend when
		-- such shots exist (one consistent hard curl), then keeper reach decides.
		local base, curled = {}, {}
		for i = 1, #pickFrom do
			weights[i] = weigh(pickFrom[i])
			Shoot.slice()
			reachMargin(pickFrom[i])
			if weights[i] > 0 then
				base[#base + 1] = pickFrom[i]
				if pickFrom[i].curve and math.abs(pickFrom[i].curve) >= 0.8 then
					curled[#curled + 1] = pickFrom[i]
				end
			end
		end
		if #base == 0 then
			base = pickFrom
		end
		if #curled > 0 and not (Mark.flickAim or Mark.aerial) and not userMix then
			base = curled
		end
		-- high or low, not mid: mid height is where the keeper's body and dive are
		do
			local hl = {}
			for i = 1, #base do
				local p = base[i]
				local y = p.land and (p.land - bottom):Dot(up) or 0
				if y >= mouthH * 0.6 or y <= mouthH * 0.35 then
					hl[#hl + 1] = p
				end
			end
			if #hl > 0 then
				base = hl
			end
		end
		local bestM, openN = -math.huge, 0
		for i = 1, #base do
			local m = base[i].reach or -math.huge
			bestM = math.max(bestM, m)
			if m >= CFG.ShotReachMargin then
				openN += 1
			end
		end
		-- one candidate per shot type (its best reach), every type within 0.15 s of the best stays in the roll:
		-- the reach model alone always crowned the same low type
		local band = {}
		local perBand = {}
		-- corner shots: the one that crosses closest to the corner (not one that bends in a stud short of it)
		local function cornerGap(p)
			local y = p.land and (p.land - bottom):Dot(up) or 0
			return math.max(post - math.abs(p.side or 0), 0) + math.max((mouthH - radius) - y, 0) * 0.5
		end
		for i = 1, #base do
			local p = base[i]
			local k = Mark.shotWKey(p) .. ((p.side or 0) >= 0 and "+" or "-")
			local cur = perBand[k]
			if not cur then
				perBand[k] = p
			elseif p.band == "high" or p.band == "corner" then
				if cornerGap(p) < cornerGap(cur) - 0.05 then
					perBand[k] = p
				end
			elseif (p.reach or -math.huge) > (cur.reach or -math.huge) then
				perBand[k] = p
			end
		end
		local floorM = bestM >= CFG.ShotReachMargin and math.max(CFG.ShotReachMargin, bestM - 0.15) or bestM - 0.15
		if userMix and bestM >= CFG.ShotReachMargin then
			floorM = CFG.ShotReachMargin -- every OPEN type is in the user's roll, not only the most open one
		end
		for _, p in perBand do
			if (p.reach or -math.huge) >= floorM then
				band[#band + 1] = p
			end
		end
		-- Side preference: the far side of a tight angle and the side away from the keeper are the open goal. The near
		-- corner from a tight angle is a sliver (curl overruns into the post) and sits next to the keeper.
		local famN = {}
		for i = 1, #band do
			local k = Mark.shotWKey(band[i])
			famN[k] = (famN[k] or 0) + 1
		end
		local function sideW(p)
			local s = p.side or 0
			local w = 1
			if math.abs(approach) > 6 then
				local tight = math.clamp((math.abs(approach) - 6) / 10, 0, 1)
				if s * approach > 0 then
					w *= 1 - 0.75 * tight
				else
					w *= 1 + 0.8 * tight
				end
			end
			if math.abs(keeper) > 1.5 then
				w *= (s * keeper > 0) and 0.45 or 1.4
			end
			-- shot-type mix: TRICK had two slots (both sides) and crowded everything else out
			-- each shot family gets a fixed share no matter how many side variants it has in the roll
			-- (DIP was 0.25 / 0.18 against HIGH 1.0: with the families' side variants that was ~5% of the shots, then the
			-- foe filter removed most of those; the user read the result as "always the same shot")
			local typeW = { high = 1, airHigh = 1, dipCorner = 0.6, trickLow = 0.45, trick = 0.8, bounceHigh = 0.9, bounceLow = 0.9, corner = 0.65, airLow = 0.8 }
			w *= (typeW[p.band or ""] or 0.6) / (famN[Mark.shotWKey(p)] or 1) * Mark.shotUserW(p)
			-- variety: what was used in the last shots is less likely again (same family x0.55 each, same family+side x0.8 more)
			local hist = Mark.shotHist
			if hist then
				local ps = s >= 0 and 1 or -1
				for hi = 1, #hist do
					local hh = hist[hi]
					local rec = hi > #hist - 3
					if rec and hh.band == p.band then
						w *= 0.55
						if hh.side == ps then
							w *= 0.8
						end
					end
				end
			end
			return w
		end
		table.sort(band, function(x, y)
			return (x.reach or 0) > (y.reach or 0)
		end)
		local totalW = 0
		for i = 1, #band do
			band[i].pickW = sideW(band[i])
			totalW += band[i].pickW
		end
		if userMix and #band > 0 then
			local parts = {}
			for i = 1, #band do
				parts[i] = string.format("%s%s:%.2f:%.0f%%", Mark.shotWKey(band[i]), (band[i].side or 0) >= 0 and "+" or "-", band[i].reach or -1, totalW > 0 and band[i].pickW / totalW * 100 or 0)
			end
			if Shoot.mixLogRoll ~= Shoot.roll then
				Shoot.mixLogRoll = Shoot.roll
				logFile("shoot mix", "roll", string.format("%.2f", Shoot.roll or 0), table.concat(parts, " "))
			end
		end
		if totalW > 0 then
			local r = (Shoot.roll or 0) * totalW
			for i = 1, #band do
				r -= band[i].pickW
				if r <= 0 then
					band = { band[i] }
					break
				end
			end
		end
		if #band == 0 then
			band = base
		end
		Shoot.reachOpen = bestM >= CFG.ShotReachMargin
		Shoot.reachN = string.format("%d/%d/%d", openN, #base, #pickFrom)
		local bi = math.clamp(math.floor((Shoot.roll or 0) * #band) + 1, 1, math.max(#band, 1))
		local best = band[bi]
		local picked = best
		-- FAKE: a flight through a teammate in front of goal (CFG.FakeShot). Rolled once per shot like Shoot.roll; when the
		-- normal pool is empty it is used as a fallback.
		Mark.fakeWhy = nil
		local banned = Mark.fakeBan()
		if banned then
			Mark.fakeWhy = "off: " .. banned
		elseif not (Mark.flickAim or Mark.aerial or Mark.flickStrike or Mark.forceBike) then
			local ctx = {
				Shoot = Shoot, start = start, camPos = camPos, bottom = bottom, face = face, lateral = lateral, low = low, up = up,
				radius = radius, post = post, mouthH = mouthH, packShot = packShot, root = root, goal = goal, world = chkWorld, fail = fail,
			}
			local order = {}
			-- Allowed Types: with both bounce families unchecked the Bounce FAKE (a bounce shot) is off too
			local sban = CFG.ShotBan
			local bounceOk = not (type(sban) == "table" and sban.bounceHigh and sban.bounceLow)
			if CFG.BounceFAKE ~= false and bounceOk and CFG.PriorityBounceFAKE then
				order[#order + 1] = { "b", true }
			end
			if CFG.FakeShot ~= false and CFG.PriorityFAKE then
				order[#order + 1] = { "f", (Shoot.fakeFirst or 0) < (CFG.FakeFirstChance or 0.85) }
			end
			if CFG.BounceFAKE ~= false and bounceOk and not CFG.PriorityBounceFAKE then
				order[#order + 1] = { "b", false }
			end
			if CFG.FakeShot ~= false then
				order[#order + 1] = { "f", picked == nil }
			end
			local notes = {}
			for _, o in order do
				ctx.force = o[2]
				local fp, why
				if o[1] == "b" then
					fp, why = Mark.bounceFake(ctx)
				elseif dist >= 12 then
					fp, why = Mark.fakeShot(ctx)
				end
				if why then
					notes[#notes + 1] = (o[1] == "b" and "bounce " or "mate ") .. why
				end
				if fp then
					picked, best = fp, fp
					break
				end
			end
			Mark.fakeWhy = table.concat(notes, " ; ")
			-- a FAKE that was meant to be found and was not: say why (throttled). A rolled-away attempt is not a failure.
			local found = picked and (picked.fake or picked.bfake)
			if not found and Mark.fakeWhy ~= "" and not Mark.fakeWhy:find("roll ", 1, true) and (not Mark.fakeFailAt or os.clock() - Mark.fakeFailAt > 1.5) then
				Mark.fakeFailAt = os.clock()
				logFile("shoot fake none", Mark.fakeWhy)
			end
		end
		Shoot.reachM = picked and picked.reach
		Shoot.keeperS = keeper
		Shoot.keeperTag = Mark.gkRoot and (Mark.gkTag and "tag" or "npc") or "none"
		if not picked then
			if holdShot() then
				return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
			end
			local bounceKeep = Shoot.aim and (Shoot.band == "bounceHigh" or Shoot.band == "bounceLow")
			if (Mark.keepAim or Mark.flickAim or Mark.aerial or Mark.flickStrike) and bounceKeep and Shoot.solveAt and (origin - Shoot.solveAt).Magnitude < 0.35 then
				return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
			end
			if Mark.flickAim or Mark.aerial or Mark.flickStrike then
				Shoot.aim = nil
				Shoot.curve = nil
				Shoot.preview = nil
				Shoot.solveT = os.clock()
				Shoot.solveVel = reported
				return nil, nil, nil, "no vel"
			end
			logFail()
			Shoot.preview = nil
			Shoot.point = nil
			Shoot.curve = nil
			Shoot.aim = nil
			Shoot.hold = nil
			Shoot.hFrac = nil
			Shoot.gap = nil
			Shoot.band = nil
			Shoot.shotName = nil
			Shoot.poolN = #pool
			Shoot.solveAt = origin
			Shoot.solveKeeper = keeper
			Shoot.solveT = os.clock()
			return nil, nil, nil, "no vel"
		end
		if not picked.inside then
			if holdShot() then
				return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
			end
			if Mark.keepAim and Shoot.aim and Shoot.solveAt and (origin - Shoot.solveAt).Magnitude < 0.35 then
				return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
			end
			logFail()
			Shoot.preview = nil
			Shoot.point = nil
			Shoot.curve = nil
			Shoot.aim = nil
			Shoot.poolN = #pool
			Shoot.solveAt = origin
			Shoot.solveKeeper = keeper
			Shoot.solveT = os.clock()
			return nil, nil, nil, "no vel"
		end
		Shoot.solveAt = origin
		Shoot.solveKeeper = keeper
		Shoot.solveT = os.clock()
		Shoot.solveVel = reported
		local aim = picked.aim
		local shown = picked.vel
		local kickDir = AimFacing.GetFlatDirection(aim.Direction) or forward
		local curve = picked.curve
		local spin = picked.spin
		local flight = picked.pts
		local hit = picked.land
		local times = picked.times
		if not picked.bfake and flightBlocked(flight, goal) then
			Shoot.preview = nil
			Shoot.point = nil
			Shoot.curve = nil
			return nil, nil, nil, "wall"
		end
		if not (flight and #flight >= 2) or not hit then
			Shoot.preview = nil
			Shoot.point = nil
			Shoot.curve = nil
			return nil, nil, nil, "frame"
		end
		Shoot.shotName = picked.lob and "LOB" or (picked.band == "flat" and "FLAT" or (picked.band == "trick" and "TRICK" or (picked.band == "trickLow" and "DIP" or (picked.band == "dipCorner" and "DIP CORNER" or (picked.band == "bounceHigh" and "HIGH" or (picked.band == "bounceLow" and "LOW" or (picked.curve and "SPIN" or "STRAIGHT")))))))
		if picked.fake or picked.bfake then
			Shoot.shotName = picked.bfake and "BOUNCE FAKE" or (picked.fakeCorner and "FAKE CORNER" or "FAKE")
			if not Mark.fakeLogAt or os.clock() - Mark.fakeLogAt > 0.8 then
				Mark.fakeLogAt = os.clock()
				logFile("shoot fake", Mark.fakeWhy or "-")
			end
		end
		Shoot.point = picked.target
		Shoot.lastSide = picked.side
		Shoot.hitSide = picked.side
		Shoot.lob = picked.lob == true
		Shoot.chipSec = picked.chipSec
		Shoot.launch = shown
		Shoot.sampleFrom = picked.from
		Shoot.kickDir = kickDir
		Shoot.face = face
		Shoot.barY = bar.Y
		Shoot.bicycle = bicycle
		Shoot.curve = curve
		Shoot.spin = spin
		Shoot.dist = dist
		Shoot.aim = aim
		Shoot.aimPoint = picked.aimPoint
		Shoot.aimFromBall = picked.fromBall
		Shoot.aimOrg0 = aim.Origin
		Shoot.aimDir0 = aim.Direction
		Shoot.aimBallAt = origin
		Shoot.goodT = os.clock()
		Shoot.hold = nil
		Shoot.hFrac = picked.hFrac
		Shoot.gap = picked.gap
		Shoot.band = picked.band
		Shoot.lastBand = picked.band
		Shoot.solveBand = Shoot.wantBand or picked.band
		Shoot.poolN = #pool
		Shoot.mouth = rise.Magnitude
		Shoot.preview = {
			pts = flight,
			times = times,
			duration = times and times[#times] or 0,
			spin = spin,
			land = hit,
			origin = origin,
			bar = bar,
			face = face,
			along = lateral,
			under = true,
		}
		return aim, kickDir, curve, nil
	end
	if holdShot() then
		return Shoot.aim, Shoot.kickDir, Shoot.curve, nil
	end
	logFail()
	Shoot.preview = nil
	Shoot.point = nil
	Shoot.curve = nil
	Shoot.aim = nil
	Shoot.poolN = 0
	Shoot.solveAt = origin
	Shoot.solveKeeper = keeper
	Shoot.solveT = os.clock()
	return nil, nil, nil, "no vel"
end

-- Re-base the solved aim onto where we are NOW. The full solve runs every 0.2-0.3 s (sliced), but the player keeps
-- moving: a stale ray lands the ball off by the distance walked (user: the ball flies over). Every solved shot keeps
-- the world point its ray passed through; each frame the ray is rebuilt from the current origin (camera, or the
-- ball for ball-origin shots) through that same point, and the preview start follows the player (landing fixed).
-- Free: one subtraction + normalise. Refused for aerial / flick / bicycle / locked strikes, for lobs, and when the
-- turn from the solved direction would exceed ~6 degrees (then the next solve owns it).
Mark.rebaseAim = function()
	local a, ap = Shoot.aim, Shoot.aimPoint
	if not (a and ap and Shoot.aimBallAt and Shoot.aimDir0) then
		return
	end
	if Mark.flickAim or Mark.aerial or Mark.flickStrike or Mark.forceBike or Shoot.lob or (Mark.shotLockUntil and os.clock() < Mark.shotLockUntil) then
		return
	end
	local ball = Renderer.GetPosition()
	local cam = workspace.CurrentCamera
	if not (ball and cam) then
		return
	end
	local org
	if Shoot.aimFromBall then
		org = Shoot.aimOrg0 + (ball - Shoot.aimBallAt)
	else
		org = cam.CFrame.Position
	end
	local d = ap - org
	if d.Magnitude < 3 then
		return
	end
	local dir = d.Unit
	if dir:Dot(Shoot.aimDir0) < 0.9945 then
		return
	end
	if (org - a.Origin).Magnitude < 0.02 and dir:Dot(a.Direction) > 0.99999 then
		return
	end
	Shoot.aim = {
		Origin = org,
		Direction = dir,
		CameraCFrame = CFrame.lookAt(org, org + dir),
		CameraFieldOfView = a.CameraFieldOfView,
		IsAirborne = a.IsAirborne,
	}
	Shoot.kickDir = AimFacing.GetFlatDirection(dir) or Shoot.kickDir
	if Shoot.preview then
		Shoot.preview.shift = ball - Shoot.aimBallAt
	end
	Shoot.rebased = os.clock()
end

-- We are the keeper: enemy slides do not stun / strip a keeper (server side; the keeper has no slide either), so the
-- dribble / dodge answers to tackles are wasted cooldowns and hijacked movement. Kicks and projectiles keep their own logic.
Mark.meKeeper = function()
	local ch = LocalPlayer.Character
	return ch ~= nil and MatchSettings.IsGoalkeeperCharacter(ch)
end

local function stepLogic()
	Mark.logicId = (Mark.logicId or 0) + 1
	Mark.volleyPending()
	dribbleWhy = "off"
	tackleWhy = "off"
	local character = LocalPlayer.Character
	local root = character and ActorTargeting.GetActorRoot(LocalPlayer)
	if not (character and root) then
		predict = nil
		ghostPos = nil
		dribbleDanger = nil
		dribbleWhy = "no char"
		tackleWhy = "no char"
		return
	end
	ghostPos, ghostDir = ourRewindPosition(root, nil), unitOrNil(flat(root.CFrame.LookVector))
	if Mark.tickGk and Mark.tickGk(character, root) then
		predict = nil
		dribbleDanger = nil
		-- an AutoBall / block / kick order left over from before we became keeper would keep steering us (GetMoveCommand
		-- returns move.dir while any mode is set): only the keeper's own modes survive
		local mm = Mark.move and Mark.move.mode
		if mm and mm ~= "gk" and mm ~= "dodge" then
			logFile("gk drop mode", mm)
			Mark.moveStop()
		elseif mm and not Mark.moveLive(Mark.move) then
			-- the keeper half of stepLogic never reaches moveTick: a stale keeper / dodge order was cleared nowhere
			logFile("move watchdog", mm, "keeper idle")
			Mark.moveStop()
		end
		Mark.dodgeTend(root)
		-- the keeper's kick (gkPress "kick"): its charge is run by the same tick as the field kick
		Mark.akTick(character, root)
		-- items / hazards are not field-player only: a keeper can hold a shotgun (SilentAim, AutoWall) and stand in oil
		if Mark.tickSkill then
			Mark.tickSkill(character, root)
		end
		if Mark.tickHazard then
			Mark.tickHazard(character, root)
		end
		if Mark.drawOil then
			Mark.drawOil(root)
		end
		return
	end
	Mark.homeSlide(root)


	if slideAim and os.clock() >= slideAimUntil then
		slideAim = nil
		if Mark.move.mode ~= "ball" and Mark.move.mode ~= "block" then
			origSetMove(character, Vector3.zero, Vector3.zero, false)
			if Mark.move.mode then
				Mark.moveStop()
			end
		end
	end
	-- A slide the player started by hand also burns SlideTackle.CooldownSeconds (3 s). lastTackleAt only knew our own slides:
	-- AutoTackle retried every frame for 3 s (log: "tackle reject" + block start/stop flapping, then it fired when the
	-- cooldown ended), and each retry called moveStop, which dropped the block.
	do
		local sliding = ClientSlide.IsSlideTackling()
		if sliding and not Mark.slideWasOn then
			Mark.slideStartAt = os.clock()
			if os.clock() - lastTackleAt > 0.5 then
				lastTackleAt = os.clock()
			end
		end
		Mark.slideWasOn = sliding
	end
	if Mark.slideBody() and not slideAim then
		if Mark.move.mode and Mark.move.mode ~= "block" then
			Mark.moveStop()
		end
		if not Mark.slideClearAt then
			Mark.slideClearAt = os.clock() + C.TotalVelocityReleaseStartsAt
		end
	end
	if Mark.slideClearAt and os.clock() >= Mark.slideClearAt then
		origSetMove(character, Vector3.zero, Vector3.zero, false)
		Mark.slideClearAt = nil
	end

	for i = #Log.pending, 1, -1 do
		local v = Log.pending[i]
		if os.clock() - v.at >= 0.8 then
			local nowOwner = liveOwnerId()
			local result
			if v.kind == "tackle" then
				if nowOwner == LocalPlayer.UserId then
					result = "HIT steal"
				elseif nowOwner == v.oid then
					result = "MISS still-them"
				else
					result = "scramble owner=" .. tostring(nowOwner)
				end
			else
				if nowOwner == LocalPlayer.UserId then
					result = "KEEP ball"
				else
					result = "LOST owner=" .. tostring(nowOwner)
				end
			end
			logFile(
				"verdict",
				v.kind,
				result,
				"distSrv",
				v.dist and string.format("%.2f", v.dist) or "-",
				"delay",
				v.delay and string.format("%.3f", v.delay) or "-",
				"delta",
				v.delta and string.format("%.2f", v.delta) or "-",
				"live",
				fmtV(v.livePos),
				"srv",
				fmtV(v.serverPos),
				"yaw",
				v.yaw and string.format("%.3f", v.yaw) or "-",
				"hit",
				fmtV(v.hit),
				"aim",
				fmtV(v.aim)
			)
			table.remove(Log.pending, i)
		end
	end

	local oid = liveOwnerId()
	local own = oid == LocalPlayer.UserId
	local tune = tackleTuning()
	ghostPos, ghostDir = ourRewindPosition(root, nil), unitOrNil(flat(root.CFrame.LookVector))
	if dribbleDanger and not ClientDodge.IsDribbling() then
		local lk = dribbleDanger.character and slideLock[dribbleDanger.character]
		if not lk and dribbleDanger.actor then
			local ch = Actors.GetCharacter(dribbleDanger.actor)
			lk = ch and slideLock[ch]
		end
		local elapsed = lk and ((lk.t0 and os.clock() - lk.t0) or lk.elapsed or dribbleDanger.elapsed)
		if not lk or (elapsed and elapsed > C.HitboxDelaySeconds + C.HitboxSeconds + 0.08) then
			dribbleDanger = nil
		end
	end

	if CFG.AutoDribble then
		if Mark.kickBoxLines then
			hideLines(Mark.kickBoxLines)
		end
		if not own then
			dribbleWhy = "no ball"
		elseif ClientDodge.IsDribbling() then
			dribbleWhy = "active"
		else
			local kt = Mark.kickThreat(root)
			Mark.drawKickBox(kt, root)
			local threat = nil
			if kt and kt.inside and kt.open then
				local ok, why = tryDribble()
				if not Mark.kickLog or os.clock() - Mark.kickLog > 0.4 then
					Mark.kickLog = os.clock()
					logFile("dribble kick", ok and "sent" or tostring(why), "e", string.format("%.2f", kt.elapsed), "d", string.format("%.1f", kt.dist), "name", actorName(kt.actor))
				end
				dribbleWhy = ok and "kick" or tostring(why)
			elseif kt and kt.facing > 0.8 and kt.dist <= 10 and CFG.AgentAddon and Mark.dribbleLeft() <= 0 and not Mark.aerial and Mark.moveSteer then
				-- dribble ready: walk into his kick box so the release lands on the iframe (speed boost)
				local to = unitOrNil(flat(kt.center - root.Position))
				if to then
					Mark.move.look = to
					Mark.move.pts = { root.Position, kt.center }
					Mark.move.born = Mark.move.born or os.clock()
					Mark.moveSteer(to, "walk")
					Mark.agentHold(true, "walk")
					Mark.kickWalkAt = os.clock()
					dribbleWhy = "kick into"
				end
			elseif not Mark.meKeeper() then
				threat = dribbleThreat(root)
			end
			if kt and (dribbleWhy == "kick" or dribbleWhy == "kick into") then
				-- handled by the kick branch this tick
			elseif not threat then
			dribbleWhy = "no threat"
			Mark.dodgeDone = nil
			if Mark.move.mode == "walk" and Mark.moveStop and os.clock() - (Mark.kickWalkAt or 0) > 0.3 then
				Mark.moveStop("walk")
			end
			else
				dribbleDanger = threat
				ghostPos = threat.ourPos
				if threat.fire and not Mark.aerial and not Mark.flickStrike then
						local used = false
						do
							local lk = threat.character and slideLock[threat.character]
							used = lk and (lk.usedDribble or lk.handled) and true or false
						end
						local dribbleReady = Mark.dribbleLeft() <= 0
					local ownBall = liveOwnerId() == LocalPlayer.UserId
					if ownBall and not threat.strong then
						dribbleWhy = "weak " .. tostring(threat.why or "")
					elseif ownBall and dribbleReady and CFG.AutoDribble then
						local ok, why = tryDribble()
						if ok then
							dribbleWhy = why or "kick"
						elseif CFG.AutoDodge and not Mark.dodgeDone and not used and Mark.dodgeSteer then
							logFile("dribble", why or "fail", "dodge instead")
							Mark.dodgeSteer(root, threat)
							dribbleWhy = "dodge"
						else
							dribbleWhy = why
						end
					elseif used then
						dribbleWhy = "handled"
					elseif CFG.AutoDodge and not Mark.dodgeDone and Mark.dodgeSteer then
						Mark.dodgeSteer(root, threat)
						dribbleWhy = dribbleReady and "dodge" or "dodge cd"
					end
				else
					dribbleWhy = "slide miss"
					if Mark.move.mode == "walk" and Mark.moveStop then
						Mark.moveStop("walk")
					end
				end
			end
		end
		note("d", dribbleWhy)
	end

	if CFG.AutoDodge and not own and not Mark.slideBody() and not slideAim and Mark.move.mode ~= "dodge" and Mark.dodgeSteer and not Mark.meKeeper() then
		local threat = dribbleThreat(root)
		if threat and threat.fire and not Mark.dodgeDone then
			dribbleDanger = threat
			Mark.dodgeSteer(root, threat)
		end
	end

	if CFG.AgentAddon and ClientDodge.IsDribbling() then
		local dir, phase, target = Mark.dribblePlan(root)
		if dir and Mark.moveSteer then
			if phase ~= Mark.dribblePhase then
				Mark.dribblePhase = phase
				logFile("dribble agent", phase, "dir", fmtV(dir), "dist", string.format("%.1f", flat(target - root.Position).Magnitude))
			end
			Mark.move.look = dir
			Mark.moveSteer(dir, "dribble")
			Mark.move.pts = { root.Position, target }
			Mark.move.born = Mark.move.born or os.clock()
		elseif Mark.move.mode == "dribble" and Mark.moveStop then
			Mark.moveStop("dribble")
		end
	else
		Mark.dribblePhase = nil
		if Mark.move.mode == "dribble" and Mark.moveStop then
			Mark.moveStop("dribble")
		end
	end

	if Mark.move.mode == "dodge" then
		if ClientDodge.IsDribbling() then
			if Mark.moveStop then
				Mark.moveStop("dodge")
			end
		elseif Mark.dodgeSteer then
			Mark.dodgeSteer(root, Mark.dodgeThreat or dribbleDanger)
		end
	end

	if Mark.flickStrike and os.clock() > Mark.flickStrike then
		Mark.flickStrike = nil
	end

	Mark.feintTick(own)
	Mark.spoofTick()
	Mark.faceTick(LocalPlayer.Character, ActorTargeting.GetActorRoot(LocalPlayer))
	if Mark.shotLockUntil and os.clock() < Mark.shotLockUntil then
		-- aerial / bicycle strike in flight: the aim solved at the press is the one the release sends; any re-solve
		-- from the moved ball (or the ownership flicker at contact) wiped Shoot.aim and the preview at the strike
		setShootWhy("lock")
	elseif CFG.AutoShoot and own then
		local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
		if charging and Shoot.aim then
			Shoot.locked = true
			local ballNow = Renderer.GetPosition() or root.Position
			-- bicycle: the hover moves the ball, a re-solve swapped the shot type between press and release
			if not Mark.forceBike and (not Shoot.solveAt or (ballNow - Shoot.solveAt).Magnitude > 0.4) then
				Mark.keepAim = true
				-- "async": same forced semantics (exact current origin, no cache) but run as a time-sliced job. The
				-- synchronous version cost 5-23 ms in ONE frame every time the dribbling ball moved 0.4 studs under
				-- the charge (perf log: solve-forced avg 4.8 max 23.2 = the strike hitch). The previous aim stays
				-- valid until the job lands (a few frames).
				local _, _, _, why = solveShot(root, "async")
				Mark.keepAim = false
				if why and os.clock() - (Shoot.goodT or 0) > 0.5 then
					Shoot.aim = nil
					Shoot.preview = nil
					Shoot.point = nil
					setShootWhy(why)
				else
					setShootWhy("lock")
				end
			else
				setShootWhy("lock")
			end
		elseif Mark.flickStrike or Mark.aerial then
			Shoot.locked = nil
			Mark.flickAim = true
			Mark.keepAim = true
			local _, _, _, why = solveShot(root, false)
			Mark.keepAim = false
			Mark.flickAim = false
			if why then
				setShootWhy(why)
			elseif Shoot.why ~= "lock" then
				setShootWhy("arm")
			end
		else
			Shoot.locked = nil
			local _, _, _, why = solveShot(root, false)
			if why then
				setShootWhy(why)
			elseif Shoot.why ~= "lock" then
				setShootWhy("arm")
			end
		end
		Mark.rebaseAim()
	elseif not own and not Mark.flickStrike then
		Shoot.preview = nil
		Shoot.locked = nil
		Shoot.wire = nil
		Shoot.curve = nil
		Shoot.dist = nil
		Shoot.point = nil
		Shoot.aim = nil
		Shoot.kickDir = nil
		Shoot.lob = nil
		Shoot.launch = nil
		if Shoot.why ~= "swap" then
			setShootWhy("no ball")
		end
	end

	if Shoot.faced then
		TurnControl.ReleaseAutoRotate("AimCharge")
		Shoot.faced = nil
	end

	if Mark.bfTrack then
		Mark.bfTrack()
	end
	if Mark.passTick and character and root then
		Mark.passTick(character, root)
	end
	Mark.manualTackle = nil
	if CFG.AutoTackle or CFG.ManualTackle then
		if own then
			predict = nil
			tackleWhy = "have ball"
		else
			local player, croot = enemyCarrier(oid)
			if not player then
				predict = nil
				tackleWhy = croot or "no enemy"
			else
				Mark.dribWatch()
				local cch = Actors.GetCharacter(player)
				local solved = solveIntercept(root, croot, cch, tune)
				predict = solved
				if not solved then
					tackleWhy = "far"
				elseif not solved.fire then
					tackleWhy = solved.wait or "outrun"
				elseif not CFG.AutoTackle then
					Mark.manualTackle = { aim = solved.aim, mult = solved.mult, char = cch, root = croot, at = os.clock() }
					tackleWhy = "manual ready"
				elseif Mark.tackleShield(player, cch, solved) then
					tackleWhy = "dribble"
				elseif (solved.conf or 1) < Mark.tackleNeed then
					tackleWhy = "unsure"
					if os.clock() - (Mark.confLogAt or 0) > 1 then
						Mark.confLogAt = os.clock()
						logFile("tackle unsure", "conf", string.format("%.2f", solved.conf or 0), "need", string.format("%.2f", Mark.tackleNeed), "drib", Mark.tackleDrib, "eta", string.format("%.2f", solved.eta or 0))
					end
				elseif CFG.TackleCompetitor and not Mark.competitorFree(root, croot.Position) and Mark.mateNear(croot.Position, CFG.TackleCompetitorRadius or 8) then
					tackleWhy = "mate"
				elseif Mark.kickCmd then
					tackleWhy = "kick"
				elseif Mark.move.mode == "dodge" and dribbleDanger and dribbleDanger.fire then
					tackleWhy = "dodge"
				else
					Mark.manualTackle = { aim = solved.aim, mult = solved.mult, char = cch, root = croot, at = os.clock() }
					local go, gate = Mark.tackleGate(character, root, player, cch, solved)
					if not go then
						tackleWhy = gate
					else
						local _, why = tryTackle(character, root, solved.aim, solved.mult, { char = cch, root = croot })
						if why == "sent" then
							logFile("tackle gate", gate, "drib", Mark.tackleDrib, "conf", string.format("%.2f", solved.conf or 0))
						end
						tackleWhy = why
					end
				end
		end
	end
	note("t", tackleWhy)
else
		predict = nil
	end

	if character and root then
		if Mark.tickAerial then
			Mark.tickAerial(character, root)
		end
		if Mark.tickBike then
			Mark.tickBike(character, root)
		end
		if Mark.moveTick then
			Mark.moveTick(character, root)
		end
		if Mark.tickSkill then
			Mark.tickSkill(character, root)
		end
		if Mark.tickHazard then
			Mark.tickHazard(character, root)
		end
		if Mark.drawOil then
			Mark.drawOil(root)
		end
		if Mark.tickVolley then
			Mark.tickVolley(character, root)
		end
		if Mark.tickBlock then
			Mark.tickBlock(character, root)
		end
		if Mark.tickBall then
			Mark.tickBall(character, root)
		end
		Mark.tickBox(character, root)
		Mark.boxResult()
		Mark.shotWatch()
		if Mark.jumpHoldUntil and os.clock() > Mark.jumpHoldUntil then
			Mark.jumpHoldUntil = nil
			CharacterControllers.SetJumpCommand(character, false)
			Mark.endJump()
		end
	end

	local now = os.clock()
	local gap = (tackleWhy == "no owner" or tackleWhy == "off") and 6 or 2
	if now - lastTally >= gap then
		lastTally = now
		local player = enemyCarrier(oid)
		dbg(
			"tally",
			"owner",
			oid,
			"own",
			own,
			"enemy",
			actorName(player),
			"distSrv",
			predict and string.format("%.1f", predict.dist) or "-",
			"distLive",
			predict and string.format("%.1f", predict.distLive or 0) or "-",
			"delay",
			predict and string.format("%.3f", predict.delay or 0) or "-",
			"delta",
			predict and string.format("%.2f", predict.delta or 0) or "-",
			"catch",
			predict and tostring(predict.catch) or "-",
			"inst",
			predict and string.format("%.2f", predict.instSpd or 0) or "-",
			"recent",
			predict and string.format("%.2f", predict.recentSpd or 0) or "-",
			"yaw",
			predict and string.format("%.3f", predict.yaw or 0) or "-",
			"t",
			tackleWhy,
			"d",
			dribbleWhy,
			"wire",
			Wire.n
		)
	end
end

local function cdLeft(lastAt, dur)
	return math.max(0, dur - (os.clock() - lastAt))
end

local function paintWorld()
	if not CFG.Draw then
		hideWorld()
		return
	end
	Camera = Workspace.CurrentCamera
	local character = LocalPlayer.Character
	local root = character and ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		hideWorld()
		return
	end
	local gy = root.Position.Y - 3.15
	local live = root.Position
	local ghost = ghostPos or live
	local gdir = ghostDir or unitOrNil(flat(root.CFrame.LookVector)) or Vector3.new(0, 0, 1)
	local predict = CFG.DrawTackle ~= false and predict or nil
	local dribbleDanger = CFG.DrawDanger ~= false and dribbleDanger or nil
	local drawPos = CFG.DrawPos ~= false
	local heroSlide = dribbleDanger ~= nil and dribbleDanger.heading ~= nil

	Mark.usQuad.Visible = false
	hideLines(Mark.usEdge)
	hideLines(Mark.usStuds)
	hideLines(Mark.ghostEdge)
	hideLines(Mark.chalkSmear)
	hideLines(Mark.enHex)
	hideLines(Mark.ballTicks)
	Mark.hideKnot()

	Mark.hideGate(Mark.gate.us)
	Mark.hideGate(Mark.gate.ghost)
	Mark.hideGate(Mark.gate.enLive)
	Mark.hideGate(Mark.gate.ball)
	local phantom = CFG.PosStyle == "phantom"
	if not drawPos then
		-- positions switched off
	elseif phantom then
		Mark.posArt(Mark.pen, live, ghost, gdir, gy, MatchSettings.IsGoalkeeperCharacter(character), os.clock())
	else
		Mark.bodyFill(live, gdir, gy, COL.Paper, 1.15)
	end
	if phantom or not drawPos then
		if not drawPos then
			Mark.stroke(Mark.rib.us, nil, gy, COL.Line)
		end
	elseif MatchSettings.IsGoalkeeperCharacter(character) then
		local h = 2.5
		local c = Vector3.new(ghost.X, gy, ghost.Z)
		local box = {
			c + Vector3.new(h, 0, h),
			c + Vector3.new(h, 0, -h),
			c + Vector3.new(-h, 0, -h),
			c + Vector3.new(-h, 0, h),
		}
		for i = 1, 4 do
			Mark.ghostEdge[i].Thickness = 1.7
			applyLine(Mark.ghostEdge[i], box[i], box[i % 4 + 1], COL.Paper, 1)
		end
		Mark.stroke(Mark.rib.us, { live, ghost }, gy, COL.Paper, 0.35)
	else
		Mark.bodyLine(ghost, gdir, gy, COL.Line, 1.35)
		if flat(ghost - live).Magnitude >= 0.2 then
			Mark.stroke(Mark.rib.us, { live, ghost }, gy, COL.Line, 0.2)
		else
			Mark.stroke(Mark.rib.us, nil, gy, COL.Line)
		end
	end

	if predict and predict.livePos and predict.serverPos then
		local edir = predict.aim or gdir
		Mark.smear(Mark.chalkSmear, predict.livePos, edir, gy, COL.Chalk)
		Mark.diamond(Mark.gate.enSrv, predict.serverPos, gy, COL.Tackle, 0.55)
		Mark.stroke(Mark.rib.en, { predict.livePos, predict.serverPos }, gy, COL.Tackle, 0.12)
	else
		Mark.hideGate(Mark.gate.enLive)
		Mark.hideGate(Mark.gate.enSrv)
		Mark.stroke(Mark.rib.en, nil, gy, COL.Tackle)
	end

	local knotDrawn = false
	if predict then
		local catching = predict.catch == true
		Mark.stroke(Mark.rib.our, nil, gy, COL.Chalk)
		Mark.stroke(Mark.rib.enemy, nil, gy, COL.Chalk)
		if predict.hit then
			local slidePts = predict.our
			if not (slidePts and #slidePts >= 2) then
				local aimU = predict.aim or unitOrNil(flat(predict.hit - live))
				local travel = Mark.dumpTravel and Mark.dumpTravel(predict.eta or 0.42) or flat(predict.hit - live).Magnitude
				slidePts = {}
				if aimU then
					for i = 0, 8 do
						slidePts[i + 1] = live + aimU * travel * (i / 8)
					end
				end
			end
			applyPath(ourPath, slidePts, gy, COL.Tackle, 1, false)
			applyPath(enemyPath, predict.enemy, gy, COL.Chalk, 0.55, false)
			Mark.approach(Mark.rib.our, hitTri, live, predict.hit, gy, catching and COL.Tackle or COL.Chalk)
			local fromEn = predict.livePos or predict.serverPos
			Mark.approach(Mark.rib.enemy, enLiveTri, fromEn, predict.hit, gy, COL.Chalk)
			Mark.sightHold = { p = predict.hit, aim = predict.aim, at = os.clock() }
			Mark.sightAt(predict.hit, gy, COL.Paper, true, predict.aim)
			Mark.sightP = predict.hit
		else
			hideLines(ourPath)
			hideLines(enemyPath)
			hitTri.Visible = false
			enLiveTri.Visible = false
			Mark.sightKeep(gy)
		end
		Mark.spur.Visible = false
	else
		hideLines(ourPath)
		hideLines(enemyPath)
		Mark.stroke(Mark.rib.our, nil, gy, COL.Chalk)
		Mark.stroke(Mark.rib.enemy, nil, gy, COL.Chalk)
		hitTri.Visible = false
		enLiveTri.Visible = false
		Mark.sightKeep(gy)
		Mark.spur.Visible = false
	end

	if heroSlide then
		local col = dribbleDanger.inFov and COL.Line or COL.Chalk
		local point = dribbleDanger.hitP or dribbleDanger.root.Position
		Mark.approach(Mark.rib.slide, dangerTri, live, point, gy, col)
		slidePip.Visible = false
	else
		hideLines(slidePath)
		slidePip.Visible = false
		dangerTri.Visible = false
		Mark.stroke(Mark.rib.slide, nil, gy, COL.Chalk)
	end
	if not knotDrawn then
		Mark.hideKnot()
	end

	local goal = enemyGoalPart()
	local lb, lt, rb, rt, along, face
	if goal then
		lb, lt, rb, rt, along, face = goalMouthCorners(goal)
	end
	if CFG.DrawGoal ~= false and lb and along and face then
		local side = along * 0.06
		local lift = face * 0.04
		local drop = Vector3.new(0, 0.08, 0)
		for i = 1, 4 do
			Mark.goalStitch[i].Thickness = Mark.ChalkW
		end
		for i = 5, 8 do
			Mark.goalStitch[i].Thickness = Mark.Thread
		end
		applyLine(Mark.goalStitch[1], lb + side + lift, lt + side + lift, COL.Line, 1)
		applyLine(Mark.goalStitch[2], lb - side + lift, lt - side + lift, COL.Line, 1)
		applyLine(Mark.goalStitch[3], rb + side + lift, rt + side + lift, COL.Line, 1)
		applyLine(Mark.goalStitch[4], rb - side + lift, rt - side + lift, COL.Line, 1)
		applyLine(Mark.goalStitch[5], lt + lift, rt + lift, COL.Tackle, 1)
		applyLine(Mark.goalStitch[6], lt - drop + lift, rt - drop + lift, COL.Tackle, 1)
		Mark.goalStitch[7].Visible = false
		Mark.goalStitch[8].Visible = false
	else
		hideLines(Mark.goalStitch)
	end

	local oid = liveOwnerId()
	local own = oid == LocalPlayer.UserId
	local ballPos = Renderer.GetMainMatchPosition()
	if ballPos and CFG.DrawBall ~= false then
		local col = own and COL.Line or COL.Paper
		Mark.ballSeam(ballPos, col)
		Mark.hideGate(Mark.gate.ball)
	else
		hideLines(Mark.ballHex)
		hideLines(Mark.ballTicks)
		Mark.hideGate(Mark.gate.ball)
	end
	hideLines(Mark.flight)
	Mark.flightTip.Visible = false
	Mark.flightTail.Visible = false
	hideLines(Mark.shadow)
	hideLines(Mark.ticks)
	hideLines(Mark.route)
	hideLines(Mark.stake)
	Mark.flightDot.Visible = false
	Mark.flightTime.Visible = false
	hideLines(Mark.box)
	local preview = Shoot.preview
	local ballNow = Renderer.GetPosition()
	if preview and preview.origin and ballNow and (preview.origin - ballNow).Magnitude > 1 and not Shoot.locked and os.clock() - (Shoot.goodT or 0) > 0.5 then
		Shoot.preview = nil
		preview = nil
	end
	if preview and preview.pts and #preview.pts >= 2 and Shoot.point and CFG.DrawShot ~= false then
		local col = Shoot.shotName == "LOB" and COL.Lob or (Shoot.shotName == "FLAT" and COL.Flat or (Shoot.shotName == "TRICK" and COL.Lob or (Shoot.shotName == "DIP" and COL.Lob or (Shoot.shotName == "LOW" and COL.Lob or (Shoot.shotName == "HIGH" and COL.Tackle or (Shoot.shotName == "SPIN" and COL.Tackle or COL.Line))))))
		if CFG.ShotStyle == "aurora" then
			local nm = Shoot.shotName
			local kind = (nm == "FLAT" or nm == "LOW") and "lo" or ((nm == "TRICK" or nm == "DIP" or nm == "SPIN") and "curl" or "hi")
			Mark.trajArt(Mark.pen, preview.pts, preview.times, preview.land, preview.along, gy, kind, os.clock(), preview.shift)
		else
			Mark.drawFlight(preview.pts, col)
			Mark.drawShadow(preview.pts, gy, COL.Chalk)
			if preview.land and preview.face then
				Mark.drawScar(preview.land, preview.face, preview.along, gy, col)
			end
		end
	end
	if Mark.paDraw then
		Mark.paDraw(gy)
	end
	if Mark.drawRoute then
		Mark.drawRoute(root, gy)
	end
	Mark.drawGk(gy)
	Mark.drawBlk(gy)
	Mark.drawDuel(gy)
	Mark.artFinish()
end

local function paintHud()
	if not CFG.Draw then
		for i = 1, 3 do
			chips[i].bg.Visible = false
			chips[i].tx.Visible = false
		end
		Mark.hudRule.Visible = false
		shotDbg.Visible = false
		return
	end
	Camera = Workspace.CurrentCamera
	local oid = liveOwnerId()
	local own = oid == LocalPlayer.UserId
	local ballTxt = "ball  none"
	if own then
		ballTxt = "shot  " .. (Shoot.why or "idle")
	elseif Mark.ak then
		ballTxt = "kick  " .. tostring(Mark.ak.tag)
	elseif ownerIdOk(oid) then
			ballTxt = "ball  " .. tostring(oid)
	end
	local rows = {
		{ chips[1], "tackle  " .. tackleWhy, tackleWhy == "sent" and COL.Tackle or COL.Chalk, tackleWhy == "sent" },
		{ chips[2], "dribble  " .. dribbleWhy, dribbleWhy == "sent" and COL.Line or COL.Chalk, dribbleWhy == "sent" },
		{ chips[3], ballTxt, own and COL.Line or COL.Paper, own },
	}
	local vp = Camera.ViewportSize
	local y = vp.Y - 22
	local x = 16
	local ruleCol = COL.Chalk
	if tackleWhy == "sent" then
		ruleCol = COL.Tackle
	elseif dribbleWhy == "sent" or own then
		ruleCol = COL.Line
	end
	for i = #rows, 1, -1 do
		local row = rows[i]
		local tx = row[1].tx
		row[1].bg.Visible = false
		tx.Text = row[2]
		tx.Color = row[3]
		tx.Size = row[4] and 16 or 13
		tx.Outline = true
		tx.OutlineColor = COL.Ink
		tx.Font = FONT
		tx.Position = Vector2.new(x, y)
		tx.Visible = true
		y -= row[4] and 20 or 16
	end
	Mark.hudRule.From = Vector2.new(x, y + 4)
	Mark.hudRule.To = Vector2.new(x + 108, y + 4)
	Mark.hudRule.Color = ruleCol
	Mark.hudRule.Transparency = 1
	Mark.hudRule.Visible = true
	local curveTxt = Shoot.curve and string.format("%.2f", Shoot.curve) or "-"
	local distTxt = Shoot.dist and string.format("%.0f", Shoot.dist) or "-"
	local sideTxt = Shoot.lastSide and (Shoot.lastSide > 0.8 and "R" or (Shoot.lastSide < -0.8 and "L" or "C")) or "-"
	local name = Shoot.shotName or "NONE"
	shotDbg.Text = name .. "  " .. sideTxt .. "  dist " .. distTxt .. "  h " .. (Shoot.hFrac and string.format("%.2f", Shoot.hFrac) or "-") .. "  curve " .. curveTxt .. "  " .. (Shoot.band or "-")
	shotDbg.Size = 18
	shotDbg.Color = name == "LOB" and COL.Lob or (name == "FLAT" and COL.Flat or (name == "TRICK" and COL.Lob or (name == "LOW" and COL.Lob or (name == "HIGH" and COL.Tackle or (name == "SPIN" and COL.Tackle or COL.Paper)))))
	shotDbg.Position = Vector2.new(vp.X * 0.5, vp.Y * 0.5 + 34)
	shotDbg.Visible = CFG.ShotDebug ~= false
	if CFG.DrawHud == false then
		for i = 1, 3 do
			chips[i].bg.Visible = false
			chips[i].tx.Visible = false
		end
		Mark.hudRule.Visible = false
	end
end

-- AutoShoot owns this kick: the namecall rewrite below sends Shoot.aim instead of the camera. The Direction and Body
-- spoofs only make sense on such a kick (the real shot is ours, the replicated aim / body are free to lie); on a kick
-- AutoShoot does not rewrite the shot comes from the camera and the body pose, so a lie there is pure desync with no
-- gain and a sideways body puts the ball off target. One predicate for the rewrite and for both spoofs.
Mark.autoShotOn = function()
	if not CFG.AutoShoot or MatchSettings.IsGoalkeeperCharacter(LocalPlayer.Character) then
		return false
	end
	local a = Shoot.aim
	if not (a and a.Direction) or Shoot.lob then
		return false
	end
	return (Mark.flickStrike or (Shoot.launch and Shoot.launch.Y > 1) or a.Direction.Y > 0.05) and true or false
end

local function shotRemote(self)
	if typeof(self) ~= "Instance" then
		return nil
	end
	local parent = self.Parent
	local ball = parent and parent.Name == "Ball"
	if self == BallGroup.Kick or (ball and self.Name == "Kick") then
		return "kick"
	end
	if self == BallGroup.ActionUpdate or (ball and self.Name == "ActionUpdate") then
		return "aim"
	end
	return nil
end

-- While an aerial / bicycle strike is locked, the game's own aim source returns our solved ray: ChargedKick's
-- charge aim ray, Shoot release (GetChargeAimRay or GetCameraAimRayWithoutHit), commitAimLock -> LockAim
-- (AimLockedAt), preview and every remote phase then carry it. Overriding only the remote packet left the client
-- release / lock built from the camera (legit flick bicycle went where the camera looked).
Mark.strikeRay = function()
	if not (Mark.shotLockUntil and os.clock() < Mark.shotLockUntil and Shoot.aim and Shoot.aim.Direction) then
		return nil
	end
	local a = Shoot.aim
	local o = typeof(a.Origin) == "Vector3" and a.Origin or Vector3.zero
	return {
		Origin = o,
		Direction = a.Direction,
		CameraCFrame = a.CameraCFrame or CFrame.lookAt(o, o + a.Direction),
		CameraFieldOfView = a.CameraFieldOfView,
		IsAirborne = a.IsAirborne,
	}
end

local oldCamRay = Reticle.GetCameraRay
Mark.oldCamRay = oldCamRay
Reticle.GetCameraRay = function(...)
	if Mark.pa and Mark.pa.live and Mark.pa.live.ray then
		return Mark.pa.live.ray
	end
	-- Keeper Push / item now: the gun goes at the planned target for the whole sequence (flintlock 3 shots over 0.5 s)
	local pa = Mark.pushAim
	if pa and os.clock() < pa.untilT then
		local cam = Workspace.CurrentCamera
		local okP, P = Mark.try(pa.fn)
		if cam and okP and typeof(P) == "Vector3" then
			-- the gun hits the FIRST character the ray meets (Reticle: TargetPosition = the aim hit). From the camera - 15-30 studs behind
			-- and above us - the line to a keeper 77 st away crosses other players: log, flintlock (ONE accurate pellet) at the keeper
			-- from the camera: "we hit victim ... = NOT the keeper" twice; from the body (v190/191): "= THE KEEPER" twice.
			local me = ActorTargeting.GetActorRoot(LocalPlayer)
			local o = me and (me.Position + Vector3.new(0, 1.5, 0)) or cam.CFrame.Position
			local dir = unitOrNil(Mark.recoilAim(pa, P, o, CFG.GunPushRecoil or 0.5, os.clock(), math.random) - o)
			if dir then
				return Ray.new(o, dir)
			end
		end
	end
	if Mark.silentRay and not (ChargedKick.IsCharging and ChargedKick.IsCharging()) then
		return Mark.silentRay
	end
	return oldCamRay(...)
end

local oldAimRay = Reticle.GetCameraAimRayWithoutHit
Reticle.GetCameraAimRayWithoutHit = function()
	if Mark.pa and Mark.pa.live and Mark.pa.live.ray then
		return Mark.pa.live.ray
	end
	if Mark.skillRay then
		return Mark.skillRay
	end
	local strike = Mark.strikeRay()
	if strike then
		return strike
	end
	-- the decoy as the game's own aim sample: the charge aim changes, so ActionRemoteProtocol.Update really sends it.
	-- After the window (spoofed charge only) the sample is the real shot: the charge ray frozen at the lock and the lock
	-- packet carry it natively, not the camera.
	if Mark.sp then
		local spoof = Mark.spoofRay()
		if spoof then
			return spoof
		end
		local a = Shoot.aim
		if a and a.Direction and ChargedKick.IsCharging and ChargedKick.IsCharging() then
			return { Origin = a.Origin, Direction = a.Direction, CameraCFrame = a.CameraCFrame, CameraFieldOfView = a.CameraFieldOfView, IsAirborne = a.IsAirborne }
		end
	end
	local ray = oldAimRay()
	local aim = Mark.volleyAim or Mark.blockAim
	if aim and type(ray) == "table" and ChargedKick.IsCharging and ChargedKick.IsCharging() and liveOwnerId() ~= LocalPlayer.UserId then
		local out = table.clone(ray)
		local camPos = typeof(out.CameraCFrame) == "CFrame" and out.CameraCFrame.Position or (typeof(out.Origin) == "Vector3" and out.Origin) or Vector3.zero
		out.Direction = aim
		out.CameraCFrame = CFrame.lookAt(camPos, camPos + aim)
		out.TargetPosition = nil
		out.ScreenPosition = nil
		return out
	end
	return ray
end

local oldPathGet = ChargePathVelocity.Get
ChargePathVelocity.Get = function(char, secs, kind, aim, origin, reported, kickDir, target, boundary, curve)
	if Shoot.locked and not Shoot.solving and Shoot.aim and Shoot.aim.Direction and not Shoot.lob and Shoot.solveAt then
		local live = Renderer.GetPosition()
		if live and (live - Shoot.solveAt).Magnitude <= (Shoot.aimPoint and 6 or 1) then
			aim = Shoot.aim
			curve = if Mark.flickStrike then nil else Shoot.curve -- was `and nil or`: the flick kept the curve
		end
	end
	-- Direction Spoof: while the decoy runs the local trajectory preview is the decoy shot (same flat direction too)
	local decoy = Mark.sp and Mark.spoofRay()
	if decoy then
		aim, target = decoy, nil
		kickDir = AimFacing.GetFlatDirection(decoy.Direction) or kickDir
	end
	return oldPathGet(char, secs, kind, aim, origin, reported, kickDir, target, boundary, curve)
end

local ShotAimAssist = require(Modules.Actions.ShotAimAssist)
local oldAssist = ShotAimAssist.GetAssistedDirection
ShotAimAssist.GetAssistedDirection = function(...)
	if CFG.AutoShoot and Shoot.aim and (liveOwnerId() == LocalPlayer.UserId or Mark.flickStrike) then
		return nil
	end
	return oldAssist(...)
end

local TrajectoryPreviewFollow = require(Client.Gameplay.Visual.TrajectoryPreviewFollow)
local oldAimStep = TrajectoryPreviewFollow.StepAimSampleCFrame
TrajectoryPreviewFollow.StepAimSampleCFrame = function(current, target, dt)
	return oldAimStep(current, target, dt)
end

local oldNamecall
oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
	local method = getnamecallmethod()
	setnamecallmethod(method)
	if method == "FireServer" and CFG.GunPush then
		local pk = ...
		if type(pk) == "table" and pk.Phase == "Release" and type(pk.Command) == "table" and pk.Command.PassType == "Shot" and shotRemote(self) == "kick" then
			local cmdR = pk.Command
			task.defer(Mark.gunPushOwn, cmdR) -- after our kick packet has gone out
		end
	end
	if method ~= "FireServer" or not CFG.AutoShoot then
		return oldNamecall(self, ...)
	end
	local packet = ...
	local which = shotRemote(self)
	if (which == "kick" or which == "aim") and type(packet) == "table" then
		local cmd = packet.Command
		if which == "kick" and packet.Phase == "Cancel" then
			Shoot.locked = nil
			Shoot.wire = nil
		elseif Mark.pa and Mark.pa.live and Mark.pa.live.ray and type(cmd) == "table" and cmd.PassType == "FreeLobPass" and (packet.Phase == "Start" or packet.Phase == "Release" or packet.Phase == "Update") then
			-- PASS ASSIST: the packet carries our yaw. At Release the charge is what the hold really produced: re-aim for it.
			local live = Mark.pa.live
			if packet.Phase == "Release" and not live.released then
				live.released = true
				local actual = cmd.ChargeSeconds
				if type(actual) == "number" then
					local sol2 = Mark.paSolve(live.sel, actual)
					if sol2 and live.sol then
						local worse = math.abs(sol2.along) > math.abs(live.sol.along or 0) + 4 or math.abs(sol2.lat) > math.abs(live.sol.lat or 0) + 3
						if not worse then
							live.dir = sol2.dir
							live.sol = sol2
							Mark.paRay(live)
						else
							logFile("pass assist", "release", "keep", "along", string.format("%.1f", sol2.along), "lat", string.format("%.1f", sol2.lat))
						end
					end
					logFile("pass assist", "release", "planned", string.format("%.3f", live.charge), "actual", string.format("%.3f", actual), "status", live.sol and live.sol.status or "-", "along", live.sol and string.format("%.1f", live.sol.along) or "-", "lat", live.sol and string.format("%.1f", live.sol.lat) or "-")
				end
			end
			local r = live.ray
			cmd.AimDirection = { Origin = r.Origin, Direction = r.Direction, CameraCFrame = r.CameraCFrame, CameraFieldOfView = r.CameraFieldOfView, IsAirborne = false }
			cmd.TargetUserId = nil
		elseif type(cmd) == "table" and (packet.Phase == "Start" or packet.Phase == "Release" or packet.Phase == "Update") and Mark.autoShotOn() and not (liveOwnerId() == LocalPlayer.UserId and (cmd.PassType == "FreeLowPass" or cmd.PassType == "FreeLobPass" or cmd.PassType == "AssistedPass")) then
			if which == "kick" and packet.Phase == "Start" and cmd.PassType == "Shot" and not Mark.sp then
				Mark.spoofPlan()
			end
			-- Direction Spoof: until the aim lock the replicated aim is a decoy; the lock packet (AimLockedAt) and the
			-- release carry the real shot
			-- Start and Release carry the real shot: the server may take the shot basis from either (the log showed shots
			-- flying to the decoy while the last Update was real). The decoy lives in Update packets only.
			local dec = packet.Phase == "Update" and cmd.AimLockedAt == nil and Mark.spoofRay() or nil
			if Mark.sp and packet.Phase == "Update" then
				-- what really went out inside the decoy window (log at "spoof done")
				local sp = Mark.sp
				if dec then
					sp.sent = (sp.sent or 0) + 1
				elseif os.clock() < sp.endAt then
					sp.real = (sp.real or 0) + 1
					sp.realWhy = cmd.AimLockedAt ~= nil and "lock" or "no decoy"
				end
			end
			if dec then
				cmd.AimDirection = dec
				-- KickDirection stays the REAL one in every packet: Shoot.GetVelocity takes the flat shot direction from it
				-- and clamps the endpoint yaw to +-15 deg around it (EndpointAim.MaximumEndpointYawDegrees). A decoy here
				-- pinned every shot to within 15 deg of the decoy - the ball flew to the fake, off target.
				cmd.KickDirection = AimFacing.GetFlatDirection(Shoot.aim.Direction) or Shoot.aim.Direction
				-- the session keeps the curve of the latest packet: the real one in every phase (nil here cost every
				-- spoofed shot its curve)
				if cmd.PassType == "Shot" and Shoot.curve and not Mark.flickStrike then
					cmd.Curve = Shoot.curve
				end
			else
				cmd.AimDirection = {
					Origin = Shoot.aim.Origin,
					Direction = Shoot.aim.Direction,
					CameraCFrame = Shoot.aim.CameraCFrame,
					CameraFieldOfView = Shoot.aim.CameraFieldOfView,
					IsAirborne = Shoot.aim.IsAirborne,
				}
				cmd.KickDirection = AimFacing.GetFlatDirection(Shoot.aim.Direction) or Shoot.aim.Direction
				if Mark.flickStrike then
					cmd.Curve = 0
				elseif cmd.PassType == "Shot" and Shoot.curve then
					cmd.Curve = Shoot.curve
				end
			end
			if packet.Phase == "Release" and cmd.PassType == "Shot" and Shoot.launch then
				-- ground truth of every shot: the ball 0.2 s after the release against the solved flight (curve included)
				local pv, hadDecoy, hadBody, p0 = Shoot.preview, Mark.sp ~= nil, Mark.fs ~= nil, Renderer.GetPosition()
				-- what the ball can have followed: the packet aim, the last decoy, the aim the game froze at its lock, the first-frame real
				local sp0 = Mark.sp
				local decoyLast = sp0 and sp0.lastDir
				local realFirst = sp0 and sp0.D0
				local lockRay = ChargedKick.GetChargeAimRay and ChargedKick.GetChargeAimRay()
				local lockDir = type(lockRay) == "table" and lockRay.Direction or nil
				-- how stale the solved shot is at the release: the ball against the origin it was solved from, the age of the
				-- solve / of the last re-aim (the carried ball swings with the body pose)
				local drift = p0 and Shoot.aimBallAt and (p0 - Shoot.aimBallAt).Magnitude or -1
				local nowR = os.clock()
				local ageS, ageR = nowR - (Shoot.goodT or nowR), nowR - (Shoot.rebased or nowR)
				local aimSent = typeof(cmd.AimDirection) == "table" and cmd.AimDirection.Direction
				Mark.shotAuditStart(pv, p0)
				task.delay(0.2, function()
					local pB = Renderer.GetPosition()
					if not (pv and pv.pts and pv.times and p0 and pB) then
						return
					end
					local function at(t)
						for i = 2, #pv.pts do
							local t1 = pv.times[i] or 0
							if t1 >= t then
								local t0 = pv.times[i - 1] or 0
								return pv.pts[i - 1]:Lerp(pv.pts[i], t1 > t0 and (t - t0) / (t1 - t0) or 0)
							end
						end
						return nil
					end
					local e0, e1 = at(0), at(0.2)
					if not (e0 and e1) then
						return
					end
					local ea, aa = e1 - e0, pB - p0
					if ea.Magnitude < 1 or aa.Magnitude < 1 then
						return
					end
					local ang = math.deg(math.acos(math.clamp(ea.Unit:Dot(aa.Unit), -1, 1)))
					if hadDecoy then
						local function yawGap(u, v)
							if not (u and v) then
								return "-"
							end
							local d = math.deg(math.atan2(u.X, u.Z) - math.atan2(v.X, v.Z))
							return string.format("%.0f", math.abs((d + 180) % 360 - 180))
						end
						local sent = typeof(aimSent) == "Vector3" and aimSent or nil
						logFile("spoof leak", "ball vs sent", yawGap(aa, sent), "vs last decoy", yawGap(aa, decoyLast), "vs game lock", yawGap(aa, lockDir), "sent vs first real", yawGap(sent, realFirst), "sent vs decoy", yawGap(sent, decoyLast))
					end
					-- the same error split: up/down (a flight over the bar) and left/right (a flight wide)
					local function elev(v)
						return math.deg(math.atan2(v.Y, flat(v).Magnitude))
					end
					local pitchErr = elev(aa) - elev(ea)
					local yawErr = math.deg(math.atan2(aa.X, aa.Z) - math.atan2(ea.X, ea.Z))
					yawErr = (yawErr + 180) % 360 - 180
					logFile("shoot", "flight", "pitch err", string.format("%.1f", pitchErr), "yaw err", string.format("%.1f", yawErr), "angle to solved", string.format("%.1f", ang), "moved", string.format("%.1f", aa.Magnitude), "solved", string.format("%.1f", ea.Magnitude), "decoy", hadDecoy and "yes" or "no", "body", hadBody and "yes" or "no", "drift", string.format("%.1f", drift), "solve age", string.format("%.2f", ageS), "rebase age", string.format("%.2f", ageR), "aim sent", aimSent and fmtV(aimSent) or "-")
				end)
			end
			if packet.Phase == "Release" and (Mark.flickStrike or Mark.forceBike) then
				local src0 = typeof(packet.Command.AimDirection) == "table" and packet.Command.AimDirection.Direction
				logFile("shoot", "release", "sent", fmtV(src0), "locked", tostring(Mark.strikeRay() ~= nil))
			end
			if packet.Phase == "Start" then
				Mark.bfShot = Shoot.shotName == "BOUNCE FAKE" and os.clock() or nil
				Shoot.roll = math.random()
				Shoot.fakeRoll = math.random()
				Shoot.fakeFirst = math.random()
				Shoot.bounceRoll = math.random()
				do
					-- last picks (family + side): the next solve down-weights what was just used (predictable shots)
					local h = Mark.shotHist or {}
					Mark.shotHist = h
					h[#h + 1] = { band = Shoot.band, side = (Shoot.hitSide or 0) >= 0 and 1 or -1 }
					if #h > 4 then
						table.remove(h, 1)
					end
				end
				logFile("shoot", "start", Shoot.lob and "lob" or "dir", "reach", Shoot.reachM and string.format("%.2f", Shoot.reachM) or "-", Shoot.reachOpen and "open" or "saveable", "pool", Shoot.reachN or "-", "bands", Mark.bandStat(Mark.shotStat), "keeper", Shoot.keeperS and string.format("%.1f", Shoot.keeperS) or "-", Shoot.keeperTag or "-", fmtV(Shoot.aim.Direction), "curve", Shoot.curve and string.format("%.2f", Shoot.curve) or "-", "dist", Shoot.dist and string.format("%.0f", Shoot.dist) or "-", "h", Shoot.hFrac and string.format("%.2f", Shoot.hFrac) or "-", "gap", Shoot.gap and string.format("%.1f", Shoot.gap) or "-", "ang", Shoot.ang and string.format("%.1f", Shoot.ang) or "-", "side", Shoot.hitSide ~= nil and string.format("%.1f", Shoot.hitSide) or "-", "band", Shoot.band or "-", "hold", Shoot.hold and "1" or "0", "vel", fmtV(Shoot.launch), "vmag", Shoot.launch and string.format("%.0f", Shoot.launch.Magnitude) or "-", "vdir", Shoot.launch and fmtV(Shoot.launch.Unit) or "-", "spin", fmtV(Shoot.spin), "org", fmtV(Shoot.aim.Origin), "from", fmtV(Shoot.sampleFrom))
			end
		end
	end
	setnamecallmethod(method)
	return oldNamecall(self, ...)
end))

if ChargedKick.IsCharging and ChargedKick.IsCharging() then
	ChargedKick.CancelCharge()
end

if ChargedKick.HandleInputBegan then
	local oldShootBegan = ChargedKick.HandleInputBegan
	ChargedKick.HandleInputBegan = function(input, processed, extra)
		if Controls.IsInput("Kick", input) then
			-- who owns the next charge: a real input object (the player) or a table we made (volley / bike / aerial)
			if typeof(input) == "Instance" then
				Mark.realChargeAt = os.clock()
			else
				Mark.scriptChargeAt = os.clock()
			end
		end
		-- who starts a kick while we hold the ball (real mouse/key vs a script-made Controls.CreateInput, and caller)
		if Controls.IsInput("Kick", input) and liveOwnerId() == LocalPlayer.UserId then
			local src0 = debug.info(2, "s")
			local line0 = debug.info(2, "l")
			logFile("kick input", "own", "type", typeof(input) == "Instance" and tostring(input.UserInputType) or typeof(input), "key", typeof(input) == "Instance" and tostring(input.KeyCode) or "-", "processed", tostring(processed), "caller", tostring(src0), tostring(line0))
		end
		if CFG.AutoShoot and not Shoot.aim and typeof(input) == "Instance" and Controls.IsInput("Kick", input) and liveOwnerId() == LocalPlayer.UserId then
			logFile("shoot", "press without aim", tostring(Shoot.why), "job", tostring(Shoot.job ~= nil), "full", string.format("%.1f", Shoot.fullCost or 0), "dt", string.format("%.1f", (Mark.dtAvg or 0) * 1000))
		end
		if CFG.AutoShoot and Shoot.lob and Shoot.aim and not processed and Controls.IsInput("Kick", input) then
			local passIn = Mark.passIn or require(Client.Gameplay.Actions.Pass)
			Mark.passIn = passIn
			if passIn.HandleInputBegan(Controls.CreateInput("Lob"), false) ~= false then
				local hold = Shoot.chipSec or 0.22
				task.delay(hold, function()
					if passIn.HandleInputEnded then
						passIn.HandleInputEnded(Controls.CreateInput("Lob"))
					end
				end)
				logFile("shoot", "chip", string.format("%.2f", hold))
				return true
			end
		end
		return oldShootBegan(input, processed, extra)
	end
end

if ChargedKick.HandleInputEnded then
	local oldShootEnded = ChargedKick.HandleInputEnded
	ChargedKick.HandleInputEnded = function(input, ...)
		-- only the player's own release (a real input object); our scripted charges pass tables and go straight through
		if typeof(input) == "Instance" and Mark.feintRelease and Controls.IsInput("Kick", input) then
			if Mark.feintRelease() then
				return
			end
		end
		return oldShootEnded(input, ...)
	end
end

Mark.wallParts = function()
	local now = os.clock()
	if Mark.wallCache and now - (Mark.wallAt or 0) < 0.25 then
		return Mark.wallCache
	end
	Mark.wallAt = now
	local list = {}
	local models = {}
	Mark.wallModels = models
	local world = workspace:FindFirstChild("Misc")
	world = world and world:FindFirstChild("Items")
	if not world then
		Mark.wallCache = list
		return list
	end
	Mark.placeMod = Mark.placeMod or require(Modules.Items.PlaceDownPlacement)
	Mark.destMod = Mark.destMod or require(Modules.Gameplay.DestructionSettings)
	local place, dest = Mark.placeMod, Mark.destMod
	for _, inst in world:GetChildren() do
		if inst:GetAttribute("PlacedItemId") == "barricades" and not dest.IsBoundaryDestroyed(inst) then
			models[#models + 1] = inst
			local parts = place.GetBoundaryParts(inst)
			for i = 1, #parts do
				list[#list + 1] = parts[i]
			end
		end
	end
	-- signature: same set of standing barricades -> memoised block results stay valid
	local sig = {}
	for i = 1, #models do
		sig[i] = tostring(models[i])
	end
	local s = #models .. ":" .. table.concat(sig, ",")
	if s == Mark.wallSig and Mark.wallModelsKeep then
		Mark.wallModels = Mark.wallModelsKeep
	else
		Mark.wallSig = s
		Mark.wallModelsKeep = models
	end
	Mark.wallCache = list
	return list
end

Mark.wallHit = function(origin, dir, dist)
	local parts = Mark.wallParts()
	if #parts == 0 or typeof(dir) ~= "Vector3" or dir.Magnitude < 0.05 then
		return nil
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Include
	params.FilterDescendantsInstances = parts
	-- A SPHERE of body size, not a ray: a ray that starts inside / beside a barricade part never reports it (a raycast has no
	-- backface hit), which is why the tackle aim "stopped seeing" the wall when we stood close to it and slid into it. A
	-- shapecast starting in contact returns the hit at distance 0.
	return Workspace:Spherecast(origin, Mark.wallBodyR or 1.6, dir.Unit * dist, params)
end

-- Barricade avoidance for agent steering. Old version: hit -> "left" whenever both sides were blocked, with no
-- memory, so after AutoWall dropped a barricade between us and the target every agent mode slid along it in one
-- direction (user: "after AutoWall the script runs one way"). Now: rotate the wanted dir by 25..90 deg, keep the side
-- chosen last time for 0.6 s, prefer the side closer to the wanted dir; nothing clear -> keep the wanted dir (walk
-- into it, the game collides) instead of inventing a direction.
Mark.wallDir = function(root, dir)
	if not (root and dir) or dir.Magnitude < 0.05 then
		return dir
	end
	local fd = unitOrNil(flat(dir))
	if not fd or not Mark.wallHit(root.Position, fd, 6) then
		Mark.wallSide = nil
		return dir
	end
	local function rot(a)
		local r = math.rad(a)
		return Vector3.new(fd.X * math.cos(r) - fd.Z * math.sin(r), 0, fd.X * math.sin(r) + fd.Z * math.cos(r))
	end
	local sticky = Mark.wallSide and os.clock() - (Mark.wallSideAt or 0) < 0.6 and Mark.wallSide or nil
	for _, a in { 25, 45, 65, 90 } do
		for _, s in (sticky == -1 and { -1, 1 } or { 1, -1 }) do
			local c = rot(a * s)
			if not Mark.wallHit(root.Position, c, 7) then
				Mark.wallSide, Mark.wallSideAt = s, os.clock()
				if not Mark.wallLog or os.clock() - Mark.wallLog > 0.5 then
					Mark.wallLog = os.clock()
					logFile("wall steer", Mark.move and Mark.move.mode or "-", a * s)
				end
				return c * dir.Magnitude
			end
		end
	end
	return dir
end

Mark.dumpBall = function(root, away)
	if liveOwnerId() ~= LocalPlayer.UserId then
		return
	end
	local aim = unitOrNil(flat(away)) or Vector3.new(0, 0, -1)
	local origin = root.Position + Vector3.new(0, 1.6, 0)
	local ray = {
		Origin = origin,
		Direction = aim,
		CameraCFrame = CFrame.lookAt(origin, origin + aim),
	}
	local now = Workspace:GetServerTimeNow()
	local cmd = ActionCommands.Kick({
		PassType = "FreeLobPass",
		ChargeSeconds = 0,
		HoldSeconds = 0,
		MaximumChargeSeconds = KickCore.Constants.MaximumChargeSeconds,
		AimDirection = ray,
		KickDirection = aim,
		ShotTime = now - 0.25,
	})
	ActionRemoteProtocol.Start(cmd)
	cmd.ShotTime = now
	ActionRemoteProtocol.Release(cmd)
	logFile("ball dump", "lob", fmtV(aim))
end

local function onProjectile(kind, proj)
	if kind ~= "ProjectileStart" or type(proj) ~= "table" then
		return
	end
	local id = proj.ItemId
	-- the same projectile arrives on two remotes (ProjectileMovement + Items.Effect) and again in a ProjectileSnapshot:
	-- a second pass over it reset its state (decision flags) and doubled the reaction
	Mark.projSeen = Mark.projSeen or {}
	if proj.Id ~= nil then
		if Mark.projSeen[proj.Id] then
			return
		end
		Mark.projSeen[proj.Id] = os.clock()
		for k, tt in Mark.projSeen do
			if os.clock() - tt > 30 then
				Mark.projSeen[k] = nil
			end
		end
	elseif os.clock() - (Mark.projAt or 0) < 0.15 and Mark.projId == id then
		return
	end
	Mark.projAt = os.clock()
	Mark.projId = id
	if type(id) == "string" and id == "freezeGun" and type(proj.Gravity) == "number" and proj.Gravity > 1 then
		Mark.projGrav[id] = proj.Gravity -- any shooter's: it is the server's constant, learned from the first one we see
	end
	if proj.SourceUserId == LocalPlayer.UserId and type(id) == "string" and typeof(proj.Velocity) == "Vector3" then
		Mark.projSpeed = Mark.projSpeed or {}
		Mark.projSpeed[id] = proj.Velocity.Magnitude
		logFile("proj speed", id, string.format("%.1f", proj.Velocity.Magnitude))
		if type(proj.Gravity) == "number" then
			Mark.projGrav = Mark.projGrav or {}
			Mark.projGrav[id] = proj.Gravity
		end
		-- SilentAim area check: the launch the server really used against the one we planned (Mark.areaLast)
		local al = Mark.areaLast
		if al and al.id == id and os.clock() - al.at < 0.7 and proj.Velocity.Magnitude > 1 then
			local v = proj.Velocity
			local ang = al.launch and math.deg(math.acos(math.clamp(v.Unit:Dot(al.launch), -1, 1))) or -1
			logFile("silent area shot", id, "launch err", string.format("%.1f", ang), "deg grav", tostring(proj.Gravity), "plan G", fmtV(al.G), "t", string.format("%.2f", al.t), "D", string.format("%.1f", al.D))
			Mark.areaShot = { id = id, G = al.G, tLand = Workspace:GetServerTimeNow() + al.t, model = al.model, logged = false }
		end
	end
	local shooter = playerOf(proj.SourceUserId)
	if shooter and sameTeam(shooter) then
		return
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local pos = proj.Position
	local vel = proj.Velocity
	if not root or typeof(pos) ~= "Vector3" then
		return
	end
	local own = liveOwnerId() == LocalPlayer.UserId

	local function gravOf(item)
		local g = Workspace.Gravity
		if type(g) ~= "number" or g < 10 then
			g = 196.2
		end
		if item == "rocketPunch" or item == "boomerang" then
			return 0
		elseif item == "freezeGun" then
			return g * 0.3
		elseif item == "bazooka" or item == "grenade" then
			return g
		end
		return g * 0.3
	end
	local function radOf(item)
		if item == "bazooka" or item == "grenade" then
			return Mark.blastR()
		end
		if item == "rocketPunch" then
			return 6.2
		end
		return HitboxSettings.Receive.Size.X * 0.5 + 1.4
	end
	-- Closest horizontal miss over the next `cap` seconds, including the item's gravity (ProjectileVfx.PredictionConfigs:
	-- bazooka/grenade = full, freezeGun = 0.3, rocketPunch = 0) and where WE will be.
	local function closest(from, velo, grav, cap)
		if typeof(velo) ~= "Vector3" or velo.Magnitude < 1 then
			return 1e9, 0
		end
		local us = root.AssemblyLinearVelocity
		us = typeof(us) == "Vector3" and us or Vector3.zero
		local best, bestT = 1e9, 0
		local t = 0.04
		while t <= cap do
			local p = from + velo * t + Vector3.new(0, -0.5 * grav * t * t, 0)
			local d = flat(p - (root.Position + us * t)).Magnitude
			if d < best then
				best, bestT = d, t
			end
			t += 0.04
		end
		return best, bestT
	end
	Mark.projDodgeAt = Mark.projDodgeAt or {}
	Mark.projSrc = Mark.projSrc or {}
	local function dodgeAt(tag, from, velo, grav, rad, cap)
		if Mark.move.mode == "dribble" then
			return
		end
		local last = Mark.projDodgeAt[tag]
		if last and os.clock() - last < 0.4 then
			return
		end
		local miss, t = closest(from, velo, grav or 0, cap or 0.5)
		if miss > rad then
			return
		end
		local axis = unitOrNil(flat(velo))
		if not axis then
			return
		end
		local right = Vector3.new(-axis.Z, 0, axis.X)
		local side = right:Dot(flat(root.Position - from))
		local sign = (side >= 0) and 1 or -1
		local need = math.clamp(rad + 1.6 - miss, 3.5, 8)
		if math.abs(side + sign * need) < math.abs(side - sign * need) then
			sign = -sign
		end
		local step = right * sign * need
		Mark.stepAway(root, step, "proj")
		Mark.projDodgeAt[tag] = os.clock()
		logFile("proj dodge", tostring(tag), string.format("miss %.2f", miss), string.format("t %.2f", t), string.format("step %.1f", need))
	end
	local rad = radOf(id)
	local g = gravOf(id)
	if proj.Id ~= nil then
		Mark.projSrc[proj.Id] = proj.SourceUserId
		Mark.projRad = Mark.projRad or {}
		Mark.projRad[proj.Id] = rad
		-- decisions are taken every frame by Mark.projTick on the live state (start + ProjectileMovement rows)
		local nowS = Workspace:GetServerTimeNow()
		Mark.projLive = Mark.projLive or {}
		Mark.projLive[proj.Id] = {
			id = proj.Id, item = id, src = proj.SourceUserId, pos = pos, vel = typeof(vel) == "Vector3" and vel or Vector3.zero,
			at = nowS, born = type(proj.StartedAt) == "number" and proj.StartedAt or nowS, rad = rad,
			-- the ice shot's gravity is the server's (grav 45 in every log), not the 0.3 g of the prediction config (58.9): the landing point is what the zone is made of
			grav = (id == "freezeGun" and type(proj.Gravity) == "number" and proj.Gravity > 1) and proj.Gravity or g,
			homing = id == "rocketPunch", throw = type(proj.BoomerangThrow) == "table" and proj.BoomerangThrow or nil,
			ballId = proj.BallId,
		}
		do
			local stN = Mark.projLive[proj.Id]
			stN.fp, stN.fv, stN.ft = stN.pos, stN.vel, stN.born
			Mark.hazAdd(stN)
		end
		logFile("proj start", tostring(id), "from", tostring(shooter and actorName(shooter) or proj.SourceUserId), "dist", string.format("%.1f", flat(pos - root.Position).Magnitude), "spd", string.format("%.0f", typeof(vel) == "Vector3" and vel.Magnitude or 0), "grav", tostring(proj.Gravity), "own", tostring(own))
		return
	end
	-- no id: old one-shot reaction
	if typeof(vel) == "Vector3" and vel.Magnitude >= 8 and id ~= "rocketPunch" then
		dodgeAt(id or "?", pos, vel, g, rad, 1.4)
	end
end

-- ProjectileMovement also sends (serverTime, rows) after the start: row = {Id, Sequence, Position, Velocity, Steering, DetonatesAt}
-- (ProjectileVfx.MovementFields). The old handler ignored everything but ProjectileStart, so a grenade arc and a boomerang
-- return were dodged once from the muzzle and never again.
Mark.projBatch = function(rows, batchAt)
	if type(rows) ~= "table" or not Mark.projLive then
		return
	end
	local nowS = Workspace:GetServerTimeNow()
	local rowAt = type(batchAt) == "number" and batchAt or nowS
	for i = 1, #rows do
		local row = rows[i]
		if type(row) == "table" then
			local st = Mark.projLive[row[1]]
			local p, v = row[3], row[4]
			if st and typeof(p) == "Vector3" then
				st.pos = p
				st.vel = typeof(v) == "Vector3" and v or st.vel
				st.at = nowS
				st.steer = typeof(row[5]) == "Vector3" and row[5] or st.steer
				if type(row[6]) == "number" and row[6] > 0 then
					st.det = row[6]
				end
				-- explosives: the zone follows every correction (a grenade bounces off bodies and the server re-sends it); a
				-- zone that could not be built at the start is built from the first row that can
				if (st.item == "grenade" or st.item == "bazooka" or st.item == "freezeGun") and not (st.det and st.det < nowS - 0.3) then
					st.fp, st.fv, st.ft = p, st.vel, rowAt
					if os.clock() - (st.hazAt or 0) > 0.12 or st.det ~= st.hazDet then
						Mark.hazAdd(st)
					end
				end
			end
		end
	end
end

-- ProjectileSnapshot re-sends every live projectile (ProjectileEffects.ShowProjectileState): a Start that never arrived (the
-- rocket punch the script "did not notice") is recovered here.
Mark.projSnapshot = function(pkt)
	if type(pkt) ~= "table" or type(pkt.Projectiles) ~= "table" then
		return
	end
	for _, p in pkt.Projectiles do
		if type(p) == "table" and p.Id ~= nil and not (Mark.projSeen and Mark.projSeen[p.Id]) then
			logFile("proj snapshot", "recovered", tostring(p.ItemId), tostring(p.Id))
			onProjectile("ProjectileStart", p)
		end
	end
end

Remotes.Get("Items", "ProjectileMovement").OnClientEvent:Connect(function(kind, proj)
	if kind == "ProjectileSnapshot" then
		Mark.projSnapshot(proj)
	elseif kind == "ProjectileStart" then
		onProjectile(kind, proj)
	elseif kind == "ProjectileFinish" then
		if type(proj) == "table" and Mark.projLive and proj.Id ~= nil then
			Mark.projLive[proj.Id] = nil
		end
	elseif type(kind) == "number" and type(proj) == "table" then
		Mark.projBatch(proj, kind)
	end
end)
Remotes.Get("Items", "Effect").OnClientEvent:Connect(function(pkt)
	if type(pkt) == "table" and pkt.Kind == "ProjectileSnapshot" then
		Mark.projSnapshot(pkt)
	elseif type(pkt) == "table" and pkt.Kind == "ProjectileStart" then
		onProjectile(pkt.Kind, pkt.Projectile or pkt)
	elseif type(pkt) == "table" and pkt.Kind == "Explosion" and typeof(pkt.Position) == "Vector3" then
		-- the real blast (Items_Script showExplosion: Position, Radius, SourceUserId). Ours: where it went off against the
		-- ground point SilentAim planned and where the target really was (calibration of the area aim)
		local sh = Mark.areaShot
		local mine = pkt.SourceUserId == LocalPlayer.UserId
		local tgt = mine and sh and sh.model and sh.model:FindFirstChild("HumanoidRootPart")
		logFile("blast real", "from", tostring(pkt.SourceUserId), "at", fmtV(pkt.Position), "r", tostring(pkt.Radius),
			"mine", tostring(mine), "vs plan", (mine and sh) and string.format("%.1f", flat(pkt.Position - sh.G).Magnitude) or "-",
			"target", tgt and string.format("%.1f", (tgt.Position - pkt.Position).Magnitude) or "-")
		if mine and sh then
			sh.logged = true
		end
		-- an enemy blast we predicted: it went off here and now (the overlay plays its shock ring, then drops it)
		for _, ev in Mark.hazEv do
			if ev.kind == "blast" and not ev.boomAt and flat(ev.p - pkt.Position).Magnitude < 8 then
				ev.boomAt, ev.p, ev.t = os.clock(), pkt.Position, Workspace:GetServerTimeNow()
				break
			end
		end
	elseif type(pkt) == "table" and pkt.Kind == "PlacedModelEntrance" then
		-- Items_Script routes this packet to PlacedModelEntrance.Show: {EntranceId, ItemId, PlacerUserId, Model, StartedAt}.
		-- It is the only place the client learns WHO placed a model (the model carries PlacementEntranceId only).
		if pkt.ItemId == "landmines" and pkt.EntranceId ~= nil then
			Mark.mineOwner = Mark.mineOwner or {}
			Mark.mineOwner[pkt.EntranceId] = pkt.PlacerUserId
			local pl = type(pkt.PlacerUserId) == "number" and playerOf(pkt.PlacerUserId)
			logFile("mine placed", "by", pl and actorName(pl) or tostring(pkt.PlacerUserId), "ours", tostring(pl ~= nil and (pl == LocalPlayer or sameTeam(pl))), "entrance", tostring(pkt.EntranceId))
			Mark.mineCache = nil
		end
	elseif type(pkt) == "table" and pkt.Kind == "HeldItemActivate" then
		Mark.onItemActivate(pkt)
	elseif type(pkt) == "table" and (pkt.Kind == "Grapple" or pkt.Kind == "GrappleStop") and type(pkt.UserId) == "number" then
		-- GrapplePull.Start payload {UserId, BallId, StartedAt, PullStartsAt, FlightSeconds}: the hook flies to the BALL,
		-- then pulls him at it (GrappleMotion: 75 st/s, Quad-out ramp 0.5 s, homing on the ball every step)
		Mark.grapples = Mark.grapples or {}
		if pkt.Kind == "GrappleStop" or pkt.UserId == LocalPlayer.UserId then
			Mark.grapples[pkt.UserId] = nil
		else
			local st = tonumber(pkt.StartedAt) or Workspace:GetServerTimeNow()
			Mark.grapples[pkt.UserId] = { pullAt = tonumber(pkt.PullStartsAt) or (st + (tonumber(pkt.FlightSeconds) or 0.3)), at = os.clock() }
			local pl = playerOf(pkt.UserId)
			logFile("grapple seen", pl and actorName(pl) or tostring(pkt.UserId), "pull in", string.format("%.2f", Mark.grapples[pkt.UserId].pullAt - Workspace:GetServerTimeNow()), "enemy", tostring(pl ~= nil and not sameTeam(pl)))
		end
	elseif type(pkt) == "table" and pkt.Kind == "MagnetAim" and type(pkt.UserId) == "number" then
		-- MagnetAim {UserId, IsActive, IsSuspended, EndsAt}: while active the server pulls a LOOSE ball toward him
		Mark.magnets = Mark.magnets or {}
		if pkt.IsActive == false or (type(pkt.EndsAt) == "number" and pkt.EndsAt <= Workspace:GetServerTimeNow()) then
			Mark.magnets[pkt.UserId] = nil
		else
			local m = Mark.magnets[pkt.UserId] or {}
			m.endsAt = tonumber(pkt.EndsAt) or m.endsAt or (Workspace:GetServerTimeNow() + 5)
			m.suspended = pkt.IsSuspended == true
			Mark.magnets[pkt.UserId] = m
		end
	elseif type(pkt) == "table" and type(pkt.Kind) == "string" and pkt.Kind:sub(1, 10) == "OilPatches" then
		if pkt.Kind == "OilPatchesClear" then
			table.clear(Mark.oil)
		elseif pkt.Kind == "OilPatchesRemove" then
			Mark.oilRemove(pkt.Patches)
		else
			Mark.oilAdd(pkt.Patches)
		end
	end
end)

do
	local reticle = require(Client.Interface.Reticle)
	local use = require(Client.Gameplay.ItemUseState)
	if reticle.GetCameraAimRay then
		local oldRay = reticle.GetCameraAimRay
		local oldBare = reticle.GetCameraAimRayWithoutHit
		reticle.GetCameraAimRay = function(...)
			-- Keeper Push goes first: right after OUR release the shot lock (strikeRay: aerial / volley / bicycle) and the
			-- direction spoof still answer this function - the gun went along the SHOT, at the goal, not at the keeper.
			-- oldRay builds the payload from GetCameraRay, which returns the push ray.
			-- a wall press (skillRay.wall, alive only inside our own ActivateEquipped) is never aimed by the push window: a wall
			-- placed within 0.85 s after a push went along the push ray, at the keeper
			if Mark.skillRay and Mark.skillRay.wall then
				return Mark.skillRay
			end
			if Mark.pushAim and os.clock() < Mark.pushAim.untilT then
				return oldRay(...)
			end
			if Mark.skillRay then
				return Mark.skillRay
			end
			local strike = Mark.strikeRay()
			if strike then
				return strike
			end
			local spoof = Mark.sp and Mark.spoofRay()
			if spoof then
				return spoof
			end
			return oldRay(...)
		end
		if oldBare then
			reticle.GetCameraAimRayWithoutHit = oldBare
		end
	end
	if use.SetEquippedItem then
		Mark.itemUse = use
		local oldSet = use.SetEquippedItem
		use.SetEquippedItem = function(item, ...)
			Mark.itemId = item and item.ItemId or nil
			return oldSet(item, ...)
		end
	end
end

-- Equipped item id straight from ItemUseState (u3 upvalue of UsesZoom): the SetEquippedItem hook misses an item
-- equipped before the script loaded.
Mark.equippedId = function()
	local use = Mark.itemUse
	if use and use.UsesZoom then
		local ok, id = Mark.try(upvalue, use.UsesZoom, 2)
		if ok and type(id) == "string" then
			return id
		end
	end
	return Mark.itemId
end

Mark.saDraw = function()
	if not Mark.saCircle then
		local c = newDraw("Circle", 45)
		c.Filled = false
		c.NumSides = 48
		c.Thickness = 1
		c.Transparency = 0.5
		c.Color = COL.Paper
		c.Visible = false
		Mark.saCircle = c
		Mark.saBox = makeLines(8, 1.6, 45)
		local t = newDraw("Text", 46)
		t.Size = 13
		t.Center = true
		t.Outline = true
		t.Font = FONT
		t.Visible = false
		Mark.saText = t
		Mark.saLink = newDraw("Line", 44)
		Mark.saLink.Visible = false
	end
end

-- SilentAim target art: beam muzzle -> chest (ink under-stroke + colour), 4 bright pulses running
-- toward the target (period 0.6 s, white fading into the beam colour), 3 spinning arcs at his feet.
Mark.silentArt = function(seg, muzzle, chest, feet, col, t)
	local hot = Color3.fromRGB(255, 255, 255)
	seg(muzzle, chest, Color3.fromRGB(12, 14, 18), 0.55, 3.2, 44)
	seg(muzzle, chest, col, 0.75, 1.2, 45)
	for n = 0, 3 do
		local f = ((t / 0.6) + n / 4) % 1
		local f2 = math.min(f + 0.06, 1)
		seg(muzzle:Lerp(chest, f), muzzle:Lerp(chest, f2), hot:Lerp(col, f), 1, 2.6, 46)
	end
	if feet then
		Mark.silentRing(seg, feet, col, t)
	end
end

-- Area target art: the blast footprint on the grass where the shot goes off. A filled disc of the real radius (16-piece
-- Triangle fan, projected once per frame), an inked rim, a shock ring running out from the centre every 0.8 s and three
-- turning rim ticks. Appears scaling up from 60 % (0.18 s ease-out), fades out over 0.25 s when the solve is gone;
-- the centre glides to a new point instead of jumping. hide = drop everything at once (item put away).
Mark.areaNew = function()
	local A = { a = 0, at = os.clock(), tris = {}, lines = makeLines(84, 1.4, 44) }
	A.pool = Mark.segPool(A.lines)
	for k = 1, 16 do
		A.tris[k] = newTri(43)
	end
	return A
end
Mark.areaDraw = function(G, R, col, hide, A)
	if not A then
		A = Mark.areaFx or Mark.areaNew()
		Mark.areaFx = A
	end
	local now = os.clock()
	local dt = math.clamp(now - A.at, 0, 0.1)
	A.at = now
	if hide then
		A.a, A.G = 0, nil
	elseif G then
		if not A.G or A.a <= 0.01 then
			A.G, A.born = G, now
		else
			A.G = A.G:Lerp(G, math.min(1, dt * 14))
		end
		A.R, A.col = R, col
		A.a = math.min(1, A.a + dt / 0.18)
	else
		A.a = math.max(0, A.a - dt / 0.25)
	end
	local pool = A.pool
	pool.i = 1
	local nTri = 0
	if A.a > 0.01 and A.G and (A.gal or CFG.DrawSilent ~= false) then
		local cam = Mark.frameCam or Workspace.CurrentCamera
		local grow = 1 - (1 - math.clamp((now - (A.born or now)) / 0.18, 0, 1)) ^ 3
		local r = A.R * (G and (0.6 + 0.4 * grow) or (1 + 0.1 * (1 - A.a)))
		local c, cl, a = A.G + Vector3.new(0, 0.15, 0), A.col, A.a
		local cs = cam:WorldToViewportPoint(c)
		local prev, prevOk = nil, false
		for k = 0, 16 do
			local ang = k / 16 * math.pi * 2
			local p = cam:WorldToViewportPoint(c + Vector3.new(math.cos(ang) * r, 0, math.sin(ang) * r))
			local ok = p.Z > 0.2
			if k > 0 and ok and prevOk and cs.Z > 0.2 then
				nTri += 1
				local tri = A.tris[nTri]
				tri.PointA, tri.PointB, tri.PointC = Vector2.new(cs.X, cs.Y), Vector2.new(prev.X, prev.Y), Vector2.new(p.X, p.Y)
				tri.Color, tri.Transparency, tri.Visible = cl, 0.16 * a, true
			end
			prev, prevOk = p, ok
		end
		local seg = pool.seg
		local ink = Color3.fromRGB(12, 14, 18)
		local function ring(rr, colr, al, th, n)
			local last = nil
			for k = 0, n do
				local ang = k / n * math.pi * 2
				local p = c + Vector3.new(math.cos(ang) * rr, 0, math.sin(ang) * rr)
				if last then
					seg(last, p, colr, al, th, 45)
				end
				last = p
			end
		end
		ring(r, ink, 0.5 * a, 3.6, 24)
		ring(r, cl, 0.95 * a, 1.6, 24)
		local f = (now % 0.8) / 0.8
		ring(r * (1 - (1 - f) ^ 2), Color3.new(1, 1, 1):Lerp(cl, f), (1 - f) * 0.8 * a, 1.4, 18)
		for q = 0, 2 do
			local a0 = now * 1.8 + q * (math.pi * 2 / 3)
			local last = nil
			for s = 0, 3 do
				local ang = a0 + s / 3 * 0.55
				local p = c + Vector3.new(math.cos(ang) * (r + 0.9), 0, math.sin(ang) * (r + 0.9))
				if last then
					seg(last, p, Color3.new(1, 1, 1), a, 2.4, 46)
				end
				last = p
			end
		end
	end
	for k = nTri + 1, 16 do
		A.tris[k].Visible = false
	end
	pool.finish()
end

Mark.saHide = function()
	if Mark.saPool then
		Mark.saPool.finish()
	end
	if Mark.areaFx then
		Mark.areaDraw(nil, 0, nil, true)
	end
	if Mark.saCircle then
		Mark.saCircle.Visible = false
		hideLines(Mark.saBox)
		Mark.saText.Visible = false
		Mark.saLink.Visible = false
	end
end

-- SilentAim lead. Old: pos + velocity * (dist / speed + ping) = a straight line, so any strafe or stop made the aim
-- run ahead of the target and miss. This one keeps a short position history of the picked target and models
-- his steering: velocity persists for an expected time tau (from how often his heading flipped lately), so the
-- expected displacement over the flight is v * tau * (1 - exp(-T / tau)). A straight runner (tau large) gets the
-- full lead, a strafer a fraction of it. The flight time is iterated against the lead point; the target is also seen
-- display-delay + one-way ping behind the server pose.
Mark.projGrav = { freezeGun = 45 } -- measured server gravity of the ice shot (proj start ... grav 45, several logs)
Mark.projSeed = { freezeGun = 77.8 } -- measured muzzle speed (log "proj speed freezeGun 77.6-77.9"); used until we shoot
-- BOOMERANG (dump Modules.Items.Boomerang). It is NOT a straight shot: a fixed loop in the throw's own frame,
--   P(t) = Start + (Forward * x(t) + up x Forward * y(t)) * Range + up * h(t),   Range 70, FlightSeconds 1.93,
-- Forward = the FLAT direction of the aim ray, Start = the throw root CFrame * ReleaseOffset (0, 1.38, -2.92) at the release
-- (ReleaseSeconds 0.067 after the press). With Count > 1 it returns to us (Returns); a single one flies away after the
-- apex. Hit = CombatHitboxes boxes against the swept 4 x 1.8 x 4 box between two path samples (server-side).
-- So the aim is a YAW: the loop rotates rigidly about Start. A point at distance r is on the outbound leg at the time
-- t(r) (the radius of the loop grows to Range at the apex), at the polar angle phi(t) from Forward. For a target D from
-- Start: Forward = unit(D) rotated by phi (complex: F = W * (a + ib) / rho). The target is led with the same velocity model
-- as the other projectiles (Mark.silentLead) over t(r) + release + ping. Local loop sampled once per Returns flag.
Mark.boomTable = function(returns)
	Mark.boomMod = Mark.boomMod or require(Modules.Items.Boomerang)
	Mark.boomTabs = Mark.boomTabs or {}
	local tab = Mark.boomTabs[returns and 1 or 2]
	if tab then
		return tab
	end
	local B = Mark.boomMod
	local th = B.NewThrow(Vector3.zero, { Direction = Vector3.new(0, 0, 1) }, returns, 0)
	local dur = math.min(B.GetEndTime(th), 2.2)
	local n = math.floor(dur / 0.025)
	tab = { a = {}, b = {}, h = {}, rho = {}, dt = 0.025, iMax = 1, n = n }
	for i = 0, n do
		local p = B.GetPosition(th, i * 0.025, nil)
		local a, b = p.Z, p.X -- Forward = +Z here, up x Forward = +X
		tab.a[i], tab.b[i], tab.h[i], tab.rho[i] = a, b, p.Y, math.sqrt(a * a + b * b)
	end
	-- outbound leg = up to the first maximum of the radius
	local im = 0
	while im < n and tab.rho[im + 1] >= tab.rho[im] - 1e-6 do
		im += 1
	end
	tab.iMax = im
	Mark.boomTabs[returns and 1 or 2] = tab
	return tab
end

-- time on the outbound leg at which the loop is r studs from Start (nil beyond its reach)
Mark.boomTimeAt = function(tab, r)
	if r > tab.rho[tab.iMax] then
		return nil
	end
	local lo, hi = 0, tab.iMax
	while hi - lo > 1 do
		local m = (lo + hi) // 2
		if tab.rho[m] < r then
			lo = m
		else
			hi = m
		end
	end
	local r0, r1 = tab.rho[lo], tab.rho[hi]
	local u = r1 > r0 and (r - r0) / (r1 - r0) or 0
	return (lo + u) * tab.dt, lo, u
end

Mark.boomReturns = function()
	local slot = Mark.slotOfItem("boomerang")
	local slots = slot and Mark.itemSlots()
	local e = slots and slots[slot]
	return type(e) == "table" and (e.Count or 1) > 1
end

-- -> Forward (flat unit), info { S, P, t, r, pts } or nil (out of reach: the player's own aim stays)
Mark.boomAim = function(pick, cam, ping, root)
	local returns = Mark.boomReturns()
	local tab = Mark.boomTable(returns)
	local B = Mark.boomMod
	-- the throw starts from the body the server has at the release: our pose + what we travel by then
	local S = B.GetReleasePosition(root.CFrame) + flat(root.AssemblyLinearVelocity) * (B.ReleaseSeconds + ping * 0.5)
	local function flightFn(P)
		local t = Mark.boomTimeAt(tab, flat(P - S).Magnitude)
		return (t or tab.iMax * tab.dt) + B.ReleaseSeconds
	end
	local P = Mark.silentLead(pick, cam.CFrame.Position, 100, ping, flightFn)
	local W = flat(P - S)
	local r = W.Magnitude
	local t, i, u = Mark.boomTimeAt(tab, r)
	if not t or r < 4 then
		return nil
	end
	local a = tab.a[i] + (tab.a[i + 1] - tab.a[i]) * u
	local b = tab.b[i] + (tab.b[i + 1] - tab.b[i]) * u
	local rho = math.sqrt(a * a + b * b)
	local wx, wz = W.X / r, W.Z / r
	-- F = W * (a + i b) / rho  (x = X, z = Z)
	local fx = (wx * a - wz * b) / rho
	local fz = (wx * b + wz * a) / rho
	local f = Vector3.new(fx, 0, fz)
	return f, { S = S, P = P, t = t, r = r, tab = tab, returns = returns }
end

-- the loop in the world for forward f (ink bed + colour), a spark where it meets him
-- Boomerang aim art = the SilentAim tracer bent along the throw: ink bed + core from the muzzle down the real loop to the
-- meeting point, hot pulses running out along it at the throw's own pace (one pass = its flight time to him), the
-- SilentAim split ring at his feet, and the rest of the loop (the way back) as a faint dashed ghost.


-- the SilentAim target ring: three split arcs turning at his feet
Mark.silentRing = function(seg, feet, col, t)
	local R = 2.2
	for arc = 0, 2 do
		local a0 = t * 2.4 + arc * (math.pi * 2 / 3)
		local prev = nil
		for s = 0, 5 do
			local ang = a0 + s / 5 * (math.pi * 2 / 3 * 0.7)
			local p = feet + Vector3.new(math.cos(ang) * R, 0, math.sin(ang) * R)
			if prev then
				seg(prev, p, col, 1, 2.2, 46)
			end
			prev = p
		end
	end
end


-- AREA WEAPONS (bazooka, freeze gun). These hit a spot on the ground, not a body: aimed at his chest the shot flies on
-- past him when he steps and goes off far behind. So the aim point is the GROUND under where he will be.
--   bazooka: ProjectileVfx.getLaunchVelocity = unit(TargetPosition - muzzle) * Speed, Gravity = workspace.Gravity;
--            TargetPosition is the game's own aim hit of our ray (Reticle.GetAimHit on the Map + hitboxes), or
--            Origin + Direction * 1000 when the ray hits nothing. Blast = ItemHitSettings.ExplosionRadius (14, the
--            server sends it in the "Explosion" effect) where it touches the ground or the first body.
--   freeze gun: ProjectileAim.GetPeakVelocity puts the LANDING (ground height) on the screen point of the ray, Speed 78,
--            Gravity 0.3 g. The freeze radius is not in the dump (CFG.FreezeRadius, unconfirmed).
-- Returns the ray to send, the ground point G, the flight time, the launch we expect and the radius - or nil (out of
-- reach, or G so close that the blast takes us too: then the player's own aim stays).
Mark.areaItems = { bazooka = true, freezeGun = true }
Mark.areaRadius = function(id)
	if id == "bazooka" then
		return Mark.blastR()
	end
	return CFG.FreezeRadius or 8
end
Mark.areaAim = function(id, pick, cam, ping, root)
	Mark.projVfx = Mark.projVfx or require(Modules.Items.ProjectileVfx)
	local cfg = Mark.projVfx.PredictionConfigs[id]
	if not (cfg and cfg.Speed) then
		return nil
	end
	Mark.projAimMod = Mark.projAimMod or require(Modules.Items.ProjectileAim)
	Mark.fieldMod = Mark.fieldMod or require(Modules.Gameplay.FieldSettings)
	Mark.heldItems = Mark.heldItems or require(Modules.Items.HeldItems)
	Mark.hitScan = Mark.hitScan or require(Modules.Items.HitScan)
	local att = Mark.heldItems.FindMuzzle(LocalPlayer.Character, id)
	local muzzle = att and att.WorldPosition or (root.Position + Vector3.new(0, 1.2, 0))
	local camCF = cam.CFrame
	local camPos = camCF.Position
	local spd = (Mark.projSpeed and Mark.projSpeed[id]) or cfg.Speed
	-- DROP: the gravity the server really flies (and solves the launch with) is the measured projectile gravity, NOT
	-- cfg.Gravity (workspace.Gravity * 0.3 read at module load = 58.9; the log: "proj start freezeGun ... grav 45").
	-- Planned with 58.9 the very first shot was off by 25.5 deg (log: "silent area shot ... launch err 25.5 deg"), after
	-- one measured shot 1.7..5.8 deg - that is why it "stopped compensating the drop": no shot yet = the wrong number.
	-- Mark.projGrav is seeded with the measured 45 and updated from EVERY freeze-gun start we see, ours or not.
	local g = (Mark.projGrav and Mark.projGrav[id]) or cfg.Gravity or 0
	local function groundAt(p)
		local gy = Mark.fieldMod.GetGroundYAt(p)
		return type(gy) == "number" and gy or root.Position.Y - 3
	end
	-- the low arc muzzle -> G: launch unit vector and flight time (nil = out of reach)
	local function lowArc(G)
		local toG = flat(G - muzzle)
		local D = toG.Magnitude
		local u = unitOrNil(toG)
		if not u then
			return nil
		end
		if g <= 0 then
			local L = unitOrNil(G - muzzle)
			return L, (G - muzzle).Magnitude / spd
		end
		local v2, dy = spd * spd, G.Y - muzzle.Y
		local disc = v2 * v2 - g * (g * D * D + 2 * dy * v2)
		if disc < 0 then
			return nil
		end
		local th = math.atan((v2 - math.sqrt(disc)) / (g * D))
		return u * math.cos(th) + Vector3.new(0, math.sin(th), 0), D / (spd * math.cos(th))
	end
	-- the ray that makes the game launch along L, checked with the game's own aim hit (TargetPosition)
	local function rayFor(L)
		local Q
		if L.Y < -0.02 then
			Q = muzzle + L * ((groundAt(muzzle + flat(L) * 10) - muzzle.Y) / L.Y)
		else
			Q = muzzle + L * 600
		end
		local dd = unitOrNil(Q - camPos)
		if not dd then
			return nil
		end
		local hit = Reticle.GetAimHit(Ray.new(Mark.hitScan.GetForwardAimOrigin(camPos, dd, root.Position), dd))
		local T = hit and hit.Position or (camPos + dd * 1000)
		return dd, unitOrNil(T - muzzle)
	end
	-- where a launch along Lr comes down
	local function landOf(Lr)
		local t = 0
		while t < 3 do
			t += 0.01
			local q = muzzle + Lr * (spd * t) + Vector3.new(0, -0.5 * g * t * t, 0)
			if q.Y <= groundAt(q) + 0.3 then
				return q, t
			end
		end
		return nil
	end
	local flightFn
	if id == "freezeGun" then
		flightFn = function(P)
			local G = Vector3.new(P.X, groundAt(P), P.Z)
			local dd = unitOrNil(G - camPos)
			local dir = dd and Mark.projAimMod.GetPeakDirection(muzzle, { Origin = camPos, Direction = dd, CameraCFrame = camCF }, spd, g, groundAt(muzzle))
			local h = typeof(dir) == "Vector3" and flat(dir).Magnitude * spd or 0
			if h < 1e-3 then
				return flat(G - muzzle).Magnitude / spd
			end
			return flat(G - muzzle).Magnitude / h
		end
	else
		flightFn = function(P)
			local _, t = lowArc(Vector3.new(P.X, groundAt(P), P.Z))
			return t or flat(P - muzzle).Magnitude / spd
		end
	end
	local P = Mark.silentLead(pick, camPos, spd, ping, flightFn)
	local G = Vector3.new(P.X, groundAt(P), P.Z)
	local R = Mark.areaRadius(id)
	if flat(G - root.Position).Magnitude < R + 1.5 then
		return nil -- the blast would take us: the player's own aim (a rocket jump at his feet is his call)
	end
	if id == "freezeGun" then
		local dd = unitOrNil(G - camPos)
		local dir = dd and Mark.projAimMod.GetPeakDirection(muzzle, { Origin = camPos, Direction = dd, CameraCFrame = camCF }, spd, g, groundAt(muzzle))
		if typeof(dir) ~= "Vector3" then
			return nil
		end
		return dd, G, { t = flightFn(P), launch = dir.Unit, R = R, D = flat(G - muzzle).Magnitude }
	end
	local L, t = lowArc(G)
	if not L then
		return nil
	end
	-- the game's aim hit can differ from the point we meant (a wall, a hitbox on the line): steer the ray by the miss
	local aimG, dd, Lr, land = G, nil, nil, nil
	for _ = 1, 3 do
		dd, Lr = rayFor(L)
		if not (dd and Lr) then
			return nil
		end
		land = landOf(Lr)
		local miss = land and flat(G - land) or nil
		if not miss or miss.Magnitude < 1.5 then
			break
		end
		aimG = aimG + miss
		L = lowArc(Vector3.new(aimG.X, groundAt(aimG), aimG.Z))
		if not L then
			return nil
		end
	end
	if not land or flat(land - G).Magnitude > R * 0.5 then
		return nil
	end
	return dd, G, { t = t, launch = Lr, R = R, D = flat(G - muzzle).Magnitude, land = land }
end

-- after our freeze shot lands: who is frozen and how far from the landing point (calibration of CFG.FreezeRadius)
Mark.areaCheck = function()
	local sh = Mark.areaShot
	if not sh or sh.logged or Workspace:GetServerTimeNow() < sh.tLand + 0.35 then
		return
	end
	sh.logged = true
	if sh.id ~= "freezeGun" then
		return
	end
	local parts = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and ActorTargeting.GetActorRoot(actor)
		if r then
			local dG = flat(r.Position - sh.G).Magnitude
			if dG < 25 then
				local fu = model:GetAttribute("FrozenUntil") or actor:GetAttribute("FrozenUntil")
				parts[#parts + 1] = string.format("%s %.1f %s", actorName(actor), dG, (type(fu) == "number" and fu > Workspace:GetServerTimeNow()) and "FROZEN" or "-")
			end
		end
	end
	logFile("silent area freeze", "at", fmtV(sh.G), #parts > 0 and table.concat(parts, " | ") or "nobody within 25")
end

Mark.silentLead = function(pick, camPos, spd, ping, flightFn)
	local ch = pick.Parent
	local now = os.clock()
	local tr = Mark.silentTr
	if not tr or tr.ch ~= ch then
		tr = { ch = ch, s = {} }
		Mark.silentTr = tr
	end
	local s = tr.s
	local cur = flat(pick.Position)
	if #s == 0 or now - s[#s].t >= 0.012 then
		s[#s + 1] = { t = now, p = cur }
		while #s > 2 and now - s[1].t > 1.6 do
			table.remove(s, 1)
		end
	end
	local function velOver(w)
		local n = #s
		if n < 2 then
			return Vector3.zero
		end
		local i = n
		while i > 1 and now - s[i - 1].t <= w do
			i -= 1
		end
		local dt = s[n].t - s[i].t
		if dt < 0.04 then
			return Vector3.zero
		end
		return (s[n].p - s[i].p) / dt
	end
	local vS = velOver(0.16)
	local vL = velOver(0.5)
	-- heading flips in the last ~1.5 s (segments of ~0.12 s; >35 deg between neighbours at real speed)
	local flips, span = 0, 0
	do
		local seg, last = {}, nil
		for i = 1, #s do
			if not last or s[i].t - last.t >= 0.12 then
				if last then
					local v = (s[i].p - last.p) / (s[i].t - last.t)
					seg[#seg + 1] = v
				end
				last = s[i]
			end
		end
		for i = 2, #seg do
			local a, b = seg[i - 1], seg[i]
			if a.Magnitude > 3 and b.Magnitude > 3 then
				if a.Unit:Dot(b.Unit) < 0.82 then
					flips += 1
				end
			elseif (a.Magnitude > 3) ~= (b.Magnitude > 3) then
				flips += 1 -- start / stop counts as a change of plan
			end
		end
		span = #s >= 2 and math.clamp(s[#s].t - s[1].t, 0.3, 1.6) or 0.3
	end
	local tau = math.clamp(span / (flips + 0.6), 0.22, 3.2)
	-- the short window is the freshest heading; blend toward the long one only when they disagree on speed
	local v = vS
	if vS.Magnitude < 1.5 and vL.Magnitude > 3 then
		v = vL * 0.3 -- just stopped: a little residual
	end
	local lag = (CharacterMotion.GetDisplayDelaySeconds(ch) or 0) + ping
	local P = cur
	local T = 0
	for _ = 1, 3 do
		local flight = flightFn and flightFn(Vector3.new(P.X, pick.Position.Y, P.Z)) or (Vector3.new(P.X, pick.Position.Y, P.Z) - camPos).Magnitude / spd
		T = flight + lag
		P = cur + v * (tau * (1 - math.exp(-T / tau)))
	end
	Mark.silentInfo = { tau = tau, flips = flips, T = T, lead = (P - cur).Magnitude, speed = v.Magnitude }
	return Vector3.new(P.X, pick.Position.Y, P.Z)
end

-- AutoWall. What the dump says a barricade is (PlaceDownPlacement, BarricadeStrikes, Physics, CollisionGroups):
--   * it spawns PlacementForwardDistance 5 ahead of the HRP the SERVER has when the press arrives, along the flat aim
--     direction, facing it (CFrame.lookAt(ground, ground + Forward)), clamped into the field and pushed out of the goals
--     (PlaceDownPlacement.Resolve with PlacementContain). Logs: 11.5 wide, 6.4 high, 1.5-3.4 thick; seen 0.11-0.14 s
--     after the press at ping ~0.08, landing 4.2-5.1 from where we stood at the press. The old code aimed from our
--     position LED by our velocity * (ping + 0.08): every wall landed 3.7-5 studs off its plan ("aimed" in the log).
--   * it is a solid: the ball bounces off it (Physics BarricadeNormalRetention), players collide with it, a kick box
--     breaks it (BarricadeStrikes), a slide into it is a BarricadeHit. No stun anywhere in the dump and none in the logs
--     ("stun false" every time): placing it ON a man does nothing, the "overlap" trigger is gone.
-- So a wall is a plane segment, and one solver (Mark.wallSolve) finds the aim yaw whose segment the threat's path crosses
-- after the wall exists: a shot into our goal, a projectile, a slide at us, the man chasing our ball, the carrier's run.
Mark.wallWatch = function()
	local p = Mark.wallPend
	if not p then
		return
	end
	local now = os.clock()
	if now - p.at > 1.6 then
		Mark.wallPend = nil
		logFile("wall result", "no barricade seen in 1.6 s", p.kind)
		return
	end
	if not p.seenAt then
		local world = workspace:FindFirstChild("Misc")
		world = world and world:FindFirstChild("Items")
		if not world then
			return
		end
		for _, inst in world:GetChildren() do
			if inst:GetAttribute("PlacedItemId") == "barricades" and not p.before[inst] then
				p.seenAt = now
				local pos, size
				if inst:IsA("Model") then
					local cf, sz = inst:GetBoundingBox()
					pos, size = cf.Position, sz
				else
					pos, size = inst.Position, inst.Size
				end
				p.wallPos = pos
				logFile("wall placed", "dt", string.format("%.2f", now - p.at), "kind", p.kind, "size", fmtV(size), "fromUs", string.format("%.1f", flat(pos - p.us).Magnitude), "aimed", string.format("%.1f", flat(p.W - pos).Magnitude))
				break
			end
		end
		return
	end
	if now - p.seenAt < 0.45 then
		return
	end
	Mark.wallPend = nil
	if not p.model then
		local alive = 0
		for _ in Mark.projLive or {} do
			alive += 1
		end
		logFile("wall result", p.kind, "projectiles still live", alive, "ball", fmtV(Renderer.GetPosition() or Vector3.zero))
		return
	end
	-- a man: still on his side of the wall plane = it held him
	local tp = CharacterMotion.GetPosition(p.model) or p.wallPos
	local side = flat(tp - p.wallPos):Dot(p.u)
	Mark.teleAdd("wall." .. p.kind, side > 0)
	logFile("wall result", p.kind, p.name, "side", string.format("%.1f", side), "dist", string.format("%.1f", flat(tp - p.wallPos).Magnitude), side > 0 and "held" or "passed")
end

-- BarricadeAddon: a wall placed so that an incoming projectile / charged shot hits IT. The wall spawns exactly 5 studs ahead of
-- us along the aim ray (PlaceDownPlacement PlacementForwardDistance), so the wall can only stop what crosses the circle of radius
-- 5 around where we stand when it exists: aim = toward the crossing point of the path with that circle. Timing: the wall is
-- there ping + WallLatency (calibrate from `wall placed dt`) after the press, plus a margin; the path must reach the circle
-- later than that, else the caller falls back to the dodge / pass. Needs the barricades item in hand (placeWall).
-- pathFn(t) = predicted position t seconds from now (nil before it exists). Returns true when the wall was placed.
-- Item slots (Client.Interface.Items keeps them in the 3rd upvalue of UpdateState: { [i] = { ItemId, Count } }).
Mark.itemSlots = function()
	local Items = Mark.itemsMod
	if not Items then
		local mod = require(Client.Interface.Items)
		if not mod.UpdateState then
			return nil
		end
		Items = mod
		Mark.itemsMod = mod
	end
	local sc = Mark.slotsCache
	if sc and os.clock() - sc.at < 0.2 then
		return sc.slots
	end
	local okU, slots = Mark.try(upvalue, Items.UpdateState, 3)
	if okU and type(slots) == "table" then
		if not Mark.slotsLogged or os.clock() - Mark.slotsLogged > 20 then
			local parts = {}
			for i = 1, 4 do
				local e = slots[i]
				parts[#parts + 1] = i .. "=" .. ((type(e) == "table" and tostring(e.ItemId)) or "-")
			end
			local changed = table.concat(parts, " ")
			if changed ~= Mark.slotsLast then
				Mark.slotsLast = changed
				logFile("item slots", changed)
			end
			Mark.slotsLogged = os.clock()
		end
		Mark.slotsCache = { at = os.clock(), slots = slots }
		return slots
	end
	return nil
end

Mark.slotOfItem = function(id)
	local s = Mark.itemSlots()
	if not s then
		return nil
	end
	for i = 1, 4 do
		local e = s[i]
		if type(e) == "table" and e.ItemId == id then
			return i
		end
	end
	return nil
end

-- Press an item slot like the keyboard does: the game's own UserInputService.InputBegan handler (Items script) gets the
-- Item<i> input and runs useSlot(i) - equip, or unequip when it is already the equipped one.
Mark.pressSlot = function(i)
	local input = Controls.CreateInput("Item" .. tostring(i))
	local UIS = game:GetService("UserInputService")
	local okC, conns = Mark.try(getconnections, UIS.InputBegan)
	if not (okC and type(conns) == "table") then
		return false, "noconns"
	end
	local fallback = nil
	for _, c in conns do
		local f = c.Function
		if type(f) == "function" then
			local okS, src = Mark.try(debug.info, f, "s")
			if okS and type(src) == "string" then
				if src:match("Gameplay%.Items$") then
					task.spawn(f, input, false)
					return true
				elseif src:match("%.Items$") and not src:find("Interface", 1, true) then
					fallback = fallback or f
				end
			end
		end
	end
	if fallback then
		task.spawn(fallback, input, false)
		return true
	end
	return false, "nohandler"
end

-- ==================================================================================================================
-- ITEM NOW: equip + fire an item in ONE frame (AutoShield, Keeper Push). Two layers, the first that works:
--   game  Mark.pressSlot runs the Items script's own useSlot synchronously (equip is in hand the same frame, as for
--         the barricades), then ItemUseState.ActivateEquipped -> fireEquipped (its payload, hit query, gun sequence).
--   raw   the client gates of that path (useSlot: Shoot/Pass charging, ActionLocks equip block, ragdoll, replay;
--         fireEquipped: an item already fired) are client-side only: the same two requests go out directly on the Items
--         Request remote - ItemCommands.UseSlot(slot, id) and ItemCommands.FireEquipped(aimRay, serverTime, id2, itemId,
--         ExpectedEquipActionId = id), ids from the script's own nextItemActionId (ItemUseState upvalue, so the
--         counter stays in step). Gun follow-ups (flintlock ShotCount 3, 0.25 s apart) as ContinueGunSequence.
--         Whether the server takes a FireEquipped whose EquipActionId it has just received in the same batch is NOT in
--         the dump: logged as "item raw".
-- aimFn (optional) = world point to hit; while it is live the GetCameraRay hook returns a ray at it (the game builds
-- the hit query / payload from that ray, exactly like SilentAim).
-- ==================================================================================================================
Mark.findUp = function(fn, name)
	if type(fn) ~= "function" then
		return nil
	end
	for i = 1, 60 do
		local ok, v = Mark.try(upvalue, fn, i)
		if not ok then
			break
		end
		if type(v) == "function" then
			local okN, n = Mark.try(debug.info, v, "n")
			if okN and n == name then
				return v
			end
		end
	end
	return nil
end

Mark.itemRaw = function(id, slot, tag)
	local use = Mark.itemUse
	if not Mark.itemNextId then
		local fe = use and Mark.findUp(use.ActivateEquipped, "fireEquipped")
		Mark.itemNextId = fe and Mark.findUp(fe, "nextItemActionId") or false
	end
	local nextId = Mark.itemNextId
	if not nextId or not slot then
		logFile("item raw", tag, id, "no", nextId and "slot" or "nextItemActionId")
		return false
	end
	Mark.itemCmds = Mark.itemCmds or require(Modules.Items.ItemCommands)
	Mark.itemReq = Mark.itemReq or Remotes.GetGroup("Items").Request
	local C, req = Mark.itemCmds, Mark.itemReq
	local equipped = use and use.IsEquipped and use.IsEquipped() and Mark.equippedId() == id
	if equipped then
		-- in hand and the game refused to fire it (already fired / its own lifecycle): a UseSlot now would UNEQUIP it
		logFile("item raw", tag, id, "no", "in hand, refused by the game")
		return false
	end
	local eq = nextId()
	req:FireServer(C.UseSlot(slot, eq))
	local q = Reticle.BuildAimHitQuery and Reticle.BuildAimHitQuery() or nil
	local ray = Reticle.GetCameraAimRay(q)
	local fa = nextId()
	local t0 = Workspace:GetServerTimeNow()
	req:FireServer(C.FireEquipped(ray, t0, fa, id, eq, false, false))
	Mark.ssg = Mark.ssg or require(Modules.Items.SingleShotGun)
	local cfgG = Mark.ssg.GetConfig(id)
	local n = cfgG and (cfgG.ShotCount or 1) or 1
	for i = 2, n do
		task.delay(Mark.ssg.GetShotDelaySeconds(cfgG, i), function()
			local q2 = Reticle.BuildAimHitQuery and Reticle.BuildAimHitQuery() or nil
			req:FireServer(C.ContinueGunSequence(Reticle.GetCameraAimRay(q2), Workspace:GetServerTimeNow(), fa, i, id, eq, false))
		end)
	end
	logFile("item raw", tag, id, "slot", slot, "equip", tostring(eq), "fire", fa, "shots", n, "equip+fire")
	return true
end

Mark.itemNow = function(id, tag, aimFn)
	local use = Mark.itemUse
	if not (use and use.ActivateEquipped) then
		return false, "no ItemUseState"
	end
	local now = os.clock()
	Mark.itemNowAt = Mark.itemNowAt or {}
	if now - (Mark.itemNowAt[id] or 0) < 0.6 then
		return false, "cooldown"
	end
	local inHand = use.IsEquipped and use.IsEquipped() and Mark.equippedId() == id
	local slot = Mark.slotOfItem(id)
	if not inHand and not slot then
		return false, "not owned"
	end
	Mark.itemNowAt[id] = now
	if aimFn then
		Mark.pushAim = { fn = aimFn, untilT = now + 0.85, at = now, id = id }
	end
	if not inHand then
		Mark.pressSlot(slot)
		inHand = use.IsEquipped and use.IsEquipped() and Mark.equippedId() == id
	end
	if inHand and use.ActivateEquipped() then
		logFile("item now", tag, id, "game path")
		return true
	end
	return Mark.itemRaw(id, slot, tag), "raw"
end

-- AUTOSHIELD (Skills > AutoShield): the forcefield (ItemInvulnerability: item hits, MaxHits 1) when an item hit is
-- coming and the other answers are worse. Never as the keeper (the user's rule: the keeper's shield is wasted). Not
-- while one is already up (ItemInvulnerableUntil on our character).
Mark.shieldUp = function()
	local ch = LocalPlayer.Character
	local u = ch and ch:GetAttribute("ItemInvulnerableUntil")
	return type(u) == "number" and u > Workspace:GetServerTimeNow()
end
-- the forcefield exists StatusActivationDelaySeconds (AuraItems, 0.25 s) after the server takes the press (+ one-way ping):
-- a hit sooner than that goes through. The old gates were "hit later than ping/2" (the shield was always up 0.2 s late:
-- "AutoShield does nothing").
Mark.shieldReady = function()
	Mark.auraMod = Mark.auraMod or require(Modules.Items.AuraItems)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	return Mark.auraMod.StatusActivationDelaySeconds + ping * 0.5 + 0.06
end
Mark.shieldNow = function(why, tLeft)
	if not CFG.AutoShield or Mark.meKeeper() or Mark.shieldUp() then
		return false
	end
	if tLeft and tLeft < Mark.shieldReady() then
		return false, "late"
	end
	if not (Mark.slotOfItem("forcefield") or (Mark.itemUse and Mark.itemUse.IsEquipped and Mark.itemUse.IsEquipped() and Mark.equippedId() == "forcefield")) then
		return false
	end
	local ok, how = Mark.itemNow("forcefield", "shield " .. why)
	logFile("shield", why, ok and "up" or "no", tostring(how or ""))
	return ok
end
-- ROCKET PUNCH, preemptive: it homes on the BALL (ProjectileHoming PointHomingBall), i.e. on us while we carry it. An
-- enemy holding it (HeldItems rig, lifecycle 0) inside ShieldRocketDist fires before any reaction can land: the shield
-- goes up now, not when the punch is in the air.
Mark.shieldTick = function(root)
	if not (CFG.AutoShield and CFG.ShieldRocket ~= false) or liveOwnerId() ~= LocalPlayer.UserId or Mark.meKeeper() or Mark.shieldUp() then
		return
	end
	local maxD = CFG.ShieldRocketDist or 24
	for _, model in Mark.models() do
		local a = Actors.GetFromCharacter(model)
		if a and a ~= LocalPlayer and not sameTeam(a) and type(a.UserId) == "number" then
			local r = ActorTargeting.GetActorRoot(a)
			if r and (r.Position - root.Position).Magnitude <= maxD and Mark.heldLauncher(a.UserId) == "rocketPunch" then
				Mark.shieldNow(string.format("rocketPunch held by %s d %.1f", actorName(a), (r.Position - root.Position).Magnitude))
				return
			end
		end
	end
end

-- KEEPER PUSH (Skills > Keeper Push). A gun hit (flintlock / shotgun: ViolenceDash knock-back, the keeper flies off his
-- line for ~1-1.5 s) on the enemy keeper the moment a shot that goes in is coming: our release, or a teammate's charge
-- (his replicated charge path, Mark.chargeShot). Conditions:
--   the shot path crosses the enemy mouth (inside the posts / under the bar);
--   the keeper (player or NPC, Mark.foeKeeper) holds the goal: within GunPushKeeperZone of the mouth segment;
--   he is in range of the gun we have: shotgun (12 pellets in 8 deg - only close) <= GunPushShotgunRange, flintlock
--   (single accurate pellet x3) <= GunPushFlintRange;
--   DEPTH: the knock-back goes along our line to him. A push whose path (GunPushTravel studs) runs over the point
--   where the ball crosses while he stays in front of the line throws him INTO the shot - skipped;
--   not down / not shielded (ItemInvulnerableUntil).
-- GUN KNOCK WINDOW. A gun hit throws the target by KnockbackMotion: the speed decays and the motion lasts ln(1 + v / 26) s
-- (v = the speed of the hit; the log's "we hit victim ... vel" gives flintlock 25 (0.67 s, ~7.6 st) and shotgun 37 (0.88 s)). The
-- flintlock fires ShotCount 3 shots ShotIntervalSeconds 0.25 apart (SingleShotGun dump) and every one hit in the log (0.21 /
-- 0.48 / 0.73 s after the press): the keeper is held from the first hit to the last hit + the knock-back. A push fired while
-- the ball is farther away than that holds him for nothing - log: a roll shot at a keeper the ball reached 1.60 s later, the
-- hold ended at ~1.4 s ("the last shot for no reason"). Speeds are observed, not from the dump.
-- Which gun at distance d: the shotgun inside GunPushShotgunRange (the user's setting, no hidden cap: the v190 cap of 50 st was
-- invented from three shots - his SilentAim shotgun hits from far away), else the flintlock inside GunPushFlintRange.
Mark.pushGun = function(d, haveShotgun, haveFlint)
	if haveShotgun and d <= (CFG.GunPushShotgunRange or 22) then
		return "shotgun"
	end
	if haveFlint and d <= (CFG.GunPushFlintRange or 70) then
		return "flintlock"
	end
	return nil
end
Mark.gunKnock = { flintlock = { v = 25, shots = 3, gap = 0.25 }, shotgun = { v = 37, shots = 1, gap = 0 } }
-- RECOIL NOISE (Keeper Push, the revolver = flintlock: 3 shots). Three shots into one pixel read as a script: each shot gets a small
-- offset on the aim point - sideways at random, and a rise that grows with the shot (a gun climbs). One random draw per 0.125 s
-- bucket since the push started (the shots are 0.25 s apart, so each lands in its own bucket; the same shot asked twice in a frame
-- gets the same offset). r = the spread in studs at the target (CFG.GunPushRecoil, 0 = off); a single-shot gun is never touched.
-- Worst case lateral r, rise 1.3 r: a keeper's body is ~4 studs wide, so r 0.5 keeps every shot on him (guessed, not measured).
Mark.recoilAim = function(pa, P, o, r, now, rnd)
	local g = pa.id and Mark.gunKnock[pa.id]
	if r <= 0 or not g or g.shots < 2 then
		return P
	end
	local fwd = unitOrNil(flat(P - o))
	if not fwd then
		return P
	end
	local b = math.floor((now - pa.at) / 0.125)
	pa.noise = pa.noise or {}
	local e = pa.noise[b]
	if not e then
		e = { lat = (rnd() * 2 - 1) * r, rise = r * 0.25 * math.min(b, 4) + rnd() * r * 0.3 }
		pa.noise[b] = e
	end
	return P + Vector3.new(-fwd.Z, 0, fwd.X) * e.lat + Vector3.new(0, e.rise, 0)
end
Mark.pushSpan = function(gun)
	local g = Mark.gunKnock[gun]
	return (g.shots - 1) * g.gap + math.log(1 + g.v / 26)
end
-- tb: seconds until the ball reaches him; tLand: seconds until the first hit lands. "late" = the ball is there before the
-- push; "early" = he is free again before the ball (0.15 s margin); else "ok".
Mark.pushWindow = function(gun, tb, tLand)
	if tb < tLand + 0.1 then
		return "late"
	end
	if tb > tLand + Mark.pushSpan(gun) - 0.15 then
		return "early"
	end
	return "ok"
end
-- when to press so the hold is on the ball: the first hit lands at tb - 0.3 of the span (never sooner than `delay`, never
-- later than 2.5 s)
Mark.pushFireIn = function(gun, tb, ping, delay)
	return math.clamp(tb - 0.3 * Mark.pushSpan(gun) - ping * 0.5, delay, 2.5)
end

-- The keeper's dive is a committed motion (GoalkeeperDive: Distance 20, DurationSeconds 0.875, he is back in control after
-- MovementRestoreStartsAtSeconds 1.125 + MovementRestoreSeconds 0.5): while it runs or he recovers a push changes nothing
-- he could still decide (user: "it shoots the keeper after his dive"). t = seconds since his dive started.
Mark.diveBusy = function(t)
	return t ~= nil and t >= 0 and t < 1.125 + 0.5
end

-- seconds since this enemy keeper started a dive, or nil. Players: the GoalkeeperDiveStarted stamp; an NPC keeper moves by
-- the server, so his body speed (kpTrack, > 35 st/s = the dive burst) and the wall-trap dive record stand for it.
Mark.keeperDiveAge = function(k)
	local now = os.clock()
	if not k.npc then
		local at = Mark.foeDive and Mark.foeDive[k.key]
		return at and now - at or nil
	end
	local td = Mark.trapDive
	if td and td.uid == k.key then
		return now - td.at + (td.el0 or 0)
	end
	local tr = Mark.kpTrack
	if tr and tr.key == k.key and tr.vK and tr.vK.Magnitude > 35 then
		return 0.2
	end
	return nil
end

Mark.gunPushTry = function(root, tag, key, pts, ts)
	if not CFG.GunPush or not pts or #pts < 2 then
		return false
	end
	Mark.gunPushKeys = Mark.gunPushKeys or {}
	if Mark.gunPushKeys[key] then
		return false
	end
	local g = enemyGoalPart()
	local lb, lt, rb = goalMouthCorners(g)
	if not (lb and lt and rb) then
		return false
	end
	local mouth = (lb + rb) * 0.5
	local side = unitOrNil(flat(rb - lb))
	if not side then
		return false
	end
	local half = flat(rb - lb).Magnitude * 0.5
	local out = Vector3.new(-side.Z, 0, side.X)
	if flat(pts[1] - mouth):Dot(out) < 0 then
		out = -out
	end
	local C, ci = nil, nil
	for i = 2, #pts do
		local a1 = flat(pts[i] - mouth):Dot(out)
		if a1 <= 0.3 then
			local a0 = flat(pts[i - 1] - mouth):Dot(out)
			local q = pts[i - 1]:Lerp(pts[i], math.clamp((a0 - 0.3) / math.max(a0 - a1, 1e-4), 0, 1))
			if math.abs(flat(q - mouth):Dot(side)) <= half + 1 and q.Y <= math.max(lt.Y, lb.Y) + 1 then
				C, ci = q, i
			end
			break
		end
	end
	local function skip(why)
		Mark.gunPushKeys[key] = true
		logFile("gunpush skip", tag, why)
		return false
	end
	if not C then
		return false -- not (yet) on target: a charge can still turn; no key stamp
	end
	local k = Mark.foeKeeper(root, math.max(CFG.GunPushFlintRange or 70, CFG.GunPushShotgunRange or 22) + 1)
	if not k then
		return skip("no keeper in range")
	end
	local K = k.r.Position
	local relK = flat(K - mouth)
	local segK = (relK - side * math.clamp(relK:Dot(side), -half, half)).Magnitude
	-- holds the goal, or came out but stands where the shot passes (a keeper rushing the shooter is the saver too:
	-- log "keeper off his goal seg 35.6" right after a bait wall - he was on the path)
	local onPath = math.huge
	for i = 1, #pts do
		onPath = math.min(onPath, flat(pts[i] - K).Magnitude)
		if flat(pts[i] - mouth):Dot(out) <= 0.3 then
			break
		end
	end
	if (segK > (CFG.GunPushKeeperZone or 14) and onPath > (CFG.GunPushPathReach or 10)) or relK:Dot(out) < -2 then
		return skip(string.format("keeper off his goal seg %.1f path %.1f", segK, onPath))
	end
	if k.actor and Mark.mateDown(k.actor, k.model) then
		return skip("keeper already down")
	end
	local diveAge = Mark.keeperDiveAge(k)
	if Mark.diveBusy(diveAge) then
		return skip(string.format("keeper is in his dive (%.2f s)", diveAge))
	end
	local inv = k.model and k.model:GetAttribute("ItemInvulnerableUntil")
	if type(inv) == "number" and inv > Workspace:GetServerTimeNow() then
		return skip("keeper shielded")
	end
	local d = (K - root.Position).Magnitude
	local gun = nil
	local use = Mark.itemUse
	local held = use and use.IsEquipped and use.IsEquipped() and Mark.equippedId() or nil
	local function have(id)
		return held == id or Mark.slotOfItem(id) ~= nil
	end
	gun = Mark.pushGun(d, have("shotgun"), have("flintlock"))
	if not gun then
		return skip(string.format("no gun for d %.1f (shotgun %s flintlock %s)", d, tostring(have("shotgun")), tostring(have("flintlock"))))
	end
	local pushDir = unitOrNil(flat(K - root.Position))
	if pushDir then
		local travel = CFG.GunPushTravel or 18
		local K2 = K + pushDir * travel
		local ab = flat(K2 - K)
		local kk = math.clamp(flat(C - K):Dot(ab) / math.max(ab:Dot(ab), 1e-4), 0, 1)
		local over = flat(K + ab * kk - C).Magnitude
		if over < 3 and flat(K2 - mouth):Dot(out) > 1 then
			return skip(string.format("push runs over the shot point (%.1f) and leaves him in front of the line", over))
		end
	end
	Mark.gunPushKeys[key] = true
	local r = k.r
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	-- GunPushDelay (user: 0.1 s) before the equip + shot: the press / equip goes out a beat after the decision. A shot the ball
	-- reaches later than the hold lasts is timed so the hold is on the ball (Mark.pushFireIn)
	local fireIn = CFG.GunPushDelay or 0.1
	if ts and ts[ci] and Mark.pushWindow(gun, ts[ci], ping * 0.5 + fireIn) == "early" then
		fireIn = Mark.pushFireIn(gun, ts[ci], ping, fireIn)
	end
	task.delay(fireIn, function()
		local ok, how = Mark.itemNow(gun, "gunpush " .. tag, function()
			local v = r.AssemblyLinearVelocity
			return r.Position + (typeof(v) == "Vector3" and flat(v) or Vector3.zero) * (ping * 0.5) + Vector3.new(0, 0.4, 0)
		end)
		if ok then
			local rec = { at = os.clock(), gun = gun, tag = tag, d = d, vid = k.actor and k.actor.UserId or nil }
			Mark.gunPushRec = rec
			task.delay(1.2, function()
				if Mark.gunPushRec == rec and not rec.hit then
					logFile("gunpush result", "NO knock-back seen", rec.gun, rec.tag, "d", string.format("%.1f", rec.d), "equipped now", tostring(Mark.equippedId()), "fired", tostring(Mark.itemUse and Mark.itemUse.IsEquippedItemFired and Mark.itemUse.IsEquippedItemFired()))
				end
			end)
		end
		logFile("gunpush", tag, gun, ok and "fired" or "no", tostring(how or ""), "keeper", k.npc and "npc" or actorName(k.actor), "d", string.format("%.1f", d), "seg", string.format("%.1f", segK), "cross lat", string.format("%.1f", flat(C - mouth):Dot(side)), "ball t", ts and ts[ci] and string.format("%.2f", ts[ci]) or "-", "fire in", string.format("%.2f", fireIn))
	end)
	return true
end

-- ROLLING BALL (Keeper Push > Rolling Ball, default off): a free ball whose path ends in the enemy goal but runs through
-- an enemy (keeper or field player) who would stop it on the way - shoot HIM, the ball rolls in. Blocker = the first
-- enemy within GunPushRollReach of the path before the crossing, reached by the ball no sooner than our push lands
-- (ping/2 + 0.1). Depth check as for the keeper: the knock-back must not leave him on the remaining path.
Mark.gunPushRoll = function(root)
	if not (CFG.GunPush and CFG.GunPushRoll) then
		return
	end
	local oid = liveOwnerId()
	if type(oid) == "number" and oid ~= 0 then
		return
	end
	local _, _, pts, ts = Mark.ballPath(root)
	if not (pts and ts and #pts >= 3) then
		return
	end
	local g = enemyGoalPart()
	local lb, lt, rb = goalMouthCorners(g)
	if not (lb and lt and rb) then
		return
	end
	local mouth = (lb + rb) * 0.5
	local side = unitOrNil(flat(rb - lb))
	if not side then
		return
	end
	local half = flat(rb - lb).Magnitude * 0.5
	local out = Vector3.new(-side.Z, 0, side.X)
	if flat(root.Position - mouth):Dot(out) < 0 then
		out = -out
	end
	local iC = nil
	for i = 2, #pts do
		if flat(pts[i] - mouth):Dot(out) <= 0.3 then
			if math.abs(flat(pts[i] - mouth):Dot(side)) <= half + 0.5 and pts[i].Y <= math.max(lt.Y, lb.Y) + 1 then
				iC = i
			end
			break
		end
	end
	if not iC then
		return
	end
	-- the ball is heading into the goal: from here every silent return says why (once per reason per second)
	local function why(w)
		-- one line per reason per second (the numbers in it change every tick: key without them)
		local k = string.gsub(w, "[%d%.]+", "#")
		Mark.rollWhy = Mark.rollWhy or {}
		if os.clock() - (Mark.rollWhy[k] or 0) > 1 then
			Mark.rollWhy[k] = os.clock()
			logFile("gunpush roll skip", w)
		end
	end
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local tLand = ping * 0.5 + (CFG.GunPushDelay or 0.1)
	local reach = CFG.GunPushRollReach or 6
	local best, bestI = nil, math.huge
	local function consider(model, actor, key)
		local r = model:FindFirstChild("HumanoidRootPart")
		if not r or (actor and Mark.mateDown(actor, model)) then
			return
		end
		for i = 2, iC do
			if ts[i] >= tLand and flat(pts[i] - r.Position).Magnitude <= reach and math.abs(pts[i].Y - r.Position.Y) <= 6 then
				if i < bestI then
					best, bestI = { model = model, actor = actor, r = r, key = key }, i
				end
				return
			end
		end
	end
	for _, model in Mark.models() do
		local a = Actors.GetFromCharacter(model)
		if a and a ~= LocalPlayer and not sameTeam(a) then
			consider(model, a, a.UserId)
		end
	end
	local npcs = Workspace:FindFirstChild("Characters")
	npcs = npcs and npcs:FindFirstChild("NPCs")
	if npcs then
		for _, model in npcs:GetChildren() do
			if model:IsA("Model") then
				consider(model, nil, model)
			end
		end
	end
	if not best then
		why("nobody on the path (reach " .. tostring(reach) .. ")")
		return
	end
	if Mark.diveBusy(Mark.keeperDiveAge({ npc = best.actor == nil, key = best.key })) then
		why("the blocker is a keeper in his dive")
		return
	end
	local now = os.clock()
	Mark.rollShotAt = Mark.rollShotAt or setmetatable({}, { __mode = "k" })
	local kk = type(best.key) == "number" and tostring(best.key) or best.key
	if now - (Mark.rollShotAt[kk] or 0) < 1.5 then
		return
	end
	local inv = best.model:GetAttribute("ItemInvulnerableUntil")
	if type(inv) == "number" and inv > Workspace:GetServerTimeNow() then
		why("the blocker is shielded")
		return
	end
	local K = best.r.Position
	local d = (K - root.Position).Magnitude
	local use = Mark.itemUse
	local held = use and use.IsEquipped and use.IsEquipped() and Mark.equippedId() or nil
	local gun = nil
	gun = Mark.pushGun(d, held == "shotgun" or Mark.slotOfItem("shotgun") ~= nil, held == "flintlock" or Mark.slotOfItem("flintlock") ~= nil)
	if not gun then
		why(string.format("no gun for d %.1f", d))
		return
	end
	-- the hold must be on the ball: too early = he is back on his feet when it arrives (waits, the next tick asks again)
	local win = Mark.pushWindow(gun, ts[bestI], tLand)
	if win == "early" then
		why(string.format("too early: the ball reaches him in %.2f s, the %s holds him %.2f s", ts[bestI], gun, tLand + Mark.pushSpan(gun)))
		return
	end
	local pushDir = unitOrNil(flat(K - root.Position))
	local K2 = pushDir and K + pushDir * (CFG.GunPushTravel or 18) or K
	for i = bestI, iC do
		if flat(pts[i] - K2).Magnitude <= reach then
			Mark.rollShotAt[kk] = now
			logFile("gunpush skip", "roll", "the push leaves him on the path", "d", string.format("%.1f", d))
			return
		end
	end
	Mark.rollShotAt[kk] = now
	local r = best.r
	task.delay(CFG.GunPushDelay or 0.1, function()
		local ok, how = Mark.itemNow(gun, "gunpush roll", function()
			local v = r.AssemblyLinearVelocity
			return r.Position + (typeof(v) == "Vector3" and flat(v) or Vector3.zero) * (ping * 0.5) + Vector3.new(0, 0.4, 0)
		end)
		if ok then
			local rec = { at = now, gun = gun, tag = "roll", d = d, vid = best.actor and best.actor.UserId or nil }
			Mark.gunPushRec = rec
			task.delay(1.2, function()
				if Mark.gunPushRec == rec and not rec.hit then
					logFile("gunpush result", "NO knock-back seen", rec.gun, rec.tag, "d", string.format("%.1f", rec.d))
				end
			end)
		end
		logFile("gunpush", "roll", gun, ok and "fired" or "no", tostring(how or ""), "blocker", best.actor and actorName(best.actor) or "npc", "d", string.format("%.1f", d), "ball reaches him", string.format("%.2f", ts[bestI]), "goal at", string.format("%.2f", ts[iC]))
	end)
end

-- teammates: the moment one charges a shot that goes in (or already charges when he gets the ball)
Mark.gunPushTick = function(root)
	-- 30 Hz: the roll window is 1 s wide and a mate's charge lasts 0.3 s+; at the frame rate it cost 7 ms of every second
	local nowT = os.clock()
	if nowT - (Mark.gunPushAt or 0) < 0.033 then
		return
	end
	Mark.gunPushAt = nowT
	Mark.gunPushRoll(root)
	if not CFG.GunPush or CFG.GunPushMates == false or not Mark.charges then
		return
	end
	local now = os.clock()
	for uid, rec in Mark.charges do
		if rec.live and now - (rec.seen or 0) < 0.3 and uid ~= LocalPlayer.UserId then
			local a = playerOf(uid)
			if a and sameTeam(a) then
				local cs = Mark.chargeShot(uid)
				if cs and cs.passType == "Shot" then
					Mark.gunPushTry(root, "mate " .. actorName(a), "m" .. uid .. "@" .. tostring(rec.at), cs.pts, cs.ts)
				end
			end
		end
	end
end

-- ours: at the Release packet. The path is the solved shot (AutoShoot preview) or, without one, the released aim as a
-- straight line from the ball (enough for "inside the posts").
Mark.gunPushOwn = function(cmd)
	if not CFG.GunPush or CFG.GunPushOwn == false then
		return
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		return
	end
	local pts, ts = nil, nil
	local pv = Shoot.preview
	if pv and pv.pts and #pv.pts >= 2 and Shoot.aim then
		pts, ts = pv.pts, pv.times
	else
		local aim = type(cmd) == "table" and typeof(cmd.AimDirection) == "table" and cmd.AimDirection.Direction
		aim = typeof(aim) == "Vector3" and aim or (type(cmd) == "table" and typeof(cmd.KickDirection) == "Vector3" and cmd.KickDirection) or nil
		local b = Renderer.GetPosition()
		if typeof(aim) == "Vector3" and typeof(b) == "Vector3" and aim.Magnitude > 0 then
			pts = {}
			for i = 0, 40 do
				pts[#pts + 1] = b + aim.Unit * (i * 4)
			end
		end
	end
	Mark.gunPushTry(root, "own", "o@" .. tostring(os.clock()), pts, ts)
end

Mark.equipWall = function(tag)
	local now = os.clock()
	if now - (Mark.wallEquipAt or 0) < 0.8 then
		return true
	end
	if Ragdoll.IsActorRagdolled(LocalPlayer) or ActionLocks.HasItemEquipBlock(LocalPlayer) then
		return false
	end
	local slot = Mark.slotOfItem("barricades")
	if not slot then
		return false
	end
	local ok, why = Mark.pressSlot(slot)
	Mark.wallEquipAt = now
	Mark.wallEquipSlot = slot
	logFile("wall equip", tag or "-", "slot", slot, ok and "sent" or ("no " .. tostring(why)))
	return ok
end

-- One aim for every wall. pts[i] = the threat's position at (i-1)*dtS s from now (nil = not there yet). For 48 aim yaws the
-- wall is the segment centre O + u*5, normal u, half width WallHalf, height WallHeight above our ground; the first
-- crossing of its plane AFTER `ready` (the wall exists) counts when it falls inside the width minus the threat's radius and
-- inside the height. window: a man must reach the wall within it after it appears (earlier and he walks around it).
-- Best = the widest margin, then the earliest crossing. Returns { u, C, t, lat, q } or nil.
-- The ground under us (the wall stands on it, not under our root): O.Y - 3 is only right while we stand. In the air
-- (jump, launch, a bump) the wall's band was solved 3 studs under our ROOT, i.e. in the air - a keeper dive on the grass
-- passed "under" it -> "no line". Raycast down, characters / placed items excluded; memo 0.05 s.
Mark.groundUnder = function(O)
	local m = Mark.groundMemo
	if m and os.clock() - m.at < 0.05 and (m.O - O).Magnitude < 1 then
		return m.y
	end
	local params = Mark.groundParams
	if not params then
		params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		Mark.groundParams = params
	end
	local ex = {}
	local chars = Workspace:FindFirstChild("Characters")
	if chars then
		ex[#ex + 1] = chars
	end
	if LocalPlayer.Character then
		ex[#ex + 1] = LocalPlayer.Character
	end
	local misc = Workspace:FindFirstChild("Misc")
	if misc then
		ex[#ex + 1] = misc
	end
	params.FilterDescendantsInstances = ex
	local hit = Workspace:Raycast(O, Vector3.new(0, -80, 0), params)
	local y = hit and math.min(hit.Position.Y, O.Y - 3) or (O.Y - 3)
	Mark.groundMemo = { at = os.clock(), O = O, y = y }
	return y
end

Mark.wallSolve = function(O, pts, dtS, ready, rad, window, floorY, placeFn)
	local hw = CFG.WallHalf or 5.75
	local H = CFG.WallHeight or 6.4
	floorY = floorY or (O.Y - 3)
	local i0 = math.ceil(ready / dtS) + 1 -- first sample at or after the wall exists
	-- the first crossing of the wall plane (centre C, normal u) after `ready`, or nil when it misses the width / the height
	local function cross(u, C)
		local pv = Vector3.new(-u.Z, 0, u.X)
		local sPrev, pPrev, iPrev = nil, nil, 0
		for i = i0, #pts do
			local p = pts[i]
			if p then
				local s = (p.X - C.X) * u.X + (p.Z - C.Z) * u.Z
				if sPrev and (sPrev > 0) ~= (s > 0) then
					local f = sPrev / (sPrev - s)
					local q = pPrev:Lerp(p, f)
					local t = (iPrev - 1 + (i - iPrev) * f) * dtS
					local lat = (q.X - C.X) * pv.X + (q.Z - C.Z) * pv.Z
					local margin = hw - rad - math.abs(lat)
					local h = q.Y - floorY
					if margin > 0.3 and h > -1 and h < H + rad and (not window or t - ready <= window) then
						return { u = u, C = C, t = t, lat = lat, q = q, margin = margin }
					end
					return nil
				end
				sPrev, pPrev, iPrev = s, p, i
			end
		end
		return nil
	end
	local best = nil
	for k = 0, 47 do
		local ang = k / 48 * math.pi * 2
		local u = Vector3.new(math.cos(ang), 0, math.sin(ang))
		-- WHERE THE WALL REALLY STANDS for this aim: placeFn = the game's own placement (field clamp, pushed out of a goal) and
		-- nil when the wall cannot go there (a teammate in it). The old solver always assumed O + 5u and rejected the best
		-- aim afterwards ("moved by the field" / "mate"): a keeper trap at the enemy goal, where the clamp bites, got no wall.
		local C = Vector3.new(O.X + u.X * 5, floorY, O.Z + u.Z * 5)
		if placeFn then
			local W = placeFn(u)
			C = W and Vector3.new(W.X, floorY, W.Z) or nil
		end
		local c = C and cross(u, C)
		if c and (not best or c.margin > best.margin + 0.25 or (c.margin > best.margin - 0.25 and c.t < best.t)) then
			best = c
		end
	end
	return best
end

-- Threat path -> wall. tag names it in the log; o = { rad, window, model, actor, equip }. Returns true (placed),
-- "equip" (barricades coming out, place on a later tick) or false + why.
Mark.wallVsPath = function(root, pathFn, tEnd, tag, o)
	o = o or {}
	if not CFG.AutoWall or (o.proj and CFG.BarricadeAddon == false) then
		return false
	end
	local use = Mark.itemUse
	if not (use and use.ActivateEquipped) then
		return false
	end
	local now = os.clock()
	if now - (Mark.skillAt or 0) < (CFG.WallCooldown or 0.7) then
		return false, "wall cooldown"
	end
	if Mark.wallPend and Mark.wallPend.seenAt == nil and now - Mark.wallPend.at < 0.5 then
		return false, "last wall not seen yet" -- the last one has not appeared yet
	end
	local equipped = use.IsEquipped and use.IsEquipped() and Mark.equippedId() == "barricades"
	if equipped and Mark.wallEqSent then
		logFile("wall equip", "ready after", string.format("%.3f", now - Mark.wallEqSent))
		Mark.wallEqSent = nil
	end
	local canEquip = o.equip ~= false and not equipped and Mark.slotOfItem("barricades") ~= nil
	if not equipped and not canEquip then
		return false, Mark.slotOfItem("barricades") and "auto use off" or "no barricades"
	end
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	-- the press reaches the server after ping/2, the wall exists WallLatency later (seen 0.11-0.14 s after the press at
	-- ping 0.08 = round trip + ~0.04); equipping first costs WallEquipDelay more
	local ready = ping * 0.5 + (CFG.WallLatency or 0.06) + (CFG.WallMargin or 0.05) + (equipped and 0 or (CFG.WallEquipDelay or 0.3))
		+ (o.proj and (CFG.ProjServerExtra or 0.04) or 0) -- the server is quicker on projectiles than on bodies (user): the wall must be up earlier
	local dtS = 0.04
	local pts = Mark.wallPts or {}
	Mark.wallPts = pts
	local n = math.floor((tEnd + (o.lagReady and ready or 0)) / dtS) + 2
	for i = 1, n do
		-- lagReady: the threat has not started yet (a bait wall for a dive he may start any moment): it starts when the
		-- wall is there
		pts[i] = pathFn(o.lagReady and math.max((i - 1) * dtS - ready, 0) or (i - 1) * dtS)
		-- a body that reaches us is not blocked by a wall it would cross later (behind us): the path ends at the contact.
		-- Against where we press, not where we run: the wall stands 5 studs ahead and stops us as well.
		if o.contact and pts[i] and flat(pts[i] - root.Position).Magnitude <= o.contact then
			n = i
			break
		end
	end
	for i = n + 1, #pts do
		pts[i] = nil
	end
	local O = root.Position
	Mark.placeMod = Mark.placeMod or require(Modules.Items.PlaceDownPlacement)
	Mark.placeContain = Mark.placeContain or require(Client.Gameplay.ItemEffects.PlacementContain)
	local cfgB = Mark.placeMod.Configs.barricades
	local contain = Mark.placeContain.Get(LocalPlayer.Team and LocalPlayer.Team.Name or "Home")
	local mates = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and sameTeam(actor) then
			local ar = ActorTargeting.GetActorRoot(actor)
			if ar then
				mates[#mates + 1] = ar.Position
			end
		end
	end
	local hw = CFG.WallHalf or 5.75
	-- the wall for aim u as the game puts it (PlaceDownPlacement: the field clamp, pushed out of a goal); nil = a teammate stands in it
	local function placeFn(u)
		local W = Mark.placeMod.GetPlacementPosition(root, { AimRay = { Direction = u } }, cfgB, contain)
		if not W then
			return nil
		end
		local pv = Vector3.new(-u.Z, 0, u.X)
		for _, m in mates do
			local d = flat(m - W)
			if math.abs(d:Dot(u)) < 2.5 and math.abs(d:Dot(pv)) < hw + 1 then
				return nil
			end
		end
		return W
	end
	local best = Mark.wallSolve(O, pts, dtS, ready, o.rad or 1, o.window, Mark.groundUnder(O), placeFn)
	if not best then
		return false, "no line"
	end
	if not equipped then
		if not Mark.equipWall(tag) then
			return false, "equip failed"
		end
		-- the press runs the equip synchronously: when the item is already in hand, place it in this very frame
		equipped = use.IsEquipped and use.IsEquipped() and Mark.equippedId() == "barricades"
		if not equipped then
			Mark.wallEqSent = now
			return "equip", "equip"
		end
		logFile("wall equip", "ready same frame")
	end
	local u = best.u
	local W = best.C
	local before = {}
	local world = workspace:FindFirstChild("Misc")
	world = world and world:FindFirstChild("Items")
	if world then
		for _, inst in world:GetChildren() do
			if inst:GetAttribute("PlacedItemId") == "barricades" then
				before[inst] = true
			end
		end
	end
	local org = O + Vector3.new(0, 1.6, 0)
	Mark.skillRay = { Origin = org, Direction = u, CameraCFrame = CFrame.lookAt(org, org + u), wall = true }
	-- the press reads the ray INSIDE this call (fireEquipped -> GetCameraAimRay): the ray lives exactly that long. ActivateEquipped
	-- answers false when the game refused (a fired lock, the placement cooldown, carrying the ball): it used to be ignored, the
	-- refused press still stamped skillAt / wallPend and the next attempts waited 0.5-0.7 s for a wall that never came
	local fired = use.ActivateEquipped()
	Mark.skillRay = nil
	if not fired then
		if now - (Mark.wallRefusedAt or 0) > 0.5 then
			Mark.wallRefusedAt = now
			logFile("wall refused", tag, "the game did not take the press (fired lock / cooldown / carrying)")
		end
		return false, "refused"
	end
	Mark.skillAt = now
	-- ours: the barricades were taken out by us (equipWall stamps os.clock() after this `now`, so a time compare fails)
	local ours = Mark.wallEquipAt ~= nil and math.abs(now - Mark.wallEquipAt) < 2
	Mark.wallPend = { at = now, kind = tag, name = o.actor and actorName(o.actor) or tag, model = o.model, us = O, W = W, u = u, before = before, trap = o.trap, ours = ours }
	logFile("skill wall", tag, o.actor and actorName(o.actor) or "-", "cross", string.format("%.2f", best.t), "ready", string.format("%.2f", ready), "lat", string.format("%.1f", best.lat), "margin", string.format("%.1f", best.margin), "q", fmtV(best.q), fmtV(u))
	return true
end

-- the replicated charge as a path: the shot that is being charged crosses the circle around us -> wall on it
Mark.wallVsShot = function(root, equip)
	local oid = liveOwnerId()
	if type(oid) ~= "number" or oid == 0 or oid == LocalPlayer.UserId then
		return false
	end
	local rec = Mark.charges and Mark.charges[oid]
	if not (rec and rec.live and os.clock() - (rec.seen or 0) < 0.6) then
		return false
	end
	local cs = Mark.chargeShot(oid)
	local g = Mark.defendGoal()
	if not (cs and g) then
		return false
	end
	local lb, lt, rb = goalMouthCorners(g)
	if not (lb and lt and rb) then
		return false
	end
	local mouth = (lb + rb) * 0.5
	local sideV = unitOrNil(flat(rb - lb))
	if not sideV then
		return false
	end
	local out = Vector3.new(-sideV.Z, 0, sideV.X)
	if flat(cs.launch - mouth):Dot(out) < 0 then
		out = -out
	end
	local half = flat(rb - lb).Magnitude * 0.5
	local onTarget = false
	for i = 2, #cs.pts do
		local p = cs.pts[i]
		if flat(p - mouth):Dot(out) <= 0.3 then
			onTarget = math.abs(flat(p - mouth):Dot(sideV)) <= half + 2.5 and p.Y <= math.max(lt.Y, lb.Y) + 1.5
			break
		end
	end
	if not onTarget then
		return false
	end
	local minRel = KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds() or 0.2
	local tRel = math.max(minRel - (os.clock() - rec.at), 0)
	return Mark.wallVsPath(root, function(t)
		if t < tRel then
			return nil
		end
		return Mark.chargeAt(cs, t - tRel)
	end, tRel + 1.2, "shot", { rad = Physics.BallRadius or 1, equip = equip })
end

-- Every tick (barricades in hand or in a slot): the threats a wall can stop, most urgent first. Not in hand = only with
-- Auto Use (WallEquip). Bodies: the server pose, a short straight path (a chaser runs at where we will be), and the wall
-- must appear at most WallWindow before he reaches it, or he steps around it.
-- KEEPER TRAP (AutoWall). A barricade is solid for the enemy keeper too: his dive into a wall stops on it and the dive
-- recovery (AnimationStopSeconds 1.3 + the 1.875 s repeat delay) leaves the goal open. Pro move: run at the keeper, make
-- him dive, put the wall between. The dive is GoalkeeperDive.GetTravel (cubic out over DurationSeconds) up to
-- GetDistance * 1.3 + 3 (DiveAssist travel scale + bonus), re-locked on the ball = on us every update. The wall (11.5 wide,
-- 6.4 high, thin, 5 studs in front of our server root along the aim) is solved by Mark.wallSolve against that path.
--   dive  the GoalkeeperDiveStarted packet: solved at once and every frame for 0.5 s (no 15 Hz throttle)
--   bait  he has his dive and we are inside the window where a reactive wall is too late (his dive front arrives sooner than equip + latency): equip, place, put away
Mark.foeKeeper = function(root, maxD)
	local best, bd = nil, maxD
	for _, model in Mark.models() do
		local a = Actors.GetFromCharacter(model)
		if a and a ~= LocalPlayer and not sameTeam(a) and isGoalkeeper(a) then
			local r = ActorTargeting.GetActorRoot(a)
			local dd = r and flat(r.Position - root.Position).Magnitude
			if dd and dd < bd then
				best, bd = { actor = a, model = model, r = r, d = dd, key = a.UserId, npc = playerOf(a.UserId) == nil }, dd
			end
		end
	end
	-- NPC keepers (practice / bots: Workspace.Characters.NPCs, the same list the shot solver reads): the one tagged
	-- ActiveGoalkeeper or standing in the mouth of the goal we attack
	local npcs = Workspace:FindFirstChild("Characters")
	npcs = npcs and npcs:FindFirstChild("NPCs")
	local g = npcs and enemyGoalPart()
	if npcs and g then
		for _, model in npcs:GetChildren() do
			local r = model:IsA("Model") and model:FindFirstChild("HumanoidRootPart")
			-- The NPC keeper is the one tagged ActiveGoalkeeper, else the one near the goal we attack. He is REMEMBERED: a keeper who
			-- ran out past the goal line (log: the trap stopped seeing him beyond 16 studs of the mouth) stays the keeper while he
			-- lives and is within KeeperTrapZone of it, whatever his tag does.
			if r and (model:GetAttribute("ActiveGoalkeeper") == true or Mark.npcKeeperModel == model or flat(r.Position - g.Position).Magnitude < 16) then
				local dd = flat(r.Position - root.Position).Magnitude
				if dd < bd and (model == Mark.npcKeeperModel or model:GetAttribute("ActiveGoalkeeper") == true or flat(r.Position - g.Position).Magnitude < 16 or flat(r.Position - g.Position).Magnitude < (CFG.KeeperTrapZone or 110)) then
					best, bd = { model = model, r = r, d = dd, key = model, npc = true }, dd
				end
			end
		end
	end
	if best and best.npc then
		Mark.npcKeeperModel = best.model
	end
	return best
end

-- An NPC keeper's dive sends no GoalkeeperDiveStarted we can tie to a player: read it from his body. The dive speed
-- is the derivative of the cubic-out travel, v(t) = 3 D / T * (1 - t / T)^2, so a burst toward us gives the dive time.
Mark.npcDiveWatch = function(root)
	local k = Mark.foeKeeper(root, 40)
	if not k then
		return
	end
	-- Positions only: an NPC is moved by the server (its AssemblyLinearVelocity is not the dive) and the position arrives
	-- in steps, so the speed is taken over 0.1 s and the start of the move is the first sample that left the standing spot.
	local now = os.clock()
	local tr = Mark.kpTrack
	if not (tr and tr.key == k.key) then
		tr = { key = k.key, ring = {}, peak = 0, peakAt = now }
		Mark.kpTrack = tr
		logFile("wall trap", "keeper", k.npc and "npc" or "player", "d", string.format("%.1f", k.d))
	end
	local ring = tr.ring
	ring[#ring + 1] = { t = now, p = k.r.Position }
	while #ring > 1 and now - ring[1].t > 0.6 do
		table.remove(ring, 1)
	end
	local ref = ring[#ring]
	for i = #ring, 1, -1 do
		if now - ring[i].t >= 0.1 then
			ref = ring[i]
			break
		end
	end
	local dtw = now - ref.t
	if dtw < 0.08 or #ring < 4 then
		return
	end
	tr.vK = flat(k.r.Position - ref.p) / dtw -- his own velocity (bait path)
	if not k.npc or (Mark.trapDive and Mark.trapDive.uid == k.key and now - Mark.trapDive.at < 1.2) then
		return
	end
	local toUs = unitOrNil(flat(root.Position - k.r.Position))
	if not toUs then
		return
	end
	local closing = flat(k.r.Position - ref.p):Dot(toUs) / dtw
	if closing > tr.peak or now - tr.peakAt > 2 then
		tr.peak, tr.peakAt = closing, now
		if closing > 18 then
			logFile("wall trap", "npc closing", string.format("%.0f", closing), "d", string.format("%.1f", k.d))
		end
	end
	if closing < (CFG.WallTrapBurst or 35) then
		return
	end
	-- Dive start = the end of the newest >= 0.08 s window in which he still closed slower than a run. The old start was
	-- "the first sample that left the standing spot": a keeper who RUNS out at us and then dives left it long before
	-- the dive (log: closing 18 -> 37, el 0.53, d 8.0 -> "dive no no line": the dive was taken as 60 % done from a
	-- point 0.6 s behind him, so the solved path never reached the wall circle).
	local runMax = (CFG.WallTrapBurst or 35) * 0.8
	local si = 1
	local j = #ring
	while j > 1 do
		local i = j - 1
		while i > 1 and ring[j].t - ring[i].t < 0.08 do
			i -= 1
		end
		local dtj = ring[j].t - ring[i].t
		if dtj <= 1e-3 then
			break
		end
		if flat(ring[j].p - ring[i].p):Dot(toUs) / dtj < runMax then
			si = j
			break
		end
		j = i
	end
	Mark.gkDiveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	local el0 = math.clamp(now - ring[si].t, 0, Mark.gkDiveMod.Constants.DurationSeconds or 0.875)
	-- P0 = where the dive started (travel 0), el0 = how far into it he is now
	Mark.trapDive = { uid = k.key, at = now, el0 = el0, P0 = ring[si].p, wd = unitOrNil(flat(k.r.Position - ring[si].p)), name = "npc" }
	Mark.trapLearn(true, flat(ring[si].p - root.Position).Magnitude)
	logFile("wall trap", "npc dive seen", "closing", string.format("%.0f", closing), "el", string.format("%.2f", el0), "d", string.format("%.1f", k.d), "from", string.format("%.1f", flat(ring[si].p - root.Position).Magnitude))
end

-- WHERE HE DIVES. The bait wall goes down `ready` before he reaches his trigger distance, so that distance is the whole
-- timing. The old fixed WallTrapTrigger 8 ("NPC ~7") was wrong for the live NPC keeper: every "npc dive seen" of the
-- log started at 13.0-15.1 studs from us (from 15.1 / 14.6 / 13.0 / 15.1 / 15.1) - the bait thought it had 6 studs of
-- run left when the dive was already on, so a straight run at him never got a wall. Each dive AT us (NPC burst start /
-- player GoalkeeperDiveStarted within the cone) is recorded; the trigger is the median of the last 7 (5..22), seeded
-- 14 for NPCs and WallTrapTrigger for players. WallTrapAuto off = the slider value.
Mark.trapSeen = { npc = { 14 }, player = {} }
Mark.trapLearn = function(npc, from)
	if type(from) ~= "number" or from < 4 or from > 30 then
		return
	end
	local l = Mark.trapSeen[npc and "npc" or "player"]
	l[#l + 1] = from
	while #l > 7 do
		table.remove(l, 1)
	end
end
Mark.trapTrig = function(npc)
	if CFG.WallTrapAuto == false then
		return CFG.WallTrapTrigger or 8
	end
	local l = Mark.trapSeen[npc and "npc" or "player"]
	if #l == 0 then
		return CFG.WallTrapTrigger or 8
	end
	local s = table.clone(l)
	table.sort(s)
	return math.clamp(s[math.floor((#s + 1) / 2)], 5, 22)
end

Mark.wallTrap = function(root, diving)
	if not (CFG.AutoWall and CFG.WallTrap ~= false) or liveOwnerId() ~= LocalPlayer.UserId then
		return false
	end
	local k = Mark.foeKeeper(root, 40)
	if not k then
		return false
	end
	Mark.gkDiveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	local D = Mark.gkDiveMod
	local dur = D.Constants.DurationSeconds or 0.875
	local reach = ((k.actor and D.GetDistance(k.actor)) or 20) * 1.3 + 3
	local el0 = 0
	local P0 = k.r.Position
	if diving then
		local td = Mark.trapDive
		if not (td and td.uid == k.key) then
			return false
		end
		el0 = math.min(td.el0 + (os.clock() - td.at), dur)
		P0 = td.P0 or P0
		if el0 >= dur - 0.05 then
			return false
		end
		-- only a dash AT us stuns us (user rule; the stun rule itself is server-side): a dive whose direction is more
		-- than WallTrapCone off the line to us (a save to the side, back, a dive at the ball elsewhere) gets no wall
		local toUs = unitOrNil(flat(root.Position - P0))
		if td.wd and toUs and CFG.WallTrapForwardOnly ~= false then
			local dot = td.wd:Dot(toUs)
			if dot < math.cos(math.rad(CFG.WallTrapCone or 50)) then
				if not td.skipLogged then
					td.skipLogged = true
					logFile("wall trap", "skip dive not at us", td.name or "?", "dot", string.format("%.2f", dot), "d", string.format("%.1f", k.d))
				end
				return false
			end
		end
	else
		-- BAIT. The dive is too close to answer: a keeper who runs out at us dives at WallTrapTrigger studs (measured on the
		-- NPC: his speed jumps from ~20 to 43 st/s at d 7), and from there to the wall plane (5 studs in front of us) is
		-- 0.03 s - the wall has to exist before he starts. So it goes down `ready` seconds before the predicted trigger:
		-- time to trigger = (gap - trigger) / closing speed, from his own velocity and ours.
		local wp, td, now = Mark.wallPend, Mark.trapDive, os.clock()
		-- every silent "no" of the bait is a reason in the log now (the straight-run misses left no line at all)
		local function wait(why)
			if k.d <= Mark.trapTrig(k.npc) + 14 and (not Mark.trapWaitLog or now - Mark.trapWaitLog > 0.4 or Mark.trapWaitWhy ~= why) then
				Mark.trapWaitLog, Mark.trapWaitWhy = now, why
				logFile("wall trap", "bait wait", why, "d", string.format("%.1f", k.d), "trig", string.format("%.1f", Mark.trapTrig(k.npc)))
			end
			return false
		end
		if CFG.WallTrapBait == false then
			return false
		end
		if td and td.uid == k.key and now - td.at < 2 then
			return wait("his dive is recent")
		end
		if Mark.foeDiveLeft() > 0 then
			return wait("his dive on cooldown")
		end
		if wp and wp.trap and now - wp.at < 3 then
			return wait("a trap wall is up")
		end
		local tr = Mark.kpTrack
		local vK = tr and tr.key == k.key and tr.vK
		local toK = unitOrNil(flat(k.r.Position - root.Position))
		if not (vK and toK) then
			return wait("no keeper track")
		end
		local ourV = flat(root.AssemblyLinearVelocity)
		local rate = -flat(vK - ourV):Dot(toK)
		local trig = Mark.trapTrig(k.npc)
		-- A keeper who comes out on a DIAGONAL (log: "stands at an angle") closes slowly until he turns at us, then the
		-- closing rate jumps (log: rate < 13 -> 22 in one tick: tt went from "too early" straight to 0.14 < ready 0.19 ->
		-- no line, he dived through). He chases the carrier, so the time to his trigger comes from his SPEED turned at us
		-- whenever he is coming out at all (not running back), and the path below is that pursuit.
		local spdK = vK.Magnitude
		local comingOut = -vK:Dot(toK) > -2
		local chase = comingOut and spdK + ourV:Dot(toK) or rate
		local eff = math.max(rate, chase)
		if k.d > trig + 14 then
			return false
		end
		if eff < 6 or k.d < 3 then
			return wait(string.format("closing %.0f", eff))
		end
		local use = Mark.itemUse
		local equipped = use and use.IsEquipped and use.IsEquipped() and Mark.equippedId() == "barricades"
		local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local ready = ping * 0.5 + (CFG.WallLatency or 0.06) + (CFG.WallMargin or 0.05) + (equipped and 0 or (CFG.WallEquipDelay or 0.04))
		local tt = math.max((k.d - trig) / eff, 0)
		if tt > ready + 0.05 then
			return false -- too early: he would still have time to see it and stop
		end
		local P0b = k.r.Position
		local O, ourV2 = root.Position, flat(root.AssemblyLinearVelocity)
		-- his run until the trigger: straight at where we will be (pursuit) when that is the faster read, else his line
		local runV = vK
		if chase > rate then
			local aimU = unitOrNil(flat(O + ourV2 * tt - P0b))
			runV = aimU and aimU * spdK or vK
		end
		local Pd = P0b + runV * tt
		local function pathBait(t)
			if t <= tt then
				return P0b + runV * t
			end
			local to = unitOrNil(flat(O + ourV2 * t - Pd)) or toK * -1
			local el = math.min(t - tt, dur)
			return Pd + to * D.GetTravel(el, reach) + Vector3.new(0, D.GetVerticalTravel(el), 0)
		end
		local ok, why = Mark.wallVsPath(root, pathBait, tt + dur, "keeper bait" .. (k.npc and " npc" or ""), { rad = 2, equip = true, actor = k.actor, model = k.model, trap = true, contact = 3 })
		if not ok and why and (not Mark.trapLog or now - Mark.trapLog > 0.6) then
			Mark.trapLog = now
			logFile("wall trap", "bait no", why, "d", string.format("%.1f", k.d), "trig", string.format("%.1f", trig), "rate", string.format("%.0f", rate), "spd", string.format("%.0f", spdK), "eff", string.format("%.0f", eff), "tt", string.format("%.2f", tt), "ready", string.format("%.2f", ready))
		end
		return ok
	end
	local O, ourV = root.Position, flat(root.AssemblyLinearVelocity)
	-- P0 is the dive START (travel 0): NPC = the burst start, player = his displayed pose at the DiveStarted packet (the
	-- display lags the server by more than the packet's own age, so it still shows the start). The old path put the
	-- start at P0 AND subtracted the travel already done, i.e. it restarted the dash from where it began - every later
	-- frame of the 0.5 s re-solve (and the whole NPC case) had him that far behind his real body.
	local function path(t)
		local to = unitOrNil(flat(O + ourV * t - P0)) or Vector3.new(0, 0, 1)
		return P0 + to * D.GetTravel(math.min(el0 + t, dur), reach) + Vector3.new(0, D.GetVerticalTravel(el0 + t), 0)
	end
	local ok, why = Mark.wallVsPath(root, path, dur - el0, (diving and "keeper dive" or "keeper bait") .. (k.npc and " npc" or ""), { rad = 2, equip = true, actor = k.actor, model = k.model, trap = true, contact = 3, lagReady = not diving })
	if not ok and why and (not Mark.trapLog or os.clock() - Mark.trapLog > 0.6) then
		Mark.trapLog = os.clock()
		logFile("wall trap", "dive no", why, "d", string.format("%.1f", k.d), "el", string.format("%.2f", el0), "reach", string.format("%.1f", reach))
	end
	return ok
end

Mark.wallTick = function(root, oid, own)
	Mark.wallWatch()
	if not CFG.AutoWall then
		return
	end
	local use = Mark.itemUse
	if not (use and use.ActivateEquipped) then
		return
	end
	local now = os.clock()
	-- a keeper dive at us is decided every frame (0.15 s of it is all the time there is)
	if own and CFG.WallTrap ~= false then
		Mark.npcDiveWatch(root)
	end
	if Mark.trapDive and now - Mark.trapDive.at < 0.5 and Mark.wallTrap(root, true) then
		return
	end
	-- the rest: 48 yaws x the path samples per threat at 30 Hz
	if now - (Mark.wallTickAt or 0) < 0.033 then
		return
	end
	Mark.wallTickAt = now
	local inHand = use.IsEquipped and use.IsEquipped()
	local isWall = inHand and Mark.equippedId() == "barricades"
	-- Keeper Trap bait: decided at 30 Hz, from his run + the predicted dive trigger
	if own and CFG.WallTrap ~= false and Mark.wallTrap(root, false) then
		return
	end
	-- PUT AWAY. Equip -> place -> put away. A used item stays "fired" in hand until its lifecycle ends and the game ignores
	-- the unequip until then (one press 0.12 s after the placement did nothing and the item stayed in hand): ask the game's
	-- own unequip as soon as the item is not fired any more, every 0.1 s, give up after 3 s.
	local wp0 = Mark.wallPend
	if isWall and wp0 and wp0.ours then
		wp0.ours = nil
		Mark.wallAway = now
	end
	if not isWall then
		if Mark.wallAway and not inHand then
			logFile("wall equip", "away", string.format("%.2f", now - Mark.wallAway), "s after the placement")
		end
		Mark.wallAway = nil
		if Mark.wallEquipAt and now - Mark.wallEquipAt > 1 then
			Mark.wallEquipAt = nil
		end
	elseif Mark.wallAway then
		if now - Mark.wallAway > 3 then
			Mark.wallAway, Mark.wallEquipAt = nil, nil
			logFile("wall equip", "away failed")
		elseif now - (Mark.wallAwayTry or 0) > 0.1 then
			Mark.wallAwayTry = now
			local fired = use.IsEquippedItemFired and use.IsEquippedItemFired()
			if not fired then
				if use.RequestUnequip then
					use.RequestUnequip()
				else
					Mark.pressSlot(Mark.wallEquipSlot or Mark.slotOfItem("barricades"))
				end
			end
			if not Mark.wallAwayLog or now - Mark.wallAwayLog > 0.5 then
				Mark.wallAwayLog = now
				logFile("wall equip", "away try", "fired", tostring(fired), "t", string.format("%.2f", now - Mark.wallAway))
			end
		end
		return
	end
	if isWall and Mark.wallEquipAt and now - Mark.wallEquipAt > (CFG.WallEquipHold or 3.5) and now - (Mark.skillAt or 0) > (CFG.WallEquipHold or 3.5) then
		-- put away what we took out and did not use (an equipped item blocks ball controls)
		Mark.wallEquipAt = nil
		if use.RequestUnequip then
			use.RequestUnequip()
			logFile("wall equip", "idle - put away")
		end
		return
	end
	if inHand and not isWall then
		return -- another item in hand: leave it
	end
	if not isWall and (CFG.WallEquip == false or not Mark.slotOfItem("barricades")) then
		return
	end
	-- no equip while we hold the ball: an item in hand blocks the ball controls
	local equip = CFG.WallEquip ~= false and not own
	-- 1) the shot being charged goes into our mouth
	-- the keeper saves a shot with the dive / catch: a wall in front of our own mouth only blocks him
	if not own and CFG.WallShot ~= false and not Mark.meKeeper() and Mark.wallVsShot(root, equip) then
		return
	end
	-- 2) a slide at us while we hold the ball: its box path (origin + heading * the dump's slide travel)
	local dd = dribbleDanger
	if own and dd and dd.heading and dd.origin and dd.fire then
		local el0 = dd.elapsed or 0
		local o0, hd = dd.origin, dd.heading
		if Mark.wallVsPath(root, function(t)
			return o0 + hd * Mark.dumpTravel(el0 + t)
		end, 0.6, "slide", { rad = 1.5, equip = equip, actor = dd.actor, model = dd.character }) then
			return
		end
	end
	-- 3) bodies: a chaser on our ball, or the carrier's run when we do not have it
	local reach = CFG.WallReach or 18
	local ourV = flat(root.AssemblyLinearVelocity)
	local us0 = root.Position
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) and (own or actor.UserId == oid) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r and flat(r.Position - us0).Magnitude <= reach then
				local pos, vel = Mark.carrierPose(r, model)
				local spd = math.min(vel.Magnitude, 32)
				local path
				if own then
					path = function(t)
						local to = unitOrNil(flat(us0 + ourV * t - pos))
						return to and (pos + to * (spd * t)) or pos
					end
				else
					local v = spd > 0.5 and vel.Unit * spd or Vector3.zero
					path = function(t)
						return pos + v * t
					end
				end
				if spd > 4 and Mark.wallVsPath(root, path, 0.9, own and "chaser" or "carrier", { rad = 1.5, window = CFG.WallWindow or 0.45, equip = equip, actor = actor, model = model, contact = 3 }) then
					return
				end
			end
		end
	end
end

Mark.tickSkill = function(character, root)
	Mark.skillRay = nil
	Mark.silentRay = nil
	Mark.areaCheck()
	for i = 1, 8 do
		fovLines[i].Visible = false
		resLines[i].Visible = false
	end
	local use = Mark.itemUse
	local cam = Workspace.CurrentCamera
	Mark.wallTick(root, liveOwnerId(), liveOwnerId() == LocalPlayer.UserId)
	if not (use and use.IsEquipped and use.IsEquipped() and cam) then
		Mark.saHide()
		return
	end
	local id = Mark.equippedId()
	Mark.itemAim = Mark.itemAim or require(Modules.Items.ItemAim)
	local aimGun = id ~= nil and Mark.itemAim.UsesGunReticle(id)
	-- the boomerang (log: proj start boomerang spd 103 grav 0) is not in the dump we have: if the live ItemAim says it is a gun-
	-- reticle item the gun path below takes it, otherwise it is aimed by the camera and the aim ray hooks carry our ray
	local boom = id == "boomerang" and not aimGun
	local placeWall = id == "barricades"
	if not (aimGun or boom) then
		Mark.saHide()
	end
	local ping = LocalPlayer:GetNetworkPing()
	local oid = liveOwnerId()

	if placeWall then
		return -- AutoWall ran above (Mark.wallTick)
	end
	if not (aimGun or boom) then
		return
	end

	-- SilentAim. Gun-reticle items (ItemAim.UsesGunReticle: flintlock, freezeGun, bazooka, shotgun) fire with
	-- Reticle.GetCameraAimRay -> getAimRayPayload(u1.GetCameraRay(), hitQuery): replacing GetCameraRay keeps the
	-- game's own payload (ClientHit/TargetPosition from its hit query on the target). Priority: enemy carrier in the
	-- FOV circle, else nearest enemy in it, else untouched.
	Mark.saDraw()
	-- centre = where the game's own gun ray points. Reticle.GetCameraRay works in GUI space (AbsolutePosition /
	-- ViewportSize * GunScreenPosition MINUS GuiInset, then ScreenPointToRay); Drawing is viewport space, so the old
	-- AbsolutePosition centre sat one top-bar inset too high. Projecting the real ray removes the mismatch.
	local center
	do
		local ray = (Mark.oldCamRay or Reticle.GetCameraRay)()
		if ray then
			local sp = cam:WorldToViewportPoint(ray.Origin + ray.Direction.Unit * 60)
			center = Vector2.new(sp.X, sp.Y)
		else
			center = cam.ViewportSize * (Reticle.GunScreenPosition or Vector2.new(0.5, 0.5))
		end
	end
	local fov = CFG.SilentFov
	Mark.saCircle.Position = center
	Mark.saCircle.Radius = fov
	Mark.saCircle.Visible = CFG.SilentAim and CFG.DrawSilentFov ~= false
	if not CFG.SilentAim then
		Mark.saHide()
		return
	end
	local pick, pickD, pickOwner = nil, math.huge, false
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r then
				local sp, on = cam:WorldToViewportPoint(r.Position)
				if on and sp.Z > 0 then
					local scr = Vector2.new(sp.X, sp.Y)
					if (scr - center).Magnitude <= fov then
						local isOwner = type(oid) == "number" and actor.UserId == oid
						local d = (r.Position - root.Position).Magnitude
						if (isOwner and not pickOwner) or (isOwner == pickOwner and d < pickD) then
							pick, pickD, pickOwner = r, d, isOwner
						end
					end
				end
			end
		end
	end
	if not pick then
		hideLines(Mark.saBox)
		Mark.saText.Visible = false
		Mark.saLink.Visible = false
		if Mark.saPool then
			Mark.saPool.finish()
		end
		if Mark.areaFx then
			Mark.areaDraw(nil)
		end
		return
	end
	local aimP = pick.Position
	local spd = (Mark.projSpeed and Mark.projSpeed[id]) or Mark.projSeed[id]
	local camPos = cam.CFrame.Position
	local areaDir, areaG, areaInfo = nil, nil, nil
	local boomDir, boomInfo = nil, nil
	if Mark.areaItems[id] then
		areaDir, areaG, areaInfo = Mark.areaAim(id, pick, cam, ping, root)
	end
	if areaDir then
		aimP = areaG + Vector3.new(0, 2.9, 0)
		Mark.areaLast = { id = id, at = os.clock(), G = areaG, t = areaInfo.t, launch = areaInfo.launch, D = areaInfo.D, model = pick.Parent }
		if os.clock() - (Mark.areaLogAt or 0) > 2 then
			Mark.areaLogAt = os.clock()
			local si = Mark.silentInfo
			logFile("silent area", id, "D", string.format("%.1f", areaInfo.D), "t", string.format("%.2f", areaInfo.t), "lead", si and string.format("%.1f", si.lead) or "-", "R", string.format("%.1f", areaInfo.R), "G", fmtV(areaG))
		end
	elseif Mark.areaItems[id] then
		Mark.areaLast = nil
	elseif id == "boomerang" then
		boomDir, boomInfo = Mark.boomAim(pick, cam, ping, root)
		if boomInfo and os.clock() - (Mark.boomLogAt or 0) > 1.5 then
			Mark.boomLogAt = os.clock()
			logFile("silent boomerang", "r", string.format("%.1f", boomInfo.r), "t", string.format("%.2f", boomInfo.t), "returns", tostring(boomInfo.returns), "fwd", fmtV(boomDir))
		end
	elseif spd and spd > 10 then
		-- projectile: lead by its measured muzzle speed (our ProjectileStart events, seeded for the freeze gun)
		aimP = Mark.silentLead(pick, camPos, spd, ping)
		local si = Mark.silentInfo
		if si and si.lead > 1 and os.clock() - (Mark.silentLogAt or 0) > 2 then
			Mark.silentLogAt = os.clock()
			logFile("silent lead", id, "tau", string.format("%.2f", si.tau), "flips", si.flips, "T", string.format("%.2f", si.T), "lead", string.format("%.1f", si.lead), "v", string.format("%.1f", si.speed))
		end
	end
	-- an area weapon with no ground solve (out of reach, blast on us) keeps the player's own aim
	local dir = areaDir or boomDir or ((not Mark.areaItems[id] and id ~= "boomerang") and unitOrNil(aimP - camPos)) or nil
	if dir then
		if boom then
			Mark.skillRay = { Origin = camPos, Direction = dir, CameraCFrame = CFrame.lookAt(camPos, camPos + dir) }
		else
			Mark.silentRay = Ray.new(camPos, dir)
		end
	end
	-- visual: a world-space tracer from the weapon muzzle (HeldItems.FindMuzzle) to the target, with light pulses
	-- running down it toward him, plus a spinning split ring at his feet and his name. Reads in one glance as "this
	-- gun -> that player", unlike the old 2D brackets.
	local col = pickOwner and Color3.fromRGB(255, 150, 50) or Color3.fromRGB(90, 220, 255)
	Mark.heldItems = Mark.heldItems or require(Modules.Items.HeldItems)
	local muzzle = nil
	local att = Mark.heldItems.FindMuzzle(LocalPlayer.Character, id)
	muzzle = att and att.WorldPosition
	muzzle = muzzle or (root.Position + Vector3.new(0, 1.2, 0) + flat(cam.CFrame.LookVector) * 1.5)
	local chest = aimP + Vector3.new(0, 0.6, 0)
	Mark.saLines = Mark.saLines or makeLines(180, 1.4, 46)
	Mark.saPool = Mark.saPool or Mark.segPool(Mark.saLines)
	local pool = Mark.saPool
	if areaG then
		-- area weapon: the beam ends on the blast spot, the footprint replaces the feet ring
		if CFG.DrawSilent ~= false then
			Mark.silentArt(pool.seg, muzzle, areaG + Vector3.new(0, 0.2, 0), nil, col, os.clock())
		end
		Mark.areaDraw(areaG, areaInfo.R, col)
	else
		if CFG.DrawSilent ~= false and boomInfo then
			local tab, S0 = boomInfo.tab, boomInfo.S
			local fb = boomDir
			local side = Vector3.new(fb.Z, 0, -fb.X)
			local iT = math.clamp(math.floor(boomInfo.t / tab.dt + 0.5), 1, tab.n)
			local cp = { muzzle }
			for i = 0, iT do
				cp[#cp + 1] = S0 + fb * tab.a[i] + side * tab.b[i] + Vector3.new(0, tab.h[i], 0)
			end
			local P = boomInfo.P
			Mark.ribbonArt(pool.seg, cp, col, os.clock(), Vector3.new(P.X, P.Y - 2.9, P.Z))
		elseif CFG.DrawSilent ~= false and not Mark.areaItems[id] and id ~= "boomerang" then
			Mark.silentArt(pool.seg, muzzle, chest, Vector3.new(aimP.X, aimP.Y - 2.9, aimP.Z), col, os.clock())
		end
		if Mark.areaFx then
			Mark.areaDraw(nil)
		end
	end
	pool.finish()
	hideLines(Mark.saBox)
	Mark.saLink.Visible = false
	Mark.saText.Visible = false
end

-- Dive search with the game's own model. role.Dive() turns the move command into one of 8 DirectionChoices
-- relative to the CAMERA (GoalkeeperDive.GetDirectionChoice) and the assist may yaw it only +-12 deg
-- (GoalkeeperDiveAssist MaximumYawDegrees). Our old dive aimed a free vector at the path point, so the game snapped
-- it up to 22.5 deg away: a corner shot 12 studs out was missed by ~4.5 studs. Here every choice is run through
-- GoalkeeperDiveAssist.GetAssist (extra reach <= 3, travel scale 0.3-1.3, lift, yaw) and then FindFlightIntercept with
-- that assisted dive; the save hitbox is AirReceive grown by max(1.25, 2*BallRadius) (GoalkeeperActions), so a
-- residual miss under half of that pad is contact.
-- Our own dive model (primary): the dive is GoalkeeperDive.GetTravel (cubic-out, Distance over DurationSeconds) along
-- one of the 8 camera-relative choices plus GetVerticalTravel; the save box is AirReceive grown by the contact pad
-- (GoalkeeperActions: max(1.25, 2*BallRadius)) and 2*SaveReachStuds along the dive. Every ball path sample
-- (Mark.ballPath, world collisions) inside SaveWindowSeconds is tested after our input delay. Independent of the
-- game's assist, which only nudges.
-- KNOCKED KEEPER (Keeper Push used on US). ViolenceKnockback is the Stun source "ViolenceKnockback" (Stun.StumbleSourceName):
-- while it lasts we touch no ball (VolleyLockOn drops stunned characters, a body block is gone), and the dive press is
-- refused by ActionLocks.HasGoalkeeperDiveBlock -> Stun.IsActorStunnedForPress, EXCEPT a press whose command time is
-- <= stumble start + our one-way delivery allowance. So the only save is a dive sent the moment the knock arrives - not
-- the walk / receive plan tickGk still believed in (log 770.33: knocked twice, "plan walk", dive 0.37 s later, goal).
-- Dive: the own model on the current path; none -> straight at the path point where the ball crosses in front of us
-- (forward-ish, never backward). The local press gate is passed with Mark.knockDiving (stunHook).
Mark.gkKnockDive = function(vel)
	local character = LocalPlayer.Character
	local root = character and ActorTargeting.GetActorRoot(LocalPlayer)
	local role, D = Mark.gkRole, Mark.gkDiveMod
	if CFG.GkKnockDive == false or not (root and role and role.Dive and D) or not MatchSettings.IsGoalkeeperCharacter(character) then
		return
	end
	local now = os.clock()
	Mark.knockMod = Mark.knockMod or require(Modules.Characters.KnockbackMotion)
	Mark.gkKnockUntil = now + Mark.knockMod.GetDuration(typeof(vel) == "Vector3" and vel or Vector3.new(0, 0, 25))
	if now - (Mark.gkDive or 0) <= D.Constants.RepeatDelaySeconds then
		logFile("gk knock", "dive on cooldown")
		return
	end
	local _, _, samples, ts = Mark.ballPath(root)
	local threat = samples and Mark.goalThreat(samples, ts)
	if not threat then
		logFile("gk knock", "no shot at goal")
		return
	end
	local hit = Mark.gkOwnDive(root)
	local wd = hit and hit.wd
	local why = hit and ("model " .. tostring(hit.name)) or "path"
	if not wd then
		-- the first path sample in front of us that the ball reaches after our dive could: dive at it
		local gf = Mark.gkFwd
		for i = 2, #samples do
			local d = flat(samples[i] - root.Position)
			if ts[i] >= 0.05 and d.Magnitude > 2 then
				local u = d.Unit
				if not gf or u:Dot(gf) > -0.3 then
					wd = u
					break
				end
			end
		end
	end
	if not wd then
		logFile("gk knock", "no dive line")
		return
	end
	local face = wd
	TurnControl.LockAutoRotate("Goalkeeper", face)
	Mark.gkDiveAim = { dir = wd, at = now, untilT = now + D.Constants.DurationSeconds + 0.05, fwd = Mark.gkFwd or wd, faceF = true }
	Mark.diveSet(character, wd, face)
	Mark.gkDive = now
	Mark.knockDiving = true
	local ok = role.Dive()
	Mark.knockDiving = false
	Mark.diveRestore(character, wd)
	if ok then
		Mark.gkDiveAim.faceLock = true
		Mark.gkDiveRec = { at = now, name = "knock", minD = math.huge, eta = threat.t }
	else
		Mark.gkDiveAim = nil
		TurnControl.ReleaseAutoRotate("Goalkeeper")
	end
	logFile("gk knock", "dive", ok and "ok" or "refused", why, "goal t", string.format("%.2f", threat.t), "lat", string.format("%.1f", threat.lat), "dir", fmtV(wd))
	if ok then
		-- did the server take the dive? 0.25 s on: how far the body went along the dive against the dive's own travel curve
		-- (a refused press = no dive motion, the knock-back alone moves us), and whether the stun is still on
		local O0, ping0 = root.Position, LocalPlayer:GetNetworkPing() or 0
		Mark.stunMod = Mark.stunMod or require(Modules.Characters.Stun)
		task.delay(0.25, function()
			local r2 = ActorTargeting.GetActorRoot(LocalPlayer)
			if r2 then
				local mv = flat(r2.Position - O0)
				local want = D.GetTravel(0.25, D.GetDistance(LocalPlayer))
				Mark.teleAdd("gk.knockdive", mv:Dot(wd) >= want * 0.5)
				logFile("gk knock", "check 0.25 s", "along dive", string.format("%.1f", mv:Dot(wd)), "of", string.format("%.1f", want), "moved", string.format("%.1f", mv.Magnitude), "ping", string.format("%.0f ms", ping0 * 1000), "stunned", tostring(Mark.stunMod.IsActorStunned(LocalPlayer)))
			end
		end)
	end
end

Mark.gkOwnDive = function(root, td, noJump)
	td = td or 0
	local yJ = 0
	if td > 0 and not noJump then
		local gW = Workspace.Gravity
		yJ = math.max(math.sqrt(2 * gW * (Mark.jumpH or 7.2)) * td - 0.5 * gW * td * td, 0)
	end
	local D = Mark.gkDiveMod
	Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
	local cam = Workspace.CurrentCamera
	if not (D and cam) then
		return nil
	end
	local _, _, samples, ts = Mark.ballPath(root)
	if not samples then
		return nil
	end
	local facing = unitOrNil(flat(root.CFrame.LookVector)) or Vector3.new(0, 0, 1)
	local ar = HitboxSettings.AirReceive
	local pad = math.max(1.25, (Physics.BallRadius or 1) * 2)
	local box = { Size = ar.Size + Vector3.new(pad, pad, pad + 2 * D.Constants.SaveReachStuds), Shape = ar.Shape, CFrameOffset = ar.CFrameOffset }
	local dist = D.GetDistance(LocalPlayer)
	local delay = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.3) * 0.5 + 0.03
	local win = D.Constants.SaveWindowSeconds
	local best = nil
	-- the 8 camera choices first (no turn needed when one of them saves); with Any-Angle Dive also a fan every 7.5 deg:
	-- a diagonal shot between two choices (45 deg apart) had no save at all -> "gk dive none" frame after frame, the
	-- keeper stood until it was too late. An exact direction is flown by the GetWorldDirection hook (Mark.gkDiveAim).
	local dirs = {}
	for name, choice in Mark.actionMotion.DirectionChoices do
		dirs[#dirs + 1] = { name = name, wd = (Mark.gkAimOrig or D.GetWorldDirection)(choice, cam.CFrame, facing) }
	end
	if CFG.GkPressExact ~= false and Mark.gkFwd then
		local f = Mark.gkFwd
		for k = -20, 20 do
			local a = math.rad(k * 7.5)
			dirs[#dirs + 1] = { name = "exact", wd = f * math.cos(a) + Vector3.new(-f.Z, 0, f.X) * math.sin(a), exact = true }
		end
	end
	local mouth = Mark.gkMouth
	local gf = Mark.gkFwd
	local ballR = Physics.BallRadius or 1
	local hold = { CFrame = root.CFrame }
	-- first contact time of a dive along wd that leaves `extra` seconds later than planned (nil = no contact)
	local function contact(wd, extra)
		for i = 2, #samples do
			local t = ts[i] - delay - td - extra
			if t > win then
				return nil
			end
			-- goal line: a save at or behind the mouth plane is already a goal (user: dived inward diagonally,
			-- touched the ball after it crossed). Ball sample and keeper pose must both stay in front of the line.
			if mouth and gf and (samples[i] - mouth.c):Dot(gf) < ballR + 0.3 then
				return nil
			end
			if t > 0 then
				local pos = root.Position + wd * D.GetTravel(t, dist) + Vector3.new(0, D.GetVerticalTravel(t) + yJ, 0)
				if mouth and gf and (pos - mouth.c):Dot(gf) < 0.3 then
					return nil
				end
				hold.CFrame = CFrame.lookAlong(pos, wd)
				-- segment test: path samples are ~6 studs apart at shot speed, a point test skips through the box
				if HitboxSettings.GetSegmentEnterAlpha(hold, box, samples[i - 1], samples[i]) then
					return t
				end
			end
		end
		return nil
	end
	-- TIMING MARGIN. The earliest contact is not the best one: a dive that meets a close, fast shot right at its start
	-- (forward, at the shooter) misses the moment the dash leaves a little later than modelled (ping jitter, server
	-- step) - the ball is already behind us (user: powered shot from close range flew through a forward dive; a
	-- sideways / covering dive would have held). So every contact is re-tested with the dive leaving GkDiveRobust later
	-- (not in the dump: a guess, logged as robust yes|no in "gk dive"); a dive that survives it wins over an earlier
	-- one that does not.
	local rob = CFG.GkDiveRobust or 0.05
	for _, dv in dirs do
		local name, wd = dv.name, dv.wd
		-- no backward dives: the backward dive arches the body back and lowers the save box (user: the ball went over
		-- the head on a "B" dive); our box model does not have that pose
		if typeof(wd) == "Vector3" and (not gf or wd:Dot(gf) > -0.3) then
			local t = contact(wd, 0)
			if t then
				local robust = rob <= 0 or contact(wd, rob) ~= nil
				local better
				if not best then
					better = true
				elseif robust ~= best.robust then
					better = robust
				else
					-- a camera choice wins ties (no turn); an exact one must be clearly earlier
					better = t < best.t - ((dv.exact and not best.exact) and 0.03 or 0)
				end
				if better then
					best = { name = name, wd = wd, t = t, miss = 0, own = true, td = td, exact = dv.exact, robust = robust }
				end
			end
		end
	end
	return best
end

Mark.gkDiveSearch = function(root, state, world)
	local A = Mark.gkAssist
	local D = Mark.gkDiveMod
	if not (A and D and state and world and A.FindFlightIntercept and A.GetAssist) then
		return nil
	end
	Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
	local cam = Workspace.CurrentCamera
	if not cam then
		return nil
	end
	local t0 = Workspace:GetServerTimeNow()
	Mark.cms = Mark.cms or require(game:GetService("ReplicatedStorage").Client.Player.CharacterMotionSmoothing)
	t0 = Mark.cms.GetSmoothedServerTime()
	local facing = unitOrNil(flat(root.CFrame.LookVector)) or Vector3.new(0, 0, 1)
	local pad = math.max(1.25, (Physics.BallRadius or 1) * 2) * 0.5
	local dist = D.GetDistance(LocalPlayer)
	local best = nil
	for name, choice in Mark.actionMotion.DirectionChoices do
		local wd = D.GetWorldDirection(choice, cam.CFrame, facing)
		local nearLine = Mark.gkMouth and Mark.gkFwd and (root.Position - Mark.gkMouth.c):Dot(Mark.gkFwd) < 8
		-- assist path has no line check of its own: close to the line, no direction with an inward component
		if typeof(wd) == "Vector3" and (not Mark.gkFwd or wd:Dot(Mark.gkFwd) > (nearLine and -0.05 or -0.3)) then
			local assist = A.GetAssist(state, world, root, wd, t0)
			local v0 = D.Constants.InitialVerticalVelocity
			local g = D.Constants.GravityStudsPerSecondSquared
			local dive = { CanExtendReach = false, ElapsedSeconds = 0, WarpedSeconds = 0, TravelScale = 1, Distance = dist }
			local dir = wd
			if assist then
				dive.TravelScale = assist.TravelScale or 1
				dive.Distance = dist + (assist.ExtraDistance or 0)
				v0 = assist.InitialVerticalVelocity or v0
				g = assist.Gravity or g
				dir = D.RotateFlatDirection(wd, assist.YawRadians or 0)
			end
			dive.GetVerticalOffset = function(s)
				return math.max(0, s * (v0 + 0.5 * g * s))
			end
			local ic = A.FindFlightIntercept(state, world, root.CFrame, dir, t0, dive)
			if type(ic) == "table" and ic.MissDistance and ic.MissDistance <= pad then
				if not best or ic.MissDistance < best.miss then
					best = { name = name, wd = wd, miss = ic.MissDistance, t = ic.OffsetSeconds, assisted = assist ~= nil }
				end
			end
		end
	end
	return best
end

-- Trust but verify the goal read. pred.GetGoalCrossing is the game's own preview; when it answers nothing the old code
-- fell back to the plane time / a straight line - both ignore the walls, so a BounceFAKE (aimed at the wall around the
-- goal, it comes BACK to the shooter) looked like a shot and drew a dive. Mark.ballPath is the same physics WITH world
-- collisions. Verdicts over its samples (distance to the mouth plane `a`):
--   goal   - the path crosses the plane inside the mouth (+0.8 slack) -> point and time of the crossing;
--   bounce - it moved toward the goal by >= 1 stud and then turned back before the plane (wall / post / bar) -> no shot;
--   wide   - it crosses the plane outside the mouth;
--   none   - it never gets there inside the sampled window.
Mark.gkVerify = function(samples, ts, c, fwd, side, half, bottomY, topY)
	local prevA, dec = nil, 0
	local bounce, bp, bt = false, nil, nil
	for i = 1, #samples do
		local a = flat(samples[i] - c):Dot(fwd)
		if prevA then
			if a < 0 and prevA >= 0 then
				local k = prevA / math.max(prevA - a, 1e-4)
				local p = samples[i - 1]:Lerp(samples[i], k)
				local s = flat(p - c):Dot(side)
				local inMouth = math.abs(s) <= half + 0.8 and p.Y >= bottomY - 0.8 and p.Y <= topY + 0.8
				-- 4th result: the flight hit something first (post, bar) and this is the crossing AFTER the rebound
				return inMouth and "goal" or "wide", p, ts[i - 1] + (ts[i] - ts[i - 1]) * k, bounce
			elseif a > prevA + 0.4 and dec >= 1.0 and not bounce then
				-- the ball turned back toward the field: a post / bar / wall. This used to end the scan as "bounce" = no
				-- shot, but the path is the game's own physics, so a rebound that ends in the mouth is a shot (log: ball hit
				-- the post, the rebound went in, the keeper treated it as a fake). Keep scanning for a later crossing.
				bounce, bp, bt = true, samples[i - 1], ts[i - 1]
				dec = 0
			end
			if a < prevA then
				dec += prevA - a
			end
		end
		prevA = a
	end
	if bounce then
		return "bounce", bp, bt
	end
	return "none"
end

-- AutoGK x enemy FAKE. A FAKE shot (AutoShoot / any human) is aimed THROUGH a teammate of the shooter so that, if nobody
-- touched it, it would end in our goal: the game's goal-crossing preview shows a shot, the dive commits, and the ball is
-- received by his teammate (Receiving.Constants.TeammateKickIgnoresSpeedThreshold = true: the shooter's teammates control
-- a Shot at ANY speed) - the keeper is on the floor, the second enemy scores. So before a dive is allowed the predicted
-- ball path (Mark.ballPath samples, world collisions) is tested against every enemy's receive volume at the time the ball
-- gets there (HitboxSettings.Receive grounded / AirReceive airborne, server pose = displayed + v*(display delay + t)).
-- A solid hit (the path goes through the box shrunk by BaitInset on each side) before the goal crossing = bait: no dive,
-- no walk to the crossing point. It is re-evaluated every frame, so a ball that really passes him (he dodged / was
-- ragdolled / the path moved) turns into a normal shot with whatever time is left. The first 0.2 s after a kick are
-- ignored for the kicker himself (Ownership.LaunchNoTouchSeconds 0.25).
-- returns { t, name, dist } or nil
Mark.gkBait = function(samples, ts, limit)
	if not samples or #samples < 2 then
		return nil
	end
	-- The real receive test (Ownership: the ball CENTRE's segment against HitboxSettings.ExtendToFeet(Receive), no ball
	-- radius) - the old version SHRANK the box by 0.6 a side for a "solid" hit: a FAKE through his teammate at 2.5 studs
	-- (log: "gk bait ... on charge ray lat 2.5", then "gk dive ok") passed that inner box, the dive went, he received.
	-- He also WANTS that ball and steps into it: the box grows by his run speed after a 0.15 s reaction, up to GkBaitReach.
	local reachMax = CFG.GkBaitReach or 3
	local rcv, air = HitboxSettings.Receive, HitboxSettings.AirReceive
	local mates = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r and not Mark.mateDown(actor, model) then
				local pos = CharacterMotion.GetPosition(model) or r.Position
				local vel = flat(CharacterMotion.GetVelocity(model) or Vector3.zero)
				local dly = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25)
				local hum = model:FindFirstChildOfClass("Humanoid")
				local landed = not hum or CharacterControllers.IsLanded(model, hum)
				local src0 = landed and rcv or air
				if landed and hum and HitboxSettings.ExtendToFeet then
					src0 = HitboxSettings.ExtendToFeet(rcv, hum, r) or rcv
				end
				Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
				local runS = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false)
				-- the kicker cannot touch his own ball for Ownership.LaunchNoTouchSeconds (0.25): only HE gets the grace
				-- window. It used to be skipped for everyone (t >= 0.2), so a second enemy taking the ball at once was a "shot".
				local fa = Mark.gkFreeAt
				local skip = (fa and fa.id == actor.UserId) and math.max(0.25 - (os.clock() - fa.at), 0) or 0
				mates[#mates + 1] = {
					skip = skip,
					name = actorName(actor), pos = pos, vel = vel, dly = dly, src = src0,
					run = (type(runS) == "number" and runS > 4) and runS or 16,
				}
			end
		end
	end
	if #mates == 0 then
		return nil
	end
	for i = 2, #samples do
		local t = ts[i]
		if t > limit then
			break
		end
		do
			for _, m in mates do
				if t < m.skip then
					continue
				end
				-- the ball leaving HIS foot is the kick itself, not a touch: a one-touch shot / quick pass-and-shoot has no
				-- ownership record for the new kicker, so the "touch at 0.00" hid the shot for 0.15 s (log: bait touch 0.00 d 2.4)
				if t < 0.07 and flat(m.pos - samples[1]).Magnitude < 4.5 then
					continue
				end
				local lead = m.dly + math.min(t, 0.5)
				local c = m.pos + m.vel * lead
				local hold = { CFrame = CFrame.new(c) }
				local grow = math.clamp(m.run * (t - 0.15), 0, reachMax) * 2
				local box = { Size = m.src.Size + Vector3.new(grow, 0, grow), Shape = m.src.Shape, CFrameOffset = m.src.CFrameOffset }
				local alpha = HitboxSettings.GetSegmentEnterAlpha(hold, box, samples[i - 1], samples[i])
				if alpha then
					return { t = ts[i - 1] + (ts[i] - ts[i - 1]) * (type(alpha) == "number" and alpha or 1), name = m.name, dist = flat(c - samples[1]).Magnitude, c = c }
				end
			end
		end
	end
	return nil
end

-- PRESS v2: AutoGK against a carrier at our goal.
--  threat   distance to the mouth SEGMENT (not its centre) and how fast he closes on it. A flank runner cutting to the near
--           post is a threat; the old test (straight line into the mouth within 1.8 s, or <= 30 studs of the centre) skipped
--           every diagonal run (log: 15 x "no need" with lat 30..66, then the goal).
--  futures  his server pose = displayed + v * (display delay + ping/2), then a weighted fan: keep running, ease off, turn
--           +-25 / +-50 deg over 0.3 s, cut to the near post, stop. Airborne (rocket / blast launch): ballistic Y with
--           workspace gravity and little air steering; jetpack: no gravity, capped lift.
--  dive     the real dive: GetTravel (cubic out, Distance in DurationSeconds); vertical = the dive's own gravity rig
--           (InitialVerticalVelocity, GravityStudsPerSecondSquared) started from the height we are at, so a dive out of a
--           jump keeps rising from the jump height and then falls (the old model froze the jump height). Contact = flat
--           <= PressReach and |dy| <= PressVert. Confidence = weight of the futures the dive catches.
--  aim      GoalkeeperDive.GetWorldDirection is a module field: performDive sends its result as AimDirection, Run reads it
--           every Heartbeat (the game steers a dive with the camera). While our press dive runs it returns our vector
--           (any angle, not one of the 8 camera choices) and turns it toward him at <= GkPressTurn rad/s.
-- Server hit radius / stun rule are not in the dump: `gk press result` logs the closest approach.
Mark.gkAimHook = function()
	local D = require(Modules.Actions.GoalkeeperDive)
	if Mark.gkAimOrig then
		return
	end
	Mark.gkAimOrig = D.GetWorldDirection
	D.GetWorldDirection = function(choice, cf, fb)
		local a = Mark.gkDiveAim
		if a and not a.hold and os.clock() < a.untilT then
			return a.dir
		end
		return Mark.gkAimOrig(choice, cf, fb)
	end
	-- The animation is DirectionChoice.Name (GetDirectionChoice reads the move command against the CAMERA); the dash goes
	-- along GetWorldDirection. With our exact direction the name came from the camera frame while the body was locked to
	-- another facing: dash forward, animation "left" (log report). A press dive faces the way it goes: choice = F.
	local AM = require(Modules.Actions.ActionMotion)
	local origChoice = D.GetDirectionChoice
	D.GetDirectionChoice = function(...)
		local a = Mark.gkDiveAim
		if a and a.faceF and os.clock() < a.untilT then
			return AM.DirectionChoices.F
		end
		return origChoice(...)
	end
	-- GoalkeeperDiveAssist bends every dive toward the BALL's flight (yaw up to 12 deg, travel scale 0.3..1.3, extra reach
	-- up to 3 studs) and re-locks it each curve update. Against a carrier the ball is at his feet and moves with him: the
	-- dash left our solved line (log: two dives, closest 6.0 / 9.1). A press dive is exactly what we solved: no assist.
	local A = require(Modules.Actions.GoalkeeperDiveAssist)
	local function pressLive()
		local a = Mark.gkDiveAim
		return a and a.faceF and os.clock() < a.untilT
	end
	local oGet, oBody, oRelock = A.GetAssist, A.GetBodyAssist, A.CreateDiveRelock
	A.GetAssist = function(...)
		if pressLive() then
			return nil
		end
		return oGet(...)
	end
	A.GetBodyAssist = function(...)
		if pressLive() then
			return nil
		end
		return oBody(...)
	end
	A.CreateDiveRelock = function(...)
		if pressLive() then
			return function() end
		end
		return oRelock(...)
	end
end
Mark.gkAimHook()

-- homing of a running press dive (what turning the camera does in the game)
Mark.gkAimTick = function(root)
	local now = os.clock()
	-- pre-turn (gkPress turns the body to him while a contact is near): released 0.15 s after the last refresh
	local pf = Mark.gkPreFace
	if pf and now - pf.at > 0.15 and not Mark.gkDiveAim then
		Mark.gkPreFace = nil
		TurnControl.ReleaseAutoRotate("Goalkeeper")
	end
	local a = Mark.gkDiveAim
	if not a then
		return
	end
	if now >= a.untilT then
		Mark.gkDiveAim = nil
		if a.faceLock then
			TurnControl.ReleaseAutoRotate("Goalkeeper")
		end
		return
	end
	if a.faceLock then
		TurnControl.LockAutoRotate("Goalkeeper", a.dir)
	end
	local dt = math.clamp(now - (a.tickAt or now), 0, 0.05)
	a.tickAt = now
	if CFG.GkPressHome == false or not (a.model and a.model.Parent) or now - a.at > 0.6 then
		return
	end
	local er = a.model:FindFirstChild("HumanoidRootPart")
	if not er then
		return
	end
	local P, V = Mark.carrierPose(er, a.model)
	local to = flat(P + V * a.lead - root.Position)
	if to.Magnitude < 1.5 then
		return
	end
	local want = to.Unit
	if a.fwd and want:Dot(a.fwd) < -0.25 then
		return
	end
	local ang = math.acos(math.clamp(a.dir:Dot(want), -1, 1))
	local maxA = (CFG.GkPressTurn or 6) * dt
	if ang <= maxA then
		a.dir = want
	elseif ang > 1e-3 then
		a.dir = unitOrNil(a.dir:Lerp(want, maxA / ang)) or a.dir
	end
end

local function gkRot(v, a)
	return v * math.cos(a) + Vector3.new(-v.Z, 0, v.X) * math.sin(a)
end

-- JETPACK (dump: Modules.Actions.JetpackMotion.Run, run by HIS client, we see the replicated body):
--   horizontal RunCFrameDash 55 st over 3.5 s, Quart-Out, along his facing (he steers, ControlledTurnSpeed 2.5 rad/s);
--   lift: LiftDelaySeconds 0.5, then 25 st over 1 s Cubic-InOut (a CFrame rig: no gravity while it runs), then the rig is
--   released and he FALLS (StartItemFallLoop) until WatchLanding -> a 14 st / 0.875 s landing dash forward.
-- JetpackMotion.IsActive only knows the local player (SetActive is never called for others), so the old "jet" branch
-- never ran: a jetpack flier was the generic "air" case, ballistic with his tiny initial vy (log: vy 7.2, dy 0.5 ->
-- "contact" in 0.28 s, conf 1.00, he was 10+ studs up by then). jet = { te = phase of his displayed pose, dir, base }.
Mark.jetCurveH = function(te)
	local u = math.clamp(te / 3.5, 0, 1)
	return 55 * (1 - (1 - u) ^ 4)
end
Mark.jetCurveY = function(te, g)
	if te <= 0.5 then
		return 0
	elseif te <= 1.5 then
		local u = te - 0.5
		return 25 * (u < 0.5 and 4 * u * u * u or 1 - ((-2 * u + 2) ^ 3) / 2)
	end
	local tf = te - 1.5
	return math.max(25 - 0.5 * g * tf * tf, 0)
end
Mark.jetFutures = function(P, jet, floorY, lead, g)
	local DT, N = 0.025, 52
	local out = {}
	local ground = jet.base or floorY
	for _, h in { { 0, 1 }, { 0.45, 0.5 }, { -0.45, 0.5 }, { 1, 0.25 }, { -1, 0.25 } } do
		local pts = table.create(N + 1)
		local x, z = P.X, P.Z
		local te = jet.te
		local function step(t0, t1, A)
			local dist = Mark.jetCurveH(t1) - Mark.jetCurveH(t0)
			local f = math.min((t1 - jet.te) * 2.5 / math.max(math.abs(A), 1e-3), 1)
			local dir = A ~= 0 and gkRot(jet.dir, A * f) or jet.dir
			x += dir.X * dist
			z += dir.Z * dist
		end
		step(te, te + lead, h[1])
		pts[1] = Vector3.new(x, ground + Mark.jetCurveY(te + lead, g), z)
		for k = 1, N do
			local a, b = te + lead + (k - 1) * DT, te + lead + k * DT
			step(a, b, h[1])
			pts[k + 1] = Vector3.new(x, math.max(ground + Mark.jetCurveY(b, g), floorY), z)
		end
		out[#out + 1] = { w = h[2], pts = pts, air = true }
	end
	return out
end

-- weighted futures of his server pose, sampled every 0.025 s from now (index 1 = now)
Mark.gkFutures = function(P, V, vy, air, jet, floorY, lead, aimP, g, dribReady)
	local DT, N = 0.025, 52
	local sp = flat(V).Magnitude
	local dGoal = unitOrNil(flat(aimP - P)) or Vector3.new(0, 0, 1)
	local base = sp > 2 and flat(V).Unit or dGoal
	local list
	if type(jet) == "table" then
		return Mark.jetFutures(P, jet, floorY, lead, g)
	elseif jet then
		list = { { 0, 1, 1 }, { 0.26, 1, 0.5 }, { -0.26, 1, 0.5 } }
	elseif air then
		list = { { 0, 1, 1 }, { 0.14, 1, 0.5 }, { -0.14, 1, 0.5 }, { 0, 0.85, 0.4 } }
	else
		list = { { 0, 1, 1 }, { 0, 0.6, 0.5 }, { 0.44, 1, 0.6 }, { -0.44, 1, 0.6 }, { 0.87, 0.9, 0.3 }, { -0.87, 0.9, 0.3 }, { 2.8, 0.8, 0.25 }, { -2.8, 0.8, 0.25 }, { "goal", 1, 0.6 }, { "stop", 0, 0.35 } }
		if dribReady then
			-- his dribble is ready: Dodge = a ~5 stud side dash + iframe, a dive into it is wasted
			list[#list + 1] = { "burst", 1, 0.9, 1 }
			list[#list + 1] = { "burst", 1, 0.9, -1 }
		end
	end
	local perp = Vector3.new(-base.Z, 0, base.X)
	local gAng = math.atan2(dGoal:Dot(perp), dGoal:Dot(base))
	local lift = (Mark.jetM and Mark.jetM.Constants and Mark.jetM.Constants.LiftDistance) or 25
	local out = {}
	for _, h in list do
		local A, sc = h[1], h[2]
		local burst = nil
		if A == "burst" then
			A, burst = 0, h[4]
		end
		local s1 = sp
		if A == "goal" then
			A = gAng
			s1 = math.max(sp, 18)
		elseif A == "stop" then
			A = 0
		end
		local pts = table.create(N + 1)
		local x, z = P.X + base.X * sp * lead, P.Z + base.Z * sp * lead
		local function y(tt)
			if jet then
				return math.clamp(P.Y + vy * tt, floorY, floorY + lift)
			elseif air then
				return math.max(P.Y + vy * tt - 0.5 * g * tt * tt, floorY)
			end
			return P.Y
		end
		pts[1] = Vector3.new(x, y(lead), z)
		for k = 1, N do
			local tt = (k - 0.5) * DT
			local f = math.min(tt / 0.3, 1)
			local dir = A ~= 0 and gkRot(base, A * f) or base
			local spd = (sp + (s1 * sc - sp) * f)
			x += dir.X * spd * DT
			z += dir.Z * spd * DT
			if burst and tt > 0.08 and tt < 0.3 then
				x += -base.Z * burst * 25 * DT
				z += base.X * burst * 25 * DT
			end
			pts[k + 1] = Vector3.new(x, y(lead + k * DT), z)
		end
		out[#out + 1] = { w = h[3], pts = pts, air = air or jet }
	end
	return out
end

-- best dive against the futures. o: root, vel, futs, D, dist, maxD, R, H, mouth, fwd, g, jumpH, air, exact, camCF, facing
Mark.gkPressSolve = function(o)
	local D, futs = o.D, o.futs
	local DT = 0.025
	local wSum = 0
	for _, f in futs do
		wSum += f.w
	end
	local v0 = D.Constants.InitialVerticalVelocity or 15
	local gd = -(D.Constants.GravityStudsPerSecondSquared or -65)
	local vJ = math.sqrt(2 * o.g * o.jumpH)
	local opts = { { T0 = 0 }, { T0 = 0.12 }, { T0 = 0.25 } }
	if o.air and CFG.GkPressJump ~= false then
		for _, td in { 0.12, 0.2, 0.28 } do
			opts[#opts + 1] = { T0 = td, jump = td }
		end
	end
	-- the weighted centre of his futures: the catch region the bearings are taken at
	local cen = table.create(#futs[1].pts)
	for k = 1, #futs[1].pts do
		local sx, sy, sz = 0, 0, 0
		for _, f in futs do
			local p = f.pts[k]
			sx += p.X * f.w
			sy += p.Y * f.w
			sz += p.Z * f.w
		end
		cen[k] = Vector3.new(sx / wSum, sy / wSum, sz / wSum)
	end
	local R2 = o.R * o.R
	local bestNow, bestLater = nil, nil
	for _, op in opts do
		local T0 = op.T0
		local p0 = o.root + o.vel * T0
		local yBase = o.root.Y + (op.jump and math.max(vJ * op.jump - 0.5 * o.g * op.jump * op.jump, 0) or 0)
		local dirs = {}
		if o.exact then
			-- AIM AT HIM, not at where he will be: the line to his server pose at the moment the dash starts (homing keeps
			-- turning it at him while it runs). A lead toward the main future is tried only after the direct line scored
			-- >= 0.85, and only a fraction of the way (0.3 / 0.6): a guess about a man who can still turn is what put the
			-- dash beside him.
			local kS = math.min(math.floor(T0 / DT + 0.5) + 1, #futs[1].pts)
			local now = flat(futs[1].pts[kS] - p0)
			local kC = math.min(math.floor((T0 + 0.32) / DT + 0.5) + 1, #cen)
			local fut = flat(cen[kC] - p0)
			for _, fr in { 0, 0.3, 0.6 } do
				local d1 = unitOrNil(now + (fut - now) * fr)
				if d1 then
					dirs[#dirs + 1] = { dir = d1, frac = fr }
				end
			end
		else
			for _, choice in Mark.actionMotion.DirectionChoices do
				local wd = Mark.gkAimOrig(choice, o.camCF, o.facing)
				if typeof(wd) == "Vector3" then
					dirs[#dirs + 1] = { dir = wd, frac = 0 }
				end
			end
		end
		local leadOk = false
		for _, rec in dirs do
			local dir = rec.dir
			if dir:Dot(o.fwd) > -0.25 and (rec.frac == 0 or leadOk) then
				local conf, tMain, tAny, hits = 0, nil, nil, nil
				for fi, f in futs do
					local pts = f.pts
					for i = 1, 35 do
						local tau = i * DT
						local travel = D.GetTravel(tau, o.dist)
						-- contact on the last stretch of the curve is a threshold: one step back by him and the dash ends short
						-- (log: the dash did not even reach him). Only the first RF of the dive counts.
						if travel > o.maxD or travel > o.dist * o.RF then
							break
						end
						local tAbs = T0 + tau
						local E = pts[math.floor(tAbs / DT + 0.5) + 1]
						if not E then
							break
						end
						local Kf = p0 + dir * travel
						if flat(E - o.mouth):Dot(o.fwd) < 0.5 or flat(Kf - o.mouth):Dot(o.fwd) < 0.3 then
							break -- he is in (or we would be behind the line) before the contact
						end
						local ky = op.jump and (yBase + v0 * tau - 0.5 * gd * tau * tau) or (o.root.Y + D.GetVerticalTravel(tau))
						ky = math.max(ky, o.root.Y)
						local dx, dz = Kf.X - E.X, Kf.Z - E.Z
						local touch = dx * dx + dz * dz <= R2 and math.abs(ky - E.Y) <= o.H
						-- a flier crosses our height at up to ~100 st/s (bazooka jump coming down): the overlap lasts a few
						-- server frames and his server pose is ahead of our estimate by up to ping/2 + jitter (o.slip). The
						-- contact must still hold with him that much further along his arc, or it is a coin toss (log: jump +
						-- dive, closest 0.1 flat, no stun). This pushes the plan to where he moves slowly: apex or landing.
						-- a man we already overlap at the dash start is passed through (the server counts the hit only once
						-- the dash has moved us: the slide / dive start pose is not a contact). Too close = no catch.
						if touch and tau < (o.minT or 0) then
							break
						end
						if touch and o.slip then
							for _, off in { o.slip * 0.5, o.slip } do
								local E2 = pts[math.floor((tAbs + off) / DT + 0.5) + 1] or pts[#pts]
								local ex, ez = Kf.X - E2.X, Kf.Z - E2.Z
								if ex * ex + ez * ez > R2 or math.abs(ky - E2.Y) > o.H then
									touch = false
									break
								end
							end
						end
						if touch then
							conf += f.w
							hits = hits or {}
							hits[fi] = tAbs
							if fi == 1 then
								tMain = tAbs
							end
							tAny = tAny and math.min(tAny, tAbs) or tAbs
							break
						end
					end
				end
				conf /= wSum
				if rec.frac == 0 then
					leadOk = conf >= 0.85
				end
				if conf > 0 then
					local cand = { conf = conf, dir = dir, T0 = T0, jump = op.jump, t = tMain or tAny, hits = hits, frac = rec.frac }
					local now0 = T0 == 0 or op.jump ~= nil
					local cur = now0 and bestNow or bestLater
					if not cur or conf - 0.12 * rec.frac > cur.conf - 0.12 * (cur.frac or 0) + 0.01 or (math.abs(conf - cur.conf) <= 0.01 and cand.t < cur.t) then
						if now0 then
							bestNow = cand
						else
							bestLater = cand
						end
					end
				end
			end
		end
	end
	return bestNow, bestLater, cen
end

-- The jetpack phase of an enemy (a packet told us he fired it): { te, dir, base } or false. One reading for the press on the
-- carrier and for the flier scan.
Mark.jetRead = function(uid, er, P, V, rootY, now, ping, lead, airborne, vyT, g, fwdDefault)
	local jr = Mark.jets and Mark.jets[uid]
	if not (jr and now - jr.at < 4) then
		return false
	end
	-- phase of the DISPLAYED pose: packet time + ping/2 - his display delay; while he is in the lift his height says
	-- it better (invert the Cubic-InOut), the packet time is only the fallback
	local te = now - jr.at + ping * 0.5 - (lead - ping * 0.5)
	local hgt = P.Y - rootY
	if te > 0.4 and te < 1.6 and hgt > 0.8 and hgt < 24.5 and vyT > 1 then
		local f = hgt / 25
		local u = f < 0.5 and (f / 4) ^ (1 / 3) or (1 - ((2 - 2 * f) ^ (1 / 3)) / 2)
		te = 0.5 + u
	end
	if te > 1.6 and not airborne then
		Mark.jets[uid] = nil -- landed
		return false
	elseif te < 2.6 then
		local dirJ = unitOrNil(flat(er.CFrame.LookVector)) or unitOrNil(flat(V)) or fwdDefault
		return { te = te, dir = dirJ, base = P.Y - Mark.jetCurveY(te, g) }
	end
	return false
end

-- Vertical state of another player's body (shared by AutoGK press and the air duel). See the note inside.
Mark.vertState = function(model, P, baseY, airborne, now, g)
	-- VERTICAL STATE. CharacterMotion.GetVelocity has Y = 0 for another player: vy and ay come from the history of his
	-- displayed Y (samples >= 12 ms apart, 0.3 s kept): vy = slope of the last 0.1 s, ay = change of the slope against the
	-- 0.1 s before. Launchers do not all fly the same way (dump):
	--   ShotgunRecoil: AssemblyLinearVelocity = up 30 (+50 aiming down) + back 30 -> ballistic;
	--   bazooka at the feet / explosions: server knock-back -> ballistic;
	--   JetpackMotion: a CFrame lift rig (Mark.jetFutures); GrappleMotion: a 75 st/s pull at the hook -> powered.
	-- "ballistic" = ay within 35 % of -gravity: the arc is known, the solver gets the measured vy. "fresh" = in the air for
	-- < 0.1 s, the slope is not measured yet. "powered" = anything else rising / hovering: the arc is NOT known.
	Mark.yHist = Mark.yHist or setmetatable({}, { __mode = "k" })
	local yh = Mark.yHist[model]
	if not yh or now - yh.last > 0.3 then
		yh = { list = {}, last = now - 1, airAt = nil }
		Mark.yHist[model] = yh
	end
	if now - yh.last >= 0.012 then
		yh.list[#yh.list + 1] = { t = now, y = P.Y }
		yh.last = now
	end
	while #yh.list > 2 and now - yh.list[1].t > 0.3 do
		table.remove(yh.list, 1)
	end
	local function yAt(age)
		local best = nil
		for _, e in yh.list do
			if now - e.t >= age - 0.02 then
				best = e
			end
		end
		return best
	end
	local yNow, yMid, yOld = yh.list[#yh.list], yAt(0.1), yAt(0.2)
	local vyT, ayT = 0, nil
	if yMid and yNow.t - yMid.t > 0.04 then
		vyT = (yNow.y - yMid.y) / (yNow.t - yMid.t)
		if yOld and yMid.t - yOld.t > 0.04 then
			local vOld = (yMid.y - yOld.y) / (yMid.t - yOld.t)
			ayT = (vyT - vOld) / ((yNow.t - yOld.t) * 0.5)
		end
	end
	local dyNow = P.Y - baseY
	if not airborne and dyNow > 3 then
		airborne = true -- IsLanded lags a launch by a few frames; 3 studs over our root is not standing
	end
	-- IsLanded of ANOTHER player flaps (a step on the ball, a slope, a dodge hop): "in the air" with no rise is not a
	-- take-off. Log: "duel plan kick ... h -0.0" then "he landed" 26 ms later - we jumped at a man standing on the grass
	-- and slid from the air (short slide, miss, goal). A take-off is confirmed by the body itself: 0.5 stud over the Y he
	-- last stood at, or a rising slope. Until then airAt follows the clock, so a real jump is timed from its last frame.
	if not airborne then
		yh.gY = P.Y
	elseif dyNow <= 3 and P.Y - (yh.gY or baseY) < 0.5 and vyT < 6 then
		airborne = false
		yh.airAt = now
	end
	if airborne then
		yh.airAt = yh.airAt or now
	elseif not (yh.airAt == now) then
		yh.airAt = nil
	end
	local vKind = "ground"
	if airborne then
		if now - yh.airAt < 0.1 or not ayT then
			vKind = "fresh"
		elseif math.abs(ayT + g) <= g * 0.35 then
			vKind = "ballistic"
		elseif vyT < -4 and ayT < 0 then
			vKind = "ballistic" -- falling and still accelerating down: a drop, the arc ends on the floor either way
		else
			vKind = "powered"
		end
	end
	if vKind == "ballistic" and yMid then
		vyT = vyT - g * (yNow.t - yMid.t) * 0.5 -- the slope is the speed at the middle of the window: bring it to now
	end
	return { vy = vyT, ay = ayT, kind = vKind, airborne = airborne, dy = dyNow, airAt = yh.airAt }
end

-- FLIER (user: a lob, a rocket punch on the ball, then a hook to it - he flew into the goal and the keeper stood). Two holes: the
-- press only knew the CARRIER (a lob leaves his hands: nobody is "owner") and a hook it SAW by packet, and both were switched off
-- while the ball was a "shot" (the lob flying at the goal IS one). Now it reads every enemy BODY by what it does, not by the item in
-- his hand: his measured flight (Mark.gkFutures: the same futures the dive is solved against, the jetpack's own timeline when a
-- packet told us) enters our mouth within the horizon AND the ball is near that path at that time (a body that never meets the
-- ball scores nothing). The dive stays the game's: a forward dash into him, solved by gkPressSolve.
-- the ball's position t seconds ahead from the live path (Mark.ballPath samples / times), else where it lies now
Mark.pathAt = function(bs, bt, now)
	local nb = bs and #bs or 0
	if nb < 2 or not bt then
		if typeof(now) ~= "Vector3" then
			return nil
		end
		return function()
			return now
		end
	end
	return function(t)
		if t >= bt[nb] then
			return bs[nb]
		end
		for i = 2, nb do
			if bt[i] >= t then
				local a, b = bt[i - 1], bt[i]
				return bs[i - 1]:Lerp(bs[i], b > a and math.clamp((t - a) / (b - a), 0, 1) or 0)
			end
		end
		return bs[nb]
	end
end

-- when (s from now) and where his path is in our mouth with the ball near it. o: pts (0.025 s steps, index 1 = now), DT, mouth, fwd,
-- side, half, inside (studs in front of the line that count as "in"), pad (studs beside the posts), ballAt(t), link (studs)
Mark.gkFlierEta = function(o)
	local pts = o.pts
	for k = 1, #pts do
		local rel = flat(pts[k] - o.mouth)
		if rel:Dot(o.fwd) <= o.inside and math.abs(rel:Dot(o.side)) <= o.half + o.pad then
			local t = (k - 1) * o.DT
			local b = o.ballAt(t)
			if b and flat(b - pts[k]).Magnitude <= o.link then
				return t, pts[k]
			end
		end
	end
	return nil
end

-- may the press dive go while the ball plan / the shot say something else? The carrier: no shot, no ball plan. A hook flier or a
-- flier body: through a shot (the lob IS the shot he flies after); a flier only if the keeper's own ball plan is not earlier
Mark.gkPressGate = function(shot, plan, hookId, flierId, flierT)
	if hookId then
		return true
	end
	if flierId then
		return plan == nil or plan.kind == "dive" or (flierT or math.huge) <= plan.t + 0.05
	end
	return not shot and plan == nil
end

-- the enemy body that gets to our mouth soonest with the ball near its path (uid, t, kind), not the carrier (his press is the old
-- one) and not a hooker (his path is exact: Mark.gkHooker). Cached 0.05 s.
Mark.gkFlierPick = function(root, mouth, side, fwd, half, now, ownerId)
	local fc = Mark.gkFlierCache
	if fc and now - fc.at < 0.05 then
		return fc.uid, fc.t, fc.kind
	end
	local uid, tBest, kBest = nil, math.huge, nil
	local _, _, bs, bt = Mark.ballPath(root)
	local ballAt = Mark.pathAt(bs, bt, Renderer.GetPosition())
	if ballAt then
		local g = workspace.Gravity
		local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local zone = CFG.GkFlierZone or 90
		for _, model in Mark.models() do
			local actor = Actors.GetFromCharacter(model)
			local id = actor and actor.UserId
			if actor and actor ~= LocalPlayer and id ~= ownerId and not sameTeam(actor) and not isGoalkeeper(actor) and not (Mark.grapples and Mark.grapples[id]) then
				local er = ActorTargeting.GetActorRoot(actor)
				local hum = model:FindFirstChildOfClass("Humanoid")
				if er and hum and flat(er.Position - mouth).Magnitude <= zone then
					local lr = Mark.launchRec and Mark.launchRec[id]
					local jr = Mark.jets and Mark.jets[id]
					local airborne = not CharacterControllers.IsLanded(model, hum)
					local wv = CharacterMotion.GetVelocity(model)
					local fast = typeof(wv) == "Vector3" and flat(wv).Magnitude >= (CFG.GkFlierSpeed or 32)
					local down = Mark.mateDown(actor, model)
					if down then
						local hrp = model:FindFirstChild("HumanoidRootPart")
						local vD = hrp and hrp.AssemblyLinearVelocity
						-- a ragdoll thrown at the goal flies; a ragdoll lying there does not
						down = not (typeof(vD) == "Vector3" and (flat(vD).Magnitude > 8 or math.abs(vD.Y) > 8))
					end
					if not down and (airborne or fast or (lr and now - lr.at < 0.6) or (jr and now - jr.at < 4)) then
						local P, V, W = Mark.carrierPose(er, model)
						local vf = flat(W)
						if vf.Magnitude > V.Magnitude then
							V = vf
						end
						local lead = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25) + ping * 0.5
						local vs = Mark.vertState(model, P, root.Position.Y, airborne, now, g)
						local vy = vs.airborne and ((math.abs(W.Y) > 0.5) and W.Y or vs.vy) or 0
						local jet = Mark.jetRead(id, er, P, V, root.Position.Y, now, ping, lead, vs.airborne, vs.vy, g, fwd)
						local futs = Mark.gkFutures(P, V, vy, vs.airborne, jet, root.Position.Y, lead, mouth, g, false)
						local t = Mark.gkFlierEta({
							pts = futs[1].pts, DT = 0.025, mouth = mouth, fwd = fwd, side = side, half = half,
							inside = 3, pad = 3, ballAt = ballAt, link = CFG.GkFlierLink or 12,
						})
						if t and t < tBest then
							uid, tBest, kBest = id, t, jet and "jet" or vs.kind
							if not Mark.gkFlierLog or now - Mark.gkFlierLog > 0.5 then
								Mark.gkFlierLog = now
								logFile("gk flier", actorName(actor), "in", string.format("%.2f", t), "kind", tostring(kBest), "dSeg", string.format("%.1f", flat(P - mouth).Magnitude), "dy", string.format("%.1f", P.Y - root.Position.Y))
							end
						end
					end
				end
			end
		end
	end
	Mark.gkFlierCache = { at = now, uid = uid, t = uid and tBest or nil, kind = kBest }
	return uid, uid and tBest or nil, kBest
end

-- HOOK FLIER (user: the enemy shot at the bar on purpose, grappled to the rebound and flew in - the keeper did nothing).
-- GrappleMotion is exact (Mark.grapplePath: the hook flies to the BALL, then a 75 st/s pull homing on it), so the dive can be
-- solved against his real path instead of being refused as "powered flight". Pure: his arrival point A is a threat when it is
-- on our side of the goal line (-1 stud) and within `zone` of the mouth segment.
Mark.hookThreat = function(A, mouth, side, fwd, half, zone)
	local rel = flat(A - mouth)
	if rel:Dot(fwd) < -1 then
		return false
	end
	return (rel - side * math.clamp(rel:Dot(side), -half, half)).Magnitude <= zone
end

-- the enemy field player whose hook lands in our zone soonest (uid, arrival t), or nil
Mark.gkHooker = function(root, mouth, side, fwd, half)
	if CFG.GkHookPress == false or not Mark.grapples or next(Mark.grapples) == nil then
		return nil
	end
	local best, bt = nil, math.huge
	for uid in Mark.grapples do
		local pl = playerOf(uid)
		local model = pl and pl ~= LocalPlayer and not sameTeam(pl) and not isGoalkeeper(pl) and Actors.GetCharacter(pl)
		local hr = model and ActorTargeting.GetActorRoot(pl)
		if hr then
			local gp, tA = Mark.grapplePath(uid, model, (Mark.carrierPose(hr, model)), root)
			if gp and tA and tA < bt and Mark.hookThreat(gp[math.min(math.floor(tA / 0.025 + 0.5) + 1, #gp)], mouth, side, fwd, half, CFG.GkPressZone or 90) then
				best, bt = uid, tA
			end
		end
	end
	return best, bt
end

Mark.gkPress = function(character, root, c)
	Mark.gkPressStandP = nil
	if CFG.GkPress == false then
		return false
	end
	local pl, er = enemyCarrier(c.ownerId)
	if not (pl and er) then
		return false
	end
	local model = Actors.GetCharacter(pl)
	local hum = model and model:FindFirstChildOfClass("Humanoid")
	if not (model and hum) then
		return false
	end
	-- a flier body (Mark.gkFlierPick), not the carrier: no ball at his feet, so no dribble, flick, charge, pass and "he shoots first"
	local bare = c.flier == true
	local function note(why)
		if not Mark.gkPressLog or c.now - Mark.gkPressLog > 0.5 then
			Mark.gkPressLog = c.now
			logFile("gk press", why, actorName(pl))
		end
		return false
	end
	-- a downed carrier is no threat - unless the hit is what carries him: a mine / bazooka / explosion ragdolls him and
	-- throws him (and the ball he holds) at our goal (log: "gk press skip down", 0.5 s later he flew in from dSeg 9.5,
	-- dy 15, the keeper stood). A ragdolled body flying faster than 8 st/s is a flier, read like any other launch.
	local downFly = false
	if Mark.mateDown(pl, model) then
		local hrp = model:FindFirstChild("HumanoidRootPart")
		local vD = hrp and hrp.AssemblyLinearVelocity
		if not (typeof(vD) == "Vector3" and (flat(vD).Magnitude > 8 or math.abs(vD.Y) > 8)) then
			return note("skip down")
		end
		downFly = true
	end
	local D = c.diveMod
	local P, V, W = Mark.carrierPose(er, model)
	local vf = flat(W)
	if vf.Magnitude > V.Magnitude then
		V = vf -- a launched player moves faster than the walk-speed clamps of carrierPose assume
	end
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local lead = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25) + ping * 0.5
	local airborne = not CharacterControllers.IsLanded(model, hum)
	local g = workspace.Gravity
	local vs = Mark.vertState(model, P, root.Position.Y, airborne, c.now, g)
	local vyT, ayT, vKind, dyNow = vs.vy, vs.ay, vs.kind, vs.dy
	airborne = vs.airborne
	local vy = airborne and ((math.abs(W.Y) > 0.5) and W.Y or vyT) or 0
	-- a launcher fired by him a moment ago while he still stands: he is about to fly, the arc is unknown
	local lr = Mark.launchRec and Mark.launchRec[pl.UserId]
	local launchPending = lr and not airborne and c.now - lr.at < 0.45 and lr.kind or nil
	Mark.jetM = Mark.jetM or require(Modules.Actions.JetpackMotion)
	local jet = Mark.jetRead(pl.UserId, er, P, V, root.Position.Y, c.now, ping, lead, airborne, vyT, g, c.fwd)
	local fwd, side, mouth, half = c.fwd, c.side, c.mouth, c.half
	-- he is on a hook: his path to the ball is exact (arrival point hookA at hookT); it replaces the speed read everywhere below
	local hookPts, hookT, hookA = nil, nil, nil
	if CFG.GkHookPress ~= false and Mark.grapples and Mark.grapples[pl.UserId] then
		local gp, tA = Mark.grapplePath(pl.UserId, model, P, root)
		if gp and tA then
			local A = gp[math.min(math.floor(tA / 0.025 + 0.5) + 1, #gp)]
			if Mark.hookThreat(A, mouth, side, fwd, half, CFG.GkPressZone or 90) then
				hookPts, hookT, hookA = gp, tA, A
			end
		end
	end

	-- threat: distance to the mouth segment and the speed he closes on it
	local E0 = P + flat(V) * lead
	local rel = flat(E0 - mouth)
	local along = rel:Dot(fwd)
	if along < -1 then
		return note("skip behind line")
	end
	local nearP = mouth + side * math.clamp(rel:Dot(side), -half, half)
	local toSeg = flat(nearP - E0)
	local dSeg = toSeg.Magnitude
	local appr = flat(V):Dot(unitOrNil(toSeg) or -fwd)
	local tReach = appr > 1 and dSeg / appr or math.huge
	local inMouth = math.abs(rel:Dot(side)) <= half + 2.5
	local committed = airborne and along <= D.GetDistance(LocalPlayer) and inMouth
	local zone = CFG.GkPressZone or 90
	-- a press target GOES at the goal: most of his speed points at the mouth (appr >= half his speed and >= 6 st/s), or he is
	-- already on top of it. "appr > 2" made every carrier drifting in the zone a target (log: press/stand all the time).
	local spd = flat(V).Magnitude
	local going = appr >= math.max(6, spd * 0.5)
	local threat = committed or dSeg <= 16 or (dSeg <= zone and going) or (tReach <= 2.2 and appr > 6)
	if hookPts then
		threat, tReach = true, hookT
	elseif bare then
		threat, tReach = true, c.flierT or tReach
	end
	-- appr hovers around the 2 st/s edge while he dribbles: the stand flipped press/free every frame (log). Hold 0.6 s.
	if threat then
		Mark.gkThreatUntil = c.now + 0.6
		Mark.gkThreatId = c.ownerId
	elseif Mark.gkThreatUntil and c.now < Mark.gkThreatUntil and Mark.gkThreatId == c.ownerId and dSeg <= zone * 1.2 then
		threat = true
	end
	if not threat then
		return note(string.format("idle dSeg %.1f appr %.1f", dSeg, appr))
	end
	-- he flicked: the ball leaves his feet (detach in ~0.4 s) and goes over us. The save logic owns the ball; a dive at the
	-- man who no longer has it is the open goal.
	local fr = Mark.flickRec and Mark.flickRec[pl.UserId]
	if fr and not bare and c.now - fr.at < 1.2 then
		-- before the detach the ball is still at his feet (RainbowFlick BallDetachSeconds 0.4): a dive at him takes it.
		-- Only after it does the lob leave him (v171 session: 9 refusals here, some mid wind-up)
		local carried = fr.detachSrv ~= nil and Workspace:GetServerTimeNow() + ping * 0.5 < fr.detachSrv - 0.05
		if not carried then
			return note("skip flick")
		end
	end
	local imminentT = tReach <= (CFG.GkPressLate or 0.9)
	-- the last man only: an open attacker nearer the goal or level with him (BlockLevelSlack) is the pass he plays the
	-- moment we leave the line. Then we do not come out and do not dive; he can still score himself only if he is at the
	-- mouth within GkPressLate s or flying in.
	if CFG.GkPressLastMan ~= false and not bare and not committed and not imminentT then
		local sup, sd = Mark.gkSupport(pl, P, mouth, side, half, dSeg)
		if sup then
			return note(string.format("pass option %s dSeg %.1f vs %.1f", actorName(sup), sd, dSeg))
		end
	end
	-- his dribble (Dodge: side dash + iframe, our dive cooldown 1.9 s afterwards = open goal) is ready unless we saw it spent
	local drec = dribbleSeen[model] or dribbleSeen[pl.UserId]
	local dribReady = not (drec and drec.cdUntil and drec.cdUntil > c.now + 0.6)
	-- the post he is going for is the side of the mouth he closes on; aim the futures' "cut in" at it
	-- RUSH (user: a man running at our goal is caught, not watched). A grounded carrier who GOES at the mouth inside
	-- GkRushZone is dived at without his dribble side-bursts in the fan and with GkRushConf: a dribble against the dive
	-- is the risk taken. "Only when sure" gave 0-2 press dives per session in every log since v134.
	local rush = CFG.GkRush ~= false and not bare and not airborne and not jet and not hookPts and going and dSeg <= (CFG.GkRushZone or 35)
	local futs = hookPts and { { w = 1, pts = hookPts, air = true } } or Mark.gkFutures(P, V, vy, airborne, jet, root.Position.Y, lead, nearP + fwd * 0.5, g, dribReady and not airborne and not jet and not rush)

	-- come out on his line to the mouth: close the angle so the dive reaches him before he reaches the line. Only when it
	-- matters: he is inside GkPressMoveZone and reaches the mouth within 3.5 s, and the player is not steering himself
	-- (any move input = the player has the keeper). A flier: stand under where he comes down, close to it.
	local landP = nil
	if airborne and not jet then
		for k = 2, #futs[1].pts do
			local q = futs[1].pts[k]
			if q.Y <= root.Position.Y + 1 then
				landP = q
				break
			end
		end
	end
	-- a jetpack flier: no coming out (he lands where the dash ends, or shoots from above: the save logic blocks the ball)
	-- a committed flier (in the air, inside dive range, over the mouth) cannot turn: standing where he comes down is
	-- exactly right, so a landing point is taken even then (it was "not committed" -> the keeper stood still)
	local moveOk = CFG.GkPressMove ~= false and not jet and ((not committed and dSeg <= (CFG.GkPressMoveZone or 50) and tReach <= 3.5) or landP ~= nil or hookA ~= nil)
	if moveOk and Mark.userInputDir() then
		moveOk = false
	end
	if moveOk then
		local Pl = landP or hookA or futs[1].pts[13] or E0
		-- he comes down behind the line: meet him where his arc crosses the mouth plane instead
		if landP and flat(landP - mouth):Dot(fwd) < 1.5 then
			local pts = futs[1].pts
			for k = 2, #pts do
				local a0, a1 = flat(pts[k - 1] - mouth):Dot(fwd), flat(pts[k] - mouth):Dot(fwd)
				if a0 >= 1.5 and a1 < 1.5 then
					local q = pts[k - 1]:Lerp(pts[k], (a0 - 1.5) / math.max(a0 - a1, 1e-4))
					local lat = math.clamp(flat(q - mouth):Dot(side), -(half + 1), half + 1)
					Pl = nil
					Mark.gkPressStandP = Vector3.new((mouth + fwd * 1.5 + side * lat).X, root.Position.Y, (mouth + fwd * 1.5 + side * lat).Z)
					Mark.gkStandLast = { p = Mark.gkPressStandP, at = c.now, id = c.ownerId }
					break
				end
			end
		end
		local u = Pl and unitOrNil(flat(Pl - mouth))
		if u and u:Dot(fwd) > 0.15 then
			local depth = math.clamp(flat(Pl - mouth).Magnitude - (landP and 5 or (CFG.GkPressGap or 12)), 1.5, CFG.GkPressOut or 18)
			local S = mouth + u * depth
			local lat = flat(S - mouth):Dot(side)
			S = S - side * (lat - math.clamp(lat, -(half + 2), half + 2))
			Mark.gkPressStandP = Vector3.new(S.X, root.Position.Y, S.Z)
			Mark.gkStandLast = { p = Mark.gkPressStandP, at = c.now, id = c.ownerId }
		end
	end

	local diveReady = c.now - (Mark.gkDive or 0) > D.Constants.RepeatDelaySeconds + 0.05
	local iframe = Dodge.IsDribbling(model)
	local viz = { at = c.now, futs = futs, from = root.Position, conf = 0, need = 1, stand = Mark.gkPressStandP, R = (CFG.PressReach or 2.6) * ((airborne or jet or hookPts ~= nil) and 1 or (CFG.GkPressRadiusFrac or 0.75)) }
	Mark.gkViz = viz
	if not diveReady then
		return note("wait dive cooldown")
	end
	if iframe then
		return note("skip iframe")
	end
	-- solve at ~30 Hz: one solve is a few thousand box tests
	local sv = Mark.gkSolveCache
	local best, later, cen
	if sv and sv.model == model and c.now - sv.at < 0.033 then
		best, later, cen = sv.best, sv.later, sv.cen
	else
		local dist = D.GetDistance(LocalPlayer)
		local cam = Workspace.CurrentCamera
		Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
		best, later, cen = Mark.gkPressSolve({
			root = root.Position, vel = flat(root.AssemblyLinearVelocity), futs = futs, D = D, dist = dist,
			maxD = math.min(CFG.PressDist or (dist - 0.5), dist - 0.5), R = (CFG.PressReach or 2.6) * ((airborne or jet or hookPts ~= nil) and 1 or (CFG.GkPressRadiusFrac or 0.75)), H = CFG.PressVert or 4,
			RF = CFG.GkPressReachFrac or 0.85,
			mouth = mouth, fwd = fwd, g = g, jumpH = Mark.jumpH or 7.2, air = airborne or jet or hookPts ~= nil,
			exact = CFG.GkPressExact ~= false, camCF = cam and cam.CFrame or root.CFrame,
			slip = (airborne or jet or hookPts ~= nil) and (ping * 0.5 + (CFG.GkPressSlip or 0.03)) or nil,
			facing = unitOrNil(flat(root.CFrame.LookVector)) or fwd,
			minT = CFG.GkPressMinT or 0.06,
		})
		Mark.gkSolveCache = { model = model, at = c.now, best = best, later = later, cen = cen }
	end
	local imminent = committed or imminentT
	local need = imminent and (CFG.GkPressConfLate or 0.35) or (CFG.GkPressConf or 0.6)
	if rush then
		need = math.min(need, CFG.GkRushConf or 0.35)
	end
	viz.need = need
	if best then
		viz.conf, viz.dir, viz.hits, viz.jump = best.conf, best.dir, best.hits, best.jump
		viz.hitP = cen[math.floor(best.t / 0.025 + 0.5) + 1]
		viz.travel = D.GetTravel(math.max(best.t - best.T0, 0), D.GetDistance(LocalPlayer))
	end
	local function fmt(x)
		return string.format("%.2f", x)
	end
	local info0 = hookPts and string.format("HOOK %.2f ", hookT) or (bare and string.format("FLIER %.2f ", c.flierT or -1) or "")
	local info = info0 .. string.format("dSeg %.1f appr %.1f tReach %s air %s vy %.1f dy %.1f drib %s jet %s vk %s%s%s", dSeg, appr, tReach == math.huge and "-" or fmt(tReach), tostring(airborne), vy, P.Y - root.Position.Y, dribReady and "ready" or "spent", jet and fmt(jet.te) or "-", vKind, downFly and " downFly" or "", Mark.gkPressStandP and string.format(" stand %.1f", flat(Mark.gkPressStandP - root.Position).Magnitude) or "")
	if not best then
		-- too close / no dive line: the keeper's own charged Kick (full charge, released by the kick box) pushes him off
		-- the ball. AutoKick's planner with the keeper flag (no run-up: the keeper keeps his stand).
		if CFG.GkKick ~= false and flat(P - root.Position).Magnitude <= Mark.kickReach() + (CFG.GkKickRange or 8) then
			local sent, why = Mark.akTry("gk", model, er, false)
			if sent then
				return note("kick " .. info)
			end
			info = info .. " kick " .. tostring(why)
		end
		return note("no contact " .. info)
	end
	-- turn to him before the dive: with the body already on the line the dash and its "F" animation start the same way
	-- (and the facing lock does not have to swing the body during the dash). Only for a near contact and exact aim (the
	-- 8 camera choices depend on the facing, turning would change them).
	if CFG.GkPressFace ~= false and (CFG.GkPressExact ~= false) and best.t <= 0.6 and best.conf >= need * 0.5 and not Mark.gkDiveAim then
		TurnControl.LockAutoRotate("Goalkeeper", best.dir)
		Mark.gkPreFace = { at = c.now }
	end
	-- a charging carrier releases within his max charge: the dive must land before that, otherwise the save logic owns
	-- it. The max is HIS (KickPowerups.GetChargeConstants: a kick powerup, the "fire" boost, cuts it 0.4 -> 0.3 s and
	-- multiplies the shot speed); the flat 0.4 let a press dive go at a powered shooter who fired 0.1 s earlier, and
	-- the ball flew through the dive.
	local crec = Mark.charges and Mark.charges[pl.UserId]
	if crec and crec.live and c.now - (crec.seen or 0) < 0.6 and not committed then
		Mark.kickPow = Mark.kickPow or require(Modules.Actions.KickPowerups)
		local maxC = Mark.kickPow.GetChargeConstants(pl, KickCore.Constants).MaximumChargeSeconds
		if best.t + ping * 0.5 > (crec.at or c.now) + maxC - c.now then
			return note(string.format("skip charging max %.2f mult %.2f t %s %s", maxC, Mark.kickPow.GetMultiplier(pl), fmt(best.t), info))
		end
	end
	-- A FLIER WITH THE BALL SHOOTS FROM THE AIR. Jetpack / launched carrier: his kick from above needs no landing (log:
	-- press dive at a jetpacker dy 21.9, contact t 0.23; he released a 124 st/s shot 0.07 s after our dash - stunned
	-- after the ball had gone, keeper on the floor, goal). A dive is only worth it when it lands before he can complete a
	-- fresh kick: contact within the game's minimum release time minus what we see of him late (display delay).
	if (airborne or jet) and not committed and not hookPts and not bare and CFG.GkPressFlierShot ~= false then
		local minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2
		local seen = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25)
		if best.t + ping * 0.5 > minRel - seen then
			return note(string.format("flier can shoot first t %s > %.2f %s", fmt(best.t), minRel - seen - ping * 0.5, info))
		end
	end
	-- never a dive at a man whose height we cannot predict: about to launch, just launched (slope not measured yet), or
	-- flying on something that is not a ballistic arc (lift rigs, grapple). Exception for powered: he is at our height
	-- right now and the contact is immediate. The jetpack has its own timeline (jet ~= false) and skips this.
	if launchPending and not hookPts then
		return note("launch pending " .. launchPending .. " " .. info)
	end
	if not jet and not hookPts and vKind == "fresh" then
		return note("wait arc " .. info)
	end
	if not jet and not hookPts and vKind == "powered" and not (best.t <= 0.15 and math.abs(dyNow) <= (CFG.PressVert or 4) * 0.75) then
		return note(string.format("powered flight ay %s %s", ayT and string.format("%.0f", ayT) or "-", info))
	end
	if best.conf < need then
		return note(string.format("watch conf %.2f need %.2f t %s %s", best.conf, need, fmt(best.t), info))
	end
	-- TIME TO IMPACT vs HIS ESCAPE. A launcher in his hands (bazooka at the feet, shotgun down, grapple, jetpack) takes
	-- him off the ground the moment he fires; he sees our dash after the latency (~our ping) and fires after a reaction
	-- (GkLauncherReact). A contact later than that is a dive into the air he is about to leave (log: bazooka boost
	-- right after our dash, the dive passed under him, 1.9 s open goal). Stand and read the launch instead.
	if not airborne and not jet and not hookPts then
		local held = Mark.heldLauncher(pl.UserId)
		if held then
			local escT = (CFG.GkLauncherReact or 0.2) + ping
			if best.t > escT then
				return note(string.format("launcher %s in hand: hit t %s > escape %.2f %s", held, fmt(best.t), escT, info))
			end
		end
	end
	-- a contact further than GkPressMaxT is a guess about a man who can still turn, dribble or shoot: the miss costs the
	-- dive cooldown (1.9 s open goal). Come out (stand above) until the contact is short. Committed / flying: allowed.
	local maxT = CFG.GkPressMaxT or 0.36
	if best.t > maxT and not committed and not imminent then
		return note(string.format("far contact t %s max %.2f conf %.2f %s", fmt(best.t), maxT, best.conf, info))
	end
	if later and later.conf >= best.conf + 0.15 and not imminent then
		return note(string.format("wait surer conf %.2f later %.2f in %.2f %s", best.conf, later.conf, later.T0, info))
	end
	local exact = CFG.GkPressExact ~= false
	if best.jump then
		if Mark.doJump("gkpress") then
			Mark.gkCombo = { diveAt = c.now + best.jump, untilT = c.now + best.jump + 0.2, dir = exact and best.dir or nil, choice = nil, wd = best.dir, fwd = fwd, role = c.role, name = actorName(pl), pl = pl, model = model, lead = lead, t = best.t }
			Mark.gkPressRec = { at = c.now, pl = pl, model = model, minD = math.huge, name = actorName(pl) }
			viz.fired = true
			logFile("gk press", "jump + dive", actorName(pl), "conf", fmt(best.conf), "dive in", fmt(best.jump), "hit t", fmt(best.t), info)
			return true
		end
		return note("jump refused " .. info)
	end
	local face = exact and best.dir or fwd
	TurnControl.LockAutoRotate("Goalkeeper", face)
	Mark.gkDiveAim = { dir = best.dir, at = c.now, untilT = c.now + D.Constants.DurationSeconds + 0.05, model = model, lead = lead, fwd = fwd, faceF = exact, hold = not exact }
	Mark.diveSet(character, best.dir, face)
	Mark.gkDive = c.now
	local ok = c.role.Dive()
	Mark.diveRestore(character, best.dir)
	if ok and exact then
		-- hold the body on the dash for the whole dive (gkAimTick re-locks it along the homing dir and releases at the
		-- end). Released right after Dive(), GoalkeeperCameraFacing turned the body back to the camera: a sideways dash
		-- with the body (and the "F" animation) pointing at the goal-out direction.
		Mark.gkDiveAim.faceLock = true
	else
		TurnControl.ReleaseAutoRotate("Goalkeeper")
	end
	if not ok then
		Mark.gkDiveAim = nil
	end
	viz.fired = ok and true or nil
	Mark.gkPressRec = { at = c.now, pl = pl, model = model, minD = math.huge, name = actorName(pl) }
	logFile("gk press", "dive", ok and "ok" or "no", actorName(pl), "conf", fmt(best.conf), "need", fmt(need), "hit t", fmt(best.t), "exact", tostring(exact), "dir", fmtV(best.dir), info)
	return ok and true or false
end

-- GRAPPLE PATH (dump GrappleMotion.Step): until PullStartsAt he stands (the hook flies); then every step he moves
-- toward GetTargetPosition(ball) (the ball + standing offset - radius) at PullSpeed * QuadOut(t / SpeedRampSeconds),
-- re-aimed at the ball each step; within the step he arrives (pickup), then RunOvershoot: OvershootDistanceStuds along
-- his velocity in OvershootDurationSeconds (Quad-out). The ball comes from Mark.ballPath. Returns pts (0.025 s, 1.3 s),
-- tArr (nil = not in 1.3 s).
Mark.grapplePath = function(uid, model, P, root)
	local gr = Mark.grapples and Mark.grapples[uid]
	if not gr then
		return nil
	end
	local nowS = Workspace:GetServerTimeNow()
	if nowS - gr.pullAt > 2.5 then
		Mark.grapples[uid] = nil
		return nil
	end
	local _, _, bs, bt = Mark.ballPath(root)
	if not bs then
		return nil
	end
	Mark.grappleM = Mark.grappleM or require(Modules.Items.GrappleMotion)
	local K = Mark.grappleM.Constants
	local nb, hint = #bs, 2
	local function ballAt(t)
		if nb < 2 or t >= bt[nb] then
			return bs[nb]
		end
		while hint < nb and bt[hint] < t do
			hint += 1
		end
		local a, b = bt[hint - 1], bt[hint]
		return bs[hint - 1]:Lerp(bs[hint], b > a and (t - a) / (b - a) or 0)
	end
	local DT, N = 0.025, 52
	local pts = table.create(N + 1)
	local p = P
	pts[1] = p
	local tArr, pArr, dir = nil, nil, nil
	for k = 1, N do
		local t = k * DT
		local tS = nowS + t
		if not tArr then
			if tS >= gr.pullAt then
				local b = ballAt(t)
				local tgt = Mark.grappleM.GetTargetPosition(model, b) or b
				local u = math.clamp((tS - gr.pullAt) / K.SpeedRampSeconds, 0, 1)
				local step = K.PullSpeed * (1 - (1 - u) * (1 - u)) * DT
				local d = tgt - p
				local m = d.Magnitude
				if m > 1e-3 then
					dir = d / m
				end
				if m <= math.max(step, K.ArrivalConfirmationToleranceStuds) then
					p, tArr, pArr = tgt, t, tgt
				else
					p += d / m * step
				end
			end
		elseif dir then
			local u = math.clamp((t - tArr) / K.OvershootDurationSeconds, 0, 1)
			p = pArr + dir * K.OvershootDistanceStuds * (1 - (1 - u) * (1 - u))
		end
		pts[k + 1] = p
	end
	return pts, tArr
end

-- The launcher an enemy HOLDS right now (dump HeldItems: rig models in workspace.Misc.Items, attribute UserId = owner,
-- ItemId, HeldItemLifecycle = 0 while equipped and not fired). Known BEFORE the shot - the packet (launchRec) only
-- comes after it. Memo 0.1 s per user.
Mark.launcherIds = { bazooka = true, shotgun = true, grapplingHook = true, jetpack = true, rocketPunch = true }
Mark.heldLauncher = function(uid)
	local now = os.clock()
	Mark.heldMemo = Mark.heldMemo or {}
	local m = Mark.heldMemo[uid]
	if m and now - m.at < 0.1 then
		return m.id
	end
	local id = nil
	local misc = workspace:FindFirstChild("Misc")
	local cont = misc and misc:FindFirstChild("Items")
	if cont then
		local uAttr = Actors.UserIdAttributeName or "UserId"
		for _, ch in cont:GetChildren() do
			local it = ch:GetAttribute("ItemId")
			if it and Mark.launcherIds[it] and ch:GetAttribute(uAttr) == uid and ch:GetAttribute("HeldItemLifecycle") == 0 then
				id = it
				break
			end
		end
	end
	Mark.heldMemo[uid] = { at = now, id = id }
	return id
end

-- the firearm (shotgun / flintlock) an enemy holds right now: the held model in Misc.Items (HeldItemLifecycle 0 = in hand)
Mark.gunIds = { shotgun = true, flintlock = true }
Mark.heldGun = function(uid)
	local now = os.clock()
	Mark.gunMemo = Mark.gunMemo or {}
	local m = Mark.gunMemo[uid]
	if m and now - m.at < 0.1 then
		return m.id
	end
	local id = nil
	local misc = workspace:FindFirstChild("Misc")
	local cont = misc and misc:FindFirstChild("Items")
	if cont then
		local uAttr = Actors.UserIdAttributeName or "UserId"
		for _, ch in cont:GetChildren() do
			local it = ch:GetAttribute("ItemId")
			if it and Mark.gunIds[it] and ch:GetAttribute(uAttr) == uid and ch:GetAttribute("HeldItemLifecycle") == 0 then
				id = it
				break
			end
		end
	end
	Mark.gunMemo[uid] = { at = now, id = id }
	return id
end

-- Does a gun at `from` facing `look` (flat) point at a body at `at`? -> aimed, distance, lateral miss (studs). The game replicates
-- the aim of a man holding a gun (UsesCameraFacing: the body turns to the camera yaw), so his look vector IS the line of fire.
-- Cone: the shotgun spreads 12 pellets, the flintlock is one accurate pellet: both judged on the lateral miss at our distance.
Mark.gunAimed = function(from, look, at, bodyR)
	local to = flat(at - from)
	local d = to.Magnitude
	local lf = unitOrNil(flat(look))
	if d < 1 or not lf then
		return false, d, math.huge
	end
	local along = to:Dot(lf)
	if along <= 0 then
		return false, d, math.huge
	end
	local miss = (to - lf * along).Magnitude
	return miss <= bodyR, d, miss
end

-- ANTI-GUN (AutoWall): an enemy within GunWallRange (80) holds a shotgun / flintlock and has been aimed at us for GunAimHold
-- seconds: the forcefield (when owned, AutoShield) or a barricade on the line of fire, 5 studs in front of us, BEFORE the shot -
-- a hitscan gets no reaction time after it. One try per aim episode; a new one needs the aim lost for 0.6 s.
Mark.gunSeen = {}
-- Out of the line of fire (no shield, no wall): with the ball a pass / dump, without it a 5 st step across the line - the side
-- away from his muzzle line is the one the line of sight leaves (his aim is on our body: either side leaves the 3.5 st cone).
Mark.gunSidestep = function(root, from, d)
	local line = unitOrNil(flat(root.Position - from))
	if not line then
		return "no line"
	end
	local side = Vector3.new(-line.Z, 0, line.X)
	if liveOwnerId() == LocalPlayer.UserId then
		local ev = { born = os.clock(), p = flat(from), r = 20, item = "gun" }
		return Mark.hazPass(root, ev, 0.4, 0, line, "gun") and "pass" or "own ball, no pass"
	end
	if side:Dot(unitOrNil(flat(root.AssemblyLinearVelocity)) or side) < 0 then
		side = -side -- the side we already run to
	end
	Mark.hazardStep(root, side * 5, "gun")
	return "step"
end
Mark.gunTick = function(root)
	-- 30 Hz: it watches for a gun aimed at us over 0.15-0.4 s holds; a frame-rate call (110 Hz) cost 4 ms of every second
	local nowT = os.clock()
	if nowT - (Mark.gunTickAt or 0) < 0.033 then
		return
	end
	Mark.gunTickAt = nowT
	-- the wall / shield answer belongs to AutoWall; AutoDodge steps out of the line of fire when that answer is not there
	local wallOn = CFG.AutoWall and CFG.GunWall ~= false
	if not (wallOn or CFG.AutoDodge) or Mark.meKeeper() then
		return
	end
	local now = os.clock()
	local range = CFG.GunWallRange or 80
	local hold = CFG.GunAimHold or 0.12
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and type(actor.UserId) == "number" and not Mark.mateDown(actor, model) then
			local r = ActorTargeting.GetActorRoot(actor)
			local uid = actor.UserId
			if r and flat(r.Position - root.Position).Magnitude <= range then
				local gun = Mark.heldGun(uid)
				local cf = gun and CharacterMotion.GetCFrame(model)
				local aimed, d, miss = false, 0, 0
				if cf then
					aimed, d, miss = Mark.gunAimed(r.Position, cf.LookVector, root.Position, CFG.GunBodyR or 3.5)
				end
				local s = Mark.gunSeen[uid]
				if aimed then
					if not s then
						s = { since = now, last = now }
						Mark.gunSeen[uid] = s
					end
					s.last = now
					if not s.tried and now - s.since >= hold then
						s.tried = true
						local how = "-"
						if wallOn and CFG.AutoShield and Mark.shieldNow(string.format("%s aimed by %s d %.0f miss %.1f", gun, actorName(actor), d, miss)) then
							how = "shield"
						elseif wallOn then
							-- the line of fire as a path the wall solver can cross: hitscan = fast (400 st/s) from his muzzle at us
							local from = r.Position
							local u = unitOrNil(flat(root.Position - from))
							local ok, why = Mark.wallVsPath(root, function(t)
								return from + u * (400 * t)
							end, d / 400 + 0.1, "gun", { rad = 1.5, lagReady = true, actor = actor, model = model, equip = liveOwnerId() ~= LocalPlayer.UserId })
							how = ok and "wall" or ("no wall: " .. tostring(why))
							if ok == "equip" then
								s.tried = false -- barricades coming out: place on the next tick
								continue
							end
						end
						if how ~= "shield" and how ~= "wall" and CFG.AutoDodge then
							how = how .. " -> " .. Mark.gunSidestep(root, r.Position, d)
						end
						logFile("gun aimed", gun, actorName(actor), "d", string.format("%.0f", d), "miss", string.format("%.1f", miss), "held", string.format("%.2f", now - s.since), "->", how)
					end
				elseif s and now - s.last > 0.6 then
					Mark.gunSeen[uid] = nil
				end
			elseif Mark.gunSeen[uid] then
				Mark.gunSeen[uid] = nil
			end
		end
	end
end

-- An open attacker (not on the ground, not marked by our field player within BlockCoverRadius) who is nearer the mouth
-- segment than the carrier or level with him (+ BlockLevelSlack), 8+ studs away from him, within 130 studs of the mouth.
Mark.gkSupport = function(pl, P, mouth, side, half, dSeg)
	local slack = CFG.BlockLevelSlack or 8
	for _, m in Mark.models() do
		local a = Actors.GetFromCharacter(m)
		if a and a ~= pl and a ~= LocalPlayer and not sameTeam(a) and not isGoalkeeper(a) and not Mark.mateDown(a, m) then
			local ar = ActorTargeting.GetActorRoot(a)
			if ar then
				local pos = ar.Position
				local nearP = mouth + side * math.clamp(flat(pos - mouth):Dot(side), -half, half)
				local dO = flat(pos - nearP).Magnitude
				if dO <= math.min(dSeg + slack, 130) and flat(pos - P).Magnitude >= 8 and not Mark.mateNear(pos, CFG.BlockCoverRadius or 8) then
					return a, dO
				end
			end
		end
	end
	return nil
end

-- Press overlay. One renderer: his futures as threads (the ones the dive catches in the state colour over an ink bed,
-- the escapes as faint paper), the dive as a ruler from us to the contact, a ripple where it lands (state palette:
-- safe = watching, armed = sure enough, live = fired), a post up to the contact height for a jump + dive, a small
-- squircle ripple on the spot we come out to.
-- Our own defensive overlays (AutoGK press, AutoBlock marking) are NOT threats: no red / amber (those colours mean an enemy
-- charge). Same hue family, the state is brightness: steel (watching) -> mint (sure enough) -> white-hot (fired / too late).
Mark.defPalette = {
	safe = { Color3.fromRGB(96, 140, 184), Color3.fromRGB(122, 156, 204), Color3.fromRGB(88, 176, 196) },
	armed = { Color3.fromRGB(92, 255, 196), Color3.fromRGB(146, 255, 224), Color3.fromRGB(64, 218, 176) },
	live = { Color3.fromRGB(240, 255, 250), Color3.fromRGB(150, 255, 226), Color3.fromRGB(92, 255, 196) },
}
Mark.gkArt = function(seg, v, gy, t)
	local key = v.fired and "live" or ((v.conf or 0) >= (v.need or 1) and "armed" or "safe")
	local pal = Mark.defPalette[key]
	local col = pal[1]
	for fi, f in v.futs do
		local caught = v.hits and v.hits[fi]
		local pts = f.pts
		local last = math.min(#pts, caught and (math.floor(caught / 0.025) + 2) or 37)
		local prev = nil
		for k = 1, last, 3 do
			local q = pts[k]
			local p = Vector3.new(q.X, f.air and math.max(q.Y - 2.9, gy) or gy + 0.05, q.Z)
			if prev then
				if caught then
					seg(prev, p, COL.Ink, 0.4, 3.6, 39)
					seg(prev, p, col, fi == 1 and 1 or 0.75, fi == 1 and 2 or 1.4, 41)
				else
					seg(prev, p, COL.Paper, 0.22, 1, 39)
				end
			end
			prev = p
		end
	end
	if v.dir and v.hitP and v.travel then
		local a = Vector3.new(v.from.X, gy + 0.05, v.from.Z)
		local b = a + v.dir * v.travel
		seg(a, b, COL.Ink, 0.45, 4.4, 39)
		seg(a, b, col, 1, 1.8, 42)
		local nrm = Vector3.new(-v.dir.Z, 0, v.dir.X) * 0.45
		for s = 4, v.travel - 1, 4 do
			local m = a + v.dir * s
			seg(m - nrm, m + nrm, COL.Paper, 0.7, 1.2, 42)
		end
		local land = Vector3.new(v.hitP.X, gy, v.hitP.Z)
		Mark.kickRipple(seg, land, v.R or 2.6, pal, Mark.rippleStep("gk-press", Mark.rippleRates[key]), t, 2)
		local top = v.hitP.Y - 2.9
		if v.jump and top > gy + 1 then
			seg(land, Vector3.new(land.X, top, land.Z), COL.Ink, 0.45, 3.4, 39)
			seg(land, Vector3.new(land.X, top, land.Z), COL.Paper, 0.9, 1.3, 42)
			seg(Vector3.new(land.X, top, land.Z) - nrm * 1.6, Vector3.new(land.X, top, land.Z) + nrm * 1.6, col, 1, 2, 42)
		end
	end
	if v.stand and not v.fired then
		Mark.kickRipple(seg, Vector3.new(v.stand.X, gy, v.stand.Z), 1.1, Mark.defPalette.safe, Mark.rippleStep("gk-stand", Mark.rippleRates.safe), t, 4)
	end
end
Mark.drawGk = function(gy)
	Mark.gkLines = Mark.gkLines or makeLines(420, 1.4, 40)
	Mark.gkPool = Mark.gkPool or Mark.segPool(Mark.gkLines)
	local v = Mark.gkViz
	local now = os.clock()
	if CFG.DrawGk ~= false and v and now - v.at < (v.fired and 0.9 or 0.25) and MatchSettings.IsGoalkeeperCharacter(LocalPlayer.Character) then
		Mark.gkArt(Mark.gkPool.seg, v, gy, now)
	end
	Mark.gkPool.finish()
end

-- closest approach + his state ~1 s after a press (calibration of PressReach / the stun rule)
-- Outcome of every keeper dive (the log had only "gk dive ok" and nothing after it, so a miss could not be told from a save):
-- closest approach of the ball to our body during the dive window, who has it 1.1 s after, and whether it crossed our mouth.
Mark.gkDiveWatch = function(root)
	local r = Mark.gkDiveRec
	if not r then
		return
	end
	local now = os.clock()
	local ball = Renderer.GetPosition()
	if typeof(ball) == "Vector3" then
		local d = (ball - root.Position).Magnitude
		if d < r.minD then
			r.minD, r.minAt = d, now - r.at
		end
		if not r.goal then
			local g = Mark.defendGoal()
			local lb, rb = nil, nil
			if g then
				lb, _, rb = goalMouthCorners(g)
			end
			if lb and rb then
				local mouth = (lb + rb) * 0.5
				local sideV = unitOrNil(flat(rb - lb))
				if sideV then
					local out = Vector3.new(-sideV.Z, 0, sideV.X)
					if flat(root.Position - mouth):Dot(out) < 0 then
						out = -out
					end
					-- out points into the field: the ball behind the mouth plane and inside the posts = in
					local rel = flat(ball - mouth)
					if rel:Dot(out) < -0.5 and math.abs(rel:Dot(sideV)) < flat(rb - lb).Magnitude * 0.5 then
						r.goal = now - r.at
					end
				end
			end
		end
	end
	if now - r.at >= 1.1 then
		Mark.gkDiveRec = nil
		local o = liveOwnerId()
		Mark.teleAdd("gk.dive", not r.goal)
		logFile("gk dive result", r.name, "closest", string.format("%.1f", r.minD), "at", string.format("%.2f", r.minAt or -1), "goal", r.goal and string.format("%.2f", r.goal) or "no", "owner", o == LocalPlayer.UserId and "us" or (type(o) == "number" and o ~= 0 and "enemy/other" or "free"), "eta", string.format("%.2f", r.eta))
	end
end

Mark.gkPressWatch = function(root)
	local rec = Mark.gkPressRec
	if not rec then
		return
	end
	local now = os.clock()
	local er = rec.model and rec.model:FindFirstChild("HumanoidRootPart")
	if er then
		-- flat AND height: a flat 0.1 with him 6 studs over our head is not a contact (log: "closest 0.1", no stun)
		local d = flat(er.Position - root.Position).Magnitude
		local dy = er.Position.Y - root.Position.Y
		local d3 = math.sqrt(d * d + dy * dy)
		if d3 < (rec.min3 or math.huge) then
			rec.min3, rec.minD, rec.minY = d3, d, dy
		end
	end
	if now - rec.at >= 1.0 then
		Mark.gkPressRec = nil
		local down, left = Mark.mateDown(rec.pl, rec.model)
		Mark.teleAdd("gk.press", down)
		logFile("gk press result", rec.name, "stunned", tostring(down), "left", string.format("%.2f", left or 0), "closest", string.format("%.1f", rec.minD), "dy", string.format("%.1f", rec.minY or 0))
	end
end

-- The keeper pushed off his spot (shotgun / any ViolenceDash: the server sends a Vector3, the client runs
-- KnockbackMotion.Run(_, root, velocity): flat speed x 1.5, duration ln(1 + speed/26), travel GetMaximumHorizontalTravel).
-- The wrapper records every push of OUR character; Mark.gkReturnTick brings the keeper back to the spot he stood on.
Mark.knockHook = function()
	local KB = require(Modules.Characters.KnockbackMotion)
	if not KB.Run or Mark.knockOrig then
		return
	end
	Mark.knockOrig = KB.Run
	KB.Run = function(a, rootPart, vel, ...)
		if CFG.NoKnockback and typeof(rootPart) == "Instance" and rootPart.Parent == LocalPlayer.Character then
			logFile("push blocked", "vel", typeof(vel) == "Vector3" and fmtV(vel) or "-")
			return
		end
		Mark.try(function()
			if typeof(rootPart) == "Instance" and rootPart.Parent == LocalPlayer.Character and typeof(vel) == "Vector3" then
				local dur = KB.GetDuration(vel)
				local travel = KB.GetMaximumHorizontalTravel(vel)
				local dir = unitOrNil(flat(vel))
				Mark.knock = { at = os.clock(), vel = vel, dur = dur, travel = travel, from = rootPart.Position, dir = dir }
				Mark.gkReturnDived = nil
				logFile("push", "vel", fmtV(vel), "dur", string.format("%.2f", dur), "travel", string.format("%.1f", travel), "end", dir and fmtV(rootPart.Position + dir * travel) or "-", "gk", tostring(MatchSettings.IsGoalkeeperCharacter(LocalPlayer.Character)))
			end
		end)
		return Mark.knockOrig(a, rootPart, vel, ...)
	end
end
Mark.knockHook()

-- the enemy field player nearest to a loose ball within r (not a keeper, not down): who a free ball is "his" for
Mark.gkContender = function(ballPos, r)
	local best, bd = nil, r
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
			local rr = ActorTargeting.GetActorRoot(actor)
			if rr then
				local d = flat(rr.Position - ballPos).Magnitude
				if d < bd then
					best, bd = rr, d
				end
			end
		end
	end
	return best, bd
end

-- the spot the keeper stands on: remembered while he stands still near his goal
-- MIRROR (user): a carrier running at the goal drags the keeper across with him, the closer the more. weight 0.15 at `range`
-- (a pass can still go the other way) -> 0.9 from 10 studs in; depth in front of the line 35 % of his depth, 2..6, never within
-- 3 studs of him (goal-side: a kick / dive at him then sends the ball away from the mouth, not into it). Pure.
Mark.gkMirror = function(along, side, half, range, seg)
	-- `seg` = his distance to the mouth SEGMENT (a carrier on the far wing is far from the goal whatever his depth is): nothing
	-- beyond `range`. The user: "mirror him when he is NEAR", the keeper stood on the line at every attack 60 studs away.
	local d = seg or along
	if d > range then
		return nil
	end
	local k = math.clamp((d - 10) / math.max(range - 10, 1), 0, 1)
	local w = 0.9 - 0.75 * k
	local lat = math.clamp(side * w, -(half - 1), half - 1)
	local depth = math.min(math.clamp(along * 0.35, 2, 6), math.max(along - 3, 1.5))
	return depth, lat
end

Mark.gkHomeTrack = function(root, c)
	local recent = Mark.knock and c.now - Mark.knock.at < 6
	if not recent and c.landed and flat(root.AssemblyLinearVelocity).Magnitude < 3 and flat(root.Position - c.mouthP).Magnitude <= 24 and c.now - (Mark.gkHomeAt or 0) > 0.4 then
		Mark.gkHomeAt = c.now
		Mark.gkHome = root.Position
	end
end

Mark.gkReturnTick = function(character, root, c)
	Mark.gkHomeTrack(root, c)
	local k = Mark.knock
	if not k or c.now - k.at > 8 or CFG.GkReturn == false then
		return nil
	end
	if c.now < k.at + k.dur + 0.15 or not c.landed then
		return nil
	end
	local home = Mark.gkHome
	if not home then
		return nil
	end
	local to = flat(home - root.Position)
	local disp = to.Magnitude
	if disp < 2.5 then
		if Mark.knock then
			Mark.knock = nil
			logFile("gk return", "done", string.format("%.1f", disp))
		end
		return nil
	end
	local D = c.diveMod
	if disp >= (CFG.GkReturnDive or 13) and not Mark.gkReturnDived and c.now - (Mark.gkDive or 0) > D.Constants.RepeatDelaySeconds + 0.05 and c.role and c.role.Dive then
		Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
		local cam = Workspace.CurrentCamera
		local facing = unitOrNil(flat(root.CFrame.LookVector)) or c.fwd
		local u = to.Unit
		local bestW, bestDot, bestName = nil, 0.8, nil
		if cam then
			for name, choice in Mark.actionMotion.DirectionChoices do
				local wd = D.GetWorldDirection(choice, cam.CFrame, facing)
				if typeof(wd) == "Vector3" and wd:Dot(u) > bestDot then
					bestW, bestDot, bestName = wd, wd:Dot(u), name
				end
			end
		end
		if bestW then
			Mark.gkReturnDived = true
			TurnControl.LockAutoRotate("Goalkeeper", c.fwd)
			Mark.diveSet(character, bestW, c.fwd)
			Mark.gkDive = c.now
			local ok = c.role.Dive()
			Mark.diveRestore(character, bestW)
			TurnControl.ReleaseAutoRotate("Goalkeeper")
			logFile("gk return", "dive", ok and "ok" or "no", "choice", bestName, "disp", string.format("%.1f", disp))
			return nil
		end
	end
	if not Mark.gkReturnLog or c.now - Mark.gkReturnLog > 0.6 then
		Mark.gkReturnLog = c.now
		logFile("gk return", "walk", "disp", string.format("%.1f", disp))
	end
	return home
end

Mark.gkComboTick = function(character, root)
	local cb = Mark.gkCombo
	if not cb then
		return
	end
	local now = os.clock()
	if now > cb.untilT then
		Mark.gkCombo = nil
		return
	end
	if now < cb.diveAt then
		return
	end
	Mark.gkCombo = nil
	local cam = Workspace.CurrentCamera
	local D = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	Mark.gkDiveMod = D
	if not cam or now - (Mark.gkDive or 0) <= D.Constants.RepeatDelaySeconds + 0.05 then
		return
	end
	local facing = unitOrNil(flat(root.CFrame.LookVector)) or cb.fwd
	local wd = cb.wd or D.GetWorldDirection(cb.choice, cam.CFrame, facing)
	if not (typeof(wd) == "Vector3") then
		return
	end
	TurnControl.LockAutoRotate("Goalkeeper", cb.dir or cb.fwd)
	if cb.dir then
		Mark.gkDiveAim = { dir = cb.dir, at = now, untilT = now + D.Constants.DurationSeconds + 0.05, model = cb.model, lead = cb.lead or 0.1, fwd = cb.fwd, faceF = true }
	end
	Mark.diveSet(character, wd, cb.dir or cb.fwd)
	Mark.gkDive = now
	local ok = cb.role.Dive()
	if not ok then
		Mark.gkDiveAim = nil
	end
	Mark.diveRestore(character, wd)
	if ok and cb.dir and Mark.gkDiveAim then
		Mark.gkDiveAim.faceLock = true
	else
		TurnControl.ReleaseAutoRotate("Goalkeeper")
	end
	logFile("gk press", "air dive", ok and "ok" or "no", cb.name, "airborne", tostring(not CharacterControllers.IsLanded(character, character:FindFirstChildOfClass("Humanoid"))))
end

Mark.tickGk = function(character, root)
	if not CFG.AutoGK or not MatchSettings.IsGoalkeeperCharacter(character) then
		Mark.ballSrcId = nil
		if Mark.gkPreFace or (Mark.gkDiveAim and Mark.gkDiveAim.faceLock) then
			-- AutoGK off / no longer the keeper with our facing lock on: do not leave the body locked
			Mark.gkPreFace, Mark.gkDiveAim = nil, nil
			TurnControl.ReleaseAutoRotate("Goalkeeper")
		end
		return false
	end
	local posMod = Mark.gkPos or require(Modules.Gameplay.GoalkeeperPositioning)
	local pred = Mark.gkPred or require(Modules.Gameplay.GoalkeeperPrediction)
	local acts = Mark.gkActs or require(Modules.Actions.GoalkeeperActions)
	local role = Mark.gkRole
	if not role then
		Mark.gkRoleMod = Mark.gkRoleMod or require(Client.Gameplay.Player.GoalkeeperRole)
		local role = Mark.gkRoleMod
		Mark.gkRole = role
	end
	Mark.gkPos, Mark.gkPred, Mark.gkActs = posMod, pred, acts
	Mark.gkComboTick(character, root)
	Mark.gkAimTick(root)
	local ours = ourGoalPart()
	local theirs = enemyGoalPart()
	-- Practice wing: the defended goal is PracticeSession.GetDefendedGoalPart (Lobby.Practice.Goals.Defence.Goal) and
	-- the ball is a practice ball (Renderer.GetNearestPracticeBallId -> GetMovementStateById), not the main match.
	local practice = false
	Mark.ballSrcId = nil
	do
		-- practice mode is a session state: checked 4 times a second, not 120 (the old per-frame closure + require
		-- + IsActive + GetDefendedGoalPart + ball id lookup was a fixed cost of every keeper frame)
		local pc = Mark.practiceCache
		local nowP = os.clock()
		if not pc or nowP - pc.at > 0.25 then
			Mark.practiceMod = Mark.practiceMod or require(Client.Gameplay.PracticeSession)
			local ps = Mark.practiceMod
			pc = { at = nowP, goal = nil }
			if ps.IsActive() then
				pc.goal = ps.GetDefendedGoalPart()
			end
			Mark.practiceCache = pc
		end
		if pc.goal and pc.goal.Parent then
			ours = pc.goal
			practice = true
			local id = Renderer.GetNearestPracticeBallId(root.Position)
			if id then
				Mark.ballSrcId = id
			end
		end
	end
	if not ours then
		if not Mark.gkNoGoal or os.clock() - Mark.gkNoGoal > 2 then
			Mark.gkNoGoal = os.clock()
			logFile("gk", "no goal")
		end
		return true
	end
	local defend = ours.Position
	local attack = theirs and theirs.Position or (defend + flat(root.CFrame.LookVector) * 40)
	if practice then
		local _, _, _, _, _, faceN = goalMouthCorners(ours)
		attack = defend + flat(faceN or root.CFrame.LookVector) * 40
	end
	local _, fwd, side = posMod.GetFieldDirections(defend, attack)
	fwd = fwd or Vector3.new(0, 0, 1)
	Mark.gkFwd = fwd
	side = side or Vector3.new(-fwd.Z, 0, fwd.X)
	local half = posMod.Constants.GoalHalfWidth
	local diveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	Mark.gkDiveMod = diveMod
	local state, gkWorld
	if Mark.ballSrcId then
		state, gkWorld = Renderer.GetMovementStateById(Mark.ballSrcId)
	else
		state, gkWorld = Renderer.GetMovementState()
	end
	if not gkWorld then
		state = nil -- no boundary world: nothing to integrate the flight in
	end
	local ballPos = (state and state.Position) or Renderer.GetPosition() or Renderer.GetMainMatchPosition()
	local ballVel = (state and state.Velocity) or Renderer.GetTargetVelocity(nil, root.Position) or Vector3.zero
	local crossP, crossT, crossWhy = nil, nil, state and "plane" or "no-state"
	if state then
		-- GetGoalCrossing integrates the whole flight. Same state and the cross is not imminent: reuse, shifting the
		-- ETA by the time since the solve. A new shot (no cross yet, or under 0.45 s) is always recomputed.
		local gc = Mark.gkCross
		local nowG = os.clock()
		if gc and gc.state == state and gc.crossT and gc.crossT > 0.45 and nowG - gc.at < 0.08 then
			crossP, crossT, crossWhy = gc.crossP, gc.crossT - (nowG - gc.at), gc.crossWhy
		else
			local t0 = Workspace:GetServerTimeNow()
			local p, t = pred.GetGoalCrossing(state, gkWorld, ours, t0, pred.Constants.GoalCrossingMaximumPredictionSeconds, false)
			if typeof(p) == "Vector3" and type(t) == "number" then
				crossP, crossT, crossWhy = p, (t > 1e6) and (t - t0) or t, "cross"
			end
			if not crossP then
				local planeT = pred.GetPlaneTime(state, defend, fwd, 0)
				if planeT and planeT > 0 and planeT <= 5 then
					crossT = planeT
					crossP = pred.GetBallPositionAtTime(state, planeT)
					crossWhy = "plane"
				end
			end
			Mark.gkCross = { state = state, at = nowG, crossP = crossP, crossT = crossT, crossWhy = crossWhy }
		end
	end
	-- Y window from the real mouth (goalMouthCorners), not the goal part centre: the part is the net VOLUME, its
	-- centre Y is not the ground, so shots at a normal height were dropped as "bad-y" (log: into 116, along 81,
	-- cross bad-y -> no shot -> no dive). Same for the lateral half width (practice goals differ from GoalHalfWidth).
	do
		local lb, lt, rb = goalMouthCorners(ours)
		if lb and lt and rb then
			local bottomY = math.min(lb.Y, rb.Y)
			local topY = math.max(lt.Y, bottomY + 4)
			half = flat(rb - lb).Magnitude * 0.5
			Mark.gkMouth = { bottomY = bottomY, topY = topY, c = (lb + rb) * 0.5 }
			if crossP and (crossP.Y < bottomY - 1.5 or crossP.Y > topY + (Physics.BallRadius or 1) + 1) then
				crossP, crossT = nil, nil
				crossWhy = "bad-y"
			end
			-- lateral / "lost" stand measured from the mouth line, not the net volume centre behind it
			defend = Vector3.new(((lb + rb) * 0.5).X, defend.Y, ((lb + rb) * 0.5).Z)
		elseif crossP and (crossP.Y < defend.Y - 1.5 or crossP.Y > defend.Y + 12) then
			crossP, crossT = nil, nil
			crossWhy = "bad-y"
		end
	end
	if not crossP and ballPos and typeof(ballVel) == "Vector3" then
		local intoNow = -flat(ballVel):Dot(fwd)
		local relNow = flat(ballPos - defend)
		local alongNow = relNow:Dot(fwd)
		if intoNow > 6 and alongNow > 3 and alongNow < 85 then
			local linT = alongNow / intoNow
			local predSide = relNow:Dot(side) + flat(ballVel):Dot(side) * linT
			local linY = ballPos.Y + ballVel.Y * linT
			if linT > 0.08 and linT < 4.2 and math.abs(predSide) <= half + 2 and linY > defend.Y - 1 and linY < defend.Y + 11 then
				crossT = linT
				crossP = defend + fwd * 0.4 + side * predSide + Vector3.new(0, linY - defend.Y, 0)
				crossWhy = "lin"
			end
		end
	end
	if crossP and ballPos then
		local mc = Mark.gkMouth
		local _, _, smp, tss = Mark.ballPath(root)
		if smp then
			local verdict, vp, vt, rebound = Mark.gkVerify(smp, tss, mc and mc.c or defend, fwd, side, half, mc and mc.bottomY or (defend.Y - 1.5), mc and mc.topY or (defend.Y + 8))
			if verdict == "bounce" or (crossWhy ~= "cross" and verdict ~= "goal") then
				if not Mark.gkNoCrossLog or os.clock() - Mark.gkNoCrossLog > 0.5 then
					Mark.gkNoCrossLog = os.clock()
					logFile("gk nocross", crossWhy, "path", verdict, "at", vt and string.format("%.2f", vt) or "-", "was", crossT and string.format("%.2f", crossT) or "-")
				end
				crossP, crossT, crossWhy = nil, nil, "no-" .. verdict
			elseif verdict == "goal" and (crossWhy ~= "cross" or rebound) then
				-- the path knows the rebound: its crossing replaces a plain cross / plane / lin one
				crossP, crossT, crossWhy = vp, vt, rebound and "rebound" or (crossWhy .. "+path")
				if rebound and (not Mark.gkReboundLog or os.clock() - Mark.gkReboundLog > 0.5) then
					Mark.gkReboundLog = os.clock()
					logFile("gk rebound", "goes in after a hit at", string.format("%.2f", vt))
				end
			end
		end
	end
	local along, ballSide, into = 0, 0, 0
	local segB = math.huge -- the ball's distance to the mouth SEGMENT (along is only its depth)
	if ballPos then
		local relB = flat(ballPos - defend)
		along = relB:Dot(fwd)
		ballSide = relB:Dot(side)
		into = -flat(ballVel):Dot(fwd)
		segB = (relB - side * math.clamp(ballSide, -half, half)).Magnitude
	end
	local now = os.clock()
	local hum = character:FindFirstChildOfClass("Humanoid")
	local landed = not hum or CharacterControllers.IsLanded(character, hum)
	local spd = hum and hum.WalkSpeed or 16
	if spd < 8 then
		spd = 16
	end
	local assist = Mark.gkAssist
	if assist == nil then
		Mark.diveAssistMod = Mark.diveAssistMod or require(Modules.Actions.GoalkeeperDiveAssist)
		assist = Mark.diveAssistMod
		Mark.gkAssist = assist
	end
	local react = math.clamp(LocalPlayer:GetNetworkPing(), 0, 0.3) + 0.05
	local diveD = diveMod.GetDistance(LocalPlayer)
	local saveReach = diveMod.Constants.SaveReachStuds
	local maxSave = diveMod.Constants.MaximumSaveHeight
	local ballR = Physics.BallRadius or 1
	-- Receive (grounded) and GoalkeeperAirReceive (airborne keeper) from HitboxSettings / Receiving.GetReceiveHitbox.
	local rcv = HitboxSettings.Receive
	local air = HitboxSettings.GoalkeeperAirReceive
	local bodyR = rcv.Size.X * 0.5 + ballR
	local groundTop = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + ballR
	local airTop = air.CFrameOffset.Y + air.Size.Y * 0.5 + ballR
	local jumpH = Mark.jumpH or 7.2
	local areaDepth = posMod.Constants.GoalkeeperAreaDepth
	-- The goal part is the net volume: its centre is behind the line. Measure from the mouth face (goalMouthCorners).
	local mlb, _, mrb = goalMouthCorners(ours)
	local mouthP = (mlb and mrb) and (mlb + mrb) * 0.5 or defend

	-- Ownership decides the mode. An owned ball is a dribble, never a shot: no velocity extrapolation, no jump, no dive.
	local ownerId = liveOwnerId()
	local free = not (type(ownerId) == "number" and ownerId ~= 0)
	local ownerRoot = nil
	if not free and ownerId ~= LocalPlayer.UserId then
		local pl, r = enemyCarrier(ownerId)
		if pl and r and not sameTeam(pl) then
			ownerRoot = r
		end
	end
	-- who let the ball go and when (gkBait gives only him the no-touch window)
	local now0 = os.clock()
	if not free then
		Mark.gkLastOwner = ownerId
		Mark.gkFreeAt = nil
	elseif Mark.gkLastOwner and not Mark.gkFreeAt then
		Mark.gkFreeAt = { id = Mark.gkLastOwner, at = now0 }
	end
	local shot = false
	local crossSide = nil
	if free and crossP and crossT and crossT > 0 and crossT <= 3 and into > 4 then
		crossSide = flat(crossP - defend):Dot(side)
		shot = math.abs(crossSide) <= half + 2
		-- ownership flicker: "free" for a moment while the ball is still at his feet (log: dive right, the same carrier
		-- owned it again 0.08 s later). A real shot is several studs away from the kicker after two frames.
		local fa = Mark.gkFreeAt
		if shot and fa and now0 - fa.at < 0.1 and ballPos then
			local fp = Players:GetPlayerByUserId(fa.id)
			local fr = fp and ActorTargeting.GetActorRoot(fp)
			if fr and flat(fr.Position - ballPos).Magnitude < 3.5 then
				shot = false
				logFile("gk flicker", "ball at", actorName(fp), "free", string.format("%.2f", now0 - fa.at))
			end
		end
	end

	-- Free ball: walk the predicted path (Physics.GetStateAtTime, world collisions) and take the EARLIEST point we can
	-- reach. Walk/jump first (no ragdoll), dive only when walking cannot make it.
	local plan = nil
	local lostStand = nil
	if free and ballPos then
		local _, _, samples, ts = Mark.ballPath(root)
		if samples then
			local limit = shot and (crossT + 0.05) or 2.5
			local diveBest = nil
			local enemies = nil
			if not shot then
				enemies = {}
				for _, model in Mark.models() do
					local actor = Actors.GetFromCharacter(model)
					if actor and actor ~= LocalPlayer and not sameTeam(actor) then
						local r = ActorTargeting.GetActorRoot(actor)
						if r and not Mark.mateDown(actor, model) then
							enemies[#enemies + 1] = r.Position
						end
					end
				end
			end
			for i = 2, #samples do
				local t = ts[i]
				if t > limit then
					break
				end
				local p = samples[i]
				local rel = flat(p - mouthP)
				local a = rel:Dot(fwd)
				local s = rel:Dot(side)
				if a < 0 then
					-- crossed the mouth: everything after is a ball in the net
					break
				end
				local inArea = a <= areaDepth and math.abs(s) <= half + 6
				local contested = false
				if inArea and enemies then
					for _, e in enemies do
						if flat(p - e).Magnitude / 26.9 < t then
							contested = true
							break
						end
					end
				end
				if inArea and not contested then
					local g = flat(p - root.Position).Magnitude
					local h = p.Y - root.Position.Y
					local walkT = math.max(g - bodyR, 0) / spd + react + CFG.GkWalkSlack
					if h >= -3 and h <= groundTop and walkT <= t then
						plan = { kind = "walk", p = p, t = t, h = h, g = g, slack = t - walkT }
						break
					end
					if h > groundTop and h - airTop <= jumpH then
						local rise = Mark.riseT(math.max(h - airTop + 0.5, 0.3))
						if walkT + rise <= t then
							plan = { kind = "jump", p = p, t = t, h = h, g = g, rise = rise, slack = t - walkT - rise }
							break
						end
					end
					if shot and not diveBest and g <= diveD + saveReach then
						local curve = diveMod.GetCurveSecondsForTravel(math.max(g - saveReach, 0), diveD)
						local slack = t - react - curve
						local top = assist and assist.GetReachableContactHeight(curve, h) or maxSave
						if slack >= 0 and h >= -2 and h <= math.min(top, maxSave) then
							diveBest = { kind = "dive", p = p, t = t, h = h, g = g, curve = curve, slack = slack }
						end
					end
				end
			end
			plan = plan or diveBest
			-- No reachable point on the path: do not run to the goal-line crossing (blind) - go to where the ball's PATH is
			-- soonest within dive range (an angled shot is reachable earlier, and sideways, than at the line)
			if shot and not plan then
				for i = 2, #samples do
					local t = ts[i]
					if t > limit then
						break
					end
					local p = samples[i]
					local rel = flat(p - mouthP)
					local a, s = rel:Dot(fwd), rel:Dot(side)
					if a < 0 then
						break
					end
					if a <= areaDepth and math.abs(s) <= half + 6 then
						local g = flat(p - root.Position).Magnitude
						local h = p.Y - root.Position.Y
						if h >= -2.5 and h <= maxSave + jumpH * 0.6 then
							local need = math.max(g - diveD * (CFG.GkLostDiveFrac or 0.75), 0) / spd + react
							local deficit = need - t
							if not lostStand or deficit < lostStand.deficit - 0.03 then
								lostStand = { p = p, t = t, g = g, h = h, deficit = deficit }
							end
						end
					end
				end
			end
			-- A ball flying over the bar ("cross bad-y") is not chased past GkChaseDepth (log: jump 23.7 out at such a ball,
			-- missed, it bounced back to an enemy - goal). A ball merely going AWAY is still taken: v171 skipped that too and
			-- the keeper let a jump intercept at 19.8 go - the enemy took it and scored (20980).
			if plan and not shot and crossWhy == "bad-y" and flat(plan.p - mouthP):Dot(fwd) > (CFG.GkChaseDepth or 12) then
				if not Mark.gkChaseLog or now - Mark.gkChaseLog > 0.8 then
					Mark.gkChaseLog = now
					logFile("gk intercept skip", "ball over the bar", "depth", string.format("%.1f", flat(plan.p - mouthP):Dot(fwd)), "into", string.format("%.1f", into), "plan", plan.kind)
				end
				plan = nil
			end
			-- A free ball that is NOT a shot: an enemy near the intercept point takes it before we are there (log: we ran
			-- out, he picked it up, nothing left to do). Stay in the goal.
			if plan and not shot and enemies then
				local nearR = CFG.GkInterceptEnemy or 14
				for _, e in enemies do
					local dE = flat(plan.p - e).Magnitude
					if dE <= nearR then
						if not Mark.gkNearLog or now - Mark.gkNearLog > 0.8 then
							Mark.gkNearLog = now
							logFile("gk intercept skip", "enemy near the point", string.format("%.1f", dE), "plan", plan.kind, "t", string.format("%.2f", plan.t), "g", string.format("%.1f", plan.g))
						end
						plan = nil
						break
					end
				end
			end
			if shot then
				local bait = Mark.gkBait(samples, ts, crossT)
				if bait then
					Mark.gkBaitKeep = now + 0.15
					-- a walk / jump that touches the ball BEFORE he does is still ours; everything else (dive, late walk) is not
					if not (plan and plan.kind ~= "dive" and plan.t < bait.t - 0.05) then
						plan = nil
					end
					shot = false
					if not Mark.gkBaitLog or now - Mark.gkBaitLog > 0.5 then
						Mark.gkBaitLog = now
						logFile("gk bait", bait.name, "touch", string.format("%.2f", bait.t), "cross", string.format("%.2f", crossT), "d", string.format("%.1f", bait.dist), "plan", plan and plan.kind or "-")
					end
				elseif Mark.gkBaitKeep and now < Mark.gkBaitKeep and crossT > 0.3 then
					-- the test dropped out for a frame (noise on the receive box edge): do not commit an irreversible dive on it
					shot = false
					plan = (plan and plan.kind ~= "dive") and plan or nil
				end
			end
		end
	end

	-- knocked (Keeper Push on us): no body touches the ball while the stumble lasts - a walk / jump / receive plan is
	-- fiction. Only the dive branch stays (Mark.gkKnockDive already fired one in the allowed window).
	local knocked = Mark.gkKnockUntil ~= nil and now < Mark.gkKnockUntil
	if knocked and plan and plan.kind ~= "dive" then
		plan = nil
	end

	-- PASS READ. A free ball on its way into an enemy's receive box near our goal is a pass to a man who shoots the moment
	-- it lands (log: cross from side -46 to a receiver at side +31 / 26 out, one-touch shot 0.21 s from the first shot
	-- frame, keeper still at lat -1.5: "gk dive none", goal). After the touch there is no time; during the pass flight
	-- (~1-2 s) there is. So while the pass flies the keeper shifts to the receiver's cone: on the bisector of the angle
	-- receiver -> posts, GkPassReadDepth in front of the line. Observed event (the ball path enters HIS receive box,
	-- gkBait = the game's own receive test), not positioning; the player's stick wins.
	local recvStand = nil
	if free and not shot and not plan and ballPos and CFG.GkPassRead ~= false then
		local _, _, smpR, tsR = Mark.ballPath(root)
		local rc = smpR and Mark.gkBait(smpR, tsR, 2.5)
		local lbR, _, rbR = goalMouthCorners(ours)
		if rc and rc.c and lbR and rbR then
			local R = rc.c
			local relR = flat(R - mouthP)
			local aR, sR = relR:Dot(fwd), relR:Dot(side)
			local segR = (relR - side * math.clamp(sR, -half, half)).Magnitude
			if aR > 3 and segR <= (CFG.GkPassReadZone or 45) then
				local a1, a2 = unitOrNil(flat(lbR - R)), unitOrNil(flat(rbR - R))
				local bis = a1 and a2 and unitOrNil(a1 + a2)
				local den = bis and -bis:Dot(fwd) or 0
				if den > 0.15 then
					local depth = math.min(CFG.GkPassReadDepth or 3, aR - 4)
					local S = R + bis * ((aR - depth) / den)
					local relS = flat(S - mouthP)
					S = mouthP + fwd * math.max(relS:Dot(fwd), 1) + side * math.clamp(relS:Dot(side), -(half - 1), half - 1)
					Mark.gkRecv = { p = Vector3.new(S.X, root.Position.Y, S.Z), at = now, name = rc.name }
					if not Mark.gkRecvLog or now - Mark.gkRecvLog > 0.5 then
						Mark.gkRecvLog = now
						logFile("gk pass read", rc.name, "touch", string.format("%.2f", rc.t), "his a", string.format("%.1f", aR), "s", string.format("%.1f", sR), "stand lat", string.format("%.1f", flat(S - mouthP):Dot(side)), "d", string.format("%.1f", flat(S - mouthP):Dot(fwd)), "move", string.format("%.1f", flat(S - root.Position).Magnitude))
					end
				end
			end
		end
	end
	-- hold through the touch (ownership flips to him, no charge yet / a one-touch shot): 0.35 s
	if not shot and not plan and Mark.gkRecv and now - Mark.gkRecv.at < 0.35 then
		recvStand = Mark.gkRecv.p
	end

	-- Charged shot read. While the carrier charges, ActionPresentationUpdate KickChargeStarted/Updated replicates his
	-- aim (Mark.charges[uid].dir). Where that ray meets our mouth is where the shot starts; moving there DURING the
	-- charge buys the 0.3-0.9 s a close corner shot never leaves after release (log: first sight eta 0.27, gap 14.6,
	-- no save possible). Not positioning: it only fires on a live charge aimed inside the frame.
	local chargeS = nil
	if not free and ownerRoot and Mark.charges then
		local rec = Mark.charges[ownerId]
		if rec and rec.live and rec.dir and now - (rec.seen or 0) < 0.6 then
			local d = rec.dir.Unit
			local den = d:Dot(fwd)
			if den < -0.2 then
				local o = ownerRoot.Position
				local tPlane = (mouthP - o):Dot(fwd) / den
				if tPlane > 0 then
					local hitP = o + d * tPlane
					local s = flat(hitP - mouthP):Dot(side)
					if math.abs(s) <= half + 3 then
						chargeS = s
						-- a FAKE charge aims through his teammate: positioning on the ray's mouth point is the bait too
						for _, model in Mark.models() do
							local actor = Actors.GetFromCharacter(model)
							if actor and actor ~= LocalPlayer and actor.UserId ~= ownerId and not sameTeam(actor) then
								local r2 = ActorTargeting.GetActorRoot(actor)
								if r2 then
									local rel = flat(r2.Position - o)
									local along2 = rel:Dot(flat(d).Unit)
									if along2 > 5 and along2 < flat(hitP - o).Magnitude then
										local lat2 = (rel - flat(d).Unit * along2).Magnitude
										if lat2 <= (CFG.GkBaitRay or 2.5) then
											chargeS = nil
											if not Mark.gkBaitLog or now - Mark.gkBaitLog > 0.5 then
												Mark.gkBaitLog = now
												logFile("gk bait", actorName(actor), "on charge ray", "lat", string.format("%.1f", lat2))
											end
											break
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end

	-- pushed off the spot (shotgun etc.): back to where he stood, unless a save is on
	local retTarget = nil
	if not plan and not shot then
		local rt = Mark.gkReturnTick(character, root, { now = now, landed = landed, fwd = fwd, side = side, mouthP = mouthP, diveMod = diveMod, role = role })
		retTarget = rt
	end
	-- PRESS (Mark.gkPress): dive / jump + dive into the carrier, or come out on his line to the mouth
	Mark.gkPressStandP = nil
	-- ownership flickers "free" for a frame or two while the ball is at his feet: keep pressing HIM (log: press/free/charge
	-- alternated every frame and the keeper shook on the spot)
	local pid = (not free and ownerRoot) and ownerId or nil
	if not pid and free and Mark.gkFreeAt and now - Mark.gkFreeAt.at < 0.3 and not shot and not plan then
		-- a 1-2 frame "free" with the ball still at his feet only; a ball that left him (flick, shot, pass) is the ball's
		local fp = playerOf(Mark.gkFreeAt.id)
		local fr = fp and ActorTargeting.GetActorRoot(fp)
		local bp = Renderer.GetPosition()
		if fr and bp and flat(bp - fr.Position).Magnitude <= 4 then
			pid = Mark.gkFreeAt.id
		end
	end
	-- a hook flier (the ball is free: he is flying at it) is pressed like a carrier, on his exact grapple path
	local hookId = nil
	if landed and role and role.Dive then
		hookId = Mark.gkHooker(root, mouthP, side, fwd, half)
		if hookId and (not pid or pid == hookId) then
			pid = hookId
		else
			hookId = nil
		end
	end
	-- a flier body: he beats the carrier's press only when he is about to arrive (the carrier we press keeps the dive until then)
	local flierId, flierT = nil, nil
	if landed and role and role.Dive and not hookId and CFG.GkFlier ~= false then
		flierId, flierT = Mark.gkFlierPick(root, mouthP, side, fwd, half, now, ownerId)
		if flierId and pid and pid ~= flierId and flierT > (CFG.GkPressLate or 0.9) then
			flierId = nil
		end
		if flierId then
			pid = flierId
		end
	end
	if pid and landed and role and role.Dive and Mark.gkPressGate(shot, plan, hookId, flierId, flierT) then
		if Mark.gkPress(character, root, { now = now, ownerId = pid, fwd = fwd, side = side, half = half, mouth = mouthP, diveMod = diveMod, role = role, flier = flierId ~= nil, flierT = flierT }) then
			return true
		end
		local sl = Mark.gkStandLast
		if not Mark.gkPressStandP and sl and sl.id == pid and now - sl.at < 0.35 then
			Mark.gkPressStandP = sl.p
		end
	end
	-- MIRROR / HOME read "who is attacking": the carrier, or the enemy standing at a loose ball. Only when he is NEAR the mouth
	local mRoot = ownerRoot
	local mirrorRange = CFG.GkMirrorRange or 26
	if not mRoot and free and ballPos and not shot and segB <= math.max(mirrorRange, CFG.GkHomeDanger or 70) and flat(ballVel).Magnitude < 25 then
		mRoot = Mark.gkContender(ballPos, CFG.GkMirrorNear or 9)
	end
	local mDepth, mLat = nil, nil
	if mRoot and CFG.GkMirror ~= false and along > -2 then
		mDepth, mLat = Mark.gkMirror(along, ballSide, half, mirrorRange, segB)
	end
	local stand, why, eta = nil, "free", nil
	local stopAt, urgent = 0.8, false
	if not plan and not shot and chargeS then
		stand = mouthP + fwd * 1.5 + side * math.clamp(chargeS, -(half - 1), half - 1)
		why = "charge"
		stopAt, urgent = 0.4, true
	elseif not plan and not shot and Mark.gkPressStandP then
		stand = Mark.gkPressStandP
		why = "press"
		stopAt, urgent = 0.8, true
	elseif not plan and not shot and recvStand and not Mark.userInputDir() then
		stand = recvStand
		why = "recv"
		stopAt, urgent = 0.5, true
	elseif not plan and not shot and mDepth and not Mark.userInputDir() then
		stand = mouthP + fwd * mDepth + side * mLat
		why = "mirror"
		stopAt, urgent = 0.6, true
	end
	if plan then
		stand = plan.p
		why = plan.kind
		eta = plan.t
		stopAt, urgent = 0.3, true
	elseif shot then
		-- No save on the path: still close the crossing on the line, a deflection beats standing.
		stand = defend + fwd * 1.5 + side * math.clamp(crossSide, -(half - 1), half - 1)
		why = "lost"
		if lostStand and CFG.GkLostPath ~= false then
			local dirv = unitOrNil(flat(lostStand.p - root.Position))
			if dirv then
				local goD = math.max(lostStand.g - diveD * (CFG.GkLostDiveFrac or 0.75), 0)
				local cand = root.Position + dirv * goD
				local depthC = math.clamp(flat(cand - mouthP):Dot(fwd), 1.0, areaDepth)
				local sideC = math.clamp(flat(cand - mouthP):Dot(side), -(half - 1), half - 1)
				stand = mouthP + fwd * depthC + side * sideC
				why = "lost-path"
			end
		end
		eta = crossT
		stopAt, urgent = 0.3, true
	end
	if not stand and retTarget then
		stand, why, stopAt, urgent = retTarget, "return", 1.0, true
	end
	-- HOME. The keeper left far up the field stays there while an attack comes (log: "gk pos free d 54.5" for 7 s as the
	-- carrier ran 140 -> 55, shot, keeper 47 studs from the crossing). With danger near our goal (an enemy carrier, or a
	-- free ball, inside GkHomeDanger of the mouth) and no stick input, a keeper further than GkHomeDist from the line
	-- runs back to the mouth on the ball's side.
	if not stand and CFG.GkHome ~= false and not Mark.userInputDir() then
		local relU = flat(root.Position - mouthP)
		local outU = relU:Dot(fwd)
		local latU = math.abs(relU:Dot(side))
		if outU > (CFG.GkHomeDist or 20) or latU > half + 15 then
			-- an attack: an enemy carrier, a shot / ball coming at us, or an enemy at a loose ball, NEAR the mouth segment (was: any
			-- ball in the half field - 51 "home" runs a session, most for a ball nobody played at us)
			local danger = ballPos and segB <= (CFG.GkHomeDanger or 70) and (ownerRoot ~= nil or (free and (into > 4 or mRoot ~= nil)))
			if danger then
				stand = mouthP + fwd * 3 + side * math.clamp(ballSide * 0.15, -(half - 2), half - 2)
				why, stopAt, urgent = "home", 1.5, true
			end
		end
	end
	-- No positioning: without a ball to chase the player keeps full control of where the keeper stands.

	local toStand = stand and flat(stand - root.Position) or Vector3.zero
	local gapStand = toStand.Magnitude
	if stand and gapStand > stopAt then
		local scale = urgent and 1 or math.max(Mark.arriveScale(gapStand, 16), 0.3)
		Mark.move.look = fwd
		Mark.moveSteer(toStand.Unit * scale, "gk")
	elseif Mark.move.mode == "gk" then
		Mark.moveStop("gk")
	end

	if not Mark.gkLog or now - Mark.gkLog > 0.45 or Mark.gkWhy ~= why then
		Mark.gkLog = now
		Mark.gkWhy = why
		local rs = flat((stand or root.Position) - defend)
		logFile(
			"gk pos", why,
			"d", string.format("%.1f", rs:Dot(fwd)),
			"lat", string.format("%.1f", rs:Dot(side)),
			"along", string.format("%.1f", along),
			"side", string.format("%.1f", ballSide),
			"into", string.format("%.1f", into),
			"eta", eta and string.format("%.2f", eta) or "-",
			"gap", string.format("%.1f", gapStand),
			"owner", free and "free" or (ownerRoot and "enemy" or "ours"),
			"cross", shot and string.format("%.1f %s", crossSide, crossWhy) or crossWhy,
			"plan", plan and string.format("%s t %.2f g %.1f h %.1f", plan.kind, plan.t, plan.g, plan.h) or "-"
		)
	end

	Mark.gkPressWatch(root)
	Mark.gkDiveWatch(root)
	-- walk / jump plans flip frame to frame on noisy h (log: jump, walk, jump, walk...), so neither the jump press
	-- nor the "no movement plan -> dive" test held for two frames. Keep the last movement plan for 0.2 s and the jump
	-- press time for 0.25 s.
	if plan and (plan.kind == "walk" or plan.kind == "jump") then
		Mark.gkMovePlanAt = now
	end
	if plan and plan.kind == "jump" then
		Mark.gkJumpPlan = { pressAt = now + (plan.t - react) - plan.rise - 0.03, h = plan.h, t = plan.t, rise = plan.rise, untilT = now + 0.25 }
	end
	local jp = Mark.gkJumpPlan
	if jp and now > jp.untilT then
		Mark.gkJumpPlan = nil
		jp = nil
	end
	local moveHeld = Mark.gkMovePlanAt and now - Mark.gkMovePlanAt < 0.2
	if jp and landed and (not plan or plan.kind ~= "dive" or moveHeld) then
		if now >= jp.pressAt and now - (Mark.gkJump or 0) > 0.45 then
			Mark.gkJump = now
			Mark.gkJumpPlan = nil
			local jumped = Mark.doJump("gk")
			logFile("gk jump", jumped and "ok" or "no", "h", string.format("%.1f", jp.h), "t", string.format("%.2f", jp.t), "rise", string.format("%.2f", jp.rise))
		end
	elseif shot and (not plan or plan.kind == "dive" or (plan.slack or 1) < (CFG.GkWalkMargin or 0.08)) and role and role.Dive and (landed or knocked) and now - (Mark.gkDive or 0) > diveMod.Constants.RepeatDelaySeconds then
		-- (the old gate: no dive while a walk / jump plan was seen in the last 0.2 s and the cross was > 0.18 s away. A
		-- walk that is only just in time flips to "no plan" a frame later, the gate held the dive for 0.2 s more and the
		-- dive was too late = the keeper "froze". Now a walk / jump with less than GkWalkMargin to spare does not block.)
		-- no walk / jump save: dive only in a direction the game's dive + assist actually connects with
		local dState, dWorld = state, gkWorld
		if not Mark.ballSrcId and Renderer.GetAuthoritativeMovementState then
			local s2, w2 = Renderer.GetAuthoritativeMovementState()
			if s2 and w2 then
				dState, dWorld = s2, w2
			end
		end
		local hit = Mark.gkOwnDive(root) or Mark.gkDiveSearch(root, dState, dWorld)
		-- Dive at the LAST moment the save still connects: a ground dive cannot be undone, and a walk / jump (or a better
		-- dive) may open up as the ball comes (log: jump + dive at eta 0.83 while a walk save at 0.35 existed).
		local late = CFG.GkDiveLate or 0.07
		local deferred = false
		if hit and hit.own and late > 0 then
			-- wait only for a later dive that keeps the timing margin of this one (a later fragile dive is no dive)
			local lateHit = Mark.gkOwnDive(root, late, true)
			if lateHit and (lateHit.robust or not hit.robust) then
				hit = nil
				deferred = true
			end
		end
		if not hit and not deferred and CFG.GkJumpDive ~= false then
			-- nothing a ground dive touches (the high corner: the dive rises ~1.7 studs): jump first, dive from the air
			for _, td in { 0.12, 0.25 } do
				local h2 = Mark.gkOwnDive(root, td)
				if h2 and late > 0 and Mark.gkOwnDive(root, td + late) then
					deferred = true
					break
				end
				if h2 then
					Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
					if Mark.doJump("gk") then
						Mark.gkJump = now
						Mark.gkCombo = { diveAt = now + td, untilT = now + td + 0.25, choice = Mark.actionMotion.DirectionChoices[h2.name], wd = h2.exact and h2.wd or nil, dir = h2.exact and h2.wd or nil, fwd = fwd, role = role, name = "shot " .. h2.name }
						logFile("gk dive", "jump + dive", "choice", h2.name, "dive in", td, "contact", string.format("%.2f", h2.t), "eta", string.format("%.2f", crossT or -1))
						hit = false
					end
					break
				end
			end
			if Mark.gkCombo then
				return true
			end
		end
		if hit then
			-- a camera choice saves: dive as the game would, body untouched. Only an exact (between-choices) save turns the
			-- body: the dash + "F" animation go along it (gkDiveAim, GetWorldDirection hook) and gkAimTick gives the
			-- rotation back when the dive ends.
			local face = hit.exact and hit.wd or fwd
			TurnControl.LockAutoRotate("Goalkeeper", face)
			if hit.exact then
				Mark.gkDiveAim = { dir = hit.wd, at = now, untilT = now + diveMod.Constants.DurationSeconds + 0.05, fwd = fwd, faceF = true }
			end
			Mark.diveSet(character, hit.wd, face)
			Mark.gkDive = now
			local ok = role.Dive()
			Mark.diveRestore(character, hit.wd)
			if ok and hit.exact then
				Mark.gkDiveAim.faceLock = true
			else
				if hit.exact then
					Mark.gkDiveAim = nil
				end
				TurnControl.ReleaseAutoRotate("Goalkeeper")
			end
			if ok then
				Mark.gkDiveRec = { at = os.clock(), name = hit.name, minD = math.huge, eta = crossT or -1 }
			end
			logFile("gk dive", ok and "ok" or "no", "model", hit.own and "own" or "assist", "choice", hit.name, "miss", string.format("%.2f", hit.miss), "t", string.format("%.2f", hit.t or -1), "assist", tostring(hit.assisted), "eta", string.format("%.2f", crossT or -1), "dir", fmtV(hit.wd), "robust", hit.own and (hit.robust and "yes" or "no") or "-", "fwd", string.format("%.2f", hit.wd:Dot(fwd)), "ballSpd", string.format("%.0f", typeof(ballVel) == "Vector3" and ballVel.Magnitude or 0))
		elseif not deferred and (not Mark.gkNoDiveLog or now - Mark.gkNoDiveLog > 0.3) then
			Mark.gkNoDiveLog = now
			logFile("gk dive none", "eta", string.format("%.2f", crossT or -1), "cross", string.format("%.1f", crossSide or 0))
		end
	end
	-- Auto clear is OFF by default: it sent a GetClearCommand every 1.2 s while we held the ball, which raced the
	-- player's own throw / kick (user: after a save the keeper could not release the ball himself).
	if CFG.GkAutoClear and Mark.weOwn and Mark.weOwn() and os.clock() - (Mark.gkClear or 0) > 1.2 then
		local aim = acts.GetClearForwardDirection(LocalPlayer, {
			GetDefendGoalPosition = function()
				return defend
			end,
			GetAttackGoalPosition = function()
				return attack
			end,
		})
		if aim then
			local cmd = acts.GetClearCommand(LocalPlayer, nil, {
				AimDirection = aim,
				KickDirection = aim,
				ChargeSeconds = acts.Constants.ClearChargeSeconds,
				HoldSeconds = acts.Constants.ClearChargeSeconds,
			})
			cmd.ShotTime = Workspace:GetServerTimeNow()
			ActionRemoteProtocol.Send(cmd)
			Mark.gkClear = os.clock()
			logFile("gk clear", fmtV(aim))
		end
	end
	return true
end

-- Perf probe (CFG.Perf): inclusive time per section, flushed to the log every 5 s as one "perf" line, biggest first.
Mark.perf = {}
Mark.perfAdd = function(name, ms)
	local p = Mark.perf[name]
	if not p then
		p = { 0, 0, 0 }
		Mark.perf[name] = p
	end
	p[1] += 1
	p[2] += ms
	if ms > p[3] then
		p[3] = ms
	end
end
Mark.perfFlush = function()
	local now = os.clock()
	if now - (Mark.perfAt or now) < 5 then
		Mark.perfAt = Mark.perfAt or now
		return
	end
	local span = now - (Mark.perfAt or now)
	Mark.perfAt = now
	local rows = {}
	for name, p in Mark.perf do
		rows[#rows + 1] = { name = name, n = p[1], sum = p[2], max = p[3] }
	end
	Mark.perf = {}
	table.sort(rows, function(x, y)
		return x.sum > y.sum
	end)
	local out = {}
	for i = 1, math.min(#rows, 9) do
		local r = rows[i]
		out[#out + 1] = string.format("%s %.2fms/s avg %.2f max %.1f n %d", r.name, r.sum / span, r.sum / math.max(r.n, 1), r.max, r.n)
	end
	if #out > 0 then
		logFile("perf", string.format("fps %.0f |", 1 / math.max(Mark.dtAvg or 0.0083, 0.001)), table.concat(out, " | "))
	end
end
-- Section timer. Built by a named factory so its closure stays NATIVE under an obfuscator (policy: Mark.perfWrapper tree).
Mark.perfWrapper = function(name, f)
	return function(...)
		local t0 = os.clock()
		local a, b, c, d, e, g = f(...)
		Mark.perfAdd(name, (os.clock() - t0) * 1000)
		return a, b, c, d, e, g
	end
end
Mark.perfOrig = {}
-- Wrappers are installed only while CFG.Perf is on and taken off again when it goes off: they used to stay on every tick
-- function for good and cost an extra vararg call each, probe or no probe.
Mark.perfSet = function(on)
	on = on and true or false
	if on == (Mark.perfOn or false) then
		return
	end
	Mark.perfOn = on
	for _, name in Mark.perfNames do
		if on then
			local f = Mark[name]
			if type(f) == "function" and not Mark.perfOrig[name] then
				Mark.perfOrig[name] = f
				Mark[name] = Mark.perfWrapper(name, f)
			end
		else
			local f = Mark.perfOrig[name]
			if f then
				Mark[name] = f
				Mark.perfOrig[name] = nil
			end
		end
	end
end

-- ====================================================================================================================
-- MOVEMENT (Movement tab). Every function rides on the game's own entry point, nothing is invented on the wire:
--  Speed       the displacement path of the game's CFrame dash (ActionMotion.RunCFrameDash): root CFrame += step, the step
--              is registered with LocalMovementGuard.RegisterDisplacement (the guard snaps an unregistered move back) and
--              the stream velocity carries the extra speed (CharacterMotion.SetStreamVelocity, nil = real velocity again),
--              so the MovementUpdate packets agree with the position. Pulse = the same step in bursts.
--  Jump Boost  Movement.SetMultiplier JumpHeight: getJumpLaunchSpeed and the guard's registered launch read that table.
--  Stamina     Sprint.SetUnlimitedStamina (the same source API AgentJump / MoveAgent use).
--  Knockback   KnockbackMotion.Run (the client half of a server push) is skipped for our character (Mark.knockHook).
--  Ragdoll     Ragdoll.ClearActor, the game's own end-of-ragdoll, as soon as the server state reaches us.
--  Stun        Stun.IsCharacterStunned / IsActorStunnedForPress answer false for us: sprint and the client button locks.
-- Stun and ragdoll are SERVER states and the server is not in the dump: `noragdoll cleared`, `speed corrected`
-- (MovementCorrection from the server) and `push blocked` in the log are the measurements, not a promise.
-- ====================================================================================================================
Mark.mvStream = function(ch, vel)
	if vel == nil and not Mark.mvStreamOn then
		return
	end
	Mark.mvStreamOn = vel ~= nil
	if ch then
		CharacterMotion.SetStreamVelocity(ch, vel)
	end
end

-- Every game dash (dodge/dribble, keeper dive, jetpack, grapple, recoil, hammer, push, slide) is ActionMotion.RunCFrameDash:
-- it adds its own travel each Heartbeat, owns the stream velocity and cancels itself when the body leaves its path by more
-- than TeleportTolerance (8). Speed must not stack on top of one, so the handles of our own character's dashes are tracked
-- (weak keys: a finished dash drops out) and speedStep stands down while any is active.
Mark.dashes = setmetatable({}, { __mode = "k" })
Mark.dashHook = function()
	local AM = require(Modules.Actions.ActionMotion)
	if Mark.dashOrig then
		return
	end
	Mark.dashOrig = AM.RunCFrameDash
	AM.RunCFrameDash = function(r, cfg)
		local h = Mark.dashOrig(r, cfg)
		if h and r and r.Parent == LocalPlayer.Character then
			Mark.dashes[h] = true
		end
		return h
	end
end
Mark.dashHook()
Mark.dashLive = function()
	for h in Mark.dashes do
		if h.IsActive() then
			return true
		end
		Mark.dashes[h] = nil
	end
	return false
end

-- One extra ground step. false = nothing to add this frame (the caller clears the stream velocity).
Mark.speedStep = function(dt, ch, root, hum)
	if Ragdoll.IsEnabled(ch) or Mark.slideBody() or Mark.dashLive() or Mark.moveLive(Mark.move) then
		return false
	end
	-- the charge walk (ActionMovement.GetChargingWalkSpeed) stays slow: AutoKick models our speed while it charges
	if ChargedKick.IsCharging and ChargedKick.IsCharging() then
		return false
	end
	local k = Mark.knock
	if k and os.clock() < k.at + k.dur + 0.1 then
		return false
	end
	Mark.iceMod = Mark.iceMod or require(Modules.Characters.FreezeIce)
	if Mark.iceMod.IsCharacterFrozen(ch) then
		return false
	end
	local mv = origGetMove(ch)
	if typeof(mv) ~= "Vector3" then
		return false
	end
	local dir = Vector3.new(mv.X, 0, mv.Z)
	local mag = dir.Magnitude
	if mag < 0.1 then
		return false
	end
	dir = dir / mag
	if CFG.SpeedMode == "Pulse" then
		local on = CFG.SpeedPulseOn or 0.25
		if os.clock() % (on + (CFG.SpeedPulseOff or 0.35)) >= on then
			return false
		end
	end
	local extra = (CFG.SpeedValue or 36) - hum.WalkSpeed
	if extra <= 0 then
		return false
	end
	extra = extra * math.min(mag, 1)
	local step = dir * (extra * math.min(dt, 0.05))
	if CFG.SpeedWall ~= false then
		local p = Mark.spdParams
		if not p then
			p = RaycastParams.new()
			p.FilterType = Enum.RaycastFilterType.Exclude
			p.RespectCanCollide = true
			Mark.spdParams = p
		end
		if Mark.spdChar ~= ch then
			Mark.spdChar = ch
			p.FilterDescendantsInstances = { ch }
		end
		p.CollisionGroup = root.CollisionGroup
		local hit = Workspace:Raycast(root.Position, dir * (step.Magnitude + 1.6), p)
		if hit then
			if os.clock() - (Mark.spdWallAt or 0) > 1.5 then
				Mark.spdWallAt = os.clock()
				logFile("speed wall", hit.Instance.Name, "class", hit.Instance.ClassName, "dist", string.format("%.1f", hit.Distance))
			end
			return false
		end
	end
	root.CFrame = root.CFrame + step
	LocalMovementGuard.RegisterDisplacement(root, step)
	local v = root.AssemblyLinearVelocity
	Mark.mvStream(ch, Vector3.new(v.X + dir.X * extra, v.Y, v.Z + dir.Z * extra))
	return true
end

-- Every PreSimulation step. Jump Boost / Stamina are "applied vs wanted", so the toggles and stop() end up in the same place.
Mark.moveHackTick = function(dt)
	local jb = CFG.JumpBoost and (CFG.JumpMult or 1.5) or false
	if jb ~= (Mark.mvJump or false) then
		Mark.mvJump = jb
		Mark.walk = Mark.walk or require(Client.Gameplay.Player.Movement)
		if jb then
			Mark.walk.SetMultiplier("MoveHack", { JumpHeight = jb })
		else
			Mark.walk.ClearMultiplier("MoveHack")
		end
	end
	local st = CFG.InfStamina == true
	if st ~= (Mark.mvStam or false) then
		Mark.mvStam = st
		Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
		Mark.sprintMod = Mark.sprintMod or require(Modules.Actions.Sprint)
		Mark.sprint.SetUnlimitedStamina("MoveHack", st)
		Mark.sprintMod.SetUnlimitedStamina(LocalPlayer, "MoveHack", st)
	end
	local ch = LocalPlayer.Character
	if CFG.NoRagdoll and ch and Ragdoll.IsActorRagdolled(LocalPlayer) then
		local now = os.clock()
		if now - (Mark.nrAt or 0) > 0.1 then
			Mark.nrAt = now
			Mark.nrN = (Mark.nrN or 0) + 1
			local ends = Ragdoll.GetRagdolledUntil(LocalPlayer)
			Ragdoll.ClearActor(LocalPlayer, true)
			logFile("noragdoll cleared", "n", tostring(Mark.nrN), "left", string.format("%.2f", (ends or 0) - Workspace:GetServerTimeNow()))
		end
	end
	local root = ch and ch:FindFirstChild("HumanoidRootPart")
	local hum = ch and ch:FindFirstChildOfClass("Humanoid")
	local moved = false
	if CFG.Speed and root and hum and hum.Health > 0 and hum.WalkSpeed >= 2 then
		moved = Mark.speedStep(dt, ch, root, hum)
	end
	if not moved then
		Mark.mvStream(ch, nil)
	end
end
RunService.PreSimulation:Connect(function(dt)
	Mark.faceStep()
	Mark.moveHackTick(dt)
end)

-- The server answers a position it does not accept with MovementCorrection (CharacterReplication: a lerp over <= 0.15 s when
-- within 15 studs, else a snap): this IS the "flag" / desync - the position the others see is the server's, ours ran ahead.
-- Two jobs: (1) the agent sprints again only after Mark.flagGuard seconds (the game checks a sprint on an empty bar);
-- (2) one log line per correction with what we were doing, which is the measurement of what the server refuses.
Remotes.Get("Characters", "MovementCorrection").OnClientEvent:Connect(function(char, cf)
	if char ~= LocalPlayer.Character or typeof(cf) ~= "CFrame" then
		return
	end
	local root = char:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	local now = os.clock()
	if Mark.agentSprinting and now >= (Mark.sprintFlagUntil or 0) then
		Mark.sprintFlagUntil = now + Mark.flagGuard
		Mark.agentHold(false)
	end
	if now - (Mark.spdCorrAt or 0) > 0.25 then
		Mark.spdCorrAt = now
		Mark.spdCorr = (Mark.spdCorr or 0) + 1
		logFile("server correction", "n", tostring(Mark.spdCorr), "off", string.format("%.1f", (root.Position - cf.Position).Magnitude), "mode", tostring(Mark.move.mode), "agent sprint", tostring(Mark.agentSprinting), "stamina", Mark.sprint and string.format("%.2f", Mark.sprint.GetStamina() or -1) or "-", "speed hack", tostring(CFG.Speed), "no sprint for", Mark.flagGuard, "s")
	end
end)

-- No Stun: the client-side answers only. Stun never touches movement in the dump (CharacterControllers has no Stun
-- reference); it locks the sprint (Sprint.updateSprint reads IsActorStunned) and the action presses (ActionLocks, a
-- shared module the server most likely runs too: an accepted press there is NOT confirmed).
Mark.stunHook = function()
	local S = require(Modules.Characters.Stun)
	if Mark.stunOrig then
		return
	end
	Mark.stunOrig = { chk = S.IsCharacterStunned, press = S.IsActorStunnedForPress }
	S.IsCharacterStunned = function(c)
		if CFG.NoStun and c ~= nil and c == LocalPlayer.Character then
			return false
		end
		return Mark.stunOrig.chk(c)
	end
	S.IsActorStunnedForPress = function(a, t, c)
		if (CFG.NoStun or Mark.knockDiving) and (a == LocalPlayer or (c ~= nil and c == LocalPlayer.Character)) then
			return false
		end
		return Mark.stunOrig.press(a, t, c)
	end
end
Mark.stunHook()

-- VOLLEY WITHOUT COMPETITORS (user: the competitor checks killed every interception). VolleyOpportunity.GetEvaluation
-- hands VolleyLockOn.GetCompetitorCharacters (every player and NPC, TEAMMATES too) to UpdateOpportunity: anyone whose
-- FrontAssist box meets the flight earlier turns OUR prompt off (BlockedByCompetitor). The server never re-checks it -
-- VolleyLockOn.ValidateOpportunityClaim runs Evaluate with competitors = nil - and the ball goes to the first claim. So
-- the local evaluation runs without competitors (CFG.VolleyNoCompetitor): the first press wins, as on the server.
Mark.volleyHook = function()
	local VO = require(Client.Gameplay.Actions.VolleyOpportunity)
	if Mark.volleyEvalOrig then
		return
	end
	local VL = require(Modules.Ball.VolleyLockOn)
	Mark.volleyEvalOrig = VO.GetEvaluation
	local lastBall = nil
	VO.GetEvaluation = function(ch, ...)
		if CFG.VolleyNoCompetitor ~= false and ch ~= nil and ch == LocalPlayer.Character then
			local st, world = Renderer.GetAuthoritativeMovementState()
			if not st then
				return nil
			end
			local id = Renderer.GetMatchBallId()
			if lastBall ~= id then
				if lastBall then
					VL.ClearOpportunities(lastBall)
				end
				lastBall = id
			end
			return VL.UpdateOpportunity(id, st, world, ch, CharacterMotionSmoothing.GetSmoothedServerTime(), nil, nil, ActorTeams.GetCharacterTeamName(ch), nil, CommandTime.GetPlayerVolleyOneWaySeconds(LocalPlayer), nil)
		end
		return Mark.volleyEvalOrig(ch, ...)
	end
end
Mark.volleyHook()

RunService.Heartbeat:Connect(function(dt)
	Mark.dt = dt
	if Log.wn > 0 and os.clock() - Log.wAt > 2 then
		Log.flush()
	end
	Mark.dtAvg = (Mark.dtAvg or dt) * 0.95 + dt * 0.05
	local perf = CFG.Perf
	if perf ~= Mark.perfOn and (perf or Mark.perfOn) then
		Mark.perfSet(perf)
	end
	if not perf then
		return stepLogic()
	end
	local t0 = os.clock()
	stepLogic()
	Mark.perfAdd("stepLogic", (os.clock() - t0) * 1000)
	Mark.perfFlush()
end)
RunService.RenderStepped:Connect(function()
	-- Paint at CFG.PaintHz (60) when the display is much faster (>= ~100 fps): Drawing objects persist between frames,
	-- so skipping a paint just keeps the previous one on screen; below that rate every frame is painted.
	local hz = CFG.PaintHz
	if hz and hz > 0 then
		local nowP = os.clock()
		if (Mark.dtAvg or 1) < 1 / (hz * 1.7) and nowP - (Mark.paintAt or 0) < 1 / hz - 0.0035 then
			return
		end
		Mark.paintAt = nowP
	end
	-- Slow machine (< ~28 fps): paint every second frame. Drawing objects persist, a skipped paint keeps the last picture
	-- (tester log: 12 fps median, paintWorld + paintHud ~ 5 % of every frame).
	if (Mark.dtAvg or 0) > 1 / 28 then
		Mark.paintSkip = not Mark.paintSkip
		if Mark.paintSkip then
			return
		end
	end
	local t0 = os.clock()
	local cam = Workspace.CurrentCamera
	if cam then
		local cf = cam.CFrame
		Mark.frameCam, Mark.framePos, Mark.frameLook = cam, cf.Position, cf.LookVector
		Mark.frameId = (Mark.frameId or 0) + 1
		Mark.framePxK = cam.ViewportSize.Y / (2 * math.tan(math.rad(cam.FieldOfView) * 0.5))
	else
		Mark.frameCam = nil
	end
	paintWorld()
	if next(Mark.hazEv) ~= nil or (Mark.projLive and next(Mark.projLive) ~= nil) or Mark.sp or (Mark.hazFx and not Mark.hazFx.empty) then
		Mark.hazDraw()
	end
	if Mark.gal and Mark.gal.on then
		Mark.galDraw()
	end
	local t1 = os.clock()
	paintHud()
	Mark.frameCam = nil -- Heartbeat-side draws read the live camera
	if CFG.Perf then
		Mark.perfAdd("paintWorld", (t1 - t0) * 1000)
		Mark.perfAdd("paintHud", (os.clock() - t1) * 1000)
	end
end)

local function onEnemyTackleStarted(userId, aim)
	if not Mark.playLive() then
		return
	end
	if not (CFG.AutoDribble or CFG.AutoDodge) or Mark.meKeeper() then
		return
	end
	if type(userId) ~= "number" or userId == LocalPlayer.UserId then
		return
	end
	local actor = playerOf(userId)
	if not actor or sameTeam(actor) or isGoalkeeper(actor) then
		return
	end
	local character = LocalPlayer.Character
	local root = character and ActorTargeting.GetActorRoot(LocalPlayer)
	local theirRoot = ActorTargeting.GetActorRoot(actor)
	if not (root and theirRoot) then
		return
	end
	local theirChar = Actors.GetCharacter(actor)
	local dist = flat(theirRoot.Position - root.Position).Magnitude
	local heading = AimFacing.GetFlatDirection(aim)
	local fromPacket = heading ~= nil
	if not heading then
		heading = headingOf(theirChar, theirRoot)
	end
	if not heading then
		dbg("dribble", "no heading", "dist", string.format("%.2f", dist))
		return
	end
	local srvPos = Mark.enemySlideOrigin(theirRoot, theirChar, heading, 0)
	slideLock[theirChar] = {
		heading = heading,
		origin = srvPos,
		feet = theirRoot.Position,
		startPos = srvPos,
		elapsed = 0,
		hold = os.clock() + 0.45,
		fromPacket = fromPacket,
		t0 = os.clock(),
	}
	local model = Actors.GetCharacter(actor)
	if model and model ~= theirChar then
		slideLock[model] = slideLock[theirChar]
	end
	local lock = slideLock[theirChar]
	local at = Mark.slideAtUs(lock, 0, root, actor)
	if dist < 60 then
		Mark.audits = Mark.audits or {}
		local list = Mark.audits
		if #list > 6 then
			table.remove(list, 1)
		end
		list[#list + 1] = { t0 = os.clock(), root = theirRoot, theirChar = theirChar, actor = actor, name = actorName(actor), p0 = theirRoot.Position, us0 = root.Position, heading = heading, dist = dist, minLat = 1e9, fired = false }
	end
	local maxReach = Mark.dumpTravel(C.HitboxDelaySeconds + C.HitboxSeconds) + 5.9
	local vis = flat(theirRoot.Position - root.Position).Magnitude
	logFile(
		"enemy tackle",
		"id",
		userId,
		"dist",
		string.format("%.2f", at and at.dist or vis),
		"vis",
		string.format("%.2f", vis),
		"dotG",
		at and at.dotG and string.format("%.2f", at.dotG) or "-",
		"dotL",
		at and at.dotL and string.format("%.2f", at.dotL) or "-",
		"hits",
		tostring(at and at.hits),
		"latG",
		at and string.format("%.1f", at.latG) or "-",
		"latL",
		at and string.format("%.1f", at.latL) or "-",
		"side",
		at and at.side and string.format("%.1f", at.side) or "-",
		"body",
		at and at.body and string.format("%.1f", at.body) or "-",
		"boxed",
		tostring(at and at.boxed),
		"fire",
		tostring(at and at.fire),
		"pred",
		tostring(at and at.predHit),
		"srv",
		at and at.srv and string.format("%.1f", at.srv) or "-",
		"def",
		tostring(at and at.defend),
		"walk",
		tostring(at and at.walkIn),
		"strong",
		tostring(at and at.strong),
		"hitIn",
		at and at.hitIn and string.format("%.2f", at.hitIn) or "-",
		"why",
		at and at.why or "-",
		"own",
		tostring(liveOwnerId() == LocalPlayer.UserId),
		"name",
		actorName(actor)
	)
	local atUs = at and at.fire
	if atUs and (at.dist <= math.max(CFG.DribbleReact, maxReach) or vis <= math.max(CFG.DribbleReact, maxReach)) then
		dribbleDanger = {
			root = theirRoot,
			dist = at.dist,
			character = theirChar,
			actor = actor,
			heading = heading,
			origin = srvPos,
			sliding = true,
			fire = at.fire,
			approach = at.approach,
			elapsed = 0,
			hitP = at.hitP,
			closest = at.closest,
			lat = at.lat,
			ourPos = at.ghost,
			hitIn = at.hitIn,
			strong = at.strong,
		}
		Mark.dodgeDone = nil
		dribbleDanger.force = at.fire
		local ownBall = liveOwnerId() == LocalPlayer.UserId
		local ok = false
		-- the dribble (4 s cooldown: Dodge ActiveSeconds 1 + CooldownSeconds 3) only on a strong read
		if at.fire and at.strong and ownBall and CFG.AutoDribble and Mark.dribbleLeft() <= 0 and not Mark.aerial and not Mark.flickStrike then
			ok = select(1, tryDribble())
		end
		local audit = Mark.audits and Mark.audits[#Mark.audits]
		if audit and audit.theirChar == theirChar then
			audit.fired = at.fire and true or false
			audit.why = at.why
			audit.dribble = ok
		end
		if at.fire and not ok and CFG.AutoDodge and Mark.dodgeSteer and not Mark.aerial and not Mark.flickStrike then
			if audit and audit.theirChar == theirChar then
				audit.dodge = true
			end
			Mark.dodgeSteer(root, dribbleDanger)
		end
	else
		dribbleWhy = "clear"
		note("d", dribbleWhy)
	end
end

-- THE REPLICATED CHARGE. Every KickChargeStarted/Updated carries the shooter's aim, pass type, curve, launch sample; the game
-- itself turns it into a launch velocity (TackleEffects.solveChargePath -> ChargePathVelocity.Get(character, chargeSeconds,
-- passType, aim, launchPos, reportedVelocity, kickDir, targetPos, boundaryWorld, curve)) to draw the observed charge path.
-- We wrap Get, keep the latest inputs per enemy and re-run the SAME function at full charge: the exact launch velocity and
-- spin of the shot that is about to be released, then the game's own ball physics (Physics.NewState/GetStateAtTime with the
-- boundary world) for the flight - the whole path, before the ball exists. AutoBlock stands on it, the slide-block times
-- the box against it.
Mark.cpvArgs = {}
Mark.chargeHook = function()
	local cpv = require(Modules.Actions.ChargePathVelocity)
	if not cpv.Get or Mark.cpvOrig then
		return
	end
	Mark.cpv, Mark.cpvOrig = cpv, cpv.Get
	cpv.Get = function(character, sec, ...)
		local pl = character and Players:GetPlayerFromCharacter(character)
		if pl and pl ~= LocalPlayer then
			Mark.cpvArgs[pl.UserId] = { at = os.clock(), char = character, sec = sec, a = table.pack(...) }
		end
		return Mark.cpvOrig(character, sec, ...)
	end
end
Mark.chargeHook()

Mark.chargeShot = function(uid)
	local ca = Mark.cpvArgs[uid]
	if not ca or os.clock() - ca.at > 0.6 or not Mark.cpvOrig then
		return nil
	end
	local memo = Mark.chargeMemo and Mark.chargeMemo[uid]
	if memo and memo.src == ca and os.clock() - memo.at < 0.05 then
		return memo
	end
	local a = ca.a
	local full = (KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds()) or 0.35
	local secF = math.max(ca.sec or 0, full)
	local vel = Mark.cpvOrig(ca.char, secF, a[1], a[2], a[3], a[4], a[5], a[6], a[7], a[8])
	local launch = a[3]
	if not (typeof(vel) == "Vector3" and typeof(launch) == "Vector3") then
		return nil
	end
	local spin = Mark.cpv.GetLaunchSpin(ca.char, vel, a[1], a[4], a[8], secF)
	local world = a[7]
	if not world then
		local _, w = Renderer.GetMovementState()
		world = w
	end
	if not world then
		return nil
	end
	local t0 = Workspace:GetServerTimeNow()
	local st = Physics.NewState(launch, vel, Physics.BallRadius, t0, (typeof(spin) == "Vector3") and spin or Vector3.zero)
	if type(st) ~= "table" then
		return nil
	end
	st.LastKickerUserId = uid
	local pts, ts = { launch }, { 0 }
	for i = 1, 50 do
		local t = i * 0.04
		local s = Physics.GetStateAtTime(st, t0 + t, world)
		local p = s.Position
		if typeof(p) ~= "Vector3" then
			break
		end
		pts[#pts + 1] = p
		ts[#ts + 1] = t
		local v = s.Velocity
		if typeof(v) == "Vector3" and v.Magnitude < 1 then
			break
		end
	end
	memo = { src = ca, at = os.clock(), pts = pts, ts = ts, vel = vel, launch = launch, speed = vel.Magnitude, passType = a[1] }
	Mark.chargeMemo = Mark.chargeMemo or {}
	Mark.chargeMemo[uid] = memo
	return memo
end

-- position of the predicted ball `t` seconds after release (linear between the 0.04 s samples)
Mark.chargeAt = function(cs, t)
	local ts, pts = cs.ts, cs.pts
	if t <= 0 then
		return pts[1]
	end
	for i = 2, #ts do
		if ts[i] >= t then
			local k = (t - ts[i - 1]) / math.max(ts[i] - ts[i - 1], 1e-4)
			return pts[i - 1]:Lerp(pts[i], k)
		end
	end
	return nil
end

-- Where to stand for the shot that is being charged. Path samples that (a) end up in our mouth, (b) are at body height,
-- (c) lie beyond his kick reach; the one we reach with the most time to spare and the least running. His release can come at
-- any moment from the minimum charge on, so the budget is: time to the earliest release + ball flight time to the sample.
Mark.chargeSpot = function(character, root, uid)
	local rec = Mark.charges and Mark.charges[uid]
	if not (rec and rec.live and os.clock() - (rec.seen or 0) < 0.6) then
		return nil
	end
	local cs = Mark.chargeShot(uid)
	local g = Mark.defendGoal()
	if not (cs and g) then
		return nil
	end
	local lb, lt, rb = goalMouthCorners(g)
	if not (lb and lt and rb) then
		return nil
	end
	local mouth = (lb + rb) * 0.5
	local sideV = unitOrNil(flat(rb - lb))
	if not sideV then
		return nil
	end
	local launchF = flat(cs.launch - mouth)
	local out = Vector3.new(-sideV.Z, 0, sideV.X)
	if launchF:Dot(out) < 0 then
		out = -out
	end
	local half = flat(rb - lb).Magnitude * 0.5
	local bottomY = math.min(lb.Y, rb.Y)
	local topY = math.max(lt.Y, bottomY + 4)
	-- does the flight end in our mouth?
	local crossI = nil
	for i = 2, #cs.pts do
		local p = cs.pts[i]
		if flat(p - mouth):Dot(out) <= 0.3 then
			if math.abs(flat(p - mouth):Dot(sideV)) <= half + 2.5 and p.Y >= bottomY - 1.5 and p.Y <= topY + 1.5 then
				crossI = i
			end
			break
		end
	end
	if not crossI then
		return nil
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
	if type(spd) ~= "number" or spd < 8 then
		spd = 16
	end
	local rcv = HitboxSettings.Receive
	local bodyHalf = rcv.Size.X * 0.5
	local lo = rcv.CFrameOffset.Y - rcv.Size.Y * 0.5
	local hi = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + (Physics.BallRadius or 1)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local minRel = KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds() or 0.2
	local tRel = math.max(minRel - (os.clock() - rec.at), 0)
	local reach = Mark.kickReach() + 0.8
	-- a high shot (most of them go up) is blocked in the air: AirReceive at the top of our jump (Mark.preJump times the
	-- jump to his charge). Standing samples are preferred (+4 studs of "cost" for a jump spot).
	local air = HitboxSettings.AirReceive
	local hiJ = (Mark.jumpH or 7.2) + air.CFrameOffset.Y + air.Size.Y * 0.5 + (Physics.BallRadius or 1)
	local best, bestMove, worst = nil, math.huge, nil
	for i = 2, crossI do
		local p = cs.pts[i]
		local h = p.Y - root.Position.Y
		local jump = h > hi
		if h >= lo and (h <= hi or (CFG.BlockPreJump ~= false and h <= hiJ)) and flat(p - cs.launch).Magnitude >= reach then
			local d = flat(p - root.Position).Magnitude
			local need = math.max(d - bodyHalf, 0) / spd + ping * 0.5 + 0.06
			local slack = tRel + cs.ts[i] - need
			if slack >= 0 then
				local cost = d + (jump and 4 or 0)
				if cost < bestMove then
					best, bestMove = { p = p, t = cs.ts[i], slack = slack, ok = true, d = d, jump = jump }, cost
				end
			elseif not worst or slack > worst.slack then
				worst = { p = p, t = cs.ts[i], slack = slack, ok = false, d = d }
			end
		end
	end
	local pick = best or worst
	if pick then
		pick.tRel, pick.speed, pick.cross = tRel, cs.speed, cs.pts[crossI]
	end
	return pick
end

local function onFx(kind, userId, a, b, c, aimDir, ...)
	-- Direction Spoof check: the server's presentation of OUR charge (what the keeper's client draws)
	if Mark.sp and userId == LocalPlayer.UserId and (kind == "KickChargeStarted" or kind == "KickChargeUpdated") then
		local sp = Mark.sp
		local d0 = typeof(aimDir) == "Vector3" and aimDir or (type(aimDir) == "table" and aimDir.Direction)
		sp.echo = (sp.echo or 0) + 1
		if typeof(d0) == "Vector3" and (sp.echo <= 6) then
			local real = Shoot.aim and Shoot.aim.Direction
			logFile("spoof echo", kind, "t", string.format("%.2f", os.clock() - sp.t0), "dir", fmtV(d0), "vs real", real and string.format("%.0f deg", math.deg(math.acos(math.clamp(d0.Unit:Dot(real.Unit), -1, 1)))) or "-")
		end
	end
	if kind == "GoalkeeperDiveStarted" and type(userId) == "number" and userId ~= LocalPlayer.UserId then
		-- the dive cooldown is GoalkeeperDive.Constants.RepeatDelaySeconds from the START of the dive
		local who = playerOf(userId)
		if who and who ~= LocalPlayer and not sameTeam(who) then
			Mark.foeDive = Mark.foeDive or {}
			Mark.foeDive[userId] = os.clock()
			-- Keeper Trap: the dive starts now; a = his server start time (as for the flick)
			-- Packet (dump TackleEffects.receiveEffect -> presentEffect): a = the dive DIRECTION NAME (ActionMotion
			-- .DirectionChoices: F / RF / R / ... relative to his camera; a keeper's body faces his camera), the server start
			-- time is the 9th arg = select(3, ...). The old code read `a` as the start time (a string -> el0 always 0) and
			-- had no direction at all: every dive was solved as a dash at us.
			local hr = ActorTargeting.GetActorRoot(who)
			local srvNow = Workspace:GetServerTimeNow()
			local st = select(3, ...)
			local wd = nil
			Mark.actionMotion = Mark.actionMotion or require(Modules.Actions.ActionMotion)
			Mark.gkDiveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
			local choice = type(a) == "string" and Mark.actionMotion.DirectionChoices[a]
			local look = hr and unitOrNil(flat(hr.CFrame.LookVector))
			if choice and look then
				wd = unitOrNil(flat(look * (choice.Forward or 0) + Vector3.new(-look.Z, 0, look.X) * (choice.Right or 0)))
			end
			Mark.trapDive = { uid = userId, at = os.clock(), el0 = type(st) == "number" and math.clamp(srvNow - st, 0, 0.4) or 0, P0 = hr and hr.Position, wd = wd, name = type(a) == "string" and a or "?" }
			local myR = ActorTargeting.GetActorRoot(LocalPlayer)
			if myR and hr and wd and isGoalkeeper(who) then
				local toUsL = unitOrNil(flat(myR.Position - hr.Position))
				if toUsL and wd:Dot(toUsL) >= math.cos(math.rad(CFG.WallTrapCone or 50)) then
					Mark.trapLearn(false, flat(myR.Position - hr.Position).Magnitude)
				end
			end
			if myR and isGoalkeeper(who) then
				Mark.wallTrap(myR, true)
			end
			logFile("keeper dive seen", actorName(who), "gk", tostring(isGoalkeeper(who)), "-> fakes off for", string.format("%.2f", Mark.foeDiveLeft()))
		end
	end
	-- Keeper Push / AutoShield ground truth (dump TackleEffects.presentEffect): ViolenceKnockback = victim actor id,
	-- (a), attacker actor id, knock velocity; ForcefieldBlocked = the shield ate a hit
	if kind == "ViolenceKnockback" and (b == LocalPlayer.UserId or userId == LocalPlayer.UserId) then
		local gp = Mark.gunPushRec
		gp = gp and os.clock() - gp.at < 1.5 and b == LocalPlayer.UserId and gp or nil
		-- tackles / slides / other guns knock too: only a knock-back of ours right after a push is its result
		logFile(gp and "gunpush result" or "knock", b == LocalPlayer.UserId and "we hit" or "we were hit", "victim", tostring(userId), "by", tostring(b), "vel", typeof(c) == "Vector3" and string.format("%.0f", c.Magnitude) or "-", gp and string.format("%.2f s after the shot", os.clock() - gp.at) or "", gp and gp.vid and (gp.vid == userId and "= THE KEEPER" or "= NOT the keeper") or "")
		if gp and b == LocalPlayer.UserId then
			gp.hit = true
		end
		if userId == LocalPlayer.UserId then
			Mark.gkKnockDive(c)
			Mark.hitNote(b, typeof(c) == "Vector3" and c.Magnitude or 0)
		end
	elseif kind == "ForcefieldBlocked" then
		logFile("shield blocked", "actor", tostring(userId), "a", tostring(a), "by", tostring(b))
	end
	if kind == "TackleStarted" then
		onEnemyTackleStarted(userId, b)
	elseif kind == "KickChargeStarted" or kind == "KickChargeUpdated" then
		if type(userId) == "number" and userId ~= LocalPlayer.UserId then
			Mark.charges = Mark.charges or {}
			local rec = Mark.charges[userId]
			if kind == "KickChargeStarted" or not rec or not rec.live then
				rec = { at = os.clock(), live = true, uid = userId }
				Mark.charges[userId] = rec
			end
			do
				local d0 = typeof(aimDir) == "Vector3" and aimDir or (type(aimDir) == "table" and aimDir.Direction)
				if typeof(d0) == "Vector3" then
					rec.dir = d0
				end
				rec.seen = os.clock()
			end
			local dir = nil
			if typeof(aimDir) == "Vector3" then
				dir = aimDir
			elseif type(aimDir) == "table" and typeof(aimDir.Direction) == "Vector3" then
				dir = aimDir.Direction
			end
			if dir then
				Mark.chargeId = userId
			end
		end
	elseif kind == "KickReleased" or kind == "KickChargeCanceled" then
		if userId == Mark.chargeId then
		end
		if Mark.charges and type(userId) == "number" and Mark.charges[userId] then
			Mark.charges[userId].live = false
		end
		if type(userId) == "number" then
			Mark.noTouchUntil = os.clock() + 0.25
			if userId ~= LocalPlayer.UserId then
				local a = playerOf(userId)
				if a and sameTeam(a) then
					Mark.allyKickUntil = os.clock() + 1.5
				end
			end
		end
	elseif kind == "RainbowFlickStarted" and type(userId) == "number" then
		if userId == LocalPlayer.UserId then
			if Shoot.aim then
				Mark.flickStrike = os.clock() + 3
			end
		else
			flickOwner = userId
			flickUntil = os.clock() + 1.15
			-- RainbowFlick.SetWindingUpUntil is only ever called for the LOCAL player (Gameplay_Script), so IsWindingUp(enemy)
			-- is always false: the flick of another player is known only from this packet (a = server start time). The ball
			-- detaches at start + his display delay + BallDetachSeconds (TackleEffects.RainbowFlickStarted).
			local who = playerOf(userId)
			local ch = who and Actors.GetCharacter(who)
			Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
			local srvNow = Workspace:GetServerTimeNow()
			local startSrv = type(a) == "number" and a or srvNow
			local dly = ch and (CharacterMotion.GetDisplayDelaySeconds(ch) or 0) or 0
			local detachSrv = math.max(startSrv + dly, srvNow) + Mark.flick.Constants.BallDetachSeconds
			Mark.flickRec = Mark.flickRec or {}
			Mark.flickRec[userId] = { at = os.clock(), srvStart = startSrv, detachSrv = detachSrv }
			if who and not sameTeam(who) then
				-- RainbowFlick flight: PopUpSpeed 48 against the ball gravity 100 = 0.96 s up and down after the detach
				Mark.lob = { uid = userId, actor = who, at = os.clock(), detachAt = os.clock() + (detachSrv - srvNow), untilT = os.clock() + (detachSrv - srvNow) + 1.4 }
			end
			local myR = ActorTargeting.GetActorRoot(LocalPlayer)
			local hisR = who and ActorTargeting.GetActorRoot(who)
			logFile("flick seen", who and actorName(who) or userId, "foe", tostring(who ~= nil and not sameTeam(who)), "d", (myR and hisR) and string.format("%.1f", flat(hisR.Position - myR.Position).Magnitude) or "-", "detach in", string.format("%.2f", detachSrv - srvNow), "delay", string.format("%.2f", dly), "arg", typeof(a) == "number" and string.format("%.2f", a - srvNow) or tostring(a))
		end
	elseif kind == "RainbowFlickCanceled" and userId == flickOwner then
		flickOwner = nil
		flickUntil = 0
		if Mark.flickRec then
			Mark.flickRec[userId] = nil
		end
	end
end
BallGroup.TackleEffect.OnClientEvent:Connect(onFx)
Remotes.Get("Ball", "ActionPresentationUpdate").OnClientEvent:Connect(onFx)
SlideTackle.SlidingUntilChanged.Event:Connect(function(ch)
	if not (CFG.AutoDribble or CFG.AutoDodge) or Mark.meKeeper() then
		return
	end
	if not ch then
		return
	end
	local untilT = SlideTackle.GetSlidingUntil(ch)
	if not (untilT and Workspace:GetServerTimeNow() < untilT) then
		return
	end
	local actor = Actors.GetFromCharacter(ch)
	if not actor or actor == LocalPlayer then
		return
	end
	if sameTeam(actor) or isGoalkeeper(actor) then
		return
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local theirRoot = ActorTargeting.GetActorRoot(actor)
	if not (root and theirRoot) then
		return
	end
	local lock, elapsed = lockEnemySlide(ch, theirRoot)
	if not lock then
		return
	end
	local at = Mark.slideAtUs(lock, elapsed, root, actor)
	local maxReach = Mark.dumpTravel(C.HitboxDelaySeconds + C.HitboxSeconds) + 5.9
	if at and at.fire and (at.dist <= CFG.DribbleReact or at.dist <= maxReach) then
		dribbleDanger = {
			root = theirRoot,
			character = ch,
			actor = actor,
			heading = lock.heading,
			origin = lock.origin,
			sliding = true,
			fire = true,
			elapsed = elapsed,
			closest = at.closest,
			lat = at.lat,
			ourPos = at.ghost,
			hitIn = at.hitIn,
			strong = at.strong,
		}
		local ownBall = liveOwnerId() == LocalPlayer.UserId
		local ok = false
		if ownBall and at.strong and CFG.AutoDribble and Mark.dribbleLeft() <= 0 then
			ok = select(1, tryDribble())
		end
		if not ok and CFG.AutoDodge and Mark.dodgeSteer then
			Mark.dodgeSteer(root, dribbleDanger)
		end
	end
end)

local function dumpLog()
	local lines = {}
	local function add(s)
		lines[#lines + 1] = s
	end
	add("-- Illegal Soccer dump " .. os.date("%Y-%m-%d %H:%M:%S") .. " build v197")
	add(string.format("clock=%.3f server=%.3f ping=%.3f", os.clock(), Workspace:GetServerTimeNow(), LocalPlayer:GetNetworkPing()))
	add(string.format(
		"cfg tackleSpeed=%.2f reach=%.1f close=%.1f slop=%.1f windup=%.3f track=%.0f",
		CFG.TackleSpeed,
		CFG.TackleReach,
		CFG.DribbleClose,
		CFG.DribbleSlop,
		CFG.TackleWindup,
		CFG.TrackStuds
	))
	add(string.format(
		"slide hitboxDelay=%.3f hitbox=%.3f travel0.27=%.2f travel0.42=%.2f travel0.57=%.2f land=%.2f dash=%s distC=%.1f/%.1f",
		C.HitboxDelaySeconds,
		C.HitboxSeconds,
		SlideTackle.GetTravel(0.27),
		SlideTackle.GetTravel(0.42),
		SlideTackle.GetTravel(0.57),
		C.AssistLandingStuds,
		tostring(C.StartupDashDistance),
		C.StartupDashDistance,
		C.Distance
	))
	local oid = liveOwnerId()
	local own = oid == LocalPlayer.UserId
	local player, croot = enemyCarrier(oid)
	add(string.format(
		"owner=%s own=%s enemy=%s enemyPos=%s us=%s ghost=%s",
		tostring(oid),
		tostring(own),
		actorName(player),
		fmtV(typeof(croot) == "Instance" and croot.Position or nil),
		fmtV(LocalPlayer.Character and ActorTargeting.GetActorRoot(LocalPlayer) and ActorTargeting.GetActorRoot(LocalPlayer).Position),
		fmtV(ghostPos)
	))
	add("state " .. Mark.stateLine())
	add(string.format(
		"why t=%s d=%s sliding=%s dribbling=%s slideAim=%s moveCmd=%s",
		tackleWhy,
		dribbleWhy,
		tostring(ClientSlide.IsSlideTackling()),
		tostring(ClientDodge.IsDribbling()),
		fmtV(slideAim),
		fmtV(LocalPlayer.Character and origGetMove(LocalPlayer.Character) or nil)
	))
	if predict then
		add(string.format(
			"predict dist=%.2f eta=%.3f catch=%s fire=%s samples=%s inst=%.2f recent=%.2f mean=%.2f spd=%.2f accel=%s hit=%s aim=%s behind=%s track=%s",
			predict.dist or -1,
			predict.eta or -1,
			tostring(predict.catch),
			tostring(predict.fire),
			tostring(predict.samples),
			predict.instSpd or -1,
			predict.recentSpd or -1,
			predict.meanSpd or -1,
			predict.spd or -1,
			fmtV(predict.accel),
			fmtV(predict.hit),
			fmtV(predict.aim),
			tostring(predict.behind),
			tostring(predict.track)
		))
	else
		add("predict=nil")
	end
	if dribbleDanger then
		add(string.format(
			"dribble dist=%.2f fire=%s close=%s elapsed=%s ang=%s heading=%s hitP=%s",
			dribbleDanger.dist or -1,
			tostring(dribbleDanger.fire),
			tostring((dribbleDanger.dist or 99) <= CFG.DribbleClose),
			tostring(dribbleDanger.elapsed),
			tostring(dribbleDanger.ang),
			fmtV(dribbleDanger.heading),
			fmtV(dribbleDanger.hitP)
		))
	else
		add("dribbleDanger=nil")
	end
	add(string.format("cd tackle=%.2f dribble=%.2f wire=%d pending=%d", cdLeft(lastTackleAt, tackleEnforced), cdLeft(lastDodgeAt, dodgeEnforced), Wire.n, #Log.pending))
	add(string.format(
		"shot why=%s dist=%s curve=%s spin=%s aim=%s vel=%s vdir=%s org=%s from=%s point=%s lob=%s h=%s gap=%s ang=%s side=%s mouth=%s pool=%s band=%s lock=%s hold=%s",
		tostring(Shoot.why),
		Shoot.dist and string.format("%.1f", Shoot.dist) or "-",
		Shoot.curve and string.format("%.2f", Shoot.curve) or "-",
		fmtV(Shoot.spin),
		fmtV(Shoot.aim and Shoot.aim.Direction),
		fmtV(Shoot.launch),
		Shoot.launch and fmtV(Shoot.launch.Unit) or "-",
		fmtV(Shoot.aim and Shoot.aim.Origin),
		fmtV(Shoot.sampleFrom),
		fmtV(Shoot.point),
		tostring(Shoot.lob == true),
		Shoot.hFrac and string.format("%.2f", Shoot.hFrac) or "-",
		Shoot.gap and string.format("%.1f", Shoot.gap) or "-",
		Shoot.ang and string.format("%.1f", Shoot.ang) or "-",
		Shoot.hitSide ~= nil and string.format("%.1f", Shoot.hitSide) or "-",
		Shoot.mouth and string.format("%.1f", Shoot.mouth) or "-",
		tostring(Shoot.poolN or "-"),
		tostring(Shoot.band or "-"),
		tostring(Shoot.locked == true),
		tostring(Shoot.hold == true)
	))
	-- the session log is kept: the snapshot goes to its END (the old dump rewrote the whole file with the ~500-line ring
	-- and wiped the session the user wanted to show). The ring is only written when there is no session log yet.
	if Log.started and isfile(Log.file) then
		Log.flush()
		Log.append(Log.file, "-- DUMP\n" .. table.concat(lines, "\n") .. "\n-- END DUMP\n")
		return
	end
	add("-- ring")
	if Log.n < Log.N then
		for i = 1, Log.n do
			add(Log.ring[i])
		end
	else
		for i = 0, Log.N - 1 do
			add(Log.ring[(Log.head + i - 1) % Log.N + 1])
		end
	end
	Log.wbuf, Log.wn = {}, 0
	writefile(Log.dir .. "/Dump.txt", table.concat(lines, "\n") .. "\n")
	Log.started = true
end

Mark.holdJump = function()
	Mark.walk = Mark.walk or require(Client.Gameplay.Player.Movement)
	if not Mark.jumpHooked then
		Mark.jumpHooked = true
		local oldBlock = Mark.walk.SetJumpStateBlocked
		local oldMin = Mark.walk.SetMinimum
		Mark.walk.SetJumpStateBlocked = function(name, on)
			if Mark.aerial and name == "BallCarrier" then
				return oldBlock(name, false)
			end
			return oldBlock(name, on)
		end
		Mark.walk.SetMinimum = function(name, values)
			if Mark.aerial and name == "BallCarrier" then
				return oldMin(name, nil)
			end
			return oldMin(name, values)
		end
	end
	Mark.walk.SetJumpStateBlocked("BallCarrier", false)
	Mark.walk.SetMinimum("BallCarrier", nil)
end

Mark.endJump = function()
	if Mark.walk and Mark.walk.ReleaseJump then
		Mark.walk.ReleaseJump()
	end
end

Mark.doJump = function(why)
	local character = LocalPlayer.Character
	local hum = character and character:FindFirstChildOfClass("Humanoid")
	if not (character and hum) then
		return false
	end
	if not CharacterControllers.IsLanded(character, hum) then
		if why == "L" or (why == "counter" and os.clock() - (Mark.jumpFailAt or 0) > 0.6) then
			Mark.jumpFailAt = os.clock()
			logFile("jump", "no", "air", why)
		end
		return false
	end
	if os.clock() - (Mark.agentJump or 0) < 0.15 then
		if why == "L" then
			logFile("jump", "cd", why)
		end
		return false
	end
	Mark.holdJump()
	Mark.walk = Mark.walk or require(Client.Gameplay.Player.Movement)
	if Mark.walk.ReleaseJump then
		Mark.walk.ReleaseJump()
	end
	-- Movement.Jump calls the jump-started handler = Sprint.spendJumpStamina, which returns false (no jump, no error) when stamina
	-- is short and no unlimited-stamina source is set (the "AutoBlock sometimes does not jump"); not while a flag guard runs
	Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
	local calm = os.clock() < (Mark.sprintFlagUntil or 0)
	if not calm then
		Mark.sprint.SetUnlimitedStamina("AgentJump", true)
	end
	local ok = Mark.walk.Jump()
	task.delay(0.4, function()
		Mark.sprint.SetUnlimitedStamina("AgentJump", false)
	end)
	if not ok and Mark.walk.SetJumpStateBlocked then
		local blocks = Mark.jumpBlocks and Mark.jumpBlocks()
		if type(blocks) == "table" and blocks.HeldJump and not blocks.Server and not blocks.Ragdoll then
			Mark.walk.SetJumpStateBlocked("HeldJump", false)
			ok = Mark.walk.Jump()
		end
	end
	if not ok then
		if why == "L" or os.clock() - (Mark.jumpFailAt or 0) > 0.6 then
			Mark.jumpFailAt = os.clock()
			local names = {}
			local blocks = Mark.jumpBlocks and Mark.jumpBlocks()
			if type(blocks) == "table" then
				for k, v in blocks do
					if v then
						names[#names + 1] = tostring(k)
					end
				end
			end
			logFile("jump", "fail", why or "?", #names > 0 and table.concat(names, ",") or "no-block", string.format("jh %.1f", hum.JumpHeight or -1))
		end
		return false
	end
	Mark.agentJump = os.clock()
	Mark.jumpHoldUntil = os.clock() + 0.18
	logFile("jump", "ok", why or "block")
	return true
end

Mark.models = function()
	local id = Mark.logicId
	local c = Mark.modelCache
	if c and c.id == id then
		return c.list
	end
	local list = Actors.GetAllCharacterModels()
	Mark.modelCache = { id = id, list = list }
	return list
end

-- World snapshot for a section: one line with every player (team, role, position relative to OUR mouth: x = across, z =
-- out of the goal) and the ball. This is the detail positioning bugs need ("where were the mates when it chose that").
Mark.snap = function(section, label, extra)
	local now = os.clock()
	Mark.snapAt = Mark.snapAt or {}
	if now - (Mark.snapAt[section] or 0) < 0.5 then
		return
	end
	Mark.snapAt[section] = now
	local g = Mark.defendGoal()
	local lb, rb, nrm
	if g then
		local a, _, b, _, _, c = goalMouthCorners(g)
		lb, rb, nrm = a, b, c
	end
	local n = nrm and unitOrNil(flat(nrm))
	local side = lb and rb and unitOrNil(flat(rb - lb))
	local M = lb and (lb + rb) * 0.5
	local function rel(p)
		if not (M and n and side) then
			return string.format("%.0f,%.0f", p.X, p.Z)
		end
		local d = flat(p - M)
		return string.format("%.0f,%.0f", d:Dot(side), d:Dot(n))
	end
	local parts = {}
	local me = ActorTargeting.GetActorRoot(LocalPlayer)
	if me then
		parts[#parts + 1] = "ME " .. rel(me.Position)
	end
	for _, model in Mark.models() do
		local a = Actors.GetFromCharacter(model)
		local r = a and a ~= LocalPlayer and ActorTargeting.GetActorRoot(a)
		if r then
			local v = flat(CharacterMotion.GetVelocity(model) or Vector3.zero) -- (another player's AssemblyLinearVelocity is 0)
			parts[#parts + 1] = string.format("%s%s %s %s v%.0f", sameTeam(a) and "M:" or "F:", isGoalkeeper(a) and "GK" or "", actorName(a):sub(1, 10), rel(r.Position), v.Magnitude)
		end
	end
	local bp = Renderer.GetPosition()
	if bp then
		parts[#parts + 1] = "BALL " .. rel(bp) .. string.format(" h%.0f own %s", bp.Y - (me and me.Position.Y or 0), tostring(liveOwnerId()))
	end
	logFile(section:lower() .. " snap", label or "-", "(x across mouth, z out of it)", table.concat(parts, " | "), extra or "")
end

Mark.defendGoal = function()
	local c = Mark.defGoal
	if c and os.clock() - c.at < 0.5 and (c.g == nil or (c.g and c.g.Parent)) then
		return c.g
	end
	local ours = teamKey(ActorTeams.GetActorTeamName(LocalPlayer))
	local map = Workspace:FindFirstChild("Map")
	local data = map and map:FindFirstChild("Data")
	local folder = data and ours and data:FindFirstChild(ours)
	local g = folder and folder:FindFirstChild("Goal")
	if g and g:IsA("BasePart") then
		Mark.defGoal = { at = os.clock(), g = g }
		return g
	end
	Mark.defGoal = { at = os.clock(), g = nil }
	return nil
end

-- Enemy outfield carrier pose for AutoBlock: displayed CharacterMotion pose, same source as the tackle solver.
Mark.blockTarget = function()
	local oid = liveOwnerId()
	if type(oid) ~= "number" or oid == 0 then
		return nil
	end
	local carrier, cr = enemyCarrier(oid)
	if not carrier then
		return nil
	end
	local ch = Actors.GetCharacter(carrier)
	local p, v = Mark.carrierPose(cr, ch)
	return carrier, cr, ch, p, Mark.trendVel(ch, v)
end

-- TREND velocity for the long predictions (AutoBlock spot, kick helper, Pass Assist receivers). A man weaving left /
-- right has an instantaneous velocity that swings +-45 deg every few tenths of a second: extrapolating it 0.5 s put the
-- spot on whichever side he zigged to last (the "he turned" read on every zig). Over the last TrendWindow s: mean
-- velocity vs mean speed. Straight (ratio ~1) -> his velocity as it is; weaving / reversing (ratio drops) -> the mean,
-- i.e. where the zig-zag actually goes. A real stop stays a stop (speeds drop together, the ratio stays 1).
Mark.trendVel = function(model, V)
	if CFG.TrendVel == false or not model then
		return V
	end
	Mark.trend = Mark.trend or setmetatable({}, { __mode = "k" })
	local now = os.clock()
	local h = Mark.trend[model]
	if not h or now - h.last > 0.3 then
		h = { list = {}, last = now - 1 }
		Mark.trend[model] = h
	end
	local list = h.list
	if now - h.last >= 0.03 then
		list[#list + 1] = { t = now, v = V }
		h.last = now
	end
	while #list > 1 and now - list[1].t > (CFG.TrendWindow or 0.7) do
		table.remove(list, 1)
	end
	if #list < 4 then
		return V
	end
	local sx, sz, sm = 0, 0, 0
	for _, e in list do
		sx += e.v.X
		sz += e.v.Z
		sm += e.v.Magnitude
	end
	local n = #list
	local mean = Vector3.new(sx / n, 0, sz / n)
	local avgM = sm / n
	if avgM < 3 then
		return V
	end
	local straight = math.clamp(1 - (1 - mean.Magnitude / avgM) * 3, 0, 1)
	return mean + (V - mean) * straight
end

-- Kick hitbox reach ahead of the aimed root: HitboxSettings.Kick CFrameOffset Z -1.5, Size Z 7 -> 5 studs.
Mark.kickReach = function()
	local k = HitboxSettings.Kick
	return -k.CFrameOffset.Z + k.Size.Z * 0.5
end

-- KICK HELPER (its own function, CFG.KickHelper): while the PLAYER charges a kick without the ball, the aim ray (Reticle
-- override) and the body turn to the enemy carrier, led to where he will be at the release. The non-owner kick hitbox is
-- oriented by the charge aim ray (Shoot release -> AimFacing.GetAimedRoot), not by the body. Independent of AutoBlock; the
-- scripted AutoKick sets its own aim and is skipped here.
Mark.kickHelper = function(root)
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
	local aim = nil
	if CFG.KickHelper ~= false and charging and not Mark.ak and liveOwnerId() ~= LocalPlayer.UserId then
		local carrier, _, chE, p, v = Mark.blockTarget()
		if carrier and flat(p - root.Position).Magnitude <= (CFG.KickHelperRange or 42) then
			local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
			local dly = chE and math.clamp(CharacterMotion.GetDisplayDelaySeconds(chE) or 0, 0, 0.25) or 0
			local minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2
			local at = p + flat(v) * (dly + ping * 0.5 + minRel)
			aim = unitOrNil(flat(at - root.Position))
		end
	end
	if aim then
		if not Mark.blockAim then
			logFile("kick helper", "aim", fmtV(aim))
		end
		Mark.chargeFace = aim
		Mark.blockAim = aim
		TurnControl.LockAutoRotate("AimCharge", aim)
	elseif Mark.blockAim then
		Mark.chargeFace = nil
		Mark.blockAim = nil
		TurnControl.ReleaseAutoRotate("AimCharge")
	end
end


-- ===== CounterJump v2: AIR DUEL ======================================================================================
-- The old CounterJump jumped on an edge ("he left the ground" / "flick: detach - rise"), rolled dice for a slide or a kick
-- (CounterComboChance / CounterKickChance) and stood still. Now one receding-horizon planner, every tick, against the
-- enemy carrier near us who is up in the air (bicycle kick, jump with the ball, a juggle):
--   HIM: one path. A plain jump = the ballistic arc (vy0 = sqrt(2 g JumpHeight) from the first frame, the measured vy
--        after); a BICYCLE = a hover (BicycleKick.StartHover: frozen where the decaying LinearVelocity stops him, until
--        his release); a launcher (shotgun, bazooka, grapple, jetpack) = unknown arc, waits.
--   US:  run at the contact (current velocity ramping to run speed), jump at td (vJ = sqrt(2 g JumpHeight)), then
--        SLIDE from the air - press at tp, box live [HitboxDelay, +HitboxSeconds], travel = dumpTravel * mult - or
--        KICK from the air - press at tp, release at tp + minimum charge, HitboxSettings.Kick along the aim.
--   A candidate counts when his path is in the box on >= 2 samples (slide) / at the release (kick), before his own
--   release when he charges. The earliest contact wins; slide before kick on a tie (a slide strips the ball).
-- Execution: td ahead -> RUN to the take-off (agent mode "duel"); td now -> jump; airborne and tp now -> press. A flick
-- wind-up: slide him before the detach when it lands in time; the lob itself is AutoBall's (Mark.tickBall plans the flick
-- path with the run / jump / slide it needs). No dice, no fixed delays.
Mark.duelSolve = function(o)
	local DT = 0.025
	-- one path: his ballistic arc (or the bicycle hover point). The old "share of a fan of futures" (CounterConf) only
	-- threw contacts away - a man in the air has no ground to cut on, the arc IS where he goes.
	local main = o.path
	local g, vJ = o.g, o.vJ
	local ramp = math.max(CFG.BallRamp or 0.2, 0.05)
	local box = HitboxSettings.SlideTackle
	local mid = -box.CFrameOffset.Z
	local hx, hz = box.Size.X * 0.5 + 0.2, box.Size.Z * 0.5 + 0.2
	local hLo = box.CFrameOffset.Y - box.Size.Y * 0.5 - 0.5
	local hHi = box.CFrameOffset.Y + box.Size.Y * 0.5 + 0.5
	local t0, t1 = C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds
	local function at(pts, t)
		return pts[math.clamp(math.floor(t / DT + 0.5) + 1, 1, #pts)]
	end
	-- our root height t seconds from now for a jump at td (nil = already in the air: our own arc)
	local function yUs(t, td)
		if td == "ground" then
			return o.floor
		elseif td == nil then
			return math.max(o.O.Y + o.vy * t - 0.5 * g * t * t, o.floor)
		end
		local x = t - td
		if x <= 0 then
			return o.floor
		end
		return o.floor + math.max(vJ * x - 0.5 * g * x * x, 0)
	end
	-- distance we cover toward u in t seconds (v0 projected, ramp to spd)
	local function run(u, t)
		local v0 = math.clamp(o.v0:Dot(u), 0, o.spd)
		if t <= ramp then
			return v0 * t + (o.spd - v0) * t * t / (2 * ramp)
		end
		return v0 * ramp + (o.spd - v0) * ramp * 0.5 + o.spd * (t - ramp)
	end
	-- "ground" first: a contact the ground slide / kick already makes needs no jump (ties keep the first = no jump)
	local tds = o.landed and (o.tds or { "ground", 0, 0.05, 0.1, 0.15, 0.2, 0.3, 0.4 }) or { false }
	local H = o.horizon or 1.25 -- latest contact considered (s)
	local span = o.span or 0.42 -- press window after the take-off (the whole horizon for "ground" / already airborne when set)
	local rcvG, rcvA = HitboxSettings.Receive, HitboxSettings.AirReceive
	local best = nil
	local function consider(c)
		if o.deadline and c.T > o.deadline then
			return -- he releases his strike first
		end
		if not best or c.T < best.T - 1e-3 or (math.abs(c.T - best.T) <= 1e-3 and c.kind == "slide" and best.kind ~= "slide") then
			best = c
		end
	end
	for _, tdv in tds do
		local td = tdv ~= false and tdv or nil
		local tpS = (type(td) == "number") and (td + 0.03) or 0
		local tp = tpS
		local tpE = tpS + ((type(td) == "number" or not o.span) and 0.42 or span)
		if o.bodyOk and type(td) == "number" then
			tpE = math.max(tpE, td + 0.6) -- the body rides the whole jump (apex 0.37 s, back down ~0.75 s)
		end
		while tp <= math.min(tpE, H) do
			-- SLIDE
			if o.slideOk then
				local tauM = (t0 + t1) * 0.5
				local E = at(main, tp + tauM)
				local u = unitOrNil(flat(E - o.O))
				if u and tp + t1 <= H then
					local dE = flat(E - o.O).Magnitude
					local travelM = math.max(Mark.dumpTravel(tauM), 1)
					local close = math.max(dE - mid - travelM * o.mLo, 0)
					local Q = o.O + u * math.min(run(u, tp), close)
					local m = (flat(E - Q).Magnitude - mid) / travelM
					-- Airborne slide at range: the slide keeps only the X/Z rig, the body falls on gravity while the dash runs (the
					-- box is 5 studs high around the root), so from the air a long slide is a guess about where we are 0.4 s on
					-- (user: at ~16 st tackle INTO him while he is on the ground, or come closer). In the air only a short slide.
					local airSlide = td ~= "ground"
					local farSlide = airSlide and flat(E - Q).Magnitude > (CFG.CounterAirSlide or 11) and E.Y > o.floor + 2.5
					if not farSlide and m >= o.mLo * 0.85 and m <= o.mHi * 1.1 then
						m = math.clamp(m, o.mLo, o.mHi)
						local hits, tHit = 0, nil
						for k = 0, 6 do
							local tau = t0 + (t1 - t0) * k / 6
							local Hp = at(main, tp + tau)
							local rel = flat(Hp - (Q + u * (Mark.dumpTravel(tau) * m + mid)))
							local dy = Hp.Y - yUs(tp + tau, td)
							if math.abs(rel:Dot(u)) <= hz and math.abs(rel.X * u.Z - rel.Z * u.X) <= hx and dy >= hLo and dy <= hHi then
								hits += 1
								tHit = tHit or (tp + tau)
							end
						end
						if hits >= 2 then
							consider({ kind = "slide", td = td, tp = tp, T = tHit or (tp + t0), aim = u, mult = m, hits = hits, E = E, Q = Q })
						end
					end
				end
			end
			-- KICK (released at the minimum charge: both in the air, the first legal moment)
			if o.kickOk and (not o.kickUntil or tp + o.minRel <= o.kickUntil) then
				local R = tp + o.minRel
				if R <= H then
					local E = at(main, R)
					local u = unitOrNil(flat(E - o.O))
					if u then
						-- run until the press, then the charge walk; stop 2.5 short of him (the box reaches 5 ahead)
						local dE = flat(E - o.O).Magnitude
						local s = math.min(run(u, tp) + o.chSpd * o.minRel, math.max(dE - 2.5, 0))
						local Q = o.O + u * s
						local aimed = AimFacing.GetAimedRoot({ Position = Vector3.new(Q.X, yUs(R, td), Q.Z) }, u)
						if HitboxSettings.ContainsPoint(aimed, HitboxSettings.Kick, at(main, R)) then
							consider({ kind = "kick", td = td, tp = tp, T = R, aim = u, E = E, Q = Q })
						end
					end
				end
			end
			-- BODY: our receive box on the ball at tp (Receive on the ground, AirReceive in the air - HitboxSettings)
			if o.bodyOk then
				local B = at(main, tp)
				local u = unitOrNil(flat(B - o.O))
				local dB = flat(B - o.O).Magnitude
				local air = (td == nil) or (type(td) == "number" and tp > td)
				local rb = air and rcvA or rcvG
				local dy = B.Y - yUs(tp, td)
				local lo, hi = rb.CFrameOffset.Y - rb.Size.Y * 0.5, rb.CFrameOffset.Y + rb.Size.Y * 0.5
				if dy >= lo and dy <= hi and dB - rb.Size.X * 0.5 <= (u and run(u, tp) or 0) then
					consider({ kind = "body", td = td, tp = tp, T = tp, aim = u, E = B, Q = u and (o.O + u * math.max(dB - rb.Size.X * 0.5 + 0.5, 0)) or o.O })
				end
			end
			if best and best.T <= tp then
				break
			end
			tp += 0.04
		end
	end
	return best
end

-- flick wind-up: slide him now if the slide lands before the ball detaches (then the flick never happens)
Mark.duelEnd = function(why)
	if Mark.duel then
		logFile("duel", "end", why, Mark.duel.name or "-")
	end
	Mark.duel = nil
	Mark.moveStop("duel")
end

-- ===== AIR DUEL / LOB overlay ========================================================================================
-- STRIKE. An air duel is two arcs that must meet: his (the airborne man / the lob) and ours (run to the take-off, the
-- jump). Lightning discharges fall from his arc onto the grass and ricochet (Mark.duelBolts): with a
-- plan they strike our take-off spot and bounce into the contact knot, so the bolt itself draws who meets whom where.
--   steel = SEEN: his rail only (no contact we can make);
--   mint  = PLAN: our rail, the ties, the take-off squircle, the contact knot (a small 3D cross) and its ripple;
--   white = committed (we jumped / pressed).
-- Only the future is drawn: the rails start at now.
-- One renderer: Mark.duelArt(seg, v, gy, t). Mark.duelSee feeds it from Mark.tickCounterJump and Mark.tickLob.
Mark.duelSee = function(key, P, o)
	local v = o or {}
	v.at, v.key, v.P = os.clock(), key, P
	local old = Mark.duelViz
	if old and old.liveUntil and v.at < old.liveUntil then
		v.liveUntil = old.liveUntil
	end
	Mark.duelViz = v
end

-- Lightning bolt between two world points (after HUSH Visual.boltTracer): a jagged line whose zigzag is smooth noise
-- re-rolled 24 times a second, envelope sin^0.6 (pinned at both ends), a wide soft glow under a paper-hot core.
-- grow 0..1 draws the bolt from A toward B (the strike runs down). Returns nothing; lines only (segPool).
Mark.hn = function(i, k, s)
	local x = math.sin(i * 12.9898 + k * 78.233 + s * 37.719) * 43758.5453
	return (x - math.floor(x)) * 2 - 1
end
Mark.boltLine = function(seg, A, B, t, seed, col, a, w, grow)
	local D = B - A
	local L = D.Magnitude
	if L < 0.4 or a <= 0.02 then
		return
	end
	local look = Mark.frameLook or Workspace.CurrentCamera.CFrame.LookVector
	local side = D:Cross(look)
	side = side.Magnitude > 1e-3 and side.Unit or Vector3.new(1, 0, 0)
	local up2 = (D / L):Cross(side)
	local n = math.clamp(math.floor(L / 2.2), 5, 12)
	local rate = t * 24 + seed * 3.1
	local blk = math.floor(rate)
	local f = rate - blk
	local e = f * f * (3 - 2 * f)
	local hn = Mark.hn
	local amp = math.clamp(L * 0.07, 0.3, 1.5)
	local hot = Color3.new(1, 1, 1):Lerp(col, 0.3)
	local prev = A
	local last = math.max(1, math.floor(n * (grow or 1) + 0.5))
	for i = 1, last do
		local u = i / n
		local env = i == n and 0 or math.sin(math.pi * u) ^ 0.6
		local a1, a2 = hn(i, blk, seed), hn(i, blk, seed + 4.1)
		local n1 = a1 + (hn(i, blk + 1, seed) - a1) * e
		local n2 = a2 + (hn(i, blk + 1, seed + 4.1) - a2) * e
		local p = A + D * u + side * (amp * env * n1) + up2 * (amp * 0.6 * env * n2)
		seg(prev, p, col, 0.2 * a, w + 4, 39)
		seg(prev, p, hot, a, w, 43)
		prev = p
	end
	-- one fork off the middle, re-rolled with the body
	if last == n and L > 5 and math.abs(hn(7, blk, seed)) > 0.3 then
		local m = A + D * (0.35 + 0.3 * math.abs(hn(3, blk, seed)))
		local fd = (D / L) * 0.5 + side * hn(5, blk, seed) + up2 * hn(6, blk, seed) * 0.5
		local fl = math.clamp(L * 0.22, 1.2, 3.5)
		local q = m + (fd.Magnitude > 1e-3 and fd.Unit or side) * fl
		seg(m, q, hot, 0.6 * a, math.max(w - 0.6, 1), 42)
	end
end

-- Discharges of the duel overlay: a strike is born every `gap` s (seen 0.5, plan 0.3, committed 0.16), lives 0.3 s:
-- the first leg runs from his arc to the grass in 0.05 s, the second (the ricochet) leaves the impact 0.05 s later,
-- a 4-ray spark at the impact, then both thin and fade with the rest of the life. pick(rnd) -> S, I, E.
Mark.duelBolts = function(seg, t, key, col, gy, pick, st)
	if not st then
		st = Mark.duelBoltSt or { list = {}, nextAt = 0, n = 0 }
		Mark.duelBoltSt = st
	end
	local gap = key == "live" and 0.16 or (key == "armed" and 0.3 or 0.5)
	if t >= st.nextAt then
		st.nextAt = math.max(st.nextAt + gap, t)
		st.n += 1
		local rnd = (math.sin(st.n * 91.7) * 43758.5453) % 1
		local S, I, E = pick(rnd)
		if S and I and E then
			table.insert(st.list, { born = t, seed = st.n % 97, S = S, I = I, E = E })
			if #st.list > 3 then
				table.remove(st.list, 1)
			end
		end
	end
	local c = key == "live" and Color3.new(1, 1, 1):Lerp(col, 0.15) or col
	for k = #st.list, 1, -1 do
		local b = st.list[k]
		local age = t - b.born
		if age > 0.3 or age < 0 then
			table.remove(st.list, k)
		else
			local fade = 1 - math.clamp((age - 0.1) / 0.2, 0, 1)
			local w = 1.2 + 1.4 * fade
			Mark.boltLine(seg, b.S, b.I, t, b.seed, c, fade, w, math.clamp(age / 0.05, 0, 1))
			if age > 0.05 then
				Mark.boltLine(seg, b.I, b.E, t, b.seed + 13, c, fade * 0.9, w * 0.85, math.clamp((age - 0.05) / 0.05, 0, 1))
				local sp = 0.6 + 1.6 * math.clamp((age - 0.05) / 0.12, 0, 1)
				for q = 0, 3 do
					local ang = b.seed + q * 1.5708
					local dir = Vector3.new(math.cos(ang), 0.35, math.sin(ang))
					seg(b.I, b.I + dir * sp, Color3.new(1, 1, 1), 0.8 * fade, 1.4, 44)
				end
			end
		end
	end
end

Mark.duelArt = function(seg, v, gy, t)
	local key = (v.liveUntil and t < v.liveUntil) and "live" or v.key
	local pal = Mark.defPalette[key]
	local col = pal[1]
	local pl = v.plan
	local el = t - v.at
	local T = pl and math.max(pl.T - el, 0) or 1.0
	-- his position tau seconds from now (the path is sampled every 0.025 s from v.pathAt)
	local path = v.path
	local function hisAt(tau)
		if not path then
			return nil
		end
		local x = (t - (v.pathAt or v.at) + tau) / 0.025 + 1
		local i = math.clamp(math.floor(x), 1, #path)
		local j = math.min(i + 1, #path)
		local p = path[i]:Lerp(path[j], math.clamp(x - i, 0, 1))
		return (p.Y - gy < 200) and p or nil -- (a lob path is lifted out of reach before its no-touch moment)
	end
	-- LIGHTNING: discharges fall from his arc, hit the grass and ricochet. Seen: they skim on along his heading. Plan: they
	-- strike our take-off spot and bounce up into the contact point (where we meet him). Committed: white, twice as often.
	local P = v.P
	local ahead = nil
	if not pl then
		local h1 = hisAt(0.3)
		ahead = h1 and unitOrNil(flat(h1 - P)) or nil
	end
	Mark.duelBolts(seg, t, key, col, gy, function(rnd)
		local S = hisAt(rnd * (pl and math.min(T * 0.7, 0.6) or 0.6)) or P
		if not pl then
			local I = Vector3.new(S.X, gy + 0.05, S.Z) + Vector3.new(rnd - 0.5, 0, (rnd * 7.3) % 1 - 0.5) * 3
			local fw = ahead or unitOrNil(flat(I - (v.us or I))) or Vector3.new(0, 0, 1)
			return S, I, I + fw * (4 + 3 * rnd) + Vector3.new(0, 1.2 + rnd, 0)
		end
		local spot = (v.landed and type(pl.td) == "number") and pl.Q or pl.E
		local I = Vector3.new(spot.X, gy + 0.05, spot.Z) + Vector3.new(rnd - 0.5, 0, (rnd * 5.1) % 1 - 0.5) * 1.6
		return S, I, pl.E
	end, v.boltSt)
	if not pl then
		Mark.kickRipple(seg, Vector3.new(P.X, gy, P.Z), 2.2, pal, Mark.rippleStep("duel-foot", Mark.rippleRates[key]), t, 2)
		return
	end
	local Eg = Vector3.new(pl.E.X, gy, pl.E.Z)
	Mark.kickRipple(seg, Eg, 2.2, pal, Mark.rippleStep("duel-foot", Mark.rippleRates[key]), t, 2)
	-- the take-off: a still squircle (n = 4) where we leave the grass, tighter as the take-off comes
	if v.landed and type(pl.td) == "number" then
		local Qg = Vector3.new(pl.Q.X, gy + 0.05, pl.Q.Z)
		local r = 0.9 + 0.8 * math.clamp((pl.td - el) / 0.5, 0, 1)
		local prev = nil
		for s = 0, 16 do
			local a = s / 16 * math.pi * 2
			local c, sn = math.cos(a), math.sin(a)
			local p = Qg + Vector3.new(math.sign(c) * math.sqrt(math.abs(c)), 0, math.sign(sn) * math.sqrt(math.abs(sn))) * r
			if prev then
				seg(prev, p, COL.Ink, 0.4, 3.4, 39)
				seg(prev, p, col, 1, 1.5, 42)
			end
			prev = p
		end
	end
end

Mark.drawDuel = function(gy)
	Mark.duelLines = Mark.duelLines or makeLines(440, 1.4, 41)
	Mark.duelPool = Mark.duelPool or Mark.segPool(Mark.duelLines)
	local v = Mark.duelViz
	local now = os.clock()
	if CFG.DrawDuel ~= false and v and (now - v.at < 0.25 or (v.liveUntil and now < v.liveUntil and now - v.at < 0.7)) then
		Mark.duelArt(Mark.duelPool.seg, v, gy, now)
	end
	Mark.duelPool.finish()
end

-- ===== FLICK LOB CATCH ===============================================================================================
-- An enemy RainbowFlick: the lob is known from the wind-up (Mark.flickShot), during the flight it is the real ball state
-- (or the wind-up solve shifted, while the flicker still "owns" it - SelfDeliveryControlSeconds). The ball is NOT his:
-- a slide box on it takes it, our body on it stops it. One plan per tick with the air-duel solver against the BALL path:
--   SLIDE: run, jump at td (or stay on the ground), press at tp, the SlideTackle box on the ball;
--   BODY : run, jump at td, our receive box (AirReceive in the air) on the ball - after the jump the agent keeps steering
--          at the ball (air control). Chosen when the contact is within LobBodyRange (9 st) of us, else the slide.
-- No touch before the detach + Ownership.LaunchNoTouchSeconds. Sliding the flicker himself is AutoTackle's.
Mark.lobBusy = function()
	return Mark.lobPlan ~= nil and os.clock() - Mark.lobPlan.seen < 0.2
end

Mark.lobEnd = function(why)
	if Mark.lobPlan then
		logFile("lob", "end", why)
		Mark.moveStop("lob")
	end
	Mark.lobPlan = nil
	Mark.lobMemo = nil
end

-- the lob as a 0.025 s path from now (1.9 s), unreachable (lifted) before the no-touch moment
Mark.lobPath = function(root, lb)
	local S, Tm = nil, nil
	local own = liveOwnerId()
	local _, _, bs, bt, live = Mark.ballPath(root)
	local src = "state"
	if live and bs and #bs >= 2 and (type(own) ~= "number" or own == 0 or own == lb.uid) and os.clock() > (lb.detachAt or 0) then
		S, Tm = bs, bt
	elseif Mark.enemyWind(lb.actor) then
		local fs, why = Mark.flickShot(lb.actor)
		if not fs then
			return nil, why
		end
		local el = os.clock() - fs.at
		S, Tm = {}, {}
		-- before the detach the ball is still CARRIED at his feet (he owns it): a slide / kick box on it there is a plain
		-- steal. The old path started at the launch point, so the whole wind-up was untouchable.
		local ballNow = Renderer.GetPosition()
		if ballNow and fs.ts[1] - el > 0.03 then
			S[1], Tm[1] = ballNow, 0
		end
		for i = 1, #fs.pts do
			S[#S + 1], Tm[#Tm + 1] = fs.pts[i], fs.ts[i] - el
		end
		src = "wind-up"
	elseif lb.fs then
		local el = os.clock() - lb.fs.at
		S, Tm = {}, {}
		for i = 1, #lb.fs.pts do
			if lb.fs.ts[i] - el >= -0.05 then
				S[#S + 1], Tm[#Tm + 1] = lb.fs.pts[i], lb.fs.ts[i] - el
			end
		end
		src = "flight"
	end
	if not S or #S < 2 then
		return nil, "no path"
	end
	local detachIn = (lb.detachAt or os.clock()) - os.clock()
	local noTouch = detachIn + 0.25
	local n, hint = #S, 2
	local pts = table.create(77)
	for k = 0, 76 do
		local t = k * 0.025
		local p
		if t <= Tm[1] then
			p = S[1]
		elseif t >= Tm[n] then
			p = S[n]
		else
			while hint < n and Tm[hint] < t do
				hint += 1
			end
			local a, b = Tm[hint - 1], Tm[hint]
			p = S[hint - 1]:Lerp(S[hint], b > a and (t - a) / (b - a) or 0)
		end
		pts[k + 1] = (t >= detachIn and t < noTouch) and (p + Vector3.new(0, 500, 0)) or p
	end
	return pts, src, noTouch
end

Mark.tickLob = function(character, root)
	local lb = Mark.lob
	local now = os.clock()
	local on = lb ~= nil and now < lb.untilT and CFG.BallFlick ~= false and (CFG.AutoBall or CFG.CounterJump)
		and not MatchSettings.IsGoalkeeperCharacter(character)
	if not on then
		if Mark.lobPlan then
			Mark.lobEnd("over")
		end
		if lb and now < lb.untilT and not lb.offLogged then
			lb.offLogged = true
			logFile("lob", "off", CFG.BallFlick == false and "Catch Flicks off" or (not (CFG.AutoBall or CFG.CounterJump) and "AutoBall and CounterJump off" or "keeper"))
		end
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	local own = liveOwnerId()
	if Mark.weOwn() then
		Mark.lobEnd("ours")
		Mark.lob = nil
		return
	elseif type(own) == "number" and own ~= 0 and own ~= lb.uid then
		Mark.lobEnd("taken")
		Mark.lob = nil
		return
	elseif not hum or Ragdoll.IsActorRagdolled(LocalPlayer) or ClientDodge.IsDribbling() or Mark.slideBody() then
		return -- our slide is out / we are down: nothing to plan this tick
	end
	local landed = CharacterControllers.IsLanded(character, hum)
	local g = Workspace.Gravity
	if type(g) ~= "number" or g < 10 then
		g = 196.2
	end
	local lm = Mark.lobMemo
	local plan
	if lm and now - lm.at < 0.05 then
		plan = lm.plan and table.clone(lm.plan)
		if plan then
			local el = now - lm.at
			plan.td = type(plan.td) == "number" and math.max(plan.td - el, 0) or plan.td
			plan.tp = math.max(plan.tp - el, 0)
			plan.T -= el
		end
	else
		local pts, src = Mark.lobPath(root, lb)
		if not pts then
			Mark.lobMemo = { at = now }
			if lb.noPathWhy ~= src then
				lb.noPathWhy = src
				logFile("lob", "no path", actorName(lb.actor), tostring(src))
			end
			return
		end
		local spd, chSpd = Mark.akSpeeds(character)
		spd = math.max(spd, hum.WalkSpeed)
		local mHi = math.max(0.4, CFG.TackleSpeed)
		local slideOk = CFG.AutoTackle and now - lastTackleAt >= tackleEnforced and not ActionLocks.HasTackleBlock(LocalPlayer)
			and not SlideTackle.IsRepeatBlocked(character, false) and not (ChargedKick.IsCharging and ChargedKick.IsCharging())
		local tds = { "ground" }
		for td = 0, 1.2001, 0.05 do
			tds[#tds + 1] = td
		end
		local base = {
			O = root.Position, v0 = flat(root.AssemblyLinearVelocity), spd = spd, chSpd = chSpd, landed = landed,
			vy = root.AssemblyLinearVelocity.Y, floor = Mark.duelFloor or root.Position.Y, g = g,
			vJ = math.sqrt(2 * g * (Mark.jumpH or 7.2)), path = pts, mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6), mHi = mHi,
			minRel = 0.2, horizon = 1.9, tds = tds, span = 1.9, kickOk = false,
		}
		-- KICK on the carried ball: only while it is still at his feet (Mark.akTry models the carrier, not a ball in the air)
		local detachIn = (lb.detachAt or now) - now
		local minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2
		local kickOk = CFG.AutoKick ~= false and detachIn > minRel and not Mark.ak and now - (Mark.akAt or 0) >= (CFG.AutoKickCooldown or 0.5)
			and not (ChargedKick.IsCharging and ChargedKick.IsCharging())
		base.minRel, base.kickUntil = minRel, detachIn
		base.slideOk, base.bodyOk, base.kickOk = slideOk, false, kickOk
		local pS = (slideOk or kickOk) and Mark.duelSolve(base) or nil
		base.slideOk, base.bodyOk, base.kickOk = false, true, false
		local pB = Mark.duelSolve(base)
		local near = pB and flat(pB.E - root.Position).Magnitude <= (CFG.LobBodyRange or 9)
		plan = (near and pB) or pS or pB
		Mark.lobMemo = { at = now, plan = plan, path = pts }
		if plan and (not Mark.lobPlan or Mark.lobPlan.kind ~= plan.kind) then
			logFile("lob", "plan", plan.kind, actorName(lb.actor), "td", type(plan.td) == "number" and string.format("%.2f", plan.td) or tostring(plan.td or "air"), "tp", string.format("%.2f", plan.tp), "T", string.format("%.2f", plan.T), "contact d", string.format("%.1f", flat(plan.E - root.Position).Magnitude), "h", string.format("%.1f", plan.E.Y - root.Position.Y), "path", src, "slide ready", tostring(slideOk and true or false))
		elseif not plan and (not Mark.lobSkipLog or now - Mark.lobSkipLog > 0.4) then
			Mark.lobSkipLog = now
			logFile("lob", "no contact", actorName(lb.actor), "path", src, "ball d", string.format("%.1f", flat(pts[#pts] - root.Position).Magnitude), "slide ready", tostring(slideOk and true or false), "kick ready", tostring(kickOk))
		end
	end
	local ballP = Renderer.GetPosition() or root.Position
	if not plan then
		Mark.duelSee("safe", ballP, Mark.lobMemo and { path = Mark.lobMemo.path, pathAt = Mark.lobMemo.at } or nil)
		if Mark.lobPlan and now - Mark.lobPlan.seen > 0.2 then
			Mark.lobEnd("no contact")
		end
		return
	end
	Mark.duelSee("armed", ballP, {
		plan = plan, path = Mark.lobMemo and Mark.lobMemo.path, pathAt = Mark.lobMemo and Mark.lobMemo.at or now,
		us = root.Position, landed = landed, floorY = Mark.duelFloor, vy = root.AssemblyLinearVelocity.Y, vJ = math.sqrt(2 * g * (Mark.jumpH or 7.2)), g = g,
	})
	Mark.lobPlan = Mark.lobPlan or { at = now }
	Mark.lobPlan.kind, Mark.lobPlan.seen = plan.kind, now
	-- move: on the ground to the take-off / press spot; in the air straight at the contact (air control)
	local mySpd = math.max(Mark.akSpeeds(character), hum.WalkSpeed)
	local cmd, route
	if landed then
		cmd, route = Mark.agentSteer({
			key = "lob", us = root.Position, vUs = flat(root.AssemblyLinearVelocity), center = nil, vC = Vector3.zero,
			target = Vector3.new(plan.Q.X, root.Position.Y, plan.Q.Z), spd = mySpd, ff = Vector3.zero,
		})
		if cmd.Magnitude < 0.2 then
			cmd = unitOrNil(flat(plan.E - root.Position)) or cmd
		end
	else
		cmd = unitOrNil(flat((plan.kind == "body" and plan.E or plan.Q) - root.Position)) or Vector3.zero
		route = { root.Position, Vector3.new(plan.E.X, root.Position.Y, plan.E.Z) }
	end
	Mark.move.look = unitOrNil(flat(plan.E - root.Position))
	Mark.move.pts = route
	Mark.move.born = Mark.move.born or now
	Mark.moveSteer(cmd, "lob")
	if landed and type(plan.td) == "number" then
		if plan.td <= 0.035 and Mark.doJump("lob") then
			Mark.duelViz.liveUntil = now + 0.6
			logFile("lob", "jump", plan.kind, "tp", string.format("%.2f", plan.tp), "T", string.format("%.2f", plan.T))
		end
		return
	end
	if plan.kind == "kick" and plan.tp <= 0.035 then
		local m = Actors.GetCharacter(lb.actor)
		local rr = m and ActorTargeting.GetActorRoot(lb.actor)
		local sent, why = false, "no carrier"
		if rr then
			sent, why = Mark.akTry("flick", m, rr, true)
		end
		logFile("lob", "kick", sent and "sent" or ("refused " .. tostring(why)), "T", string.format("%.2f", plan.T))
		if sent then
			Mark.duelViz.liveUntil = now + 0.6
			Mark.lobMemo = nil
		end
	elseif plan.kind == "slide" and plan.tp <= 0.035 then
		local sent, why = tryTackle(character, root, plan.aim, plan.mult)
		logFile("lob", "slide", sent and "sent" or ("refused " .. tostring(why)), "T", string.format("%.2f", plan.T), "mult", string.format("%.2f", plan.mult or 0), "air", tostring(not landed))
		if sent then
			Mark.duelViz.liveUntil = now + 0.6
			Mark.lobMemo = nil
		end
	end
end

Mark.tickCounterJump = function(character, root)
	do
		local h0 = character:FindFirstChildOfClass("Humanoid")
		if h0 and CharacterControllers.IsLanded(character, h0) then
			Mark.duelFloor = root.Position.Y
		end
	end
	if not CFG.CounterJump or liveOwnerId() == LocalPlayer.UserId or MatchSettings.IsGoalkeeperCharacter(character) then
		if Mark.duel then
			Mark.duelEnd("off")
		end
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	if not hum or Ragdoll.IsActorRagdolled(LocalPlayer) or Mark.slideBody() or ClientDodge.IsDribbling() then
		if Mark.duel then
			Mark.duelEnd("busy")
		end
		return
	end
	local now = os.clock()
	local landed = CharacterControllers.IsLanded(character, hum)
	if landed then
		Mark.duelFloor = root.Position.Y
	end
	if Mark.duel and now - (Mark.duel.seen or Mark.duel.at) > 0.3 then
		Mark.duelEnd("stale") -- no plan refreshed it (he flies a powered / fresh arc): do not keep AutoBlock parked
	end
	-- GRAPPLE first: an enemy pulled at the ball on a hook whose path comes within range. If AutoBall wins the ball race
	-- (Mark.grappleRace, fresh) the ball is the answer; otherwise we meet HIM on his path (his path is exact: homing on the
	-- ball at 75 st/s, then the overshoot) with the same air / ground slide-kick planner.
	local grap = nil
	if Mark.grapples and next(Mark.grapples) then
		for uid, _ in Mark.grapples do
			local a = playerOf(uid)
			local m = a and not sameTeam(a) and Actors.GetCharacter(a)
			local rr = m and ActorTargeting.GetActorRoot(a)
			if rr then
				local pts, tArr = Mark.grapplePath(uid, m, (Mark.carrierPose(rr, m)), root)
				local near = false
				if pts then
					for k = 1, #pts, 4 do
						if flat(pts[k] - root.Position).Magnitude <= (CFG.CounterJumpRange or 24) then
							near = true
							break
						end
					end
				end
				local race = Mark.grappleRace
				local ballWins = race and race.uid == uid and race.win and os.clock() - race.at < 0.3
				if near and ballWins then
					if not Mark.grapSkipLog or now - Mark.grapSkipLog > 0.5 then
						Mark.grapSkipLog = now
						logFile("duel skip", "grapple: AutoBall takes the ball first", actorName(a))
					end
				elseif near then
					grap = { actor = a, model = m, r = rr, pts = pts, tArr = tArr }
					break
				end
			end
		end
	end
	-- the target: the enemy carrier within range (the ball is with him)
	local oid = liveOwnerId()
	local actor = grap and grap.actor or (type(oid) == "number" and playerOf(oid)) or nil
	if not actor or sameTeam(actor) or isGoalkeeper(actor) then
		if Mark.duel then
			Mark.duelEnd("no carrier")
		end
		return
	end
	local model = Actors.GetCharacter(actor)
	local r = ActorTargeting.GetActorRoot(actor)
	local hisHum = model and model:FindFirstChildOfClass("Humanoid")
	if not (model and r and hisHum) or (not grap and flat(r.Position - root.Position).Magnitude > (CFG.CounterJumpRange or 24)) then
		if Mark.duel then
			Mark.duelEnd("range")
		end
		return
	end
	-- a flick wind-up: the slide, if it lands before the detach; the ball after it is AutoBall's
	if CFG.CounterCompetitor and not grap and not Mark.competitorFree(root, r.Position) then
		local myD = flat(r.Position - root.Position).Magnitude
		for _, m2 in Mark.models() do
			local a2 = Actors.GetFromCharacter(m2)
			if a2 and a2 ~= LocalPlayer and sameTeam(a2) and not isGoalkeeper(a2) and not Mark.mateDown(a2, m2) then
				local r2 = ActorTargeting.GetActorRoot(a2)
				local d2 = r2 and flat(r2.Position - r.Position).Magnitude
				if d2 and d2 <= (CFG.CounterCompetitorRadius or 12) and d2 < myD then
					if Mark.duel then
						Mark.duelEnd("competitor")
					end
					return
				end
			end
		end
	end
	if not grap and Mark.isLobber(model) then
		-- his flick: the lob is Mark.tickLob's (jump-slide / take the BALL), a slide at him is AutoTackle's
		if Mark.duel then
			Mark.duelEnd("flick")
		end
		return
	end
	local P, V = Mark.carrierPose(r, model)
	local g = Workspace.Gravity
	if type(g) ~= "number" or g < 10 then
		g = 196.2
	end
	local floor = Mark.duelFloor or root.Position.Y
	local vs = Mark.vertState(model, P, floor, not CharacterControllers.IsLanded(model, hisHum), now, g)
	if not vs.airborne and not grap then
		if Mark.duel then
			Mark.duelEnd("he landed")
		end
		return -- a grounded carrier is AutoTackle / AutoKick / AutoBlock work
	end
	local function skip(why)
		local dmS = Mark.duelMemo
		Mark.duelSee("safe", P, dmS and dmS.model == model and now - dmS.at < 0.1 and { path = dmS.path, pathAt = dmS.at } or nil)
		if not Mark.duelSkipLog or now - Mark.duelSkipLog > 0.4 then
			Mark.duelSkipLog = now
			logFile("duel skip", why, actorName(actor), "d", string.format("%.1f", flat(P - root.Position).Magnitude), "h", string.format("%.1f", P.Y - floor), "vk", vs.kind, "vy", string.format("%.1f", vs.vy))
		end
	end
	-- A fresh take-off (the slope needs 0.1-0.2 s of samples) is where a bicycle / a jump with the ball lives: he kicks
	-- while rising, the old wait for a measured arc lost the whole duel (log: 0 "duel" lines). A plain jump has a known
	-- take-off speed (CharacterControllers JumpHeight -> vy0 = sqrt(2 g H)); only a launcher (shotgun, bazooka, grapple,
	-- jetpack) leaves the arc unknown.
	local vyPlan, hoverP = vs.vy, nil
	local crec = Mark.charges and Mark.charges[actor.UserId]
	local hisCharge = crec and crec.live and now - (crec.seen or 0) < 0.6 and crec.at
	if grap then
		vyPlan = 0 -- the path is the hook's (grap.pts)
	elseif hisCharge then
		-- BICYCLE (dump BicycleKick.StartHover): a charge started in the air freezes him - LinearVelocity = his velocity at
		-- the start * (1 - t / StopSeconds)^2, held up to MaximumHoverSeconds until the release. What is left of the drift
		-- from now: v(now) * (StopSeconds - e) / 3. He was "powered" (ay ~ 0) for vertState: the old code skipped him.
		-- the module is the file-level BicycleKick. It used to be cached in Mark.bike - the slot of OUR bicycle state:
		-- tickBike then read the module as a bicycle with no .at -> "Soccer:19293 arithmetic (sub) on number and nil"
		-- every frame, and Mark.bike ~= nil blocked every later bicycle / feint
		local S = (BicycleKick.Constants and BicycleKick.Constants.StopSeconds) or 0.375
		local e = now - crec.at
		hoverP = P + Vector3.new(V.X, vs.vy, V.Z) * (math.max(S - e, 0) / 3)
	elseif vs.kind == "fresh" then
		local lr = Mark.launchRec and Mark.launchRec[actor.UserId]
		local jr = Mark.jets and Mark.jets[actor.UserId]
		if (lr and now - lr.at < 1.5) or (jr and now - jr.at < 4) then
			skip("launcher take-off")
			return
		end
		vyPlan = math.sqrt(2 * g * (Mark.jumpH or 7.2)) - g * math.max(now - (vs.airAt or now), 0)
	elseif vs.kind ~= "ballistic" then
		skip("powered flight")
		return
	end
	-- his charge in the air (bicycle / volley): the contact must land before his release. Expected at the full charge;
	-- one held past it can go any moment - 0.3 s is a guess, not a dump value.
	local deadline = nil
	if hisCharge then
		local full = (KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds()) or 0.35
		deadline = math.max(crec.at + full - now, 0.3)
	end
	-- solve at ~20 Hz
	local dm = Mark.duelMemo
	local plan
	if dm and dm.model == model and now - dm.at < 0.05 then
		plan = dm.plan
		if plan then
			local el = now - dm.at
			plan = table.clone(plan)
			plan.td = type(plan.td) == "number" and math.max(plan.td - el, 0) or plan.td
			plan.tp = math.max(plan.tp - el, 0)
			plan.T = plan.T - el
		end
	else
		local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local lead = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25) + ping * 0.5
		local goal = Mark.defendGoal()
		local path
		if grap then
			path = grap.pts
		elseif hoverP then
			path = table.create(53, hoverP)
		else
			path = Mark.gkFutures(P, V, vyPlan, true, false, floor, lead, goal and goal.Position or (P + flat(V) * 10), g, false)[1].pts
		end
		local spd, chSpd = Mark.akSpeeds(character)
		if hum.WalkSpeed > spd then
			spd = hum.WalkSpeed
		end
		local mHi = math.max(0.4, CFG.TackleSpeed)
		local tackleReady = CFG.CounterTackle ~= false and CFG.AutoTackle and now - lastTackleAt >= tackleEnforced
			and not ActionLocks.HasTackleBlock(LocalPlayer) and not SlideTackle.IsRepeatBlocked(character, false)
		local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
		plan = Mark.duelSolve({
			O = root.Position, v0 = flat(root.AssemblyLinearVelocity), spd = spd, chSpd = chSpd, landed = landed,
			vy = root.AssemblyLinearVelocity.Y, floor = floor, g = g, vJ = math.sqrt(2 * g * (Mark.jumpH or 7.2)), path = path,
			slideOk = tackleReady and not charging, kickOk = CFG.AutoKick ~= false and not Mark.ak and not charging,
			mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6), mHi = mHi,
			minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2,
			deadline = deadline,
		})
		Mark.duelMemo = { model = model, at = now, plan = plan, path = path }
		if not plan then
			skip((grap and "grapple: " or hoverP and "bicycle: " or "") .. (deadline and string.format("no contact before his release (%.2f s)", deadline) or "no contact"))
		end
	end
	if not plan then
		if Mark.duel and now - Mark.duel.seen > 0.2 then
			Mark.duelEnd("no plan")
		end
		return
	end
	local name = actorName(actor)
	if not Mark.duel or Mark.duel.model ~= model then
		Mark.duel = { model = model, at = now, name = name }
		logFile("duel", "plan", plan.kind, name, "td", type(plan.td) == "number" and string.format("%.2f", plan.td) or (plan.td or "air"), "tp", string.format("%.2f", plan.tp), "T", string.format("%.2f", plan.T), "bike", tostring(hoverP ~= nil), "grapple", grap and (grap.tArr and string.format("arrives %.2f", grap.tArr) or "flying") or "-", "d", string.format("%.1f", flat(P - root.Position).Magnitude), "h", string.format("%.1f", P.Y - floor))
	end
	Mark.duel.seen = now
	Mark.duelSee("armed", P, {
		plan = plan, path = Mark.duelMemo and Mark.duelMemo.path, pathAt = Mark.duelMemo and Mark.duelMemo.at or now,
		us = root.Position, landed = landed, floorY = Mark.duelFloor, vy = root.AssemblyLinearVelocity.Y, vJ = math.sqrt(2 * g * (Mark.jumpH or 7.2)), g = g,
	})
	-- move: to where we press, facing him (the agent; air control steers too)
	if CFG.CounterMove ~= false then
		local mySpd = Mark.akSpeeds(character)
		local cmd, route = Mark.agentSteer({
			key = "duel", us = root.Position, vUs = flat(root.AssemblyLinearVelocity), center = nil, vC = flat(V),
			target = Vector3.new(plan.Q.X, root.Position.Y, plan.Q.Z), spd = math.max(mySpd, hum.WalkSpeed), ff = Vector3.zero,
		})
		if cmd.Magnitude < 0.2 then
			cmd = unitOrNil(flat(plan.E - root.Position)) or cmd -- at the spot: lean in, the press goes out from the run
		end
		Mark.move.look = unitOrNil(flat(P - root.Position))
		Mark.move.pts = route
		Mark.move.born = Mark.move.born or now
		Mark.moveSteer(cmd, "duel")
	end
	if landed and plan.td ~= "ground" then
		if type(plan.td) == "number" and plan.td <= 0.035 and Mark.doJump("duel") then
			Mark.duel.jumpAt = now
			Mark.duelViz.liveUntil = now + 0.6
			logFile("duel", "jump", plan.kind, name, "tp", string.format("%.2f", plan.tp), "T", string.format("%.2f", plan.T))
		end
		return
	end
	if plan.tp > 0.035 then
		return
	end
	local sent = false
	if plan.kind == "slide" then
		predict = { dist = flat(P - root.Position).Magnitude, eta = plan.T, hit = plan.E, spd = V.Magnitude, iframe = 0, serverPos = P, livePos = r.Position, distLive = flat(r.Position - root.Position).Magnitude, delay = 0 }
		Mark.duelPress = true
		sent = tryTackle(character, root, plan.aim, plan.mult, { char = model, root = r })
		Mark.duelPress = nil
	else
		sent = Mark.akTry("duel", model, r, true)
	end
	logFile("duel", "press", plan.kind, sent and "sent" or "refused", name, "T", string.format("%.2f", plan.T), "mult", plan.mult and string.format("%.2f", plan.mult) or "-")
	if sent then
		Mark.duelViz.liveUntil = now + 0.6
		Mark.duelMemo = nil
		Mark.duelEnd("pressed")
	end
end

Mark.blockFrame = 0
-- why AutoBlock did nothing while an enemy owns the ball (rate-limited): "block skip <why> ..."
Mark.blockSkip = function(why, extra)
	local oid = liveOwnerId()
	if type(oid) ~= "number" or oid == 0 or oid == LocalPlayer.UserId then
		return
	end
	local pl = playerOf(oid)
	if not pl or sameTeam(pl) then
		return
	end
	if Mark.blockSkipWhy == why and os.clock() - (Mark.blockSkipAt or 0) < 1.5 then
		return
	end
	Mark.blockSkipWhy, Mark.blockSkipAt = why, os.clock()
	logFile("block skip", why, extra or "")
end
-- COMPETITOR CHECKS ARE OFF (user rule, repeated many times): when we OR the ball / target are near OUR goal, when we OR
-- the ball are near THEIR goal (CompetitorGoalZone, both ends), or when an enemy is within CompetitorEnemyNear of the
-- ball / target. "A teammate is nearer" only lets him have it in open midfield with no enemy on it. The old rule needed
-- the ball AND us at our goal only - every attack and every contested ball still yielded (log: 34 "ball teammate").
Mark.competitorFree = function(root, pos)
	local z = CFG.CompetitorGoalZone or 45
	if z > 0 then
		local g, eg = Mark.defendGoal(), enemyGoalPart()
		for _, gp in { g, eg } do
			if gp and (flat(pos - gp.Position).Magnitude <= z or flat(root.Position - gp.Position).Magnitude <= z) then
				return true
			end
		end
	end
	local rE = CFG.CompetitorEnemyNear or 15
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not Mark.mateDown(actor, model) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r and flat(r.Position - pos).Magnitude <= rE then
				return true
			end
		end
	end
	return false
end

-- PASS READ (AutoBlock). The carrier's charge is replicated and Mark.chargeShot replays it with the game's own solve
-- (ChargePathVelocity at full charge + ball physics). A flight that does NOT end in our mouth is a pass: the receiver is
-- the enemy closest to the flight. Spot = the EARLIEST flight sample (body height, past his kick reach) we reach before
-- the ball AND before the receiver: early samples hold for any charge length (only the length of the pass changes with
-- the charge, not its line). Returns { p, t, slack, rcv } or nil (no charge, a shot, or no sample we beat).
Mark.passSpot = function(character, root, uid)
	local rec = Mark.charges and Mark.charges[uid]
	if not (rec and rec.live and os.clock() - (rec.seen or 0) < 0.6) then
		return nil
	end
	local cs = Mark.chargeShot(uid)
	local g = Mark.defendGoal()
	if not (cs and g) or #cs.pts < 3 then
		return nil
	end
	local lb, lt, rb = goalMouthCorners(g)
	if lb and lt and rb then
		local mouth = (lb + rb) * 0.5
		local sideV = unitOrNil(flat(rb - lb))
		if sideV then
			local out = Vector3.new(-sideV.Z, 0, sideV.X)
			if flat(cs.launch - mouth):Dot(out) < 0 then
				out = -out
			end
			local half = flat(rb - lb).Magnitude * 0.5
			for i = 2, #cs.pts do
				local p = cs.pts[i]
				if flat(p - mouth):Dot(out) <= 0.3 then
					if math.abs(flat(p - mouth):Dot(sideV)) <= half + 2.5 then
						return nil -- a shot: the shot block owns it
					end
					break
				end
			end
		end
	end
	-- the receiver: the enemy (not the carrier) nearest to the flight
	local rcv, rcvPos, rcvMin = nil, nil, CFG.BlockPassRcvRadius or 14
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor.UserId ~= uid and actor ~= LocalPlayer and not sameTeam(actor) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r then
				local pos = CharacterMotion.GetPosition(model) or r.Position
				for i = 3, #cs.pts, 2 do
					local dd = flat(cs.pts[i] - pos).Magnitude
					if dd < rcvMin then
						rcv, rcvPos, rcvMin = actor, pos, dd
					end
				end
			end
		end
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
	if type(spd) ~= "number" or spd < 8 then
		spd = 16
	end
	local rcvBox = HitboxSettings.Receive
	local bodyHalf = rcvBox.Size.X * 0.5
	local lo = rcvBox.CFrameOffset.Y - rcvBox.Size.Y * 0.5
	local hi = rcvBox.CFrameOffset.Y + rcvBox.Size.Y * 0.5 + (Physics.BallRadius or 1)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local minRel = KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds() or 0.2
	local tRel = math.max(minRel - (os.clock() - rec.at), 0)
	local reach = Mark.kickReach() + 0.8
	local best = nil
	for i = 2, #cs.pts do
		local p = cs.pts[i]
		local h = p.Y - root.Position.Y
		if h >= lo and h <= hi and flat(p - cs.launch).Magnitude >= reach then
			local d = flat(p - root.Position).Magnitude
			local need = math.max(d - bodyHalf, 0) / spd + ping * 0.5 + 0.06
			local slack = tRel + cs.ts[i] - need
			local rcvNeed = rcvPos and math.max(flat(p - rcvPos).Magnitude - bodyHalf, 0) / 24 or math.huge
			if slack >= 0.05 and need < rcvNeed then
				return { p = p, t = cs.ts[i], slack = slack, rcv = rcv, ok = true }
			end
			if not best or slack > best.slack then
				best = { p = p, t = cs.ts[i], slack = slack, rcv = rcv, ok = false }
			end
		end
	end
	return best
end


-- ISOLATED CARRIER (the user's pro read): he has nobody to pass to when no teammate of his stands level with him or
-- closer to our goal, or every such teammate is already marked by one of ours. Holding distance for the pass is then
-- pointless: press him (stand at kick reach on his goal line, the push / AutoKick distance).
Mark.foeIsolated = function(carrier, P, g)
	local lb, _, rb = goalMouthCorners(g)
	local mouth = (lb and rb) and (lb + rb) * 0.5 or g.Position
	local dC = flat(P - mouth).Magnitude
	local slack = CFG.BlockLevelSlack or 8
	local outlets, names = 0, nil
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and actor ~= carrier and not sameTeam(actor) and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
			local r = ActorTargeting.GetActorRoot(actor)
			if r then
				local pos = CharacterMotion.GetPosition(model) or r.Position
				if flat(pos - mouth).Magnitude <= dC + slack and flat(pos - P).Magnitude <= (CFG.BlockPassMax or 130) and not Mark.mateNear(pos, CFG.BlockCoverRadius or 8) then
					outlets += 1
					names = (names and names .. "," or "") .. actorName(actor)
				end
			end
		end
	end
	return outlets == 0, outlets, names, dC
end



-- Agent route as a curve: cubic Hermite from our position (leaving along our own velocity) to the spot (arriving along
-- his run). 6 points. Short or standing: the straight pair.
Mark.blockCurve = function(from, to, vUs, vHim)
	local d = flat(to - from)
	local L = d.Magnitude
	if L < 3 then
		return { from, to }
	end
	local chord = d / L
	local u0 = vUs.Magnitude > 4 and vUs.Unit or chord
	local u1 = vHim.Magnitude > 3 and vHim.Unit or chord
	local m0, m1 = u0 * (L * 0.5), u1 * (L * 0.4)
	local out = table.create(6)
	for i = 0, 5 do
		local s = i / 5
		local s2, s3 = s * s, s * s * s
		local h00, h10, h01, h11 = 2 * s3 - 3 * s2 + 1, s3 - 2 * s2 + s, -2 * s3 + 3 * s2, s3 - s2
		local p = from * h00 + m0 * h10 + to * h01 + m1 * h11
		out[i + 1] = Vector3.new(p.X, from.Y, p.Z)
	end
	out[1], out[6] = from, to
	return out
end

-- ARRIVAL. The routes braked in proportion to the distance left: speed = 3.5 * gap (the polar orbit), d / 3 of the stick (the
-- straight run), another d / 3 on top for the block roles: the last 5-8 studs were an exponential crawl, 0.6 s of it for the last
-- stud (user: "the closer to the final point, the slower"). The speed worth keeping with `gap` studs to go is the one the body
-- can still stop from: v = sqrt(2 * a * gap), a = vmax / stopT; full speed until then, the last studs braked like a body does.
Mark.arriveSpeed = function(gap, vmax, stopT)
	local g = math.abs(gap)
	if g < 0.05 then
		return 0
	end
	local v = math.min(vmax, math.sqrt(2 * (vmax / math.max(stopT or CFG.ArriveStop or 0.12, 0.03)) * g))
	return gap < 0 and -v or v
end
Mark.arriveScale = function(gap, spd)
	return math.abs(Mark.arriveSpeed(gap, spd)) / math.max(spd, 1)
end

-- AGENT STEER (AutoBlock shadow / mark / cut-off, the air duel). The agent's way to a spot near a moving man is not a ruler:
--   far from him (> 20 st): a Hermite curve that leaves along our momentum and arrives along his run (Mark.blockCurve);
--     the command follows the curve a few studs ahead;
--   near him: POLAR control around him - the angle round him and the distance to him are steered separately (gain
--     3.5 /s each), so the body ORBITS him toward the spot (a spiral in, a tank-track turn) instead of cutting through
--     him, never closer than minR while the angle is still wrong; the agent faces him meanwhile (Mark.move.look) = a
--     strafe;
--   between 10 and 20 st the two blend; his velocity (or the caller's feed-forward) is added; a 60 ms low-pass keeps
--   the heading from snapping when his velocity jumps.
-- Returns cmd (|cmd| <= 1, zero under the move-hook threshold) and the route: the same law integrated 1 s ahead (the
-- agent line shows where the body will actually go).
Mark.agentSteer = function(o)
	local spd = math.max(o.spd or 16, 8)
	local function law(us, vUs, center, target)
		local off = flat(target - us)
		local straight
		do
			local d = off.Magnitude
			if d < 0.05 then
				straight = Vector3.zero
			else
				local route = Mark.blockCurve(us, target, vUs, o.vC or Vector3.zero)
				local aim = route[3] and d > 5 and flat(route[3] - us) or off
				straight = (unitOrNil(aim) or Vector3.zero) * Mark.arriveSpeed(d, spd)
			end
		end
		if not center then
			return straight
		end
		local rel = flat(us - center)
		local r = rel.Magnitude
		local relT = flat(target - center)
		local rT = relT.Magnitude
		if r < 0.5 or rT < 0.5 then
			return straight
		end
		local er = rel / r
		local et = Vector3.new(-er.Z, 0, er.X)
		local uT = relT / rT
		local dA = math.atan2(er.X * uT.Z - er.Z * uT.X, er:Dot(uT))
		local vt = Mark.arriveSpeed(dA * r, spd)
		local vr = Mark.arriveSpeed(rT - r, spd)
		local minR = o.minR or 4
		if r < minR and math.abs(dA) > 0.5 then
			vr = math.max(vr, (minR - r) * 4)
		end
		local polar = er * vr + et * vt
		local w = math.clamp((r - 10) / 10, 0, 1)
		return polar * (1 - w) + straight * w
	end
	local ff = o.ff or o.vC or Vector3.zero
	local v = law(o.us, o.vUs, o.center, o.target) + ff
	local cmd = v / spd
	if cmd.Magnitude > 1 then
		cmd = cmd.Unit
	end
	if cmd.Magnitude < 0.2 and flat(o.target - o.us).Magnitude < 0.8 then
		cmd = Vector3.zero
	end
	Mark.steerPrev = Mark.steerPrev or {}
	local now = os.clock()
	local pc = Mark.steerPrev[o.key or "x"]
	if pc and now - pc.t < 0.25 and cmd.Magnitude > 0.2 and pc.v.Magnitude > 0.2 then
		local k = 1 - math.exp(-(now - pc.t) / 0.06)
		local mixed = pc.v + (cmd - pc.v) * k
		if mixed.Magnitude > 0.2 then
			cmd = mixed.Magnitude > 1 and mixed.Unit or mixed
		end
	end
	Mark.steerPrev[o.key or "x"] = { t = now, v = cmd }
	-- route: integrate the same law (him moving with vC, the target with him), 10 x 0.1 s
	local pts = { o.us }
	local p, vel = o.us, o.vUs or Vector3.zero
	local c, tg = o.center, o.target
	local vC = o.vC or Vector3.zero
	for _ = 1, 10 do
		local want = law(p, vel, c, tg) + ff
		if want.Magnitude > spd then
			want = want.Unit * spd
		end
		vel = vel + (want - vel) * 0.6
		p = p + vel * 0.1
		if c then
			c = c + vC * 0.1
		end
		tg = tg + flat(ff) * 0.1
		pts[#pts + 1] = Vector3.new(p.X, o.us.Y, p.Z)
		if flat(tg - p).Magnitude < 0.8 then
			break
		end
	end
	pts[#pts + 1] = Vector3.new(tg.X, o.us.Y, tg.Z)
	return cmd, pts
end



-- Marking overlay: the pass lane (ink bed + state colour: safe = we make it, armed = we make it with margin, live = too late),
-- a ripple at the intercept point, a small ring on the receiver.
Mark.drawBlk = function(gy)
	Mark.blkLines = Mark.blkLines or makeLines(160, 1.4, 40)
	Mark.blkPool = Mark.blkPool or Mark.segPool(Mark.blkLines)
	local v = Mark.blkViz
	local now = os.clock()
	if CFG.DrawBlock ~= false and v and now - v.at < 0.25 and v.pick.lane then
		local ln = v.pick.lane
		local key = ln.ok and ((ln.slack or 0) > 0.4 and "armed" or "safe") or "live"
		local pal = Mark.defPalette[key]
		local seg = Mark.blkPool.seg
		local a = Vector3.new(ln.from.X, gy + 0.05, ln.from.Z)
		local b = Vector3.new(ln.to.X, gy + 0.05, ln.to.Z)
		local d = flat(b - a)
		local n = d.Magnitude
		if n > 1 then
			local u = d / n
			local nrm = Vector3.new(-u.Z, 0, u.X) * 0.45
			seg(a, b, COL.Ink, 0.3, 3.0, 39)
			seg(a, b, pal[1], 0.7, 1.4, 41)
			for s = 4, n - 1, 5 do
				local m = a + u * s
				seg(m - nrm, m + nrm, COL.Paper, 0.6, 1.1, 41)
			end
			Mark.kickRipple(seg, Vector3.new(ln.spot.X, gy, ln.spot.Z), 2.4, pal, Mark.rippleStep("blk-spot", Mark.rippleRates[key]), now, 2)
			Mark.kickRipple(seg, Vector3.new(b.X, gy, b.Z), 1.2, Mark.defPalette.safe, Mark.rippleStep("blk-rcv", Mark.rippleRates.safe), now, 4)
		end
	end
	Mark.blkPool.finish()
end

-- Coverage cone: the ball can go anywhere between the posts, so the body must sit on the bisector of the lines to both
-- posts, no deeper than where its width (Receive box + ball radius) still spans the whole cone. Returns bisector, depth.

-- How much of OUR mouth a shot from P really has: rays from P to 17 points across the mouth; a ray is closed when our
-- keeper (or a teammate standing in it) gets to it before the ball. Keeper reach along a ray = SaveReachStuds + the dive
-- travel (GoalkeeperDive: 20 st, cubic-out over 0.875 s) in the ball's flight time to the closest point, after 0.25 s of
-- reaction (a human keeper; the dive itself is not free either). Shot speed: the replicated charge's (Mark.chargeShot), else CFG.BlockShotSpeed. From a tight angle near the
-- post the keeper closes the whole mouth (open 0): no shot - the pass is the danger. Centre: open sides on both posts.
-- { open = deg, width = deg, bis = unit to the middle of the open part (nil when none), dist, keeper = bool }
Mark.shotOpen = function(P, g, uid)
	local lb, _, rb = goalMouthCorners(g)
	if not (lb and rb) then
		return nil
	end
	local cs = uid and Mark.charges and Mark.charges[uid] and Mark.charges[uid].live and Mark.chargeShot(uid)
	local spd = (cs and cs.speed and cs.speed > 20) and cs.speed or (CFG.BlockShotSpeed or 90)
	local Pf = Vector3.new(P.X, 0, P.Z)
	local keepers = {}
	Mark.gkDiveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	local DC = Mark.gkDiveMod.Constants
	local N, open, sum = 17, 0, Vector3.zero
	local a1, a2 = unitOrNil(flat(lb - P)), unitOrNil(flat(rb - P))
	local width = (a1 and a2) and math.deg(math.acos(math.clamp(a1:Dot(a2), -1, 1))) or 0
	for k = 0, N - 1 do
		local m = lb:Lerp(rb, (k + 0.5) / N)
		local seg = Vector3.new(m.X, 0, m.Z) - Pf
		local L = seg.Magnitude
		local closed = false
		if L > 1e-3 then
			local u = seg / L
			for _, K in keepers do
				local s = math.clamp((K - Pf):Dot(u), 0, L)
				local off = (Pf + u * s - K).Magnitude
				local e = math.clamp((s / spd - 0.25) / DC.DurationSeconds, 0, 1)
				if off <= DC.SaveReachStuds + 1 + DC.Distance * (1 - (1 - e) ^ 3) then
					closed = true
					break
				end
			end
			if not closed then
				open += 1
				sum += u
			end
		end
	end
	local mouth = (lb + rb) * 0.5
	return { open = width * open / N, width = width, bis = open > 0 and unitOrNil(sum) or nil, dist = flat(mouth - P).Magnitude, keeper = #keepers > 0, mouth = mouth, n = open }
end

-- FULL DEFENSIVE (user): with two or more enemies near our goal the body holds the goal like a keeper would, with run / jump /
-- slide / air intercept instead of a dive. Where to stand = the point in the zone in front of the mouth that is closest to
-- EVERY shot line (threat -> 7 points across the mouth, posts and the middle between them), weighted by how soon he can shoot
-- (the carrier now, the others after a pass), with each line already held by a mate counting as that mate's distance (a spot a
-- mate holds is taken). Smooth minimax: the 4-norm of w * min(our distance, best mate's distance) over the lines.
-- Guessed: the weights, FullDefDepth 14, the 7 mouth points, the 4-norm.
Mark.segDist = function(P, a, b)
	local ab = flat(b - a)
	local L2 = ab.X * ab.X + ab.Z * ab.Z
	local ap = flat(P - a)
	local s = L2 > 1e-6 and math.clamp((ap.X * ab.X + ap.Z * ab.Z) / L2, 0, 1) or 0
	local dx, dz = ap.X - ab.X * s, ap.Z - ab.Z * s
	return math.sqrt(dx * dx + dz * dz)
end

-- o: lb, rb (posts), M (mouth middle), n (field-ward), side (lb -> rb), half, threats {{pos, w}}, mates {pos}, depth, y (our height), prev (last spot)
-- -> spot, score | nil
Mark.fullDef = function(o)
	local K = 7
	local reach = o.reach or 3
	local lines = {}
	for _, t in o.threats do
		for j = 0, K - 1 do
			local G = o.lb + (o.rb - o.lb) * (j / (K - 1))
			local mate = math.huge
			for _, m in o.mates do
				mate = math.min(mate, Mark.segDist(m, t.pos, G))
			end
			local abx, abz = G.X - t.pos.X, G.Z - t.pos.Z
			lines[#lines + 1] = { ax = t.pos.X, az = t.pos.Z, abx = abx, abz = abz, L2 = abx * abx + abz * abz, w = t.w, mate = mate }
		end
	end
	if #lines == 0 then
		return nil
	end
	-- scalar maths only: ~300 spots x up to 28 lines per solve, no vector allocations in the loop
	local function score(P)
		local px, pz = P.X, P.Z
		local s = 0
		for _, l in lines do
			local apx, apz = px - l.ax, pz - l.az
			local k = l.L2 > 1e-6 and math.clamp((apx * l.abx + apz * l.abz) / l.L2, 0, 1) or 0
			local dx, dz = apx - l.abx * k, apz - l.abz * k
			-- a line that passes within the body's reach is held (distance 0): standing IN the cone beats standing beside it
			local d = math.max(math.min(math.sqrt(dx * dx + dz * dz), l.mate) - reach, 0) * l.w
			s += d * d * d * d
		end
		-- (tie-break: the spot nearest to where we already are)
		return s ^ 0.25 + 0.05 * math.sqrt((px - o.me.X) ^ 2 + (pz - o.me.Z) ^ 2)
	end
	local best, bs = nil, math.huge
	local lim = o.half + 4
	local x = -lim
	while x <= lim + 1e-6 do
		local z = 1.5
		while z <= o.depth + 1e-6 do
			local P = o.M + o.n * z + o.side * x
			local sc = score(P)
			if sc < bs then
				best, bs = P, sc
			end
			z += 1.5
		end
		x += 1.5
	end
	-- hysteresis: the old spot stays unless the new one is clearly better (no dance on a changing world)
	if o.prev then
		local so = score(o.prev)
		if so <= bs * 1.06 then
			return Vector3.new(o.prev.X, o.y, o.prev.Z), so
		end
	end
	return Vector3.new(best.X, o.y, best.Z), bs
end

Mark.blockCone = function(Pt, g)
	local lb, _, rb = goalMouthCorners(g)
	if not (lb and rb) then
		return nil
	end
	local a1, a2 = unitOrNil(flat(lb - Pt)), unitOrNil(flat(rb - Pt))
	local bis = a1 and a2 and unitOrNil(a1 + a2)
	if not bis then
		return nil
	end
	local half = math.acos(math.clamp(a1:Dot(a2), -1, 1)) * 0.5
	local body = HitboxSettings.Receive.Size.X * 0.5 + (Physics.BallRadius or 1)
	return bis, (half > 1e-3) and body / math.tan(half) or math.huge
end


Mark.tickBlock = function(character, root)
	if Mark.akUserTick(character, root) then
		return
	end
	if Mark.airBusy() then
		return -- Air Intercept owns the body (it ticks first, in tickVolley)
	end
	Mark.tickLob(character, root)
	Mark.tickCounterJump(character, root)
	if Mark.duel or Mark.lobBusy() then
		-- the air duel / the flick lob catch owns the body this frame
		return
	end
	-- idle polling at half rate when the frame budget is tight (>= ~100 fps): a started block runs every frame
	Mark.blockFrame += 1
	if Mark.blockFrame % 2 == 0 and (Mark.dtAvg or 1) < 0.0105 and Mark.move.mode ~= "block" then
		return
	end
	if not CFG.AutoBlock then
		return
	end
	Mark.tickBlockJump(character, root)
	Mark.blockSlide(character, root)
	if Mark.move.mode == "dodge" or Mark.move.mode == "dribble" or Mark.move.mode == "flee" then
		Mark.blockSkip("mode", tostring(Mark.move.mode))
		return
	end
	if slideAim or Mark.slideBody() then
		Mark.blockSkip("sliding")
		return
	end
	if ClientDodge.IsDribbling() then
		Mark.blockSkip("our dribble")
		return
	end
	if liveOwnerId() == LocalPlayer.UserId then
		if Mark.move.mode == "block" then
			logFile("block stop", "own")
			Mark.moveStop("block")
		end
		return
	end
	-- a loose ball is AutoBall's once tickBall took the steering: do not fight it with the stale block hold
	do
		local o2 = liveOwnerId()
		if Mark.move.mode == "ball" and not (type(o2) == "number" and o2 ~= 0) then
			return
		end
	end
	local held = Mark.blockHold and os.clock() - Mark.blockHold < 0.45 and (not Mark.blockRoot or Mark.blockRoot.Parent)
	local carrier, cr, chE, P, V = Mark.blockTarget()
	-- A pass / lob of THEIRS in the air that AutoBall is not running for (mode ~= "ball", checked above): keep the shape
	-- around the enemy it flies to - his arrival point is the carrier, the presser contests him there, the deep man
	-- stays deep. Before, the block stopped ("no carrier") for the whole flight.
	if not carrier and Mark.defendGoal() then
		local fl = Mark.flightTarget(root)
		if fl then
			Mark.blockRoleTick(character, root, fl.actor, fl.root, fl.model, fl.pos, Vector3.zero, Mark.defendGoal(), fl.t)
			return
		end
	end
	if not carrier then
		if Mark.move.mode == "block" and not held then
			logFile("block stop", "no carrier")
			Mark.moveStop("block")
		end
		Mark.blockSkip("no carrier")
		return
	end
	local g = Mark.defendGoal()
	if not g then
		if Mark.move.mode == "block" then
			logFile("block stop", "no goal")
			Mark.moveStop("block")
		end
		return
	end
	-- SHOT BLOCK FIRST (user: pros hold the goal and close the shot with their body). He is charging and the replicated
	-- charge path ends in our mouth: stand on the path sample we reach with time to spare (Mark.chargeSpot; a high one =
	-- jump spot, Mark.preJump times the jump to his charge). Every other mode (mark / cut / pass read / shadow) waits:
	-- before, a "closed" shot sent us to mark a receiver while he shot. Arrived = stand still (no sprint drift).
	if CFG.BlockShotFirst ~= false and Mark.chargeId == carrier.UserId then
		local ps = Mark.chargeSpot(character, root, carrier.UserId)
		if ps and ps.ok then
			local S = Vector3.new(ps.p.X, root.Position.Y, ps.p.Z)
			local off = flat(S - root.Position)
			local now = os.clock()
			Mark.move.look = unitOrNil(flat(P - root.Position))
			Mark.move.pts = nil
			Mark.move.born = Mark.move.born or now
			Mark.moveSteer(off.Magnitude > 0.6 and off.Unit or Vector3.zero, "block")
			Mark.standing = off.Magnitude <= 0.8
			Mark.sprintStand(Mark.standing) -- on the path: stand still, sprint dropped (even a held one)
			Mark.blockHold, Mark.blockLast, Mark.blockDest, Mark.blockRoot = now, now, S, cr
			if not Mark.shotBlockLog or now - Mark.shotBlockLog > 0.4 then
				Mark.shotBlockLog = now
				logFile("block shot", actorName(carrier), "t", string.format("%.2f", ps.t), "slack", string.format("%.2f", ps.slack), "move", string.format("%.1f", off.Magnitude), "jump", tostring(ps.jump == true), "h", string.format("%.1f", ps.p.Y - root.Position.Y))
			end
			return
		elseif ps and ps.slack > -0.9 then
			Mark.chargeRush(character, root, ps) -- (hopeless = more than 0.9 s short: the roles go on, a run there only loses the shape)
			return
		end
	end
	-- PASS READ: his charge says where the ball goes. A pass we can cut: stand on its path now, whatever we were doing
	if CFG.BlockPassRead ~= false then
		local ps = Mark.passSpot(character, root, carrier.UserId)
		if ps and ps.ok then
			Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
			local sp = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
			local S = Vector3.new(ps.p.X, root.Position.Y, ps.p.Z)
			local cmd, route = Mark.agentSteer({
				key = "block", us = root.Position, vUs = flat(root.AssemblyLinearVelocity), center = P, vC = Vector3.zero,
				target = S, spd = (type(sp) == "number" and sp >= 8) and sp or 16, ff = Vector3.zero, minR = HitboxSettings.Receive.Size.X * 0.5 + 1.5,
			})
			local now = os.clock()
			Mark.move.look = unitOrNil(flat(P - root.Position))
			Mark.move.pts = route
			Mark.move.born = Mark.move.born or now
			Mark.moveSteer(cmd, "block")
			Mark.blockHold, Mark.blockLast, Mark.blockDest, Mark.blockRoot = now, now, S, cr
			-- the marking overlay draws the read pass: his flight line to the cut spot, live palette (the ball is coming)
			local endP = ps.rcv and ps.rcv.Character and ActorTargeting.GetActorRoot(ps.rcv)
			Mark.blkViz = { at = now, pick = { lane = { from = P, to = endP and endP.Position or ps.p, spot = S, ok = true, slack = ps.slack } }, S = S, carrier = P }
			if not Mark.passReadLog or now - Mark.passReadLog > 0.4 then
				Mark.passReadLog = now
				logFile("block pass read", actorName(carrier), "to", ps.rcv and actorName(ps.rcv) or "space", "t", string.format("%.2f", ps.t), "slack", string.format("%.2f", ps.slack), "move", string.format("%.1f", flat(S - root.Position).Magnitude))
			end
			return
		end
	end
	Mark.blockRoleTick(character, root, carrier, cr, chE, P, V, g)
end

-- ===== AUTOBLOCK TEAM ROLES ==========================================================================================
-- User's defence (3 a side: keeper + 2 field): ONE presser on the carrier, the others hold the shape - the deep
-- defender near our goal covering the goal and the men around it, the screen between the carrier and his most dangerous
-- outlet (pass lane / second ball / a lob over the presser). The old AutoBlock was "me vs the carrier": every mode
-- (shadow, mark, cut, def cover) looked at him and at one receiver, ignored where our teammates stood, followed his
-- predicted diagonal (he goes left -> we go left) and stood aside the moment a mate came within CompetitorRadius.
-- Roles are decided every tick for every field defender we see (us + mates, keeper and downed mates excluded), with
-- our teammates' REAL positions: they are humans, we take the role they leave open.
--   PRESS : the defender who reaches the press spot soonest (Mark.pressTime: the spot moves with the carrier, so a man in
--           front of him meets him and a man behind only chases; anyone already on him -0.9 s; our own role -0.25 s of
--           hysteresis). Press spot = on the line from his CURRENT server pose to the MIDDLE of our mouth (not his
--           predicted run), RolePressGap in front of him (tight = kick reach when nobody can take a pass or he has an
--           open shot). His sideways run is mirrored (feed-forward), so we stay on that line and he cannot go round us.
--   DEEP  : near our goal, on the weighted direction to the threats (every enemy field player within RoleDeepZone of
--           the mouth: nearer = heavier, the carrier lighter while he is pressed, a man already marked lighter), pulled
--           to the middle by RoleDeepCenter, at a depth from the nearest threat (RoleDeepMin..RoleDeepMax), never wider
--           than the posts + 3. A pass from the wing into the middle meets this body.
-- MARK  : the other defenders take the enemies nobody covers (a mate on the line enemy -> middle of the mouth covers him),
--         by danger, standing ON that line goal-side of him; all covered = between the two most dangerous (DEEP).
-- NOBODY to pass to (no other enemy ahead / near): everyone PRESSES the carrier. Shot block first / pass read (above) and
-- AutoBall / Air Intercept (a free ball) override every role.
-- Seconds until a defender at `pos` (speed spd) stands on the press spot - and the spot MOVES: the carrier C runs with `vel`
-- and the spot is always C + off (the line to our mouth, in front of him). First t on a 0.1 s grid (6 s horizon) at which the
-- defender can be there. A man in front of the carrier meets him (closing speed = ours + his), a man behind chases (ours -
-- his: never catches a carrier that is as fast): the old cost divided the distance to the spot AS IT WAS NOW by our speed and
-- added a flat penalty for "behind" - it sent a mate 40 studs behind the runner to press while the man standing in front of
-- him marked a receiver (user: "he just runs to the goal and the script covers his teammate").
Mark.pressTime = function(pos, spd, C, vel, off)
	-- |A + v t| = spd t with A = C + off - pos: a quadratic, solved - the first version scanned 60 steps per defender per frame
	-- (tickBlock 0.13 -> 0.5 ms a tick: the FPS drop after v189)
	local ax, az = C.X + off.X - pos.X, C.Z + off.Z - pos.Z
	local c = ax * ax + az * az
	if c < 1e-6 then
		return 0
	end
	local vx, vz = vel.X, vel.Z
	local a = vx * vx + vz * vz - spd * spd
	local b = 2 * (ax * vx + az * vz)
	local best = nil
	if math.abs(a) < 1e-6 then
		if b < 0 then
			best = -c / b
		end
	else
		local disc = b * b - 4 * a * c
		if disc >= 0 then
			local sq = math.sqrt(disc)
			for _, t in { (-b - sq) / (2 * a), (-b + sq) / (2 * a) } do
				if t > 0 and (not best or t < best) then
					best = t
				end
			end
		end
	end
	if best and best <= 6 then
		return best
	end
	return 6 + math.sqrt(c) / spd
end

Mark.rolePlan = function(o)
	local M, n, side, half = o.M, o.n, o.side, o.half
	local C = o.C
	local ug = unitOrNil(flat(M - C)) or -n
	local dC = flat(C - M).Magnitude
	local spd = math.max(o.spd or 24, 8)
	local now = o.now
	local prev = o.prev
	local prevFresh = prev and now - prev.at < 0.6
	local takenR = CFG.RoleTakenR or 10
	-- 1) PRESS
	-- MEDIAN stand (within shot range): on the bisector of his lines to both posts (the median of his view from where the
	-- ball starts), at the depth where our body spans the whole post-to-post cone (Mark.blockCone) - the ball then meets
	-- the body whichever corner he picks. Tight press (nobody to pass to / open shot) = kick reach; no cone = RolePressGap.
	local gapP = o.tight and o.gap or math.max(CFG.RolePressGap or 6, o.gap)
	if o.bis and not o.tight then
		gapP = math.clamp(o.cover, o.gap, CFG.RoleCoverMax or 12)
	end
	local pressSpot = C + (o.bis or ug) * gapP
	local defs = { { me = true, pos = o.me, name = "me" } }
	for _, m in o.mates do
		defs[#defs + 1] = { pos = m.pos, name = m.name, actor = m.actor }
	end
	local presser, costs = nil, {}
	-- the carrier's run AT OUR GOAL only: his sideways drift and the sign noise of the replicated velocity flipped a defender
	-- between "meets him" and "never catches him" from one tick to the next (log: my cost 3.4 / 7.7 / 3.4 on consecutive ticks)
	local vRun = ug * math.max((o.vel or Vector3.zero):Dot(ug), 0)
	for _, d in defs do
		local engaged = flat(d.pos - C).Magnitude <= takenR + 2
		-- a man within reach of the carrier is ON him, whichever side (a mate slightly behind him is chasing, not
		-- absent: log - we ran at the carrier while his unmarked receivers stood nearer our goal)
		local cost = Mark.pressTime(d.pos, spd, C, vRun, pressSpot - C)
		if engaged then
			cost -= 0.9
		end
		if d.me and prevFresh and prev.role == "press" then
			cost -= 0.25
		end
		d.cost = cost
		costs[#costs + 1] = d.name .. string.format(" %.2f", cost)
		if not presser or cost < presser.cost then
			presser = d
		end
	end
	if CFG.BlockCompetitor == false then
		presser = defs[1]
	end
	-- 2) THREATS and who covers them. Every enemy field player (carrier excluded: the presser has him) nearer our goal
	-- than the carrier + slack, or inside the deep zone, is a threat. COVERED = one of ours (presser excluded) stands
	-- between him and the MIDDLE of our mouth: within 5 studs of the line threat -> mouth middle and within 16 of him.
	-- Uncovered threats are handed out by danger to the nearest free defender, who stands ON that line, goal side of
	-- him, leaning to the middle - the pros' "stand between the attackers": a spot a mate holds is taken, we go to
	-- the next one. The keeper is not a defender here (not in mates / foes).
	local zone = CFG.RoleDeepZone or 90
	local threats = {}
	for _, f in o.foes do
		if not f.carrier then
			local dR = flat(f.pos - M).Magnitude
			if dR <= zone or dR <= dC + (CFG.BlockLevelSlack or 8) then
				local toM = flat(M - f.pos)
				local L = toM.Magnitude
				local u = L > 0.5 and toM / L or n
				local covered, coverName = false, nil
				for _, d in defs do
					if d ~= presser and not d.me then -- (our own stand never "covers": it is the assignment itself)
						local r = flat(d.pos - f.pos)
						local s = r:Dot(u)
						if s > -1 and s < L + 2 and r.Magnitude <= 16 and (r - u * s).Magnitude <= 5 then
							covered, coverName = true, d.name
							break
						end
					end
				end
				local face = (o.face and flat(f.pos - C).Magnitude > 1) and math.clamp(flat(f.pos - C).Unit:Dot(o.face), -1, 1) or 0
				local danger = (1 - math.clamp(dR / zone, 0, 1)) * 3 + face * 0.8 + (1 - math.clamp(math.abs(flat(f.pos - C).Magnitude - 30) / 80, 0, 1))
				threats[#threats + 1] = { f = f, u = u, L = L, dR = dR, covered = covered, by = coverName, danger = danger, id = f.id }
			end
		end
	end
	table.sort(threats, function(a, b) return a.danger > b.danger end)
	-- PRESS WITH A PASS LEAN. Standing exactly on the line carrier -> mouth leaves his pass to the man behind / beside him
	-- open (user: one defender, one enemy behind, one with the ball: stand between "forward is a wall" and "the pass is cut").
	-- When the most dangerous UNCOVERED receiver is not on that line, the press direction swings from the goal line toward
	-- his lane by RolePassLean of the angle between them, never more than RolePassMax degrees: forward still meets us,
	-- and the lane to the receiver is shortened.
	local leanDeg, leanTo = 0, nil
	for _, t in threats do
		if not t.covered then
			local toR = flat(t.f.pos - C)
			if toR.Magnitude > 6 then
				local tu = toR.Unit
				local dotg = math.clamp(tu:Dot(ug), -1, 1)
				local lat = tu - ug * dotg
				if lat.Magnitude > 0.05 then
					local ang = math.min(math.deg(math.acos(dotg)), 90) -- (a man BEHIND the carrier is no reason to open the goal side)
					leanDeg = math.min(ang * (CFG.RolePassLean or 0.5), CFG.RolePassMax or 55)
					leanTo = t.f.name
					local lu = lat.Unit
					local a = math.rad(leanDeg)
					pressSpot = C + (ug * math.cos(a) + lu * math.sin(a)) * gapP
				end
			end
			break
		end
	end
	local free = {}
	for _, d in defs do
		if d ~= presser then
			free[#free + 1] = d
		end
	end
	local assigned = {}
	local function spotFor(t)
		local depth = math.clamp(t.L * 0.3, CFG.RoleMarkMin or 4, CFG.RoleMarkMax or 9)
		return t.f.pos + t.u * depth
	end
	for _, t in threats do
		if not t.covered and #free > 0 then
			local bi, bc = nil, math.huge
			for i, d in free do
				local c = flat(spotFor(t) - d.pos).Magnitude
				if prevFresh and d.me and prev.mark == t.id then
					c -= 4
				end
				if c < bc then
					bi, bc = i, c
				end
			end
			assigned[free[bi]] = t
			table.remove(free, bi)
		end
	end
	local myThreat = assigned[defs[1]]
	local dir = unitOrNil(flat(C - M)) or n
	local depth = math.clamp(math.min(dC, zone) * 0.35, CFG.RoleDeepMin or 8, CFG.RoleDeepMax or 24)
	local deepSpot = M + dir * depth
	do
		local lat = flat(deepSpot - M):Dot(side)
		local lim = half + 3
		if math.abs(lat) > lim then
			deepSpot = deepSpot - side * (lat - math.sign(lat) * lim)
		end
	end
	if myThreat then
		deepSpot = spotFor(myThreat)
	elseif #threats > 0 then
		-- every threat is covered: stand between the two most dangerous ones (the pass chain goes between them)
		local t1, t2 = threats[1], threats[2] or threats[1]
		local mid = (t1.f.pos + t2.f.pos) * 0.5
		deepSpot = M + (unitOrNil(flat(mid - M)) or n) * math.clamp(flat(mid - M).Magnitude * 0.4, CFG.RoleDeepMin or 8, CFG.RoleDeepMax or 24)
	end
	-- 4) our role
	local role, why
	if presser and presser.me then
		role, why = "press", (#defs == 1 and "alone" or "best cost")
	elseif myThreat then
		role, why = "mark", "uncovered " .. myThreat.f.name
	elseif #threats > 0 then
		role, why = "deep", "all covered"
	else
		-- nobody he can pass to (every other enemy is far or behind): pressing HIM is safe and it is the only job there is
		-- (user: "when the enemy is alone we must press him"; the old SCREEN role stood behind a presser instead)
		role, why = "press", "lone carrier"
	end
	return {
		role = role, why = why, presser = presser, costs = table.concat(costs, ", "), pressSpot = pressSpot, gapP = gapP,
		deepSpot = deepSpot, depth = depth, lean = leanDeg, leanTo = leanTo, mark = myThreat and myThreat.id, threats = threats, ug = ug, dC = dC,
	}
end

-- Executor: gathers the world for Mark.rolePlan, steers to our role's spot, logs role changes.
-- The enemy a free ball of theirs flies to: the field player nearest the path end (<= 25 studs), arrival time t.
Mark.flightTarget = function(root)
	local own = liveOwnerId()
	if type(own) == "number" and own ~= 0 then
		return nil
	end
	local st = Renderer.GetAuthoritativeMovementState()
	local kid = st and st.LastKickerUserId
	local kicker = type(kid) == "number" and playerOf(kid) or nil
	if not kicker or kicker == LocalPlayer or sameTeam(kicker) then
		return nil
	end
	local _, _, S, T = Mark.ballPath(root)
	if not S or #S < 2 then
		return nil
	end
	local best, bestD, bestT = nil, 25, nil
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) and ActorTargeting.GetActorRoot(actor)
		if r then
			for i = 2, #S, 2 do
				local d = flat(S[i] - r.Position).Magnitude - 24 * T[i]
				if d < bestD then
					best, bestD, bestT = { actor = actor, model = model, root = r }, d, T[i]
					best.pos = S[i]
				end
			end
		end
	end
	if best then
		best.t = bestT
	end
	return best
end

-- sprint off while we stand on the block spot (Sprint.SetBlocked is a per-source block table; our source is released
-- the moment we move on / the block ends, see moveStop)
Mark.sprintStand = function(on)
	if (Mark.sprintStandOn or false) == on then
		return
	end
	Mark.sprintStandOn = on
	Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
	Mark.sprint.SetBlocked("AgentStand", on)
end

-- A role is kept RoleHold s: the answer must stay the same that long before the body changes its job. The log: 130 role changes,
-- 111 of them under 3 s, press <-> deep every 0.1 s (a threat's "covered" flag or the cost margin flickers around its
-- threshold, and the agent ran at the carrier, then back, then at the carrier). A new carrier or a stale state (> 0.6 s) takes
-- the answer at once.
Mark.roleSettle = function(cand, carrierId, now)
	local h = Mark.roleHeld
	if not h or h.carrier ~= carrierId or now - h.at > 0.6 then
		Mark.roleHeld = { role = cand, carrier = carrierId, at = now }
		return cand
	end
	h.at = now
	if cand == h.role then
		h.cand = nil
		return h.role
	end
	if h.cand ~= cand then
		h.cand, h.candAt = cand, now
	end
	if now - h.candAt >= (CFG.RoleHold or 0.7) then
		h.role, h.cand = cand, nil
	end
	return h.role
end

Mark.blockRoleTick = function(character, root, carrier, cr, chE, P, V, g, flightT)
	local lb, _, rb, _, _, nrm = goalMouthCorners(g)
	local n = nrm and unitOrNil(flat(nrm))
	local side = lb and rb and unitOrNil(flat(rb - lb))
	if not (n and side) then
		return
	end
	local M = (lb + rb) * 0.5
	local now = os.clock()
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local dly = chE and math.clamp(CharacterMotion.GetDisplayDelaySeconds(chE) or 0, 0, 0.25) or 0
	local Vc = V.Magnitude > 30 and V.Unit * 30 or V
	-- his server pose NOW (display delay + half the ping), no run prediction
	local C = P + Vc * (dly + ping * 0.5)
	local mySpd = Mark.akSpeeds(character)
	local mates, foes = {}, {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and ActorTargeting.GetActorRoot(actor)
		if r and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
			local pos = CharacterMotion.GetPosition(model) or r.Position
			if sameTeam(actor) then
				mates[#mates + 1] = { pos = pos, name = actorName(actor), actor = actor }
			else
				foes[#foes + 1] = { id = actor.UserId, pos = actor == carrier and C or pos, vel = flat(CharacterMotion.GetVelocity(model) or Vector3.zero), carrier = actor == carrier, marked = actor ~= carrier and Mark.mateNear(pos, CFG.BlockCoverRadius or 8) ~= nil, name = actorName(actor) }
			end
		end
	end
	-- tight press: nobody he can pass to, or an open shot past our keeper near goal
	local iso = CFG.BlockPressIso ~= false and Mark.foeIsolated(carrier, P, g)
	local so = CFG.BlockDanger ~= false and Mark.shotOpen(C, g, carrier.UserId) or nil
	local openShot = so ~= nil and so.dist <= (CFG.BlockGoalRange or 70) and so.open >= (CFG.BlockOpenAngle or 5) and CFG.BlockPressOpen ~= false
	local gap = math.max(CFG.BlockGapMin or 2.2, Mark.kickReach() - 1 - (CFG.BlockCloser or 1.0))
	local bis, cover = nil, nil
	if flat(C - M).Magnitude <= (CFG.BlockGoalRange or 70) then
		bis, cover = Mark.blockCone(C, g)
		if bis and not (cover and cover < math.huge) then
			bis, cover = nil, nil
		end
	end
	local plan = Mark.rolePlan({
		bis = bis, cover = cover,
		M = M, n = n, side = side, half = flat(rb - lb).Magnitude * 0.5, C = C, me = root.Position, spd = mySpd, now = now,
		prev = Mark.roleLast, mates = mates, foes = foes, gap = gap, tight = iso or openShot, ping = ping,
		face = unitOrNil(flat(Vc)) or (cr and unitOrNil(flat(cr.CFrame.LookVector))), vel = flat(Vc),
	})
	local role = Mark.roleSettle(plan.role, carrier.UserId, now)
	local S = role == "press" and plan.pressSpot or plan.deepSpot
	S = Vector3.new(S.X, root.Position.Y, S.Z)
	-- FULL DEFENSIVE: the carrier and at least one more enemy near the mouth -> hold the goal (Mark.fullDef) instead of the roles
	if CFG.FullDefensive then
		local range = CFG.FullDefRange or 60
		local th = {}
		for _, f in foes do
			local dR = flat(f.pos - M).Magnitude
			if f.carrier or dR <= range then
				th[#th + 1] = { pos = f.pos, w = f.carrier and 1 or (0.35 + 0.35 * (1 - math.clamp(dR / range, 0, 1))), name = f.name }
			end
		end
		if #th >= 2 and flat(C - M).Magnitude <= range then
			local fc = Mark.fullCache
			local mp = {}
			for _, m in mates do
				mp[#mp + 1] = m.pos
			end
			-- re-solved at 10 Hz (the solve is a few thousand segment tests); the old spot is the hysteresis reference
			local spot, sc
			if fc and now - fc.at < 0.1 then
				spot, sc = fc.p, fc.sc
			else
				spot, sc = Mark.fullDef({ lb = lb, rb = rb, M = M, n = n, side = side, half = flat(rb - lb).Magnitude * 0.5, threats = th, mates = mp, depth = CFG.FullDefDepth or 14, y = root.Position.Y, me = root.Position, reach = HitboxSettings.Receive.Size.X * 0.5 + (Physics.BallRadius or 1), prev = fc and now - fc.at < 0.6 and fc.p or nil })
				Mark.fullCache = { p = spot, at = now, sc = sc }
			end
			role, S = "full", spot
			plan.why = string.format("%d threats", #th)
			if not fc or now - (Mark.fullLog or 0) > 0.8 then
				Mark.fullLog = now
				local names = {}
				for _, t in th do
					names[#names + 1] = t.name:sub(1, 8)
				end
				logFile("block full", "spot", fmtV(spot), "score", string.format("%.1f", sc), "lat", string.format("%.1f", flat(spot - M):Dot(side)), "out", string.format("%.1f", flat(spot - M):Dot(n)), "threats", table.concat(names, ","), "mates", tostring(#mp))
			end
		else
			Mark.fullCache = nil
		end
	end
	local last = Mark.roleLast
	if not last or last.role ~= role or now - last.at > 0.6 then
		logFile("block role", role, plan.why, actorName(carrier), flightT and string.format("ball arrives %.2f", flightT) or "carrier", "presser", plan.presser and plan.presser.name or "-", "costs", plan.costs,
			"dC", string.format("%.0f", plan.dC), "tight", tostring(iso or openShot), "deep d", string.format("%.1f", plan.depth), "lean", string.format("%.0f", plan.lean or 0) .. (plan.leanTo and ("->" .. plan.leanTo) or ""),
			"mates", tostring(#mates), "foes", tostring(#foes))
	end
	Mark.roleLast = { role = role, at = now, mark = plan.mark }
	do
		local tl = {}
		for _, t in plan.threats do
			tl[#tl + 1] = string.format("%s d%.0f %s", t.f.name:sub(1, 8), t.dR, t.covered and ("cov:" .. t.by) or "OPEN")
		end
		Mark.snap("AutoBlock", role .. " " .. plan.why, "threats: " .. table.concat(tl, ", ") .. " | costs " .. plan.costs)
	end
	-- movement: the presser orbits him onto his goal line and mirrors his sideways run; the others walk to their spot and
	-- stand (no sprint drift), orbiting him only when he is close
	local off = flat(S - root.Position)
	local ff = Vector3.zero
	if role == "press" then
		ff = Vc - plan.ug * Vc:Dot(plan.ug)
	end
	local nearHim = flat(C - root.Position).Magnitude < 14
	local cmd, route = Mark.agentSteer({
		key = "block", us = root.Position, vUs = flat(root.AssemblyLinearVelocity), center = (role == "press" or nearHim) and C or nil,
		vC = Vc, target = S, spd = mySpd, ff = ff, minR = HitboxSettings.Receive.Size.X * 0.5 + 1.5,
	})
	-- ON the spot: stand still and drop the sprint (even the one the player holds) - no wobble around a perfect stand,
	-- and a standing body is what the ball bounces off. Leaves the stand only when the spot moves > 1.8 studs away.
	local standing = Mark.standing
	if off.Magnitude <= 1.0 or (standing and off.Magnitude <= 1.8) then
		cmd = Vector3.zero
		Mark.standing = true
	else
		Mark.standing = false
	end
	Mark.sprintStand(Mark.standing)
	if role ~= "press" then
		Mark.blockMarkAt = now -- not on the carrier: the tackle is not held for this block (tackleGate)
	end
	Mark.blockRoot, Mark.blockHold, Mark.blockLast, Mark.blockDest = cr, now, now, S
	Mark.blkViz = { at = now, pick = { lane = { from = C, to = S, spot = S, ok = true, slack = 0 } }, S = S, carrier = P }
	if not Mark.blockLogged then
		Mark.blockLogged = true
		logFile("block start", role, "dist", string.format("%.1f", flat(C - root.Position).Magnitude), "spot", string.format("%.1f", off.Magnitude))
	end
	if not Mark.blockTraceAt or now - Mark.blockTraceAt > 0.5 then
		Mark.blockTraceAt = now
		local along = flat(root.Position - C):Dot(plan.ug)
		local lat = math.abs(flat(root.Position - C):Dot(Vector3.new(-plan.ug.Z, 0, plan.ug.X)))
		logFile("block track", role, "dist", string.format("%.1f", flat(C - root.Position).Magnitude), "along", string.format("%.1f", along), "lat", string.format("%.1f", lat), "off", string.format("%.1f", off.Magnitude), "his", string.format("%.1f", V.Magnitude), "dC", string.format("%.0f", plan.dC))
	end
	Mark.move.look = unitOrNil(flat(C - root.Position)) or Mark.chargeFace
	Mark.move.pts = route
	Mark.move.born = Mark.move.born or now
	Mark.moveSteer(cmd, "block")
	if off.Magnitude > 6 then
		Mark.agentHold(true, "chase")
	end
end

-- Tackle vs block. The slide is one committed direction; a carrier with Dodge ready dribbles it (Dodge iframe, and
-- SuccessfulDodgeSpeedBoost for him). So with AutoBlock on, the slide is only for: his Dodge seen and still on
-- RepeatDelaySeconds cooldown ("naked"), he is running away from behind us faster than block can follow ("escape"),
-- or he is inside TackleGoalZone of our goal and we are not already holding him in kick range ("goal").
Mark.tryTackle = tryTackle

-- Seconds left on the enemy keeper's dive cooldown (0 = he can dive). Only keepers (isGoalkeeper) count.
Mark.foeDiveLeft = function()
	local d = Mark.foeDive
	if not d then
		return 0
	end
	Mark.gkDiveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
	local cd = Mark.gkDiveMod.Constants.RepeatDelaySeconds or 1.875
	local now = os.clock()
	local left = 0
	for uid, at in d do
		if now - at > cd + 1 then
			d[uid] = nil
		else
			local a = playerOf(uid)
			if a and isGoalkeeper(a) then
				left = math.max(left, cd - (now - at))
			end
		end
	end
	return left
end

-- ===== PASS ASSIST =====================================================================================
-- The user presses Pass or Lob while the crosshair is on a teammate. The game would send FreeLowPass (a 15 deg ground
-- pass) or its AssistedPass (its own aim). We swap the press for a script-held Lob (FreeLobPass) and choose the two numbers
-- the server derives the velocity from: the aim YAW (flat direction; pitch is ignored by Pass.GetVelocity) and the CHARGE
-- seconds (hspeed 45..80 and upward speed 45..60 both come from the charge). Everything else is the game's own function
-- (ChargePathVelocity.GetLaunchVelocity -> Pass.GetVelocity, Pass.GetSpin, Physics.GetAirFlight), so the preview is the
-- flight the server will compute. Too far -> max charge (the ball lands short of him), too near -> min charge.
Mark.pa = Mark.pa or {}

Mark.paRot = function(v, a)
	local c, s = math.cos(a), math.sin(a)
	return Vector3.new(v.X * c - v.Z * s, 0, v.X * s + v.Z * c)
end

Mark.paConst = function(char)
	Mark.passMod = Mark.passMod or require(Modules.Actions.Pass)
	local c = Mark.passMod.GetChargeConstants("FreeLobPass", char)
	if type(c) == "table" and type(c.MinimumChargeSeconds) == "number" and type(c.MaximumChargeSeconds) == "number" then
		return c.MinimumChargeSeconds, c.MaximumChargeSeconds
	end
	return 0.1, 0.3
end

Mark.paPose = function(sel)
	local pos, vel = Mark.carrierPose(sel.root, sel.model)
	vel = Mark.trendVel(sel.model, vel)
	sel.pos = pos
	sel.vel = Vector3.new(vel.X, 0, vel.Z)
end

-- One lob: returns { vel, pts, times, land, t, apex, origin } or nil.
Mark.paFlight = function(ctx, charge, dir)
	local look = Vector3.new(dir.X, 0, dir.Z)
	local origin = nil
	local o = Mark.carry.GetLaunchPosition(ctx.char, "FreeLobPass", look, false, charge)
	if typeof(o) == "Vector3" then
		origin = o
	else
		origin = Renderer.GetPosition()
	end
	if typeof(origin) ~= "Vector3" then
		return nil
	end
	local aim = {
		Origin = ctx.camPos,
		Direction = look,
		CameraCFrame = CFrame.lookAt(ctx.camPos, ctx.camPos + look),
		CameraFieldOfView = ctx.fov,
		IsAirborne = false,
	}
	local vel = ChargePathVelocity.GetLaunchVelocity(ctx.char, charge, "FreeLobPass", aim, origin, ctx.reported, nil, nil, nil, ctx.boundary)
	if typeof(vel) ~= "Vector3" then
		return nil
	end
	local spin = Mark.passMod.GetSpin(ctx.char, vel, "FreeLobPass", ctx.reported)
	local pos, v, sp = origin, vel, (typeof(spin) == "Vector3") and spin or Vector3.zero
	local pts, times = { pos }, { 0 }
	local t, apex = 0, pos.Y
	local land = nil
	local step = 0.05
	for _ = 1, 100 do
		local np, nv, ns = Physics.GetAirFlight(pos, v, sp, step, ctx.tuning)
		if typeof(np) ~= "Vector3" then
			break
		end
		local prev = pos
		pos, v, sp = np, nv or v, ns or sp
		t += step
		apex = math.max(apex, pos.Y)
		pts[#pts + 1], times[#times + 1] = pos, t
		if v.Y < 0 and pos.Y <= ctx.yT then
			local a = math.clamp((prev.Y - ctx.yT) / math.max(prev.Y - pos.Y, 1e-4), 0, 1)
			land = prev:Lerp(pos, a)
			t = t - step + step * a
			pts[#pts], times[#times] = land, t
			break
		end
		if pos.Y <= ctx.floorY then
			land = Vector3.new(pos.X, ctx.floorY, pos.Z)
			pts[#pts] = land
			break
		end
	end
	land = land or pts[#pts]
	return { vel = vel, pts = pts, times = times, land = land, t = t, apex = apex, origin = origin, landedHigh = land.Y > ctx.floorY + 0.5 }
end

-- sel = { actor, model, root, ... }; fixed = charge seconds to keep (re-aim at release), nil = choose the charge.
Mark.paSolve = function(sel, fixed)
	local char = LocalPlayer.Character
	local root = char and char:FindFirstChild("HumanoidRootPart")
	if not (char and root and Workspace.CurrentCamera) then
		return nil
	end
	Mark.paPose(sel)
	Mark.carry = Mark.carry or require(Modules.Ball.Carry)
	Mark.passMod = Mark.passMod or require(Modules.Actions.Pass)
	Mark.pathPreview = Mark.pathPreview or require(Client.Gameplay.Actions.ChargePathPreview)
	Mark.fieldSet = Mark.fieldSet or require(Modules.Gameplay.FieldSettings)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local boundary = Mark.pathPreview.GetChargeBoundaryWorld(LocalPlayer)
	local rcv = HitboxSettings.Receive
	local gy = Mark.fieldSet.GetGroundYAt(sel.pos)
	local ctx = {
		char = char,
		reported = flat(root.AssemblyLinearVelocity),
		tuning = Physics.GetCharacterTuning(char),
		boundary = boundary,
		camPos = Workspace.CurrentCamera.CFrame.Position,
		fov = Workspace.CurrentCamera.FieldOfView,
		yT = sel.pos.Y + rcv.CFrameOffset.Y,
		floorY = (type(gy) == "number" and gy or (sel.pos.Y - 3.8)) + Physics.BallRadius,
	}
	local ceilY = boundary and type(boundary.CeilingY) == "number" and boundary.CeilingY or math.huge
	local ballPos = Renderer.GetPosition() or root.Position
	local goalP = enemyGoalPart()
	goalP = goalP and goalP.Position
	local leadMin = CFG.PassGoalLead or 34
	-- GOAL-AWARE INTENT. His velocity (Mark.trendVel) says where he runs now, not where he is going: a winger cutting
	-- sideways is going for the goal. The receive point leads along his speed turned PassGoalBias of the way toward their goal
	-- (speed kept), so the ball goes where he will want to be, not where a straight extrapolation puts him.
	local ug = goalP and unitOrNil(flat(goalP - sel.pos)) or nil
	local spdV = sel.vel.Magnitude
	local intent = nil
	if spdV > 1.5 then
		local vu = sel.vel / spdV
		local b = CFG.PassGoalBias or 0.3
		intent = ug and unitOrNil(vu * (1 - b) + ug * b) or vu
	end
	-- CROSS. A mate in the box area (PassCrossMin..PassCrossZone from their goal, the ball farther out) catches a high
	-- ball in a JUMP: the ball is solved to the point he reaches at the top of a jump (AirReceive box at jump height) and
	-- PassCrossAhead studs ahead of him toward the goal, so the flight ends a little beyond where he stands and he meets it in
	-- the air. Only the lob exists in Pass Assist, so this is the lob's aim, not another pass type.
	local dMate = goalP and flat(sel.pos - goalP).Magnitude or math.huge
	local crossOn = CFG.PassCross ~= false and goalP ~= nil and dMate <= (CFG.PassCrossZone or 60) and dMate >= (CFG.PassCrossMin or 12) and flat(ballPos - goalP).Magnitude > dMate + 4
	local ahead = Vector3.zero
	if crossOn then
		leadMin = math.min(leadMin, CFG.PassCrossMin or 12)
		if ug then
			ahead = ug * math.min(CFG.PassCrossAhead or 2, math.max(dMate - (CFG.PassCrossMin or 12), 0))
		end
		local ar = HitboxSettings.AirReceive
		ctx.yT = math.max(ctx.yT, sel.pos.Y + ar.CFrameOffset.Y + (Mark.jumpH or 7.2) * (CFG.PassCrossJump or 0.6))
	end
	-- Near their goal a pass is a pass to HIM: the usual receive point is where he will be when the ball arrives (a through ball),
	-- which up there sails past or in front of him into the keeper's hands. Within PassNearGoal of the goal (ball or target)
	-- the lead is capped at PassNearLead studs (0 = exactly on him) and the ball is solved to that point.
	local nearGoal = goalP ~= nil and CFG.PassNearGoal ~= 0 and math.min(flat(ballPos - goalP).Magnitude, flat(sel.pos - goalP).Magnitude) <= (CFG.PassNearGoal or 80)
	local leadCap = CFG.PassNearLead or 3
	local function targetAt(tt)
		local lead = intent and intent * (spdV * (tt + ping * 0.5)) or Vector3.zero
		if nearGoal and lead.Magnitude > leadCap then
			lead = lead.Magnitude > 1e-3 and lead.Unit * leadCap or Vector3.zero
		end
		local T = sel.pos + lead + ahead
		if goalP then
			-- never predict a receive point close to their goal: shorten the lead until it is outside the zone (or drop it
			-- when he already stands inside - the keeper owns that area)
			if flat(T - goalP).Magnitude < leadMin then
				if flat(sel.pos - goalP).Magnitude < leadMin then
					return sel.pos
				end
				local lo2, hi2 = 0, 1
				for _ = 1, 6 do
					local m = (lo2 + hi2) * 0.5
					if flat(sel.pos + lead * m - goalP).Magnitude < leadMin then
						hi2 = m
					else
						lo2 = m
					end
				end
				T = sel.pos + lead * lo2
			end
		end
		return T
	end
	local function evalCharge(c, tFly, dirFixed)
		local T0 = targetAt(c + tFly)
		local dir = dirFixed or unitOrNil(flat(T0 - ballPos))
		if not dir then
			return nil
		end
		local fl = Mark.paFlight(ctx, c, dir)
		if not fl then
			return nil
		end
		local T = targetAt(c + fl.t)
		local to = flat(T - fl.origin)
		local D = to.Magnitude
		local d0 = unitOrNil(to) or dir
		local miss = flat(fl.land - T)
		local perp = Vector3.new(-d0.Z, 0, d0.X)
		return { c = c, dir = dir, fl = fl, T = T, D = D, along = miss:Dot(d0), lat = miss:Dot(perp) }
	end
	local lo, hi = Mark.paConst(char)
	local tF = Mark.pa.tFly or 1.5
	local best, status = nil, nil
	if fixed then
		best = evalCharge(math.clamp(fixed, lo, hi), tF)
	else
		local eHi = evalCharge(hi, tF)
		if not eHi then
			return nil
		end
		if eHi.along < 0 then
			best, status = eHi, "short"
		else
			local eLo = evalCharge(lo, eHi.fl.t)
			if not eLo then
				return nil
			end
			if eLo.along > 0 then
				best, status = eLo, "long"
			else
				local a, b = eLo, eHi
				best = a
				for _ = 1, 5 do
					local mid = evalCharge((a.c + b.c) * 0.5, (a.fl.t + b.fl.t) * 0.5)
					if not mid then
						break
					end
					if mid.along < 0 then
						a = mid
					else
						b = mid
					end
					if math.abs(mid.along) < math.abs(best.along) then
						best = mid
					end
				end
			end
		end
	end
	if not best then
		return nil
	end
	for _ = 1, 2 do
		if math.abs(best.lat) < 0.5 then
			break
		end
		local e2 = evalCharge(best.c, best.fl.t, Mark.paRot(best.dir, -best.lat / math.max(best.D, 8) * 0.55))
		if not e2 then
			break
		end
		if math.abs(e2.lat) + math.abs(e2.along) * 0.35 < math.abs(best.lat) + math.abs(best.along) * 0.35 - 0.3 then
			best = e2
		else
			break
		end
	end
	Mark.pa.tFly = best.fl.t
	local fl = best.fl
	local sol = {
		charge = best.c, dir = best.dir, land = fl.land, pts = fl.pts, times = fl.times, vel = fl.vel, t = fl.t, apex = fl.apex,
		origin = fl.origin, T = best.T, along = best.along, lat = best.lat, D = best.D,
		ceiling = fl.apex >= ceilY - Physics.BallRadius - 1,
	}
	sol.along3 = Vector3.new(-best.dir.Z, 0, best.dir.X)
	sol.cross = crossOn
	local contested = false
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
		if r and flat(r.Position - fl.land).Magnitude < (isGoalkeeper(actor) and (CFG.PassKeeperRadius or 14) or 5) then
			contested = true
			break
		end
	end
	sol.contested = contested
	if status then
		sol.status = status
	elseif math.abs(sol.lat) <= 2.4 and math.abs(sol.along) <= 4 and not sol.ceiling and not contested then
		sol.status = "ok"
	else
		sol.status = contested and "contested" or (sol.ceiling and "ceiling" or "off")
	end
	sol.ok = sol.status == "ok"
	return sol
end

-- Every teammate we could pass to (range, alive, not standing in their goal mouth). Drawn whether or not the crosshair
-- is on them: the old mark existed only after a solved flight and sat on the ground under the model, so nothing showed.
Mark.paList = function(root)
	local list = {}
	local ballPos = Renderer.GetPosition() or root.Position
	local goal = enemyGoalPart()
	local zone = CFG.PassGoalZone or 36
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
		if r and (CFG.PassToKeeper or not isGoalkeeper(actor)) and not Mark.mateDown(actor, model) then
			local pos = r.Position
			local flatD = flat(pos - ballPos).Magnitude
			if flatD >= (CFG.PassMinDist or 7) and flatD <= (CFG.PassMaxDist or 130) then
				if not (goal and flat(pos - goal.Position).Magnitude < zone) then
					list[#list + 1] = { actor = actor, root = r, name = actorName(actor), flatD = flatD }
				end
			end
		end
	end
	-- OPENNESS (the automatic passes - projectile / blast / Air Intercept - used to take whoever came first: the log showed balls
	-- handed to a mate with an enemy on him). open = the nearest enemy to the mate, lane = the nearest enemy to the line ball ->
	-- mate (both capped at 40); marked = an enemy within 9 of him or 5 of the lane.
	local foes = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
		if r and not Mark.mateDown(actor, model) then
			foes[#foes + 1] = r.Position
		end
	end
	for _, e in list do
		local to = flat(e.root.Position - ballPos)
		local u = unitOrNil(to)
		local open, lane = 40, 40
		for _, fp in foes do
			open = math.min(open, flat(fp - e.root.Position).Magnitude)
			if u then
				local q = flat(fp - ballPos)
				local s = math.clamp(q:Dot(u), 0, to.Magnitude)
				lane = math.min(lane, (q - u * s).Magnitude)
			end
		end
		e.open, e.lane, e.marked = open, lane, open < 9 or lane < 5
	end
	table.sort(list, function(a, b)
		if a.marked ~= b.marked then
			return not a.marked
		end
		return a.open + a.lane * 0.5 - a.flatD * 0.15 > b.open + b.lane * 0.5 - b.flatD * 0.15
	end)
	return list
end

-- the list for passes the SCRIPT makes (nobody chose the mate): the unmarked ones, best first; all of them only if every mate is marked
Mark.paAuto = function(root)
	local all = Mark.paList(root)
	local free = {}
	for _, e in all do
		if not e.marked then
			free[#free + 1] = e
		end
	end
	return #free > 0 and free or all
end

-- The teammate under the crosshair. Candidates sit inside a cone around the camera ray (wider for close teammates);
-- one near the enemy goal and in line with it is a shooting target, and when the crosshair is closer to the goal than to
-- him while AutoShoot has a solution, the goal wins.
Mark.paSelect = function(root)
	local cam = Workspace.CurrentCamera
	if not cam then
		return nil
	end
	local cf = cam.CFrame
	local look = cf.LookVector
	local ballPos = Renderer.GetPosition() or root.Position
	local goal = enemyGoalPart()
	local gdir = goal and (goal.Position - cf.Position)
	local angGoal = gdir and gdir.Magnitude > 1 and math.deg(math.acos(math.clamp(gdir.Unit:Dot(look), -1, 1))) or 999
	local prev = Mark.pa.sel
	local fov = CFG.PassFov or 12
	local best, why = nil, nil
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
		if r and (CFG.PassToKeeper or not isGoalkeeper(actor)) and not Mark.mateDown(actor, model) then
			local pos = r.Position
			local flatD = flat(pos - ballPos).Magnitude
			if flatD >= (CFG.PassMinDist or 7) and flatD <= (CFG.PassMaxDist or 130) then
				local d = pos + Vector3.new(0, 1.5, 0) - cf.Position
				if d:Dot(look) > 0 then
					local ang = math.deg(math.acos(math.clamp(d.Unit:Dot(look), -1, 1)))
					local tol = fov
					if prev and prev.actor == actor then
						tol = math.min(fov + 6, 16)
					end
					if ang <= tol then
						local shadow = false
						if goal and gdir and gdir.Magnitude > 1 and flat(pos - goal.Position).Magnitude < (CFG.PassGoalZone or 36) then
							local a2 = math.deg(math.acos(math.clamp(d.Unit:Dot(gdir.Unit), -1, 1)))
							shadow = a2 < (CFG.PassGoalSep or 9)
						end
						if shadow then
							why = "goal shadow " .. actorName(actor)
						elseif Shoot.aim and angGoal + 0.5 < ang and angGoal <= fov * 1.3 then
							why = string.format("goal wins %.1f<%.1f", angGoal, ang)
						elseif not best or ang < best.ang then
							best = { actor = actor, model = model, root = r, ang = ang, flatD = flatD, name = actorName(actor) }
						end
					end
				end
			end
		end
	end
	local held = nil
	if prev then
		for _, model in Mark.models() do
			local actor = Actors.GetFromCharacter(model)
			if actor == prev.actor then
				local r = ActorTargeting.GetActorRoot(actor)
				if r and not Mark.mateDown(actor, model) then
					local d = r.Position + Vector3.new(0, 1.5, 0) - cf.Position
					if d.Magnitude > 1 and d:Dot(look) > 0 then
						local ang = math.deg(math.acos(math.clamp(d.Unit:Dot(look), -1, 1)))
						if ang <= math.min(fov + 6, 16) then
							held = { actor = actor, model = model, root = r, ang = ang, flatD = flat(r.Position - ballPos).Magnitude, name = actorName(actor) }
						end
					end
				end
				break
			end
		end
	end
	if held and (not best or best.actor == held.actor or best.ang + 3 >= held.ang) then
		best = held
	end
	Mark.pa.skipWhy = (not best) and why or nil
	return best
end

Mark.passTick = function(character, root)
	local pa = Mark.pa
	local now = os.clock()
	if not CFG.PassAssist or liveOwnerId() ~= LocalPlayer.UserId or MatchSettings.IsGoalkeeperCharacter(character) then
		if not pa.live then
			pa.sel, pa.sol, pa.marks = nil, nil, nil
		end
		return
	end
	if pa.live or now - (pa.at or 0) < 0.1 then
		return
	end
	pa.at = now
	pa.marks = Mark.paList(root)
	pa.marksAt = now
	if (pa.markN or -1) ~= #pa.marks and now - (pa.markLog or 0) > 1 then
		pa.markN, pa.markLog = #pa.marks, now
		logFile("pass marks", #pa.marks)
	end
	local sel = Mark.paSelect(root)
	if not sel then
		if pa.sel and now - (pa.selAt or 0) > 0.2 then
			pa.sel, pa.sol = nil, nil
		end
		if pa.skipWhy and now - (pa.skipLog or 0) > 1.5 then
			pa.skipLog = now
			logFile("pass assist", "skip", pa.skipWhy)
		end
		return
	end
	pa.selAt = now
	if not pa.sel or pa.sel.actor ~= sel.actor then
		logFile("pass assist", "target", sel.name, "ang", string.format("%.1f", sel.ang), "dist", string.format("%.0f", sel.flatD))
	end
	pa.sel = sel
	local sol = Mark.paSolve(sel)
	if sol then
		pa.sol, pa.solAt = sol, now
	end
end

Mark.paRay = function(live)
	local cam = Workspace.CurrentCamera
	local camPos = cam and cam.CFrame.Position or Vector3.zero
	live.ray = {
		Origin = camPos,
		Direction = live.dir,
		CameraCFrame = CFrame.lookAt(camPos, camPos + live.dir),
		CameraFieldOfView = cam and cam.FieldOfView or 70,
		IsAirborne = false,
	}
end

-- The press: replaced by a script-held Lob whose aim ray the Reticle/packet overrides carry (live.ray).
Mark.paPress = function(forceSel, forceSol, tag, maxCharge)
	local pa = Mark.pa
	local char = LocalPlayer.Character
	if liveOwnerId() ~= LocalPlayer.UserId or not char or MatchSettings.IsGoalkeeperCharacter(char) then
		return false
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		return false
	end
	local sel = forceSel or pa.sel
	if not forceSel and not (sel and sel.root and os.clock() - (pa.selAt or 0) < 0.4) then
		sel = Mark.paSelect(root)
	end
	if not sel then
		return false
	end
	local sol = forceSol or ((pa.sol and pa.sel and pa.sel.actor == sel.actor and os.clock() - (pa.solAt or 0) < 0.3) and pa.sol or Mark.paSolve(sel))
	if not sol then
		logFile("pass assist", "press", "no solution", sel.name)
		return false
	end
	-- maxCharge: a forced pass under a deadline (blast, punch) charges as long as the time allows, not the full solve
	local charge = maxCharge and math.max(math.min(sol.charge, maxCharge), CFG.PassMinCharge or 0.1) or sol.charge
	local live = { sel = sel, sol = sol, at = os.clock(), charge = charge, dir = sol.dir, forced = forceSel ~= nil }
	Mark.paRay(live)
	pa.live = live
	pa.injecting = true
	local r = Mark.passIn.HandleInputBegan(Controls.CreateInput("Lob"), false)
	pa.injecting = false
	if r == false then
		pa.live = nil
		logFile("pass assist", "press", "start refused", tostring(r))
		return false
	end
	logFile("pass assist", "press", tag or "user", sel.name, "status", sol.status, "cross", tostring(sol.cross), "charge", string.format("%.3f", sol.charge), "dist", string.format("%.1f", sol.D), "along", string.format("%.1f", sol.along), "lat", string.format("%.1f", sol.lat), "apex", string.format("%.1f", sol.apex - sol.origin.Y), "t", string.format("%.2f", sol.t))
	task.spawn(function()
		local due = live.at + live.charge - 0.004
		while os.clock() < due and pa.live == live do
			local cam = Workspace.CurrentCamera
			local rr = live.sel and live.sel.root
			if cam and rr and not live.forced then
				local d = rr.Position + Vector3.new(0, 1.5, 0) - cam.CFrame.Position
				local ang = d.Magnitude > 1 and math.deg(math.acos(math.clamp(d.Unit:Dot(cam.CFrame.LookVector), -1, 1))) or 0
				if ang > 22 then
					pa.injecting = true
					Mark.passIn.CancelCharge()
					pa.injecting = false
					pa.live = nil
					logFile("pass assist", "cancel", "look away", string.format("%.0f", ang))
					return
				end
			end
			RunService.Heartbeat:Wait()
		end
		if pa.live == live then
			pa.injecting = true
			Mark.passIn.HandleInputEnded(Controls.CreateInput("Lob"))
			pa.injecting = false
		end
		task.delay(0.35, function()
			if pa.live == live then
				pa.live = nil
			end
		end)
	end)
	return true
end

-- Pass Assist ManualButton (UI keybind, unbound by default): no crosshair needed. Picks a teammate and fires the same legit
-- Lob (Pass.HandleInputBegan with the solved charge / yaw, real animation) through Mark.paPress.
-- Choice: the CLOSEST teammate that is not right next to us (PassManualNear) - a pass to a man standing beside us
-- is no pass; only when nobody else exists the near one gets it. Each candidate is solved with the real flight model
-- (Mark.paSolve); a lob that lands on an enemy / the keeper, hits the ceiling or cannot be placed ranks below the clean
-- ones, an enemy close to the receive point and a pass backwards from the enemy goal cost distance-equivalents.
Mark.paManual = function()
	local pa = Mark.pa
	local char = LocalPlayer.Character
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not (CFG.PassManual and char and root) or pa.live then
		return
	end
	if liveOwnerId() ~= LocalPlayer.UserId or MatchSettings.IsGoalkeeperCharacter(char) then
		return
	end
	if os.clock() - (pa.manualAt or 0) < 0.5 then
		return
	end
	local list = Mark.paList(root)
	if #list == 0 then
		logFile("pass manual", "no teammate")
		return
	end
	pa.manualAt = os.clock()
	local near = CFG.PassManualNear or 16
	local goal = enemyGoalPart()
	local toGoal = goal and unitOrNil(flat(goal.Position - root.Position))
	local foes = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and ActorTargeting.GetActorRoot(actor)
		if r then
			foes[#foes + 1] = r.Position
		end
	end
	-- pre-rank by distance only (solving every teammate is a full flight simulation each), then solve the best few
	table.sort(list, function(a, b)
		local fa, fb = a.flatD >= near, b.flatD >= near
		if fa ~= fb then
			return fa
		end
		if fa then
			return a.flatD < b.flatD
		end
		return a.flatD > b.flatD
	end)
	local best = nil
	for i = 1, math.min(#list, 5) do
		local sel = list[i]
		local sol = Mark.paSolve(sel)
		if sol then
			local tier = (sel.flatD >= near) and 0 or 3
			if sol.status ~= "ok" then
				tier += (sol.status == "short" or sol.status == "long") and 1 or 2
			end
			local score = tier * 1000 + (sel.flatD >= near and sel.flatD or (near - sel.flatD))
			local pressure = 0
			for _, fp in foes do
				if flat(fp - sol.land).Magnitude < 8 then
					pressure += 1
				end
			end
			score += pressure * 30
			local dirU = unitOrNil(flat(sel.root.Position - root.Position))
			if toGoal and dirU and dirU:Dot(toGoal) < -0.3 then
				score += 20
			end
			if not best or score < best.score then
				best = { sel = sel, sol = sol, score = score, pressure = pressure }
			end
		end
	end
	if not best then
		logFile("pass manual", "no solution", #list)
		return
	end
	local okP = Mark.paPress(best.sel, best.sol, "manual")
	logFile("pass manual", okP and "sent" or "refused", best.sel.name, "dist", string.format("%.0f", best.sel.flatD), "status", best.sol.status, "pressure", best.pressure, "score", string.format("%.0f", best.score), "cand", #list)
end

Mark.paInstall = function()
	local passIn = Mark.passIn or require(Client.Gameplay.Actions.Pass)
	Mark.passIn = passIn
	if Mark.paInstalled then
		return
	end
	Mark.paInstalled = true
	local oldBegan, oldEnded = passIn.HandleInputBegan, passIn.HandleInputEnded
	passIn.HandleInputBegan = function(input, processed, ...)
		if CFG.PassAssist and not processed and not Mark.pa.injecting and not Mark.pa.live and typeof(input) == "Instance" and (Controls.IsInput("Pass", input) or Controls.IsInput("Lob", input)) then
			local handled = Mark.paPress()
			if handled then
				return true
			end
		end
		return oldBegan(input, processed, ...)
	end
	passIn.HandleInputEnded = function(input, ...)
		-- the user's own release must not end our timed charge early
		if Mark.pa.live and typeof(input) == "Instance" and (Controls.IsInput("Pass", input) or Controls.IsInput("Lob", input)) then
			return true
		end
		return oldEnded(input, ...)
	end
end

Mark.paDraw = function(gy)
	local pa = Mark.pa
	if not (CFG.PassAssist and CFG.PassShow and Mark.pen and Mark.artPal) then
		return
	end
	local sel, sol = pa.sel, pa.sol
	if pa.live then
		sel, sol = pa.live.sel, pa.live.sol
	end
	local t = os.clock()
	local cam = Workspace.CurrentCamera
	-- chest-height, camera-facing, at least ~36 px. The old one was a 1.9-stud frame on the grass under the model
	-- (min 15 px) and only after a solved flight, so a teammate never read as a pass target.
	local marks = pa.marks
	if cam and marks and t - (pa.marksAt or 0) < 0.45 then
		local right, up = cam.CFrame.RightVector, cam.CFrame.UpVector
		for i = 1, #marks do
			local m = marks[i]
			if not (sel and sel.actor == m.actor) then
				Mark.cornerFrame(Mark.pen, m.root.Position, right, up, 0.5, Mark.artPal.lime, t, 0.15, 0, 0.4, 9, 12)
			end
		end
		if sel and sel.root then
			local kind = (sol and sol.ok) and "lime" or "limeWarn"
			Mark.cornerFrame(Mark.pen, sel.root.Position, right, up, 0.7, Mark.artPal[kind], t, 0.7, 0.05, 0.85, 13, 17)
		end
	end
	if not (sol and sol.pts and #sol.pts >= 2) or (not pa.live and t - (pa.solAt or 0) > 0.5) then
		return
	end
	local ballNow = Renderer.GetPosition()
	local shift = (ballNow and sol.origin) and (ballNow - sol.origin) or nil
	if shift and shift.Magnitude > 6 then
		shift = nil
	end
	Mark.trajArt(Mark.pen, sol.pts, sol.times, sol.land, sol.along3, gy, sol.ok and "lime" or "limeWarn", t, shift)
end

-- AutoShoot tab > Shot Types: drop candidates whose band the user excluded. The lob is keyed "chip". A flick strike needs
-- the bounce bands, so those stay legal there. An emptied pool simply means "no auto shot" (same path as no candidates).
Mark.shotFilter = function(pool)
	-- while a flick / volley is being aimed its own list decides (FlickBan), the normal list does not apply
	local flick = Mark.flickAim or Mark.aerial or Mark.flickStrike
	local ban = flick and CFG.FlickBan or CFG.ShotBan
	local sw = not flick and CFG.ShotWeight or nil
	if (type(ban) ~= "table" or next(ban) == nil) and not sw then
		return pool
	end
	ban = type(ban) == "table" and ban or {}
	local out = {}
	for i = 1, #pool do
		local p = pool[i]
		local key = p.lob and "chip" or (p.band == "mid" and "high" or p.band)
		-- a weight of 0% means never (the UI says so), not "least likely"; weights use the split key (curl / high)
		if not ban[key] and not (sw and sw[Mark.shotWKey(p)] == 0) then
			out[#out + 1] = p
		end
	end
	if #out == 0 and #pool > 0 and (not Mark.shotBanLog or os.clock() - Mark.shotBanLog > 2) then
		Mark.shotBanLog = os.clock()
		logFile("shoot ban", "every candidate excluded", #pool)
	end
	return out
end

-- Feint: our own charge is cancelled instead of released. Decided ONCE per charge when it starts:
-- Chance = roll FeintChance; Count = FeintCount feints in a row, then one real charge (the counter restarts).
-- The cancel happens at FeintAt, or at the moment YOU release if that comes first (the release is swallowed and becomes
-- the cancel: a timer alone lost the race against a human who lets go at the full charge, 0.35 s).
-- Never on FAKE / BOUNCE FAKE (shot name read from the solver); Smart Select: never once the enemy keeper has dived
-- (his dive is on cooldown: the feint has nothing left to bait and only burns the chance).
-- A feint applies to the PLAYER's own Kick charge (real input object) while we own the ball or owned it a moment ago
-- (a charge pressed just before the ball arrives). Scripted charges (volley / bicycle / flick / AutoKick) never feint.
-- Near a goal (either mouth, flat distance from our root < r) a feint is never worth it: the charge is the shot (user: < 20 studs).
Mark.nearMouth = function(p, mouths, r)
	for _, m in mouths do
		if flat(p - m).Magnitude < r then
			return true
		end
	end
	return false
end
Mark.feintNearGoal = function()
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		return false
	end
	local mouths = {}
	for _, g in { enemyGoalPart(), ourGoalPart() } do
		local lb, _, rb = goalMouthCorners(g)
		if lb and rb then
			mouths[#mouths + 1] = (lb + rb) * 0.5
		end
	end
	return Mark.nearMouth(root.Position, mouths, CFG.FeintGoalDist or 20)
end

Mark.feintEligible = function(own)
	local now = os.clock()
	-- a feint is part of AutoShoot: off with it, and only for a shot AutoShoot has actually solved (aim exists)
	if not (CFG.AutoShoot and Shoot.aim) then
		return false
	end
	if own then
		Mark.ownSeenAt = now
	end
	if Mark.aerial or Mark.forceBike or Mark.flickStrike or Mark.bike then
		return false
	end
	if (Mark.realChargeAt or 0) < (Mark.scriptChargeAt or 0) then
		return false
	end
	if Mark.feintNearGoal() then
		return false
	end
	return own or now - (Mark.ownSeenAt or -100) < 1.0
end

-- The once-per-press decision. It is keyed by the press (Mark.realChargeAt is set by every real Kick press), NOT by
-- per-charge flags: resetting those mid-charge (the tick skipped for a while, the charge flickering) made the same press
-- decide again, the counter restarted and every press fired a feint (log: "feint Count ... n 1" on 5 presses in a row).
Mark.feintBegin = function(mode)
	local id = Mark.realChargeAt or 0
	local fd = Mark.fd
	if fd and fd.id == id then
		return fd
	end
	local doIt
	if mode == "Chance" then
		doIt = math.random() < (CFG.FeintChance or 0.6)
	elseif (Mark.feintN or 0) < (CFG.FeintCount or 1) then
		doIt = true
	else
		Mark.feintN = 0
		doIt = false
	end
	fd = { id = id, doIt = doIt, done = false }
	Mark.fd = fd
	logFile("feint decide", mode, doIt and "feint" or "real", "n", Mark.feintN or 0, "of", CFG.FeintCount or 1)
	return fd
end

-- true = the charge was cancelled as a feint; false = no feint (the caller lets the shot go)
Mark.feintNow = function(why)
	local fd = Mark.fd
	local nm = Shoot.shotName
	-- no ball, nothing to feint: the cancel would only eat a charge, and in Count mode it still COUNTED (log: the ball was
	-- tackled away 0.3 s into a press decided as a feint, the release 0.35 s later "feinted" an empty charge, n 1 -> the
	-- next press was the "real" one: the player never saw a feint). The decision stays for when the ball is ours again.
	if not Mark.weOwn() then
		if fd and not fd.noBallLogged then
			fd.noBallLogged = true
			logFile("feint skip", "no ball", why)
		end
		return false
	end
	local skip = nil
	if Mark.feintNearGoal() then
		skip = "near goal" -- (the press was decided farther out and we ran in: no feint anymore)
	elseif (nm == "BOUNCE FAKE" and CFG.FeintSkipBounce ~= false) or ((nm == "FAKE" or nm == "FAKE CORNER") and CFG.FeintSkipFake ~= false) then
		skip = nm
	elseif CFG.FeintSmart ~= false and Mark.foeDiveLeft() > 0 then
		skip = "keeper dived"
	elseif CFG.FeintCompetitor ~= false then
		-- an outfield enemy close to the ball can just take it while the feint cancels and recharges: shoot instead
		local root = ActorTargeting.GetActorRoot(LocalPlayer)
		local ball = root and (Renderer.GetPosition() or root.Position)
		if root and ball then
			for _, model in Mark.models() do
				local a = Actors.GetFromCharacter(model)
				local r = a and a ~= LocalPlayer and not sameTeam(a) and not isGoalkeeper(a) and ActorTargeting.GetActorRoot(a)
				if r and flat(r.Position - ball).Magnitude <= (CFG.FeintCompetitorRange or 10) then
					skip = "enemy close"
					break
				end
			end
		end
	end
	if skip then
		if fd and not fd.skipLogged then
			fd.skipLogged = true
			logFile("feint skip", skip, why)
		end
		if fd then
			fd.doIt = false
		end
		return false
	end
	local inst = Mark.chargeInst()
	local held = inst and inst.GetHeldSeconds and inst.GetHeldSeconds() or 0
	if fd then
		fd.done = true
	end
	Shoot.feinted = true
	Mark.feintN = (Mark.feintN or 0) + 1
	ChargedKick.CancelCharge()
	setShootWhy("feint")
	logFile("feint", CFG.FeintMode or "Off", nm or "-", why, "held", string.format("%.2f", held), "n", Mark.feintN)
	return true
end

-- called from the ChargedKick.HandleInputEnded hook for the player's own release. Also decides here when no tick had
-- decided yet (the charge was too short to be seen, or the ball was not ours until the very end).
Mark.feintRelease = function()
	local mode = CFG.FeintMode or "Off"
	if mode == "Off" or not CFG.AutoShoot then
		return false
	end
	local fd = Mark.fd
	if not (fd and fd.id == (Mark.realChargeAt or 0)) then
		if not Mark.feintEligible(Mark.weOwn()) then
			return false
		end
		fd = Mark.feintBegin(mode)
	end
	if fd.done or not fd.doIt then
		return false
	end
	return Mark.feintNow("release")
end

-- every logic step, whether or not we own the ball right now
-- DIRECTION SPOOF (AutoShoot). The game replicates our charge aim to everybody (ActionRemoteProtocol.Update ->
-- KickChargeUpdated, the keeper's charge-path preview and every keeper script read it) and only freezes it AimLockSeconds
-- (0.1 s) before the full charge (ChargedKick updateAimLock -> LockAim). The release direction is ours (the namecall hook
-- already rewrites it; the server does not check it against the body facing - a shot with our back to the goal goes in).
-- So until the lock the replicated aim shows decoys: corners, the middle, a sweep across the mouth; the lock packet and
-- the release carry the real shot. The pattern is picked per shot from where the enemy keeper stands and what was used
-- last; the body can turn with the decoy, away from the goal or spin (TurnControl lock "GoKart", rank 5 > AimCharge 3).
Mark.spoofHist = {}
-- How long the aim / body may lie: the charge until the aim lock (AimLockSeconds before full charge), minus 0.05 s so the
-- real aim is replicated (30 Hz, ~0.11 s to the observers) before the lock freezes it
-- { fake aim time, body time } in seconds; Custom = the two sliders
-- Shot Curve preset: scales every curve the solver asks for (the game may not bend a shot as far as the sim does)
Mark.curveScale = function(curve)
	local m = CFG.ShotCurve
	if curve == nil or m == nil or m == "Full" then
		return curve
	end
	if m == "Off" then
		return nil
	end
	return curve * 0.5
end

Mark.spoofPresets = { Safe = { 0.06, 0.08 }, Normal = { 0.12, 0.15 }, Long = { 0.2, 0.24 } }

Mark.spoofWin = function(body)
	-- How long the aim / the body may lie. The lock freezes the aim AimLockSeconds before the max charge; the real aim has
	-- to be at the server ping/2 before that (+ a margin). Inside that ceiling the user sets the time (a longer lie = the
	-- shot may follow it: see the `shoot flight` log, `angle to solved` with decoy yes).
	local lock = (KickCore.Constants.MaximumChargeSeconds or 0.4) - (KickCore.Constants.AimLockSeconds or 0.1)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local pre = Mark.spoofPresets[CFG.DirSpoofPreset or "Normal"]
	local want
	if pre then
		want = body and pre[2] or pre[1]
	else
		want = body and (CFG.FaceSpoofTime or 0.15) or (CFG.DirSpoofTime or 0.12)
	end
	return math.min(want, lock - ping * 0.5 - 0.03)
end

-- weighted pattern pick. Pro Patterns: only what a human does with the camera. A curled shot: yaw-locked patterns only.
-- Patterns used in the last two shots weigh x0.3. Pure: `roll` is math.random().
Mark.spoofPro = { triple = true, reverse = true, mirror = true, late = true, drop = true, across = true, stair = true, lift = true }
Mark.spoofPick = function(pats, hist, proOnly, curved, roll)
	local total, list = 0, {}
	for name, p in pats do
		local w = ((proOnly and not Mark.spoofPro[name]) or (curved and not p.yawLock)) and 0 or p.w
		for i = 1, #hist do
			if hist[i] == name then
				w *= 0.3
			end
		end
		if w > 0 then
			total += w
			list[#list + 1] = { name, w }
		end
	end
	table.sort(list, function(x, y)
		return x[1] < y[1]
	end)
	local r, pick = roll * total, list[#list][1]
	for i = 1, #list do
		r -= list[i][2]
		if r <= 0 then
			pick = list[i][1]
			break
		end
	end
	hist[#hist + 1] = pick
	if #hist > 2 then
		table.remove(hist, 1)
	end
	return pick
end

Mark.spoofPlan = function()
	Mark.sp = nil
	if not CFG.DirSpoof or Mark.flickStrike or Mark.forceBike or Mark.aerial or Shoot.lob then
		return
	end
	if math.random() >= (CFG.DirSpoofChance or 1) then
		return
	end
	if CFG.DirSpoofSmart ~= false and Mark.foeDiveLeft() > 0 then
		logFile("spoof", "skip", "keeper dive spent")
		return
	end
	local g = enemyGoalPart()
	local a = Shoot.aim
	if not (g and a and typeof(a.Origin) == "Vector3" and typeof(a.Direction) == "Vector3") then
		return
	end
	local lb, lt, rb, _, along, n = goalMouthCorners(g)
	local O, D = a.Origin, a.Direction.Unit
	local den = D:Dot(n)
	if den > -0.05 then
		return
	end
	local t = (lb - O):Dot(n) / den
	if t <= 0 then
		return
	end
	local P = O + D * t
	local W, H = (rb - lb).Magnitude, lt.Y - lb.Y
	if W < 1 or H < 1 then
		return
	end
	local win = Mark.spoofWin(false)
	if win < 0.04 then
		return
	end
	local sr = math.clamp((P - lb):Dot(along) / W * 2 - 1, -1, 1)
	local hr = math.clamp((P.Y - lb.Y) / H, 0, 1)
	local rs = sr >= 0 and 1 or -1
	local sk = nil
	if Mark.gkRoot and Mark.gkRoot.Parent then
		sk = math.clamp((Mark.gkRoot.Position - lb):Dot(along) / W * 2 - 1, -1.5, 1.5)
	end
	-- steps = { side, seconds, side at the end (a sweep) }. A side is in HALF-GOALS RELATIVE TO THE REAL SHOT: +a = the real
	-- side, -a = the other one, "R" = the real point itself. The real shot is re-solved while we charge (the carried ball
	-- moves, the keeper moves: log `vs real 52 deg` mid-charge), so the decoy is rebuilt from the live real aim in
	-- Mark.spoofDir, not from the aim of the first frame.
	local pats = {
		-- the mirror corner the whole time: he leans the wrong way
		mirror = { w = 1 + ((sk and math.abs(sk - sr) < 0.5) and 1.5 or 0), steps = { { -0.8, win } } },
		-- the other side low, our side high, the other side high: a bot keeper follows every update
		swing = { w = 1.6, steps = { { -0.8, win / 3 }, { 0.6, win / 3 }, { -0.8, win / 3 } } },
		-- the middle: he stays where he is (best when he is already far from the real side)
		freeze = { w = (sk and math.abs(sk - sr) > 0.9) and 2 or 0.4, steps = { { 0, win } } },
		-- four quick hops: with a 30 Hz update stream every hop is one packet, he cannot settle on one side
		zigzag = { w = 1.6, steps = { { -0.85, win / 4 }, { 0.5, win / 4 }, { -0.5, win / 4 }, { 0.85, win / 4 } } },
		-- a sweep from our side to the far post: he chases it away from the real shot
		sweep = { w = 0.8, steps = { { 0.9, win, -0.9 } } },
		-- PRO TRIPLE (user: aim the real corner, flick to the other, come back): the real point first, the other corner up to
		-- the window end, then real again for the lock - the last flick is as late as the server allows (spoofWin)
		triple = { w = 3, steps = { { "R", win * 0.35 }, { -0.85, win * 0.65 } } },
		-- PRO REVERSE: the fake corner first, then across through the middle, then the real one at the lock
		reverse = { w = 2.5, steps = { { -0.85, win * 0.55 }, { 0, win * 0.45 } } },
		-- left, right, then the real one (made for a middle shot, high or low)
		late = { w = math.abs(sr) < 0.35 and 2.5 or 0, steps = { { 0.8, win / 2 }, { -0.8, win / 2 } } },
		-- VERTICAL (user: real top corner right, look at the bottom corner right or left): a step is { side, seconds, side
		-- at the end, height, height at the end }; height nil = the real one, "O" = the other half of the goal (low <-> high)
		-- DROP: the real point, then the same side in the other half
		drop = { w = 2.5, steps = { { "R", win * 0.3 }, { 0.85, win * 0.7, nil, "O" } } },
		-- ACROSS: the real point, then the other half AND the other side
		across = { w = 2.5, steps = { { "R", win * 0.3 }, { -0.85, win * 0.7, nil, "O" } } },
		-- STAIR: the other half on the other side, then the other half on the real side
		stair = { w = 1.8, steps = { { -0.85, win * 0.5, nil, "O" }, { 0.85, win * 0.5, nil, "O" } } },
		-- LIFT: the yaw never leaves the real shot (a curled shot is bent around its yaw), only the pitch lies
		lift = { w = 2, yawLock = true, steps = { { "R", win * 0.4, nil, "O" }, { "R", win * 0.6, nil, "R" } } },
	}
	-- a CURLED shot (|curve| >= SpoofCurveGuard) is bent around its yaw: only the yaw-locked pattern may lie (user: from the
	-- side, curling to the other side, the ball flew nowhere near the goal with the yaw patterns)
	local curved = math.abs(Shoot.curve or 0) >= (CFG.SpoofCurveGuard or 0.4)
	local pick = Mark.spoofPick(pats, Mark.spoofHist, CFG.DirSpoofPro ~= false, curved, math.random())
	local now = os.clock()
	Mark.sp = {
		t0 = now, endAt = now + win, steps = pats[pick].steps, O = O, lb = lb, along = along, n = n, W = W, H = H,
		fov = a.CameraFieldOfView, air = a.IsAirborne, name = pick, hr = hr, sr = sr, rs = rs, cs = sr, ch = hr, lt = now, sr0 = sr, D0 = D,
	}
	logFile("spoof", "plan", pick, "curve", string.format("%.2f", Shoot.curve or 0), "real s", string.format("%.2f", sr), "h", string.format("%.2f", hr), "keeper s", sk and string.format("%.2f", sk) or "-", "window", string.format("%.2f", win))
end

-- the REAL shot on the goal plane now (half-goals side, height 0..1) from the live Shoot.aim: the origin moves with us and
-- the solve changes mid-charge, the decoy is built around this and not around the first frame
Mark.spoofReal = function(sp)
	local a = Shoot.aim
	if not (a and typeof(a.Origin) == "Vector3" and typeof(a.Direction) == "Vector3") then
		return
	end
	local den = a.Direction:Dot(sp.n)
	if den > -0.05 then
		return
	end
	local t = (sp.lb - a.Origin):Dot(sp.n) / den
	if t <= 0 then
		return
	end
	local P = a.Origin + a.Direction * t
	sp.sr = math.clamp((P - sp.lb):Dot(sp.along) / sp.W * 2 - 1, -1, 1)
	sp.hr = math.clamp((P.Y - sp.lb.Y) / sp.H, 0, 1)
	sp.O = a.Origin
end

-- the decoy direction now (nil = real: after the window, or no plan). The aim travels to each step's side and ARRIVES
-- inside the step: speed = max(Fake Speed, distance / half of what is left of the step). With the fixed speed alone the
-- short presets never got there (Normal: 0.078 s for 1.85 half-goals at 14/s = it moved 1.1 and the window was over), the
-- keeper saw a slow drift off the real point and no fake corner at all - only Long (0.13 s) arrived.
Mark.spoofDir = function()
	local sp = Mark.sp
	if not sp then
		return nil
	end
	local now = os.clock()
	if now >= sp.endAt then
		return nil
	end
	Mark.spoofReal(sp)
	local rl = math.abs(sp.sr) >= 0.15 and (sp.sr > 0 and 1 or -1) or sp.rs
	local el = now - sp.t0
	local s, h, rem, acc = 0, sp.hr, 0.02, 0
	-- height tokens: nil / "R" = the real height, "O" = the other half of the goal, a number = that fraction
	local function hOf(tok)
		if tok == nil or tok == "R" then
			return sp.hr
		elseif tok == "O" then
			return sp.hr > 0.5 and 0.12 or 0.88
		end
		return tok
	end
	for i = 1, #sp.steps do
		local st = sp.steps[i]
		if el < acc + st[2] or i == #sp.steps then
			local f = st[3] and math.clamp((el - acc) / st[2], 0, 1) or 0
			s = st[1] == "R" and sp.sr or st[1] * rl
			if st[3] then
				s += (st[3] * rl - s) * f
			end
			h = hOf(st[4])
			if st[5] then
				h += (hOf(st[5]) - h) * f
			end
			rem = acc + st[2] - el
			break
		end
		acc += st[2]
	end
	local spd = CFG.DirSpoofSpeed or 14
	if sp.cs == nil or spd >= 40 then
		sp.cs, sp.ch = s, h
	elseif now > sp.lt then
		-- one straight move in the goal plane (metres), same arrival rule for side and height
		local dm = math.sqrt(((s - sp.cs) * sp.W * 0.5) ^ 2 + ((h - sp.ch) * sp.H) ^ 2)
		if dm > 1e-6 then
			local v = math.max(spd, dm / (sp.W * 0.5) / math.max(rem * 0.5, 0.02))
			local k = math.min(1, v * (sp.W * 0.5) * (now - sp.lt) / dm)
			sp.cs += (s - sp.cs) * k
			sp.ch += (h - sp.ch) * k
		end
	end
	sp.lt = now
	-- the decoy ray goes through (cs, ch) on the goal plane
	local Q = sp.lb + sp.along * (sp.W * (sp.cs + 1) * 0.5) + Vector3.new(0, sp.H * sp.ch, 0)
	sp.q = Q
	sp.lastDir = unitOrNil(Q - sp.O)
	return sp.lastDir
end

Mark.spoofRay = function()
	local d = Mark.spoofDir()
	if not d then
		return nil
	end
	local sp = Mark.sp
	return { Origin = sp.O, Direction = d, CameraCFrame = CFrame.lookAt(sp.O, sp.O + d), CameraFieldOfView = sp.fov, IsAirborne = sp.air }
end

-- every logic step: the body turn while the charge runs, cleanup when it is over
-- every logic step: cleanup when the charge is over (the body turn is Mark.faceTick)
Mark.spoofTick = function()
	local sp = Mark.sp
	if not sp then
		return
	end
	local now = os.clock()
	-- AutoShoot lost the shot mid-charge (re-solve failed, Shoot.aim cleared): the release is the camera's now, the decoy
	-- must not leak into it (the aim-ray hook would still hand the decoy to the game)
	if ChargedKick.IsCharging and ChargedKick.IsCharging() and not Mark.autoShotOn() then
		logFile("spoof", "drop", sp.name, "autoshoot off this kick", "held", string.format("%.2f", now - sp.t0))
		Mark.sp = nil
		return
	end
	if not (ChargedKick.IsCharging and ChargedKick.IsCharging()) and now - sp.t0 > 0.05 then
		logFile("spoof", "done", sp.name, "held", string.format("%.2f", now - sp.t0), "decoy packets", sp.sent or 0, "real in window", sp.real or 0, sp.realWhy or "-", "echo", sp.echo or 0)
		Mark.sp = nil
	end
end

-- BODY SPOOF. The body facing replicates to everybody for the whole charge (and before it); the shot direction is the
-- packet's, never checked against it (log: shots with the back to the goal score). A keeper reads the body first, so
-- the body lies: TurnControl lock "GoKart" (AimFacing rank 5 > Aim / AimCharge 3) on a pattern around the reference
-- (the real shot while charging, else their goal). Modes:
--   spin      full turns at FaceSpinSpeed, side rolled per activation
--   side      shoulders open ~70 deg to one side (the usual way to hide the corner)
--   lookoff   a look to one side, then the other, then the shot
--   away      back to the goal
--   decoy     faces the aim decoy of Direction Spoof (side without one)
--   smart     a random one of these per activation, re-rolled every 1.5-3 s, never the last two again
-- The body lies only inside Mark.spoofWin (until the aim lock), then it stands on the real shot until the kick.
-- When: charge (only while charging a shot), ball (whenever we have it), always (also without the ball).
Mark.faceModes = { "spin", "side", "lookoff", "away", "decoy" }
Mark.faceSet2 = { spin = true, side = true, lookoff = true, away = true, decoy = true }
Mark.faceHist = {}
Mark.facePick = function()
	local hist, cand = Mark.faceHist, {}
	for _, m in Mark.faceModes do
		if m ~= hist[1] and m ~= hist[2] then
			cand[#cand + 1] = m
		end
	end
	local m = cand[math.random(1, #cand)]
	table.insert(hist, 1, m)
	hist[3] = nil
	return m
end

Mark.faceActive = function(character)
	if not CFG.FaceSpoof or Mark.meKeeper() or Ragdoll.IsActorRagdolled(LocalPlayer) then
		return false
	end
	if Mark.slideBody() or ClientDodge.IsDribbling() or Mark.ak or Mark.volleyInput or Mark.aerial or Mark.forceBike or Mark.flickStrike then
		return false
	end
	if Mark.pa and Mark.pa.live then
		return false
	end
	local mm = Mark.move.mode
	if mm == "dodge" or mm == "dribble" then
		return false
	end
	local own = liveOwnerId() == LocalPlayer.UserId
	local when = CFG.FaceSpoofWhen or "charge"
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging() and true or false
	-- a kick AutoShoot does not own is struck from the body pose and the camera: no lie on it (any When mode)
	if own and charging and not Mark.autoShotOn() then
		return false
	end
	if when == "charge" then
		return own and charging
	elseif when == "ball" then
		return own
	end
	-- always: not while charging a kick without the ball (the AutoKick / volley aim needs the body)
	return own or not (ChargedKick.IsCharging and ChargedKick.IsCharging())
end

-- FORCED: the facing others see is the yaw of our root CFrame that CharacterReplication writes into every motion
-- entry (CharacterMotion.WriteEntry, byte 11 = atan2 of root.LookVector, sent every CharacterSendIntervalSeconds). The
-- TurnControl lock alone only sets the ground controller's FacingDirection, which turns the body at the TURN SPEED: a
-- jitter / flip faster than that never reaches the root, so the wire shows a small wobble (only spin read as real).
-- So the root is rotated directly (position kept) and the lock holds the controller on the same heading.
-- The body turns toward the lie at a limited rate (1440 deg/s = instant): a legit-looking turn, not a snap.
Mark.faceTurn = function(root, target, rate)
	local now = os.clock()
	local cur = Mark.faceCur
	if not cur or rate >= 1440 then
		cur = rate >= 1440 and target or (unitOrNil(flat(root.CFrame.LookVector)) or target)
	else
		local dt = math.clamp(now - (Mark.faceCurAt or now), 0, 0.1)
		local cosA = math.clamp(cur:Dot(target), -1, 1)
		local ang = math.acos(cosA)
		local step = math.rad(rate) * dt
		if ang <= step then
			cur = target
		else
			-- turn the short way, about Y
			local sgn = (cur.X * target.Z - cur.Z * target.X) >= 0 and 1 or -1
			local a = step * sgn
			local c, s = math.cos(a), math.sin(a)
			cur = Vector3.new(cur.X * c - cur.Z * s, 0, cur.X * s + cur.Z * c)
		end
	end
	Mark.faceCur, Mark.faceCurAt = cur, now
	Mark.faceSet(root, cur)
end

Mark.faceSet = function(root, face)
	Mark.faceNow = face
	TurnControl.LockAutoRotate("GoKart", face)
	local lv = root.CFrame.LookVector
	local lf = Vector3.new(lv.X, 0, lv.Z)
	if lf.Magnitude < 0.1 or lf.Unit:Dot(face) < 0.999 then
		local p = root.Position
		root.CFrame = CFrame.lookAt(p, p + face)
	end
end

-- The decoy as a lock-on on the goal: a broken ring turning round the point, a diamond that breathes, four inward ticks,
-- and an outer arc that burns down with the time the aim may still lie (when it is gone the aim is real again). From the
-- ball a dashed line of chevrons runs to it. The threat tint of kickPalette.armed, never the real-shot line colour.

-- SPRING BRACKETS (Direction Spoof fake aim point): four corners chase the decoy on a spring (overshoot, settle); every
-- arm is a lightning line, now and then a bolt arcs across an edge.
-- st = per-overlay state ({}), right = the goal's along axis, left = 0..1 of the lie left.
Mark.bracketArt = function(seg, q, right, left, t, st)
	local up = Vector3.new(0, 1, 0)
	local dt = math.clamp(t - (st.lastT or t), 0, 0.1)
	st.lastT = t
	if not st.bq or (st.bq - q).Magnitude > 40 then
		st.bq, st.bv = q, Vector3.zero
	end
	st.bv = st.bv + ((q - st.bq) * 260 - st.bv * 18) * dt
	st.bq = st.bq + st.bv * dt
	local p = st.bq
	-- small: the time the aim may still lie is the length of the arms (they draw back into the corners as it runs out)
	local s = 0.9
	local e = 0.9 * (0.45 + 0.55 * math.clamp(left, 0, 1))
	local ice = { Color3.fromRGB(150, 220, 255), Color3.fromRGB(215, 242, 255), Color3.fromRGB(90, 170, 255) }
	local corners = {}
	local seed = 0
	for _, sx in { -1, 1 } do
		for _, sy in { -1, 1 } do
			local cn = p + right * (sx * s) + up * (sy * s)
			corners[#corners + 1] = cn
			seed += 1
			Mark.boltLine(seg, cn, cn - right * (sx * e), t, seed, ice[2], 1, 1.3, 1)
			Mark.boltLine(seg, cn, cn - up * (sy * e), t, seed + 11, ice[2], 1, 1.3, 1)
		end
	end
	-- an arc across one edge, a new one every ~0.12 s, short-lived
	local slot = math.floor(t * 8)
	local f = (t * 8) % 1
	if f < 0.5 then
		local pairs4 = { { 1, 2 }, { 2, 4 }, { 4, 3 }, { 3, 1 } }
		local pr = pairs4[slot % 4 + 1]
		Mark.boltLine(seg, corners[pr[1]], corners[pr[2]], t, slot, ice[1], 1 - f * 1.6, 1.1, math.clamp(f * 5, 0, 1))
	end
end

Mark.spoofDraw = function(seg)
	local sp = Mark.sp
	local now = os.clock()
	if not (sp and sp.q and now < sp.endAt + 0.3) then
		return
	end
	sp.br = sp.br or {}
	Mark.bracketArt(seg, sp.q, sp.along, (sp.endAt - now) / math.max(sp.endAt - sp.t0, 0.05), now, sp.br)
end


-- PreSimulation: the controller turns the root during the physics step and CharacterReplication samples it in
-- PostSimulation; a Heartbeat write alone races that. Re-apply the facing right before the step.
Mark.faceStep = function()
	local fs, face = Mark.fs, Mark.faceNow
	if not (fs and face) then
		return
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if root then
		local lv = root.CFrame.LookVector
		local lf = Vector3.new(lv.X, 0, lv.Z)
		if lf.Magnitude < 0.1 or lf.Unit:Dot(face) < 0.999 then
			root.CFrame = CFrame.lookAt(root.Position, root.Position + face)
		end
	end
end

Mark.faceTick = function(character, root)
	local fs = Mark.fs
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging() or false
	if not (character and root) or not Mark.faceActive(character) then
		Mark.faceNow = nil
		Mark.faceCur = nil
		if fs then
			TurnControl.ReleaseAutoRotate("GoKart")
			Mark.fs = nil
		end
		return
	end
	local now = os.clock()
	if not fs then
		local mode = CFG.FaceSpoofMode or "smart"
		if mode ~= "smart" and not Mark.faceSet2[mode] then
			mode = "smart"
		end
		fs = { t0 = now, mode = mode, cur = mode == "smart" and Mark.facePick() or mode, sgn = math.random() < 0.5 and -1 or 1, repickAt = now + 1.5 + math.random() * 1.5 }
		Mark.fs = fs
		logFile("face spoof", "start", fs.cur, "when", CFG.FaceSpoofWhen or "charge")
	end
	if fs.mode == "smart" and now >= fs.repickAt then
		fs.cur, fs.repickAt, fs.sgn = Mark.facePick(), now + 1.5 + math.random() * 1.5, -fs.sgn
	end
	-- reference: the real shot while charging, else their goal, else our run
	local ref = nil
	if Shoot.aim and Shoot.aim.Direction and charging then
		ref = unitOrNil(flat(Shoot.aim.Direction))
	end
	if not ref then
		local g = enemyGoalPart()
		ref = g and unitOrNil(flat(g.Position - root.Position)) or unitOrNil(flat(root.CFrame.LookVector)) or Vector3.new(0, 0, 1)
	end
	-- The body only lies while the aim may lie. The game turns the body at a fixed rate toward the aim and the shot is
	-- struck from that pose (carry offset, stabilised direction): leaving it sideways at the release put the ball on
	-- the bar. After the window the body is on the real shot and stays there until the kick.
	local win = Mark.spoofWin(true)
	local rate = CFG.FaceSpoofSpeed or 720
	-- back on the real shot faster than it left: the pose has to be right at the release
	local back = rate >= 1440 and 1440 or math.max(rate * 2, 900)
	if charging then
		fs.chargeAt = fs.chargeAt or now
	else
		fs.chargeAt = nil
	end
	local p
	if fs.chargeAt then
		local el = now - fs.chargeAt
		if el >= win then
			Mark.faceTurn(root, ref, back)
			return
		end
		p = el / win
	else
		p = ((now - fs.t0) % 1.2) / 1.2
	end
	local cur, off = fs.cur, 0
	if cur == "decoy" then
		-- the body looks at the decoy point: the keeper reads body and aim as one
		local d = Mark.spoofDir()
		local f = d and unitOrNil(flat(d))
		if f then
			Mark.faceTurn(root, f, rate)
			return
		end
		cur = "side"
	end
	if cur == "spin" then
		off = fs.sgn * (now - fs.t0) * (CFG.FaceSpinSpeed or 3) * math.pi * 2
	elseif cur == "side" then
		-- shoulders open to one side: the usual way to hide the corner
		off = fs.sgn * math.rad(70)
	elseif cur == "lookoff" then
		-- a look to one side, then to the other, then the shot
		off = fs.sgn * math.rad(55) * (p < 0.5 and 1 or -1)
	elseif cur == "away" then
		-- back to goal
		off = math.pi
	end
	local c, s = math.cos(off), math.sin(off)
	Mark.faceTurn(root, Vector3.new(ref.X * c - ref.Z * s, 0, ref.X * s + ref.Z * c), rate)
end


Mark.feintTick = function(own)
	local mode = CFG.FeintMode or "Off"
	if own then
		Mark.ownSeenAt = os.clock()
	end
	local inst = mode ~= "Off" and CFG.AutoShoot and Mark.chargeInst()
	if not (inst and inst.IsCharging()) then
		Shoot.feinted = false
		return
	end
	if not Mark.feintEligible(own) then
		return
	end
	local fd = Mark.feintBegin(mode)
	if fd.done or not fd.doIt then
		return
	end
	-- the cancel must beat the game's own release: with a kick powerup it comes at 0.30 s, before Cancel At 0.32 (log:
	-- "feint decide ... feint", the shot left at 0.30, the feint only saw the player's late release -> "no ball")
	local held = inst.GetHeldSeconds()
	local at = math.min(CFG.FeintAt or 0.32, Mark.chargeMax() - 0.05)
	if held and held >= at then
		Mark.feintNow("timer")
	end
end

-- Why the FAKE family must not be used right now (nil = allowed).
Mark.fakeBan = function()
	if CFG.FakeAfterDiveBan ~= false then
		local left = Mark.foeDiveLeft()
		if left > 0 then
			return string.format("keeper dive cd %.1f", left)
		end
	end
	if CFG.FakeOnceThenShoot ~= false and Mark.bfOkAt then
		return "after bounce fake"
	end
	return nil
end

-- BounceFAKE bookkeeping, every step. Shot fired as BOUNCE FAKE (Start packet) -> if the ball is ours again within 7 s it
-- worked: no more fakes (the keeper has been moved / has dived: the next shot is a real one) until we lose the ball.
Mark.bfTrack = function()
	local now = os.clock()
	local own = liveOwnerId() == LocalPlayer.UserId
	local s = Mark.bfShot
	if s then
		if own and now - s > 0.4 then
			Mark.bfShot = nil
			Mark.bfOkAt = now
			Mark.bfLostAt = nil
			logFile("bounce fake", "ok - ball back after", string.format("%.2f", now - s), "-> real shot, fakes off until the ball is lost")
		elseif now - s > 7 or (not own and now - s > 0.6 and type(liveOwnerId()) == "number" and liveOwnerId() ~= 0 and liveOwnerId() ~= LocalPlayer.UserId) then
			Mark.bfShot = nil
			logFile("bounce fake", "failed", "owner", tostring(liveOwnerId()), "after", string.format("%.2f", now - s))
		end
	end
	if Mark.bfOkAt then
		if own then
			Mark.bfLostAt = nil
		else
			Mark.bfLostAt = Mark.bfLostAt or now
		end
		if (Mark.bfLostAt and now - Mark.bfLostAt > 1) or now - Mark.bfOkAt > 20 then
			Mark.bfOkAt, Mark.bfLostAt = nil, nil
		end
	end
end

-- BounceFAKE. A shot whose launch reads as a shot on goal (the unwalled flight lands in the mouth) but which, through
-- the game's own physics (Physics.NewState + GetStateAtTime with the charge boundary world: walls, floor, spin),
-- hits a wall, turns around and comes back to us. Candidates: aim points across the mouth, a few with curve; keep those
-- the sampler says are walled, simulate the real flight, require a horizontal reversal (the wall), no goal crossing
-- before it, and a return that we reach (run + receive box) clearly before any enemy field player.
-- The map walls are NOT in BarricadeStrikes.GetReplicatedBoundaryParts (that is only the placed barricades): they are
-- the box solids of the ball's boundary world (Physics.BuildBoundaryWorld -> world.Solids, IsGoalBoundary marks the goal
-- frame). flightBlocked() therefore never saw a map wall - BounceFAKE reported "walled 0" for every candidate.
Mark.worldBlocked = function(pts, world)
	local solids = world and world.Solids
	if type(solids) ~= "table" or not pts or #pts < 2 then
		return false
	end
	local pad = Vector3.new(1, 1, 1) * (Physics.BallRadius or 1)
	-- Mark.wallList: the VERTICAL solids only. The map's "walls" listed in the log include 129x1x180 slabs at y=32.4 (the
	-- ground) and y=81.4 (the ceiling): every flight touches those, which made "walled" meaningless in the first version.
	local list = Mark.wallListFor == solids and Mark.wallList
	if not list then
		list = {}
		for j = 1, #solids do
			local s = solids[j]
			if s and s.CFrame and s.HalfSize then
				local h = s.HalfSize
				local axis = (h.X <= h.Y and h.X <= h.Z) and s.CFrame.RightVector or ((h.Y <= h.Z) and s.CFrame.UpVector or s.CFrame.LookVector)
				if math.abs(axis.Y) < 0.7 then
					list[#list + 1] = s
				end
			end
		end
		Mark.wallList, Mark.wallListFor = list, solids
	end
	for i = 2, #pts do
		local a, b = pts[i - 1], pts[i]
		for j = 1, #list do
			local s = list[j]
			if Physics.GetSegmentOrientedBoxEnterAlpha(a, b, s.CFrame, s.HalfSize + pad) then
				return true
			end
		end
	end
	return false
end

Mark.bounceFake = function(c)
	if not c.world then
		return nil, "noworld"
	end
	if Mark.bfWorld ~= c.world and (not Mark.bfWorldAt or os.clock() - Mark.bfWorldAt > 60) then
		Mark.bfWorld = c.world
		Mark.bfWorldAt = os.clock()
		local sol = c.world.Solids or {}
		local n, goalN = 0, 0
		local lines = {}
		for _, s in sol do
			if s.IsGoalBoundary then
				goalN += 1
			else
				n += 1
				if #lines < 40 and s.CFrame and s.HalfSize then
					lines[#lines + 1] = string.format("%s|%s", fmtV(s.CFrame.Position), fmtV(s.HalfSize * 2))
				end
			end
		end
		logFile("bounce world", "walls", n, "goalSolids", goalN, "ceil", tostring(c.world.CeilingY), "goal", fmtV(c.bottom), "face", fmtV(c.face))
		for _, l in lines do
			logFile("bounce wall", l)
		end
	end
	local cache = Mark.bfCache
	if cache and os.clock() - cache.at < 0.6 and (c.root.Position - cache.us).Magnitude < 0.6 and cache.force == c.force then
		return cache.pack, cache.why
	end
	local packR, whyR = Mark.bounceFakeRaw(c)
	Mark.bfCache = { at = os.clock(), us = c.root.Position, force = c.force, pack = packR, why = whyR }
	return packR, whyR
end

Mark.bounceFakeRaw = function(c)
	local Shoot = c.Shoot
	if flat(c.start - c.bottom).Magnitude > (CFG.BounceFakeRange or 110) then
		return nil, "far"
	end
	if not c.force and (Shoot.bounceRoll or 1) >= (CFG.BounceFakeChance or 0.08) then
		return nil, "roll"
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local root = c.root
	local us = root.Position
	local runSp = (Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(root.Parent), false) or 24)
	local rcv = HitboxSettings.Receive
	local hiR = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + c.radius
	local foes = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) and ActorTargeting.GetActorRoot(actor)
		if r then
			foes[#foes + 1] = { p = r.Position, s = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false) or 24 }
		end
	end
	local function depthOf(p)
		return (p - c.bottom):Dot(c.face)
	end
	local function sideOf(p)
		return flat(p - c.low):Dot(c.lateral)
	end
	-- Aim points on the wall around the goal, not in the mouth: just above the bar (the wall rises above the frame),
	-- and just outside the posts. {lateral fraction of the post, height above the goal floor}. To the keeper's read of the
	-- launch they are a high shot / a shot at the corner.
	local mh = c.mouthH
	local plan = {
		{ 0, mh + 1.5, nil }, { -0.5, mh + 1.5, nil }, { 0.5, mh + 1.5, nil }, { -0.9, mh + 1.5, nil }, { 0.9, mh + 1.5, nil },
		{ 0, mh + 4, nil }, { -0.5, mh + 4, nil }, { 0.5, mh + 4, nil }, { -0.9, mh + 4, nil }, { 0.9, mh + 4, nil },
		{ 0, mh + 8, nil }, { -0.6, mh + 8, nil }, { 0.6, mh + 8, nil },
		{ -1.12, 3, nil }, { 1.12, 3, nil }, { -1.12, 7, nil }, { 1.12, 7, nil },
		-- more wall points: between the posts and the bar, wide of the frame, high on the wall
		{ -0.25, mh + 1.5, nil }, { 0.25, mh + 1.5, nil }, { -0.75, mh + 1.5, nil }, { 0.75, mh + 1.5, nil },
		{ -0.25, mh + 4, nil }, { 0.25, mh + 4, nil }, { -0.75, mh + 6, nil }, { 0.75, mh + 6, nil },
		{ -1.3, 3, nil }, { 1.3, 3, nil }, { -1.3, 10, nil }, { 1.3, 10, nil }, { -1.12, 11, nil }, { 1.12, 11, nil },
		{ 0, mh + 12, nil }, { -0.4, mh + 12, nil }, { 0.4, mh + 12, nil },
	}
	-- curved variants: the bend alone can take the flight into a wall the straight line misses
	if CurvedKicks.IsEnabled() then
		-- { lateral fraction of the post, height above the bar (or an absolute 3 studs beside a post) }
		for _, e in { { 0, mh + 1.5 }, { -0.6, mh + 1.5 }, { 0.6, mh + 1.5 }, { 0, mh + 4 }, { -0.9, mh + 4 }, { 0.9, mh + 4 }, { -1.12, 3 }, { 1.12, 3 }, { -1.12, 8 }, { 1.12, 8 }, { 0, mh + 8 }, { -1.3, 5 }, { 1.3, 5 } } do
			plan[#plan + 1] = { e[1], e[2], 0.85 }
			plan[#plan + 1] = { e[1], e[2], -0.85 }
		end
	end
	local nil0 = c.fail and c.fail.cross or 0
	local velNil0 = c.fail and c.fail.vel or 0
	local saved = Shoot.simCap
	Shoot.simCap = (Shoot.sims or 0) + #plan
	local tried, walled, noRet, goalIn, foeWins = 0, 0, 0, 0, 0
	local best = nil
	local t0 = Workspace:GetServerTimeNow()
	for _, cand in plan do
		local point = c.bottom + c.up * (cand[2] + (CFG.BounceFakeHeight or 0)) + c.lateral * (cand[1] * c.post)
		local look = point - c.camPos
		if look.Magnitude < 1 then
			continue
		end
		local pack = c.packShot(look.Unit, cand[3], "fake", false)
		if not pack then
			continue
		end
		tried += 1
		if math.abs(pack.side or 99) > c.post + 1.6 or (pack.land - c.bottom):Dot(c.up) > mh + 14 + (CFG.BounceFakeHeight or 0) then
			continue
		end
		if not (pack.pts and (Mark.worldBlocked(pack.pts, c.world) or flightBlocked(pack.pts, c.goal))) then
			continue
		end
		walled += 1
		if walled > (CFG.BounceFakeMaxSim or 8) then
			break
		end
		Shoot.slice()
		local st = Physics.NewState(pack.from, pack.vel, Physics.BallRadius, t0, pack.spin or Vector3.zero)
		if type(st) ~= "table" then
			continue
		end
		st.LastKickerUserId = LocalPlayer.UserId
		local v0f = unitOrNil(flat(pack.vel))
		local pts, times = { pack.from }, { 0 }
		local bounceT, crossedGoal = nil, false
		local cand2 = nil
		for i = 1, (CFG.BounceFakeSteps or 70) do
			local t = i * 0.06
			local s = Physics.GetStateAtTime(st, t0 + t, c.world)
			local p = s.Position
			if typeof(p) ~= "Vector3" then
				break
			end
			pts[#pts + 1] = p
			times[#times + 1] = t
			local v = s.Velocity
			if not bounceT then
				if depthOf(p) < c.radius and math.abs(sideOf(p)) < c.post + 1 and (p - c.bottom):Dot(c.up) < mh then
					crossedGoal = true
					break
				end
				if typeof(v) == "Vector3" and v0f then
					local vf = flat(v)
					if vf.Magnitude > 3 and vf.Unit:Dot(v0f) < 0.3 then
						bounceT = t
					end
				end
			elseif t > bounceT + 0.12 and typeof(v) == "Vector3" and v.Magnitude < 85 and p.Y - us.Y <= hiR then
				-- Back TO US: we may step up to 10 studs for it, no more (the first version let us "run" 60 studs after a
				-- ball that went somewhere else and called that a return).
				local slack = flat(p - us).Magnitude - math.min(runSp * 0.9 * math.max(t - 0.3, 0), CFG.BounceFakeRun or 14)
				local score = slack + t * 0.8
				if slack <= (CFG.BounceFakeSlack or 3.5) and (not cand2 or score < cand2.score) then
					cand2 = { slack = slack, score = score, t = t, p = p }
				end
			end
		end
		if crossedGoal then
			goalIn += 1
		elseif not bounceT or not cand2 then
			noRet += 1
		else
			local lost = false
			for _, f in foes do
				local fs = flat(cand2.p - f.p).Magnitude - f.s * 0.85 * math.max(cand2.t - 0.3, 0)
				if fs < cand2.slack - 0.5 then
					lost = true
					break
				end
			end
			if lost then
				foeWins += 1
			elseif not best or cand2.score < best.score then
				pack.bfake = true
				pack.inside = true
				pack.pts = pts
				pack.times = times
				pack.reach = 9
				pack.fromBall = false
				pack.aimPoint = point
				best = { pack = pack, slack = cand2.slack, score = cand2.score, t = cand2.t, bt = bounceT, p = cand2.p }
				if cand2.slack <= 0.8 then
					break
				end
			end
		end
	end
	Shoot.simCap = math.max(saved or 0, Shoot.sims or 0)
	local info = string.format("tried %d/%d walled %d noReturn %d goal %d foe %d nil cross %d vel %d", tried, #plan, walled, noRet, goalIn, foeWins, (c.fail and c.fail.cross or 0) - nil0, (c.fail and c.fail.vel or 0) - velNil0)
	if best then
		return best.pack, string.format("%s | wall t %.2f back at %.2f slack %.1f", info, best.bt, best.t, best.slack)
	end
	return nil, info
end

-- ManualTackle target: the enemy carrier inside CFG.ManualRadius. Returns aim, speed multiplier, {char, root}, how.
-- how = "solve" (a real intercept inside the 0.6..TackleSpeed multiplier window) or "best" (no window: the carrier is
-- too close/too far for the solver - slide at where he will be mid hitbox, multiplier clamped to the legal range).
Mark.manualAim = function(character, root)
	local oid = liveOwnerId()
	if type(oid) ~= "number" or oid == 0 or oid == LocalPlayer.UserId then
		return nil
	end
	local player, croot = enemyCarrier(oid)
	if not player or typeof(croot) ~= "Instance" then
		return nil
	end
	local cch = Actors.GetCharacter(player)
	if flat(croot.Position - root.Position).Magnitude > (CFG.ManualRadius or 26) then
		return nil
	end
	local solved = solveIntercept(root, croot, cch, tackleTuning())
	if solved and solved.aim and solved.mult then
		return solved.aim, solved.mult, { char = cch, root = croot }, "solve"
	end
	local pos, rawVel = Mark.carrierPose(croot, cch)
	local t = C.HitboxDelaySeconds + C.HitboxSeconds * 0.35
	local to = flat(pos + rawVel * t - root.Position)
	local aim = unitOrNil(to)
	if not aim then
		return nil
	end
	local mHi = math.max(0.4, CFG.TackleSpeed)
	local mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6)
	local mult = math.clamp((to.Magnitude - Mark.slideBox()) / math.max(Mark.dumpTravel(t), 1), mLo, mHi)
	return aim, mult, { char = cch, root = croot }, "best"
end

-- Who counts as "ours": 3 = party member (RankedState.Get().Party.MemberUserIds), 2 = club mate (ClubsState.GetClub()),
-- 1 = Roblox friend (Player:IsFriendsWith, fetched off-thread). Cached 4 s.
Mark.friendTier = function(actor)
	local uid = actor and actor.UserId
	if type(uid) ~= "number" then
		return 0
	end
	local c = Mark.friendCache
	if not c then
		c = {}
		Mark.friendCache = c
	end
	local now = os.clock()
	local e = c[uid]
	if e and now - e.t < 4 then
		return e.tier
	end
	local tier = 0
	Mark.rankedMod = Mark.rankedMod or require(Client.Interface.RankedState)
	local st = Mark.rankedMod.Get()
	local party = st and st.Party
	if party and type(party.MemberUserIds) == "table" and table.find(party.MemberUserIds, uid) then
		tier = 3
	end
	if tier == 0 then
		Mark.try(function()
			Mark.clubsMod = Mark.clubsMod or require(Client.Interface.ClubsState)
			local club = Mark.clubsMod.GetClub()
			local budget = 600
			local function scan(t, depth)
				if type(t) ~= "table" or depth > 3 or budget <= 0 then
					return false
				end
				for k, v in t do
					budget -= 1
					if (type(v) == "number" and v == uid and (type(k) ~= "string" or k:find("User") or k:find("Member") or k:find("Id"))) or (type(k) == "number" and k == uid) or (type(k) == "string" and k == tostring(uid)) then
						return true
					end
					if type(v) == "table" and scan(v, depth + 1) then
						return true
					end
				end
				return false
			end
			if club and scan(club, 0) then
				tier = 2
			end
		end)
	end
	Mark.rbxFriends = Mark.rbxFriends or {}
	if tier == 0 then
		local f = Mark.rbxFriends[uid]
		if f == nil then
			Mark.rbxFriends[uid] = false
			task.spawn(function()
				local ok, res = Mark.try(function()
					return LocalPlayer:IsFriendsWith(uid)
				end)
				Mark.rbxFriends[uid] = ok and res == true
			end)
		elseif f then
			tier = 1
		end
	end
	c[uid] = { t = now, tier = tier }
	return tier
end

-- FAKE shot. A normal shot at goal whose flight passes through a teammate's Receive box: the preview (and the keeper
-- reading the replicated launch) says "goal", the ball is received by the mate (Receiving.Resolve: a teammate's Shot
-- is a clean Receive, TeammateKickIgnoresSpeedThreshold) and the keeper has already dived. Candidates: mates in front
-- of their goal, slow, with no enemy near them or on the pass. The aim is iterated (<= 4 sims) until the flight
-- crosses the mate's Receive box AND the same flight still ends inside the mouth. Returns pack, info.
Mark.fakeShot = function(c)
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local Shoot = c.Shoot
	local rcv = HitboxSettings.Receive
	local lo = rcv.CFrameOffset.Y - rcv.Size.Y * 0.5
	local hi = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5
	local bodyR = rcv.Size.X * 0.5
	local function depthOf(p)
		return (p - c.bottom):Dot(c.face)
	end
	local function sideOf(p)
		return flat(p - c.low):Dot(c.lateral)
	end
	local Ds = depthOf(c.start)
	local sS = sideOf(c.start)
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local mates, foes = {}, {}
	local dg = { team = 0, down = 0, fast = 0, depth = 0, lat = 0, foe = 0, dMin = 999, dMax = -999 }
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and ActorTargeting.GetActorRoot(actor)
		if r and not isGoalkeeper(actor) then
			if sameTeam(actor) then
				dg.team += 1
				if Mark.mateDown(actor, model) then
					dg.down += 1
				else
					-- Moving mates are fine: his pose is projected to the moment the ball gets there (first guess from the
					-- distance, refined from the simulated flight time below). Only a sprint across the line is too uncertain.
					local v = flat(r.AssemblyLinearVelocity)
					if v.Magnitude > (CFG.FakeMateSpeed or 38) then
						dg.fast += 1
					else
						local tFly = flat(r.Position - c.start).Magnitude / 95
						local M = r.Position + v * (ping + tFly)
						local Dm = depthOf(M)
						local sM = sideOf(M)
						dg.dMin, dg.dMax = math.min(dg.dMin, Dm), math.max(dg.dMax, Dm)
						local slop0 = CFG.FakeSlop or 3.5
						if not (Dm > 6 - slop0 and Dm < Ds - 2 and Dm <= (CFG.FakeMaxDepth or 100) + slop0 and flat(M - c.start).Magnitude >= 6) then
							dg.depth += 1
						else
							local f = Ds / (Ds - Dm)
							local sg = sS + (sM - sS) * f
							-- straight line may miss the mouth: curve (FAKE CORNER) can still bend through him into the post
							if math.abs(sg) > c.post * (CFG.FakeLatMul or 1.5) + slop0 then
								dg.lat += 1
							else
								mates[#mates + 1] = { actor = actor, root = r, v = v, spd = v.Magnitude, M = M, Dm = Dm, sM = sM, sg = sg, f = f, off = math.abs(sg) > c.post - 1.2, tier = Mark.friendTier(actor), name = actorName(actor) }
							end
						end
					end
				end
			else
				foes[#foes + 1] = { p = r.Position, v = flat(r.AssemblyLinearVelocity), s = Mark.mover and Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false) or 26, y = r.Position.Y }
			end
		end
	end
	-- an enemy next to the mate takes the ball (Ownership: whoever's Receive box it enters first)
	for i = #mates, 1, -1 do
		for _, f in foes do
			if flat(f.p - mates[i].M).Magnitude < (CFG.FakeFoeRadius or 7) then
				dg.foe += 1
				table.remove(mates, i)
				break
			end
		end
	end
	if #mates == 0 then
		return nil, string.format("no mate (team %d down %d fast %d depth %d lat %d foe %d D %.0f..%.0f of Ds %.0f)", dg.team, dg.down, dg.fast, dg.depth, dg.lat, dg.foe, dg.dMin, dg.dMax, Ds)
	end
	local prio = CFG.PrioritizeFriends ~= false
	-- Friends first, then the mates a line through him ends inside the posts for (small |sg|), a mate close to the goal last
	-- among equals: the old order was "nearest to the goal first", the steepest shot with the keeper on top of it.
	table.sort(mates, function(a, b)
		if prio and a.tier ~= b.tier then
			return a.tier > b.tier
		end
		if a.off ~= b.off then
			return not a.off
		end
		local sa, sb = math.abs(a.sg) + math.max(0, 14 - a.Dm) * 0.4, math.abs(b.sg) + math.max(0, 14 - b.Dm) * 0.4
		return sa < sb
	end)
	local chance = CFG.FakeChance or 0.12
	if prio and mates[1].tier > 0 then
		chance = math.min(chance * 2.2, 0.35)
	end
	if not c.force and (Shoot.fakeRoll or 1) >= chance then
		return nil, string.format("roll %.2f >= %.2f", Shoot.fakeRoll or 1, chance)
	end
	local slop = CFG.FakeSlop or 3.5
	local latLim = math.max(bodyR - 0.5, 1.1) + slop * 0.4
	local saved = Shoot.simCap
	Shoot.simCap = (Shoot.sims or 0) + ((Mark.dtAvg or 0) > 0.028 and 30 or 60)
	local result, info = nil, "none"
	local function crossOf(pack, mate)
		if not (pack and pack.pts) then
			return nil
		end
		local Q, tQ = nil, nil
		for i = 2, #pack.pts do
			local d0, d1 = depthOf(pack.pts[i - 1]), depthOf(pack.pts[i])
			if d0 >= mate.Dm and d1 <= mate.Dm and d0 ~= d1 then
				local a = (d0 - mate.Dm) / (d0 - d1)
				Q = pack.pts[i - 1]:Lerp(pack.pts[i], a)
				tQ = (pack.times[i - 1] or 0) + ((pack.times[i] or 0) - (pack.times[i - 1] or 0)) * a
				break
			end
		end
		if not Q then
			return nil
		end
		local side = pack.side or 99
		local landH = (pack.land - c.bottom):Dot(c.up)
		return {
			pack = pack, Q = Q, tQ = tQ,
			latErr = mate.sM - sideOf(Q),
			yRel = Q.Y - mate.root.Position.Y,
			inMouth = math.abs(side) <= c.post - 0.35 and landH >= -0.3 and landH <= c.mouthH - c.radius - 0.9,
			corner = math.abs(side) >= c.post * 0.5,
		}
	end
	-- The mate's pose at the moment the ball reaches him. The first guess (distance / 95) is off by the real flight time (arc,
	-- curve, drag): a mate running at 20 studs/s is 2-4 studs away from it, which is the whole lateral window. After each
	-- simulation his pose is recomputed for the simulated time tQ and the same flight is re-read at his new depth.
	local function retime(mate, tQ)
		local M = mate.root.Position + mate.v * (ping + tQ)
		local moved = (M - mate.M).Magnitude
		if moved > 1e-3 then
			local Dm = depthOf(M)
			mate.M, mate.Dm, mate.sM = M, Dm, sideOf(M)
			mate.f = Ds / math.max(Ds - Dm, 1)
			mate.sg = sS + (mate.sM - sS) * mate.f
		end
		return moved
	end
	local function aimAt(mate, aimSide, aimH, curve)
		local point = c.bottom + c.up * math.clamp(aimH, 0.4, c.mouthH - 2.2) + c.lateral * aimSide
		local look = point - c.camPos
		if look.Magnitude < 1 then
			return nil
		end
		local pack = c.packShot(look.Unit, curve, "fake", false)
		local hit = crossOf(pack, mate)
		if not hit then
			return nil
		end
		if mate.spd > 1 then
			for _ = 1, 2 do
				if retime(mate, hit.tQ) < 0.4 then
					break
				end
				local again = crossOf(pack, mate)
				if not again then
					break
				end
				hit = again
			end
		end
		hit.point, hit.curve, hit.aimSide, hit.aimH = point, curve, aimSide, aimH
		hit.latOk = math.abs(hit.latErr) <= latLim
		hit.yOk = hit.yRel >= lo - slop * 0.3 and hit.yRel <= hi + slop * 0.2
		return hit
	end
	local function foeBlocks(hit, mate)
		for _, f in foes do
			for i = 2, #hit.pack.pts do
				local t = hit.pack.times[i] or 0
				if t > hit.tQ then
					break
				end
				local q = hit.pack.pts[i]
				local need = math.max(flat(q - (f.p + f.v * math.min(t, 0.3))).Magnitude - (bodyR + c.radius), 0)
				if q.Y - f.y <= hi + c.radius + 1.5 and need <= f.s * 0.85 * math.max(t - 0.3, 0) then
					return true
				end
			end
		end
		return false
	end
	local function take(hit, mate, corner)
		if foeBlocks(hit, mate) then
			info = "foe on pass"
			return false
		end
		local pack = hit.pack
		pack.fake = true
		pack.fakeCorner = (CFG.FakeCorner ~= false and hit.corner) or nil
		pack.reach = 9
		pack.mate = mate
		pack.aimPoint = hit.point
		pack.fromBall = false
		result = pack
		info = string.format("%s %s tier %d d %.0f lat %.1f y %.1f curve %s land %.1f/%.1f", mate.name, hit.corner and "corner" or "line", mate.tier, mate.Dm, hit.latErr, hit.yRel, hit.curve and string.format("%.2f", hit.curve) or "-", pack.side or 0, hit.aimH or 0)
		return true
	end
	-- AIM AT THE MATE, then make the flight a goal. The flight has to pass through his body (a point inside his Receive
	-- box at his depth) AND finish inside the mouth. Unknowns: the aim point on the goal plane (side, height) - two
	-- numbers - against two requirements (lateral and vertical position at his depth), solved by damped Newton steps
	-- on the real flight sim. The free choices are then what makes it not a template, all taken from the shot roll so
	-- the picture does not flicker frame to frame: where in his body the ball goes (height, a little sideways) and
	-- which curve (none / +-0.45 / +-0.85) - each curve is another arc through the SAME mate with a different landing
	-- in the mouth. The corner is not a goal, it is just where a bent arc sometimes ends (the name follows the landing).
	local function frac(x)
		return x - math.floor(x)
	end
	local r0 = Shoot.fakeRoll or 0.5
	local u1, u2, u3 = frac(r0 * 7.31 + 0.17), frac(r0 * 13.7 + 0.43), frac(r0 * 29.3 + 0.71)
	local curves = { false }
	if CurvedKicks.IsEnabled() and CFG.FakeCurve ~= false then
		for _, v in { 0.85, -0.85, 0.45, -0.45 } do
			curves[#curves + 1] = v
		end
		-- the first curve tried follows the roll, so the cheap early exit does not always favour the same side
		if u2 > 0.5 then
			curves[2], curves[3] = curves[3], curves[2]
			curves[4], curves[5] = curves[5], curves[4]
		end
	end
	local yLoT, yHiT = lo + 1.0, hi - 0.8
	-- Damped Newton on (aim side, aim height) against (lateral, vertical) error at his depth, always stepping from the BEST
	-- aim so far: a step that did not improve is halved instead of being followed (the old 3 blind steps diverged on a curve and
	-- stopped), and a step that misses the goal plane is also halved instead of ending the search.
	local function solveCurve(mate, curve, yT, latWant)
		local aSide = mate.sg + latWant * mate.f
		local aH = 2.4
		local bestH, bestS, bestAS, bestAH = nil, math.huge, aSide, aH
		local step = 0.85
		for it = 1, 5 do
			local h = aimAt(mate, aSide, aH, curve or nil)
			if not h and it == 1 then
				aSide = math.clamp(aSide, -(c.post - 1.5), c.post - 1.5)
				bestAS = aSide
				h = aimAt(mate, aSide, aH, curve or nil)
			end
			if h then
				local eLat = h.latErr + latWant
				local eY = yT - h.yRel
				local s = math.abs(eLat) + 0.5 * math.abs(eY)
				if s < bestS then
					bestH, bestS, bestAS, bestAH = h, s, aSide, aH
					if math.abs(eLat) <= 0.6 and math.abs(eY) <= 0.9 then
						break
					end
				else
					step *= 0.5
				end
			elseif bestH then
				step *= 0.5
			else
				break
			end
			if not bestH then
				break
			end
			local eL = bestH.latErr + latWant
			local eV = yT - bestH.yRel
			aSide = bestAS + eL * mate.f * step
			aH = math.clamp(bestAH + eV * mate.f * step, 0.5, c.mouthH - 2.2)
		end
		if bestH then
			bestH.res = bestS
		end
		return bestH
	end
	local pool, tried, blocked = {}, 0, 0
	local worst = nil -- the closest miss, for the log
	for mi = 1, math.min(#mates, 3) do
		local mate = mates[mi]
		-- a different spot of his body for each mate (the roll is reused with an offset)
		local yT = yLoT + (yHiT - yLoT) * frac(u1 + mi * 0.37)
		local latWant = (frac(u2 + mi * 0.21) - 0.5) * bodyR * 0.7
		for _, curve in curves do
			if #pool >= 4 then
				break
			end
			tried += 1
			local h = solveCurve(mate, curve, yT, latWant)
			if h and (not worst or (h.res or 99) < (worst.res or 99)) then
				worst = h
			end
			if h and h.pack.inside and h.inMouth and h.latOk and h.yOk then
				if foeBlocks(h, mate) then
					blocked += 1
				else
					local k = h.curve and math.abs(h.curve) or 0
					pool[#pool + 1] = { hit = h, mate = mate, w = k == 0 and 1.0 or (k < 0.6 and 0.9 or 0.7) }
				end
			end
		end
		if #pool > 0 then
			break
		end
	end
	if #pool > 0 then
		local total = 0
		for _, e in pool do
			total += e.w
		end
		local x, pick = u3 * total, pool[1]
		for _, e in pool do
			x -= e.w
			if x <= 0 then
				pick = e
				break
			end
		end
		take(pick.hit, pick.mate, pick.hit.corner)
		info = info .. string.format(" pool %d/%d", #pool, tried)
	else
		info = blocked > 0 and "foe on pass" or string.format("miss (%d solves)", tried)
		if worst then
			info = info .. string.format(" best lat %.1f/%.1f y %.1f in %s mouth %s", worst.latErr, latLim, worst.yRel, tostring(worst.pack.inside == true), tostring(worst.inMouth == true))
		end
	end
	Shoot.simCap = math.max(saved or 0, Shoot.sims or 0)
	return result, info
end

-- A teammate who is stunned, ragdolled or frozen cannot contest anything: CompetitorCheck must not yield to him.
-- Stun.IsCharacterStunned(model) / Ragdoll.IsActorRagdolled(actor, model) / FreezeIce.IsCharacterFrozen(model) read the
-- replicated server-time deadlines (the same ones the game's own press checks use). TTL 0.1 s per model.
-- Returns down, secondsLeft (0 when unknown).
Mark.mateDown = function(actor, model)
	if not model then
		return false, 0
	end
	local c = Mark.downCache
	if not c then
		c = setmetatable({}, { __mode = "k" })
		Mark.downCache = c
	end
	local now = os.clock()
	local e = c[model]
	if e and now - e.t < 0.1 then
		return e.down, e.left
	end
	local down, left = false, 0
	Mark.stunMod = Mark.stunMod or require(Modules.Characters.Stun)
	local stunned = Mark.stunMod.IsCharacterStunned(model)
	if stunned then
		down, left = true, 0.5
	end
	local rag = Ragdoll.IsActorRagdolled(actor, model)
	if rag then
		down = true
		local untilT = Ragdoll.GetRagdolledUntil(actor)
		if type(untilT) == "number" then
			left = math.max(left, untilT - Workspace:GetServerTimeNow())
		else
			left = math.max(left, 0.5)
		end
	end
	Mark.iceMod = Mark.iceMod or require(Modules.Characters.FreezeIce)
	local frozen = Mark.iceMod.IsCharacterFrozen(model)
	if frozen then
		down, left = true, math.max(left, 1)
	end
	c[model] = { t = now, down = down, left = left }
	return down, left
end

-- A field teammate (not the keeper, not stunned / ragdolled / frozen) within `radius` of `pos`, or nil.
Mark.mateNear = function(pos, radius)
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and sameTeam(actor) and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
			local ar = ActorTargeting.GetActorRoot(actor)
			if ar and flat(ar.Position - pos).Magnitude <= radius then
				return actor
			end
		end
	end
	return nil
end

-- DRIBBLE SHIELD (user: "it slides when he has his dribble and does nothing when he has none"). A carrier answers a
-- slide with his dribble (iframe + SuccessfulDodgeSpeedBoost), so:
--   his dribble covers our box (iframe) or is ready with Perfect Mode on -> no slide;
--   spent (cooldown runs past our box) / no ball / his own slide / locked -> slide on TackleNakedConf (he can only run);
--   ready with Perfect Mode off -> TackleConfidence (the strict number for a man who can still dribble).
-- Sets Mark.tackleNeed / Mark.tackleDrib for the confidence test that follows. Returns true = hold the slide.
Mark.tackleShield = function(player, ch, solved)
	local now = os.clock()
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local hitAt = now + (solved.eta or C.HitboxDelaySeconds) + ping * 0.5
	local ds, rec = Mark.dribState(player, ch, hitAt, true)
	Mark.tackleDrib = ds
	-- the confidence the state asks for: he cannot dribble (spent / no ball) -> the naked number; he cannot even move
	-- (down) -> any window; a dribble that is still possible -> the strict one
	Mark.tackleNeed = ds == "down" and 0.15 or ((ds == "spent" or ds == "noball" or ds == "slide" or ds == "locked") and (CFG.TackleNakedConf or 0.35) or (CFG.TackleConfidence or 0))
	-- no slide into a man who is charging an attack either (it only fed his dribble / shot; AutoBlock blocks the shot)
	if Mark.foeCharging(player.UserId) then
		Mark.tackleDrib = "charge"
		return true
	end
	local hold = ds == "iframe" or (ds == "ready" and CFG.TacklePerfect ~= false)
	if hold and now - (Mark.todLog or 0) > 0.8 then
		Mark.todLog = now
		logFile("tackle shield", actorName(player), ds, rec and string.format("iframe %.2f cd %.2f hit %.2f", rec.untilT - now, rec.cdUntil - now, hitAt - now) or "never dribbled", "conf", string.format("%.2f", solved.conf or 0))
	end
	return hold
end

Mark.tackleGate = function(character, root, player, ch, solved)
	if not CFG.AutoBlock then
		return true, "noblock"
	end
	local now = os.clock()
	local eta = solved.eta or C.HitboxDelaySeconds
	local key = (typeof(player) == "Instance" and player:IsA("Player") and player.UserId) or nil
	do
		local dsG = Mark.dribState(player, ch, now + eta, true)
		if dsG == "spent" or dsG == "slide" or dsG == "locked" then
			return true, "naked"
		end
	end
	-- our kick is on him (charging, or the run-up): the slide waits. Kick first - his Dodge against it opens "naked"
	-- above; a slide into a ready Dodge was 84 of 115 misses.
	do
		local ap = Mark.akApproach
		if Mark.ak or (ap and now - ap.at < 0.15 and ap.phase == "run") then
			return false, "kick"
		end
	end
	local g = Mark.defendGoal()
	local P = solved.serverPos
	if not (g and P) then
		return true, "nogoal"
	end
	local u = unitOrNil(flat(g.Position - P))
	local rel = flat(root.Position - P)
	local along = u and rel:Dot(u) or 0
	local holding = along > 0 and rel.Magnitude <= Mark.kickReach() + 1.5
	-- Priority between the tackle and AutoBlock (CFG.TackleVsBlock):
	--   "block"  - AutoBlock first: the tackle waits while the block is actually on him (it is moving us, or we already
	--              stand in kick reach), for at most TackleHoldMax s, and never when the block cannot act (far, mate, sliding).
	--   "smart"  - the tackle waits only when the AutoKick is about to fire (the v89 behaviour: almost always free).
	--   "tackle" - never waits.
	-- The pre-v89 gate waited for EVERY carrier whether or not the block / kick could act: the tackle did nothing.
	local mode = CFG.TackleVsBlock or "block"
	if mode == "tackle" then
		return true, "free"
	end
	-- The block / AutoKick only hold the tackle for a carrier they can actually kick: one who moves away from us (or just
	-- dribbled off) is not waited for - the tackle goes now (the kick would not be pressed for him either: akTry "leaving").
	do
		local hr = ch and ch:FindFirstChild("HumanoidRootPart")
		local awayDir = unitOrNil(-rel)
		local away = hr and awayDir and flat(hr.AssemblyLinearVelocity):Dot(awayDir) or 0
		if away > (CFG.AutoKickAway or 3) or (ch and now - ((Mark.akDrib or {})[ch] or -9) < 0.9 and away > -1) then
			return true, "leaving"
		end
	end
	if mode == "smart" then
		local d = rel.Magnitude
		local ap = Mark.akApproach
		local kickLive = CFG.AutoKick ~= false and ((ap and now - ap.at < 0.15 and ap.conf >= (CFG.AutoKickConf or 0.55) and d <= Mark.kickReach() + 12) or (Mark.ak and true) or false)
		if not kickLive then
			return true, "free"
		end
		return false, "hold"
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local mySpd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
	if type(mySpd) ~= "number" then
		mySpd = 16
	end
	if along < -1 and rel.Magnitude > Mark.kickReach() + 2 and (solved.spd or 0) >= mySpd * 0.85 then
		return true, "escape"
	end
	if not holding and flat(g.Position - P).Magnitude <= (CFG.TackleGoalZone or 40) then
		return true, "goal"
	end
	local marking = Mark.blockMarkAt and now - Mark.blockMarkAt < 0.2
	if not (holding or (Mark.move.mode == "block" and not marking)) then
		return true, "free"
	end
	local who = key or ch
	local h = Mark.tackleHold
	if not h or h.who ~= who or now - h.last > 0.5 then
		h = { who = who, since = now, last = now }
		Mark.tackleHold = h
	end
	h.last = now
	if now - h.since > (CFG.TackleHoldMax or 0.8) then
		return true, "timeout"
	end
	return false, holding and "hold" or "block"
end

Mark.ballStop = function(why)
	if Mark.move.mode == "ball" then
		Mark.ballStopWhy = why
		Mark.moveStop("ball")
	end
end

-- Ball path from the renderer's authoritative movement state through Physics.GetStateAtTime (rolling damping,
-- bounces, walls). Dense 0.05 s for the first 1.2 s (slide/jump/volley windows), then 0.1 s until the state says the
-- ball is at rest (Mode Resting / speed under Physics StopSpeed-ish), capped at 8 s. No fixed "2 s ahead" point.
-- MAGNET (dump: Magnet.DurationSeconds 5, MagnetMotion.GetPullAcceleration = flat unit to the holder * PullAcceleration *
-- a power fraction by distance, applied by the SERVER to a loose ball). The client Physics state has no such force: the
-- path from the last state is a straight line, every new server state bends it again - the planner chased ghosts.
-- The pull strength is not in the client dump: measured from consecutive server states (the velocity the plain physics
-- predicts at the new state's start vs the velocity the server sent). The path is then integrated with the pull toward
-- each holder (his pose + velocity, 0.5 s), Air / Rolling damping 0.5 / 2 from Physics.Constants, the height from the
-- plain sim; it ends at the holder's receive box.
Mark.magnetBend = function(state, world, now, samples, ts)
	local me = Mark.magEst or {}
	Mark.magEst = me
	if me.state ~= state then
		local ps = me.state
		if ps and me.world and type(state.StartedAt) == "number" and type(ps.StartedAt) == "number" and typeof(state.InitialVelocity) == "Vector3" then
			local dtS = state.StartedAt - ps.StartedAt
			if dtS > 0.01 and dtS < 0.5 then
				local sp = Physics.GetStateAtTime(ps, state.StartedAt, me.world)
				if sp and typeof(sp.Velocity) == "Vector3" then
					local a = flat(state.InitialVelocity - sp.Velocity).Magnitude / dtS
					if a > 3 and a < 400 then -- a kick / touch is a jump of 40+ st/s in one tick: not a pull
						me.A = me.A and (me.A * 0.6 + a * 0.4) or a
						me.at = os.clock()
					end
				end
			end
		end
		me.state, me.world = state, world
	end
	local nowS = Workspace:GetServerTimeNow()
	local pulls = {}
	for uid, m in Mark.magnets do
		if type(m.endsAt) ~= "number" or m.endsAt <= nowS then
			Mark.magnets[uid] = nil
		elseif not m.suspended then
			local pl = playerOf(uid)
			local r = pl and ActorTargeting.GetActorRoot(pl)
			if r then
				pulls[#pulls + 1] = { p = r.Position, v = flat(r.AssemblyLinearVelocity), endsAt = m.endsAt }
			end
		end
	end
	if #pulls == 0 or not me.A or os.clock() - (me.at or 0) > 1.5 then
		if #pulls > 0 and (not Mark.magLog or os.clock() - Mark.magLog > 1) then
			Mark.magLog = os.clock()
			logFile("magnet path", "no pull measured", "A", me.A and string.format("%.0f", me.A) or "-", "holders", #pulls)
		end
		return nil -- no measured pull yet: the plain path
	end
	local s0 = Physics.GetStateAtTime(state, now, world)
	if not (s0 and typeof(s0.Position) == "Vector3" and typeof(s0.Velocity) == "Vector3") then
		return nil
	end
	local n0 = #samples
	local floorY = math.huge
	for i = 1, n0 do
		floorY = math.min(floorY, samples[i].Y)
	end
	local hint = 2
	local function yAt(t)
		if n0 < 2 or t >= ts[n0] then
			return samples[n0].Y
		end
		while hint < n0 and ts[hint] < t do
			hint += 1
		end
		local a, b = ts[hint - 1], ts[hint]
		return samples[hint - 1].Y + (samples[hint].Y - samples[hint - 1].Y) * (b > a and (t - a) / (b - a) or 0)
	end
	local half = HitboxSettings.Receive.Size.X * 0.5
	local p, v = s0.Position, flat(s0.Velocity)
	local outS, outT = { samples[1] }, { 0 }
	local rest, t, DT = false, 0, 0.05
	while t < 3 do
		t += DT
		local acc, done = Vector3.zero, false
		for _, q in pulls do
			if nowS + t < q.endsAt then
				local d = flat(q.p + q.v * math.min(t, 0.5) - p)
				local m = d.Magnitude
				if m <= half then
					done = true
				elseif m > 1e-3 then
					acc += d / m * me.A
				end
			end
		end
		local y = yAt(t)
		local damp = (y <= floorY + 0.6) and 2 or 0.5
		v += (acc - v * damp) * DT
		p = Vector3.new(p.X + v.X * DT, y, p.Z + v.Z * DT)
		outS[#outS + 1] = p
		outT[#outT + 1] = t
		if done then
			break
		end
		if acc.Magnitude < 1e-3 and v.Magnitude < 0.6 then
			rest = true
			break
		end
	end
	if not Mark.magLog or os.clock() - Mark.magLog > 1 then
		Mark.magLog = os.clock()
		logFile("magnet path", "pull", string.format("%.0f", me.A), "holders", #pulls, "steps", #outS, "end", fmtV(outS[#outS]), "rest", tostring(rest))
	end
	return { samples = outS, ts = outT, rest = rest }
end

Mark.ballPathRaw = function(root)
	local pos = Renderer.GetTargetPosition(nil, root.Position) or Renderer.GetMainMatchPosition()
	if typeof(pos) ~= "Vector3" then
		return nil
	end
	local samples, ts = { pos }, { 0 }
	local state, world
	if Mark.ballSrcId then
		state, world = Renderer.GetMovementStateById(Mark.ballSrcId)
		if state and typeof(state.Position) == "Vector3" then
			pos = state.Position
			samples[1] = pos
		end
	else
		state, world = Renderer.GetMovementState()
	end
	if world then
		Mark.lastWorld = world -- static per arena: flickShot needs it while the ball is carried (no movement state then)
	end
	-- Renderer.GetBoundaryWorld is nil when no arena is registered (goal replay / intermission): the game itself
	-- guards it. Physics.GetStateAtTime indexes world.Solids -> "attempt to index nil with 'Solids'" every frame.
	if state and not world then
		state = nil
		if not Mark.noWorldLog or os.clock() - Mark.noWorldLog > 5 then
			Mark.noWorldLog = os.clock()
			logFile("ball world", "nil: no boundary world, path skipped")
		end
	end
	local memo = Mark.ballMemo
	-- Callers only read the arrays. The old memo died at 40 ms, so below ~25 fps every frame re-ran the sim
	-- (weak-pc log: ballPath p90 9 ms, one stall 386 ms). Same state and the ball has not moved: reuse.
	local rough = Renderer.GetTargetVelocity(nil, root.Position)
	if memo and os.clock() - memo.at < 0.09 and (pos - memo.samples[1]).Magnitude < 1.0 and (memo.state == state or (typeof(rough) == "Vector3" and (rough - memo.vel).Magnitude < 8)) then
		return pos, memo.vel, memo.samples, memo.ts, true, memo.rest
	end
	local vel = nil
	local rest = false
	if state then
		local now = CharacterMotionSmoothing.GetSmoothedServerTime()
		local s0 = Physics.GetStateAtTime(state, now, world)
		vel = s0 and s0.Velocity
		local spd0 = typeof(vel) == "Vector3" and vel.Magnitude or 0
		-- GetStateAtTime integrates up to the asked time, so 90 queries out to 8 s is quadratic. A shot crosses
		-- inside 3 s; a roller is at rest long before 5 s. Fine steps only inside the slide window.
		local horizon = spd0 > 28 and 3.2 or 5.2
		local t, prev = 0, pos
		while t < horizon do
			t += (t < 0.7 - 1e-6) and 0.05 or ((t < 2.2) and 0.1 or 0.2)
			local s = Physics.GetStateAtTime(state, now + t, world)
			local p = s and s.Position
			if typeof(p) ~= "Vector3" then
				break
			end
			samples[#samples + 1] = p
			ts[#ts + 1] = t
			local v = s.Velocity
			local vm = typeof(v) == "Vector3" and v.Magnitude or 0
			-- a flick / lob is slow at the apex and still in the air: only a ball back down near the start height is resting
			-- only a ball back at the start height counts as stopped; a lob is slow at the apex and must keep falling.
			-- t > 0.3 so the first samples of a lob we just started tracking are not cut off
			local grounded = p.Y <= samples[1].Y + 0.8
			if s.Mode == "Resting" or vm < 0.6 or (grounded and vm < 2 and t > 0.3) then
				rest = true
				break
			end
			prev = p
		end
		if not Mark.pathLog or os.clock() - Mark.pathLog > 2 then
			Mark.pathLog = os.clock()
			logFile("ball path", "steps", #samples, "spd", string.format("%.0f", spd0), "rest", tostring(rest))
		end
	end
	if state and Mark.magnets and next(Mark.magnets) then
		local bent = Mark.magnetBend(state, world, CharacterMotionSmoothing.GetSmoothedServerTime(), samples, ts)
		if bent then
			samples, ts, rest = bent.samples, bent.ts, bent.rest
		end
	end
	if typeof(vel) ~= "Vector3" then
		vel = Renderer.GetTargetVelocity(nil, root.Position)
	end
	vel = typeof(vel) == "Vector3" and vel or Vector3.zero
	Mark.ballMemo = state and { state = state, at = os.clock(), samples = samples, ts = ts, vel = vel, rest = rest } or nil
	return pos, vel, samples, ts, state ~= nil, rest
end

-- ONE path per logic frame (and ball source): the log showed ballPath called 5-6 times a frame (every agent asks) with the 0.09 s
-- memo missing whenever the ball moves > 1 stud a frame (any shot): avg 0.65 ms/call, 41 ms of every second. Callers only read.
Mark.ballPath = function(root)
	local f = Mark.ballFrame
	if f and f.id == Mark.logicId and f.src == Mark.ballSrcId and f.root == root then
		return f[1], f[2], f[3], f[4], f[5], f[6]
	end
	local a, b, c, d, e, g = Mark.ballPathRaw(root)
	Mark.ballFrame = { id = Mark.logicId, src = Mark.ballSrcId, root = root, a, b, c, d, e, g }
	return a, b, c, d, e, g
end

-- Jump rise time to lift the root by r studs: vy0 = sqrt(2 g H) (CharacterControllers JumpHeight), ballistic.
Mark.riseT = function(r)
	local g = Workspace.Gravity
	if type(g) ~= "number" or g < 10 then
		g = 196.2
	end
	local H = Mark.jumpH or 7.2
	r = math.clamp(r, 0, H)
	local v0 = math.sqrt(2 * g * H)
	return (v0 - math.sqrt(math.max(v0 * v0 - 2 * g * r, 0))) / g
end

-- Volley: press Kick only when the game's own VolleyOpportunity.GetEvaluation(char) is non-nil (Shoot.HandleInputBegan
-- then claims with GetClaim and the arrival time; DelayRelease waits for arrival). Release with the same input
-- object (ChargedKick.IsChargeInput compares identity). Rising in a jump lifts the miss-angle gate (Evaluate v161).
-- Volley only when it is worth losing a clean reception: an opponent can reach the contact point about as soon
-- as we can (threat), or we are in shooting range of their goal. A free grounded ball is received, not struck.
Mark.volleyAimAt = function(from)
	local goal = enemyGoalPart()
	if not goal then
		return nil
	end
	local lb, lt, rb, rt = goalMouthCorners(goal)
	if not (lb and lt and rb and rt) then
		return unitOrNil(goal.Position - from)
	end
	local bottom = (lb + rb) * 0.5
	local rise = (lt + rt) * 0.5 - bottom
	local up = rise.Magnitude > 0.4 and rise.Unit or Vector3.yAxis
	local lateral = unitOrNil(flat(rt - lt)) or Vector3.xAxis
	local half = flat(rt - lt).Magnitude * 0.5 - Physics.BallRadius
	local keeper = keeperSide(bottom + up * 2, lateral, false)
	local side = (keeper >= 0) and -1 or 1
	local target = bottom + up * math.min(rise.Magnitude * 0.35, 4) + lateral * (side * half * 0.7)
	return unitOrNil(target - from), target
end

-- ===== AIR INTERCEPT ================================================================================================
-- Its own module (CFG.AirIntercept; also on with AutoBall / AutoBlock when AirWithBall / AirWithBlock). The volley /
-- bicycle press: VolleyLockOn.Evaluate (dump) gives an opportunity when
--   * the ball is in the air (> GroundedBallClearance 4 above the ground) or rolls faster than 1.25x walk speed,
--   * an OPPONENT's flight is >= MinimumOpponentFlightSeconds 0.25 old (own flight 0.15),
--   * the ball is coming at our root (velocity . (ball - root) <= 0) and enters our FrontAssist box (5.5 x 5.25 x 6,
--     centre 1.5 ahead / 0.45 down of the root; swept by OUR flat velocity capped at the ball's flat speed) within
--     MaximumApproachSeconds 0.4,
--   * the miss angle atan(missDistance / boxDistanceNow) <= 6 deg (opponent's flight) / 10 deg (else), +3 deg on the server
--     (ServerValidationMissAngleSlackDegrees, with our pose recorded at the prompt),
--   * a NEW prompt with ApproachSeconds < ReactionSeconds 0.25 and missDistance > 1.5 is dropped: be in place early.
-- The first claim locks the ball (MovementState.VolleyUserId), the server re-checks with competitors = nil.
-- So the old reactive code (press only when the game already offered it, through the contested / receivable gates of
-- volleyPlan) never put us where the offer happens: 2 presses in two sessions. This module PLANS the meet - run, jump
-- (the root carries the box up 7.2 st: a high ball, a flick over the defender), face the incoming ball - and presses the
-- moment the offer exists. No "earlier than everyone" gate; the enemy ETA is logged only.
Mark.airOn = function()
	return CFG.AirIntercept == true or (CFG.AirWithBall ~= false and CFG.AutoBall == true) or (CFG.AirWithBlock ~= false and CFG.AutoBlock == true)
end

Mark.airBusy = function()
	return Mark.airPlan ~= nil and os.clock() - Mark.airPlan.seen < 0.2
end

Mark.airEnd = function(why)
	if Mark.airFaced then
		Mark.airFaced = nil
		TurnControl.ReleaseAutoRotate("Aim")
	end
	if Mark.airPlan then
		logFile("air", "end", why)
		Mark.moveStop("air")
	end
	Mark.airPlan = nil
	Mark.airMemo = nil
end

-- the meet point of an offer: the path sample at the game's ApproachSeconds
Mark.volleyMeet = function(root, ev)
	local _, _, samples, ts = Mark.ballPath(root)
	if not samples then
		return root.Position
	end
	for i = 1, #samples do
		if ts[i] >= (ev.ApproachSeconds or 0) then
			return samples[i]
		end
	end
	return samples[#samples]
end

-- Is this ball ours to strike? (user rules)
--   enemy's ball (pass, flick, lob, shot): always - the first press takes it from him;
--   teammate's pass: only at their goal (VolleyGoalZone) with an enemy within VolleyPressRadius of the meet (bicycle at
--     goal before the enemy gets it), else he passed it to us to receive;
--   our own / nobody's ball: only above the receive box (a ball AutoBall can just walk into is received).
-- an ENEMY shot whose path ends in our mouth: the volley / bicycle is the answer whatever the height (a body-height shot is
-- not "a ground ball"; the height gate is for balls in midfield)
Mark.airGoalShot = function(root, kicker)
	if not (kicker and kicker ~= LocalPlayer and not sameTeam(kicker)) or not Mark.defendGoal() then
		return false
	end
	local _, _, samples, ts = Mark.ballPath(root)
	return samples ~= nil and Mark.goalThreat(samples, ts) ~= nil
end

Mark.airWant = function(root, B, kicker, floorY)
	-- AIR intercept: only a ball that is in the air at the meet. A ball rolling on the grass (hip height of ours -2) is
	-- AutoBall's / the body's: the old "foe ball: always strike" punted flat passes in midfield (user log). Ground rest of
	-- the ball centre is ~ floor - 2.1; the game's own "grounded" line is 4 above the ground (GroundedBallClearance).
	if B.Y - floorY < (CFG.AirMinHeight or 1.5) and not Mark.airGoalShot(root, kicker) then
		return false, string.format("ball on the ground h %.1f", B.Y - floorY)
	end
	-- user rule: near EITHER goal (we or the meet point within CompetitorGoalZone) every flying ball is ours to take
	local z = CFG.CompetitorGoalZone or 45
	if z > 0 then
		for _, gp in { Mark.defendGoal(), enemyGoalPart() } do
			if gp and (flat(B - gp.Position).Magnitude <= z or flat(root.Position - gp.Position).Magnitude <= z) then
				return true, "goal zone"
			end
		end
	end
	if kicker ~= nil and kicker ~= LocalPlayer and not sameTeam(kicker) then
		return true, "foe ball"
	end
	if kicker ~= nil and kicker ~= LocalPlayer then
		local goal = enemyGoalPart()
		local goalD = goal and flat(goal.Position - B).Magnitude or math.huge
		local foeD = math.huge
		for _, model in Mark.models() do
			local actor = Actors.GetFromCharacter(model)
			if actor and actor ~= LocalPlayer and not sameTeam(actor) and not Mark.mateDown(actor, model) then
				local r = ActorTargeting.GetActorRoot(actor)
				if r then
					foeD = math.min(foeD, flat(r.Position - B).Magnitude)
				end
			end
		end
		if goalD <= (CFG.VolleyGoalZone or 90) and foeD <= (CFG.VolleyPressRadius or 20) then
			return true, "mate pass"
		end
		return false, string.format("mate pass to receive goalD %.0f foe %.0f", goalD, foeD)
	end
	local rcv = HitboxSettings.Receive
	local top = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + (Physics.BallRadius or 1)
	if B.Y - floorY > top then
		return true, "free high"
	end
	return false, string.format("free low h %.1f", B.Y - floorY)
end

-- The ball path on a 0.025 s grid (1.9 s), with who kicked it. A flick in the wind-up (the flicker still owns it) is
-- Mark.lobPath (no-touch samples lifted +500).
Mark.airPath = function(root)
	local DT, N = 0.025, 77
	local own = liveOwnerId()
	local lb = Mark.lob
	if lb and os.clock() < lb.untilT and type(own) == "number" and own == lb.uid then
		local pts, src = Mark.lobPath(root, lb)
		if not pts then
			return nil, "flick " .. tostring(src)
		end
		return pts, "flick", lb.actor
	end
	if type(own) == "number" and own ~= 0 then
		return nil, "carried"
	end
	local _, _, S, Tm = Mark.ballPath(root)
	if not S or #S < 2 then
		return nil, "no path"
	end
	local pts = table.create(N)
	local n, hint = #S, 2
	for k = 0, N - 1 do
		local t = k * DT
		local p
		if t >= Tm[n] then
			p = S[n]
		else
			while hint < n and Tm[hint] < t do
				hint += 1
			end
			local a, b = Tm[hint - 1], Tm[hint]
			p = S[hint - 1]:Lerp(S[hint], b > a and (t - a) / (b - a) or 0)
		end
		pts[k + 1] = p
	end
	local st = Renderer.GetAuthoritativeMovementState()
	local kid = st and st.LastKickerUserId
	return pts, "flight", type(kid) == "number" and playerOf(kid) or nil
end

-- our root height t s from now: "ground", a jump at td (s from now), or false = the arc we are on
Mark.airY = function(o, t, td)
	local g, vJ = o.g, o.vJ
	if td == "ground" then
		return o.floor
	elseif td == false then
		return math.max(o.O.Y + o.vy * t - 0.5 * g * t * t, o.floor)
	end
	local x = t - td
	if x <= 0 then
		return o.floor
	end
	return o.floor + math.max(vJ * x - 0.5 * g * x * x, 0)
end

-- The order the meets are shown to the game. The earliest reachable meet is the one we reach with NOTHING to spare: one frame of
-- ping, a ramp slower than the model, and the press misses (log: "short xz 0.3"). So: the earliest meet with `minSlack` seconds in
-- hand, if there is one within `window` of the earliest, else the old order. Inside those the plan we are on keeps its kind
-- (ground / a jump): the log flipped between td ground and td 1.00 every 0.05 s for one ball. prevGround = nil: no plan yet.
Mark.airOrder = function(list, minSlack, window, prevGround)
	local lead = list[1]
	if not lead then
		return list
	end
	local comfy, rest = {}, {}
	for _, c in list do
		if c.slack >= minSlack and c.T <= lead.T + window then
			comfy[#comfy + 1] = c
		else
			rest[#rest + 1] = c
		end
	end
	if #comfy == 0 then
		return list
	end
	if prevGround ~= nil then
		for i, c in comfy do
			if (c.td == "ground") == prevGround then
				if i > 1 then
					table.insert(comfy, 1, table.remove(comfy, i))
				end
				break
			end
		end
	end
	for _, c in rest do
		comfy[#comfy + 1] = c
	end
	return comfy
end

-- What the game's own no is worth: a dive, a spent jump or a competitor who takes the ball first do not pass with time; "no approach"
-- (the flight is too young, the ball not at the box yet) and a rising kicker do.
Mark.airHard = function(info)
	return info ~= nil and (info.BlockedByDive == true or info.BlockedBySpentJump == true or info.BlockedByCompetitor == true)
end

-- Candidates: per path sample, a root spot where our FrontAssist box (facing the incoming ball) sits on the ball, that
-- we reach in time - running at o.spd on the ground and at o.spdAir after a take-off (the game drops the sprint in the
-- air: state lines show ws 16 in Freefall) - and a height option (ground, a jump at td with the latest td first =
-- rising at the contact = the bicycle upgrade, or our current arc). Only a SHORTLIST: the game's own Evaluate
-- (Mark.airOracle) decides which of them really gets an offer. Returns first, nearMiss, list (by T).
Mark.airSolve = function(o)
	local front = HitboxSettings.FrontAssist
	local fz = -front.CFrameOffset.Z
	local cy = front.CFrameOffset.Y
	local hx = front.Size.X * 0.5 + o.ballR
	local hy = front.Size.Y * 0.5 + o.ballR
	local ramp = math.max(CFG.BallRamp or 0.2, 0.05)
	local spdAir = o.spdAir or o.spd
	local function run(u, t, s)
		local v0 = u and math.clamp(o.v0:Dot(u), 0, s) or 0
		if t <= ramp then
			return v0 * t + (s - v0) * t * t / (2 * ramp)
		end
		return v0 * ramp + (s - v0) * ramp * 0.5 + s * (t - ramp)
	end
	local function reach(u, T, td)
		if td == false then
			return spdAir * T
		elseif td == "ground" then
			return run(u, T, o.spd)
		end
		-- never more than running on: the air only takes speed away
		return math.min(run(u, T, o.spd), run(u, math.min(td, T), o.spd) + spdAir * math.max(T - td, 0))
	end
	local tds = { false }
	if o.landed then
		tds = { "ground" }
		for td = 1.0, -0.0001, -0.05 do
			tds[#tds + 1] = math.max(td, 0)
		end
	end
	local pts, DT = o.pts, o.DT
	local tanT = math.tan(math.rad(o.tolDeg)) * (CFG.AirTolT or 0.3)
	local near, list = nil, {}
	for k = 5, #pts - 1 do
		local T = (k - 1) * DT
		local B = pts[k]
		local inc = unitOrNil(flat(pts[k - 1] - pts[k + 1])) or unitOrNil(flat(o.O - B)) or Vector3.new(0, 0, 1)
		local bs = (pts[k + 1] - pts[k - 1]).Magnitude / (2 * DT)
		local tol = math.min(tanT * bs + (CFG.AirSlack or 0.5), 3)
		local Q = B - inc * fz
		local toQ = flat(Q - o.O)
		local u = unitOrNil(toQ)
		local need = math.max(toQ.Magnitude - (hx + tol), 0)
		local bestY, bestTd, gapXZ, slack = math.huge, nil, math.huge, 0
		for _, td in tds do
			if td == "ground" or td == false or td + 0.03 <= T then
				local gx = math.max(need - reach(u, T, td), 0)
				local dy = math.max(math.abs(B.Y - Mark.airY(o, T, td) - cy) - (hy + tol), 0)
				if gx <= 0 and dy <= 0 then
					bestY, bestTd, gapXZ = 0, td, 0
					-- seconds to spare: the studs we reach beyond what the meet needs, at the speed we run
					slack = (reach(u, T, td) - need) / math.max(o.spd, 1)
					break
				end
				if gx + dy < gapXZ + bestY then
					bestY, gapXZ = dy, gx
				end
			end
		end
		if bestTd ~= nil then
			list[#list + 1] = { td = bestTd, T = T, B = B, Q = Vector3.new(Q.X, o.O.Y, Q.Z), inc = inc, tol = tol, k = k, slack = slack }
		else
			local gap = gapXZ + bestY
			-- (only an AIR sample is a near miss: the log's "short xz 0.0" was a ball rolling on the grass under the height gate)
			if (not near or gap < near.gap) and B.Y - o.floor >= (o.minH or -math.huge) then
				near = { gap = gap, gapXZ = gapXZ, gapY = bestY, T = T, h = B.Y - o.floor, d = flat(B - o.O).Magnitude }
			end
		end
	end
	return list[1], near, list
end

-- THE GAME'S OWN ANSWER for a planned pose (user: "the game says when it can - so make it say it"). VolleyLockOn.Evaluate
-- takes a claim pose (RootCFrame, Velocity) and an evaluation time: we ask it at time te, our root at the spot (height of
-- our jump there), facing the incoming ball - the exact rule the prompt and the server's claim validation use (box,
-- swept velocity, miss angle, approach <= 0.4 s, flight gate, lock, grounded-ball / rising-kicker). The flight cache it
-- writes is time-keyed: the real prompt re-evaluates at its own time.
Mark.airOracle = function(character, st, world, te, Qr, inc)
	local VL = require(Modules.Ball.VolleyLockOn)
	local cf = CFrame.lookAt(Qr, Qr + inc)
	local ev, _, info = VL.Evaluate(st, world, character, CharacterMotionSmoothing.GetSmoothedServerTime() + te, nil, ActorTeams.GetCharacterTeamName(character), nil, CommandTime.GetPlayerVolleyOneWaySeconds(LocalPlayer), { RootCFrame = cf, Velocity = Vector3.zero }, nil)
	return ev, info
end

Mark.airInfo = function(info)
	if not info then
		return "no approach (ball not coming at the box within 0.4 s / flight gate)"
	end
	local f = {}
	for _, k in { "BlockedByDive", "BlockedBySpentJump", "BlockedByRisingKicker", "BlockedByCompetitor" } do
		if info[k] then
			f[#f + 1] = k
		end
	end
	return string.format("approach %.2f miss %.1f deg %.2f st%s", info.ApproachSeconds or -1, info.MissAngleDegrees or -1, info.MissDistance or -1, #f > 0 and (" " .. table.concat(f, ",")) or "")
end

-- What the game says for our REAL pose on the way in (every 0.1 s while the meet is < 0.7 s away): the prompt either
-- comes (OFFER) or this line says why not.
Mark.airDiag = function(character, plan)
	local now = os.clock()
	if now - (Mark.airDiagAt or 0) < 0.1 then
		return
	end
	Mark.airDiagAt = now
	local st, world = Renderer.GetAuthoritativeMovementState()
	if not (st and world) then
		return
	end
	local VL = require(Modules.Ball.VolleyLockOn)
	local ev, _, info = VL.Evaluate(st, world, character, CharacterMotionSmoothing.GetSmoothedServerTime(), nil, ActorTeams.GetCharacterTeamName(character), nil, CommandTime.GetPlayerVolleyOneWaySeconds(LocalPlayer), nil, nil)
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local look = root and unitOrNil(flat(root.CFrame.LookVector))
	logFile("air eval", ev and "OFFER" or "nil", "flick age", Mark.flickAge(), Mark.airInfo(info), "locked", tostring(VL.IsLocked(st)), "plan T", string.format("%.2f", plan.T), "td", tostring(plan.td),
		"to spot", root and string.format("%.1f", flat(plan.Q - root.Position).Magnitude) or "-", "face err", look and string.format("%.0f", math.deg(math.acos(math.clamp(look:Dot(plan.inc), -1, 1)))) or "-")
end

-- seconds since the enemy flick started (the animation: detach at 0.4, ball touchable from detach + 0.25) or "-"
Mark.flickAge = function()
	local lb = Mark.lob
	return (lb and os.clock() < lb.untilT) and string.format("%.2f", os.clock() - lb.at) or "-"
end

Mark.airSkipLog = function(why, extra)
	local now = os.clock()
	if Mark.airSkipWhy ~= why or now - (Mark.airSkipAt or 0) > 0.5 then
		Mark.airSkipWhy, Mark.airSkipAt = why, now
		logFile("air skip", why, extra or "")
	end
end

Mark.tickAir = function(character, root)
	if not Mark.airOn() or MatchSettings.IsGoalkeeperCharacter(character) or not Mark.playLive() then
		if Mark.airPlan then
			Mark.airEnd("off")
		end
		return
	end
	-- our own volley claim is out (Mark.volleyAt): it is the press of this module or the player's - nothing to plan
	if Mark.weOwn() or (Mark.volleyAt and os.clock() - Mark.volleyAt < 1.2) then
		if Mark.airPlan then
			Mark.airEnd(Mark.weOwn() and "ours" or "pressed")
		end
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	if not hum or Ragdoll.IsActorRagdolled(LocalPlayer) or Mark.slideBody() or ClientDodge.IsDribbling() then
		if Mark.airPlan then
			Mark.airEnd("busy")
		end
		return
	end
	local now = os.clock()
	local landed = CharacterControllers.IsLanded(character, hum)
	local floor = landed and root.Position.Y or (Mark.duelFloor or root.Position.Y)
	local g = Workspace.Gravity
	if type(g) ~= "number" or g < 10 then
		g = 196.2
	end
	local am = Mark.airMemo
	local plan, why
	if am and now - am.at < 0.05 then
		plan, why = am.plan and table.clone(am.plan), am.why
		if plan then
			local el = now - am.at
			plan.td = type(plan.td) == "number" and math.max(plan.td - el, 0) or plan.td
			plan.T -= el
		end
	else
		local pts, src, kicker = Mark.airPath(root)
		if not pts then
			Mark.airMemo = { at = now }
			if src ~= "carried" or (Mark.lob and now < Mark.lob.untilT) then
				Mark.airSkipLog(src)
			end
			if Mark.airPlan then
				Mark.airEnd(src)
			end
			return
		end
		local st, world = Renderer.GetAuthoritativeMovementState()
		if st and st.VolleyUserId and st.VolleyUserId ~= 0 and st.VolleyUserId ~= LocalPlayer.UserId then
			-- somebody's volley / bicycle claim locked the ball (the flicker re-claiming his own flick gets 0.15 s of
			-- flight against our 0.25 s - MinimumOwnFlightSeconds vs MinimumOpponentFlightSeconds): nobody else gets an offer
			local who = playerOf(st.VolleyUserId)
			Mark.airMemo = { at = now }
			Mark.airSkipLog("locked by " .. (who and actorName(who) or tostring(st.VolleyUserId)))
			if Mark.airPlan then
				Mark.airEnd("locked")
			end
			return
		end
		-- CHEAP PRE-GATE before the 77-sample solve (it ran every 0.05 s for every ball in flight anywhere: 296 "no reach" lines
		-- in one short log): a path that never rises above AirMinHeight over our hip (a shot into our mouth excepted), or never
		-- comes within AirReachFar of us, is nobody's air ball
		do
			local hmax, dmin = -math.huge, math.huge
			local O = root.Position
			for i = 1, #pts, 3 do
				local p = pts[i]
				hmax = math.max(hmax, p.Y - floor)
				dmin = math.min(dmin, flat(p - O).Magnitude)
			end
			if (hmax < (CFG.AirMinHeight or 1.5) and not Mark.airGoalShot(root, kicker)) or dmin > (CFG.AirReachFar or 140) then
				Mark.airMemo = { at = now }
				if Mark.airPlan then
					Mark.airEnd("not an air ball")
				end
				return
			end
		end
		Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
		local spd = math.max(Mark.akSpeeds(character), hum.WalkSpeed)
		local spdAir = landed and Mark.mover.GetBaseWalkSpeed(character) or hum.WalkSpeed
		local foeFlight = kicker ~= nil and kicker ~= LocalPlayer and not sameTeam(kicker)
		local gshot = Mark.airGoalShot(root, kicker) -- (a shot into our mouth is met at any height)
		local o = {
			minH = (not gshot) and (CFG.AirMinHeight or 1.5) or nil,
			O = root.Position, v0 = flat(root.AssemblyLinearVelocity), spd = spd, spdAir = (type(spdAir) == "number" and spdAir > 4) and spdAir or 16,
			landed = landed, vy = root.AssemblyLinearVelocity.Y, floor = floor, g = g, vJ = math.sqrt(2 * g * (Mark.jumpH or 7.2)),
			pts = pts, DT = 0.025, tolDeg = foeFlight and 6 or 10, ballR = Physics.BallRadius or 1,
		}
		local _, near, all = Mark.airSolve(o)
		-- only meets IN THE AIR (a ball that is on the grass at the sample is nobody's air ball)
		local list = {}
		for _, c in all do
			if gshot or c.B.Y - floor >= (CFG.AirMinHeight or 1.5) then
				list[#list + 1] = c
			end
		end
		-- the meet we reach with time to spare before the one we reach by a hair; the kind of plan we are on (ground / jump) first
		local prev = Mark.airPlan
		list = Mark.airOrder(list, CFG.AirComfort or 0.12, CFG.AirComfyWindow or 0.35, prev and prev.td ~= nil and (prev.td == "ground") or nil)
		local first = list[1]
		-- the rules on the earliest reachable meet (user: near a goal every ball)
		local want = false
		if first then
			want, why = Mark.airWant(root, first.B, kicker, floor)
		end
		if first and want then
			-- the game's verdict on the shortlist: the earliest candidate whose pose gets an offer 0.25-0.4 s before the
			-- meet. In the wind-up (he still owns it) there is no flight to evaluate yet: the earliest reachable spot.
			local inFlight = src == "flight" and st ~= nil and world ~= nil
			local verdict, firstInfo, tried = nil, nil, 0
			if inFlight then
				local step = math.max(1, math.floor(#list / 12))
				for i = 1, #list, step do
					local c = list[i]
					for _, lead in { 0.32, 0.27 } do
						local te = math.max(c.T - lead, 0)
						local Qr = Vector3.new(c.Q.X, Mark.airY(o, te, c.td), c.Q.Z)
						local ev, info = Mark.airOracle(character, st, world, te, Qr, c.inc)
						tried += 1
						if ev then
							verdict = c
							c.lead = lead
							break
						end
						firstInfo = firstInfo or { info = info, c = c, lead = lead }
					end
					if verdict or tried >= 18 then
						break
					end
				end
				plan = verdict
			else
				plan = first
			end
			if plan then
				plan.verified = inFlight
				plan.why, plan.src, plan.kicker = why, src, kicker
				plan.aim = Mark.volleyClearAim(plan.B)
			elseif firstInfo and not Mark.airHard(firstInfo.info) and firstInfo.c.T <= 1.2 then
				-- the game says no NOW (the flight is too young for a claim, the kicker still rises): the answer changes with
				-- the ball's age, and standing still until it does is how the spot is never reached. Run to the earliest meet; the
				-- press stays the game's (an offer). A dive / a spent jump / a competitor is a no that does not pass: no run.
				plan = firstInfo.c
				plan.hope = true
				plan.verified = false
				plan.why, plan.src, plan.kicker = why, src, kicker
				plan.aim = Mark.volleyClearAim(plan.B)
				why = "game says no, running to the meet: " .. Mark.airInfo(firstInfo.info)
			else
				local fi = firstInfo
				why = "game says no: " .. Mark.airInfo(fi and fi.info) .. (fi and string.format(" (T %.2f td %s h %.1f d %.1f, %d poses)", fi.c.T, tostring(fi.c.td), fi.c.B.Y - floor, flat(fi.c.B - root.Position).Magnitude, tried) or "")
			end
		elseif first then
			plan = nil
		else
			why = near and string.format("no reach: best T %.2f d %.1f h %.1f short xz %.1f y %.1f", near.T, near.d, near.h, near.gapXZ, near.gapY) or "no samples"
		end
		Mark.airMemo = { at = now, plan = plan, why = why }
		if not plan then
			local bp = pts[1]
			if bp.Y - floor > 3 or flat(bp - root.Position).Magnitude < 40 then
				Mark.airSkipLog(tostring(why), string.format("src %s kicker %s ball d %.1f h %.1f landed %s", src, kicker and actorName(kicker) or "-", flat(bp - root.Position).Magnitude, bp.Y - floor, tostring(landed)))
			end
		end
	end
	if not plan then
		if Mark.airPlan and now - Mark.airPlan.seen > 0.2 then
			Mark.airEnd(why or "no plan")
		end
		return
	end
	local st = Renderer.GetAuthoritativeMovementState()
	local key = st and (st.FlightStartedAt or st.StartedAt) or 0
	local fresh = not Mark.airPlan or Mark.airPlan.key ~= key or (Mark.airPlan.td == "ground") ~= (plan.td == "ground") or Mark.airPlan.verified ~= plan.verified
	plan.seen, plan.key = now, key
	plan.jumped = Mark.airPlan and not fresh and Mark.airPlan.jumped or nil
	Mark.airPlan = plan
	if fresh then
		logFile("air plan", plan.why, plan.verified and "GAME OK" or (plan.hope and "HOPE (the game says no now)" or "wind-up (not checkable yet)"), "flick age", Mark.flickAge(), "src", plan.src, "kicker", plan.kicker and actorName(plan.kicker) or "-", "T", string.format("%.2f", plan.T), "lead", tostring(plan.lead or "-"),
			"td", tostring(type(plan.td) == "number" and string.format("%.2f", plan.td) or plan.td), "meet d", string.format("%.1f", flat(plan.B - root.Position).Magnitude), "h", string.format("%.1f", plan.B.Y - floor), "landed", tostring(landed))
	end
	-- move to the spot; face the incoming ball once we are close (the box is in FRONT of the root; facing it from afar
	-- would backpedal)
	local toQ = flat(plan.Q - root.Position)
	local close = toQ.Magnitude < 8 or plan.T < 0.6
	Mark.move.look = close and plan.inc or unitOrNil(toQ) or plan.inc
	if close then
		TurnControl.LockAutoRotate("Aim", plan.inc)
		Mark.airFaced = true
	elseif Mark.airFaced then
		Mark.airFaced = nil
		TurnControl.ReleaseAutoRotate("Aim")
	end
	Mark.moveSteer(toQ.Magnitude > 0.6 and toQ.Unit or Vector3.zero, "air")
	-- JUMP: the take-off time td counts down from the plan; press when it is due (the solver steps td by 0.05, so
	-- "<= 0.035" was only true for one frame in two and a refused press was never retried: the module never jumped).
	if landed and type(plan.td) == "number" and plan.td <= 0.06 and not plan.jumped then
		if Mark.doJump("air") then
			plan.jumped = true
			logFile("air", "jump", "flick age", Mark.flickAge(), "T", string.format("%.2f", plan.T), "td", string.format("%.2f", plan.td), "h", string.format("%.1f", plan.B.Y - floor))
		elseif not Mark.airJumpLog or now - Mark.airJumpLog > 0.3 then
			Mark.airJumpLog = now -- (Mark.doJump logs the blocking source itself: "jump fail <why>")
			logFile("air", "jump REFUSED", "td", string.format("%.2f", plan.td), "T", string.format("%.2f", plan.T))
		end
	end
	if plan.T < 0.7 then
		Mark.airDiag(character, plan)
	end
end

-- Clear / layoff from a volley meet point: the open teammate furthest up the pitch (no enemy within 7 studs of the line
-- to him, in front of us toward their goal), else the flat direction among 16 that keeps furthest from every enemy,
-- biased toward their goal; lifted a little so it clears bodies.
Mark.volleyClearAim = function(meet)
	local goal = enemyGoalPart()
	local fwd = goal and unitOrNil(flat(goal.Position - meet)) or Vector3.new(0, 0, 1)
	local foes, mates = {}, {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		local r = actor and actor ~= LocalPlayer and ActorTargeting.GetActorRoot(actor)
		if r and not Mark.mateDown(actor, model) then
			if not sameTeam(actor) then
				foes[#foes + 1] = flat(r.Position - meet)
			elseif not isGoalkeeper(actor) then
				mates[#mates + 1] = flat(r.Position - meet)
			end
		end
	end
	-- a pass to the mate who is FREE and CLOSE: no enemy near him (a marked mate hands the ball to the marker), none on the
	-- lane, short (he reaches it sooner), and not backward. Score = his space + progress - length.
	local best, bestV = nil, -math.huge
	for _, to in mates do
		local L = to.Magnitude
		if L > 8 and L < 110 then
			local u = to / L
			local space, laneMin = 40, 40
			for _, q in foes do
				space = math.min(space, (q - to).Magnitude)
				local s = math.clamp(q:Dot(u), 0, L)
				laneMin = math.min(laneMin, (q - u * s).Magnitude)
			end
			if space >= 9 and laneMin >= 6 then
				local v = math.min(space, 25) * 1.2 + u:Dot(fwd) * 8 - L * 0.22
				if v > bestV then
					best, bestV = u, v
				end
			end
		end
	end
	if not best then
		-- nobody free: the flat direction among 16 that keeps furthest from every enemy, a little toward their goal
		bestV = -math.huge
		for k = 0, 15 do
			local a = k * math.pi / 8
			local d = Vector3.new(math.cos(a), 0, math.sin(a))
			local v = d:Dot(fwd) * 20
			for _, q in foes do
				local s = q:Dot(d)
				if s > 0 then
					v -= 60 / math.max((q - d * s).Magnitude, 2) * math.clamp(1 - s / 120, 0, 1)
				end
			end
			if v > bestV then
				best, bestV = d, v
			end
		end
	end
	return (best + Vector3.new(0, CFG.BlockClearLift or 0.35, 0)).Unit
end

-- AutoKick context: his pose (display delay aware), our velocity, gravity.
Mark.akCtx = function(root, model, r)
	local character = LocalPlayer.Character
	local hum = character and character:FindFirstChildOfClass("Humanoid")
	local hisHum = model:FindFirstChildOfClass("Humanoid")
	local pos, vel, worldVel = Mark.carrierPose(r, model)
	local g = Workspace.Gravity
	if type(g) ~= "number" or g < 10 then
		g = 196.2
	end
	-- CharacterMotion.GetVelocity has Y = 0 for another player: his vertical speed is the measured one (Mark.vertState)
	local hisAir = hisHum ~= nil and not CharacterControllers.IsLanded(model, hisHum)
	local vyM = (typeof(worldVel) == "Vector3") and worldVel.Y or 0
	if hisAir and math.abs(vyM) < 0.5 then
		vyM = Mark.vertState(model, pos, root.Position.Y, true, os.clock(), g).vy
	end
	return {
		root = root, ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25),
		pos = pos, vel = vel, vy = vyM,
		dly = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25),
		hisAir = hisHum ~= nil and not CharacterControllers.IsLanded(model, hisHum),
		usAir = hum ~= nil and not CharacterControllers.IsLanded(character, hum),
		vUs = flat(root.AssemblyLinearVelocity), vyUs = root.AssemblyLinearVelocity.Y, g = g,
	}
end


-- ===== AutoKick v2 ====================================================================================================
-- The old kick asked "is he inside the box at the release, now?" and stood still while the charge (walking speed ~8)
-- ran: a man pulling away left the box, a man we could have caught was never chased (no movement at all).
-- Now a PLAN: for every start delay tp (0 .. AutoKickLead) our body is simulated (run at him with the current speed
-- ramping up, then the charge at charging speed, still steering at him) to the release; his server pose comes from the
-- weighted fan of futures AutoGK uses (keep, ease off, turns, retreat, and the two side bursts of a READY dribble). The
-- kick aims at his main line at the release; confidence = the weight of the futures that stand in HitboxSettings.Kick
-- then (box 6 x 7 x 7, 1.5 ahead of the aimed root), and the main line must hold with a margin. The earliest tp with
-- confidence >= AutoKickConf wins: tp > 0 = run there first (Mark.akApproach feeds tickBlock's steering), tp = 0 = press
-- the real ChargedKick now, release at the full charge (AutoKickFull) or when the share would only fall. A charge whose
-- share drops under AutoKickCancel is cancelled. Nothing here learns: the thresholds are CFG numbers.
Mark.akFutures = function(ctx, root, dribReady)
	local g = Mark.defendGoal()
	local aimP = g and g.Position or (root.Position + root.CFrame.LookVector * 50)
	return Mark.gkFutures(ctx.pos, ctx.vel, ctx.vy, ctx.hisAir, false, root.Position.Y - 0.6, ctx.dly + ctx.ping * 0.5, aimP, ctx.g, dribReady and not ctx.hisAir)
end

-- our flat position after `tp` s of running at him plus `rr` s of charging (steering at his main line all the time)
Mark.akSim = function(ctx, main, mySpd, chSpd, tp, rr)
	local DT = 0.025
	local px, pz = ctx.root.Position.X, ctx.root.Position.Z
	local vx, vz = ctx.vUs.X, ctx.vUs.Z
	local ramp = math.max(CFG.BallRamp or 0.2, 0.05)
	local t, total = 0, tp + rr
	while t < total - 1e-6 do
		local k = math.min(math.floor((t + 0.2) / DT + 0.5) + 1, #main)
		local dx, dz = main[k].X - px, main[k].Z - pz
		local m = math.sqrt(dx * dx + dz * dz)
		if m > 1e-3 then
			dx, dz = dx / m, dz / m
		end
		local spd
		if t < tp then
			local s0 = math.clamp(vx * dx + vz * dz, 0, mySpd)
			spd = s0 + (mySpd - s0) * math.min(t / ramp, 1)
		else
			spd = chSpd
		end
		px += dx * spd * DT
		pz += dz * spd * DT
		t += DT
	end
	return px, pz
end

-- share of his futures inside the kick box for a release tp + rr from now. -> conf, mainSolid, aim, usPos, mainPos
Mark.akShare = function(ctx, futs, mySpd, chSpd, tp, rr)
	local DT = 0.025
	local px, pz = Mark.akSim(ctx, futs[1].pts, mySpd, chSpd, tp, rr)
	local tot = tp + rr
	-- airborne: our arc, never below the floor we left (Mark.duelFloor = our root Y the last frame we stood)
	local us = Vector3.new(px, ctx.usAir and math.max(ctx.root.Position.Y + ctx.vyUs * tot - 0.5 * ctx.g * tot * tot, Mark.duelFloor or -math.huge) or ctx.root.Position.Y, pz)
	local k = math.min(math.floor(tot / DT + 0.5) + 1, #futs[1].pts)
	local m = futs[1].pts[k]
	local aim = unitOrNil(flat(m - us)) or unitOrNil(flat(ctx.root.CFrame.LookVector))
	if not aim then
		return 0, false, nil, us, m
	end
	local box = HitboxSettings.Kick
	local aimed = AimFacing.GetAimedRoot({ Position = us }, aim)
	local conf, wSum = 0, 0
	for _, f in futs do
		wSum += f.w
		local p = f.pts[k]
		if p and HitboxSettings.ContainsPoint(aimed, box, p) then
			conf += f.w
		end
	end
	local solid = true
	for _, o in { { 0.5, 0 }, { -0.5, 0 }, { 0, 0.5 }, { 0, -0.5 } } do
		if not HitboxSettings.ContainsPoint(aimed, box, m + Vector3.new(o[1], 0, o[2])) then
			solid = false
			break
		end
	end
	return conf / math.max(wSum, 1e-6), solid, aim, us, m
end

Mark.akSpeeds = function(character)
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local base = Mark.mover.GetBaseWalkSpeed(character)
	local run = Mark.mover.GetRunWalkSpeed(base, false)
	local ch = Mark.mover.GetChargingWalkSpeed(base, false)
	return (type(run) == "number" and run >= 8) and run or 16, (type(ch) == "number" and ch > 1) and ch or 8
end

-- earliest start delay whose release holds >= AutoKickConf of his futures. -> plan | nil, bestConf
Mark.akPlan = function(ctx, futs, character, urgent)
	local mySpd, chSpd = Mark.akSpeeds(character)
	local minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2
	local maxC = KickCore.Constants.MaximumChargeSeconds or 0.4
	local fullT = (KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds()) or (maxC - 0.05)
	local rrs = urgent and { minRel } or ((CFG.AutoKickFull ~= false) and { fullT } or { minRel, (minRel + fullT) * 0.5, fullT })
	local need = urgent and 0.35 or (CFG.AutoKickConf or 0.55)
	local tpMax = (urgent or CFG.AutoKickMove == false or ctx.usAir or ctx.keeper) and 0 or (CFG.AutoKickLead or 0.5)
	local bestConf = 0
	local tp = 0
	while tp <= tpMax + 1e-6 do
		for _, rr in rrs do
			local conf, solid, aim, us, m = Mark.akShare(ctx, futs, mySpd, chSpd, tp, rr)
			if conf > bestConf then
				bestConf = conf
			end
			if aim and conf >= need and (solid or urgent) then
				return { tp = tp, rr = rr, conf = conf, aim = aim, us = us, hit = m, chSpd = chSpd, mySpd = mySpd }, conf
			end
		end
		tp += 0.04
	end
	return nil, bestConf
end

-- The player is charging the kick himself (real Kick input held, nothing of ours pressed): AutoKick does not press or release
-- for him, but the Agent steers him through the charge (Run To Kick): toward where the carrier will be at the release,
-- from the same weighted futures the script's own kick uses. The release is the player's; his aim is the camera / Kick
-- Helper, so nothing here touches the shot direction. Returns true when the steer was set.
Mark.akUser = function(tag, model, r)
	if CFG.AutoKickMove == false then
		return false
	end
	local character = LocalPlayer.Character
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not (character and root and model and r and r.Parent) or Dodge.IsDribbling(model) then
		return false
	end
	local actor = Actors.GetFromCharacter(model)
	if Mark.mateDown(actor, model) then
		return false
	end
	local ctx = Mark.akCtx(root, model, r)
	local now = os.clock()
	local futs = Mark.akFutures(ctx, root, false)
	local mySpd, chSpd = Mark.akSpeeds(character)
	local inst = Mark.chargeInst()
	local held = (inst and inst.GetHeldSeconds and inst.GetHeldSeconds()) or 0
	local fullAt = KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds() or ((KickCore.Constants.MaximumChargeSeconds or 0.4) - 0.05)
	local conf, _, _, _, m = Mark.akShare(ctx, futs, mySpd, chSpd, 0, math.max(fullAt - held, 0))
	local toM = m and unitOrNil(flat(m - root.Position))
	if not toM then
		return false
	end
	Mark.akApproach = { at = now, dir = toM, tp = 0, conf = conf, phase = "user", model = model }
	if not Mark.akUserLog or now - Mark.akUserLog > 0.5 then
		Mark.akUserLog = now
		logFile("autokick user", tag, actorName(actor), "held", string.format("%.2f", held), "conf", string.format("%.2f", conf), "dist", string.format("%.1f", flat(r.Position - root.Position).Magnitude))
	end
	return true
end

-- The player charges the kick himself: the Agent walks him through the charge at the enemy carrier (Run To Kick). Runs
-- every frame on its own, not from inside AutoBlock: the old path lived in akTry, which only AutoBlock calls, and the
-- block bails right after our slide ("block skip sliding") - exactly when the player presses Kick (log v146: kick helper
-- aim, no "autokick user" line in the whole session). Release and aim stay the player's.
Mark.akUserTick = function(character, root)
	if CFG.AutoKick == false or CFG.AutoKickMove == false or Mark.volleyInput then
		return false
	end
	-- OUR kick owns the body: the charge (Mark.ak, akTick steers at him every frame) and the run-up (akTry "run").
	-- AutoBlock used to read akApproach only in its carrier branch; in mark / cut / shadow frames it steered to its own
	-- spot during our charge, the box drifted off him and the kick was cancelled ("cancel at release conf 0.00").
	do
		local ap = Mark.akApproach
		if ap and os.clock() - ap.at < 0.12 and (Mark.ak or ap.phase == "run") then
			Mark.moveSteer(ap.dir, "kick")
			return true
		end
	end
	if Mark.ak then
		return false
	end
	if not (Mark.realKick and Mark.realKick.down and ChargedKick.IsCharging and ChargedKick.IsCharging()) then
		return false
	end
	if MatchSettings.IsGoalkeeperCharacter(character) or Mark.slideBody() or Ragdoll.IsActorRagdolled(LocalPlayer) then
		return false
	end
	local own = liveOwnerId()
	local who = own ~= LocalPlayer.UserId and playerOf(own) or nil
	if not who or sameTeam(who) or isGoalkeeper(who) then
		return false
	end
	local model = Actors.GetCharacter(who)
	local r = model and ActorTargeting.GetActorRoot(who)
	if not r or flat(r.Position - root.Position).Magnitude > Mark.kickReach() + (CFG.AutoKickUserRange or 30) then
		return false
	end
	if not Mark.akUser("user", model, r) then
		return false
	end
	Mark.moveSteer(Mark.akApproach.dir, "kick")
	return true
end

-- AutoKick on its own, every frame, whatever AutoBlock is doing. It lived only inside AutoBlock's carrier branch and
-- the cut branch: mark / far / pass-read / def-cover / after-slide frames never asked it (10 presses in all logs).
Mark.akAutoTick = function(character, root)
	if CFG.AutoKick == false or Mark.ak then
		return
	end
	local own = liveOwnerId()
	local who = type(own) == "number" and own ~= 0 and own ~= LocalPlayer.UserId and playerOf(own) or nil
	-- a keeper holding the ball is not kickable off it (the keeper exemptions: no strip, no stun) - log: AutoKick ran at
	-- the enemy keeper
	if not who or sameTeam(who) or isGoalkeeper(who) then
		return
	end
	local model = Actors.GetCharacter(who)
	local r = model and ActorTargeting.GetActorRoot(who)
	if r and flat(r.Position - root.Position).Magnitude <= Mark.kickReach() + (CFG.AutoKickRange or 16) then
		Mark.akTry("auto", model, r, false)
	end
end

-- Does the ray from `from` along `aim` (flat) cross the goal mouth lb..rb (extended by pad on both sides) within `reach` studs?
-- The kick sends the ball along the facing: a kick that hits the carrier is fine, one whose line ends in OUR mouth is an own goal.
Mark.aimsAtMouth = function(from, aim, lb, rb, pad, reach)
	local seg = flat(rb - lb)
	local len = seg.Magnitude
	if len < 1e-3 then
		return false
	end
	local su = seg / len
	local a = unitOrNil(flat(aim))
	if not a then
		return false
	end
	local den = a.X * su.Z - a.Z * su.X
	if math.abs(den) < 1e-4 then
		return false
	end
	local d = flat(lb - from)
	local t = (d.X * su.Z - d.Z * su.X) / den
	local s = (d.X * a.Z - d.Z * a.X) / den
	return t > 0 and t <= reach and s >= -pad and s <= len + pad
end

Mark.akTry = function(tag, model, r, urgent)
	if CFG.AutoKick == false then
		return false, "off"
	end
	local now = os.clock()
	if Mark.ak or now - (Mark.akAt or 0) < (CFG.AutoKickCooldown or 0.5) then
		return false, "busy"
	end
	local character = LocalPlayer.Character
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not (character and root and model and r and r.Parent) then
		return false, "nochar"
	end
	local gk = tag == "gk"
	if (MatchSettings.IsGoalkeeperCharacter(character) and not gk) or liveOwnerId() == LocalPlayer.UserId then
		return false, "role"
	end
	if (ChargedKick.IsCharging and ChargedKick.IsCharging()) or Mark.volleyInput or (Mark.realKick and Mark.realKick.down) then
		return false, "charging"
	end
	if slideAim or Mark.slideBody() or ClientDodge.IsDribbling() or Ragdoll.IsActorRagdolled(LocalPlayer) or Mark.aerial then
		return false, "busy2"
	end
	Mark.akDrib = Mark.akDrib or {}
	if Dodge.IsDribbling(model) then
		Mark.akDrib[model] = now
		return false, "iframe"
	end
	local actor = Actors.GetFromCharacter(model)
	if Mark.mateDown(actor, model) then
		return false, "down"
	end
	local ctx = Mark.akCtx(root, model, r)
	ctx.keeper = gk
	local drec = dribbleSeen[model] or (actor and dribbleSeen[actor.UserId])
	local dribReady = not (drec and drec.cdUntil and drec.cdUntil > now + 0.4)
	-- no dribble bursts in the kick fan: a dribble AGAINST the kick is the point (his iframe eats the kick, his Dodge is
	-- spent and the tackle gate's "naked" window opens) - with the bursts the share never reached the threshold
	local futs = Mark.akFutures(ctx, root, false)
	local plan, bestConf = Mark.akPlan(ctx, futs, character, urgent)
	if not plan then
		Mark.akApproach = nil
		if not Mark.akSkipLog or now - Mark.akSkipLog > 0.8 then
			Mark.akSkipLog = now
			local toHim = unitOrNil(flat(r.Position - root.Position))
			local away = toHim and flat(ctx.vel):Dot(toHim) or 0
			logFile("autokick skip", tag, actorName(actor), "conf", string.format("%.2f", bestConf), "need", string.format("%.2f", urgent and 0.35 or (CFG.AutoKickConf or 0.55)), "away", string.format("%.1f", away), "dist", string.format("%.1f", flat(r.Position - root.Position).Magnitude), "drib", dribReady and "ready" or "spent")
		end
		return false, "nohit"
	end
	-- never kick through a teammate or toward our own goal with the ball at his feet
	for _, m in Mark.models() do
		local a = Actors.GetFromCharacter(m)
		if a and a ~= LocalPlayer and sameTeam(a) then
			local ar = ActorTargeting.GetActorRoot(a)
			if ar and HitboxSettings.ContainsPoint(AimFacing.GetAimedRoot({ Position = plan.us }, plan.aim), HitboxSettings.Kick, ar.Position) then
				Mark.akApproach = nil
				return false, "mate"
			end
		end
	end
	local ball = Renderer.GetPosition()
	local goal = Mark.defendGoal()
	if ball and goal and flat(ball - r.Position).Magnitude < 7 then
		-- the old test refused any aim within 60 degrees of "toward our goal" (log: kick ownside at a carrier 6.8 away, the keeper
		-- stood and did nothing). The ball goes along the aim: refuse only a line that actually ends in our mouth (4 studs of pad).
		local lb, _, rb = goalMouthCorners(goal)
		if lb and rb and Mark.aimsAtMouth(ball, plan.aim, lb, rb, 4, 90) then
			Mark.akApproach = nil
			return false, "ownside"
		end
	end
	if plan.tp > 0.04 then
		-- RUN: tickBlock takes this direction instead of its shadow spot while the plan is fresh
		local DT = 0.025
		local main = futs[1].pts
		local chase = main[math.min(math.floor((plan.tp + 0.2) / DT + 0.5) + 1, #main)]
		local dir = unitOrNil(flat(chase - root.Position))
		if not (Mark.akApproach and now - Mark.akApproach.at < 0.3) then
			Mark.akAppSince = now
		end
		if dir and now - (Mark.akAppSince or now) <= 1.2 then
			Mark.akApproach = { at = now, dir = dir, tp = plan.tp, conf = plan.conf, phase = "run", model = model }
			if not Mark.akAppLog or now - Mark.akAppLog > 0.5 then
				Mark.akAppLog = now
				logFile("autokick run", tag, actorName(actor), "tp", string.format("%.2f", plan.tp), "conf", string.format("%.2f", plan.conf), "dist", string.format("%.1f", flat(r.Position - root.Position).Magnitude), "drib", dribReady and "ready" or "spent")
			end
			return false, "run", dir
		end
		Mark.akApproach = nil
		Mark.akAt = now -- ran for 1.2 s without getting there: cooldown, the tackle / block go on
		logFile("autokick", "run timeout", tag, actorName(actor))
		return false, "timeout"
	end
	Mark.volleyAim = plan.aim
	Mark.volleyAimUntil = now + 0.7
	local input = Controls.CreateInput("Kick")
	if not (ChargedKick.HandleInputBegan(input, false) and ChargedKick.IsCharging()) then
		Mark.volleyAim, Mark.volleyAimUntil = nil, nil
		return false, "refused"
	end
	Mark.volleyAt = now
	Mark.scriptChargeAt = now
	Mark.userVolleyAt = now
	Mark.akApproach = nil
	Mark.ak = { input = input, at = now, model = model, root = r, tag = tag, urgent = urgent and true or false, lastT = now, low = 0, conf0 = plan.conf }
	Mark.akAt = now
	logFile("autokick", "press", tag, actorName(actor), "conf", string.format("%.2f", plan.conf), "urgent", tostring(urgent and true or false), "dist", string.format("%.1f", flat(r.Position - root.Position).Magnitude), "drib", dribReady and "ready" or "spent")
	return true, "pressed"
end

Mark.akTick = function(character, root)
	local ak = Mark.ak
	if not ak then
		return
	end
	local now = os.clock()
	local dt = math.clamp(now - (ak.lastT or now), 0, 0.1)
	ak.lastT = now
	local function finish(why, cancel)
		if cancel and ChargedKick.CancelCharge and ChargedKick.IsCharging and ChargedKick.IsCharging() then
			ChargedKick.CancelCharge()
		end
		Mark.ak = nil
		Mark.akApproach = nil
		Mark.volleyAim, Mark.volleyAimUntil = nil, nil
		TurnControl.ReleaseAutoRotate("AimCharge")
		logFile("autokick", why, ak.tag, "held", string.format("%.2f", now - ak.at))
	end
	if not (ChargedKick.IsCharging and ChargedKick.IsCharging()) then
		return finish("end")
	end
	if not (ak.model and ak.model.Parent and ak.root and ak.root.Parent) or liveOwnerId() == LocalPlayer.UserId or Mark.slideBody() or Ragdoll.IsActorRagdolled(LocalPlayer) then
		return finish("abort", true)
	end
	if Mark.realKick and Mark.realKick.down and Mark.realKick.at and Mark.realKick.at > ak.at then
		Mark.ak = nil -- the user took the kick over
		Mark.akApproach = nil
		return
	end
	-- he dribbled: the iframe eats the kick. Cancel it, remember his Dodge (Mark.dribWatch) so the tackle gate
	-- ("naked": slide right after his iframe while his cooldown runs) takes over.
	if Dodge.IsDribbling(ak.model) then
		Mark.akDrib = Mark.akDrib or {}
		Mark.akDrib[ak.model] = now
		Mark.dribWatch()
		return finish("cancel iframe", true)
	end
	local inst = Mark.chargeInst()
	local held = (inst and inst.GetHeldSeconds and inst.GetHeldSeconds()) or (now - ak.at)
	local minRel = (KickCore.GetMinimumReleaseSeconds and KickCore.GetMinimumReleaseSeconds()) or 0.2
	local maxC = KickCore.Constants.MaximumChargeSeconds or 0.4
	local fullAt = KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds() or (maxC - 0.05)
	local full = CFG.AutoKickFull ~= false and not ak.urgent -- urgent (air duel): the first legal release
	local ctx = Mark.akCtx(root, ak.model, ak.root) -- we are already slowed by the charge: vUs is the real one
	-- no dribble bursts in the kick fan: a dribble AGAINST the kick is the point (his iframe eats the kick, his Dodge is
	-- spent and the tackle gate's "naked" window opens) - with the bursts the share never reached the threshold
	local futs = Mark.akFutures(ctx, root, false)
	local mySpd, chSpd = Mark.akSpeeds(character)
	local relAt = full and (fullAt + 0.002) or minRel
	local rem = math.max(relAt - held, 0)
	local conf, _, aim, _, m = Mark.akShare(ctx, futs, mySpd, chSpd, 0, rem)
	if aim then
		Mark.volleyAim = aim
		Mark.volleyAimUntil = now + 0.5
		TurnControl.LockAutoRotate("AimCharge", aim)
	end
	-- steer at him through the charge (the game caps us at the charging speed)
	local toM = unitOrNil(flat(m - root.Position))
	if toM then
		Mark.akApproach = { at = now, dir = toM, tp = 0, conf = conf, phase = "charge", model = ak.model }
	end
	if conf < (CFG.AutoKickCancel or 0.25) then
		ak.low = (ak.low or 0) + dt
	else
		ak.low = 0
	end
	if ak.low > 0.14 and held < fullAt - 0.03 then
		logFile("autokick", "cancel low", ak.tag, "conf", string.format("%.2f", conf))
		return finish("cancel miss", true)
	end
	local releaseNow = false
	if full then
		releaseNow = held >= fullAt + 0.002 or held >= maxC - 0.03
	elseif held >= minRel - 0.004 then
		-- early release only while the share is good and would not get better by waiting for more power
		local confFull = Mark.akShare(ctx, futs, mySpd, chSpd, 0, math.max(fullAt - held, 0))
		releaseNow = ak.urgent or (conf >= (CFG.AutoKickConf or 0.55) and confFull < conf - 0.05) or held >= fullAt or held >= maxC - 0.03
	end
	if releaseNow then
		if conf < (CFG.AutoKickCancel or 0.25) then
			logFile("autokick", "cancel at release", ak.tag, "conf", string.format("%.2f", conf))
			return finish("cancel miss", true)
		end
		Mark.ak = nil
		Mark.akApproach = nil
		Mark.volleyAimUntil = now + 0.25
		ChargedKick.HandleInputEnded(ak.input)
		TurnControl.ReleaseAutoRotate("AimCharge")
		logFile("autokick", "release", ak.tag, "held", string.format("%.3f", held), "conf", string.format("%.2f", conf), "dist", string.format("%.1f", flat(ak.root.Position - root.Position).Magnitude))
		-- outcome: the ball's last kicker is us shortly after the release = the kick took it
		local tag, victim = ak.tag, ak.model
		task.delay(0.35, function()
			local st = Renderer.GetAuthoritativeMovementState()
			local won = st ~= nil and st.LastKickerUserId == LocalPlayer.UserId
			Mark.teleAdd("kick." .. tag, won)
			logFile("autokick result", won and "WON" or "no", tag, "owner", tostring(liveOwnerId()), "iframe", tostring(victim.Parent ~= nil and Dodge.IsDribbling(victim)))
		end)
	end
end

-- any enemy field player within r of pos (the keeper counts: he can come out for a ball we hold)
Mark.foeWithin = function(pos, r)
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not Mark.mateDown(actor, model) then
			local fr = ActorTargeting.GetActorRoot(actor)
			if fr and flat(fr.Position - pos).Magnitude <= r then
				return actor
			end
		end
	end
	return nil
end

Mark.volleyPending = function()
	local input = Mark.volleyInput
	if not input then
		return
	end
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
	local age = os.clock() - (Mark.volleyAt or 0)
	if not charging then
		Mark.volleyInput = nil
		Mark.volleyKeep = nil
		return
	end
	-- KEEP: the press only LOCKED the ball (first claim wins); nobody is near, so there is nothing to clear - hold the
	-- charge until the ball is ours and cancel it (no strike). An enemy coming within reach, or the arrival without
	-- possession, strikes it as before. The game auto-releases at the maximum charge (<= MaximumApproachSeconds 0.4).
	local keep = Mark.volleyKeep
	if keep then
		local me = ActorTargeting.GetActorRoot(LocalPlayer)
		local foe = me and Mark.foeWithin(me.Position, keep.radius)
		local st = Renderer.GetAuthoritativeMovementState()
		local ball = Renderer.GetPosition()
		local bd = (me and typeof(ball) == "Vector3") and (ball - me.Position).Magnitude or math.huge
		local ownerUs = liveOwnerId() == LocalPlayer.UserId
		local lockedUs = st ~= nil and st.VolleyUserId == LocalPlayer.UserId
		-- the volley LOCK may hold the ball at our foot without an owner (the old rule waited for ownership and the delayed
		-- release struck first): cancel when the ball is owned by us OR locked to us and inside the body's reach
		if not keep.watchAt or os.clock() - keep.watchAt >= 0.08 then
			keep.watchAt = os.clock()
			logFile("volley keep watch", "age", string.format("%.2f", age), "owner", tostring(liveOwnerId()), "lockedUs", tostring(lockedUs), "ball", string.format("%.1f", bd), "foe", foe and actorName(foe) or "-")
		end
		if not foe and (ownerUs or (lockedUs and bd <= (CFG.VolleyKeepReach or 4.5))) then
			Mark.volleyInput, Mark.volleyKeep, Mark.volleyAim, Mark.volleyAt = nil, nil, nil, nil
			ChargedKick.CancelCharge()
			logFile("volley keep", "ball kept, charge cancelled", ownerUs and "owner" or "locked", "age", string.format("%.2f", age), "ball", string.format("%.1f", bd))
			return
		end
		if not foe and os.clock() < keep.arriveAt then
			return
		end
		Mark.volleyKeep = nil
		logFile("volley keep", foe and ("strike: foe " .. actorName(foe)) or "strike: arrived without possession", "age", string.format("%.2f", age))
	end
	if age >= 0.05 then
		Mark.volleyInput = nil
		ChargedKick.HandleInputEnded(input)
		logFile("volley", "release", age > 0.3 and "late" or "")
		if age > 0.6 and ChargedKick.IsCharging() and ChargedKick.CancelCharge then
			ChargedKick.CancelCharge()
			logFile("volley", "cancel", "stale")
		end
	end
end

-- GOAL CLEAR (AutoBlock, Defend Goal). An ENEMY shot whose path ends in OUR mouth (Mark.goalThreat) that the game
-- offers us as a volley (VolleyOpportunity.GetEvaluation: the ball enters our FrontAssist box within MaximumApproachSeconds
-- 0.4 s, <= MaximumOpponentMissAngleDegrees 6 for an opponent's flight, >= MinimumOpponentFlightSeconds 0.25 after his kick):
-- press Kick, the game claims it and DelayRelease strikes at the arrival = the ball is cleared, not deflected
-- (Receiving.Deflection keeps 12-52 % of a shot's speed and drops it in our box). The attack-volley rules of volleyPlan
-- (never grounded / low, threat or shooting range) are for OUR shots; a ball going into our net is struck whatever it is.
-- Aim: out of the goal through the meet point, lifted (BlockClearLift) - never back across our own mouth.
Mark.guardClear = function(character, root, ev)
	if not (CFG.AutoBlock and CFG.BlockGoal ~= false and CFG.BlockGoalClear ~= false) or MatchSettings.IsGoalkeeperCharacter(character) then
		return false
	end
	local st = Renderer.GetAuthoritativeMovementState and Renderer.GetAuthoritativeMovementState()
	local kicker = st and type(st.LastKickerUserId) == "number" and playerOf(st.LastKickerUserId) or nil
	if not kicker or kicker == LocalPlayer or sameTeam(kicker) then
		return false
	end
	local _, vel, samples, ts = Mark.ballPath(root)
	local threat = samples and Mark.goalThreat(samples, ts)
	local g = threat and Mark.defendGoal()
	if not g then
		return false
	end
	local lb, _, rb, _, _, n = goalMouthCorners(g)
	local fwd = n and unitOrNil(flat(n))
	if not (lb and rb and fwd) then
		return false
	end
	local meet = samples[#samples]
	for i = 1, #samples do
		if ts[i] >= (ev.ApproachSeconds or 0) then
			meet = samples[i]
			break
		end
	end
	-- one press attempt per 0.1 s (a refused press must not be re-sent every frame)
	if os.clock() - (Mark.clearTryAt or 0) < 0.1 then
		return true
	end
	Mark.clearTryAt = os.clock()
	local outD = unitOrNil(flat(meet - (lb + rb) * 0.5)) or fwd
	local f = unitOrNil(fwd + outD) or fwd
	local dir = (f + Vector3.new(0, CFG.BlockClearLift or 0.35, 0)).Unit
	Mark.volleyAim = dir
	Mark.volleyAimUntil = os.clock() + 1.5
	local input = Controls.CreateInput("Kick")
	if not (ChargedKick.HandleInputBegan(input, false) and ChargedKick.IsCharging()) then
		Mark.volleyAim, Mark.volleyAimUntil = nil, nil
		if not Mark.clearRefLog or os.clock() - Mark.clearRefLog > 0.5 then
			Mark.clearRefLog = os.clock()
			logFile("block clear", "refused", "approach", string.format("%.2f", ev.ApproachSeconds or -1))
		end
		return true
	end
	Mark.volleyInput = input
	Mark.volleyAt = os.clock()
	Mark.volleyShot = false
	logFile("block clear", "press", "from", actorName(kicker), "approach", string.format("%.2f", ev.ApproachSeconds or -1), "miss", string.format("%.1f", ev.MissAngleDegrees or -1), "grounded", tostring(ev.BallGrounded), "goal t", string.format("%.2f", threat.t), "lat", string.format("%.1f", threat.lat), "speed", string.format("%.0f", typeof(vel) == "Vector3" and vel.Magnitude or 0), "aim", fmtV(dir))
	return true
end

Mark.tickVolley = function(character, root)
	Mark.dribWatch()
	Mark.volleyPending()
	Mark.akTick(character, root)
	Mark.akAutoTick(character, root)
	Mark.kickHelper(root)
	Mark.tickAir(character, root)
	if not (CFG.AutoBall or CFG.AutoBlock or Mark.airOn()) then
		return
	end
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
	-- Our volley charge turned into a normal reception (we own the ball): the delayed release would now shoot our
	-- own ball away. Cancel it.
	-- Only a charge that was a KEEP (no shot, nobody near): with enemies near or a shot solved the delayed release is the point
	-- (the shot at the goal / the clear) and cancelling it handed the ball to the man next to us (user, twice: "the cancel is
	-- only for when nobody is near").
	if Mark.volleyAt and os.clock() - Mark.volleyAt < 1.2 and charging and liveOwnerId() == LocalPlayer.UserId then
		local foeNear = Mark.foeWithin(root.Position, (CFG.VolleyKeepRadius or 22) * 0.55)
		if not Mark.volleyShot and not foeNear then
			ChargedKick.CancelCharge()
			Mark.volleyInput = nil
			Mark.volleyAt = nil
			Mark.volleyAim = nil
			logFile("volley", "cancel", "own")
			return
		elseif not Mark.volleyOwnLog or os.clock() - Mark.volleyOwnLog > 1 then
			Mark.volleyOwnLog = os.clock()
			logFile("volley", "kept charge", "own ball", Mark.volleyShot and "a shot is solved" or ("enemy near " .. actorName(foeNear)))
		end
	end
	if Mark.volleyInput then
		return -- still waiting for the 0.05 s press (Mark.volleyPending releases it)
	end
	if Mark.volleyAimUntil and os.clock() > Mark.volleyAimUntil then
		Mark.volleyAim = nil
		Mark.volleyAimUntil = nil
	end
	-- The player's OWN volley / bicycle (he jumped and pressed Kick at an incoming ball): AutoShoot it once per claim
	-- from the meet point and lock the aim, so the release goes into the goal instead of where the camera looks.
	if charging and not Mark.volleyAt and CFG.AutoShoot and not Mark.weOwn() and not Mark.aerial then
		Mark.volleyMod = Mark.volleyMod or require(Client.Gameplay.Actions.VolleyOpportunity)
		local evU = Mark.volleyMod.GetEvaluation(character)
		if evU and not (Mark.userVolleyAt and os.clock() - Mark.userVolleyAt < 1.0) then
			Mark.userVolleyAt = os.clock()
			local _, _, samples, ts = Mark.ballPath(root)
			local meet = nil
			if samples then
				for i = 1, #samples do
					if ts[i] >= (evU.ApproachSeconds or 0) then
						meet = samples[i]
						break
					end
				end
			end
			local goal = enemyGoalPart()
			if meet and goal and flat(goal.Position - meet).Magnitude <= (CFG.ShootMaxDist or 160) then
				Mark.volleyContact = meet
				Mark.flickAim = true
				Shoot.curve = nil
				solveShot(root, true)
				Mark.flickAim = false
				Mark.volleyContact = nil
				if Shoot.aim then
					Mark.shotLockUntil = os.clock() + (evU.ApproachSeconds or 0.4) + 1.0
				end
				local hum = character:FindFirstChildOfClass("Humanoid")
				logFile("volley", "user", Shoot.aim and ("shot " .. tostring(Shoot.band)) or "noshot", "bike", tostring(hum and BicycleKick.CanBicycleKick(character, hum)), "goalD", string.format("%.0f", flat(goal.Position - meet).Magnitude))
			end
		end
	end
	if charging or not Mark.playLive() or Mark.weOwn() or Mark.aerial then
		return
	end
	local oid = liveOwnerId()
	if type(oid) == "number" and oid ~= 0 then
		-- a team-mate's ball is his; an ENEMY on the ball only blocks us if the game gives no volley evaluation (it
		-- does for a ball he pops or kicks up). VolleyOpportunity.GetEvaluation + the plan gate below decide.
		local who = playerOf(oid)
		if not who or who == LocalPlayer or sameTeam(who) then
			return
		end
	end
	if slideAim or Mark.slideBody() or ClientDodge.IsDribbling() or Ragdoll.IsActorRagdolled(LocalPlayer) then
		return
	end
	local inst = Mark.chargeInst()
	if inst and inst.CanKick and not inst.CanKick() then
		return
	end
	Mark.volleyMod = Mark.volleyMod or require(Client.Gameplay.Actions.VolleyOpportunity)
	local ev = Mark.volleyMod.GetEvaluation(character)
	if not ev then
		return
	end
	if Mark.guardClear(character, root, ev) then
		return
	end
	if not Mark.airOn() then
		return
	end
	-- The offer exists: press NOW (the first claim locks the ball; waiting for the rise / a "better" moment handed it
	-- to whoever pressed first). A planned meet (Mark.tickAir) carries its reason; an unplanned offer gets the same
	-- Mark.airWant rules.
	local hum = character:FindFirstChildOfClass("Humanoid")
	local landedNow = hum and CharacterControllers.IsLanded(character, hum)
	if ev.BallGrounded then
		return -- the game itself calls it grounded (bicycle / volley of a ground ball just launches it)
	end
	local ap = Mark.airBusy() and Mark.airPlan or nil
	local meet, why
	if ap then
		meet, why = ap.B, "plan " .. ap.why
	else
		meet = Mark.volleyMeet(root, ev)
		local st0 = Renderer.GetAuthoritativeMovementState()
		local kid = st0 and st0.LastKickerUserId
		local want
		want, why = Mark.airWant(root, meet, type(kid) == "number" and playerOf(kid) or nil, landedNow and root.Position.Y or (Mark.duelFloor or root.Position.Y))
		if not want then
			local skipKey = tostring(why):match("^%S+ %S+")
			if Mark.volleySkip ~= skipKey then
				Mark.volleySkip = skipKey
				logFile("volley", "skip", why, "approach", string.format("%.2f", ev.ApproachSeconds or -1))
			end
			return
		end
		why = "offer " .. why
	end
	Mark.volleySkip = nil
	-- one press attempt per 0.1 s (a refused press is not re-sent every frame, and the shot solve below is 5-20 ms)
	if os.clock() - (Mark.volleyTryAt or 0) < 0.1 then
		return
	end
	Mark.volleyTryAt = os.clock()
	-- aim: AutoShoot from the contact point inside shooting range, else the clear / lay-off
	local goal = enemyGoalPart()
	local goalD = goal and flat(goal.Position - meet).Magnitude or math.huge
	local shotFrom = nil
	if CFG.AutoShoot and goalD <= (CFG.ShootMaxDist or 160) then
		Mark.volleyContact = meet
		Mark.flickAim = true
		Shoot.curve = nil
		solveShot(root, true)
		Mark.flickAim = false
		Mark.volleyContact = nil
		if Shoot.aim then
			shotFrom = Shoot.band or "-"
			Mark.shotLockUntil = os.clock() + (ev.ApproachSeconds or 0.4) + 1.0
		end
	end
	Mark.volleyAim = shotFrom == nil and (ap and ap.aim or Mark.volleyClearAim(meet)) or nil
	Mark.volleyAimUntil = os.clock() + 1.5
	local input = Controls.CreateInput("Kick")
	if not (ChargedKick.HandleInputBegan(input, false) and ChargedKick.IsCharging()) then
		Mark.volleyAim = nil
		Mark.volleyAimUntil = nil
		logFile("volley", "refused", why, "approach", string.format("%.2f", ev.ApproachSeconds or -1))
	else
		Mark.volleyInput = input
		Mark.volleyAt = os.clock()
		Mark.volleyShot = shotFrom ~= nil
		Mark.volleyKeep = nil
		if CFG.VolleyKeep ~= false and not shotFrom and not Mark.foeWithin(meet, CFG.VolleyKeepRadius or 22) then
			Mark.volleyKeep = { radius = (CFG.VolleyKeepRadius or 22) * 0.55, arriveAt = os.clock() + (ev.ApproachSeconds or 0.3) + 0.12 }
		end
		Mark.airEnd("pressed")
		task.delay((ev.ApproachSeconds or 0.3) + 0.25, function()
			local st = Renderer.GetAuthoritativeMovementState()
			Mark.teleAdd("air.volley", st ~= nil and st.LastKickerUserId == LocalPlayer.UserId)
			logFile("volley result", st ~= nil and st.LastKickerUserId == LocalPlayer.UserId and "STRUCK" or "lost", why, "owner", tostring(liveOwnerId()), "volleyUser", tostring(st and st.VolleyUserId))
		end)
		logFile("volley", "press", why, shotFrom and ("shot " .. shotFrom) or "clear", "goalD", string.format("%.0f", goalD), "approach", string.format("%.2f", ev.ApproachSeconds or -1), "miss", string.format("%.1f", ev.MissAngleDegrees or -1), "grounded", tostring(ev.BallGrounded), "air", tostring(not landedNow), "bike", tostring(hum and BicycleKick.CanBicycleKick(character, hum)), "enemyOwner", tostring(type(oid) == "number" and oid ~= 0))
	end
end

-- Jump planner shared by AutoBall and AutoBlock: a ball that will pass ABOVE the standing contact band but inside jump
-- reach, near enough to be at us when the rise lifts the root to it. The old rule jumped only when the sample time
-- matched the rise time within +-0.05 and lived in tickBall, which returns while AutoBlock is active - so under
-- block a high shot or lob never made the script jump. A jump holds us above height h from the rise time tr until
-- the fall back through it (2*apexT - tr): jump as soon as the ball arrives no later than 0.1 s after that rise, not
-- before -0.03 (too late to get there).
Mark.planJump = function(root, samples, ts, spd)
	local front = HitboxSettings.FrontAssist
	local reachHi = front.CFrameOffset.Y + front.Size.Y * 0.5
	local reachXZ = front.Size.X * 0.5 + (-front.CFrameOffset.Z)
	local jumpH = Mark.jumpH or 7.2
	local gain = CFG.BallJumpGain or 0.3
	-- A jump is worth it only if the ball would not be standing-reachable soon after the contact: a ball that drops into
	-- reach 0.1 s after it passes the jump height is on the ground by the time the body is up (log: jump at t 0.25, h 7.0
	-- of a ball that landed in front of us - the jump only delayed the receive).
	local function worth(i)
		for j = i + 1, #samples do
			local h = samples[j].Y - root.Position.Y
			if h <= reachHi and flat(samples[j] - root.Position).Magnitude <= reachXZ + spd * math.min(ts[j], 0.5) then
				return ts[j] - ts[i] >= gain
			end
		end
		return true
	end
	for i = 2, #samples do
		local t = ts[i]
		if t > 1.25 then
			break
		end
		local p = samples[i]
		local h = p.Y - root.Position.Y
		if h > reachHi and h <= reachHi + jumpH - 0.3 then
			local tr = Mark.riseT(h - reachHi + 0.6)
			local d = t - tr
			local flatD = flat(p - root.Position).Magnitude
			-- already under the arc: jump up to 0.28 s early (the hold covers it). Running in: 0.18 s, not the old 0.1 s window that a skipped frame missed.
			if flatD <= reachXZ + 2 and d >= -0.04 and d <= 0.14 then
				return worth(i) and t or nil, h
			end
			if d >= -0.04 and d <= 0.10 and flatD <= reachXZ + spd * math.min(t, 0.5) then
				return worth(i) and t or nil, h
			end
		end
	end
	return nil
end

-- The flick as a path. RainbowFlick pops the ball up 0.4 s (BallDetachSeconds) after the start: GetCharacterLaunch gives the
-- launch position and velocity (ForwardSpeed 6 forward, PopUpSpeed 48 up, the carrier's own velocity inherited), and the ball
-- is a plain ballistic flight from there - so the whole lob is known the moment the wind-up starts. Times are from now.
-- the enemy whose flick lob is live (wind-up -> his self-delivery): he is the man to slide, the ball over him is his own
Mark.isLobber = function(ch)
	local lb = Mark.lob
	if not (lb and ch and os.clock() < lb.untilT) then
		return false
	end
	local pl = Players:GetPlayerFromCharacter(ch)
	return pl ~= nil and pl.UserId == lb.uid
end

Mark.flickShot = function(actor)
	Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
	local ch = Actors.GetCharacter(actor)
	if not ch or not Mark.enemyWind(actor) then
		return nil, "no wind-up"
	end
	local memo = Mark.flickMemo and Mark.flickMemo[actor]
	if memo and os.clock() - memo.at < 0.06 then
		return memo
	end
	local L = Mark.flick.GetCharacterLaunch(ch)
	if not (L and typeof(L.Position) == "Vector3" and typeof(L.Velocity) == "Vector3") then
		return nil, "no launch"
	end
	local fr = Mark.flickRec and Mark.flickRec[actor.UserId]
	local untilT = fr and fr.detachSrv
	local nowS = Workspace:GetServerTimeNow()
	local left = 0
	if type(untilT) == "number" then
		left = math.max(untilT - nowS, 0)
	end
	local carrierV = flat(CharacterMotion.GetVelocity(ch) or Vector3.zero)
	local launch = L.Position + carrierV * left
	local t0 = nowS + left
	local st = Physics.NewState(launch, L.Velocity, Physics.BallRadius, t0, Vector3.zero)
	if type(st) ~= "table" then
		return nil, "no state"
	end
	-- Renderer.GetMovementState() is nil while the ball is CARRIED (it only answers for Kind == "Movement"): during the
	-- wind-up the ball is still at his feet, so this returned nil on 14 of 15 flicks (log: 15 "flick seen", 1 "ball
	-- flick"). The boundary world is the arena's and does not change: the last one seen (Mark.ballPath) is the one.
	local _, world = Renderer.GetMovementState()
	world = world or Mark.lastWorld
	if not world then
		return nil, "no world"
	end
	local pts, ts = { launch }, { left }
	for i = 1, 40 do
		local t = i * 0.04
		local s = Physics.GetStateAtTime(st, t0 + t, world)
		local p = s.Position
		if typeof(p) ~= "Vector3" then
			break
		end
		pts[#pts + 1] = p
		ts[#ts + 1] = left + t
	end
	memo = { at = os.clock(), pts = pts, ts = ts, left = left, launch = launch, vel = L.Velocity }
	Mark.flickMemo = Mark.flickMemo or setmetatable({}, { __mode = "k" })
	Mark.flickMemo[actor] = memo
	if Mark.lob and Mark.lob.uid == actor.UserId then
		Mark.lob.fs = memo -- the last wind-up solve = the lob he actually launches (kept for the flight)
	end
	return memo
end

-- true when a predicted flight (points, relative times) ends in our mouth
Mark.pathOnTarget = function(pts)
	local g = Mark.defendGoal()
	if not (g and pts and #pts >= 2) then
		return false
	end
	local lb, lt, rb = goalMouthCorners(g)
	if not (lb and lt and rb) then
		return false
	end
	local mouth = (lb + rb) * 0.5
	local sideV = unitOrNil(flat(rb - lb))
	if not sideV then
		return false
	end
	local out = Vector3.new(-sideV.Z, 0, sideV.X)
	if flat(pts[1] - mouth):Dot(out) < 0 then
		out = -out
	end
	local half = flat(rb - lb).Magnitude * 0.5
	for i = 2, #pts do
		local p = pts[i]
		if flat(p - mouth):Dot(out) <= 0.3 then
			return math.abs(flat(p - mouth):Dot(sideV)) <= half + 2.5 and p.Y <= math.max(lt.Y, lb.Y) + 1.5, i
		end
	end
	return false
end

-- BEFORE the release: the replicated charge gives the flight, so the jump for a high shot is timed to it (the release is
-- assumed at the full charge: the game releases by itself at the maximum). The old jump waited for the ball to exist - on a
-- close shot the rise (0.27 s) was longer than the ball's whole flight.
Mark.preJump = function(character, root, oid)
	if CFG.BlockPreJump == false then
		return
	end
	local rec = Mark.charges and Mark.charges[oid]
	if not (rec and rec.live and os.clock() - (rec.seen or 0) < 0.6) then
		return
	end
	local cs = Mark.chargeShot(oid)
	if not (cs and Mark.pathOnTarget(cs.pts)) then
		return
	end
	local full = (KickCore.GetFullChargeSeconds and KickCore.GetFullChargeSeconds()) or 0.35
	local shift = math.max(rec.at + full - 0.03 - os.clock(), 0)
	local ts2 = table.create(#cs.ts)
	for i, t in cs.ts do
		ts2[i] = t + shift
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false) * 1.05
	local t, h = Mark.planJump(root, cs.pts, ts2, spd)
	if t and Mark.doJump("prejump") then
		Mark.blockJumpAt = os.clock()
		logFile("block prejump", "arrive", string.format("%.2f", t), "h", string.format("%.1f", h), "release in", string.format("%.2f", shift), "speed", string.format("%.0f", cs.speed))
	end
end

-- TELEMETRY: attempt -> result per feature, one `tele` line every 30 s (session totals + the last window, file Telemetry.txt).
-- feat = "module.what"; ok = the outcome the feature exists for; x = an optional error to average (seconds / studs, signed).
Mark.tele = { c = {}, at = os.clock() }
Mark.teleAdd = function(feat, ok, x)
	local c = Mark.tele.c[feat]
	if not c then
		c = { n = 0, ok = 0, wn = 0, wok = 0, xs = 0, xn = 0 }
		Mark.tele.c[feat] = c
	end
	c.n += 1
	c.wn += 1
	if ok then
		c.ok += 1
		c.wok += 1
	end
	if x then
		c.xs += x
		c.xn += 1
	end
end
Mark.teleTick = function()
	local now = os.clock()
	if now - Mark.tele.at < 30 then
		return
	end
	Mark.tele.at = now
	local names = {}
	for k, c in Mark.tele.c do
		names[#names + 1] = k
	end
	table.sort(names)
	for _, k in names do
		local c = Mark.tele.c[k]
		logFile("tele", k, "all", string.format("%d/%d %.0f%%", c.ok, c.n, 100 * c.ok / math.max(c.n, 1)), "30s", string.format("%d/%d", c.wok, c.wn), c.xn > 0 and string.format("err %+.2f (n %d)", c.xs / c.xn, c.xn) or "")
		c.wn, c.wok = 0, 0
	end
end

-- measured, not modelled: what did the slide really cover, and how close did the ball come to its box? (`slide audit`)
Mark.slideTrackTick = function(root)
	local tr = Mark.slideTrack
	if not tr then
		return
	end
	local now = os.clock()
	local tau = now - tr.at
	if tau < 0 then
		return
	end
	local disp = flat(root.Position - tr.O):Dot(tr.dir)
	for _, b in { 0.27, 0.42, 0.57 } do
		if not tr["g" .. b] and tau >= b then
			tr["g" .. b] = disp
		end
	end
	local ball = Renderer.GetPosition()
	if typeof(ball) == "Vector3" and tau >= 0.2 and tau <= 0.8 then
		local box = HitboxSettings.SlideTackle
		local d = flat(ball - (root.Position + tr.dir * (-box.CFrameOffset.Z))).Magnitude
		if not tr.minD or d < tr.minD then
			tr.minD, tr.minT = d, tau
		end
	end
	if tau >= 0.95 then
		Mark.slideTrack = nil
		if tr.tag == "ball" then
			-- planned contact time vs the time the box was closest to the ball: the TTI error of the planner (signed, + = late)
			Mark.teleAdd(tr.bent and "tackle.ball.bent" or "tackle.ball", tr.minD ~= nil and tr.minD <= 1.5, (tr.minD ~= nil and tr.minD <= 1.5 and tr.pc) and (tr.minT - tr.pc) or nil)
		else
			local o = liveOwnerId()
			Mark.teleAdd("tackle.carrier", o == LocalPlayer.UserId or not (type(o) == "number" and o ~= 0))
		end
		logFile("slide audit", tr.tag or "ball", tr.bent and "BENT" or "straight", "planned", tr.pc and string.format("%.2f", tr.pc) or "-", "mult", string.format("%.2f", tr.m),
			"travel@0.27", string.format("%.1f/%.1f", tr["g0.27"] or -1, Mark.dumpTravel(0.27) * tr.m),
			"@0.42", string.format("%.1f/%.1f", tr["g0.42"] or -1, Mark.dumpTravel(0.42) * tr.m),
			"@0.57", string.format("%.1f/%.1f", tr["g0.57"] or -1, Mark.dumpTravel(0.57) * tr.m),
			"ballClosest", tr.minD and string.format("%.1f at %.2f", tr.minD, tr.minT) or "-", "ownerNow", tostring(liveOwnerId()))
	end
end

Mark.tackleReady = function(character)
	local hum = character:FindFirstChildOfClass("Humanoid")
	return CFG.AutoTackle ~= false and hum ~= nil and os.clock() - lastTackleAt >= tackleEnforced
		and not Ragdoll.IsActorRagdolled(LocalPlayer)
		and not (ChargedKick.IsCharging and ChargedKick.IsCharging())
		and not ActionLocks.HasTackleBlock(LocalPlayer)
		and not SlideTackle.IsRepeatBlocked(character, false)
		and not ClientDodge.IsDribbling()
end

-- AutoBlock x TACKLE. The block stands where the replicated charge says; when the shot is out and the body cannot get to it
-- in time, a slide can: ~36 studs/s for the first second against 27 for a run, and the box (5x5x5, 3 ahead) stops the ball.
-- Ground slide only (the old blind "jump first, slide from the air" is gone: a ball over the box is Defend Goal's jump /
-- server acceptance of an air slide is not confirmed: `block slide air` + the tackle verdict decide). A body that reaches the
-- ball in time keeps the slide in the pocket (cooldown 3 s, ~1 s of lock).
Mark.blockSlide = function(character, root)
	if CFG.BlockSlide == false or not CFG.AutoTackle then
		return
	end
	local now = os.clock()
	if now - (Mark.blockSlideAt or 0) < 0.6 or slideAim or ClientSlide.IsSlideTackling() then
		return
	end
	local oid = liveOwnerId()
	if (type(oid) == "number" and oid ~= 0) or Mark.weOwn() or (Mark.allyKickUntil and now < Mark.allyKickUntil) then
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	if not hum or not Mark.tackleReady(character) then
		return
	end
	local landed = CharacterControllers.IsLanded(character, hum)
	if not landed then
		return
	end
	local _, vel, samples, ts = Mark.ballPath(root)
	if not samples or #samples < 3 or vel.Magnitude < 24 then
		return
	end
	local ok, ci = Mark.pathOnTarget(samples)
	if not ok then
		return
	end
	local crossT = ts[ci] or 9
	if crossT > 1.5 then
		return
	end
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
	local rcv = HitboxSettings.Receive
	local bodyHalf = rcv.Size.X * 0.5
	local lo = rcv.CFrameOffset.Y - rcv.Size.Y * 0.5
	local hi = rcv.CFrameOffset.Y + rcv.Size.Y * 0.5 + (Physics.BallRadius or 1)
	-- the body gets there first: nothing to add
	for i = 2, ci do
		local p = samples[i]
		local h = p.Y - root.Position.Y
		if h >= lo and h <= hi and (math.max(flat(p - root.Position).Magnitude - bodyHalf, 0) / spd + ping * 0.5 + 0.06) <= ts[i] then
			return
		end
	end
	local box = HitboxSettings.SlideTackle
	local boxMid = -box.CFrameOffset.Z
	local hx, hz = box.Size.X * 0.5, box.Size.Z * 0.5
	local yLo, yHi = box.CFrameOffset.Y - box.Size.Y * 0.5 - (Physics.BallRadius or 1), box.CFrameOffset.Y + box.Size.Y * 0.5 + (Physics.BallRadius or 1)
	local t0, t1 = C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds
	local mHi = math.max(0.4, CFG.TackleSpeed)
	local mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6)
	local function ballAt(t)
		if t <= 0 then
			return samples[1]
		end
		for i = 2, #ts do
			if ts[i] >= t then
				local k = (t - ts[i - 1]) / math.max(ts[i] - ts[i - 1], 1e-3)
				return samples[i - 1]:Lerp(samples[i], k)
			end
		end
		return nil
	end
	local O = root.Position
	local vy = root.AssemblyLinearVelocity.Y
	local g = Workspace.Gravity
	local fine = {}
	for k = 0, 10 do
		local tau = t0 + (t1 - t0) * k / 10
		fine[#fine + 1] = { tau, Mark.dumpTravel(tau), ballAt(ping * 0.5 + (CFG.SlideLag or 0.03) + tau) }
	end
	local best = nil
	for a = 0, 345, 15 do
		local r = math.rad(a)
		local phi = Vector3.new(math.cos(r), 0, math.sin(r))
		for mi = 0, 4 do
			local m = mLo + (mHi - mLo) * mi / 4
			local hits = 0
			for _, f in fine do
				local B = f[3]
				if B then
					local oy = landed and 0 or (vy * f[1] - 0.5 * g * f[1] * f[1])
					local ctr = O + phi * (f[2] * m + boxMid)
					local rel = flat(B - ctr)
					local dy = B.Y - (O.Y + oy)
					if math.abs(rel:Dot(phi)) <= hz and math.abs(rel.X * phi.Z - rel.Z * phi.X) <= hx and dy >= yLo and dy <= yHi then
						hits += 1
					end
				end
			end
			if hits >= (CFG.SlideMinHits or 3) and (not best or hits > best.hits) then
				best = { aim = phi, mult = m, hits = hits, ang = a }
			end
		end
	end
	-- no straight slide: press along a1, turn to a2 before the hand-off (Mark.bendDisp) - reverse and quarter turns
	if not best and CFG.SlideBend ~= false then
		for a = 0, 345, 15 do
			local r = math.rad(a)
			local a2 = Vector3.new(math.cos(r), 0, math.sin(r))
			for _, rot in { math.pi, math.pi * 0.5, -math.pi * 0.5 } do
				local ca, sa = math.cos(rot), math.sin(rot)
				local a1 = Vector3.new(a2.X * ca - a2.Z * sa, 0, a2.X * sa + a2.Z * ca)
				for mi = 0, 4 do
					local m = mLo + (mHi - mLo) * mi / 4
					local hits = 0
					for _, f in fine do
						local B = f[3]
						if B then
							local oy = landed and 0 or (vy * f[1] - 0.5 * g * f[1] * f[1])
							local ctr = O + Mark.bendDisp(a1, a2, m, f[1]) + a2 * boxMid
							local rel = flat(B - ctr)
							local dy = B.Y - (O.Y + oy)
							if math.abs(rel:Dot(a2)) <= hz and math.abs(rel.X * a2.Z - rel.Z * a2.X) <= hx and dy >= yLo and dy <= yHi then
								hits += 1
							end
						end
					end
					if hits >= (CFG.SlideMinHits or 3) and (not best or hits > best.hits) then
						best = { aim = a1, bend = { a2 = a2 }, mult = m, hits = hits, ang = a }
					end
				end
			end
		end
	end
	if best then
		Mark.blockSlideAt = now
		local sent, why = Mark.tryTackle(character, root, best.aim, best.mult, nil, nil, best.bend)
		logFile("block slide", landed and "ground" or "air", sent and "sent" or ("no " .. tostring(why)), best.bend and "BENT" or "straight", "hits", best.hits, "mult", string.format("%.2f", best.mult), "cross", string.format("%.2f", crossT), "speed", string.format("%.0f", vel.Magnitude))
		return
	end
end

-- Slide multiplier + start delay that put the slide box on point `p` when the ball gets there. D = flat distance us -> p,
-- tBall = seconds until the ball is at p. The box stands at travel(tau) * m + boxMid ahead of us tau seconds after the press
-- reaches the server; aimed at the middle of the hit window (tauMid). -> mult, startIn (s from now) or nil (too far / too near).
Mark.rushSlide = function(D, tBall, ping, mLo, mHi, t0, t1, boxMid, lag)
	local tauMid = (t0 + t1) * 0.5
	local m = (D - boxMid) / math.max(Mark.dumpTravel(tauMid), 1e-3)
	if m > mHi * 1.02 then
		return nil, "too far"
	end
	if m < mLo then
		return nil, "near"
	end
	local startIn = tBall - (ping * 0.5 + lag) - tauMid
	if startIn < -0.05 then
		return nil, "late"
	end
	return math.min(m, mHi), math.max(startIn, 0)
end

-- SHOT BLOCK, EMERGENCY. The replicated charge path ends in our mouth and no standing point on it is reachable in time
-- (Mark.chargeSpot: ok = false): run at the path sample we come closest to, sprint kept, and when a slide (36 st/s for the
-- first second, box 5 x 5 x 5 three ahead) lands on that sample at the ball's arrival, send it - the body arrives where a
-- run cannot. Used to be: not reachable -> nothing (the role planner went on marking a receiver while he shot).
Mark.chargeRush = function(character, root, ps)
	local now = os.clock()
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local O = root.Position
	local S = Vector3.new(ps.p.X, O.Y, ps.p.Z)
	local off = flat(S - O)
	Mark.move.look = unitOrNil(flat(ps.cross and (ps.cross - O) or off))
	Mark.move.pts = nil
	Mark.move.born = Mark.move.born or now
	Mark.moveSteer(off.Magnitude > 0.6 and off.Unit or Vector3.zero, "block")
	Mark.blockHold, Mark.blockLast, Mark.blockDest = now, now, S
	if off.Magnitude > 6 then
		Mark.agentHold(true, "chase")
	end
	local how = "run"
	local hum = character:FindFirstChildOfClass("Humanoid")
	local h = ps.p.Y - O.Y
	if CFG.BlockSlide ~= false and CFG.AutoTackle and hum and CharacterControllers.IsLanded(character, hum) and Mark.tackleReady(character) and h <= 4 then
		local box = HitboxSettings.SlideTackle
		local mHi = math.max(0.4, CFG.TackleSpeed)
		local mLo = math.min(mHi, CFG.TackleMinSpeed or 0.6)
		local m, startIn = Mark.rushSlide(off.Magnitude, ps.tRel + ps.t, ping, mLo, mHi, C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds, -box.CFrameOffset.Z, CFG.SlideLag or 0.03)
		if m then
			if startIn <= 0.03 then
				local sent, why = Mark.tryTackle(character, root, off.Unit, m)
				how = sent and "slide sent" or ("slide no " .. tostring(why))
				Mark.blockSlideAt = now
			else
				how = string.format("slide in %.2f", startIn)
			end
		else
			how = "run (slide " .. tostring(startIn) .. ")"
		end
	end
	if not Mark.rushLog or now - Mark.rushLog > 0.4 then
		Mark.rushLog = now
		logFile("block rush", "t", string.format("%.2f", ps.t), "slack", string.format("%.2f", ps.slack), "move", string.format("%.1f", off.Magnitude), "h", string.format("%.1f", h), "->", how)
	end
end

-- AutoBlock jump: enemy shots / lobs / passes over the Receive box while we shadow the carrier.
Mark.tickBlockJump = function(character, root)
	if os.clock() - (Mark.blockJumpAt or 0) < 0.5 or Mark.aerial then
		return
	end
	local oid = liveOwnerId()
	if type(oid) == "number" and oid ~= 0 then
		if oid ~= LocalPlayer.UserId then
			local humP = character:FindFirstChildOfClass("Humanoid")
			if humP and CharacterControllers.IsLanded(character, humP) and not ClientDodge.IsDribbling() then
				Mark.preJump(character, root, oid)
			end
		end
		return
	end
	if Mark.weOwn() or ClientDodge.IsDribbling() or (Mark.allyKickUntil and os.clock() < Mark.allyKickUntil) then
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	if not (hum and CharacterControllers.IsLanded(character, hum)) then
		return
	end
	local _, vel, samples, ts = Mark.ballPath(root)
	if not samples or #samples < 3 or vel.Magnitude < 8 then
		return
	end
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false) * 1.05
	local t, h = Mark.planJump(root, samples, ts, spd)
	if t and Mark.doJump("blockjump") then
		Mark.blockJumpAt = os.clock()
		logFile("block jump", "t", string.format("%.2f", t), "h", string.format("%.1f", h))
	end
end

-- ROUTE PLANNER for AutoBall (Mark.routePlan). A Baritone-style search over ACTION SEQUENCES instead of "run straight at
-- the earliest reachable sample":
--   run    - run to a point of the ball path and receive it there (also "jump" for a ball above the Receive box);
--   slide  - run for tp seconds to a waypoint W, then slide in ANY direction phi with multiplier m so the slide box
--            (HitboxSettings.SlideTackle 5x5x5, 3 studs ahead, -0.5 Y) contains the ball somewhere in its live window
--            [HitboxDelaySeconds, +HitboxSeconds]. W does not have to lie on the line to the ball: besides the direct
--            waypoint, waypoints rotated +-35 / +-70 deg around the contact point give slides that cut ACROSS the ball's
--            path (the box sweeps over it for longer = more robust), so the route bends: run one way, slide another.
-- Our reach is modelled with inertia: from the current velocity v0 to full speed in CFG.BallRamp, so the set of points we
-- can be at after t seconds is a disk C(t), r(t) (closed form) - turning around costs what it really costs.
-- Contact must be earlier than the ball by ping/2 + 0.08 (we arrived exactly on time before: "t 4.20 ourT 4.20" and
-- the ball went past). The race: every foe's earliest touch of the ball path (straight run); since that is a constant,
-- the earliest contact of ours is also the best margin. A slide replaces the run only when it is clearly earlier
-- (0.25 s) or the run loses the race and the slide does not.
Mark.routePlan = function(c)
	local O, v0, spd = c.O, c.v0, c.spd
	local S, T, n = c.samples, c.ts, #c.samples
	local ramp = math.max(CFG.BallRamp or 0.2, 0.05)
	local function reach(t)
		if t <= 0 then
			return O, 0
		elseif t <= ramp then
			return O + v0 * (t - t * t / (2 * ramp)), spd * t * t / (2 * ramp)
		end
		return O + v0 * (ramp * 0.5), spd * (t - ramp * 0.5)
	end
	local function arriveT(p, pad)
		local function ok(t)
			local Cc, r = reach(t)
			return flat(p - Cc).Magnitude - pad <= r
		end
		if ok(0) then
			return 0
		end
		local lo, hi = 0, 0.5
		while not ok(hi) do
			lo = hi
			hi *= 2
			if hi > 32 then
				return math.huge
			end
		end
		for _ = 1, 12 do
			local m = (lo + hi) * 0.5
			if ok(m) then
				hi = m
			else
				lo = m
			end
		end
		return hi
	end
	local hint = 2
	local function ballAt(t)
		if t <= 0 then
			return S[1]
		end
		if t >= T[n] then
			return c.rest and S[n] or nil
		end
		if T[hint] and T[hint] > t then
			hint = 2
		end
		while hint < n and T[hint] < t do
			hint += 1
		end
		local a, b = T[hint - 1], T[hint]
		local k = b > a and (t - a) / (b - a) or 0
		return S[hint - 1]:Lerp(S[hint], k)
	end
	-- foes: earliest touch of the ball path each (straight run, no ramp; the reaction they need is not modelled)
	local foeFirst = math.huge
	for _, f in c.foes do
		local first = math.huge
		if f.grappleT then
			first = f.grappleT
		elseif f.s > 1 then
			for i = 1, n do
				-- a foe touches only a ball his receive box (+ a jump, 0.15 s to rise) reaches: the old race ignored the
				-- height, so a lob over everyone was "his" the moment he stood under it and every jump plan lost
				local hF = S[i].Y - f.p.Y
				if hF >= c.recvLo - 1 and hF <= c.recvHi + c.jumpH - 0.4 then
					local tF = (f.delay or 0) + math.max(0, flat(S[i] - f.p).Magnitude - c.half) / f.s + (hF > c.recvHi and 0.15 or 0)
					local tt = math.max(T[i], tF)
					if tt < first then
						first = tt
					end
				end
				if T[i] > first then
					break
				end
			end
		end
		f.first = first
		foeFirst = math.min(foeFirst, first)
	end
	local safe = 0.08 + c.ping * 0.5
	-- BODY: run under it, jump into it, or (already in the air) ride our own arc. The earliest sample the body reaches.
	--   run : the ball in the Receive band of a standing body;
	--   jump: higher - the root height that puts the ball a stud under the top of AirReceive, reached on the RISE
	--         (x = time from take-off), take-off at td = tb - x. A high ball is met on its way down, not where it lands;
	--   air : we are airborne (c.air): the root follows O.Y + vy t - g t^2 / 2 down to the floor we left.
	-- (It used to treat an airborne body as standing: the plan vanished the frame after the jump - "no aim" - and the
	-- agent stopped steering in the air. The jump band used the ground box: 1.8 studs of reach were missing.)
	local g, vJ, floorY = c.g, c.vJ, c.floorY or O.Y
	local run = nil
	for i = 2, n do
		local p, tb = S[i], T[i]
		local mode, td = nil, nil
		if c.air then
			local y = math.max(O.Y + c.vy * tb - 0.5 * g * tb * tb, floorY)
			local h = p.Y - y
			if y > floorY + 0.3 then
				mode = (h >= c.airLo and h <= c.airHi) and "air" or nil
			elseif h >= c.recvLo - 0.6 and h <= c.recvHi then
				mode = "run"
			end
		else
			local h = p.Y - O.Y
			if h >= c.recvLo - 0.6 and h <= c.recvHi then
				mode = "run"
			elseif h > c.recvHi and h - c.airHi <= c.jumpH - 0.4 then
				local yT = math.clamp(h - c.airHi + 1, 0.4, c.jumpH - 0.2)
				local x = (vJ - math.sqrt(math.max(vJ * vJ - 2 * g * yT, 0))) / g
				if tb - x >= 0 then
					mode, td = "jump", tb - x
				end
			end
		end
		if mode then
			local tU = arriveT(p, c.half)
			if tU + safe <= tb then
				local cand = { kind = mode == "air" and "jump" or mode, p = p, t = tb, tUs = tU, way = p, td = td }
				if mode == "jump" then
					run = run or cand -- kept only if no plain run comes within JumpGain of it
				elseif run and tb - run.t > (CFG.BallJumpGain or 0.3) then
					break
				else
					run = cand
					break
				end
			end
		end
		if run and tb - run.t > (CFG.BallJumpGain or 0.3) then
			break
		end
	end
	if not run and c.rest and n >= 2 then
		local p = S[n]
		local tU = arriveT(p, c.half)
		run = { kind = "rest", p = p, t = math.max(T[n], tU), tUs = tU, way = p }
	end
	-- RUN + SLIDE (W, phi, m). A slide is TRANSPORT: from the press the body dashes (StartupDash 10 st * mult in 0.27 s,
	-- then Distance 24 * mult) and the ball is ours when EITHER the SlideTackle box (live 0.27..0.57 s) OR the sliding
	-- body itself (our receive oval, the whole dash up to VelocityReleaseStartsAt) passes over it. The old plan counted
	-- the box only: a ball 8-15 studs away was "contact at 0.27+" while the body is on it at 0.15-0.2, and a slide that
	-- ran through the ball after the box closed was no contact at all (log: "slide audit ball ... ballClosest 0.2 at
	-- 0.63-0.70" = taken by the body, three steals). Ball time = press + ping/2 + SlideLag + tau (the server's slide).
	local slide = nil
	if c.slideReady then
		local t0, t1 = C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds
		local box = HitboxSettings.SlideTackle
		local boxMid = -box.CFrameOffset.Z
		local hx, hz = box.Size.X * 0.5 + 0.25, box.Size.Z * 0.5 + 0.25
		local hLo = box.CFrameOffset.Y - box.Size.Y * 0.5 - 0.5
		local hHi = box.CFrameOffset.Y + box.Size.Y * 0.5 + 0.5
		local mLo, mHi = c.mLo, c.mHi
		local rb = c.half - 0.5 -- body radius used (half a stud inside the receive oval)
		local fine, fineD, fineBox = {}, {}, {}
		local tau = 0.06
		while tau <= (C.VelocityReleaseStartsAt or 0.75) + 1e-6 do
			local k = #fine + 1
			fine[k], fineD[k], fineBox[k] = tau, Mark.dumpTravel(tau), tau >= t0 - 1e-6 and tau <= t1 + 1e-6
			tau += 0.03
		end
		local NF = #fine
		local function touch(W, phi, m, k, B)
			local h = B.Y - O.Y
			local rel = flat(B - (W + phi * (fineD[k] * m)))
			local lon = rel:Dot(phi)
			local lat = rel.X * phi.Z - rel.Z * phi.X
			if fineBox[k] and h >= hLo and h <= hHi and math.abs(lon - boxMid) <= hz and math.abs(lat) <= hx then
				return true
			end
			return h >= c.recvLo - 0.6 and h <= c.recvHi and lon * lon + lat * lat <= rb * rb
		end
		local slideLag = c.ping * 0.5 + (CFG.SlideLag or 0.03)
		local Bs = nil
		-- contact samples around the candidate sample k0 (the ball depends only on the press time: Bs, once per tp)
		local function sweep(W, phi, m, k0)
			local first, hits = nil, 0
			for k = math.max(k0 - 4, 1), math.min(k0 + 4, NF) do
				local B = Bs[k]
				if B and touch(W, phi, m, k, B) then
					first = first or fine[k]
					hits += 1
				end
			end
			return first, hits
		end
		local rots = { 0, math.rad(35), -math.rad(35), math.rad(70), -math.rad(70) }
		local limit = math.min(run and run.t or math.huge, 3)
		local tp = 0
		local slideTp0 = nil
		local goodHits = math.min(CFG.SlideGoodHits or 7, 4) -- the body follows the box through the ball: 4 samples is centred
		local minHits = math.min(CFG.SlideMinHits or 3, 3)
		while tp <= 1.5 + 1e-6 do
			if tp + fine[1] >= limit or (slideTp0 and tp > slideTp0 + (CFG.SlideCenterWindow or 0.2)) then
				break
			end
			local Cc, r = reach(tp)
			Bs = {}
			for k = 1, NF do
				Bs[k] = ballAt(tp + slideLag + fine[k])
			end
			for k = 2, NF, 3 do
				local B = Bs[k]
				if B then
					local h = B.Y - O.Y
					local boxK = fineBox[k] and h >= hLo and h <= hHi
					if boxK or (h >= c.recvLo - 0.6 and h <= c.recvHi) then
						local toB = flat(B - Cc)
						local dCB = toB.Magnitude
						-- distance from the press point to the ball along the slide: the box (centre boxMid ahead) or the body
						local Slo = boxK and (fineD[k] * mLo + boxMid - hz + 0.6) or (fineD[k] * mLo)
						local Shi = boxK and (fineD[k] * mHi + boxMid + hz - 0.6) or (fineD[k] * mHi + rb - 0.6)
						local s = math.clamp(dCB, Slo, Shi)
						local u = dCB > 1e-3 and toB / dCB or Vector3.new(1, 0, 0)
						for _, a in rots do
							local ca, sa = math.cos(a), math.sin(a)
							local ur = Vector3.new(u.X * ca - u.Z * sa, 0, u.X * sa + u.Z * ca)
							local W = Vector3.new(B.X, O.Y, B.Z) - ur * s
							local off = flat(W - Cc).Magnitude
							if off <= r + 0.05 then
								local m = math.clamp((s - (boxK and boxMid or 0)) / math.max(fineD[k], 1), mLo, mHi)
								local first, hits = sweep(W, ur, m, k)
								if first and hits >= minHits then
									local tc = tp + first
									local sc, scOld = math.min(hits, goodHits), slide and math.min(slide.hits, goodHits) or -1
									if not slide or tc < slide.tc - 0.04 or (math.abs(tc - slide.tc) <= 0.04 and sc > scOld) then
										slideTp0 = slideTp0 or tp
										local heading = off > 0.3 and unitOrNil(flat(W - Cc)) or nil
										slide = { kind = "slide", p = B, tc = tc, t = tc, tp = tp, W = W, phi = ur, mult = m, hits = hits, rot = math.deg(a), heading = heading, way = W, body = not boxK }
									end
								end
							end
						end
					end
				end
			end
			tp += 0.05
		end
		-- BENT SLIDES (only when no straight one reaches): press along a1, turn to a2 = the heading at the ball before the
		-- hand-off (Mark.bendDisp). Reverse (a ball too close for the minimum travel: the shortest straight slide overshoots
		-- it by ~17 studs) and quarter turns. Same contact test, the box / body centre follows the bent path.
		if not slide and (CFG.SlideBend ~= false) then
			local function touchB(W, a1, a2, m, k, B)
				local h = B.Y - O.Y
				local rel = flat(B - (W + Mark.bendDisp(a1, a2, m, fine[k])))
				local lon = rel:Dot(a2)
				local lat = rel.X * a2.Z - rel.Z * a2.X
				if fineBox[k] and h >= hLo and h <= hHi and math.abs(lon - boxMid) <= hz and math.abs(lat) <= hx then
					return true
				end
				return h >= c.recvLo - 0.6 and h <= c.recvHi and lon * lon + lat * lat <= rb * rb
			end
			local bentRots = { math.pi, math.pi * 0.5, -math.pi * 0.5 }
			local mids = { mLo, (mLo + mHi) * 0.5, mHi }
			local tpB = 0
			while tpB <= 1.0 + 1e-6 do
				if tpB + fine[1] >= limit then
					break
				end
				local Cc, r = reach(tpB)
				for k = 2, NF, 3 do
					local B = ballAt(tpB + slideLag + fine[k])
					if B then
						local h = B.Y - O.Y
						local boxK = fineBox[k] and h >= hLo and h <= hHi
						if boxK or (h >= c.recvLo - 0.6 and h <= c.recvHi) then
							local toB = flat(B - Cc)
							local u = unitOrNil(toB) or Vector3.new(1, 0, 0)
							for _, a in bentRots do
								local ca, sa = math.cos(a), math.sin(a)
								local a1 = Vector3.new(u.X * ca - u.Z * sa, 0, u.X * sa + u.Z * ca)
								for _, m in mids do
									local W = Vector3.new(B.X, O.Y, B.Z) - Mark.bendDisp(a1, u, m, fine[k]) - (boxK and u * boxMid or Vector3.zero)
									if flat(W - Cc).Magnitude <= r + 0.05 then
										local first, hits = nil, 0
										for kk = math.max(k - 4, 1), math.min(k + 4, NF) do
											local Bk = ballAt(tpB + slideLag + fine[kk])
											if Bk and touchB(W, a1, u, m, kk, Bk) then
												first = first or fine[kk]
												hits += 1
											end
										end
										if first and hits >= minHits then
											local tc = tpB + first
											if not slide or tc < slide.tc - 0.04 then
												local off = flat(W - Cc).Magnitude
												slide = { kind = "slide", p = B, tc = tc, t = tc, tp = tpB, W = W, phi = a1, bend = { a2 = u }, mult = m, hits = hits, rot = math.deg(a), heading = off > 0.3 and unitOrNil(flat(W - Cc)) or nil, way = W, body = not boxK }
											end
										end
									end
								end
							end
						end
					end
				end
				tpB += 0.05
			end
		end
	end
	-- The slide costs 3 s of cooldown and the ball after it is a scramble: it is spent when it WINS something - no run
	-- reaches the ball, the race is tight (run margin under BallSlideNeed against the first foe) or the ball is going
	-- into our goal (c.urgent). An uncontested ball is run to (log: a 90 st/s ball, run margin 0.74, slide by the body
	-- with 3 hits picked for being 0.3 s earlier - MISS by 6 studs).
	local pick = run
	if slide then
		local runMargin = run and (foeFirst - run.t) or -math.huge
		local slideMargin = foeFirst - slide.tc
		local need = c.urgent or runMargin < (CFG.BallSlideNeed or 0.35)
		if not run or (need and (slide.tc < run.t - (CFG.RouteSlideGain or 0.3) or slideMargin > runMargin + 0.05)) then
			pick = slide
		end
	end
	-- CONTEST: the race is lost by more than BallContestLate (the foe's reaction is not modelled, a small loss can still be
	-- won). Chasing the ball to OUR earliest sample then leaves us past him when he touches it. Run at HIS touch point
	-- instead: when he receives, we are on him (AutoTackle / AutoKick take it from there). Not for a ball going into
	-- our goal (c.urgent): there every touch on the path counts.
	if pick and not c.urgent and foeFirst < math.huge and foeFirst - pick.t < -(CFG.BallContestLate or 0.15) then
		local fp = ballAt(foeFirst)
		if fp then
			pick = { kind = "contest", p = fp, t = foeFirst, way = fp, tUs = arriveT(fp, c.half), lost = pick.t - foeFirst }
		end
	end
	if not pick then
		return nil, foeFirst
	end
	pick.margin = foeFirst - pick.t
	pick.foeFirst = foeFirst
	return pick, foeFirst, run, slide
end

-- CandidateKiller (CFG.CandidateKiller). An enemy racing us for the loose ball is slid NOW if a slide direction within
-- CFG.KillerAngle of our route direction puts his body (his server-side pose: displayed + velocity * (display delay +
-- ping/2 + tau)) inside the slide box for >= 2 samples of the live window. Smallest deviation first, then more hits.
-- He is a racer when he is within KillerReach of us and either touches the ball path no later than KillerMargin after
-- us or is already within KillerRadius of the ball. The old version measured "near the ball" to OUR intercept point
-- (often the ball's rest point 60-200 studs away) and never fired once.
Mark.killerSlide = function(root, routeDir, foes, ballNow, ourT, mLo, mHi, guard)
	-- our own kick charge locks the slide (log: 3 "killer no game-reject" in 20 ms while the player charged)
	if ChargedKick.IsCharging and ChargedKick.IsCharging() then
		return nil, "our kick charge"
	end
	local O = root.Position
	local t0, t1 = C.HitboxDelaySeconds, C.HitboxDelaySeconds + C.HitboxSeconds
	local box = HitboxSettings.SlideTackle
	local boxMid = -box.CFrameOffset.Z
	local hx, hz = box.Size.X * 0.5, box.Size.Z * 0.5
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local minHits = CFG.SlideMinHits or 3
	local fine, fineD = {}, {}
	for k = 0, 10 do
		local tau = t0 + (t1 - t0) * k / 10
		fine[k + 1], fineD[k + 1] = tau, Mark.dumpTravel(tau)
	end
	local maxA = CFG.KillerAngle or 50
	local why = {}
	-- 1) every enemy a slide may hit, with his server-side path over the hitbox window
	local cands = {}
	for _, f in foes do
		local name = f.actor and actorName(f.actor) or "?"
		if not (f.root and f.root.Parent and f.model) then
			continue
		end
		local pos, vel = Mark.carrierPose(f.root, f.model)
		local dUs = flat(pos - O).Magnitude
		if dUs > (CFG.KillerReach or 28) then
			why[#why + 1] = name .. " far " .. string.format("%.0f", dUs)
			continue
		end
		local dBall = ballNow and flat(pos - ballNow).Magnitude or math.huge
		if dBall > (CFG.IntentTackleRadius or 60) then
			why[#why + 1] = name .. string.format(" ball %.0f > %d", dBall, CFG.IntentTackleRadius or 60)
			continue
		end
		-- his dribble: he has the ball (or touches it before our box closes) and can still dribble -> the slide is his
		do
			local own = liveOwnerId()
			local hasBall = (f.actor and own == f.actor.UserId) or (f.first ~= nil and f.first <= t1 + ping * 0.5 + 0.1)
			local ds = f.actor and Mark.dribState(f.actor, f.model, os.clock() + ping * 0.5 + (t0 + t1) * 0.5, hasBall) or "noball"
			if f.actor and Mark.foeCharging(f.actor.UserId) then
				why[#why + 1] = name .. " charging"
				continue
			end
			if ds == "iframe" or (ds == "ready" and CFG.TacklePerfect ~= false) then
				why[#why + 1] = name .. " dribble " .. ds
				continue
			end
			f.drib = ds
		end
		if (f.delay or 0) > 0 then
			why[#why + 1] = name .. " down"
			continue
		end
		-- Perfect Mode: a man in his OWN slide cannot dribble and his path is a locked heading dash (lockEnemySlide) - he is a
		-- target; with it off the old rule stands (no slide at a slider)
		local slideLock, slideEl = nil, nil
		if f.sliding then
			if CFG.TacklePerfect == false then
				why[#why + 1] = name .. " sliding"
				continue
			end
			slideLock, slideEl = lockEnemySlide(f.model, f.root)
			if not slideLock then
				why[#why + 1] = name .. " sliding (no lock)"
				continue
			end
		end
		local delay = math.clamp(CharacterMotion.GetDisplayDelaySeconds(f.model) or 0, 0, 0.25)
		if vel.Magnitude > 32 then
			vel = vel.Unit * 32
		end
		local E = {}
		for k = 1, #fine do
			if slideLock then
				E[k] = slideLock.origin + slideLock.heading * Mark.dumpTravel(math.min(slideEl + ping * 0.5 + fine[k], C.TotalMotionSeconds))
			else
				E[k] = pos + vel * (delay + ping * 0.5 + fine[k])
			end
		end
		local racer = dBall <= (CFG.KillerRadius or 22) or (f.first or math.huge) <= (ourT or math.huge) + (CFG.KillerMargin or 0.5)
		cands[#cands + 1] = { f = f, name = name, pos = pos, dUs = dUs, dBall = dBall, E = E, racer = racer or guard }
	end
	local function hitsOf(c, phi, m)
		local hits = 0
		for k = 1, #fine do
			local ctr = O + phi * (fineD[k] * m + boxMid)
			local rel = flat(c.E[k] - ctr)
			if math.abs(rel:Dot(phi)) <= hz and math.abs(rel.X * phi.Z - rel.Z * phi.X) <= hx then
				hits += 1
			end
		end
		return hits
	end
	local mates = nil
	local best = nil
	-- 2) per target: the slide that catches him, and among those the one that also catches the most other enemies (a
	-- cluster at the ball: two men in one slide). Ranked by who is nearest to the ball, not who is nearest to us.
	for _, c in cands do
		if not c.racer then
			why[#why + 1] = c.name .. string.format(" notracer ball %.0f first %.2f us %.2f", c.dBall, c.f.first or -1, ourT or -1)
			continue
		end
		local found = nil
		local base = (not guard and routeDir) or unitOrNil(flat(c.pos - O))
		if base then
			for step = 0, math.floor(maxA / 3) do
				for _, sg in (step == 0 and { 1 } or { 1, -1 }) do
					local a = math.rad(step * 3 * sg)
					local ca, sa = math.cos(a), math.sin(a)
					local phi = Vector3.new(base.X * ca - base.Z * sa, 0, base.X * sa + base.Z * ca)
					for mi = 0, 4 do
						local m = mLo + (mHi - mLo) * mi / 4
						local hits = hitsOf(c, phi, m)
						if hits >= minHits then
							local extra, names = 0, nil
							for _, o in cands do
								if o ~= c and hitsOf(o, phi, m) >= minHits then
									extra += 1
									names = (names and names .. "+" or "") .. o.name
								end
							end
							if not found or extra > found.extra or (extra == found.extra and hits > found.hits) then
								found = { aim = phi, mult = m, hits = hits, ang = step * 3 * sg, extra = extra, also = names }
							end
						end
					end
				end
				-- alone at the ball: the first (straightest) direction is enough; with others around keep looking for one
				-- that takes two
				if found and (#cands == 1 or found.extra > 0) then
					break
				end
			end
		end
		if not found then
			why[#why + 1] = c.name .. string.format(" angle (dist %.0f)", c.dUs)
			continue
		end
		if not mates then
			mates = {}
			for _, mm in Mark.models() do
				local a = Actors.GetFromCharacter(mm)
				if a and a ~= LocalPlayer and sameTeam(a) then
					local ar = ActorTargeting.GetActorRoot(a)
					if ar then
						mates[#mates + 1] = ar.Position
					end
				end
			end
		end
		local clear = true
		for _, mp in mates do
			local rel = flat(mp - O)
			local along = rel:Dot(found.aim)
			if along > 0 and along < c.dUs + 3 and math.abs(rel.X * found.aim.Z - rel.Z * found.aim.X) < 2.6 then
				clear = false
				break
			end
		end
		if not clear then
			why[#why + 1] = c.name .. " mate on line"
			continue
		end
		-- rank: two in one slide first, then the man nearest to the ball (he is the one who gets it), then who reaches it
		-- first, a small bonus for staying close to our route
		local score = -found.extra * 2 + c.dBall / 12 + (c.f.first or 3) * 0.5 + math.abs(found.ang) * 0.004
		if not best or score < best.score then
			found.foe, found.dist, found.dBall, found.name, found.score = c.f, c.dUs, c.dBall, c.name, score
			best = found
		end
	end
	return best, table.concat(why, "; ")
end

-- GOAL GUARD (AutoBlock): a free ball whose predicted path crosses OUR mouth within BlockGoalTime s. Returns the crossing
-- ({ i = first sample past the line, t, p, lat }) or nil. goalMouthCorners' last value is the face normal pointing into the
-- field, so "along" is the distance in front of the line.
Mark.goalThreat = function(samples, ts)
	local g = Mark.defendGoal()
	if not (g and samples and #samples >= 3) then
		return nil
	end
	local lb, lt, rb, _, _, n = goalMouthCorners(g)
	local fwd = n and unitOrNil(flat(n))
	if not (lb and rb and lt and fwd) then
		return nil
	end
	local mc = (lb + rb) * 0.5
	local side = Vector3.new(-fwd.Z, 0, fwd.X)
	local half = flat(rb - lb).Magnitude * 0.5
	local bottomY, topY = math.min(lb.Y, rb.Y), math.max(lt.Y, math.min(lb.Y, rb.Y) + 4)
	local prev = flat(samples[1] - mc):Dot(fwd)
	for i = 2, #samples do
		local a = flat(samples[i] - mc):Dot(fwd)
		if a <= 0.5 then
			if prev <= a then
				return nil -- not moving towards the line
			end
			local k = math.clamp((prev - 0.5) / (prev - a), 0, 1)
			local p = samples[i - 1]:Lerp(samples[i], k)
			local t = ts[i - 1] + (ts[i] - ts[i - 1]) * k
			local lat = flat(p - mc):Dot(side)
			if t <= (CFG.BlockGoalTime or 3) and math.abs(lat) <= half + 1.5 and p.Y >= bottomY - 1.5 and p.Y <= topY + 1.5 then
				return { i = i, t = t, p = p, lat = lat }
			end
			return nil
		end
		prev = a
	end
	return nil
end

-- WHY AUTOBALL DID NOTHING for a loose ball that passes close (user: "it sometimes ignores balls that fly right by me"). Every
-- silent return of tickBall calls this with its reason: if the ball path comes within 20 studs of us in the next 1.5 s (and
-- the ball is not owned) one `ball idle` line says which gate fired, with the closest approach and our state.
Mark.ballIdle = function(root, why)
	local now = os.clock()
	if now - (Mark.ballIdleAt or 0) < 0.5 then
		return
	end
	local pos, vel, S, T = Mark.ballPath(root)
	if not (pos and S and vel.Magnitude > 6) then
		return
	end
	local oid = liveOwnerId()
	if type(oid) == "number" and oid ~= 0 then
		return
	end
	local O = root.Position
	local bd, bt, bh = math.huge, 0, 0
	for i = 1, #S do
		if T[i] > 1.5 then
			break
		end
		local d = flat(S[i] - O).Magnitude
		if d < bd and S[i].Y - O.Y < 12 then
			bd, bt, bh = d, T[i], S[i].Y - O.Y
		end
	end
	if bd <= 20 then
		Mark.ballIdleAt = now
		local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
		logFile("ball idle", why, "closest", string.format("%.1f", bd), "at", string.format("%.2f", bt), "h", string.format("%.1f", bh), "ball v", string.format("%.0f", vel.Magnitude), "ws", hum and string.format("%.1f", hum.WalkSpeed) or "-", "mode", tostring(Mark.move.mode), "AutoBall", tostring(CFG.AutoBall))
	end
end

-- SHOT AUDIT. The log had the first 0.2 s of every shot and nothing about where it ended: "flick / straight shots fly over" could
-- not be checked. Now every released shot is followed to the goal plane and compared with the flight the solver PREDICTED (the
-- preview at the release): height and side where it crosses, and when. The height error is kept per class (straight / flick /
-- curve) and the solver aims lower by the median of the recent ones that flew HIGH (Mark.calBias): the bar margin grows by what
-- the last shots proved, not by a guess. A save, a block or a deflection (the ball is late / off line) is not a sample.
Mark.shotClass = function(curve, air)
	if air then
		return "flick"
	end
	return (curve ~= nil and curve ~= 0) and "curve" or "straight"
end

-- the first crossing of the plane through `mouth` with the horizontal normal `out` (pointing from the goal to the shooter) by a
-- polyline: the point and its time (ts optional)
Mark.planeCross = function(pts, mouth, out, ts)
	for i = 2, #pts do
		local a0 = flat(pts[i - 1] - mouth):Dot(out)
		local a1 = flat(pts[i] - mouth):Dot(out)
		if a0 > 0 and a1 <= 0 then
			local f = a0 / math.max(a0 - a1, 1e-6)
			return pts[i - 1]:Lerp(pts[i], f), ts and (ts[i - 1] + (ts[i] - ts[i - 1]) * f) or nil
		end
	end
	return nil
end

Mark.shotCal = { straight = {}, flick = {}, curve = {} }
Mark.calAdd = function(cls, dh)
	local l = Mark.shotCal[cls]
	l[#l + 1] = dh
	while #l > 6 do
		table.remove(l, 1)
	end
end
-- how many studs HIGH the class flew over its prediction (median of the last 6, needs 2); 0 when it flew low or is unknown. The
-- solver adds it to the bar margin and takes it off the aim height.
Mark.calBias = function(cls)
	if CFG.ShootCalib == false then
		return 0
	end
	local l = Mark.shotCal[cls]
	if not l or #l < 2 then
		return 0
	end
	local s = table.clone(l)
	table.sort(s)
	local med = s[math.floor((#s + 1) / 2)]
	return math.clamp(med, 0, 2.5)
end

-- follow the released shot (Mark.shotAudit, set at the release) to the goal plane
Mark.shotWatch = function()
	local A = Mark.shotAudit
	if not A then
		return
	end
	local now = os.clock()
	local p = Renderer.GetPosition()
	if typeof(p) ~= "Vector3" then
		return
	end
	local function done(...)
		Mark.shotAudit = nil
		logFile("shoot result", A.cls, A.name, ...)
	end
	if now - A.at > 3.2 then
		done("no crossing", "pred h", string.format("%.1f", A.predH or -1))
		return
	end
	local prev = A.prev
	A.prev = p
	if not prev then
		return
	end
	local q = Mark.planeCross({ prev, p }, A.mouth, A.out)
	if not q then
		return
	end
	local lat = flat(q - A.mouth):Dot(A.side)
	local h = (q - A.bottom):Dot(A.up)
	local t = now - A.at
	local dh, dlat = h - (A.predH or h), lat - (A.predLat or lat)
	-- a sample only when the flight went as predicted to the plane (a deflected / saved ball is off in time or side)
	local clean = A.predH ~= nil and math.abs(t - (A.predT or t)) <= 0.45 and math.abs(dlat) <= 4
	if clean then
		Mark.calAdd(A.cls, dh)
	end
	local inside = math.abs(lat) <= A.half and h >= 0 and h <= A.mouthH
	done(inside and "IN" or (h > A.mouthH and "OVER" or (math.abs(lat) > A.half and "WIDE" or "UNDER")), "h", string.format("%.1f", h), "pred", string.format("%.1f", A.predH or -1),
		"dh", string.format("%.1f", dh), "side", string.format("%.1f", lat), "pred", string.format("%.1f", A.predLat or 0), "dside", string.format("%.1f", dlat), "t", string.format("%.2f", t),
		"pred t", string.format("%.2f", A.predT or -1), clean and "sample" or "not a sample", "bias", string.format("%.1f", Mark.calBias(A.cls)), "dist", string.format("%.0f", A.dist))
end

-- the audit of a shot that has just been released: the predicted flight is the preview of the release
Mark.shotAuditStart = function(pv, p0)
	local goal = enemyGoalPart()
	local lb, lt, rb, rt = goalMouthCorners(goal)
	if not (pv and pv.pts and lb and lt and rb and rt and typeof(p0) == "Vector3") then
		return
	end
	local bottom = (lb + rb) * 0.5
	local rise = (lt + rt) * 0.5 - bottom
	local side = unitOrNil(flat(rb - lb))
	if not side then
		return
	end
	local out = Vector3.new(-side.Z, 0, side.X)
	if flat(p0 - bottom):Dot(out) < 0 then
		out = -out
	end
	local A = { at = os.clock(), mouth = bottom, bottom = bottom, up = rise.Magnitude > 0.4 and rise.Unit or Vector3.yAxis, side = side, out = out,
		half = flat(rb - lb).Magnitude * 0.5, mouthH = math.max(rise.Magnitude, 1), dist = flat(p0 - bottom).Magnitude,
		cls = Mark.shotClass(Shoot.curve, (Mark.flickStrike ~= nil and os.clock() < Mark.flickStrike) or Mark.aerial ~= nil or Mark.forceBike == true), name = Shoot.shotName or "?" }
	local q, t = Mark.planeCross(pv.pts, bottom, out, pv.times)
	if q then
		A.predH, A.predLat, A.predT = (q - bottom):Dot(A.up), flat(q - bottom):Dot(side), t
	end
	Mark.shotAudit = A
end

-- ITEM BOXES. Dump: a box is a Model tagged "GameplayItemBox" (ItemBoxes.TagName) with a Hitbox part; Hitbox.CanTouch false =
-- claimed / not there (ItemBoxVisuals.shouldShowItemBox). The server grants on touch and tells the clients only
-- {Kind "ItemBoxClaimed", BoxName}: the content is NOT replicated - the box shows a "?" and the roll is server side
-- (ItemTiers.RollWeightedItemId over the claimer's own item pool, recent grants down-weighted). Nothing to read before the
-- touch. Race decision (pure): myEta against rivals {eta, closing}; "go" when nobody closing beats us by `margin`,
-- "stun" when a closing rival wins but is inside slide reach (a slide stuns him and we are nearer the box afterwards),
-- else "skip".
Mark.boxPlan = function(myEta, rivals, margin, mates)
	for _, e in mates do
		if e < myEta - margin then
			return "skip", "mate"
		end
	end
	local worst, wd = nil, math.huge
	for _, r in rivals do
		if r.closing and r.eta < myEta + margin and r.eta < wd then
			worst, wd = r, r.eta
		end
	end
	if not worst then
		return "go"
	end
	if worst.reach then
		return "stun", worst
	end
	return "skip", "rival"
end

-- Item slots: ItemCommands.Constants.SlotCount = 2 (dump; the 4 it was written with was a guess - the box was chased with
-- both slots full: user "AutoBox goes for the box with 2 skills, the maximum is 2"). Mark.boxCount was lost in the v188
-- rewrite of tickBox: `attempt to call a nil value` in boxStep every frame.
Mark.slotCount = function()
	Mark.itemCmds = Mark.itemCmds or require(Modules.Items.ItemCommands)
	return Mark.itemCmds.Constants.SlotCount
end
Mark.boxCount = function()
	local s = Mark.itemSlots()
	local n = 0
	if s then
		for i = 1, Mark.slotCount() do
			-- an EMPTY slot is a table too ({ ItemId = nil }: the log prints "item slots 1=nil 2=nil"); only an ItemId fills it.
			-- v190 counted every table and read two empty slots as full: "AutoBox stopped working"
			if type(s[i]) == "table" and s[i].ItemId ~= nil then
				n += 1
			end
		end
	end
	return n
end
Mark.boxFree = function()
	return Mark.boxCount() < Mark.slotCount()
end

-- a condition must hold `onT` s to turn true and fail `offT` s to turn false: a one-frame flicker (the ball owner flips
-- between "nobody" and "him" at a touch) used to stop the run and zero the stick every other frame - the log showed
-- `box go` 120 times a second with the distance frozen
Mark.boxDeb = {}
Mark.boxHold = function(key, cond, onT, offT)
	local now = os.clock()
	local s = Mark.boxDeb[key]
	if not s then
		s = { v = false }
		Mark.boxDeb[key] = s
	end
	if cond == s.v then
		s.pend = nil
	else
		s.pend = s.pend or now
		if now - s.pend >= (cond and onT or offT) then
			s.v, s.pend = cond, nil
		end
	end
	return s.v
end

-- Seconds to cover d studs: the body accelerates from the speed it already has TOWARD the target (v0, 0..speed) to `speed` over
-- `ramp` s (CFG.BallRamp), then runs. The old race was d / WalkSpeed: a standing rival and a runner at full speed were the same.
Mark.boxEta = function(d, speed, v0, ramp)
	if d <= 0 then
		return 0
	end
	speed = math.max(speed, 1)
	v0 = math.clamp(v0, 0, speed)
	ramp = math.max(ramp, 0.05)
	local acc = (speed - v0) / ramp
	local dRamp = (speed + v0) * 0.5 * ramp
	if d <= dRamp then
		if acc < 1e-6 then
			return d / math.max(v0, 1e-6)
		end
		return (math.sqrt(v0 * v0 + 2 * acc * d) - v0) / acc
	end
	return ramp + (d - dRamp) / speed
end

-- Which box to run for. cands = { { part, bd, eta, plan } }: a box we win ("go") beats one we can only take by stunning a rival
-- ("stun"), that beats a lost race ("skip", kept only so the overlay has something to show: the nearest). Inside a rank the soonest
-- arrival; the box we already run for counts 20 % sooner (a pick that flips between two boxes every 0.1 s is two half runs).
Mark.boxPick = function(cands, runPart)
	local rank = { go = 0, stun = 1, skip = 2 }
	local best, bestKey = nil, math.huge
	for _, c in cands do
		local r = rank[c.plan]
		local key = r * 1000 + (r < 2 and c.eta * (c.part == runPart and 0.8 or 1) or c.bd)
		if key < bestKey then
			best, bestKey = c, key
		end
	end
	return best
end

-- the plan for the best live box, at 10 Hz: who gets there first and what we do about it. EVERY box in range is raced, not only the
-- nearest: the nearest one is the one rivals stand at, another a few studs farther is often free.
Mark.boxScan = function(character, root, hum)
	local now = os.clock()
	local N = Mark.boxNow
	if N and now - N.at < 0.1 then
		return N
	end
	N = { at = now, others = {}, rivals = {} }
	Mark.boxNow = N
	local O = root.Position
	local lim = CFG.BoxMaxDist or 45
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local ramp = CFG.BallRamp or 0.2
	local speed = math.max(hum.WalkSpeed, 16)
	local v0 = flat(root.AssemblyLinearVelocity)
	local boxes = {}
	for _, b in CollectionService:GetTagged("GameplayItemBox") do
		local hb = b:FindFirstChild("Hitbox")
		if hb and hb.CanTouch then
			local d = flat(hb.Position - O).Magnitude
			if d <= lim then
				boxes[#boxes + 1] = { part = hb, bd = d }
			elseif d <= lim * 1.5 then
				N.others[#N.others + 1] = hb.Position
			end
		end
	end
	if #boxes == 0 then
		return N
	end
	-- the racers once (the same men for every box). An enemy is seen DISPLAY DELAY behind where he runs: his pose is advanced by it.
	local mates, foes = {}, {}
	for _, pl in Players:GetPlayers() do
		if pl ~= LocalPlayer and not isGoalkeeper(pl) then
			local hr = ActorTargeting.GetActorRoot(pl)
			local ch = Actors.GetCharacter(pl)
			local hh = ch and ch:FindFirstChildOfClass("Humanoid")
			if hr and hh and hh.Health > 0 then
				local pos, vel = Mark.carrierPose(hr, ch)
				if not sameTeam(pl) then
					pos = pos + flat(vel) * math.clamp(CharacterMotion.GetDisplayDelaySeconds(ch) or 0, 0, 0.25)
				end
				local rec = { pl = pl, root = hr, pos = pos, v = flat(vel), speed = math.max(hh.WalkSpeed, 16) }
				if sameTeam(pl) then
					mates[#mates + 1] = rec
				else
					foes[#foes + 1] = rec
				end
			end
		end
	end
	local runPart = Mark.boxRun and Mark.boxRun.part
	for _, c in boxes do
		local P = c.part.Position
		local R = math.max(c.part.Size.X, c.part.Size.Z) * 0.5 -- the Hitbox the server touches against
		local u = unitOrNil(flat(P - O))
		c.P, c.R = P, R
		c.eta = Mark.boxEta(math.max(c.bd - R * 0.9, 0), speed, u and v0:Dot(u) or 0, ramp) + ping * 0.5 -- the server sees us ping/2 late
		c.rivals, c.mateEta = {}, {}
		for _, f in foes do
			local to = flat(P - f.pos)
			local d = to.Magnitude
			local fu = unitOrNil(to)
			local eta = Mark.boxEta(math.max(d - R * 0.9, 0), f.speed, fu and f.v:Dot(fu) or 0, ramp)
			-- coming at it, or on top of it, or a man much nearer than us who will simply start (a standing enemy next to a box
			-- was "not closing" and a race we were about to lose looked free)
			local closing = d < 10 or (f.v.Magnitude > 4 and fu ~= nil and fu:Dot(f.v.Unit) > 0.5) or (eta < c.eta - 0.15 and eta < 1.2)
			local rec = { eta = eta, closing = closing, pl = f.pl, root = f.root, pos = f.pos, v = f.v, speed = f.speed }
			rec.reach = closing and flat(f.root.Position - O).Magnitude <= math.min(CFG.TackleReach or 18, 14)
			c.rivals[#c.rivals + 1] = rec
		end
		for _, m in mates do
			local to = flat(P - m.pos)
			local mu = unitOrNil(to)
			c.mateEta[#c.mateEta + 1] = Mark.boxEta(math.max(to.Magnitude - R * 0.9, 0), m.speed, mu and m.v:Dot(mu) or 0, ramp)
		end
		-- a run already on this box is kept unless a rival wins it outright (0.05 s margin instead of 0.3)
		c.plan, c.who = Mark.boxPlan(c.eta, c.rivals, c.part == runPart and 0.05 or (CFG.BoxMargin or 0.3), c.mateEta)
	end
	local pick = Mark.boxPick(boxes, runPart)
	for _, c in boxes do
		if c ~= pick then
			N.others[#N.others + 1] = c.P
		end
	end
	N.part, N.P, N.bd, N.R, N.rivals, N.plan, N.who = pick.part, pick.P, pick.bd, pick.R, pick.rivals, pick.plan, pick.who
	N.myV, N.myEta, N.ping, N.boxes = speed, pick.eta, ping, #boxes
	return N
end

-- A run that is on and winning: AutoBall may not take the body for a ball we cannot get to soon anyway (the log: `box go` and 0.1-0.4 s
-- later `box end mode ball` for a free ball 50-75 studs away, our ETA 1.9-2.6 s, the box 1.3 s). ONLY for the near box (CFG.BoxCommitEta).
Mark.boxCommit = function()
	local r, N = Mark.boxRun, Mark.boxNow
	return r ~= nil and N ~= nil and N.part == r.part and N.plan == "go" and N.myEta <= (CFG.BoxCommitEta or 1.6) and os.clock() - N.at < 0.3
end

Mark.boxEnd = function(why)
	local m = Mark.move
	if m.mode == "box" then
		Mark.moveStop("box")
	end
	-- AutoBox on and doing nothing must say why (v190: two empty slots read as full and the feature was silent for a whole session)
	-- (one line per reason per 5 s: two reasons alternating frame to frame - "no box" / "mode block" - wrote 300 lines in 100 s)
	if CFG.AutoBox and why ~= "off" and not Mark.boxRun then
		Mark.boxIdle = Mark.boxIdle or {}
		if os.clock() - (Mark.boxIdle[why] or 0) > 5 then
			Mark.boxIdle[why] = os.clock()
			logFile("box idle", why)
		end
	end
	local r = Mark.boxRun
	if r then
		Mark.boxRun = nil
		logFile("box end", why, "ran", string.format("%.1f", os.clock() - r.at), "dist", string.format("%.1f", r.last or -1), "from", string.format("%.1f", r.d0))
	end
	Mark.boxWhy = why
end

Mark.boxStep = function(character, root)
	local m = Mark.move
	if not CFG.AutoBox then
		Mark.boxEnd("off")
		return
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	if not hum or Mark.meKeeper() or Mark.slideBody() or Mark.aerial or Mark.duel or not CharacterControllers.IsLanded(character, hum) then
		Mark.boxEnd("busy")
		return
	end
	if Mark.moveLive(m) and m.mode ~= "box" then
		Mark.boxEnd("mode " .. tostring(m.mode)) -- another module owns the body
		return
	end
	local oid = liveOwnerId()
	local carried = type(oid) == "number" and oid ~= 0 and not (playerOf(oid) and sameTeam(playerOf(oid)) and oid ~= LocalPlayer.UserId)
	if Mark.boxHold("carried", carried, 0.25, 0.25) then
		Mark.boxEnd("ball carried") -- we or an enemy carry: the ball is the job
		return
	end
	if not Mark.boxFree() then
		Mark.boxEnd("slots full")
		return
	end
	local N = Mark.boxScan(character, root, hum)
	if not N.part then
		Mark.boxEnd("no box")
		return
	end
	-- practice maps have no goal part: nothing to keep the ball away from there
	local goal = ourGoalPart()
	local lb, _, rb
	if goal then
		lb, _, rb = goalMouthCorners(goal)
	end
	local ballP = Renderer.GetPosition()
	if lb and rb and typeof(ballP) == "Vector3" and flat(ballP - (lb + rb) * 0.5).Magnitude < (CFG.BoxBallSafe or 45) then
		Mark.boxEnd("ball near our goal")
		return
	end
	Mark.boxVis = os.clock() -- the plan is live: the overlay shows it
	if N.plan == "skip" then
		Mark.boxEnd("skip " .. tostring(N.who == "mate" and "mate" or "rival"))
		return
	end
	local O = root.Position
	if N.plan == "stun" then
		local r = N.who
		local aimP = r.root.Position + r.v * (0.25 + N.ping * 0.5)
		local dir = unitOrNil(flat(aimP - O))
		if dir then
			local ok, why = tryTackle(character, root, dir, nil, nil, false, nil)
			-- a refusal for the cooldown is not an attempt; every other answer is logged when it changes
			if ok or (why ~= "cd" and why ~= "reject-wait") then
				Mark.teleAdd("box.stun", ok == true)
			end
			local key = ok and "ok" or tostring(why)
			if key ~= Mark.boxStunKey or os.clock() - (Mark.boxStunAt or 0) > 1 then
				Mark.boxStunKey, Mark.boxStunAt = key, os.clock()
				logFile("box stun", ok and "ok" or "refused", tostring(why), "rival eta", string.format("%.2f", r.eta), "my eta", string.format("%.2f", N.myEta), "dist", string.format("%.1f", flat(r.root.Position - O).Magnitude))
			end
			if ok then
				return
			end
		end
		Mark.boxEnd("stun refused")
		return
	end
	local bd = flat(N.P - O).Magnitude
	if bd < 1.0 then
		Mark.boxEnd("at box")
		return
	end
	local dir = unitOrNil(flat(N.P - O))
	if Mark.boxRun and Mark.boxRun.part ~= N.part then
		Mark.boxEnd("another box") -- a rival took it / a better one appeared: the new run is logged as its own
	end
	if not Mark.boxRun then
		Mark.boxRun = { at = os.clock(), part = N.part, d0 = bd }
		Mark.boxTrack = { at = os.clock(), part = N.part, n0 = Mark.boxCount() }
		Mark.boxWhy = "go"
		logFile("box go", "dist", string.format("%.1f", bd), "eta", string.format("%.2f", N.myEta), "rivals", #N.rivals, "boxes", N.boxes or 1, "R", string.format("%.1f", N.R))
	end
	Mark.boxRun.last = bd
	Mark.moveSteer(dir, "box")
end

-- AUTOBOX OVERLAY, a photo finish. No text: who wins the box is geometry. Every racer is a thread laid on the floor from his feet to
-- the box (ink bed under a thin colour line, as the route line). The racer who gets there FIRST carries chevrons running to the
-- box; every other racer has a bar across his thread at the spot he will have reached when the winner touches, and a dashed
-- gap from that bar to the box - the length of the dashes is what he loses by. Colours are the roles of the other overlays:
-- mint = ours (Mark.defPalette), red / amber = an enemy action (Mark.kickPalette). The box is the squircle footprint of its
-- Hitbox; the plan is the footprint's state:
--   go    mint footprint + mint ripple rings born at the box (we take it)
--   skip  amber footprint, still (a rival wins it, we do not run) / steel footprint (a mate is nearer)
--   stun  amber footprint + red ripple on the rival we slide into
-- Other boxes in range are four corner ticks. v = { gy, me, myV, myEta, P, R, plan, who, rivals = { { pos, speed, eta, closing } },
-- others, stunAt }. One renderer for the live overlay and the gallery station.
Mark.boxArt = function(seg, v, t)
	local gy, INK = v.gy, COL.Ink
	local P = Vector3.new(v.P.X, gy + 0.08, v.P.Z)
	local mint, steel = Mark.defPalette.armed[1], Mark.defPalette.safe[1]
	local red, amber = Mark.kickPalette.live[1], Mark.kickPalette.armed[1]
	local function floor(p)
		return Vector3.new(p.X, gy + 0.08, p.Z)
	end
	local function thread(from, col, alpha, thick)
		seg(from, P, INK, alpha * 0.5, thick + 2, 39)
		seg(from, P, col, alpha, thick, 41)
	end
	-- the bar at the point this racer has reached when the winner arrives (T s), and the dashed gap to the box
	local function lag(from, speed, T, col)
		local to = P - from
		local d = to.Magnitude
		if d < 1 then
			return
		end
		local dir = to / d
		local run = math.min(speed * T, d)
		local m = from + dir * run
		local side = Vector3.new(-dir.Z, 0, dir.X) * 1.7
		seg(m - side, m + side, INK, 0.8, 4.2, 39)
		seg(m - side, m + side, col, 1, 2.2, 42)
		local gap = d - run
		local n = math.min(6, math.floor(gap / 1.6))
		for k = 0, n - 1 do
			seg(m + dir * (gap * k / n + 0.5), m + dir * (gap * (k + 0.55) / n), col, 0.6, 1.3, 41)
		end
	end
	-- chevrons running to the box: three on the thread, phase accumulated (never read off the clock)
	local function lead(from, col, key)
		local to = P - from
		local d = to.Magnitude
		if d < 4 then
			return
		end
		local dir = to / d
		local side = Vector3.new(-dir.Z, 0, dir.X)
		local ph = Mark.rippleStep(key, 0.9)
		for k = 0, 2 do
			local u = (ph + k / 3) % 1
			local c = from + dir * (d * u)
			local a = math.sin(u * math.pi) ^ 0.7
			seg(c - dir * 1.1 + side * 1.0, c, col, a, 1.8, 42)
			seg(c - dir * 1.1 - side * 1.0, c, col, a, 1.8, 42)
		end
	end
	local function footprint(col, alpha, thick)
		local prev = nil
		for s = 0, 20 do
			local a = s / 20 * math.pi * 2
			local c, sn = math.cos(a), math.sin(a)
			local p = P + Vector3.new((c >= 0 and 1 or -1) * math.sqrt(math.abs(c)), 0, (sn >= 0 and 1 or -1) * math.sqrt(math.abs(sn))) * v.R
			if prev then
				seg(prev, p, INK, alpha * 0.5, thick + 2, 39)
				seg(prev, p, col, alpha, thick, 42)
			end
			prev = p
		end
	end
	for _, q in v.others do
		local c = floor(q)
		for k = 0, 3 do
			local a = k * math.pi / 2 + math.pi / 4
			local u, w = Vector3.new(math.cos(a), 0, math.sin(a)), Vector3.new(-math.sin(a), 0, math.cos(a))
			local at = c + u * 2.2
			seg(at + w * 0.9, at, COL.Chalk, 0.4, 1, 40)
			seg(at - w * 0.9, at, COL.Chalk, 0.4, 1, 40)
		end
	end
	local me = floor(v.me)
	local winner, T = "me", v.myEta
	for _, r in v.rivals do
		if r.closing and r.eta < T then
			winner, T = r, r.eta
		end
	end
	if v.plan == "go" then
		footprint(mint, 0.95, 1.6)
		Mark.kickRipple(seg, P, v.R * 2.2, Mark.defPalette.armed, Mark.rippleStep("box-go", Mark.rippleRates.armed), t, 4)
	elseif v.plan == "stun" then
		footprint(amber, 0.9, 1.6)
	elseif v.who == "mate" then
		footprint(steel, 0.8, 1.4)
		return
	else
		footprint(amber, 0.9, 1.6)
	end
	thread(me, winner == "me" and mint or steel, winner == "me" and 0.55 or 0.3, 1.2)
	if winner == "me" then
		lead(me, mint, "box-me")
	else
		lag(me, v.myV, T, steel)
	end
	for _, r in v.rivals do
		if r.closing then
			local from = floor(r.pos)
			thread(from, red, r == winner and 0.6 or 0.35, 1.2)
			if r == winner then
				lead(from, red, "box-foe")
			else
				lag(from, r.speed, T, red)
			end
		end
	end
	if v.plan == "stun" and v.stunAt then
		Mark.kickRipple(seg, floor(v.stunAt), 2.8, Mark.kickPalette.live, Mark.rippleStep("box-stun", Mark.rippleRates.live), t, 4)
	end
end

Mark.drawBox = function(root)
	Mark.boxLines = Mark.boxLines or makeLines(220, 1.4, 40)
	Mark.boxPool = Mark.boxPool or Mark.segPool(Mark.boxLines)
	local pool = Mark.boxPool
	local N = Mark.boxNow
	if CFG.Draw and CFG.AutoBox and CFG.DrawBox ~= false and N and N.part and os.clock() - (Mark.boxVis or -1) < 0.3 and Workspace.CurrentCamera then
		local stunAt = nil
		if N.plan == "stun" then
			stunAt = N.who.root.Position + N.who.v * (0.25 + N.ping * 0.5)
		end
		local others = {}
		for i = 1, math.min(#N.others, 4) do
			others[i] = N.others[i]
		end
		Mark.boxArt(pool.seg, {
			gy = root.Position.Y - 2.9, me = root.Position, myV = N.myV, myEta = N.myEta, P = N.P, R = N.R,
			plan = N.plan, who = N.who, rivals = N.rivals, others = others, stunAt = stunAt,
		}, os.clock())
	end
	pool.finish()
end

Mark.tickBox = function(character, root)
	Mark.boxStep(character, root)
	Mark.drawBox(root)
end

-- result of a box run: the box gone -> did a slot fill (we got it) or not (a rival did)? Checked while we run for it and
-- for 3 s after; a box still there 3 s after the run ended is dropped
Mark.boxResult = function()
	local t = Mark.boxTrack
	if not t then
		return
	end
	local now = os.clock()
	local gone = not (t.part.Parent and t.part.CanTouch)
	if not gone and not Mark.boxRun and now - (t.endAt or now) > 3 then
		t.endAt = nil
		Mark.boxTrack = nil
		return
	end
	if not Mark.boxRun and not t.endAt then
		t.endAt = now
	end
	if gone then
		t.goneAt = t.goneAt or now
		Mark.slotsCache = nil
		local n = Mark.boxCount()
		local got = n > (t.n0 or 0)
		-- the box leaves the world one trip before the item state arrives: "lost to a rival" was written at that moment
		-- for boxes we took (box.take 2/5 in telemetry). Wait for the slot, 0.8 s at most.
		if not got and now - t.goneAt < 0.8 then
			return
		end
		Mark.boxTrack = nil
		Mark.teleAdd("box.take", got)
		logFile("box result", got and "taken" or "lost to a rival", "slots", n, "after", string.format("%.1f", now - t.at))
	end
end

Mark.tickBall = function(character, root)
	local guardOn = CFG.AutoBlock and CFG.BlockGoal ~= false
	if not CFG.AutoBall and not guardOn then
		return
	end
	if not Mark.playLive() then
		Mark.ballStop("intermission")
		if Mark.ballWhy ~= "intermission" then
			Mark.ballWhy = "intermission"
			logFile("ball", "intermission")
		end
		return
	end
	if Mark.move.mode == "dodge" or Mark.move.mode == "dribble" or Mark.move.mode == "flee" or Mark.aerial then
		Mark.ballIdle(root, "busy " .. (Mark.aerial and "aerial" or tostring(Mark.move.mode)))
		return
	end
	if Mark.duel or Mark.lobBusy() or Mark.airBusy() then
		Mark.ballIdle(root, Mark.duel and "duel" or (Mark.lobBusy() and "lob" or "air intercept"))
		return -- the air duel / the flick lob catch / Air Intercept owns the body
	end
	if Mark.move.mode == "block" then
		-- Block shadows a CARRIER. The moment he loses the ball nothing owned it for ~0.45 s (block hold) because this
		-- tick returned on mode == "block": that dead zone is where the enemy got to the loose ball first.
		local o = liveOwnerId()
		if type(o) == "number" and o ~= 0 then
			return
		end
	end
	if slideAim or Mark.slideBody() then
		Mark.ballIdle(root, "sliding")
		return
	end
	if ClientDodge.IsDribbling() or Mark.weOwn() then
		Mark.ballStop("own")
		return
	end
	-- Frozen (kickoff freeze: ws=0.0, jblock/sprintBlk/rot = Kickoff; also stun/ragdoll): there is nothing to run with.
	-- The log showed ball start / slideboost / tackle sent three times in a row at kickoff, every one a MISS, and a
	-- start/stop every 0.15 s at ws=0.
	do
		local humF = character:FindFirstChildOfClass("Humanoid")
		if humF and humF.WalkSpeed < 2 then
			Mark.ballStop("frozen")
			Mark.ballIdle(root, "frozen")
			return
		end
	end
	local oid = liveOwnerId()
	if type(oid) == "number" and oid ~= 0 then
		local a = playerOf(oid)
		if a and a ~= LocalPlayer and sameTeam(a) then
			Mark.allyKickUntil = os.clock() + 1.5
		end
		if Mark.move.mode == "ball" and (not Mark.ballLostAt or os.clock() - Mark.ballLostAt > 1) then
			Mark.ballLostAt = os.clock()
			local info = Mark.ballInfo
			logFile("ball lost", "to", a and actorName(a) or tostring(oid), "team", tostring(a ~= nil and sameTeam(a)), "age", string.format("%.2f", os.clock() - (Mark.move.born or os.clock())), "plan", info and info.mode or "-", "tUs", info and string.format("%.2f", info.tUs or 0) or "-", "margin", info and info.margin and string.format("%.2f", info.margin) or "-")
		end
		Mark.ballStop("owner")
		return
	end
	local pos, vel, samples, ts, live, rest = Mark.ballPath(root)
	if not pos then
		Mark.ballStop("no ball")
		return
	end
	-- Goal guard: the path is cut at our goal line (a contact point behind it / in the net is worthless), the enemy field
	-- players are no racers for a ball that is going in, and AutoBall may be off - the guard needs no other switch.
	local threat = nil
	if guardOn and not MatchSettings.IsGoalkeeperCharacter(character) then
		threat = Mark.goalThreat(samples, ts)
		if threat then
			local cs, ct = {}, {}
			for i = 1, threat.i - 1 do
				cs[i], ct[i] = samples[i], ts[i]
			end
			cs[#cs + 1], ct[#ct + 1] = threat.p, threat.t
			samples, ts, rest = cs, ct, false
			if not Mark.guardLog or os.clock() - Mark.guardLog > 0.8 then
				Mark.guardLog = os.clock()
				logFile("block goal", "threat", "t", string.format("%.2f", threat.t), "lat", string.format("%.1f", threat.lat), "h", string.format("%.1f", threat.p.Y - root.Position.Y), "speed", string.format("%.0f", vel.Magnitude))
			end
		end
	end
	if not CFG.AutoBall and not threat then
		Mark.ballStop("guard idle")
		return
	end
	do
		local sp = vel.Magnitude
		if sp > 4 then
			if os.clock() - (Mark.ballPeakAt or 0) > 0.8 then
				Mark.ballPeak = sp
			else
				Mark.ballPeak = math.max(Mark.ballPeak or 0, sp)
			end
			Mark.ballPeakAt = os.clock()
		elseif os.clock() - (Mark.ballPeakAt or 0) > 0.8 then
			Mark.ballPeak = sp
		end
	end
	local to = flat(pos - root.Position)
	local dist = to.Magnitude
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false) * 1.05
	-- HitboxSettings.Receive: Oval 5.5 x 5.25, CFrameOffset Y -0.45 around our root
	local receive = HitboxSettings.Receive
	local receiveHalf = receive.Size.X * 0.5
	local recvLo = receive.CFrameOffset.Y - receive.Size.Y * 0.5
	local recvHi = receive.CFrameOffset.Y + receive.Size.Y * 0.5
	local jumpH = Mark.jumpH or 7.2
	local steer, steerT, how = nil, nil, nil
	-- Enemy field players compete for the same loose ball (Ownership.FindNearestOwner: whoever's Receive hitbox the
	-- ball enters first); Mark.routePlan races every candidate contact against them.
	local foes = {}
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if actor and actor ~= LocalPlayer and not sameTeam(actor) and not isGoalkeeper(actor) then
			local fr = ActorTargeting.GetActorRoot(actor)
			local grT = nil
			if fr and Mark.grapples and Mark.grapples[actor.UserId] then
				-- he flies at the ball on a hook: his touch is the arrival of the pull, at any distance / height
				local _, tA = Mark.grapplePath(actor.UserId, model, (Mark.carrierPose(fr, model)), root)
				grT = tA or math.huge
				foes[#foes + 1] = { p = fr.Position, s = 75, root = fr, model = model, actor = actor, delay = 0, grappleT = grT, sliding = false }
			end
			if fr and not grT and not threat and flat(fr.Position - pos).Magnitude < 60 then
				-- delay = seconds until he can move again (stun / ragdoll / freeze ice / WalkSpeed 0): a downed enemy is not a
				-- racer for that long (it was: killer slides and "foe near" boosts at men who could not walk)
				local down, left = Mark.mateDown(actor, model)
				local delay = (down) and math.max(left or 0, 0.5) or 0
				local humF = model:FindFirstChildOfClass("Humanoid")
				if delay == 0 and humF and humF.WalkSpeed < 2 then
					delay = 0.5
				end
				local slideUntil = SlideTackle.GetSlidingUntil(model)
				local sliding = slideUntil ~= nil and Workspace:GetServerTimeNow() < slideUntil
				-- fr.Position is the DISPLAYED pose, behind his server pose by display delay + ping/2: the old race gave him
				-- those metres for free (log: "t 0.60 ourT 0.12", owner = the enemy 0.4 s later)
				local fpos, fvel = Mark.carrierPose(fr, model)
				local lead = math.clamp(CharacterMotion.GetDisplayDelaySeconds(model) or 0, 0, 0.25) + math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25) * 0.5
				if fvel.Magnitude > 32 then
					fvel = fvel.Unit * 32
				end
				foes[#foes + 1] = { p = fpos + fvel * lead, s = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false), root = fr, model = model, actor = actor, delay = delay, sliding = sliding }
			end
		end
	end
	-- GOAL GUARD (CFG.KillerGuard). A loose ball near OUR goal, we are near it: the enemy nearest to the ball is slid first.
	-- It used to live inside Rival Slide, after the route plan: off with Rival Slide, off with Slide Boost (readyB), and
	-- never reached exactly when it mattered - the enemy is closer to the ball, our plan loses the race, tickBall returned
	-- "no aim" before the guard. Now it runs first, on its own switch, against the plain tackle readiness.
	if CFG.KillerGuard ~= false and CFG.AutoTackle and not threat then
		local gGoal = Mark.defendGoal()
		local humG = character:FindFirstChildOfClass("Humanoid")
		if gGoal and humG and CharacterControllers.IsLanded(character, humG) and Mark.tackleReady(character) and not slideAim
			and not (Mark.allyKickUntil and os.clock() < Mark.allyKickUntil)
			and flat(pos - gGoal.Position).Magnitude <= (CFG.KillerGuardGoal or 55)
			and flat(pos - root.Position).Magnitude <= (CFG.KillerGuardNear or 22) then
			local bestF, bestD = nil, math.huge
			for _, f in foes do
				local dB = flat(f.p - pos).Magnitude
				if (f.delay or 0) <= 0 and not f.sliding and dB <= (CFG.KillerGuardFoe or 40) and dB < bestD then
					bestF, bestD = f, dB
				end
			end
			if bestF then
				local mHiG = math.max(0.4, CFG.TackleSpeed)
				local mLoG = math.min(mHiG, CFG.TackleMinSpeed or 0.6)
				local near = { bestF }
				for _, f in foes do
					if f ~= bestF and (f.delay or 0) <= 0 and not f.sliding and flat(f.p - pos).Magnitude <= (CFG.KillerGuardFoe or 40) then
						near[#near + 1] = f
					end
				end
				local k, kWhy = Mark.killerSlide(root, nil, near, pos, nil, mLoG, mHiG, true)
				if k then
					predict = solveIntercept(root, bestF.root, bestF.model, tackleTuning()) or predict
					local sent, why = tryTackle(character, root, k.aim, k.mult, { char = bestF.model, root = bestF.root })
					logFile("killer guard", sent and "sent" or ("no " .. tostring(why)), k.name, "also", k.also or "-", "ang", string.format("%.0f", k.ang), "hits", tostring(k.hits), "mult", string.format("%.2f", k.mult), "ballD", string.format("%.1f", bestD))
					if sent then
						return
					end
				elseif not Mark.guardSkipLog or os.clock() - Mark.guardSkipLog > 1 then
					Mark.guardSkipLog = os.clock()
					logFile("killer guard skip", kWhy or "-")
				end
			end
		end
	end
	-- real run speed: the speed boosts (ws 33.3 in the log) were planned as 26.9
	do
		local humS = character:FindFirstChildOfClass("Humanoid")
		if humS and humS.WalkSpeed > spd then
			spd = humS.WalkSpeed
		end
	end
	local boxS = HitboxSettings.SlideTackle
	local slideLo = boxS.CFrameOffset.Y - boxS.Size.Y * 0.5
	local slideHi = boxS.CFrameOffset.Y + boxS.Size.Y * 0.5
	local humB = character:FindFirstChildOfClass("Humanoid")
	local readyB = CFG.AutoTackle ~= false and CFG.BallBoost ~= false and humB and CharacterControllers.IsLanded(character, humB)
		and os.clock() - lastTackleAt >= tackleEnforced
		and not Ragdoll.IsActorRagdolled(LocalPlayer)
		and not (ChargedKick.IsCharging and ChargedKick.IsCharging())
		and not ActionLocks.HasTackleBlock(LocalPlayer)
		and not SlideTackle.IsRepeatBlocked(character, false)
		and not ClientDodge.IsDribbling()
	local mHiB = math.max(0.4, CFG.TackleSpeed)
	local mLoB = math.min(mHiB, CFG.TackleMinSpeed or 0.6)
	local plan = nil
	local memo = Mark.routeMemo
	local nowR = os.clock()
	local airB = humB ~= nil and not CharacterControllers.IsLanded(character, humB)
	if memo and nowR - memo.at < 0.06 and memo.ready == (readyB and true or false) and memo.air == airB then
		plan = memo.plan
		if plan and plan.tp then
			plan.tp = math.max(0, memo.tp0 - (nowR - memo.at))
		end
		if plan and memo.td0 then
			plan.td = math.max(0, memo.td0 - (nowR - memo.at))
		end
	else
	plan = Mark.routePlan({
		O = root.Position, v0 = flat(root.AssemblyLinearVelocity), spd = spd, samples = samples, ts = ts, rest = rest, foes = foes,
		half = receiveHalf, recvLo = recvLo, recvHi = recvHi, jumpH = jumpH, ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25),
		slideReady = readyB, mLo = mLoB, mHi = mHiB, urgent = threat ~= nil,
		g = Workspace.Gravity, vJ = math.sqrt(2 * Workspace.Gravity * jumpH), air = airB, vy = root.AssemblyLinearVelocity.Y,
		floorY = airB and (Mark.duelFloor or root.Position.Y) or root.Position.Y,
		airLo = HitboxSettings.AirReceive.CFrameOffset.Y - HitboxSettings.AirReceive.Size.Y * 0.5,
		airHi = HitboxSettings.AirReceive.CFrameOffset.Y + HitboxSettings.AirReceive.Size.Y * 0.5,
	})
		Mark.routeMemo = { at = nowR, plan = plan, tp0 = plan and plan.tp, td0 = plan and plan.td, ready = readyB and true or false, air = airB }
	end
	do
		local gf = nil
		for _, f in foes do
			if f.grappleT and (not gf or f.grappleT < gf.grappleT) then
				gf = f
			end
		end
		if gf then
			local win = plan ~= nil and (plan.t or math.huge) < gf.grappleT - 0.05
			Mark.grappleRace = { at = os.clock(), uid = gf.actor.UserId, win = win }
			if not Mark.grapRaceLog or os.clock() - Mark.grapRaceLog > 0.4 then
				Mark.grapRaceLog = os.clock()
				logFile("grapple race", actorName(gf.actor), "his arrival", gf.grappleT < math.huge and string.format("%.2f", gf.grappleT) or "-", "our contact", plan and string.format("%.2f", plan.t or 0) or "-", win and "BALL" or "-> duel him")
			end
		end
	end
	local wayP = nil
	local slideP, slideT, slidePress = nil, nil, nil
	if plan then
		steer, steerT, how = plan.p, plan.t, plan.kind
		wayP = plan.way
		Mark.ballInfo = { n = #samples, tUs = plan.tUs or plan.tp or 0, margin = plan.margin, mode = plan.kind, tp = plan.tp, rot = plan.rot, hits = plan.hits }
		if plan.kind == "slide" and plan.tp <= 0.03 then
			slidePress = plan
			slideP, slideT = plan.p, plan.tc
		end
	else
		Mark.ballInfo = nil
	end
	local aimP = steer
	if not aimP and threat then
		-- Defend Goal with no contact in time: still put the body as close to the shot path as the run allows (the least
		-- late sample within jump reach). It used to stop here ("no aim") = the defender stood and watched the goal.
		local bestS, bestT, bestL = nil, nil, math.huge
		for i = 2, #samples do
			local p = samples[i]
			if p.Y - root.Position.Y <= recvHi + jumpH then
				local late = math.max(flat(p - root.Position).Magnitude - receiveHalf, 0) / spd - ts[i]
				if late < bestL then
					bestS, bestT, bestL = p, ts[i], late
				end
			end
		end
		if bestS then
			aimP, steerT, how = bestS, bestT, "goal line"
			if not Mark.guardLateLog or os.clock() - Mark.guardLateLog > 0.8 then
				Mark.guardLateLog = os.clock()
				logFile("block goal", "best effort", "late", string.format("%.2f", bestL), "t", string.format("%.2f", bestT))
			end
		end
	end
	-- a plan that drops out for a frame (a bounce, a sample at the edge of the band) keeps its aim for 0.15 s: it used
	-- to stop and restart the chase ("ball stop no aim" then "ball start" 0.1 s later)
	if aimP then
		Mark.ballAimKeep = { p = aimP, t = steerT, how = how, way = wayP, at = os.clock() }
	elseif Mark.ballAimKeep and os.clock() - Mark.ballAimKeep.at < 0.15 and Mark.move.mode == "ball" then
		local k = Mark.ballAimKeep
		aimP, steerT, how, wayP = k.p, k.t and math.max(k.t - (os.clock() - k.at), 0), k.how, k.way
	end
	if not aimP then
		Mark.ballStop("no aim")
		Mark.ballIdle(root, "no aim (no contact the run / slide / jump can reach)")
		return
	end
	-- TOO FAR: no chase for a ball (and a contact point) farther than BallMaxDist - anywhere on the map, enemy goal included
	-- (log: starts at 73-86 studs, every one lost to the man standing next to it). A shot into OUR goal is the guard's, not
	-- this rule's. Already running = 10 studs of hysteresis, so the chase does not flicker on the edge.
	if not threat then
		local lim = (CFG.BallMaxDist or 60) + (Mark.move.mode == "ball" and 10 or 0)
		if dist > lim and flat(aimP - root.Position).Magnitude > lim then
			Mark.ballStop("far")
			Mark.ballIdle(root, "far")
			return
		end
	end
	local dir = unitOrNil(flat(aimP - root.Position))
	if plan and plan.kind == "slide" and not slidePress then
		dir = plan.heading or unitOrNil(flat(plan.W - root.Position)) or dir
	end
	local gap = flat(aimP - root.Position).Magnitude
	local beaten = false
	local homeDef = Mark.competitorFree(root, aimP)
	local ourNeed = math.max(0, gap - receiveHalf)
	for _, model in Mark.models() do
		local actor = Actors.GetFromCharacter(model)
		if CFG.BallCompetitor ~= false and not homeDef and actor and actor ~= LocalPlayer and sameTeam(actor) and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
			local ar = ActorTargeting.GetActorRoot(actor)
			if ar then
				-- CompetitorCheck (ball): yield only when a teammate is NOTICEABLY closer (e.g. 6 vs our 20 studs):
				-- clearly earlier in time and in distance, not a coin flip
				local d = math.max(0, flat(ar.Position - aimP).Magnitude - receiveHalf)
				local their = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false)
				local ourT = ourNeed / math.max(spd, 8)
				local theirT = their > 1 and d / their or math.huge
				if theirT < ourT * 0.6 and ourT - theirT > 0.25 and ourNeed - d > (CFG.BallYieldGap or 6) then
					beaten = true
					break
				end
			end
		end
	end
	-- Enemy keeper gets to our contact point first (run, or a GoalkeeperDive whose curve time beats us): the chase is
	-- pointless, he claims it.
	-- the enemy keeper claiming the ball first stopped the chase in their half (log: 22 "ball keeper") - a pressed keeper
	-- fumbles / spends his dive / gets volleyed; standing still gives nothing. Only with BallYieldKeeper on.
	local keeperFirst = false
	if not beaten and not threat and CFG.BallYieldKeeper then
		local diveMod = Mark.gkDiveMod or require(Modules.Actions.GoalkeeperDive)
		Mark.gkDiveMod = diveMod
		local ourT = ourNeed / math.max(spd, 8)
		for _, model in Mark.models() do
			local actor = Actors.GetFromCharacter(model)
			if actor and actor ~= LocalPlayer and not sameTeam(actor) and isGoalkeeper(actor) then
				local ar = ActorTargeting.GetActorRoot(actor)
				if ar then
					local d = math.max(0, flat(ar.Position - aimP).Magnitude - receiveHalf)
					local their = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(model), false)
					local theirT = their > 1 and d / their or math.huge
					local diveD = diveMod.GetDistance(actor)
					local reachD = flat(ar.Position - aimP).Magnitude - diveMod.Constants.SaveReachStuds
					if reachD <= diveD and aimP.Y - ar.Position.Y <= diveMod.Constants.MaximumSaveHeight then
						theirT = math.min(theirT, diveMod.GetCurveSecondsForTravel(math.max(reachD, 0), diveD))
					end
					if theirT + 0.1 < ourT then
						keeperFirst = true
						break
					end
				end
			end
		end
	end
	-- yield flapping: "ball start" / "ball stop teammate" alternated every frame (log 14911.9-14912.4) because the
	-- competitor test sits on a threshold. Once we yielded, stay yielded for 0.6 s.
	if beaten then
		Mark.ballYieldUntil = os.clock() + 0.6
	elseif Mark.ballYieldUntil and os.clock() < Mark.ballYieldUntil and not keeperFirst and not homeDef then
		beaten = true
	end
	do
		local hzEv, hzT = Mark.hazardGate(root, aimP, steerT, spd)
		if hzEv then
			Mark.ballStop("hazard")
			if not Mark.ballHazLog or os.clock() - Mark.ballHazLog > 0.6 then
				Mark.ballHazLog = os.clock()
				logFile("ball", "hazard", hzEv.item or hzEv.kind, "ta", string.format("%.2f", hzT or 0), "gap", string.format("%.1f", gap))
			end
			return
		end
	end
	if keeperFirst then
		Mark.ballIdle(root, "enemy keeper first")
		Mark.ballStop("keeper")
		if Mark.ballWhy ~= "keeper" then
			Mark.ballWhy = "keeper"
			logFile("ball", "keeper")
		end
		return
	end
	-- a box run that is winning keeps the body for a ball that is not ours within CFG.BoxYieldBall seconds (Mark.boxCommit)
	if not threat and Mark.boxCommit() and (plan and (plan.tUs or plan.tp or plan.t) or steerT or 0) > (CFG.BoxYieldBall or 1.0) then
		Mark.ballIdle(root, "box run (ball later than " .. tostring(CFG.BoxYieldBall or 1.0) .. " s)")
		Mark.ballStop("box")
		return
	end
	if beaten then
		Mark.ballIdle(root, "teammate closer")
		Mark.ballStop("teammate")
		if Mark.ballWhy ~= "teammate" then
			Mark.ballWhy = "teammate"
			logFile("ball", "teammate")
		end
		return
	end
	-- Defend Goal: "at the contact" (inside the Receive half) is not enough. The clear needs the path through our
	-- FrontAssist box (Mark.guardClear: <= 6 deg miss for an opponent's shot) and a body block wants it through the
	-- middle, not the edge of the box (the run stopped at Receive half = 2.75 studs off the line: a shot at the edge
	-- of the box). Keep stepping onto the path line until it passes within BlockGoalCenter of our root.
	local moveScale = 1
	if threat and gap <= receiveHalf + 1 then
		local O = flat(root.Position)
		local bq, bd = nil, math.huge
		for i = 2, #samples do
			if ts[i] >= 0.1 then
				local a, b = flat(samples[i - 1]), flat(samples[i])
				local ab = b - a
				local L2 = ab:Dot(ab)
				local k = L2 > 1e-6 and math.clamp((O - a):Dot(ab) / L2, 0, 1) or 0
				local q = a + ab * k
				local d = (q - O).Magnitude
				if d < bd then
					bq, bd = q, d
				end
			end
		end
		if bq and bd > (CFG.BlockGoalCenter or 0.8) then
			dir = unitOrNil(bq - O) or dir
			gap = receiveHalf + bd
			moveScale = math.max(Mark.arriveScale(bd, spd or 27.6), 0.35)
			if not Mark.centreLog or os.clock() - Mark.centreLog > 0.5 then
				Mark.centreLog = os.clock()
				logFile("block goal", "centre", "off", string.format("%.1f", bd), "t", string.format("%.2f", threat.t))
			end
		end
	end
	if dir and gap > receiveHalf then
		if not Mark.ballLogged then
			Mark.ballLogged = true
			logFile("ball start", how, "dist", string.format("%.2f", dist), "destT", string.format("%.2f", steerT or 0), "dest", string.format("%.1f", gap), "spd", string.format("%.1f", spd), "h", string.format("%.1f", aimP.Y - root.Position.Y), "state", tostring(live), "n", tostring(#samples), "rest", tostring(rest))
		end
		Mark.ballWhy = "chase"
		Mark.move.look = dir
		Mark.move.pts = (wayP and wayP ~= aimP) and { root.Position, wayP, aimP } or { root.Position, aimP }
		Mark.move.born = Mark.move.born or os.clock()
		Mark.moveSteer(dir * moveScale, "ball")
		Mark.agentHold(true, "ball")
		if not Mark.ballTraceAt or os.clock() - Mark.ballTraceAt > 0.5 then
			Mark.ballTraceAt = os.clock()
			local pi = Mark.ballInfo
			local humT = character:FindFirstChildOfClass("Humanoid")
			logFile("ball track", how, "gap", string.format("%.1f", gap), "t", string.format("%.2f", steerT or 0), "ourT", pi and string.format("%.2f", pi.tUs) or "-", "margin", pi and ((pi.margin == math.huge or pi.margin ~= pi.margin) and "inf" or string.format("%.2f", pi.margin)) or "-", "mode", pi and pi.mode or "-", "tp", pi and pi.tp and string.format("%.2f", pi.tp) or "-", "rot", pi and pi.rot and string.format("%.0f", pi.rot) or "-", "hits", pi and pi.hits and tostring(pi.hits) or "-", "v", string.format("%.1f", flat(root.AssemblyLinearVelocity).Magnitude), "ws", humT and string.format("%.1f", humT.WalkSpeed) or "-", "spd", string.format("%.1f", spd))
		end
	elseif Mark.move.mode == "ball" then
		Mark.moveSteer(Vector3.zero, "ball")
	end
	local noTouch = Mark.noTouchUntil and os.clock() < Mark.noTouchUntil
	local allyBlock = Mark.allyKickUntil and os.clock() < Mark.allyKickUntil
	if not allyBlock then
		for _, model in Mark.models() do
			local actor = Actors.GetFromCharacter(model)
			if actor and actor ~= LocalPlayer and sameTeam(actor) and not isGoalkeeper(actor) and not Mark.mateDown(actor, model) then
				local ar = ActorTargeting.GetActorRoot(actor)
				if ar and (flat(ar.Position - root.Position).Magnitude <= 8 or flat(ar.Position - pos).Magnitude <= 8) then
					allyBlock = true
					break
				end
			end
		end
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	local landed = hum and CharacterControllers.IsLanded(character, hum)
	local hstate = hum and hum:GetState()
	local airborne = hstate == Enum.HumanoidStateType.Jumping or hstate == Enum.HumanoidStateType.Freefall
	local liveH0 = pos.Y - root.Position.Y
	local nowBox = liveH0 >= slideLo and liveH0 <= slideHi
	-- Jump timing: a ball that will pass above the standing contact band (FrontAssist top) but under jump reach,
	-- close enough to be at us when the rise lifts the root to it. Volley press itself is tickVolley (game evaluation).
	-- the route's own jump (take-off at plan.td); Mark.planJump only when the route has no jump of its own (rest / goal line)
	local jumpAt, jumpMeet = nil, nil
	if landed and plan and plan.kind == "jump" then
		if plan.td and plan.td <= 0.035 then
			jumpAt, jumpMeet = plan.t, plan.p.Y - root.Position.Y
		end
	elseif landed then
		jumpAt, jumpMeet = Mark.planJump(root, samples, ts, spd)
		-- the route already has this ball earlier on the ground (a run / slide contact): no jump after it
		if jumpAt and plan and plan.t and plan.kind ~= "rest" and plan.t <= jumpAt + 0.05 then
			jumpAt = nil
		end
	end
	local slideDir = slidePress and slidePress.phi
	-- CandidateKiller first: an enemy racing us for this ball and a slide within KillerAngle of our route that hits him.
	-- While such a racer exists the "slide as a sprint" toward the ball is off (that was the slide the user saw: our
	-- route direction, the enemy beside it untouched).
	local kill, killWhy = nil, nil
	if CFG.CandidateKiller ~= false and CFG.AutoTackle and readyB and not slideDir and not noTouch
		and not (Mark.allyKickUntil and os.clock() < Mark.allyKickUntil) then
		kill, killWhy = Mark.killerSlide(root, dir, foes, pos, steerT, mLoB, mHiB, false)
		if not kill and killWhy and killWhy ~= "" and (not Mark.killLogAt or os.clock() - Mark.killLogAt > 1) then
			Mark.killLogAt = os.clock()
			logFile("killer skip", killWhy)
		end
	end
	if kill then
		local f = kill.foe
		local solved = solveIntercept(root, f.root, f.model, tackleTuning())
		predict = solved or predict
		local sent, why = tryTackle(character, root, kill.aim, kill.mult, { char = f.model, root = f.root })
		logFile(kill.guard and "killer guard" or "killer", sent and "sent" or ("no " .. tostring(why)), kill.name, "also", kill.also or "-", "ballD", string.format("%.1f", kill.dBall or -1), "ang", string.format("%.0f", kill.ang), "hits", tostring(kill.hits), "mult", string.format("%.2f", kill.mult), "dist", string.format("%.1f", kill.dist), "ballD", string.format("%.1f", kill.dBall), "hisFirst", string.format("%.2f", f.first or -1), "ourT", string.format("%.2f", steerT or -1), "drib", tostring(f.drib))
	elseif CFG.AutoTackle and slideDir and not allyBlock and not noTouch and (landed or (airborne and nowBox)) then
		logFile("ball tackle", "route", "tc", string.format("%.2f", slideT or 0), "h", string.format("%.1f", slideP.Y - root.Position.Y), "rot", string.format("%.0f", slidePress.rot or 0), "hits", tostring(slidePress.hits), "mult", string.format("%.2f", slidePress.mult), "by", slidePress.body and "body" or "box")
		Mark.slidePlanTc = slideT
		tryTackle(character, root, slideDir, slidePress.mult, nil, nil, slidePress.bend)
		Mark.slidePlanTc = nil
	elseif jumpAt then
		if Mark.doJump("ball") then
			logFile("ball jump", "t", string.format("%.2f", jumpAt), "h", string.format("%.1f", jumpMeet))
		end
	else
	end
end


Mark.armFlickWindow = function()
	if not CFG.AutoShoot then
		return
	end
	local character = LocalPlayer.Character
	local root = character and ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		return
	end
	if liveOwnerId() == LocalPlayer.UserId then
		Mark.flickAim = true
		solveShot(root, true)
		Mark.flickAim = false
	end
	if Shoot.aim then
		Mark.flickStrike = os.clock() + 3
		logFile("aerial", "arm", "flick", "dist", Shoot.dist and string.format("%.0f", Shoot.dist) or "-", "band", Shoot.band or "-")
	end
end

Mark.startAerial = function()
	if Mark.aerial then
		return
	end
	if not Mark.weOwn() then
		dbg("aerial", "no ball")
		return
	end
	local character = LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not (character and root) then
		return
	end
	Mark.flickAim = true
	Shoot.curve = nil
	solveShot(root, true)
	Mark.flickAim = false
	local now = CharacterMotionSmoothing.GetSmoothedServerTime()
	Mark.aerial = { phase = "pop", at = os.clock(), server = now, jumped = false }
	Mark.flickStrike = os.clock() + 3
	if not Shoot.aim then
		logFile("aerial", "flick", "no aim", "dist", Shoot.dist and string.format("%.0f", Shoot.dist) or "-", "pool", tostring(Shoot.poolN))
	end
	-- no jump here: jumping at the flick lands us before the ball is even touchable (detach 0.4 + apex 0.48)
	Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
	Mark.fx = Mark.fx or require(Client.Gameplay.Actions.TackleEffects)
	Mark.fx.PlayLocalRainbowFlick()
	ActionRemoteProtocol.Send(ActionCommands.RainbowFlick({ ShotTime = now }))
	Mark.flick.SetWindingUpUntil(LocalPlayer, now + Mark.flick.Constants.BallDetachSeconds + Mark.flick.Constants.DetachCommandGraceSeconds)
	logFile("aerial", "flick")
end

-- G test: owned ball, plain jump (as L) and an OWNER bicycle. Shoot.HandleInputBegan(input, false, extra) passes
-- extra.IsBicycleKick into startCharge (v241 = p234.IsBicycleKick or ...), ChargedKick sets u40 and the command gets
-- IsBicycleKick (ActionRemoteProtocol); Carry.GetLaunchPosition(..., isBicycle) moves the launch point. Press while
-- rising (BicycleKick.CanBicycleKick: unused jump + vy > 0), hold the full charge, release. Server acceptance of an
-- owner bicycle is NOT confirmed by the dump.
Mark.startBike = function()
	if Mark.bike or Mark.aerial then
		return
	end
	if not Mark.weOwn() then
		logFile("bike", "no ball")
		return
	end
	if not Mark.doJump("bike") then
		logFile("bike", "no jump")
		return
	end
	Mark.bike = { at = os.clock() }
	logFile("bike", "jump")
end

Mark.tickBike = function(character, root)
	local b = Mark.bike
	if not b then
		return
	end
	local now = os.clock()
	local hum = character:FindFirstChildOfClass("Humanoid")
	if b.input then
		local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
		if not charging then
			logFile("bike", "end", "charge gone")
			Mark.bike = nil
			Mark.forceBike = nil
			return
		end
		if now - b.pressAt >= (KickCore.Constants.MaximumChargeSeconds or 0.4) then
			ChargedKick.HandleInputEnded(b.input)
			logFile("bike", "release", "aim", Shoot.aim and fmtV(Shoot.aim.Direction) or "-", "band", Shoot.band or "-")
			Mark.bike = nil
			task.delay(0.3, function()
				Mark.forceBike = nil
			end)
		end
		return
	end
	if now - b.at > 0.6 or not Mark.weOwn() then
		logFile("bike", "end", Mark.weOwn() and "no rise" or "lost ball")
		Mark.bike = nil
		return
	end
	if not (hum and BicycleKick.CanBicycleKick(character, hum)) then
		return
	end
	Mark.forceBike = true
	solveShot(root, true)
	local input = Controls.CreateInput("Kick")
	local started = ChargedKick.HandleInputBegan(input, false, { IsBicycleKick = true }) and ChargedKick.IsCharging()
	local inst = Mark.chargeInst()
	local isBike = inst and inst.IsBicycleKickCharge and inst.IsBicycleKickCharge()
	logFile("bike", "press", started and "ok" or "no", "bike", tostring(isBike), "aim", Shoot.aim and fmtV(Shoot.aim.Direction) or "-", "band", Shoot.band or "-", "bands", Mark.bandStat(Mark.shotStat))
	if started then
		b.input = input
		b.pressAt = now
		Mark.shotLockUntil = now + (KickCore.Constants.MaximumChargeSeconds or 0.4) + 0.6
	else
		Mark.bike = nil
		Mark.forceBike = nil
	end
end

Mark.bandStat = function(stat)
	local out = {}
	for k, v in stat or {} do
		out[#out + 1] = string.format("%s%d/%d", k, v[2], v[1])
	end
	table.sort(out)
	if Mark.dipWhy then
		out[#out + 1] = "dip:" .. Mark.dipWhy
		Mark.dipWhy = nil
	end
	if Mark.trickWhy then
		out[#out + 1] = "trk:" .. Mark.trickWhy
		Mark.trickWhy = nil
	end
	if Mark.fakeWhy then
		out[#out + 1] = "fake:" .. Mark.fakeWhy
	end
	if Mark.barWhy then
		out[#out + 1] = "bar:" .. Mark.barWhy
		Mark.barWhy = nil
	end
	if Mark.cornerWhy then
		out[#out + 1] = "cor:" .. Mark.cornerWhy
		Mark.cornerWhy = nil
	end
	local f = Mark.shotFail
	if f then
		out[#out + 1] = string.format("f:v%d,c%d,b%d,fr%d,k%d,bar%d,foe%d", f.vel or 0, f.cross or 0, f.block or 0, f.frame or 0, f.keeper or 0, f.bar or 0, f.foe or 0)
	end
	return table.concat(out, ",")
end

Mark.tickAerial = function(character, root)
	local a = Mark.aerial
	if not (a and character and root) then
		return
	end
	local now = os.clock()
	local dt = now - a.at
	local hum = character:FindFirstChildOfClass("Humanoid")
	Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
	local detach = Mark.flick.Constants.BallDetachSeconds
	if a.phase == "pop" then
		if dt < detach then
			return
		end
		local launch = Mark.flick.GetCharacterLaunch(character)
		if not launch then
			logFile("aerial", "detach", "miss")
			Mark.aerial = nil
			return
		end
		ActionRemoteProtocol.Send(ActionCommands.RainbowFlick({
			Mode = ActionCommands.Modes.RainbowFlickDetach,
			AimDirection = launch.Direction,
			ShotTime = a.server + detach,
		}))
		a.phase = "air"
		a.detachAt = now
		a.noTouch = Mark.flick.GetLaunchNoTouchSeconds(character) or 0.48
		Mark.flickStrike = now + 2.2
		logFile("aerial", "detach", string.format("%.1f", launch.Velocity.Y), "noTouch", string.format("%.2f", a.noTouch))
		return
	end
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
	if a.input then
		if charging and (now - a.pressAt >= 0.05 or liveOwnerId() == LocalPlayer.UserId) then
			ChargedKick.HandleInputEnded(a.input)
			logFile("aerial", "release", "air", tostring(hum and not CharacterControllers.IsLanded(character, hum)))
			Mark.aerial = nil
			Mark.aerialContact = nil
		elseif not charging then
			a.input = nil
		end
		return
	end
	-- Right after detach the client still reports us as owner (IsLocalOwner lags the detach); only a real reception
	-- after the untouchable apex ends the move.
	local ownNow = liveOwnerId() == LocalPlayer.UserId and now - a.detachAt > (a.noTouch or 0.48) + 0.1
	local late = a.plan and now > a.plan.t0 + 0.4
	if now - a.detachAt > 3 or (ownNow and not a.plan) or late then
		logFile("aerial", "end", late and "late" or (ownNow and "own" or "timeout"))
		Mark.aerial = nil
		Mark.aerialContact = nil
		return
	end
	local _, _, samples, ts = Mark.ballPath(root)
	if not samples then
		return
	end
	local landed = not hum or CharacterControllers.IsLanded(character, hum)
	if not a.plan or now - a.planAt > 0.1 then
		local air = HitboxSettings.AirReceive
		local ballR = Physics.BallRadius or 1
		local airTop = air.CFrameOffset.Y + air.Size.Y * 0.5 + ballR
		local reachXZ = air.Size.X * 0.5 + ballR
		local jumpH = Mark.jumpH or 7.2
		Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
		local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false)
		local untouch = a.detachAt + a.noTouch - now
		local baseY = landed and root.Position.Y or (a.groundY or root.Position.Y)
		a.groundY = baseY
		local plan, chase, chaseX = nil, nil, math.huge
		local floored = false
		for i = 2, #samples - 1 do
			local t = ts[i]
			local p = samples[i]
			if p.Y <= baseY + 1.5 then
				floored = true -- after a floor bounce the rising ball is fair game too
			end
			local falling = samples[i + 1].Y < p.Y
			if t >= untouch and (falling or floored) then
				local h = p.Y - baseY
				local g = math.max(flat(p - root.Position).Magnitude - reachXZ, 0)
				if h <= airTop + jumpH then
					if g <= spd * math.max(t - 0.05, 0) then
						plan = { t = t, p = p, h = h, rise = Mark.riseT(math.clamp(h - airTop + 0.5, 0.3, jumpH)) }
						break
					end
					local x = g - spd * t
					if x < chaseX then
						chaseX, chase = x, p
					end
				end
			end
		end
		a.plan, a.planAt = plan and { t0 = now + plan.t, p = plan.p, h = plan.h, rise = plan.rise } or nil, now
		a.chase = (not plan) and chase or nil
		if a.chase and not a.chaseLog then
			a.chaseLog = true
			logFile("aerial", "chase", "short", string.format("%.1f", chaseX))
		end
		if plan and a.solved and Mark.aerialContact and (plan.p - Mark.aerialContact).Magnitude > 3 then
			a.solved = false -- contact moved: the old aim was solved from the wrong point
		end
		if plan and not a.solved then
			a.solved = true
			Mark.aerialContact = plan.p
			Mark.flickAim = true
			Shoot.curve = nil
			solveShot(root, true)
			Mark.flickAim = false
			if not Shoot.aim and Mark.volleyAimAt then
				local dirA = Mark.volleyAimAt(plan.p)
				if dirA then
					Shoot.aim = { Origin = plan.p, Direction = dirA, CameraCFrame = CFrame.lookAt(plan.p, plan.p + dirA), IsAirborne = true }
					Shoot.curve = nil
					Shoot.band = "fallback"
				end
			end
			if Shoot.aim then
				Mark.shotLockUntil = now + plan.t + 1.2
			end
			logFile("aerial", "plan", "t", string.format("%.2f", plan.t), "h", string.format("%.1f", plan.h), "rise", string.format("%.2f", plan.rise), "aim", Shoot.aim and fmtV(Shoot.aim.Direction) or "-", "band", Shoot.band or "-", "bands", Mark.bandStat(Mark.shotStat))
		end
	end
	local plan = a.plan
	if not plan then
		-- out of reach this tick: run at the closest sample so a later replan finds a contact
		if a.chase then
			local toC = flat(a.chase - root.Position)
			if toC.Magnitude > 1 then
				Mark.move.look = toC.Unit
				Mark.moveSteer(toC.Unit, "kick")
			end
		end
		return
	end
	local left = plan.t0 - now
	local to = flat(plan.p - root.Position)
	if to.Magnitude > 1 then
		Mark.move.look = to.Unit
		Mark.moveSteer(to.Unit, "kick")
	end
	-- The kick the game counts is the VOLLEY claim: Shoot.HandleInputBegan only claims when
	-- VolleyOpportunity.GetEvaluation is non-nil (ball arrival <= VolleyLockOn MaximumApproachSeconds 0.4, miss angle),
	-- and upgrades it to a bicycle kick only while BicycleKick.CanBicycleKick (unused jump AND rising). The bicycle
	-- then hovers us (StartHover) until arrival. So: jump inside the approach window, press while rising with an
	-- evaluation; a press without an evaluation is a plain kick and is never sent.
	-- The bicycle needs the volley evaluation (arrival <= MaximumApproachSeconds 0.4) WHILE we still rise (~0.27 s).
	-- Jump only when the whole rise lies inside that window: the game's own ApproachSeconds if it already evaluates,
	-- else our contact time. Once pressed, BicycleKick.StartHover holds us up until the ball arrives.
	Mark.volleyMod = Mark.volleyMod or require(Client.Gameplay.Actions.VolleyOpportunity)
	local ev = Mark.volleyMod.GetEvaluation(character)
	if landed and not a.jumped and CFG.FlickAutoJump ~= false then
		local gameLeft = ev and ev.ApproachSeconds
		if (gameLeft and gameLeft <= CFG.AerialJumpLead) or left <= CFG.AerialJumpLead then
			a.jumped = Mark.doJump("aerial")
			a.jumpAt = now
			logFile("aerial", "jump", tostring(a.jumped), "left", string.format("%.2f", left), "approach", gameLeft and string.format("%.2f", gameLeft) or "-")
		end
	end
	if charging or Mark.flick.IsWindingUp(LocalPlayer) or left > 0.5 then
		return
	end
	local rising = hum and BicycleKick.IsRisingInJump(character, hum)
	local bike = hum and BicycleKick.CanBicycleKick(character, hum)
	-- plain volley only as the last chance (rise already spent, ball about to arrive)
	local ready = ev ~= nil and (bike or (a.jumped and not rising and left < 0.12))
	if not ready then
		if not a.waitLog or now - a.waitLog > 0.15 then
			a.waitLog = now
			logFile("aerial", "wait", "ev", tostring(ev ~= nil), "approach", ev and string.format("%.2f", ev.ApproachSeconds or -1) or "-", "miss", ev and string.format("%.1f", ev.MissAngleDegrees or -1) or "-", "rising", tostring(rising), "bike", tostring(bike), "left", string.format("%.2f", left))
		end
		return
	end
	if CFG.FlickAutoKick == false then
		return -- the player kicks; the aim stays locked on the solved shot
	end
	local input = Controls.CreateInput("Kick")
	local started = ChargedKick.HandleInputBegan(input, false) and ChargedKick.IsCharging()
	if started then
		a.input = input
		a.pressAt = now
		Mark.shotLockUntil = now + 1.2
	end
	logFile("aerial", "press", started and "ok" or "no", "bike", tostring(bike), "approach", string.format("%.2f", ev.ApproachSeconds or -1), "miss", string.format("%.1f", ev.MissAngleDegrees or -1), "left", string.format("%.2f", left), "aim", Shoot.aim and fmtV(Shoot.aim.Direction) or "-")
end

Mark.agentHold = function(on, why)
	Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
	Mark.sprintMod = Mark.sprintMod or require(Modules.Actions.Sprint)
	local ch = LocalPlayer.Character
	if on then
		if not Mark.agentSprinting and ch then
			-- remember the character's own IsSprinting attribute; only GoalkeeperActions ever writes it in the game, the
			-- client Sprint loop never sets it back, so forcing false on release left it false (slow, no sprint)
			Mark.sprintAttrPrev = ch:GetAttribute(Mark.sprintMod.Constants.IsSprintingAttribute)
		end
		Mark.agentSprinting = true
		-- the agent sprints without limit (stamina source "MoveAgent") EXCEPT for Mark.flagGuard seconds after the server put
		-- us back (the anti-cheat sees a sprint on an empty server bar): then it jogs on the real bar
		local calm = os.clock() < (Mark.sprintFlagUntil or 0)
		Mark.sprint.SetUnlimitedStamina("MoveAgent", not calm)
		Mark.sprintMod.SetUnlimitedStamina(LocalPlayer, "MoveAgent", not calm)
		Mark.sprintMod.SetCharacterIsSprinting(LocalPlayer, not calm)
		if not calm and why ~= "block" and why ~= "dribble" and why ~= "dodge" and ch and Mark.sprintMod.SetDodgeBoost then
			local now = Workspace:GetServerTimeNow()
			local want = now + 0.4
			local boostUntil = Mark.sprintMod.GetDodgeBoostUntil and Mark.sprintMod.GetDodgeBoostUntil(ch)
			if type(boostUntil) ~= "number" or boostUntil < want then
				Mark.sprintMod.SetDodgeBoost(ch, want, 1.08)
			end
		end
	else
		Mark.sprint.SetUnlimitedStamina("MoveAgent", false)
		Mark.sprintMod.SetUnlimitedStamina(LocalPlayer, "MoveAgent", false)
		if Mark.agentSprinting then
			Mark.agentSprinting = false
			-- restore what the attribute was before the agent, or the live client sprint state
			local want = Mark.sprintAttrPrev
			if want == nil then
				want = Mark.sprint.IsSprinting and Mark.sprint.IsSprinting() or false
			end
			Mark.sprintMod.SetCharacterIsSprinting(LocalPlayer, want == true or (Mark.sprint.IsSprinting and Mark.sprint.IsSprinting()))
		end
		if Mark.sprint.RestoreStamina and os.clock() >= (Mark.sprintFlagUntil or 0) then
			Mark.sprint.RestoreStamina(1)
		end
	end
end

-- HIT TRAIN. Items we do not model (a gun that fires every 1.5 s, a repeating slam) hit us again and again and the log showed 8
-- knock-backs in 12 s from one man while the script did nothing. Every STRONG knock-back (>= 40: slides are 24-26) is noted per
-- attacker; the second one inside 8 s starts an evade: 3 s of running away from him (a lateral weave, alternating each 0.6 s) and,
-- with the ball, a pass / dump (Mark.hazPass). Pure counter: times = the attacker's earlier hits.
Mark.hitCount = function(times, now, window)
	local n = 0
	for i = #times, 1, -1 do
		if now - times[i] > window then
			table.remove(times, i)
		else
			n += 1
		end
	end
	return n
end
Mark.hitLog = {}
Mark.hitNote = function(attacker, vel)
	if not CFG.AutoDodge or type(attacker) ~= "number" or attacker == LocalPlayer.UserId or vel < 40 then
		return
	end
	local now = os.clock()
	local h = Mark.hitLog[attacker]
	if not h then
		h = {}
		Mark.hitLog[attacker] = h
	end
	h[#h + 1] = now
	local n = Mark.hitCount(h, now, CFG.EvadeWindow or 8)
	if n >= (CFG.EvadeHits or 2) then
		Mark.evade = { uid = attacker, untilT = now + (CFG.EvadeTime or 3), since = now, ev = { born = now, r = 45, item = "hits" } }
		logFile("evade", "hit train", n, "by", tostring(attacker), "vel", string.format("%.0f", vel), "for", CFG.EvadeTime or 3, "s")
	end
end
Mark.evadeTick = function(character, root)
	local e = Mark.evade
	if not e then
		return
	end
	local now = os.clock()
	if now >= e.untilT then
		Mark.evade = nil
		return
	end
	local a = playerOf(e.uid)
	local ar = a and ActorTargeting.GetActorRoot(a)
	if not ar then
		Mark.evade = nil
		return
	end
	local P, O = flat(ar.Position), flat(root.Position)
	if (O - P).Magnitude > 80 then
		Mark.evade = nil
		return
	end
	local away = unitOrNil(O - P) or Vector3.new(0, 0, 1)
	local side = Vector3.new(-away.Z, 0, away.X) * (math.floor((now - e.since) / 0.6) % 2 == 0 and 1 or -1)
	e.ev.p = P
	if liveOwnerId() == LocalPlayer.UserId then
		Mark.hazPass(root, e.ev, 0.8, 0, away, "evade")
	end
	if Mark.move.mode ~= "dodge" and Mark.move.mode ~= "dribble" and not Mark.slideBody() then
		local dir = unitOrNil(away + side * 0.7) or away
		Mark.fleeUntil = now + 0.3
		Mark.move.look = away
		Mark.moveSteer(dir, "flee")
		Mark.agentHold(true, "flee")
	end
end

-- the pause after the server put us back (user: 4 s): see the MovementCorrection hook in the Movement section
Mark.flagGuard = 4

-- Oil Spill (ItemIds.OilSpill). Server streams patches as {Id, Position, TeamName, ExpiresAt} (OilSpill.PatchFields)
-- on Items/OilPatches (gen, patches) and Items/Effect (Kind OilPatchesCheckpoint/Snapshot/Remove/Clear). HazardZoneKind
-- "Oil": the stun zone is resolved server-side, its radius is NOT in the client dump -> taken from the Puddle VFX
-- template extents (fallback 3.5). Patches of our own team are assumed harmless (puddle tinted by TeamName).
Mark.oil = {}
Mark.oilRadius = function()
	if Mark.oilR then
		return Mark.oilR
	end
	-- the stun zone is server-side (HazardZoneKind "Oil"); best client proxy is the Puddle VFX footprint: the largest
	-- flat BasePart / Attachment-emitter extent under the template. Logged so the radius can be checked in game.
	local r, how = CFG.OilRadius or 4, "cfg"
	Mark.try(function()
		local t = game:GetService("ReplicatedStorage").VFX.Items["Oil Spill"].Puddle
		local best = 0
		local info = {}
		for _, d in t:GetDescendants() do
			if d:IsA("BasePart") then
				best = math.max(best, math.max(d.Size.X, d.Size.Z) * 0.5)
				info[#info + 1] = d.ClassName .. string.format("%.1fx%.1f", d.Size.X, d.Size.Z)
			elseif d:IsA("ParticleEmitter") then
				local sz = d.Size.Keypoints
				local m = 0
				for _, kp in sz do
					m = math.max(m, kp.Value)
				end
				info[#info + 1] = "PE" .. string.format("%.1f", m)
			end
		end
		logFile("oil template", t.ClassName, table.concat(info, ","))
		if best > 1 then
			r, how = math.clamp(best, 2, 9), "part"
		end
	end)
	Mark.oilR = r
	logFile("oil radius", string.format("%.2f", r), how)
	return r
end
Mark.oilAdd = function(list)
	if type(list) ~= "table" then
		return
	end
	local ours = ActorTeams.GetActorTeamName(LocalPlayer)
	for _, p in list do
		if type(p) == "table" then
			local id, pos, team, exp = p[1], p[2], p[3], p[4]
			if id ~= nil and typeof(pos) == "Vector3" and type(exp) == "number" then
				if team == nil or team ~= ours then
					Mark.oil[id] = { pos = pos, exp = exp }
				end
			end
		end
	end
end
Mark.oilRemove = function(list)
	if type(list) ~= "table" then
		return
	end
	for _, p in list do
		local id = type(p) == "table" and p[1] or p
		if id ~= nil then
			Mark.oil[id] = nil
		end
	end
end
Mark.try(function()
	Remotes.Get("Items", "OilPatches").OnClientEvent:Connect(function(_, patches)
		Mark.oilAdd(patches)
	end)
end)
-- live patches near a point, expired ones dropped (server clock)
Mark.oilNear = function(pos, range)
	local now = Workspace:GetServerTimeNow()
	local out = nil
	for id, p in Mark.oil do
		if p.exp <= now then
			Mark.oil[id] = nil
		elseif flat(p.pos - pos).Magnitude <= range then
			out = out or {}
			out[#out + 1] = p.pos
		end
	end
	return out
end
-- Covered stretch of our flat path: patches merge into one run when their discs overlap along the ray. Returns the
-- first run {enter, exit} within `ahead` studs, or nil.
Mark.oilAhead = function(pos, dir, ahead)
	local R = Mark.oilRadius() + 0.3 -- a fat margin merged separate puddles into one "too long to jump" run
	local list = Mark.oilNear(pos, ahead + R + 30)
	if not list then
		return nil
	end
	local spans = {}
	for _, c in list do
		local rel = flat(c - pos)
		local along = rel:Dot(dir)
		local lat = (rel - dir * along).Magnitude
		if lat < R then
			local h = math.sqrt(R * R - lat * lat)
			if along + h > 0 then
				spans[#spans + 1] = { math.max(0, along - h), along + h }
			end
		end
	end
	if #spans == 0 then
		return nil
	end
	table.sort(spans, function(x, y)
		return x[1] < y[1]
	end)
	local enter, exit = spans[1][1], spans[1][2]
	if enter > ahead then
		return nil
	end
	for i = 2, #spans do
		if spans[i][1] <= exit + 0.5 then
			exit = math.max(exit, spans[i][2])
		else
			break
		end
	end
	return { enter = enter, exit = exit }
end
-- Jump flight: Movement.Jump with the humanoid jump height, workspace gravity. Airtime = 2*sqrt(2h/g).
Mark.jumpAir = function()
	local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
	local h = (hum and hum.UseJumpPower == false and hum.JumpHeight) or (hum and (hum.JumpPower ^ 2) / (2 * Workspace.Gravity)) or 7.2
	if h < 1 then
		h = Mark.jumpH or 7.2
	end
	return 2 * math.sqrt(2 * h / Workspace.Gravity)
end
-- Movement filter used by moveSteer. Free to jump (ball not ours): hop the whole covered run only when the jump
-- covers it with margin, taking off so the run sits in the middle of the flight; a run longer than the jump is walked
-- around. Own ball (no jump) / dribble: bend around it, or stop when every side is covered.
-- Enemy landmines (PlaceDownPlacement.Configs.landmines): placed models live in workspace.Misc.Items with
-- PlacedItemId == "landmines" (the same container as barricades). Nothing in the client says which team owns one - the
-- stripes are tinted from the LOCAL player's team - so a mine is skipped only when one of its attributes names our team /
-- one of our team's userIds (attributes are logged once per mine to find the key). Trigger radius is server-side:
-- half the model's footprint + CFG.MineMargin (2.5).
Mark.mineCache = nil
Mark.mines = function()
	local now = os.clock()
	local c = Mark.mineCache
	if c and now - c.at < 0.25 then
		return c.list
	end
	local list = {}
	local world = workspace:FindFirstChild("Misc")
	world = world and world:FindFirstChild("Items")
	if world then
		local ours = ActorTeams.GetActorTeamName(LocalPlayer)
		Mark.mineSeen = Mark.mineSeen or setmetatable({}, { __mode = "k" })
		for _, inst in world:GetChildren() do
			if inst:GetAttribute("PlacedItemId") == "landmines" then
				local friendly = false
				local attrs = inst:GetAttributes()
				-- owner: the PlacedModelEntrance packet (PlacerUserId by EntranceId). Mines placed before the script ran have
				-- no record: they stay hostile (a detour is cheaper than the stun)
				local entrance = inst:GetAttribute("PlacementEntranceId")
				local placer = entrance ~= nil and Mark.mineOwner and Mark.mineOwner[entrance]
				if type(placer) == "number" then
					local pl = placer == LocalPlayer.UserId and LocalPlayer or playerOf(placer)
					friendly = pl ~= nil and (pl == LocalPlayer or sameTeam(pl))
				end
				if not Mark.mineSeen[inst] then
					Mark.mineSeen[inst] = true
					local ks = {}
					for k, v in attrs do
						ks[#ks + 1] = tostring(k) .. "=" .. tostring(v)
					end
					logFile("mine seen", fmtV(inst:GetPivot().Position), "friendly", tostring(friendly), "owner", tostring(placer), table.concat(ks, ","))
				end
				if not friendly then
					local size = inst:GetExtentsSize()
					local r = math.max(size.X, size.Z) * 0.5
					list[#list + 1] = { pos = inst:GetPivot().Position, r = r + (CFG.MineMargin or 2.5), model = inst }
				end
			end
		end
	end
	Mark.mineCache = { at = now, list = list }
	return list
end

-- distance along dir (within `ahead`) where the straight path first comes within a mine's radius, or nil
Mark.mineAhead = function(pos, dir, ahead)
	local list = Mark.mines()
	if #list == 0 then
		return nil
	end
	local best = nil
	for _, m in list do
		local rel = flat(m.pos - pos)
		local along = rel:Dot(dir)
		if along > -m.r and along < ahead + m.r then
			local lat = (rel - dir * along).Magnitude
			if lat < m.r then
				local enter = math.max(along - math.sqrt(m.r * m.r - lat * lat), 0)
				if enter <= ahead and (not best or enter < best) then
					best = enter
				end
			end
		end
	end
	return best
end

Mark.mineDir = function(root, dir)
	local fd = unitOrNil(flat(dir))
	if not fd or #Mark.mines() == 0 then
		return dir
	end
	local hum = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
	if hum and not CharacterControllers.IsLanded(root.Parent, hum) then
		return dir
	end
	local speed = math.max(flat(root.AssemblyLinearVelocity).Magnitude, 16)
	local look = speed * 0.7 + 2
	if not Mark.mineAhead(root.Position, fd, look) then
		return dir
	end
	for _, a in { 25, -25, 50, -50, 80, -80, 110, -110 } do
		local r = math.rad(a)
		local cand = Vector3.new(fd.X * math.cos(r) - fd.Z * math.sin(r), 0, fd.X * math.sin(r) + fd.Z * math.cos(r))
		if not Mark.mineAhead(root.Position, cand, look) then
			if not Mark.mineLog or os.clock() - Mark.mineLog > 0.6 then
				Mark.mineLog = os.clock()
				logFile("mine avoid", a)
			end
			return cand * dir.Magnitude
		end
	end
	return dir
end

Mark.oilDir = function(root, dir, mode)
	if not next(Mark.oil) then
		return dir
	end
	local fd = unitOrNil(flat(dir))
	if not fd then
		return dir
	end
	-- one timed hop, then just run: no second jump, no swerve while airborne or right after the hop (user: it
	-- jumped 2-3 times and did nonsense)
	local hum = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
	if hum and not CharacterControllers.IsLanded(root.Parent, hum) then
		return dir
	end
	if os.clock() - (Mark.oilJumpAt or 0) < 0.9 then
		return dir
	end
	local speed = math.max(flat(root.AssemblyLinearVelocity).Magnitude, 16)
	local look = speed * 0.7
	local run = Mark.oilAhead(root.Position, fd, look)
	if not run then
		return dir
	end
	local own = liveOwnerId() == LocalPlayer.UserId
	if not own and mode ~= "dribble" then
		local air = Mark.jumpAir()
		local reach = speed * air * 0.85 - 1.0 -- landing margin
		local len = run.exit - run.enter
		if len <= reach then
			-- take off so the run is centred in the flight; ping delay eats ~speed*ping of run-up
			local takeoff = (reach - len) * 0.5
			local lead = speed * (LocalPlayer:GetNetworkPing() * 0.5 + 0.03)
			if run.enter <= takeoff + lead then
				if run.enter >= 0.2 and Mark.doJump("oil") then
					Mark.oilJumpAt = os.clock()
					logFile("oil hop", "enter", string.format("%.1f", run.enter), "len", string.format("%.1f", len), "reach", string.format("%.1f", reach))
				end
				if run.enter >= 0.2 then
					return dir
				end
			else
				return dir -- keep running, the hop point is still ahead
			end
		end
	end
	for _, a in { 30, -30, 55, -55, 80, -80, 110, -110 } do
		local r = math.rad(a)
		local cand = Vector3.new(fd.X * math.cos(r) - fd.Z * math.sin(r), 0, fd.X * math.sin(r) + fd.Z * math.cos(r))
		if not Mark.oilAhead(root.Position, cand, look) then
			if not Mark.oilLog or os.clock() - Mark.oilLog > 0.5 then
				Mark.oilLog = os.clock()
				logFile("oil avoid", mode or "-", a, "run", string.format("%.1f-%.1f", run.enter, run.exit))
			end
			return cand * dir.Magnitude
		end
	end
	return Vector3.zero
end

-- Debug rings: every live enemy patch within 60 studs, radius = the model radius, so the zone can be checked in game.
Mark.drawOil = function(root)
	Mark.oilLines = Mark.oilLines or makeLines(160, 1.2, 22)
	Mark.oilPool = Mark.oilPool or Mark.segPool(Mark.oilLines)
	local pool = Mark.oilPool
	if CFG.Draw and CFG.DrawHazards ~= false and next(Mark.oil) and Workspace.CurrentCamera then
		local list = Mark.oilNear(root.Position, 60)
		if list then
			local R = Mark.oilRadius()
			local col = Color3.fromRGB(190, 120, 255)
			for n = 1, math.min(#list, 20) do
				local c = list[n]
				local prev = nil
				for k = 0, 8 do
					local a = k / 8 * math.pi * 2
					local p = Vector3.new(c.X + math.cos(a) * R, c.Y + 0.1, c.Z + math.sin(a) * R)
					if prev then
						pool.seg(prev, p, col, 0.8, 1.2, 22)
					end
					prev = p
				end
			end
		end
	end
	pool.finish()
end

-- User's own steering intent, independent of the agent's move override: PlayerModule controls (keyboard / pad /
-- touch) in camera space -> flat world; WASD fallback.
Mark.userInputDir = function()
	local cam = Workspace.CurrentCamera
	if not cam then
		return nil
	end
	-- PlayerModule controls: looked up once (a custom / missing PlayerModule is expected on some executors), then
	-- read directly every call (the old per-call xpcall + closure ran every frame)
	if Mark.ctrls == nil then
		local pm = LocalPlayer.PlayerScripts:FindFirstChild("PlayerModule")
		local ok, c = false, nil
		if pm then
			ok, c = Mark.try(function()
				return require(pm):GetControls()
			end)
		end
		Mark.ctrls = (ok and c) or false
	end
	local mv = Mark.ctrls and Mark.ctrls:GetMoveVector() or nil
	if not (mv and mv.Magnitude > 0.1) then
		local UIS = game:GetService("UserInputService")
		local x, z = 0, 0
		if UIS:IsKeyDown(Enum.KeyCode.W) then z -= 1 end
		if UIS:IsKeyDown(Enum.KeyCode.S) then z += 1 end
		if UIS:IsKeyDown(Enum.KeyCode.A) then x -= 1 end
		if UIS:IsKeyDown(Enum.KeyCode.D) then x += 1 end
		mv = Vector3.new(x, 0, z)
	end
	if mv.Magnitude < 0.1 then
		return nil
	end
	local f = unitOrNil(flat(cam.CFrame.LookVector))
	local r = unitOrNil(flat(cam.CFrame.RightVector))
	if not (f and r) then
		return nil
	end
	return unitOrNil(r * mv.X - f * mv.Z)
end

-- Instant sidestep used by the hazard dodges (same displacement path as the slide dodge: root CFrame + guard).
-- One place for every sidestep. DodgeTeleport: the old instant step (CFrame + displacement guard). Off: no CFrame write,
-- the agent walks that way for the time the step would have taken (moveSteer "dodge", stopped by moveTick).
Mark.stepAway = function(root, step, why, stream)
	if CFG.DodgeTeleport ~= false then
		root.CFrame = root.CFrame + step
		LocalMovementGuard.RegisterDisplacement(root, step)
		if stream then
			CharacterMotion.SetStreamVelocity(root.Parent, root.AssemblyLinearVelocity)
		end
		return true
	end
	local dir = unitOrNil(flat(step))
	if not dir then
		return false
	end
	Mark.walkOff = { untilT = os.clock() + math.clamp(step.Magnitude / 20, 0.2, 0.6) }
	Mark.moveSteer(dir, "dodge")
	logFile("step walk", why or "-", fmtV(step))
	return false
end

Mark.hazardStep = function(root, step, why)
	Mark.stepAway(root, step, why, true)
	logFile("hazard step", why, fmtV(step))
end

-- Kick charge dodge (no ball, or ball with the dribble unavailable). Exit the HitboxSettings.Kick box through the
-- nearest face whose direction does not go back against the user's own movement (or facing when idle). Exit within
-- 5 studs -> instant step; otherwise leave it.
-- The way out of the enemy kick box. opts = { { d = studs to the face, v = direction }, ... }; u = our own heading. A STEP (<= 5.2 st,
-- Dodge's teleport) through the nearest face not against our heading; else a RUN (<= 14 st) through the nearest face that is not
-- straight back. Returns "step" | "run", { d, v } or nil.
Mark.kickExit = function(opts, u)
	local step, run = nil, nil
	for _, o in opts do
		local v = unitOrNil(flat(o.v))
		if v and o.d > 0.2 then
			if o.d <= 5.2 and (not u or v:Dot(u) >= -0.4) and (not step or o.d < step.d) then
				step = { d = o.d, v = v }
			end
			if o.d <= 14 and (not u or v:Dot(u) >= -0.8) and (not run or o.d < run.d) then
				run = { d = o.d, v = v }
			end
		end
	end
	if step then
		return "step", step
	end
	if run then
		return "run", run
	end
	return nil, nil
end

Mark.tickKickDodge = function(root, own)
	if not CFG.AutoDodge or os.clock() - (Mark.kickDodgeAt or 0) < 0.9 then
		return
	end
	local kt = Mark.kickThreat(root)
	if not (kt and kt.inside and kt.open and kt.aimed) then
		return
	end
	if own then
		if ClientDodge.IsDribbling() then
			return
		end
		-- With the ball the dribble owns the kick. A step (teleport) only when the dribble is still on cooldown at the EARLIEST
		-- release (min charge): if it frees up before that, wait and dribble (the dribble branch fires as soon as it is ready).
		local left = Mark.dribbleLeft()
		local pingK = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local rMinK = math.max(kt.minRel - kt.elapsed, 0)
		if left <= 0 or left + pingK * 0.5 + 0.03 <= rMinK then
			if left > 0 and (not Mark.kickWaitLog or os.clock() - Mark.kickWaitLog > 0.5) then
				Mark.kickWaitLog = os.clock()
				logFile("hazard kick", "wait dribble", "cdLeft", string.format("%.2f", left), "release in", string.format("%.2f", rMinK))
			end
			return
		end
		logFile("hazard kick", "dribble cd at release", Mark.dribbleBlock or "cd", "cdLeft", string.format("%.2f", left), "release in", string.format("%.2f", rMinK))
	end
	local k = HitboxSettings.Kick
	local cf = kt.aimed.CFrame * k.CFrameOffset
	-- geometry from the point that was tested (root + velocity * lead): taking the exit distances from the current
	-- root gave negative distances ("no-forward-exit -4.6,4.8") and a step the wrong way
	local lp = cf:PointToObjectSpace(Vector3.new(kt.us.X, root.Position.Y, kt.us.Z))
	local hx, hz = k.Size.X * 0.5, k.Size.Z * 0.5
	local u = Mark.userInputDir() or unitOrNil(flat(root.AssemblyLinearVelocity)) or unitOrNil(flat(root.CFrame.LookVector))
	local opts = {
		{ d = hx - lp.X + 0.8, v = cf.RightVector },
		{ d = hx + lp.X + 0.8, v = -cf.RightVector },
		{ d = hz - lp.Z + 0.8, v = -cf.LookVector }, -- back face (+Z, toward him)
		{ d = hz + lp.Z + 0.8, v = cf.LookVector }, -- front face (-Z, along the kick)
	}
	local kind, best = Mark.kickExit(opts, u)
	if kind == "step" then
		Mark.kickDodgeAt = os.clock()
		Mark.hazardStep(root, best.v * best.d, "kick " .. actorName(kt.actor))
		return
	end
	-- no exit a step away (it used to be a log line and nothing else - the user stood in the box and got hit): the ball goes
	-- to a mate, and the body RUNS out through the nearest face
	local away = best and best.v or unitOrNil(flat(root.Position - kt.aimed.CFrame.Position))
	if own and away then
		local ev = Mark.kickPassEv
		if not ev or os.clock() - ev.born > 1.5 then
			ev = { born = os.clock(), p = kt.aimed.CFrame.Position, r = 14, item = "kick" }
			Mark.kickPassEv = ev
		end
		Mark.hazPass(root, ev, math.max(math.max(kt.minRel - kt.elapsed, 0), 0.25), 0, away, "kick")
	end
	if best and Mark.move.mode ~= "dodge" and Mark.move.mode ~= "dribble" then
		Mark.fleeUntil = os.clock() + 0.3
		Mark.move.look = best.v
		Mark.moveSteer(best.v, "flee")
		Mark.agentHold(true, "flee")
	end
	if not Mark.kickDodgeLog or os.clock() - Mark.kickDodgeLog > 0.5 then
		Mark.kickDodgeLog = os.clock()
		logFile("hazard kick", best and "run out" or "no exit", string.format("%.1f,%.1f", lp.X, lp.Z), best and string.format("%.1f st", best.d) or "", own and "ball" or "")
	end
end

-- Sledgehammer (dump: Items.Sledgehammer). Effect "HeldItemActivate" (ItemId sledgehammer) carries StartedAt and
-- LandingSeconds: the slam lands at StartedAt + LandingSeconds after a LungeDistance 12 leap, striking at
-- GetStrikePoint = landing + 6.1 forward, 0.7 side (SlamOffset). It is a ground slam: airborne = safe. The slam radius
-- is server-side and NOT in the client dump -> CFG.HammerRadius (estimate) and every slam is logged with our
-- distance to calibrate. Response: no ball -> jump so we are in the air at the slam. Own ball (cannot jump) -> flick
-- (detach 0.4 s) then jump; too late for that -> step out of the zone.
Mark.hammers = {}
Mark.onItemActivate = function(pkt)
	local uid = pkt.UserId
	if type(uid) ~= "number" or uid == LocalPlayer.UserId then
		return
	end
	local actor = playerOf(uid)
	if actor and sameTeam(actor) then
		return
	end
	local ch = actor and Actors.GetCharacter(actor)
	local r = ch and ch:FindFirstChild("HumanoidRootPart")
	logFile("skill activate", tostring(pkt.ItemId), actorName(actor), r and string.format("d %.1f", (r.Position - (ActorTargeting.GetActorRoot(LocalPlayer) or r).Position).Magnitude) or "-", "land", tostring(pkt.LandingSeconds))
	if pkt.ItemId == "magnet" then
		Mark.magnets = Mark.magnets or {}
		Mark.magnets[uid] = { endsAt = (tonumber(pkt.StartedAt) or Workspace:GetServerTimeNow()) + 5 } -- Magnet.DurationSeconds
	end
	if pkt.ItemId == "jetpack" then
		Mark.jets = Mark.jets or {}
		Mark.jets[uid] = { at = os.clock() }
	elseif pkt.ItemId == "shotgun" or pkt.ItemId == "bazooka" or pkt.ItemId == "grapplingHook" or pkt.ItemId == "rocketPunch" then
		-- self-launchers (recoil up / rocket at the feet / pull): AutoGK holds the press until the flight is measured
		Mark.launchRec = Mark.launchRec or {}
		Mark.launchRec[uid] = { at = os.clock(), kind = pkt.ItemId }
	end
	if pkt.ItemId == "sledgehammer" and r and type(pkt.StartedAt) == "number" then
		local look = unitOrNil(flat(r.CFrame.LookVector)) or Vector3.new(0, 0, 1)
		local land = r.Position + look * 12
		local right = Vector3.new(-look.Z, 0, look.X)
		Mark.hammers[uid] = {
			slamAt = pkt.StartedAt + (tonumber(pkt.LandingSeconds) or 0.7),
			strike = land + look * 6.1 - right * 0.7,
			name = actorName(actor),
		}
		-- the slam is a zone like a blast: flee / pass / stick clamp / overlay all read Mark.hazEv (the hammer's own jump
		-- and flick stay in tickHazard, so no blast step for it)
		local h = Mark.hammers[uid]
		Mark.hazEv["hammer" .. uid] = { kind = "blast", t = h.slamAt, p = h.strike, r = CFG.HammerRadius or 9, item = "sledgehammer", noStep = true, id = "hammer" .. uid, srcName = h.name, seen = Workspace:GetServerTimeNow() }
	end
end

Mark.plainFlick = function()
	local now = CharacterMotionSmoothing.GetSmoothedServerTime()
	Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
	Mark.fx = Mark.fx or require(Client.Gameplay.Actions.TackleEffects)
	Mark.fx.PlayLocalRainbowFlick()
	ActionRemoteProtocol.Send(ActionCommands.RainbowFlick({ ShotTime = now }))
	Mark.flick.SetWindingUpUntil(LocalPlayer, now + Mark.flick.Constants.BallDetachSeconds + Mark.flick.Constants.DetachCommandGraceSeconds)
	Mark.hazardFlickAt = os.clock()
end

-- Diagnostic for "charge stays full": a charge older than MaximumChargeSeconds + 1.5 s gets one log line with
-- everything that can hold a release (volley lock / delayed release, our own kick session, dodge / facing locks).
Mark.chargeWatch = function()
	local charging = ChargedKick.IsCharging and ChargedKick.IsCharging()
	if not charging then
		Mark.chargeSeenAt = nil
		Mark.chargeWarned = nil
		return
	end
	Mark.chargeSeenAt = Mark.chargeSeenAt or os.clock()
	local held = os.clock() - Mark.chargeSeenAt
	-- Recovery: the player already let go of Kick (real input up for > 0.25 s) but the game still shows a charge and
	-- nothing of ours owns it. Re-sending HandleInputEnded does NOT release it: Shoot.HandleInputEnded only calls
	-- releaseCharge when the ended input IS the charge input (ChargedKick.IsChargeInput, identity compare), and a
	-- fresh call carries a different object, so the game returns without releasing (log: "release resent" then the
	-- charge still stuck, then "cancelled"). ReleaseFullCharge is the game's own releaseCharge handed to the charge
	-- action - it fires the shot outright, no input-identity check. One shot at it; if the charge survives (a volley
	-- delay re-armed it) cancel so it can never sit at full.
	-- The game releases a charge itself: ChargedKick.StartCharge arms task.delay(maxSeconds, ReleaseFullCharge), and a
	-- release can be delayed legitimately (DelayReleaseUntilMinimum, a volley claim waiting for arrival). The v41 fix
	-- cancelled 0.25 s after the real input went up, i.e. it killed those legitimate delayed releases (the "my shot
	-- is dropped") and every keeper FORCED CLEAR (after a catch the game holds a charge it owns and ignores input:
	-- Gameplay_Script returns on goalkeeperRole.IsForcedClearActive). Now only a charge that outlived its own
	-- auto-release by 0.9 s with the real input long up, never a forced clear, never a goalkeeper's.
	local forced = (ChargedKick.IsForcedClearCharging and ChargedKick.IsForcedClearCharging()) or MatchSettings.IsGoalkeeperCharacter(LocalPlayer.Character)
	local rk = Mark.realKick
	local maxC = KickCore.Constants.MaximumChargeSeconds or 0.4
	local dodgeT = Mark.dodgeAt or Mark.dodgeEndedAt
	local afterDodge = dodgeT and os.clock() - dodgeT < 2.5
	local function stillCharging()
		return ChargedKick.IsCharging and ChargedKick.IsCharging()
	end
	local function fireRelease()
		-- the SAME input object StartCharge stored (IsChargeInput is an identity compare). A fresh Controls.CreateInput
		-- does not release. This is releaseCharge, so the shot goes out; CancelCharge only deletes it.
		if rk and rk.input and ChargedKick.HandleInputEnded then
			ChargedKick.HandleInputEnded(rk.input)
		end
	end
	-- After a script dodge the game's own task.delay(max, ReleaseFullCharge) does not finish the charge: releaseCharge
	-- sees the ball the dodge knocked loose, marks a volley and DelayReleases until an arrival that never comes. The
	-- charge sits at full. The old fix then CancelCharge'd it (log: dodge, kick 0.06 s later, charge fix cancelled
	-- held 1.3) so the shot never existed.
	if not forced and afterDodge and stillCharging() and held > maxC + 0.2 and rk and rk.input and (not Mark.chargeFixAt or os.clock() - Mark.chargeFixAt > 0.45) then
		Mark.chargeFixAt = os.clock()
		fireRelease()
		if stillCharging() then
			Mark.volleyMod = Mark.volleyMod or require(Client.Gameplay.Actions.VolleyOpportunity)
			if Mark.volleyMod.ClearPredictedLock then
				Mark.volleyMod.ClearPredictedLock()
			end
			local inst = Mark.chargeInst and Mark.chargeInst()
			if inst and inst.SetVolleyArrivalTime then
				inst.SetVolleyArrivalTime(inst, 0)
			end
			fireRelease()
		end
		if stillCharging() and ChargedKick.CancelCharge then
			ChargedKick.CancelCharge()
			logFile("charge fix", "cancelled", string.format("held %.1f", held), "after dodge")
		else
			logFile("charge fix", "released", string.format("held %.1f", held), "after dodge")
		end
	elseif not forced and rk and rk.down == false and not Mark.volleyInput and Mark.realChargeAt and Mark.realChargeAt >= (Mark.scriptChargeAt or 0) and rk.upAt >= Mark.realChargeAt and os.clock() - rk.upAt > 0.6 and held > maxC + 0.9 and (not Mark.chargeFixAt or os.clock() - Mark.chargeFixAt > 0.5) then
		Mark.chargeFixAt = os.clock()
		fireRelease()
		if stillCharging() and ChargedKick.CancelCharge then
			ChargedKick.CancelCharge()
			logFile("charge fix", "cancelled", string.format("held %.1f", held))
		else
			logFile("charge fix", "released", string.format("held %.1f", held))
		end
	end
	if held > KickCore.Constants.MaximumChargeSeconds + 1.5 and not Mark.chargeWarned then
		Mark.chargeWarned = true
		Mark.volleyMod = Mark.volleyMod or require(Client.Gameplay.Actions.VolleyOpportunity)
		local locked = Mark.volleyMod.IsLockedBy(LocalPlayer)
		logFile("charge stuck", string.format("%.1f", held), "forced", tostring(forced), "volleyLock", tostring(locked), "ourVolley", tostring(Mark.volleyAt ~= nil), "ourKick", tostring(Mark.kickCmd ~= nil), "move", tostring(Mark.move and Mark.move.mode), "dodgeLock", tostring(Mark.dodgeLockOn), "rotLock", tostring(TurnControl.GetActiveAutoRotateLockName and TurnControl.GetActiveAutoRotateLockName()))
	end
end

-- Sprint "forbidden for good". Sprint.SetBlocked(source) keeps a per-source flag table (module-local u121); while any
-- source is true the sprint state never starts a sprint (canStartSprinting / isSprintBlocked). The game clears its own
-- sources in stopDribble ("Dribble"), the slide-tackle cleanup / OnVelocityReleased ("SlideTackle"), the jetpack end
-- ("Jetpack"). The agent starts and cancels dribbles / tackles from outside, so a source can outlive its action. Read
-- the table through the upvalue chain (log what is stuck) and clear only sources whose action is provably dead.
Mark.sprintWatch = function()
	local now = os.clock()
	if now - (Mark.sprintWatchAt or 0) < 0.5 then
		return
	end
	Mark.sprintWatchAt = now
	Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
	local slideLive = ClientSlide.IsSlideTackling()
	local dribLive = ClientDodge.IsDribbling()
	local chargeLive = ChargedKick.IsCharging and ChargedKick.IsCharging()
	if slideLive or dribLive then
		Mark.sprintBusyAt = now
	end
	if now - (Mark.sprintBusyAt or 0) < 0.8 then
		return
	end
	-- diagnostic: which sources are actually set (executor debug API; silent if it is not there)
	if debug.getupvalues and not Mark.sprintWatchLogged then
		Mark.try(function()
			local function find(fn, want)
				for _, v in debug.getupvalues(fn) do
					if want(v) then
						return v
					end
				end
			end
			local function allBool(v)
				if type(v) ~= "table" then
					return false
				end
				for _, x in v do
					if type(x) ~= "boolean" then
						return false
					end
				end
				return true
			end
			local state = find(Mark.sprint.SetBlocked, function(v)
				return type(v) == "table" and type(v.SetBlocked) == "function"
			end)
			-- the source flags (u121) are the table of booleans among SetBlocked's upvalues; the module table the first
			-- version matched holds functions
			local blocks = state and find(state.SetBlocked, allBool)
			if blocks then
				local out = {}
				for k, v in blocks do
					if v then
						out[#out + 1] = tostring(k)
					end
				end
				if #out > 0 then
					Mark.sprintWatchLogged = true
					logFile("sprint stuck", table.concat(out, ","), "slide", tostring(slideLive), "dribble", tostring(dribLive), "charge", tostring(chargeLive))
				end
			end
		end)
	end
	-- idempotent: SetBlocked(src,false) on an unset source is a table write of nil
	Mark.sprint.SetBlocked("SlideTackle", false)
	Mark.sprint.SetBlocked("Dribble", false)
	if Mark.sprint.SetRefillBlocked then
		Mark.sprint.SetRefillBlocked("SlideTackle", false)
		Mark.sprint.SetRefillBlocked("Dribble", false)
		if not chargeLive then
			Mark.sprint.SetRefillBlocked("KickCharge", false)
		end
	end
end

-- Player-state probe. The "can't jump / can't run / charge sits at full" reports share one suspect: a block state
-- that outlived its action. Everything that gates those is listed here in one line (logged when the set changes, and
-- on H): Movement jump-state blocks (module-local table, HeldJump = jump disabled until the key is released), humanoid
-- WalkSpeed / JumpHeight / Jumping state, ActionLocks, Sprint block sources, ragdoll/stun/frozen, auto-rotate lock,
-- our own move mode, jump hold, volley/kick flags.
Mark.stateLine = function()
	local out = {}
	local function add(k, v)
		out[#out + 1] = k .. "=" .. tostring(v)
	end
	local function try(fn)
		fn()
	end
	local ch = LocalPlayer.Character
	local hum = ch and ch:FindFirstChildOfClass("Humanoid")
	try(function()
		local ch1 = ChargedKick.IsCharging and ChargedKick.IsCharging()
		add("charge", ch1 and string.format("%.1f", os.clock() - (Mark.chargeSeenAt or os.clock())) or 0)
		add("forced", (ChargedKick.IsForcedClearCharging and ChargedKick.IsForcedClearCharging()) or false)
		add("gk", MatchSettings.IsGoalkeeperCharacter(ch))
		add("drib", ClientDodge.IsDribbling())
		add("slide", ClientSlide.IsSlideTackling())
	end)
	try(function()
		if hum then
			add("ws", string.format("%.1f", hum.WalkSpeed))
			add("jh", string.format("%.1f", hum.JumpHeight))
			add("hs", hum:GetState().Name)
			add("jumpOn", hum:GetStateEnabled(Enum.HumanoidStateType.Jumping))
			add("landed", CharacterControllers.IsLanded(ch, hum))
		end
	end)
	try(function()
		local t = Mark.jumpBlocks and Mark.jumpBlocks()
		if t then
			local keys = {}
			for k, v in t do
				if v then
					keys[#keys + 1] = tostring(k)
				end
			end
			table.sort(keys)
			add("jblock", #keys > 0 and table.concat(keys, "+") or "-")
		end
	end)
	try(function()
		local keys = {}
		for _, name in ActionLocks.LockNames do
			if ActionLocks.IsLocked(LocalPlayer, name) then
				keys[#keys + 1] = name
			end
		end
		add("locks", #keys > 0 and table.concat(keys, "+") or "-")
		add("kickBlk", ActionLocks.HasKickBlock(LocalPlayer))
		Mark.flick = Mark.flick or require(Modules.Actions.RainbowFlick)
		add("flickWind", Mark.flick.IsWindingUp(LocalPlayer))
		add("pressStun", require(Modules.Characters.Stun).IsActorStunnedForPress(LocalPlayer, nil, ch))
		add("tackleBlk", ActionLocks.HasTackleBlock(LocalPlayer))
		add("dodgeBlk", ActionLocks.HasDodgeBlock(LocalPlayer))
	end)
	try(function()
		Mark.sprint = Mark.sprint or require(Client.Gameplay.Player.Sprint)
		Mark.sprintMod = Mark.sprintMod or require(Modules.Actions.Sprint)
		local keys = Mark.sprintBlockKeys and Mark.sprintBlockKeys() or {}
		add("sprintBlk", #keys > 0 and table.concat(keys, "+") or "-")
		add("sprinting", Mark.sprintMod.GetCharacterIsSprinting(LocalPlayer))
		add("unlimited", Mark.sprintMod.HasUnlimitedStamina(LocalPlayer))
	end)
	try(function()
		local down, left = Mark.mateDown(LocalPlayer, ch)
		add("down", down and string.format("%.1f", left) or false)
		add("rot", TurnControl.GetActiveAutoRotateLockName and TurnControl.GetActiveAutoRotateLockName() or "-")
	end)
	try(function()
		add("move", Mark.move and Mark.move.mode or "-")
		add("agentSpr", Mark.agentSprinting == true)
		add("volleyIn", Mark.volleyInput ~= nil)
		add("jumpHold", Mark.jumpHoldUntil ~= nil)
		add("slideAim", slideAim ~= nil)
	end)
	try(function()
		local attrs = {}
		for k, v in ch:GetAttributes() do
			if type(v) == "boolean" or type(v) == "number" then
				attrs[#attrs + 1] = k .. ":" .. (type(v) == "number" and string.format("%.1f", v) or tostring(v))
			end
			if #attrs >= 10 then
				break
			end
		end
		table.sort(attrs)
		add("attrs", table.concat(attrs, ","))
	end)
	return table.concat(out, " ")
end

Mark.jumpBlocks = function()
	if Mark.jumpBlockTbl then
		return Mark.jumpBlockTbl
	end
	if not debug.getupvalues then
		return nil
	end
	Mark.walk = Mark.walk or require(Client.Gameplay.Player.Movement)
	local function allBool(v)
		if type(v) ~= "table" then
			return false
		end
		for _, x in v do
			if type(x) ~= "boolean" then
				return false
			end
		end
		return true
	end
	local function search(fn, depth)
		local ups = debug.getupvalues(fn)
		for _, v in ups do
			if allBool(v) and v ~= Mark then
				return v
			end
		end
		if depth > 0 then
			for _, v in ups do
				if type(v) == "function" then
					local t = search(v, depth - 1)
					if t then
						return t
					end
				end
			end
		end
	end
	local okS, t = Mark.try(search, Mark.walk.SetJumpStateBlocked, 2)
	if okS and t then
		Mark.jumpBlockTbl = t
	end
	return Mark.jumpBlockTbl
end

Mark.sprintBlockKeys = function()
	if not debug.getupvalues then
		return {}
	end
	local out = {}
	local function find(fn, want)
		for _, v in debug.getupvalues(fn) do
			if want(v) then
				return v
			end
		end
	end
	local function allBool(v)
		if type(v) ~= "table" then
			return false
		end
		for _, x in v do
			if type(x) ~= "boolean" then
				return false
			end
		end
		return true
	end
	local state = find(Mark.sprint.SetBlocked, function(v)
		return type(v) == "table" and type(v.SetBlocked) == "function"
	end)
	local blocks = state and find(state.SetBlocked, allBool)
	if blocks then
		for k, v in blocks do
			if v then
				out[#out + 1] = tostring(k)
			end
		end
	end
	table.sort(out)
	return out
end

Mark.stateWatch = function(character)
	local now = os.clock()
	-- the jump command we hold for an agent jump is released here (it used to live only in the field-player half of
	-- stepLogic: a jump as keeper never let go of Movement's HeldJump block)
	if Mark.jumpHoldUntil and now > Mark.jumpHoldUntil then
		Mark.jumpHoldUntil = nil
		CharacterControllers.SetJumpCommand(character, false)
		Mark.endJump()
	end
	if now - (Mark.stateAt or 0) < 0.25 then
		return
	end
	Mark.stateAt = now
	local line = Mark.stateLine()
	-- signature without volatile fields
	local sig = line:gsub("charge=[%d%.]+", "charge=N"):gsub("move=%S+", ""):gsub("landed=%S+", ""):gsub("hs=%S+", ""):gsub("ws=%S+", ""):gsub("unlimited=%S+", ""):gsub("agentSpr=%S+", ""):gsub("sprinting=%S+", ""):gsub("slideAim=%S+", ""):gsub("jh=%S+", function(s)
		return s == "jh=0.0" and s or "jh=N"
	end):gsub("down=%S+", function(s)
		return s:match("false") and s or "down=T"
	end)
	local blk = Mark.jumpBlocks and Mark.jumpBlocks()
	local held = blk and blk.HeldJump
	if held then
		Mark.heldSince = Mark.heldSince or now
	else
		Mark.heldSince = nil
	end
	-- HeldJump stays until the jump key is released; with the key up and no agent jump pending it is stale
	if held and now - Mark.heldSince > 1.2 and not UserInputService:IsKeyDown(Enum.KeyCode.Space) and not Mark.jumpHoldUntil then
		Mark.heldSince = now
		Mark.walk = Mark.walk or require(Client.Gameplay.Player.Movement)
		if Mark.walk.ReleaseJump then
			Mark.walk.ReleaseJump()
		end
		logFile("jump unblock", "HeldJump stale, released")
	end
	if sig ~= Mark.stateSig and now - (Mark.stateLogAt or 0) > 0.4 then
		Mark.stateSig = sig
		Mark.stateLogAt = now
		logFile("state", line)
	end
end

-- ===== Blast / projectile hazards (AutoDodge) =====
-- Explosive items (bazooka, grenade) stun everyone inside ItemHitSettings.ExplosionRadius (14; ScreenShakeEffects uses it as
-- the full-amplitude radius, the server's stun rule is not in the client dump - CFG.BlastRadius / BlastMargin tune it).
-- The blast is an EVENT: where and when. Grenade: the game's own flight model (Grenade.NewFlight / GetDetonationTime /
-- GetStateAtTime with the movement world: bounces, TimeScale 0.7, countdown after the first ground contact), the
-- ProjectileMovement row's DetonatesAt overrides the time. Bazooka: ballistic path (workspace gravity) to the ground or the
-- first body on the way. Freeze gun: not a blast but a contact path (sampled), used by the chase gate.
-- Consumers: Mark.hazFlee (run out of the radius / pass the ball when we cannot), Mark.hazardGate (AutoBall never walks
-- into a zone before it fires), GetMoveCommand clamp (the player's own stick cannot carry us into it), tryTackle.
Mark.blastR = function()
	if CFG.BlastRadius then
		return CFG.BlastRadius
	end
	Mark.itemHit = Mark.itemHit or require(Modules.Items.ItemHitSettings)
	local m = Mark.itemHit.ExplosionRadius
	return m
end

-- The keeper does not run from grenades (user): his place is the goal, the stun / knock does not decide a save the way a
-- missed save does. Other zones (bazooka, hammer) still count. Dynamic: the role can change while the grenade flies.
Mark.hazSkip = function(ev)
	return ev.item == "grenade" and Mark.meKeeper()
end

-- Distance covered in t seconds along a heading by a body that runs up to spd from a start speed v0 (along that heading,
-- negative = coming the other way): the speed ramps linearly over `ramp` (BallRamp, the same body model as routePlan), then holds.
-- The old flee gain was spd * t - the full speed from the first frame - and "could run out" was true by ~3 studs too often.
Mark.runGain = function(spd, v0, t, ramp)
	if t <= 0 then
		return 0
	end
	v0 = math.clamp(v0, -spd, spd)
	if t <= ramp then
		return v0 * t + (spd - v0) * t * t / (2 * ramp)
	end
	return v0 * ramp + (spd - v0) * ramp * 0.5 + spd * (t - ramp)
end

Mark.hazAdd = function(st)
	local item = st.item
	if item ~= "grenade" and item ~= "bazooka" and item ~= "freezeGun" then
		return
	end
	local who = st.src and playerOf(st.src)
	if st.src == LocalPlayer.UserId or (who and sameTeam(who)) then
		return
	end
	st.hazAt, st.hazDet = os.clock(), st.det
	local nowS = Workspace:GetServerTimeNow()
	local old = Mark.hazEv[st.id]
	local ev = nil
	if item == "grenade" then
		-- GrenadeEffects.refreshFlight: Flight = NewFlight(row Position, Velocity, UpdatedAt), DetonatesAt from the row or
		-- GetDetonationTime (bounces with the movement world, TimeScale 0.7, the fuse starts at the first contact).
		-- The world is the game's own source for it: ChargePathPreview.GetBallBoundaryWorld(projectile BallId). It used to be
		-- Renderer.GetMovementState(), which is nil whenever the ball is not in free flight (carried, held by a keeper):
		-- every grenade thrown at a carrier made no zone at all, and no later row retried it ("sees grenades every other time").
		Mark.grenMod = Mark.grenMod or require(Modules.Items.Grenade)
		Mark.pathPreview = Mark.pathPreview or require(Client.Gameplay.Actions.ChargePathPreview)
		local world = Mark.pathPreview.GetBallBoundaryWorld(st.ballId)
		if not world then
			if not Mark.grenNoWorld or os.clock() - Mark.grenNoWorld > 1 then
				Mark.grenNoWorld = os.clock()
				logFile("blast skip", "grenade", "no boundary world", "ball", tostring(st.ballId))
			end
			return
		end
		local flight = Mark.grenMod.NewFlight(st.fp, st.fv, st.ft)
		local tDet = type(st.det) == "number" and st.det or Mark.grenMod.GetDetonationTime(flight, world, nil)
		local s = Mark.grenMod.GetStateAtTime(flight, tDet, world)
		if typeof(s.Position) ~= "Vector3" then
			return
		end
		ev = old or {}
		ev.kind, ev.t, ev.p = "blast", tDet, s.Position
		-- the hop path from now to the blast, for the overlay (12 samples, rebuilt with each correction)
		local path = ev.path or {}
		local n = 12
		for i = 0, n do
			local ts = nowS + (tDet - nowS) * i / n
			local si = Mark.grenMod.GetStateAtTime(flight, math.max(ts, st.ft), world)
			path[i + 1] = si.Position
		end
		ev.path = path
	elseif item == "bazooka" or item == "freezeGun" then
		-- The freeze gun is a bazooka with the ice shot's gravity (user): it is dangerous where it LANDS (ground, a wall, the first body),
		-- not along its flight - the flight was a corridor "contact path" and the dodge ran from a shot that came down 20 studs behind us.
		local g = st.grav or (item == "freezeGun" and 58.9 or 196.2)
		local dt0 = math.max(nowS - st.ft, 0)
		local p = st.fp + st.fv * dt0 + Vector3.new(0, -0.5 * g * dt0 * dt0, 0)
		local v = st.fv + Vector3.new(0, -g * dt0, 0)
		Mark.fieldMod = Mark.fieldMod or require(Modules.Gameplay.FieldSettings)
		-- The rocket also stops on WORLD GEOMETRY (platforms, walls, goal frames: a ground rectangle from FieldSettings
		-- knows none of them: "it explodes in the sky" was a platform edge, "it flies over" was a ground height from the
		-- wrong rectangle). One ray per 0.12 s segment of the arc, characters / ball / camera excluded (the first body is
		-- judged below with its own radius).
		local rp = RaycastParams.new()
		rp.FilterType = Enum.RaycastFilterType.Exclude
		local ex = { Workspace.CurrentCamera }
		for _, model in Mark.models() do
			ex[#ex + 1] = model
		end
		rp.FilterDescendantsInstances = ex
		rp.RespectCanCollide = true
		local t, tSeg, qSeg = 0, 0, p
		while t < 5 and not ev do
			local q = p + v * t + Vector3.new(0, -0.5 * g * t * t, 0)
			local gy = Mark.fieldMod.GetGroundYAt(q)
			local wall = nil
			if t - tSeg >= 0.12 then
				wall = Workspace:Raycast(qSeg, q - qSeg, rp)
				if not wall then
					qSeg, tSeg = q, t
				end
			end
			if wall then
				ev = old or {}
				ev.kind, ev.t, ev.p = "blast", nowS + tSeg + (t - tSeg) * math.clamp((wall.Position - qSeg).Magnitude / math.max((q - qSeg).Magnitude, 1e-3), 0, 1), wall.Position
				ev.world = wall.Instance.Name
			elseif type(gy) == "number" and q.Y <= gy + 0.8 then
				ev = old or {}
				ev.kind, ev.t, ev.p = "blast", nowS + t, q
			else
				-- the first body on the way (any but the shooter) sets it off
				for _, model in Mark.models() do
					local a = Actors.GetFromCharacter(model)
					local r = a and a.UserId ~= st.src and ActorTargeting.GetActorRoot(a)
					if r and flat(q - r.Position).Magnitude < 3.8 and math.abs(q.Y - r.Position.Y) < 4.5 then
						ev = old or {}
						ev.kind, ev.t, ev.p = "blast", nowS + t, q
						break
					end
				end
			end
			t += 0.03
		end
	end
	if ev then
		ev.id, ev.item, ev.srcName = st.id, item, who and actorName(who) or "?"
		ev.r = ev.r or (item == "freezeGun" and (CFG.FreezeRadius or 8) or Mark.blastR())
		ev.seen = ev.seen or nowS
		Mark.hazEv[st.id] = ev
		if ev.kind == "blast" and not old then
			logFile("blast event", item, ev.world and ("hits world:" .. ev.world) or "ground/body", "from", ev.srcName, "in", string.format("%.2f", ev.t - nowS), "at", fmtV(ev.p), "r", string.format("%.1f", ev.r))
		end
	end
end

-- first event our position hits. posAt(tAhead) -> Vector3 (flat is taken). blasts: inside radius + margin at the blast (one-way
-- ping earlier: the server judges our pose then) or 0.2 s after it; paths: inside the contact radius at that sample's time.
Mark.hazardHits = function(posAt, tMax)
	local list = Mark.hazEv
	if not list or next(list) == nil then
		return nil
	end
	local nowS = Workspace:GetServerTimeNow()
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local margin = CFG.BlastMargin or 1.5
	for id, ev in list do
		if Mark.hazSkip(ev) then
			continue
		end
		if ev.kind == "blast" then
			local ta = ev.t - nowS
			if ta < -0.6 then
				list[id] = nil
			elseif ta <= tMax then
				for k = 0, 2 do
					local tt = ta + (k == 0 and -0.05 or (k == 1 and 0 or 0.2))
					if tt >= -0.05 then
						local pp = posAt(math.max(tt - ping * 0.5, 0))
						if flat(pp - ev.p).Magnitude < ev.r + margin then
							return ev, ta
						end
					end
				end
			end
		else
			local last = ev.samples[#ev.samples]
			if last.t < nowS - 0.3 then
				list[id] = nil
			else
				for _, s in ev.samples do
					local ta = s.t - nowS
					if ta >= 0 and ta <= tMax then
						if (posAt(math.max(ta - ping * 0.5, 0)) - s.p).Magnitude < ev.r then
							return ev, ta
						end
					end
				end
			end
		end
	end
	return nil
end

-- AutoBall: do not run into a zone / projectile corridor before it is over (the ball is not worth the stun)
Mark.hazardGate = function(root, aimP, steerT, spd)
	if next(Mark.hazEv) == nil then
		return nil
	end
	local O = root.Position
	local to = flat(aimP - O)
	local D = to.Magnitude
	local u = unitOrNil(to)
	if not u then
		return nil
	end
	local y = O.Y
	return Mark.hazardHits(function(t)
		local d = math.min(spd * t, D)
		return Vector3.new(O.X + u.X * d, y, O.Z + u.Z * d)
	end, 4)
end

-- Run out of a blast; with the ball and no clean way out, give it to a teammate first (a stun takes it otherwise).
-- The pass is charged as long as the time allows, not to the full solve: the release packet must reach the server before
-- the blast (ta - ping/2 - HazPassMargin). A lob needs PassMinCharge; under that the ball is dumped away from the zone.
-- The ball leaves us before a zone that is about to hurt: a Pass Assist lob to the mate whose landing is farthest from the zone
-- (ev = { p, r, item }), or, with no time even for the shortest lob, a dump away from it. One try per 0.1 s, once per event.
Mark.hazPass = function(root, ev, ta, slack, away, tag)
	if ev.passed or (Mark.pa and Mark.pa.live) or os.clock() < (ev.passTry or 0) then
		return false
	end
	ev.passTry = os.clock() + 0.1
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local budget = ta - ping * 0.5 - (CFG.HazPassMargin or 0.1)
	local minC = CFG.PassMinCharge or 0.1
	local pick, pickSol, pickFar = nil, nil, -1
	if budget >= minC and CFG.PassAssistSync ~= false and Mark.paList then
		for _, sel in Mark.paAuto(root) do
			local sol = Mark.paSolve(sel)
			if sol and not sol.contested then
				local far = flat(sol.land - ev.p).Magnitude
				if far > ev.r and far > pickFar then
					pick, pickSol, pickFar = sel, sol, far
				end
			end
		end
	end
	if pick then
		local c = math.min(pickSol.charge or 0.3, budget)
		if Mark.paPress(pick, pickSol, tag, c) then
			ev.passed = true
			logFile(tag .. " pass", ev.item, "to", pick.name, "ta", string.format("%.2f", ta), "charge", string.format("%.2f", c), "of", string.format("%.2f", pickSol.charge or 0.3), "slack", string.format("%.1f", slack))
			return true
		end
	elseif budget < minC and ta > ping * 0.5 then
		-- no time even for the shortest lob: the ball leaves us away from the zone instead of dying with us
		ev.passed = true
		Mark.dumpBall(root, away)
		logFile(tag .. " dump", ev.item, "ta", string.format("%.2f", ta), "slack", string.format("%.1f", slack))
		return true
	end
	return false
end

Mark.hazFlee = function(character, root)
	local list = Mark.hazEv
	local nowS = Workspace:GetServerTimeNow()
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local O = flat(root.Position)
	local ourV = flat(root.AssemblyLinearVelocity)
	local margin = CFG.BlastMargin or 1.5
	local worst = nil
	for id, ev in list do
		if ev.kind == "blast" then
			local ta = ev.t - nowS
			if ta < -0.6 then
				list[id] = nil
			elseif ta > -0.15 and ta < 3.5 and not ev.boomAt and not Mark.hazSkip(ev) then
				local d = flat(O + ourV * math.max(ta - ping * 0.5, 0) - ev.p).Magnitude
				if d < ev.r + margin and (not worst or ta < worst.ta) then
					worst = { ev = ev, ta = ta, d = d }
				end
			end
		end
	end
	if not worst then
		if Mark.move.mode == "flee" and os.clock() >= (Mark.fleeUntil or 0) then
			Mark.moveStop("flee")
		end
		return
	end
	local ev, ta = worst.ev, worst.ta
	local P = flat(ev.p)
	local d0 = (O - P).Magnitude
	local away = unitOrNil(O - P) or unitOrNil(flat(root.CFrame.LookVector)) or Vector3.new(0, 0, 1)
	local hum = character:FindFirstChildOfClass("Humanoid")
	Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
	local spd = Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(character), false) or 24
	if hum and hum.WalkSpeed > spd then
		spd = hum.WalkSpeed
	end
	local gain = Mark.runGain(spd, ourV:Dot(away), ta - ping * 0.5 - 0.05, math.max(CFG.BallRamp or 0.2, 0.05))
	local need = ev.r + margin
	local slack = d0 + gain - need
	local byRun = slack >= 0
	local byStep = slack + 5 >= 0 and not ev.noStep
	local own = liveOwnerId() == LocalPlayer.UserId
	if not ev.logged then
		ev.logged = true
		logFile("blast flee", ev.item, "ta", string.format("%.2f", ta), "d", string.format("%.1f", d0), "need", string.format("%.1f", need), "gain", string.format("%.1f", gain), "run", tostring(byRun), "step", tostring(byStep), "own", tostring(own))
	end
	-- no way out on foot (run and step both short): the shield takes the blast
	if not byRun and not byStep and not ev.shieldTried and ta > ping * 0.5 then
		ev.shieldTried = true
		if Mark.shieldNow(string.format("%s blast in %.2f slack %.1f", ev.item, ta, slack), ta) then
			ev.passed = true
			return
		end
	end
	-- with the ball: out by a thin margin or not at all -> the ball goes to a mate now
	if own and slack < (CFG.HazPassSlack or 2) then
		Mark.hazPass(root, ev, ta, slack, away, "blast")
	end
	if Mark.move.mode == "dodge" or Mark.move.mode == "dribble" then
		return
	end
	if byRun or own or not byStep then
		Mark.move.look = away
		Mark.moveSteer(away, "flee")
		Mark.agentHold(true, "flee")
	end
	-- not enough by running alone: the 5-stud step (it knocks the ball loose, so never with the ball)
	if not byRun and byStep and not own and not ev.stepped and ta > 0.12 then
		ev.stepped = true
		Mark.moveSteer(away, "flee")
		Mark.hazardStep(root, away * 5, "blast")
		logFile("blast step", ev.item, "ta", string.format("%.2f", ta))
	end
end

-- the player's own stick cannot carry us into a zone that is about to go off
Mark.blastClamp = function(ch, cmd)
	if not CFG.AutoDodge then
		return cmd
	end
	local list = Mark.hazEv
	if not list or next(list) == nil or typeof(cmd) ~= "Vector3" or cmd.Magnitude < 0.2 then
		return cmd
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	if not root then
		return cmd
	end
	local nowS = Workspace:GetServerTimeNow()
	local O = flat(root.Position)
	local c = flat(cmd)
	if c.Magnitude < 0.2 then
		return cmd
	end
	local cu = c.Unit
	local spd = (ch:FindFirstChildOfClass("Humanoid") and ch:FindFirstChildOfClass("Humanoid").WalkSpeed) or 24
	local margin = CFG.BlastMargin or 1.5
	local out = c
	for _, ev in list do
		if ev.kind == "blast" and not ev.boomAt and not Mark.hazSkip(ev) then
			local ta = ev.t - nowS
			if ta > 0 and ta < 3.5 then
				local P = flat(ev.p)
				local rel = O - P
				local d = rel.Magnitude
				local radial = rel / math.max(d, 1e-3)
				local inward = -out:Dot(radial)
				-- inside already (deeper is worse), or the straight run would be inside when it goes off: no inward part.
				-- Only the inward component goes, the player keeps the tangent and decides how far to turn away.
				if inward > 0.05 and (d < ev.r + margin or flat(O + cu * spd * ta - P).Magnitude < ev.r + margin) then
					out = out + radial * inward
				end
			end
		end
	end
	if out ~= c then
		if not Mark.clampLog or os.clock() - Mark.clampLog > 1 then
			Mark.clampLog = os.clock()
			logFile("blast clamp", "stick bent away from the zone")
		end
		return Vector3.new(out.X, cmd.Y, out.Z)
	end
	return cmd
end

-- ===== Enemy blast zones (overlay) =====================================================================================
-- FUSE. The zone is the threat ripple the user picked for enemy charges (rings born at the centre, growing to the real
-- radius, amber -> red as it nears), over a faint filled disc, and the time left is a FUSE burning around the rim: the
-- remaining arc is the remaining time, its head a flickering white spark. A grenade also shows its hop path (dashed, from
-- where it is now to where it goes off). The detonation itself: one white shock ring running out past the rim.
-- One renderer for live and gallery: Mark.hazArt(seg, tris, n0, ev, now, clk) -> triangles used. now = ev.t's clock.
Mark.hazArt = function(seg, tris, n0, ev, now, clk)
	local cam = Mark.frameCam or Workspace.CurrentCamera
	local c = ev.p
	local R = ev.r
	if ev.boomAt then
		local age = clk - ev.boomAt
		if age < 0.3 then
			local u = age / 0.3
			local rr = R * (1 + 0.35 * (1 - (1 - u) ^ 2))
			local prev = nil
			for s = 0, 28 do
				local a = s / 28 * math.pi * 2
				local p = c + Vector3.new(math.cos(a) * rr, 0.2, math.sin(a) * rr)
				if prev then
					seg(prev, p, Color3.new(1, 1, 1):Lerp(Mark.kickPalette.live[1], u), 1 - u, 3.2 * (1 - u) + 1, 46)
				end
				prev = p
			end
		end
		return 0
	end
	local left = ev.t - now
	if left < -0.1 then
		return 0
	end
	local T0 = math.max(ev.t - (ev.seen or now), 0.3)
	local f = math.clamp(left / T0, 0, 1)
	local pal = left > 0.5 and Mark.kickPalette.armed or Mark.kickPalette.live
	local cl = pal[1]
	-- the faint floor of the zone
	local used = 0
	local cs = cam:WorldToViewportPoint(c + Vector3.new(0, 0.1, 0))
	if cs.Z > 0.2 then
		local prev, prevOk = nil, false
		for k = 0, 16 do
			local a = k / 16 * math.pi * 2
			local p = cam:WorldToViewportPoint(c + Vector3.new(math.cos(a) * R, 0.1, math.sin(a) * R))
			local ok = p.Z > 0.2
			if k > 0 and ok and prevOk and n0 + used < #tris then
				used += 1
				local tri = tris[n0 + used]
				tri.PointA, tri.PointB, tri.PointC = Vector2.new(cs.X, cs.Y), Vector2.new(prev.X, prev.Y), Vector2.new(p.X, p.Y)
				tri.Color, tri.Transparency, tri.Visible = cl, 0.1 + 0.12 * (1 - f), true
			end
			prev, prevOk = p, ok
		end
	end
	-- ripples: faster as the fuse burns down (per-zone phase accumulator, never os.clock / a changing period)
	local dt = math.clamp(clk - (ev.phAt or clk), 0, 0.1)
	ev.phAt = clk
	ev.ph = (ev.ph or 0) + dt * (1 / 0.7 + (1 / 0.22 - 1 / 0.7) * (1 - f))
	Mark.kickRipple(seg, c + Vector3.new(0, 0.15, 0), R, pal, ev.ph, clk, 2)
	-- the fuse: the remaining arc, starting on the side facing the camera so the head is easy to read
	local look = Mark.frameLook or cam.CFrame.LookVector
	local a0 = math.atan2(-look.Z, -look.X)
	local n = math.max(math.floor(32 * f + 0.5), 1)
	local ink = COL.Ink
	local prev = nil
	local head = nil
	for s = 0, n do
		local a = a0 + (s / 32) * math.pi * 2
		local p = c + Vector3.new(math.cos(a) * R, 0.25, math.sin(a) * R)
		if prev then
			seg(prev, p, ink, 0.55, 5, 44)
			seg(prev, p, Color3.new(1, 1, 1):Lerp(cl, 0.35), 0.95, 2.2, 45)
		end
		prev, head = p, p
	end
	if head and left > 0 then
		local blk = math.floor(clk * 30)
		for q = 0, 2 do
			local ang = Mark.hn(q, blk, 3) * math.pi
			local dir = Vector3.new(math.cos(ang), 0.6 + 0.4 * Mark.hn(q + 3, blk, 3), math.sin(ang))
			seg(head, head + dir * (0.8 + 0.6 * math.abs(Mark.hn(q + 6, blk, 3))), Color3.new(1, 1, 1), 0.9, 1.6, 46)
		end
	end
	-- grenade: the hop path, dashed
	local path = ev.path
	if path and #path > 1 then
		local dc = pal[3]
		for i = 1, #path - 1, 1 do
			if i % 2 == 1 then
				seg(path[i], path[i + 1], dc, 0.85, 2, 44)
			end
		end
		local g0 = path[1]
		seg(g0 - Vector3.new(0.6, 0, 0), g0 + Vector3.new(0.6, 0, 0), COL.Paper, 1, 2, 46)
		seg(g0 - Vector3.new(0, 0, 0.6), g0 + Vector3.new(0, 0, 0.6), COL.Paper, 1, 2, 46)
	end
	return used
end

-- Incoming projectile = a wire coming at you: ink bed + thin threat-coloured core along its predicted flight, chevrons
-- riding it at the projectile's real speed (they arrive when it arrives), and the threat ripple where it meets you.
-- v = { pts, len (cumulative), speed, hit (point or nil), key }. One renderer for the live overlay and the gallery.
-- RIBBON (SilentAim boomerang): the real loop to the interception point as a flowing ribbon, no head and no end marker: crests of
-- light run along it, it tapers and dissolves toward the meeting point; the point itself is the usual silent ring on the floor.
-- pts: 1-based world points (muzzle -> meeting point), feet: floor point under the meeting point.
Mark.ribbonArt = function(seg, pts, col, now, feet)
	local n = #pts
	if n < 2 then
		return
	end
	local L = { 0 }
	for k = 2, n do
		L[k] = L[k - 1] + (pts[k] - pts[k - 1]).Magnitude
	end
	local total = L[n]
	if total < 1 then
		return
	end
	local white = Color3.new(1, 1, 1)
	local step = math.clamp(total / 28, 1.4, 3)
	local m = math.max(2, math.floor(total / step))
	local hint = 2
	local function at(s)
		hint = 2
		while hint < n and L[hint] < s do
			hint += 1
		end
		local a, b = L[hint - 1], L[hint]
		return pts[hint - 1]:Lerp(pts[hint], b > a and math.clamp((s - a) / (b - a), 0, 1) or 0)
	end
	local prev = at(0)
	for i = 1, m do
		local u = i / m
		local p = at(u * total)
		-- two crests per 18 studs run toward the meeting point
		local wave = 0.5 + 0.5 * math.sin((u * total - now * 24) / 18 * math.pi * 2)
		wave *= wave
		local fade = 1 - math.clamp((u - 0.7) / 0.3, 0, 1) ^ 1.5
		local w = (2.8 - 2 * u) * (0.7 + 0.5 * wave)
		if fade > 0.03 then
			seg(prev, p, COL.Ink, 0.45 * fade, w + 2.2, 44)
			seg(prev, p, col:Lerp(white, wave * 0.8), (0.35 + 0.6 * wave) * fade, w, 45)
		end
		prev = p
	end
	if feet and Mark.silentRing then
		Mark.silentRing(seg, feet, col, now)
	end
end

-- FUSE RAIL (incoming projectile): the remaining path as dashes running at us, a spark on the projectile, and the impact
-- rim burning down with the time left. v = { pts (1-based, from the projectile), hit (point on the floor or nil),
-- frac (0..1 time left) , speed }.
Mark.fuseArt = function(seg, v, clk)
	local pts = v.pts
	local n = #pts
	if n < 2 then
		return
	end
	local pal = Mark.kickPalette.armed
	local hot = Color3.new(1, 1, 1)
	local L = { 0 }
	for k = 2, n do
		L[k] = L[k - 1] + (pts[k] - pts[k - 1]).Magnitude
	end
	local total = L[n]
	local hint = 2
	local function at(s)
		s = math.clamp(s, 0, total)
		hint = 2
		while hint < n and L[hint] < s do
			hint += 1
		end
		local a, b = L[hint - 1], L[hint]
		return pts[hint - 1]:Lerp(pts[hint], b > a and (s - a) / (b - a) or 0)
	end
	local gap, dash = 3.4, 1.7
	local s = (clk * math.max(v.speed or 40, 20) * 0.35) % gap
	while s < total - 0.5 do
		local a, b = at(s), at(math.min(s + dash, total))
		seg(a, b, COL.Ink, 0.5, 3.4, 44)
		seg(a, b, Color3.new(1, 1, 1):Lerp(pal[1], math.clamp(s / total + 0.2, 0, 1)), 0.9, 1.3, 45)
		s += gap
	end
	local p = pts[1]
	local hn = (math.sin(clk * 97.3) * 43758.5) % 1
	for k = 0, 2 do
		local a = hn * 6.28 + k * 2.09
		seg(p, p + Vector3.new(math.cos(a), 0.5, math.sin(a)) * (0.5 + hn * 0.5), hot, 0.9, 1.3, 46)
	end
	local hit = v.hit
	if hit then
		local left = math.clamp(v.frac or 1, 0, 1)
		local m = math.max(2, math.floor(left * 24))
		local prev
		for k = 0, m do
			local a = math.pi / 2 + k / m * left * math.pi * 2
			local q = hit + Vector3.new(math.cos(a) * 3.2, 0.1, math.sin(a) * 3.2)
			if prev then
				seg(prev, q, COL.Ink, 0.5, 3.6, 44)
				seg(prev, q, pal[2], 0.95, 1.4, 45)
			end
			prev = q
		end
	end
end


-- live state -> projArt input: its flight for up to 1.4 s (to the ground for ballistic ones), the homing punch as the
-- line to the ball it homes on, and the contact point when it comes within its radius of where we will be
Mark.projViz = function(st, nowS, root)
	local pts, len = {}, { 0 }
	local hit = nil
	local O, ourV = root.Position, flat(root.AssemblyLinearVelocity)
	local rad = (st.rad or 4) + 0.5
	if st.homing then
		local ball = Renderer.GetPosition()
		if not ball then
			return nil
		end
		local dt = math.max(nowS - st.at, 0)
		pts[1] = st.pos + st.vel * dt
		pts[2] = ball
		if liveOwnerId() == LocalPlayer.UserId then
			hit = Vector3.new(O.X, O.Y - 2.9, O.Z)
		end
	else
		local pathAt = Mark.projPathFn(st, nowS)
		Mark.fieldMod = Mark.fieldMod or require(Modules.Gameplay.FieldSettings)
		local best = rad
		for k = 0, 28 do
			local t = k * 0.05
			local p = pathAt(t)
			pts[#pts + 1] = p
			local us = O + ourV * t
			local d = flat(p - us).Magnitude
			if d < best and math.abs(p.Y - us.Y) < 5 then
				best, hit = d, Vector3.new(p.X, us.Y - 2.9, p.Z)
			end
			if not st.throw then
				local gy = Mark.fieldMod.GetGroundYAt(p)
				if type(gy) == "number" and p.Y <= gy + 0.5 then
					break
				end
			end
		end
	end
	for k = 2, #pts do
		len[k] = len[k - 1] + (pts[k] - pts[k - 1]).Magnitude
	end
	return { pts = pts, len = len, speed = math.max(st.vel.Magnitude, 40), hit = hit, key = tostring(st.id) }
end

Mark.hazDraw = function()
	local H = Mark.hazFx
	if not H then
		H = { lines = makeLines(900, 1.4, 44), tris = {} }
		H.pool = Mark.segPool(H.lines)
		for k = 1, 48 do
			H.tris[k] = newTri(42)
		end
		Mark.hazFx = H
	end
	local pool = H.pool
	pool.i = 1
	local used = 0
	if CFG.Draw and CFG.DrawHazard ~= false then
		local nowS = Workspace:GetServerTimeNow()
		local clk = os.clock()
		local drawn = 0
		for id, ev in Mark.hazEv do
			if ev.kind == "blast" then
				if (ev.boomAt and clk - ev.boomAt > 0.4) or ev.t < nowS - 0.6 then
					Mark.hazEv[id] = nil
				elseif drawn < 3 then
					drawn += 1
					used += Mark.hazArt(pool.seg, H.tris, used, ev, nowS, clk)
				end
			end
		end
		-- incoming projectiles (the grenade's hops are already in its zone)
		local root = ActorTargeting.GetActorRoot(LocalPlayer)
		local np = 0
		if not (Mark.projLive and next(Mark.projLive)) then
			Mark.projInit = nil
		end
		if root and Mark.projLive then
			for _, st in Mark.projLive do
				local who = st.src and playerOf(st.src)
				if np < 3 and st.item ~= "grenade" and st.src ~= LocalPlayer.UserId and not (who and sameTeam(who)) and nowS - st.at < 1.2 then
					local v = Mark.projViz(st, nowS, root)
					if v then
						np += 1
						-- time left to the impact: the path length to the point nearest the hit over the projectile speed
						v.frac = 1
						if v.hit then
							local bi, bd = #v.pts, math.huge
							for k = 1, #v.pts do
								local dd = flat(v.pts[k] - v.hit).Magnitude
								if dd < bd then
									bi, bd = k, dd
								end
							end
							Mark.projInit = Mark.projInit or {}
							local tHit = v.len[bi] / math.max(v.speed, 1)
							local t0 = Mark.projInit[v.key]
							if not t0 or tHit > t0 then
								t0 = tHit
								Mark.projInit[v.key] = t0
							end
							v.frac = t0 > 0.02 and math.clamp(tHit / t0, 0, 1) or 0
						end
						Mark.fuseArt(pool.seg, v, clk)
					end
				end
			end
		end
	end
	if CFG.Draw and CFG.DrawSpoof ~= false and Mark.sp then
		Mark.spoofDraw(pool.seg)
	end
	for k = used + 1, H.triHw or #H.tris do
		H.tris[k].Visible = false
	end
	H.triHw = used
	pool.finish()
	H.empty = used == 0 and pool.hw == 0
end

-- Projectiles, every frame on the live state (Mark.projLive: ProjectileStart + ProjectileMovement rows).
-- HOMING (rocketPunch, ProjectileVfx MotionKind PointHomingBall): it homes on the BALL (TargetBallId), not on us, with
-- the game's own steering ProjectileHoming.AdvancePointHoming (intercept lead, turn rate Speed/TurnRadius doubling every
-- TurnRateDoublingSeconds, x4 inside LinearTurnNearDistance). A sidestep cannot shake it (the ball moves with us). So
-- the decision is simulated with that same function, for every option:
--   keep  - the ball stays at our feet (moves with our current velocity);
--   pass  - PassAssistSync: a legit Lob (Pass.HandleInputBegan, real charge + animation, Mark.paPress) to a teammate;
--           the ball sits with us for the charge, then flies the solved lob (paSolve pts/times). Safe when the punch
--           never gets within ProjHitRadius of the ball before the teammate's arrival time and the release happens
--           before the punch reaches us.
-- If keep is hit, the safest pass (largest closest approach) is taken; no safe pass -> the old dump as a last resort.
-- STRAIGHT / BALLISTIC (bazooka, grenade, freezeGun, ...): our clearance for "stay" and 8 sidesteps of 5 studs over
-- the remaining flight, with the item's gravity and an explosion pad. Best clearance >= rad + ProjSafeMargin -> just
-- dodge (confidence high). Lower -> with the ball, pass it first (if the release fits before impact), then still step.
-- ProjHitRadius / the blast radius are NOT in the client dump: every decision is logged with its numbers ("proj ...").
-- Where a live enemy projectile is t seconds from nowS. A boomerang flies its throw (BoomerangThrow from the
-- ProjectileStart packet, Boomerang.GetPosition = a fixed loop, not a straight shot); anything else is the last
-- server row + its gravity (ProjectileVfx.PredictionConfigs).
Mark.projPathFn = function(st, nowS)
	if st.throw then
		Mark.boomMod = Mark.boomMod or require(Modules.Items.Boomerang)
		local B, th = Mark.boomMod, st.throw
		return function(t)
			return B.GetPosition(th, nowS + t, nil)
		end
	end
	local dt = math.max(nowS - st.at, 0)
	local g = st.grav or 0
	local p0 = st.pos + st.vel * dt + Vector3.new(0, -0.5 * g * dt * dt, 0)
	local v0 = st.vel + Vector3.new(0, -g * dt, 0)
	return function(t)
		return p0 + v0 * t + Vector3.new(0, -0.5 * g * t * t, 0)
	end
end

-- OUR POSE AS THE SERVER TESTS IT. The server tests a projectile against the pose we SENT: at server time t it holds what we did
-- lag seconds earlier (our packet's one-way trip ping/2 + the send interval CharacterSendIntervalSeconds 1/60 + ProjServerExtra).
-- The old dodge assumed our pose at t was where we would be at t: a 5 st step taken now reaches the server ping/2+ later, against a
-- boomerang flying 103 st/s that is 4-8 studs of "I already left" that the server never saw (user: the dodge is always late).
-- vel = our velocity, off = the step (teleport) taken NOW.
Mark.projPose = function(O, vel, off, t, lag)
	local s = t - lag
	if s < 0 then
		return O + vel * s
	end
	return O + off + vel * s
end

-- Smallest flat distance between a projectile path and our server pose over [0, tMax] (0.03 s grid) while the heights overlap.
Mark.projClear = function(pathAt, O, vel, off, lag, rad, tMax)
	local best, bestT = math.huge, 0
	local t = 0
	while t <= tMax do
		local p = pathAt(t)
		local us = Mark.projPose(O, vel, off, t, lag)
		local dz = math.abs(p.Y - (us.Y - 0.5))
		local d = flat(p - us).Magnitude
		if dz < 4.5 + rad * 0.5 and d < best then
			best, bestT = d, t
		end
		t += 0.03
	end
	return best, bestT
end

-- The user's own stick, kept out from under a projectile (user: a dodge is not only the step - do not let me walk INTO the
-- boomerang). wish = his unit direction, speed = his run speed. Returns the direction to use and whether it was changed: his own
-- when it clears the path (server pose), else the nearest turn (30 st .. 180 deg, either side) that does, else the widest.
Mark.projDirPick = function(paths, O, wish, speed, lag, margin)
	local function clear(dir)
		local worst = math.huge
		for _, P in paths do
			local c = Mark.projClear(P.pathAt, O, dir * speed, Vector3.zero, lag, P.rad, P.tEnd)
			worst = math.min(worst, c - P.rad)
		end
		return worst
	end
	local base = clear(wish)
	if base >= margin then
		return wish, false
	end
	local best, bestC = wish, base
	for _, a in { 30, -30, 60, -60, 90, -90, 135, -135, 180 } do
		local r = math.rad(a)
		local cand = Vector3.new(wish.X * math.cos(r) - wish.Z * math.sin(r), 0, wish.X * math.sin(r) + wish.Z * math.cos(r))
		local c = clear(cand)
		if c >= margin then
			return cand, true
		end
		if c > bestC then
			best, bestC = cand, c
		end
	end
	return best, best ~= wish
end

-- the projectile as the wall must stop it: the server's projectile hitbox is ProjectileHitboxScale 1.15 x the item's own
-- (ItemHitSettings); boomerang HitboxSize 4 x 1.8 x 4 (dump) = 2.3 st half-width. The old fixed 1.5 let a boomerang edge past
-- the barricade's side.
Mark.projWallRad = function(item)
	if item == "boomerang" then
		return 4 * 0.5 * 1.15
	end
	return 1.5 * 1.15
end

-- GetMoveCommand hook: the user's stick, turned away from a live projectile's path when his own direction runs into it. One answer
-- per 30 ms (the hook is asked several times a frame).
Mark.projDir = function(cc)
	local now = os.clock()
	local memo = Mark.projDirMemo
	if memo and now - memo.at < 0.03 and (memo.cc - cc).Magnitude < 0.05 then
		return memo.out
	end
	local paths = {}
	for id, P in Mark.projDanger do
		if now - P.at > 0.15 then
			Mark.projDanger[id] = nil
		else
			paths[#paths + 1] = P
		end
	end
	local out = cc
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local wish = unitOrNil(flat(cc))
	if #paths > 0 and root and wish then
		local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local lag = ping * 0.5 + 1 / 60 + (CFG.ProjServerExtra or 0.04)
		local speed = math.max(flat(root.AssemblyLinearVelocity).Magnitude, 16)
		local dir, changed = Mark.projDirPick(paths, root.Position, wish, speed, lag, CFG.ProjSafeMargin or 1.0)
		if changed then
			out = dir * cc.Magnitude
			if now - (Mark.projDirLog or 0) > 0.5 then
				Mark.projDirLog = now
				logFile("proj stick", "turned away", string.format("%.0f deg", math.deg(math.acos(math.clamp(wish:Dot(dir), -1, 1)))), "paths", #paths)
			end
		end
	end
	Mark.projDirMemo = { at = now, cc = cc, out = out }
	return out
end

Mark.projTick = function(character, root)
	Mark.hazFlee(character, root)
	local live = Mark.projLive
	if not live or next(live) == nil then
		return
	end
	local nowS = Workspace:GetServerTimeNow()
	local own = liveOwnerId() == LocalPlayer.UserId
	local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	local O = root.Position
	local ourV = flat(root.AssemblyLinearVelocity)
	for id, st in live do
		-- explosives live until ProjectileFinish (a grenade flies up to MaximumFlightSeconds 5 with rows only at the
		-- bounces): dropped after 1.2 s without a row, its later corrections had no state to land in
		local explosive = st.item == "grenade" or st.item == "bazooka" or st.item == "freezeGun"
		if (not explosive and nowS - st.at > 1.2) or nowS - st.born > 8 then
			-- a punch that left no trace: neither "wait" nor "eval" (the 3rd punch of the last session: no line at all)
			if st.homing and not st.waitLogged and not st.evalLogged then
				logFile("proj punch", "dropped unseen", nowS - st.at > 1.2 and "no row for 1.2 s" or "older than 8 s", "age", string.format("%.2f", nowS - st.born), "done", tostring(st.done))
			end
			live[id] = nil
			continue
		end
		if explosive then
			continue -- explosives are events (Mark.hazEv / Mark.hazFlee), not a corridor
		end
		local who = st.src and playerOf(st.src)
		if st.src == LocalPlayer.UserId or (who and sameTeam(who)) or st.done then
			continue
		end
		if st.wallUntil and os.clock() < st.wallUntil then
			continue -- a wall is being placed on its path: no dodge / pass in the meantime
		end
		local dt = math.max(nowS - st.at, 0)
		if st.homing then
			if own and Mark.meKeeper() then
				-- the keeper's ball is not knocked out by the punch: no lob, no dump
				if not st.keeperLogged then
					st.keeperLogged = true
					logFile("proj punch", "keeper holds: ignored")
				end
				continue
			end
			if not own then
				if not st.waitLogged then
					st.waitLogged = true
					local oid = liveOwnerId()
					local ow = type(oid) == "number" and oid ~= 0 and playerOf(oid) or nil
					local bl = Renderer.GetPosition()
					logFile("proj punch", "wait: ball not ours", "owner", tostring(oid), ow and (sameTeam(ow) and "mate " or "foe ") .. actorName(ow) or "free", "us-ball", typeof(bl) == "Vector3" and string.format("%.1f", flat(bl - O).Magnitude) or "-", "punch-ball", typeof(bl) == "Vector3" and string.format("%.1f", (st.pos - bl).Magnitude) or "-")
				end
				continue
			end
			Mark.homingMod = Mark.homingMod or require(Modules.Items.ProjectileHoming)
			Mark.projVfx = Mark.projVfx or require(Modules.Items.ProjectileVfx)
			local cfg = Mark.projVfx.PredictionConfigs[st.item]
			local ball = Renderer.GetPosition()
			if not (cfg and typeof(ball) == "Vector3") then
				continue
			end
			local dir0 = st.vel.Magnitude > 0.1 and st.vel.Unit or unitOrNil(ball - st.pos) or Vector3.new(0, 0, 1)
			local hitR = CFG.ProjHitRadius or 3
			-- returns time of hit (or nil) and the closest approach, against ballFn(t) = position, velocity
			local function chase(ballFn, horizon)
				local p, d, age = st.pos, dir0, (st.at - st.born)
				-- catch up the time since the last packet first (target = where the ball is now)
				if dt > 0 then
					local b0, v0 = ballFn(0)
					p, d, age = Mark.homingMod.AdvancePointHoming(cfg, p, d, b0, v0, age, dt)
				end
				local step = 1 / 30
				local t = 0
				local closest = (p - ballFn(0)).Magnitude
				while t < horizon do
					local b, v = ballFn(t)
					p, d, age = Mark.homingMod.AdvancePointHoming(cfg, p, d, b, v, age, step)
					t += step
					local b2 = ballFn(t)
					local dd = (p - b2).Magnitude
					if dd < closest then
						closest = dd
					end
					if dd <= hitR then
						return t, closest
					end
				end
				return nil, closest
			end
			local keepFn = function(t)
				return ball + ourV * t, ourV
			end
			local tKeep, cKeep = chase(keepFn, 2.0)
			if not st.evalLogged then
				st.evalLogged = true
				logFile("proj punch", "eval", "keepHit", tKeep and string.format("%.2f", tKeep) or "none", "closest", string.format("%.1f", cKeep or -1), "dist", string.format("%.1f", (st.pos - ball).Magnitude), "spd", string.format("%.0f", st.vel.Magnitude), "age", string.format("%.2f", st.at - st.born))
			end
			if not tKeep then
				continue
			end
			-- AutoShield first: one activation, the ball stays ours (a pass gives it away, a wall needs a line)
			if not st.shieldTried then
				st.shieldTried = true
				if Mark.shieldNow(string.format("%s keepHit %.2f", st.item, tKeep), tKeep) then
					st.done = true
					continue
				end
			end
			-- BarricadeAddon: the punch homes on the ball we hold; a wall on its approach stops it (path = the same simulation)
			if not st.wallTried then
				local trail = {}
				do
					local p, d, age = st.pos, dir0, (st.at - st.born)
					if dt > 0 then
						local b0, v0b = keepFn(0)
						p, d, age = Mark.homingMod.AdvancePointHoming(cfg, p, d, b0, v0b, age, dt)
					end
					trail[1] = p
					local tt = 0
					while tt < tKeep + 0.2 and #trail < 90 do
						local b, vb = keepFn(tt)
						p, d, age = Mark.homingMod.AdvancePointHoming(cfg, p, d, b, vb, age, 1 / 30)
						tt += 1 / 30
						trail[#trail + 1] = p
					end
				end
				local okW, wWhy = Mark.wallVsPath(root, function(t)
					local f = t * 30
					local i = math.floor(f) + 1
					if i < 1 or i >= #trail then
						return nil
					end
					return trail[i]:Lerp(trail[i + 1], f - math.floor(f))
				end, tKeep, "rocketPunch", { proj = true, rad = 1.5 })
				if okW == "equip" then
					st.wallUntil = os.clock() + 0.12 -- barricades coming out: hold the dodge a moment, place on the next tick
					continue
				elseif okW then
					st.wallTried = true
					st.wallUntil = os.clock() + 0.35
					continue
				elseif wWhy and (not st.wallLog or os.clock() - st.wallLog > 1) then
					st.wallLog = os.clock()
					logFile("proj wall", st.item, "no", wWhy, "keepHit", string.format("%.2f", tKeep))
				end
			end
			-- options: a lob to each teammate, charged as long as the time allows (the release packet must reach the server
			-- before the punch reaches the ball: tKeep - ping/2 - ProjPassMargin), never waiting for the full solve
			local budget = tKeep - ping * 0.5 - (CFG.ProjPassMargin or 0.1)
			local minC = CFG.PassMinCharge or 0.1
			local best, bestSel, bestSol, tried = nil, nil, nil, {}
			if budget >= minC and CFG.PassAssistSync ~= false and Mark.paList and Mark.paSolve and Mark.paPress then
				for _, sel in Mark.paAuto(root) do
					if #tried >= 4 then
						break
					end
					local sol = Mark.paSolve(sel)
					if sol and sol.pts and sol.times and #sol.pts >= 2 then
						local charge = math.max(math.min(sol.charge or 0.1, budget), minC)
						local release = charge + ping * 0.5 + 0.03
						local pts, ts = sol.pts, sol.times
						local function lobFn(t)
							if t <= release then
								return ball + ourV * t, ourV
							end
							local tt = t - release
							for i = 2, #ts do
								if ts[i] >= tt then
									local a = (tt - ts[i - 1]) / math.max(ts[i] - ts[i - 1], 1e-3)
									local v = (pts[i] - pts[i - 1]) / math.max(ts[i] - ts[i - 1], 1e-3)
									return pts[i - 1]:Lerp(pts[i], math.clamp(a, 0, 1)), v
								end
							end
							return pts[#pts], Vector3.zero
						end
						local horizon = release + (sol.t or ts[#ts])
						local tHit, cl = chase(lobFn, math.min(horizon, 3))
						local safe = tHit == nil and release < tKeep - 0.03 and not sol.contested
						tried[#tried + 1] = string.format("%s %s cl %.1f rel %.2f%s", sel.name, safe and "SAFE" or "no", cl, release, sol.contested and " contested" or "")
						if safe and (not best or cl > best) then
							best, bestSel, bestSol = cl, sel, sol
						end
						-- no safe lob: the one that keeps the punch farthest from the ball is still a legit pass to a mate,
						-- better than the raw-packet dump (which the punch also reaches: in sim it catches a lob launched
						-- 80-120 studs away almost always; only a lob back over a far punch escaped)
						if not sol.contested and release < tKeep - 0.03 and (not st.fbCl or cl > st.fbCl) then
							st.fbCl, st.fbSel, st.fbSol = cl, sel, sol
						end
					end
				end
			end
			st.done = true
			local unsafe = false
			if not bestSel and st.fbSel then
				bestSel, bestSol, best, unsafe = st.fbSel, st.fbSol, st.fbCl, true
			end
			if Mark.pa and Mark.pa.live then
				logFile("proj", st.item, "pass already live")
			elseif bestSel and Mark.paPress(bestSel, bestSol, unsafe and "projectile-unsafe" or "projectile", budget) then
				logFile("proj pass", unsafe and "UNSAFE" or "safe", st.item, "to", bestSel.name, "keepHit", string.format("%.2f", tKeep), "charge", string.format("%.2f", math.max(math.min(bestSol.charge or 0.1, budget), minC)), "clear", string.format("%.1f", best), "tried", table.concat(tried, " | "))
			else
				local fly = ball - st.pos
				Mark.dumpBall(root, Vector3.new(-fly.Z, 0, fly.X))
				logFile("proj dump", st.item, "keepHit", string.format("%.2f", tKeep), "keepClose", string.format("%.1f", cKeep), "budget", string.format("%.2f", budget), "tried", #tried > 0 and table.concat(tried, " | ") or "no mates")
			end
		else
			if Mark.move.mode == "dribble" or (st.lastDodge and os.clock() - st.lastDodge < 0.4) then
				continue
			end
			local pathAt = Mark.projPathFn(st, nowS)
			local p0 = pathAt(0)
			local v0 = (pathAt(0.05) - p0) / 0.05
			if v0.Magnitude < 8 then
				continue
			end
			local rad = st.rad or 4
			local lag = ping * 0.5 + 1 / 60 + (CFG.ProjServerExtra or 0.04)
			-- every live threat is also a corridor for the user's own stick (Mark.projDir, GetMoveCommand)
			local tEnd = 1.4
			if st.throw then
				tEnd = math.clamp(Mark.boomMod.GetEndTime(st.throw) - nowS, 0.1, 2.2)
			end
			Mark.projDanger = Mark.projDanger or {}
			Mark.projDanger[id] = { pathAt = pathAt, rad = rad, tEnd = tEnd, at = os.clock() }
			local function clearance(off)
				return Mark.projClear(pathAt, O, ourV, off, lag, rad, 1.4)
			end
			local stay, tImp = clearance(Vector3.zero)
			local margin = CFG.ProjSafeMargin or 1.0
			if stay >= rad + margin then
				continue
			end
			-- the forcefield first when the projectile really reaches us and there is time for it (0.25 s to come up): it keeps
			-- the ball, the position and the wall item; a wall / dodge only when it is late or not owned
			if not st.shieldTried and CFG.AutoShield and tImp >= Mark.shieldReady() then
				st.shieldTried = true
				if Mark.shieldNow(string.format("%s hit in %.2f stay %.1f", st.item, tImp, stay), tImp) then
					st.done = true
					continue
				end
			end
			-- BarricadeAddon: a wall on its path instead of a dodge / pass (explosives excluded: the blast would still reach us)
			if st.item ~= "bazooka" and st.item ~= "grenade" and not st.wallTried then
				local okW, wWhy = Mark.wallVsPath(root, pathAt, tImp, st.item, { proj = true, rad = Mark.projWallRad(st.item) })
				if okW == "equip" then
					st.wallUntil = os.clock() + 0.12 -- barricades coming out: hold the dodge a moment, place on the next tick
					continue
				elseif okW then
					st.wallTried = true
					st.wallUntil = os.clock() + 0.35
					continue
				elseif wWhy and (not st.wallLog or os.clock() - st.wallLog > 1) then
					st.wallLog = os.clock()
					logFile("proj wall", st.item, "no", wWhy, "tImp", string.format("%.2f", tImp))
				end
			end
			-- dodge across its travel AT the impact (a boomerang curves: its start velocity is not where it comes from)
			local axis = unitOrNil(flat(pathAt(tImp + 0.03) - pathAt(math.max(tImp - 0.03, 0)))) or unitOrNil(flat(v0)) or Vector3.new(0, 0, 1)
			local bestOff, bestC = nil, stay
			for k = 0, 7 do
				local a = k * math.pi / 4
				local dir = Vector3.new(axis.X * math.cos(a) - axis.Z * math.sin(a), 0, axis.X * math.sin(a) + axis.Z * math.cos(a))
				local off = dir * 5
				if not (Mark.wallHit and Mark.wallHit(O, dir, 5.5)) then
					local c = clearance(off)
					if c > bestC then
						bestOff, bestC = off, c
					end
				end
			end
			local sure = bestC >= rad + margin
			-- AutoShield: a hit no step clears (and no wall) - the shield takes it; nothing else this frame
			if not sure and not st.shieldTried and tImp > 0.05 then
				st.shieldTried = true
				if Mark.shieldNow(string.format("%s hit in %.2f stay %.1f step %.1f", st.item, tImp, stay, bestC), tImp) then
					st.done = true
					continue
				end
			end
			if own and not sure and CFG.PassAssistSync ~= false and Mark.paList and Mark.paPress and not (Mark.pa and Mark.pa.live) then
				-- low confidence: get rid of the ball legitimately before the impact if the lob can be released in time
				local pick, pickSol, pickD = nil, nil, -1
				for _, sel in Mark.paAuto(root) do
					local sol = Mark.paSolve(sel)
					if sol and not sol.contested and (CFG.PassMinCharge or 0.1) + ping * 0.5 + (CFG.ProjPassMargin or 0.1) < tImp then
						local dAway = flat(sol.land - pathAt(tImp)).Magnitude
						if dAway > pickD then
							pick, pickSol, pickD = sel, sol, dAway
						end
					end
				end
				if pick and Mark.paPress(pick, pickSol, "projectile", tImp - ping * 0.5 - (CFG.ProjPassMargin or 0.1)) then
					logFile("proj pass", st.item, "to", pick.name, "stay", string.format("%.1f", stay), "bestStep", string.format("%.1f", bestC), "rad", string.format("%.1f", rad), "tImp", string.format("%.2f", tImp))
				end
			end
			if bestOff then
				Mark.stepAway(root, bestOff, "proj")
				st.lastDodge = os.clock()
				logFile("proj dodge", st.item, sure and "sure" or "unsure", "stay", string.format("%.1f", stay), "step", string.format("%.1f", bestC), "rad", string.format("%.1f", rad), "tImp", string.format("%.2f", tImp))
			end
		end
	end
end

Mark.tickHazard = function(character, root)
	Mark.shieldTick(root)
	Mark.gunTick(root)
	Mark.gunPushTick(root)
	Mark.stateWatch(character)
	Mark.chargeWatch()
	Mark.sprintWatch()
	local own = liveOwnerId() == LocalPlayer.UserId
	Mark.slideAudit(root)
	Mark.tickKickDodge(root, own)
	Mark.slideTrackTick(root)
	Mark.teleTick()
	if not CFG.AutoDodge then
		return
	end
	Mark.oilSlideTick(character, root)
	Mark.projTick(character, root)
	Mark.evadeTick(character, root)
	local now = Workspace:GetServerTimeNow()
	local R = CFG.HammerRadius
	for uid, h in Mark.hammers do
		local left = h.slamAt - now
		if left < -0.4 then
			local d = flat(root.Position - h.strike).Magnitude
			logFile("skill hammer slam", h.name, "dist", string.format("%.1f", d), "air", tostring(not CharacterControllers.IsLanded(character, character:FindFirstChildOfClass("Humanoid"))))
			Mark.hammers[uid] = nil
		elseif left > -0.05 then
			local at = root.Position + flat(root.AssemblyLinearVelocity) * math.max(left, 0)
			local d = flat(at - h.strike).Magnitude
			if d <= R then
				local act = "-"
				if own and not (Mark.pa and Mark.pa.live) then -- a blast pass (Mark.hazFlee) is already taking the ball out
					local flickReady = os.clock() - (Mark.hazardFlickAt or 0) > 1.5
					if flickReady and left >= 0.5 then
						Mark.plainFlick()
						act = "flick"
					elseif left < 0.5 and os.clock() - (Mark.hazardFlickAt or 0) > 1.5 and not h.stepped then
						local away = unitOrNil(flat(root.Position - h.strike)) or unitOrNil(flat(root.CFrame.LookVector))
						local need = math.min(R - d + 1, 5)
						if away and need > 0 then
							h.stepped = true
							Mark.hazardStep(root, away * need, "hammer")
							act = "step"
						end
					end
				end
				-- jump: airborne through the slam; rise ~0.27 s, so leave 0.3 s before it
				if (not own or os.clock() - (Mark.hazardFlickAt or 0) > 0.42) and left <= 0.32 and not h.jumped then
					if Mark.doJump("hammer") then
						h.jumped = true
						act = act .. "+jump"
					end
				end
				if act ~= "-" then
					logFile("skill hammer", act, h.name, "left", string.format("%.2f", left), "d", string.format("%.1f", d))
				end
			end
		end
	end
end

Mark.moveSteer = function(dir, mode, replay)
	local m = Mark.move
	m.mode = mode or m.mode or "steer"
	-- m.want is what the CALLER asked for; m.dir is that after barricade / oil deflection. moveTick re-applies the
	-- steer every frame from m.want: it used to feed the already deflected m.dir back through wallDir, so the
	-- deflection compounded frame after frame and the agent ended up running along the wall in one direction
	-- (AutoWall bug) until the next caller overwrote it.
	if not replay then
		m.want = dir
	end
	m.dir = dir
	if not replay then
		m.at = os.clock() -- the caller that owns this mode is alive: Mark.moveLive expires it when it stops calling
	end
	local ch = LocalPlayer.Character
	if ch and dir then
		local face = m.look or dir
		local steerRoot = ActorTargeting.GetActorRoot(LocalPlayer)
		if Mark.wallDir and steerRoot then
			dir = Mark.wallDir(steerRoot, dir) or dir
			m.dir = dir
		end
		if steerRoot then
			dir = Mark.oilDir(steerRoot, dir, m.mode) or dir
			dir = Mark.mineDir(steerRoot, dir) or dir
			m.dir = dir
		end
		local rot = (m.mode == "dodge" or m.mode == "block" or m.mode == "air")
		origSetMove(ch, dir, face, rot)
		if m.mode == "ball" or m.mode == "box" or m.mode == "walk" or m.mode == "dodge" or m.mode == "dribble" or m.mode == "take" or m.mode == "block" or m.mode == "gk" or m.mode == "kick" or m.mode == "flee" or m.mode == "duel" or m.mode == "lob" or m.mode == "air" then
			Mark.agentHold(true, m.mode)
		end
		if m.mode == "dodge" then
			local root = ActorTargeting.GetActorRoot(LocalPlayer)
			if root and not Mark.dodgeFaced then
				-- snap the facing and hold it with an auto-rotate lock for the whole dodge (the old one-off CFrame write
				-- was turned back at normal turn speed by TurnControl the next frame)
				local fd = unitOrNil(flat(dir))
				if fd then
					root.CFrame = CFrame.lookAt(root.Position, root.Position + fd)
					TurnControl.LockAutoRotate("Dribble", fd)
					Mark.dodgeLockOn = true
				end
				Mark.dodgeFaced = true
			end
		end
	end
end

Mark.moveStop = function(only)
	local m = Mark.move
	if only and m.mode ~= only then
		return
	end
	local was = m.mode
	local lastDir = m.dir
	m.mode = nil
	m.dir = nil
	m.want = nil
	m.look = nil
	m.pts = nil
	local ch = LocalPlayer.Character
	-- AIR COAST (user: "after the script's jump it stops moving"): a plan that ends while we are in the air (Air
	-- Intercept / AutoBall / lob re-solve from the arc and drop it) used to zero the stick mid-jump - the body stalled and
	-- fell straight down. In the air the last agent direction is kept until we land (GetMoveCommand hook).
	local hum = ch and ch:FindFirstChildOfClass("Humanoid")
	if ch and hum and lastDir and lastDir.Magnitude > 0.2 and not CharacterControllers.IsLanded(ch, hum)
		and (was == "air" or was == "ball" or was == "block" or was == "lob" or was == "duel" or was == "kick") then
		Mark.coast = { dir = lastDir, at = os.clock() }
	elseif ch then
		origSetMove(ch, Vector3.zero, Vector3.zero, false)
	end
	if was == "walk" or was == "take" or was == "box" or was == "dodge" or was == "block" or was == "ball" or was == "gk" or was == "kick" or was == "flee" or was == "air" then
		Mark.agentHold(false)
	end
	if was == "block" then
		Mark.standing = false
		Mark.sprintStand(false)
		Mark.blockLogged = nil
		Mark.blockDest = nil
		TurnControl.ReleaseAutoRotate("Aim")
		TurnControl.SetTurnSpeedFactor(1)
		logFile("block stop")
	end
	if was == "ball" then
		Mark.ballLogged = nil
		logFile("ball stop", Mark.ballStopWhy or "-")
		Mark.ballStopWhy = nil
	end
	if was == "dodge" then
		Mark.dodgeEndedAt = os.clock()
		Mark.dodgeAt = nil
		Mark.dodgeDest = nil
		Mark.dodgeSign = nil
		Mark.dodgeFrom = nil
		Mark.dodgeThreat = nil
		Mark.dodgeLogged = nil
		Mark.dodgeFaced = nil
		Mark.dodgeDone = true
		Mark.dodgeBoosted = nil
		TurnControl.ReleaseAutoRotate("Dribble")
		Mark.dodgeLockOn = nil
		Mark.dodgeDirFixed = nil
		TurnControl.SetTurnSpeedFactor(1)
	end
	if was == "dribble" then
	end
end

-- End of a dodge. It lived only in the field-player half of stepLogic; the keeper branch returns before it, so a
-- dodge taken as keeper kept steering (GetMoveCommand returns move.dir while any mode is set) and kept its facing
-- lock until the next dodge. Called from both halves; hard cap 1.4 s.
Mark.dodgeTend = function(root)
	local m = Mark.move
	if Mark.dodgeLockOn and (not m or m.mode ~= "dodge") then
		TurnControl.ReleaseAutoRotate("Dribble")
		TurnControl.SetTurnSpeedFactor(1)
		Mark.dodgeLockOn = nil
		Mark.dodgeFaced = nil
		logFile("dodge lock", "released-orphan")
	end
	if not (m and m.mode == "dodge") then
		return
	end
	if ClientDodge.IsDribbling() then
		Mark.moveStop("dodge")
		return
	end
	Mark.dodgeSteer(root, Mark.dodgeThreat or dribbleDanger)
	if Mark.move.mode == "dodge" and Mark.dodgeAt and os.clock() - Mark.dodgeAt > 1.4 then
		logFile("dodge", "timeout")
		Mark.moveStop("dodge")
	end
end

-- Where the slide box will be. rootAt(te): his root and heading at slide time te. Non-assisted: his current
-- (re-anchored) line. Assisted: the game's real homing (Mark.assistPath, rotateFlatDirectionToward toward the
-- predicted target until the hand-off) toward OUR predicted pose.
Mark.slideRootAt = function(lock, elapsed, targetAt, assisted)
	if not assisted or liveOwnerId() ~= LocalPlayer.UserId then -- the assist homes on the ball OWNER only
		return function(bt)
			return lock.origin + lock.heading * Mark.dumpTravel(bt), lock.heading
		end
	end
	local body = lock.origin + lock.heading * Mark.dumpTravel(math.max(elapsed, 0))
	return Mark.assistPath(body, lock.heading, math.max(elapsed, 0), targetAt)
end

-- posAt(sv): our pose sv seconds after NOW on the client timeline (negative = the past). The server tests the pose we
-- had `ping` ago, so slide time te maps to sv = te - elapsed - ping.
Mark.slideClearance = function(lock, elapsed, posAt, assisted, ping)
	local hb = HitboxSettings.SlideTackle
	local half = hb.Size * 0.5
	local t0 = C.HitboxDelaySeconds
	local t1 = t0 + C.HitboxSeconds
	local function targetAt(te)
		return posAt(te - elapsed - ping)
	end
	local rootAt = Mark.slideRootAt(lock, elapsed, targetAt, assisted)
	local worst = math.huge
	local te = math.max(t0, elapsed)
	while te <= t1 + 1e-4 do
		local rp, hd = rootAt(te)
		local p = targetAt(te)
		local proxy = { CFrame = CFrame.lookAt(rp, rp + hd) }
		local cf = HitboxSettings.GetCFrame(proxy, hb)
		local lp = cf:PointToObjectSpace(Vector3.new(p.X, rp.Y, p.Z))
		local c = math.max(math.abs(lp.X) - half.X, math.abs(lp.Z) - half.Z)
		if c < worst then
			worst = c
		end
		te += 0.04
	end
	if worst == math.huge then
		return 99
	end
	return worst - 1.6
end

Mark.dodgeSteer = function(root, threat)
	if ClientDodge.IsDribbling() then
		return
	end
	-- (a dodge is plain movement: it must NOT touch a charge. v39 cancelled it here - that was the "dodge resets my
	-- charge" report. The hang after a dodge came from the keeper-branch dodge never ending: see Mark.dodgeTend.)
	if not (root and threat) then
		if Mark.dodgeAt and os.clock() - Mark.dodgeAt > 0.4 then
			Mark.dodgeDone = true
			if Mark.moveStop then
				Mark.moveStop("dodge")
			end
		end
		return
	end
	local lock = slideLock[threat.character]
	if not lock and threat.actor then
		local ch = Actors.GetCharacter(threat.actor)
		lock = ch and slideLock[ch]
	end
	if not lock then
		lock = {
			heading = threat.heading,
			origin = threat.origin or (threat.root and threat.root.Position),
		}
	end
	if lock.usedDribble and ClientDodge.IsDribbling() then
		return
	end
	if Mark.dodgeDone then
		return
	end
	-- WITH THE BALL: the dribble is the answer, the dodge only when the dribble is still on cooldown AT THE IMPACT.
	-- The dribble's iframe (Dodge.ActiveSeconds 1) covering the hit is what gives the game's
	-- SuccessfulDodgeSpeedBoost (1.5 s), so: cooldown free now -> dribble now; it frees up before his box reaches us
	-- (cdLeft + ping/2 + 0.03 <= impact) -> wait and dribble then (the threat is re-read every frame); otherwise -> dodge.
	-- Impact = threat.hitIn (first time his real box contains our server pose, from Mark.slideAtUs), else the earliest
	-- possible hit from his elapsed slide time.
	if not Mark.dodgeAt and liveOwnerId() == LocalPlayer.UserId and not threat.strong then
		return -- with the ball only a strong read (his real box on our server pose) costs a dribble or a dodge
	end
	if not Mark.dodgeAt and liveOwnerId() == LocalPlayer.UserId and CFG.AutoDribble then
		local now = os.clock()
		local cdLeft = Mark.dribbleLeft()
		local elapsed0 = lock.t0 and (now - lock.t0) or (lock.elapsed or threat.elapsed or 0)
		local hitIn = threat.hitIn or math.max(C.HitboxDelaySeconds - elapsed0, 0)
		local pingD = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		local verdict
		if cdLeft <= 0 then
			local ok, why = false, "aerial"
			if not Mark.aerial and not Mark.flickStrike then
				ok, why = tryDribble()
			end
			if ok then
				lock.handled = true
				verdict = "dribble sent"
			else
				verdict = "dribble refused " .. tostring(why)
			end
		elseif cdLeft + pingD * 0.5 + 0.03 <= hitIn then
			verdict = "wait dribble"
		end
		if verdict then
			if not Mark.ownDodgeLog or now - Mark.ownDodgeLog > 0.3 or verdict ~= Mark.ownDodgeWhy then
				Mark.ownDodgeLog, Mark.ownDodgeWhy = now, verdict
				logFile("dodge gate", verdict, "cdLeft", string.format("%.2f", cdLeft), "hitIn", string.format("%.2f", hitIn), "strong", tostring(threat.strong))
			end
			if verdict ~= "dribble refused cd" and not verdict:find("refused") then
				return
			end
		else
			if not Mark.ownDodgeLog or now - Mark.ownDodgeLog > 0.3 or Mark.ownDodgeWhy ~= "dodge" then
				Mark.ownDodgeLog, Mark.ownDodgeWhy = now, "dodge"
				logFile("dodge gate", "dodge: dribble cd at impact", "cdLeft", string.format("%.2f", cdLeft), "hitIn", string.format("%.2f", hitIn), "strong", tostring(threat.strong))
			end
		end
	end
	local elapsed = lock.t0 and (os.clock() - lock.t0) or (lock.elapsed or threat.elapsed or 0)
	local live = root.Position
	local heading = lock.heading or Vector3.new(0, 0, 1)
	local right = Vector3.new(-heading.Z, 0, heading.X)
	if right.Magnitude < 0.05 then
		right = Vector3.new(1, 0, 0)
	else
		right = right.Unit
	end
	local at = Mark.slideAtUs(lock, elapsed, root, threat.actor)
	local approach = threat.approach or (at and at.approach)
	local willHit = (at and at.fire) or threat.fire or threat.force
	local closest = (at and at.closest) or (threat.root and threat.root.Position) or live
	local lat = right:Dot(flat(live - closest))
	local along = heading:Dot(flat(live - (lock.origin or closest)))
	-- a homing (assisted) tackler is still turning toward us until the hand-off: a step now is re-aimed at. Wait until
	-- the direction is about to lock (hand-off minus ping), then step - the plan below simulates the locked heading.
	local pingD = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
	if not Mark.dodgeAt and Mark.assistOK(threat.actor) and elapsed < C.HitboxDelaySeconds - pingD - 0.05 then
		return
	end
	-- the window is over for the SERVER only after the packet and our pose have both travelled: hold until then, so
	-- control does not come back (and walk into the box) while the slide is still live there
	local slideOver = elapsed > C.HitboxDelaySeconds + C.HitboxSeconds + pingD + 0.08
	if Mark.dodgeAt and slideOver then
		Mark.dodgeDone = true
		if Mark.moveStop then
			Mark.moveStop("dodge")
		end
		return
	end
	if not Mark.dodgeAt and not willHit and not approach then
		return
	end
	if not Mark.dodgeSign then
		local side = right:Dot(flat(live - (lock.origin or live)))
		local sign = (side >= 0) and 1 or -1
		if math.abs(side + sign * 5) < math.abs(side - sign * 5) then
			sign = -sign
		end
		-- the user's own direction wins: dodging against it is undone the moment control comes back
		local u = Mark.userInputDir()
		if u and math.abs(right:Dot(u)) > 0.25 then
			sign = right:Dot(u) > 0 and 1 or -1
		end
		Mark.dodgeSign = sign
		Mark.dodgeUser = u and fmtV(u) or "-"
	end
	local sign = Mark.dodgeSign
	local dir = right * sign
	if dir.Magnitude < 0.1 then
		dir = right
	end
	-- Teleport direction by score, not just "perpendicular to his heading". Roblox interpolates our replicated CFrame
	-- from the old spot to the new one, so for the server-side hit check we sweep the whole segment: the midpoint
	-- must already be clear of the slide path, not only the end. Straight ahead along our own run is penalised (it
	-- keeps us on the line he is sliding into), straight back too; user input breaks near-ties.
	if not Mark.dodgeAt and lock and lock.heading then
		local u = Mark.userInputDir()
		local runDir = unitOrNil(flat(root.AssemblyLinearVelocity)) or u
		local best, bestS = dir, -math.huge
		local ping = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
		Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
		local vB = (Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(root.Parent), false) or 24) * 1.08
		local v0 = flat(root.AssemblyLinearVelocity)
		local assisted = Mark.assistOK(threat.actor)
		-- Each of the 16 directions is simulated against the REAL slide box over its whole hit window: our server pose
		-- (what the server tests) is the pose from `ping` ago - the old run until the step lands, then +5 studs and the
		-- dash - against a box laid along the packet heading, or, for an actor seen homing, along the heading the assist
		-- will have turned to by the hand-off. Score = clearance of the body (1.6) from the box, minimum over the window.
		for k = 0, 15 do
			local a = k / 16 * math.pi * 2
			local d = Vector3.new(math.cos(a), 0, math.sin(a))
			local function posAt(sv)
				if sv < 0 then
					return live + v0 * sv
				end
				return live + d * (CFG.DodgeTeleport ~= false and 5 or 0) + d * (vB * sv)
			end
			local clear = Mark.slideClearance(lock, elapsed, posAt, assisted, ping)
			if type(clear) == "number" then
				local s = clear
				if runDir then
					local f = d:Dot(runDir)
					if f > 0.8 then
						s -= 1.2 -- keeps us on the line we run on
					elseif f < -0.8 then
						s -= 0.8
					end
				end
				-- the user's own stick breaks ties among SAFE options only (never buys an unsafe one)
				if u and s >= 0 then
					s += d:Dot(u) * 1.5
				end
				if s > bestS then
					best, bestS = d, s
				end
			end
		end
		dir = best
		Mark.dodgeDirFixed = best
		Mark.dodgeScore = bestS
	elseif Mark.dodgeAt and Mark.dodgeDirFixed then
		dir = Mark.dodgeDirFixed
	end
	if not Mark.dodgeAt then
		Mark.dodgeAt = os.clock()
		lock.handled = true
		Mark.dodgeFrom = root.Position
		if CFG.DodgeTeleport ~= false then
			local step = dir.Unit * 5
			root.CFrame = root.CFrame + step
			LocalMovementGuard.RegisterDisplacement(root, step)
			CharacterMotion.SetStreamVelocity(root.Parent, root.AssemblyLinearVelocity)
			logFile("dodge tp", "5.00", fmtV(step))
		else
			logFile("dodge walk", fmtV(dir))
		end
	end
	Mark.dodgeDest = root.Position + dir * 6
	Mark.move.pts = { Mark.dodgeFrom or root.Position, Mark.dodgeDest }
	Mark.move.born = Mark.move.born or os.clock()
	Mark.move.i = 1
	Mark.dodgeThreat = threat
	if not Mark.dodgeLogged then
		Mark.dodgeLogged = true
		logFile(
			"dodge start",
			"dir",
			fmtV(dir),
			"hit",
			willHit,
			"lat",
			string.format("%.2f", lat),
			"along",
			string.format("%.1f", along),
			"live",
			tostring(at and at.hits),
			"ghost",
			tostring(at and at.hits),
			"fut",
			tostring(at and at.fut),
			"user",
			Mark.dodgeUser or "-",
			"score",
			string.format("%.1f", Mark.dodgeScore or -1),
			"dribbleReady",
			tostring(os.clock() - lastDodgeAt >= dodgeEnforced),
			"cdLeft",
			string.format("%.1f", math.max(0, dodgeEnforced - (os.clock() - lastDodgeAt))),
			"own",
			tostring(liveOwnerId() == LocalPlayer.UserId),
			"assisted",
			tostring(Mark.assistOK(threat.actor))
		)
	end
	local holdDir = dir
	if Mark.dodgeAt and os.clock() - Mark.dodgeAt > 0.3 then
		local uIn = Mark.userInputDir()
		if uIn and lock.heading then
			-- the burst is over: give the stick back only where the box stays clear for the rest of the window
			-- (before, the whole dodge belonged to the script and control returned the moment `fire` flickered off)
			Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
			local vU = (Mark.mover.GetRunWalkSpeed(Mark.mover.GetBaseWalkSpeed(root.Parent), false) or 24)
			local pingH = math.clamp(LocalPlayer:GetNetworkPing() or 0.07, 0.02, 0.25)
			local v0h = flat(root.AssemblyLinearVelocity)
			local clr = Mark.slideClearance(lock, elapsed, function(sv)
				if sv < 0 then
					return root.Position + v0h * sv
				end
				return root.Position + uIn * (vU * sv)
			end, Mark.assistOK(threat.actor), pingH)
			if type(clr) == "number" and clr >= 0.8 then
				holdDir = uIn
			end
		end
	end
	if Mark.moveSteer then
		Mark.moveSteer(holdDir, "dodge")
	end
	Mark.agentHold(true, "dodge")
	if not Mark.dodgeBoosted then
		Mark.dodgeBoosted = true
		Mark.sprintMod = Mark.sprintMod or require(Modules.Actions.Sprint)
		local ch2 = LocalPlayer.Character
		if ch2 and Mark.sprintMod.SetDodgeBoost then
			local now = Workspace:GetServerTimeNow()
			local want = now + 0.2
			Mark.sprintMod.SetDodgeBoost(ch2, want, 1.08)
			logFile("dodge burst", "0.20", "1.08")
			end
			end
			end

Mark.moveTick = function(character, root)
	local m = Mark.move
	if Mark.walkOff and os.clock() >= Mark.walkOff.untilT then
		Mark.walkOff = nil
		if m and m.mode == "dodge" and not Mark.dodgeAt then
			Mark.moveStop("dodge")
		end
	end
	-- watchdog: a dodge replaced by another mode (moveSteer overwrites m.mode) never ran moveStop("dodge"), leaving
	-- the facing lock on -> stuck facing, backpedal speed, no sprint
	if Mark.dodgeLockOn and (not m or m.mode ~= "dodge") then
		TurnControl.ReleaseAutoRotate("Dribble")
		TurnControl.SetTurnSpeedFactor(1)
		Mark.dodgeLockOn = nil
		Mark.dodgeFaced = nil
		logFile("dodge lock", "released-orphan")
	end
	if Mark.sprintStandOn and not (m and m.mode == "block") then
		Mark.standing = false
		Mark.sprintStand(false) -- the block ended without moveStop (another mode took the steer): give the sprint back
	end
	if not (m and m.mode and root) then
		return
	end
	if not Mark.moveLive(m) then
		logFile("move watchdog", m.mode, "idle", string.format("%.2f", os.clock() - (m.at or 0)))
		Mark.moveStop()
		return
	end
	if m.mode == "dribble" or m.mode == "dodge" or m.mode == "block" or m.mode == "ball" or m.mode == "kick" or m.mode == "air" or (m.mode == "steer" and not m.pts) then
		if m.want or m.dir then
			Mark.moveSteer(m.want or m.dir, m.mode, true)
		end
		return
	end
	if not m.pts then
		return
	end
	local i = m.i or 1
	local nxt = m.pts[math.min(#m.pts, i + 1)]
	if not nxt then
		Mark.moveStop(m.mode)
		return
	end
	local delta = flat(nxt - root.Position)
	if delta.Magnitude < 1.5 then
		if i + 1 >= #m.pts then
			Mark.moveStop(m.mode)
			return
		end
		m.i = i + 1
		nxt = m.pts[m.i + 1]
		delta = nxt and flat(nxt - root.Position) or Vector3.zero
	end
	local dir = delta.Magnitude > 0.15 and delta.Unit or Vector3.zero
	if m.mode == "walk" or m.mode == "take" then
		Mark.agentHold(true)
	end
	local ahead = root.Position + dir * 3.2
	local up = Vector3.new(0, 5.5, 0)
	local hum = character:FindFirstChildOfClass("Humanoid")
	local probe = false
	if dir.Magnitude > 0.2 and hum and os.clock() - (Mark.agentJump or 0) > 0.9 and os.clock() - (Mark.wallProbeAt or 0) > 0.08 then
		Mark.wallProbeAt = os.clock() -- two box sweeps over every barricade part: 12 times a second is plenty
		probe = wallBlocks(root.Position, ahead) and not wallBlocks(root.Position + up, ahead + up)
	end
	if probe and CharacterControllers.IsLanded(character, hum) then
		Mark.mover = Mark.mover or require(Modules.Actions.ActionMovement)
		if CharacterControllers.RequestJump(character, hum, Mark.mover.GetBaseJumpHeight(character)) then
			Mark.agentJump = os.clock()
		end
	end
	Mark.moveSteer(dir, m.mode)
end

Mark.agentPalette = {
	route = { Color3.fromRGB(235, 240, 255), Color3.fromRGB(120, 210, 255), Color3.fromRGB(170, 150, 255) },
	dodge = { Color3.fromRGB(90, 200, 255), Color3.fromRGB(80, 255, 220), Color3.fromRGB(150, 120, 255) },
	dribble = { Color3.fromRGB(255, 190, 70), Color3.fromRGB(255, 110, 150), Color3.fromRGB(255, 240, 140) },
}
-- What is left of an agent route: the passed part is eaten. The route is anchored in the world (moveTick advances m.i as
-- points are passed, but the whole m.pts used to be drawn: passed points stayed on screen and the line kept pointing
-- through them). Start = our projection on the furthest segment we are on; nil once the destination is behind us.
Mark.routeRemain = function(chain, pos, i0)
	local n = #chain
	local j = math.clamp(i0 or 1, 1, n - 1)
	local P = flat(pos)
	local bestK, bestD, bestU = j, math.huge, 0
	for k = j, n - 1 do
		local a, b = flat(chain[k]), flat(chain[k + 1])
		local ab = b - a
		local L2 = ab:Dot(ab)
		local u = L2 > 1e-6 and (P - a):Dot(ab) / L2 or 1
		local dd = (P - (a + ab * math.clamp(u, 0, 1))).Magnitude
		if dd <= bestD + 0.05 then -- ties go to the later segment
			bestK, bestD, bestU = k, dd, u
		end
	end
	if bestK == n - 1 and bestU >= 1 then
		return nil -- the destination is behind us
	end
	local out = { pos }
	for q = bestK + 1, n do
		out[#out + 1] = chain[q]
	end
	return out
end
Mark.drawRoute = function(root, gy)
	Mark.agentLines = Mark.agentLines or makeLines(200, 1.4, 42)
	Mark.agentPool = Mark.agentPool or Mark.segPool(Mark.agentLines)
	Mark.agentPool.finish()
	hideLines(Mark.route)
	hideLines(Mark.pathInk)
	hideLines(Mark.stake)
	hideLines(Mark.ticks)
	if Mark.routeSight then
		for i = 1, #Mark.routeSight do
			Mark.routeSight[i].Visible = false
		end
	end
	Mark.needle.Visible = false
	Mark.flag.Visible = false
	Mark.spur.Visible = false
	if Mark.aimLip then
		hideLines(Mark.aimLip)
	end
	if Mark.lockRing then
		hideLines(Mark.lockRing)
	end
	local sightP = Mark.sightP
	Mark.sightP = nil
	local m = Mark.move
	if CFG.DrawRoute == false or not (m and m.pts and #m.pts >= 2 and root) or not Mark.moveLive(m) then
		return
	end
	local chain = Mark.routeRemain(m.pts, root.Position, m.i)
	if not chain or #chain < 2 then
		return
	end
	local y = gy + 0.06
	local col = m.mode == "dodge" and COL.Dodge or (m.mode == "dribble" and COL.Tackle or COL.Line)
	local total = 0
	for i = 2, #chain do
		total = total + flat(chain[i] - chain[i - 1]).Magnitude
	end
	if total < 0.4 then
		return
	end
	local keyP = (m.mode == "dodge" and "dodge") or (m.mode == "dribble" and "dribble") or "route"
	Mark.agentPath(Mark.agentPool.seg, chain, y, CFG.AgentPathStyle, keyP, os.clock(), col)
	local destP = chain[#chain]
	Mark.routeInk = col
	if sightP and flat(destP - sightP).Magnitude <= 3 then
		-- agent spot and tackle sight agree: keep the tackle sight, ring it with the route colour (one locked mark)
		Mark.lockRing = Mark.lockRing or makeLines(10, 1.6, 43)
		local reel = Mark.stepReel()
		local mid = (destP + sightP) * 0.5
		local r = 2.35 + reel.fastRoll * 0.06
		for i = 1, #Mark.lockRing do
			local a0 = reel.drumAng * 0.25 + (i - 1) / #Mark.lockRing * math.pi * 2
			local a1 = a0 + math.pi * 2 / #Mark.lockRing * 0.55
			Mark.lockRing[i].Thickness = 1.9
			applyLine(Mark.lockRing[i], Vector3.new(mid.X + math.cos(a0) * r, y, mid.Z + math.sin(a0) * r), Vector3.new(mid.X + math.cos(a1) * r, y, mid.Z + math.sin(a1) * r), col, 1)
		end
		Mark.agentPool.finish() -- the path above already used pool lines; without this they stayed lit next frame
		return
	end
	local key = (m.mode == "dodge" and "dodge") or (m.mode == "dribble" and "dribble") or "route"
	Mark.agentSpot(Mark.agentPool.seg, Vector3.new(destP.X, y, destP.Z), CFG.AgentSpotStyle, key, os.clock())
	Mark.agentPool.finish()
end

-- ===== new-look art ======================================================================
-- Rendering model (rewritten for cost): every shape projects its vertices ONCE (pen.P = one WorldToViewportPoint),
-- then every layer (glow / core / fill) is written from those 2D points through pen.L / pen.T. Lines go straight
-- to the Drawing object with per-property change checks, gradient colours come from a 48-step LUT (no Color3:Lerp
-- per segment), alpha is quantised to 1/24 so unchanged segments cost nothing. Ring / arc resolution follows the
-- on-screen radius (LOD). Live drawing goes through the pen.
Mark.artInit = function()
	local floor, clamp, cos, sin, abs, pi = math.floor, math.clamp, math.cos, math.sin, math.abs, math.pi
	local V2 = Vector2.new

	Mark.artPal = {
		hi = { Color3.fromRGB(90, 212, 255), Color3.fromRGB(160, 132, 255), Color3.fromRGB(110, 255, 232) },
		lo = { Color3.fromRGB(110, 255, 226), Color3.fromRGB(80, 200, 255), Color3.fromRGB(196, 242, 255) },
		curl = { Color3.fromRGB(190, 122, 255), Color3.fromRGB(255, 112, 204), Color3.fromRGB(110, 204, 255) },
		live = { Color3.fromRGB(235, 245, 255), Color3.fromRGB(120, 216, 255), Color3.fromRGB(170, 152, 255) },
		srv = { Color3.fromRGB(255, 192, 92), Color3.fromRGB(255, 122, 162), Color3.fromRGB(255, 228, 144) },
		hot = { Color3.fromRGB(255, 108, 92), Color3.fromRGB(255, 192, 72), Color3.fromRGB(255, 240, 164) },
		lime = { Color3.fromRGB(150, 255, 40), Color3.fromRGB(70, 255, 130), Color3.fromRGB(226, 255, 96) },
		limeWarn = { Color3.fromRGB(255, 214, 60), Color3.fromRGB(190, 255, 70), Color3.fromRGB(255, 238, 140) },
	}
	Mark.artGrad = function(pal, f)
		f = f % 1
		local k = f * 3
		local i = floor(k)
		local u = k - i
		u = u * u * (3 - 2 * u)
		return pal[i % 3 + 1]:Lerp(pal[(i + 1) % 3 + 1], u)
	end
	local lutCache = setmetatable({}, { __mode = "k" })
	local function artCol(pal, f)
		local l = lutCache[pal]
		if not l then
			l = {}
			for i = 0, 47 do
				l[i + 1] = Mark.artGrad(pal, i / 48)
			end
			lutCache[pal] = l
		end
		return l[floor((f % 1) * 48) + 1]
	end
	local WHITE = Color3.fromRGB(255, 255, 255)
	local INK = Color3.fromRGB(8, 10, 22)

	-- pen: nextLine() -> Line proxy or nil, nextTri(layer) -> Triangle proxy or nil
	Mark.makePen = function(nextLine, nextTri)
		local pen = {}
		pen.P = function(p)
			local v = (Mark.frameCam or Workspace.CurrentCamera):WorldToViewportPoint(p)
			return v.X, v.Y, v.Z
		end
		pen.L = function(x0, y0, d0, x1, y1, d1, col, alpha, thick, z)
			if d0 < 0.15 or d1 < 0.15 then
				return
			end
			local ln = nextLine()
			if not ln then
				return
			end
			local c, r = ln._c, ln._r
			local f, t = V2(x0, y0), V2(x1, y1)
			if c.From ~= f then
				r.From = f
				c.From = f
			end
			if c.To ~= t then
				r.To = t
				c.To = t
			end
			if c.Color ~= col then
				r.Color = col
				c.Color = col
			end
			alpha = floor(alpha * 24 + 0.5) / 24
			if c.Transparency ~= alpha then
				r.Transparency = alpha
				c.Transparency = alpha
			end
			if c.Thickness ~= thick then
				r.Thickness = thick
				c.Thickness = thick
			end
			if c.ZIndex ~= z then
				r.ZIndex = z
				c.ZIndex = z
			end
			if c.Visible ~= true then
				r.Visible = true
				c.Visible = true
			end
		end
		pen.T = function(layer, x0, y0, d0, x1, y1, d1, x2, y2, d2, col, alpha)
			if d0 < 0.15 or d1 < 0.15 or d2 < 0.15 then
				return
			end
			local tri = nextTri(layer)
			if not tri then
				return
			end
			local c, r = tri._c, tri._r
			local a, b, cc = V2(x0, y0), V2(x1, y1), V2(x2, y2)
			if c.PointA ~= a then
				r.PointA = a
				c.PointA = a
			end
			if c.PointB ~= b then
				r.PointB = b
				c.PointB = b
			end
			if c.PointC ~= cc then
				r.PointC = cc
				c.PointC = cc
			end
			if c.Color ~= col then
				r.Color = col
				c.Color = col
			end
			alpha = floor(alpha * 24 + 0.5) / 24
			if c.Transparency ~= alpha then
				r.Transparency = alpha
				c.Transparency = alpha
			end
			if c.Visible ~= true then
				r.Visible = true
				c.Visible = true
			end
		end
		return pen
	end

	-- live pen over a dedicated pool; high-water marks keep the per-frame hide pass proportional to what changed
	local lines = makeLines(520, 1.4, 42)
	local tris = {}
	for n = 1, 48 do
		tris[n] = newTri(n <= 24 and 37 or 38)
	end
	local lineI, lineHi = 1, 0
	local triI, triHi = { 1, 25 }, { 0, 24 }
	Mark.pen = Mark.makePen(function()
		local ln = lines[lineI]
		if ln then
			lineI += 1
		else
			Mark.penFull = "lines"
		end
		return ln
	end, function(layer)
		layer = layer or 1
		local i = triI[layer]
		if i > (layer == 1 and 24 or 48) then
			Mark.penFull = "tris" .. layer
			return nil
		end
		triI[layer] = i + 1
		return tris[i]
	end)
	Mark.artFinish = function()
		if Mark.penFull then
			if os.clock() - (Mark.penFullAt or -10) > 5 then
				Mark.penFullAt = os.clock()
				logFile("pen", "pool exhausted", Mark.penFull, "lines", #lines)
			end
			Mark.penFull = nil
		end
		for n = lineI, lineHi do
			lines[n].Visible = false
		end
		lineHi = lineI - 1
		lineI = 1
		for layer = 1, 2 do
			for n = triI[layer], triHi[layer] do
				tris[n].Visible = false
			end
			triHi[layer] = triI[layer] - 1
		end
		triI[1], triI[2] = 1, 25
	end
	Mark.artHide = function()
		Mark.artFinish()
		for n = 1, lineHi do
			lines[n].Visible = false
		end
		lineHi = 0
	end

	-- ring LOD: segments follow the on-screen radius (about 11 px per chord), clamped
	local function ringN(center, r, maxN)
		local fp = Mark.framePos
		if not fp then
			return maxN
		end
		local dist = math.max((center - fp).Magnitude, 1)
		local cap = ((Mark.dtAvg or 0) > 1 / 28) and math.min(maxN, 16) or maxN
		return clamp(floor(r * (Mark.framePxK or 700) / dist * 0.55), 10, cap)
	end
	-- scratch arrays (no allocation per frame)
	local RX, RY, RD = {}, {}, {}
	local function ringProject(pen, c, axA, axB, r, N, a0)
		for s = 0, N do
			local a = a0 + s / N * pi * 2
			RX[s], RY[s], RD[s] = pen.P(c + axA * (cos(a) * r) + axB * (sin(a) * r))
		end
	end

	-- Corner frame in an arbitrary plane (the agent-spot look): four squircle arcs, glow + gradient core, a faint
	-- filled quad behind, centre cross; never smaller than ~22 px on screen so it stays readable at 100+ studs.
	local QX, QY, QD = {}, {}, {}
	local CX, CY, CD = {}, {}, {}
	Mark.cornerFrame = function(pen, center, axA, axB, R0, pal, t, spinRate, fillAlpha, k, minPx, maxPx)
		k = k or 1
		local fp = Mark.framePos
		local R = R0
		if fp then
			local dd = math.max((center - fp).Magnitude, 1)
			local K = Mark.framePxK or 700
			R = math.max(R0, (minPx or 22) * dd / K)
			-- screen-size ceiling: R0 is in studs, so a close mark grew without limit (1.15 studs at 10 studs = ~80 px)
			if maxPx then
				R = math.min(R, maxPx * dd / K)
			end
		end
		R = R * (1 + 0.08 * sin(t * pi * 2 / 1.2))
		local spin = t * (spinRate or 0.9)
		local cs, sn = cos(spin), sin(spin)
		local span = math.rad(52)
		for q = 0, 3 do
			for s = 0, 4 do
				local a = pi / 4 + q * pi / 2 - span * 0.5 + span * s / 4
				local c, sg = cos(a), sin(a)
				local x = (c >= 0 and 1 or -1) * abs(c) ^ 0.5 * R
				local z = (sg >= 0 and 1 or -1) * abs(sg) ^ 0.5 * R
				QX[s], QY[s], QD[s] = pen.P(center + axA * (x * cs - z * sn) + axB * (x * sn + z * cs))
			end
			for s = 1, 4 do
				pen.L(QX[s - 1], QY[s - 1], QD[s - 1], QX[s], QY[s], QD[s], artCol(pal, q / 4 + s / 4 * 0.25 + t * 0.35), k, 1.6 + k, 43)
			end
			pen.L(QX[0], QY[0], QD[0], QX[2], QY[2], QD[2], pal[1], 0.26 * k * k, 4 + 4 * k, 41)
			pen.L(QX[2], QY[2], QD[2], QX[4], QY[4], QD[4], pal[1], 0.26 * k * k, 4 + 4 * k, 41)
			CX[q], CY[q], CD[q] = QX[2], QY[2], QD[2]
		end
		if fillAlpha and fillAlpha > 0 then
			pen.T(1, CX[0], CY[0], CD[0], CX[1], CY[1], CD[1], CX[2], CY[2], CD[2], pal[1], fillAlpha)
			pen.T(1, CX[0], CY[0], CD[0], CX[2], CY[2], CD[2], CX[3], CY[3], CD[3], pal[1], fillAlpha)
		end
		local mx, my, md = pen.P(center)
		local cr = clamp((R * (Mark.framePxK or 700) / math.max(md or 1, 1)) * 0.4, 1.5, 4)
		pen.L(mx - cr, my, md, mx + cr, my, md, WHITE, 0.9 * k, 1.8, 44)
		pen.L(mx, my - cr, md, mx, my + cr, md, WHITE, 0.9 * k, 1.8, 44)
	end

	-- TRAJECTORY "aurora". Glow + core ribbon in a flowing 3-colour gradient (core never dimmer than 0.8), a comet
	-- with a bright tail running the shot, tick beads, a dashed ground shadow, a small arrow at the START that
	-- points BACK toward the shooter, and a corner-frame landing mark on the goal plane. shift (Vector3) moves the
	-- start with the player while the landing stays put (the aim is re-based every frame while we move).
	local VX, VY, VD = {}, {}, {}
	local TLEN = {}
	local SX, SY, SD = {}, {}, {}
	Mark.trajArt = function(pen, pts, times, land, along, gy, kind, t, shift)
		local n = #pts
		if n < 2 then
			return
		end
		local pal = Mark.artPal[kind] or Mark.artPal.hi
		-- the preview keeps sampling past the goal plane: cut the ribbon at the vertex nearest the landing mark
		if typeof(land) == "Vector3" then
			local cut, best = n, math.huge
			for i = 2, n do
				local dd = (pts[i] - land).Magnitude
				if dd < best then
					best, cut = dd, i
				end
			end
			if best < 4 then
				n = cut
			end
		end
		local lens, total = TLEN, 0
		lens[1] = 0
		for i = 2, n do
			total += (pts[i] - pts[i - 1]).Magnitude
			lens[i] = total
		end
		if total < 1 then
			return
		end
		local steps = clamp(floor(total / 3), 12, 32)
		local idx = 1
		for k = 0, steps do
			local d = total * k / steps
			while idx < n - 1 and lens[idx + 1] < d do
				idx += 1
			end
			local s = lens[idx + 1] - lens[idx]
			local u = s > 1e-4 and clamp((d - lens[idx]) / s, 0, 1) or 0
			local p = pts[idx]:Lerp(pts[idx + 1], u)
			if shift then
				p = p + shift * (1 - k / steps)
			end
			VX[k], VY[k], VD[k] = pen.P(p)
			if k % 2 == 0 then
				SX[k], SY[k], SD[k] = pen.P(Vector3.new(p.X, gy + 0.08, p.Z))
			end
		end
		local dur = math.max(times and times[#times] or 1, 0.45)
		local head = (t / dur) % 1.3
		local hf = math.min(head, 1)
		for k = 1, steps do
			local f = k / steps
			local behind = hf - f + 0.5 / steps
			local tail = (behind >= 0 and behind < 0.3) and (1 - behind / 0.3) or 0
			local col = artCol(pal, f * 0.8 - t * 0.25)
			pen.L(VX[k - 1], VY[k - 1], VD[k - 1], VX[k], VY[k], VD[k], col, 0.8 + 0.2 * tail, 2.1 + 1.7 * tail, 42)
			if k % 2 == 0 or tail > 0 then
				pen.L(VX[k - 1], VY[k - 1], VD[k - 1], VX[k], VY[k], VD[k], col, 0.18 + 0.24 * tail, 7.5, 41)
			end
			if k % 4 == 0 then
				pen.L(SX[k - 2], SY[k - 2], SD[k - 2], SX[k], SY[k], SD[k], col, 0.3, 1.2, 41)
			end
		end
		-- comet
		if head <= 1.02 then
			local function xyAt(hv)
				hv = clamp(hv, 0, steps)
				local k0 = floor(hv)
				local k1 = math.min(k0 + 1, steps)
				local u = hv - k0
				return VX[k0] + (VX[k1] - VX[k0]) * u, VY[k0] + (VY[k1] - VY[k0]) * u, VD[k0] + (VD[k1] - VD[k0]) * u
			end
			local hv = hf * steps
			local hx, hy, hd = xyAt(hv)
			local tx, ty, td = xyAt(hv - 0.9)
			local ux, uy, ud = xyAt(hv - 2.4)
			pen.L(tx, ty, td, hx, hy, hd, WHITE, 1, 4, 44)
			pen.L(ux, uy, ud, tx, ty, td, WHITE, 0.7, 2.6, 43)
			pen.L(tx, ty, td, hx, hy, hd, pal[1], 0.35, 9, 41)
		end
		-- start arrow: a thin chevron LYING IN THE WORLD (horizontal plane at the ball), tip pointing back toward the
		-- shooter, so it has perspective like everything else instead of facing the camera
		do
			local p0 = pts[1]
			if shift then
				p0 = p0 + shift
			end
			local fwdv = Vector3.new(pts[2].X - pts[1].X, 0, pts[2].Z - pts[1].Z)
			if fwdv.Magnitude < 0.05 then
				fwdv = Vector3.new(pts[n].X - pts[1].X, 0, pts[n].Z - pts[1].Z)
			end
			if fwdv.Magnitude > 0.05 then
				fwdv = fwdv.Unit
				local sidev = Vector3.new(-fwdv.Z, 0, fwdv.X)
				local tipx, tipy, tipd = pen.P(p0 - fwdv * 0.5)
				local w1x, w1y, w1d = pen.P(p0 + fwdv * 0.1 + sidev * 0.32)
				local w2x, w2y, w2d = pen.P(p0 + fwdv * 0.1 - sidev * 0.32)
				pen.L(tipx, tipy, tipd, w1x, w1y, w1d, pal[1], 0.7, 1.5, 43)
				pen.L(tipx, tipy, tipd, w2x, w2y, w2d, pal[1], 0.7, 1.5, 43)
				pen.L(tipx, tipy, tipd, w1x, w1y, w1d, pal[1], 0.12, 4.5, 41)
				pen.L(tipx, tipy, tipd, w2x, w2y, w2d, pal[1], 0.12, 4.5, 41)
			end
		end
		-- landing: corner frame on the goal plane + a drop line to the ground
		if typeof(land) == "Vector3" then
			local ax = (along and along.Magnitude > 0.5) and along.Unit or Vector3.new(1, 0, 0)
			if kind == "lime" or kind == "limeWarn" then
				Mark.cornerFrame(pen, land, ax, Vector3.new(0, 1, 0), 0.5, pal, t, 0.7, 0.06, 0.72, 10, 14)
			else
				Mark.cornerFrame(pen, land, ax, Vector3.new(0, 1, 0), 1.0, pal, t, 0.7, 0.1, 0.72, 15)
			end
			local lx, ly, ld = pen.P(land)
			local fx, fy, fd2 = pen.P(Vector3.new(land.X, gy + 0.08, land.Z))
			pen.L(lx, ly, ld, fx, fy, fd2, pal[1], 0.4, 1.4, 41)
		end
	end

	-- POSITIONS "phantom". FIELD PLAYER: a puzzle pair of circles. SERVER = amber ring with a flowing gradient, glow
	-- and a faint fill; LIVE = plain white ring with a glow, just inside it; when they agree the server ring hugs
	-- the live one. A running tether links them when they drift apart. GOALKEEPER: breathing corner frame at the
	-- server position + live chevron + tether.
	Mark.posArt = function(pen, live, ghost, dir, gy, isKeeper, t)
		local y = gy + 0.06
		local l = Vector3.new(live.X, y, live.Z)
		local g = Vector3.new(ghost.X, y, ghost.Z)
		local fd = (dir and dir.Magnitude > 0.05) and Vector3.new(dir.X, 0, dir.Z).Unit or Vector3.new(0, 0, 1)
		local right = Vector3.new(-fd.Z, 0, fd.X)
		local srv, lv = Mark.artPal.srv, Mark.artPal.live
		if isKeeper then
			local h = 2.5 * (1 + 0.04 * sin(t * pi * 2 / 1.4))
			for sx = -1, 1, 2 do
				for sz = -1, 1, 2 do
					local c = g + right * (sx * h) + fd * (sz * h)
					local ax, ay, ad = pen.P(c)
					local bx, by, bd = pen.P(c - right * (sx * 1.2))
					local cx, cy, cd = pen.P(c - fd * (sz * 1.2))
					local col = artCol(srv, (sx + sz) * 0.12 + t * 0.3)
					pen.L(ax, ay, ad, bx, by, bd, col, 1, 2.2, 43)
					pen.L(ax, ay, ad, cx, cy, cd, col, 1, 2.2, 43)
					pen.L(ax, ay, ad, bx, by, bd, col, 0.2, 7, 41)
					pen.L(ax, ay, ad, cx, cy, cd, col, 0.2, 7, 41)
				end
			end
			local gx, gy2, gd = pen.P(g)
			pen.L(gx - 6, gy2, gd, gx + 6, gy2, gd, srv[1], 0.85, 1.8, 43)
			pen.L(gx, gy2 - 6, gd, gx, gy2 + 6, gd, srv[1], 0.85, 1.8, 43)
			local tip = l + fd * 1.0
			local tx, ty, td = pen.P(tip)
			local ax, ay, ad = pen.P(l - fd * 0.3 - right * 0.62)
			local bx, by, bd = pen.P(l - fd * 0.3 + right * 0.62)
			pen.L(ax, ay, ad, tx, ty, td, lv[1], 1, 2.2, 44)
			pen.L(tx, ty, td, bx, by, bd, lv[1], 1, 2.2, 44)
			pen.L(ax, ay, ad, tx, ty, td, lv[2], 0.25, 7, 41)
			pen.L(tx, ty, td, bx, by, bd, lv[2], 0.25, 7, 41)
		else
			local R = 1.0
			local apart = (g - l).Magnitude
			local lock = apart < 0.15 and (0.5 + 0.5 * sin(t * 6)) or 0
			local ex, ez = Vector3.new(1, 0, 0), Vector3.new(0, 0, 1)
			local N = ringN(g, R + 0.12, 28)
			N = N - N % 2
			-- server ring: faint fill (fan over every second ring vertex) + gradient core + glow
			local rs = R + 0.12
			ringProject(pen, g, ex, ez, rs, N, 0)
			local cx, cy, cd = pen.P(g)
			for s = 0, N - 2, 2 do
				pen.T(1, cx, cy, cd, RX[s], RY[s], RD[s], RX[s + 2], RY[s + 2], RD[s + 2], srv[1], 0.2)
			end
			for s = 1, N do
				local col = artCol(srv, s / N - t * 0.4)
				pen.L(RX[s - 1], RY[s - 1], RD[s - 1], RX[s], RY[s], RD[s], col, 0.95, 2.1 + 1.2 * lock, 43)
				if s % 2 == 0 then
					pen.L(RX[s - 2], RY[s - 2], RD[s - 2], RX[s], RY[s], RD[s], col, 0.22, 6.5, 41)
				end
			end
			-- live ring: plain white + glow
			local glowK = 0.85 + 0.15 * sin(t * 3)
			ringProject(pen, l, ex, ez, R, N, 0)
			for s = 1, N do
				pen.L(RX[s - 1], RY[s - 1], RD[s - 1], RX[s], RY[s], RD[s], WHITE, 1, 2, 44)
				if s % 2 == 0 then
					pen.L(RX[s - 2], RY[s - 2], RD[s - 2], RX[s], RY[s], RD[s], lv[2], 0.28 * glowK, 6.5, 41)
				end
			end
		end
		-- tether live -> server (edge to edge), dashes interpolated in screen space
		local d = g - l
		local m = d.Magnitude
		if m > 0.25 then
			local u = d / m
			local from = isKeeper and l or (l + u * 1.0)
			local to = isKeeper and g or (g - u * 1.12)
			if (to - from):Dot(u) > 0.1 then
				local x0, y0, d0 = pen.P(from)
				local x1, y1, d1 = pen.P(to)
				for k = 0, 5 do
					local f0 = (k + (t * 2.2) % 1) / 6
					local f1 = f0 + 0.5 / 6
					if f1 <= 1 then
						pen.L(x0 + (x1 - x0) * f0, y0 + (y1 - y0) * f0, d0 + (d1 - d0) * f0, x0 + (x1 - x0) * f1, y0 + (y1 - y0) * f1, d0 + (d1 - d0) * f1, artCol(srv, f0), 0.9, 1.6, 43)
					end
				end
			end
		end
	end

	-- TACKLE SIGHT. Three arcs like the SilentAim target ring, spinning fast, four filled arrows on the outer edge
	-- turning with them, and the slide-direction arrow when we have one. No dashed inner ring, no centre diamond.
	-- Scale barely grows with distance. Alpha stays full once shown: resetting the fade on every jitter of the
	-- slide point was the flicker.
	Mark.sightArt = function(pen, p, gy, hot, aim, t, bornOverride)
		-- fade only on a real retarget. Resetting on a 1.8-stud jitter of the slide point dropped alpha to 0
		-- every few frames (the flicker). Live stays full.
		local st = Mark.sightState
		if not st or (st.pos - p).Magnitude > 14 then
			st = { born = t, pos = p, last = t, ang = 0, vel = 5.6, dir = 1, flipAt = t + 1.2, n = 0 }
			Mark.sightState = st
		end
		local dtS = clamp(t - st.last, 0, 0.05)
		st.last, st.pos = t, p
		-- spin that reverses: the target speed flips sign every ~0.9-2 s and the real speed eases through zero
		if t >= st.flipAt then
			st.dir = -st.dir
			st.n += 1
			st.flipAt = t + 0.9 + (st.n * 0.37) % 1.1
		end
		st.vel += (st.dir * 5.6 - st.vel) * math.min(1, dtS * 6)
		st.ang += st.vel * dtS
		local e = bornOverride and clamp((t - bornOverride) / 0.2, 0, 1) or 1
		local pal = hot and Mark.artPal.hot or Mark.artPal.hi
		local spin = st.ang
		local c = Vector3.new(p.X, gy + 0.07, p.Z)
		local fp = Mark.framePos
		local sc = 1
		if fp then
			sc = clamp(1 + math.max((c - fp).Magnitude - 12, 0) / 220, 1, 1.12)
		end
		local R = 1.45 * sc
		-- three arcs, SilentAim target language (gap between them), ink under-stroke so it reads on the pitch
		for arc = 0, 2 do
			local a0 = spin + arc * (pi * 2 / 3)
			local px0, py0, pd0 = nil, nil, nil
			for s = 0, 5 do
				local ang = a0 + s / 5 * (pi * 2 / 3 * 0.72)
				local x, y, d = pen.P(c + Vector3.new(cos(ang) * R, 0, sin(ang) * R))
				if s > 0 then
					local col = artCol(pal, arc / 3 + spin / (pi * 2))
					pen.L(px0, py0, pd0, x, y, d, INK, 0.4 * e, 4.4, 40)
					pen.L(px0, py0, pd0, x, y, d, col, 0.16 * e, 7.2, 41)
					pen.L(px0, py0, pd0, x, y, d, col, e, 2.2, 44)
				end
				px0, py0, pd0 = x, y, d
			end
		end
		-- four filled arrows on the OUTER edge of the ring, pointing outward, turning with the drum
		for q = 0, 3 do
			local a = spin + q * pi / 2
			local ca, sa = cos(a), sin(a)
			local tipR, baseR, half = R * 1.5, R * 1.05, R * 0.17
			local ox, oz = ca, sa
			local px, pz = -sa, ca
			local tx, ty, td = pen.P(c + Vector3.new(ox * tipR, 0, oz * tipR))
			local w1x, w1y, w1d = pen.P(c + Vector3.new(ox * baseR + px * half, 0, oz * baseR + pz * half))
			local w2x, w2y, w2d = pen.P(c + Vector3.new(ox * baseR - px * half, 0, oz * baseR - pz * half))
			local col = artCol(pal, q / 4 + t * 0.2)
			pen.T(2, tx, ty, td, w1x, w1y, w1d, w2x, w2y, w2d, col, e)
			-- outline: dark under-stroke + glow + bright edge on all three sides
			pen.L(tx, ty, td, w1x, w1y, w1d, INK, 0.5 * e, 4.4, 40)
			pen.L(tx, ty, td, w2x, w2y, w2d, INK, 0.5 * e, 4.4, 40)
			pen.L(w1x, w1y, w1d, w2x, w2y, w2d, INK, 0.5 * e, 4.4, 40)
			pen.L(tx, ty, td, w1x, w1y, w1d, col, 0.3 * e, 7.5, 41)
			pen.L(tx, ty, td, w2x, w2y, w2d, col, 0.3 * e, 7.5, 41)
			pen.L(tx, ty, td, w1x, w1y, w1d, WHITE, 0.9 * e, 1.6, 44)
			pen.L(tx, ty, td, w2x, w2y, w2d, WHITE, 0.9 * e, 1.6, 44)
			pen.L(w1x, w1y, w1d, w2x, w2y, w2d, WHITE, 0.7 * e, 1.4, 44)
		end
		if typeof(aim) == "Vector3" and Vector3.new(aim.X, 0, aim.Z).Magnitude > 0.05 then
			local d = Vector3.new(aim.X, 0, aim.Z).Unit
			local r = Vector3.new(-d.Z, 0, d.X)
			local a = c + d * (R * 1.75)
			local b = c + d * (R * 1.75 + 1.8 * sc)
			local ax, ay, ad = pen.P(a)
			local bx, by, bd = pen.P(b)
			local h1x, h1y, h1d = pen.P(b - d * 0.55 * sc + r * 0.4 * sc)
			local h2x, h2y, h2d = pen.P(b - d * 0.55 * sc - r * 0.4 * sc)
			pen.L(ax, ay, ad, bx, by, bd, INK, 0.45 * e, 4.6, 40)
			pen.L(bx, by, bd, h1x, h1y, h1d, INK, 0.45 * e, 4.6, 40)
			pen.L(bx, by, bd, h2x, h2y, h2d, INK, 0.45 * e, 4.6, 40)
			pen.L(ax, ay, ad, bx, by, bd, pal[1], 1, 2.2, 43)
			pen.L(bx, by, bd, h1x, h1y, h1d, pal[1], 1, 2.2, 43)
			pen.L(bx, by, bd, h2x, h2y, h2d, pal[1], 1, 2.2, 43)
			local f = (t * 1.6) % 1
			local f2 = math.min(f + 0.12, 1)
			pen.L(ax + (bx - ax) * f, ay + (by - ay) * f, ad + (bd - ad) * f, ax + (bx - ax) * f2, ay + (by - ay) * f2, ad + (bd - ad) * f2, WHITE, 1, 3, 44)
		end
	end
end
Mark.artInit()

-- Agent path, same visual language as the corner spot it ends in (palette per mode, ink under-stroke, gradient that
-- flows, short bright pulses running toward the destination). style "flow" (default) or "classic" (the old chalk
-- route: ink + solid mode colour + three paper chevrons). pts are world points, drawn flat at height y.
Mark.agentPath = function(seg, pts, y, style, key, t, classicCol)
	local n = #pts
	if n < 2 then
		return
	end
	local g = {}
	local lens, total = { 0 }, 0
	for i = 1, n do
		g[i] = Vector3.new(pts[i].X, y, pts[i].Z)
		if i > 1 then
			total += (g[i] - g[i - 1]).Magnitude
			lens[i] = total
		end
	end
	if total < 0.4 then
		return
	end
	local function atDist(d)
		d = math.clamp(d, 0, total)
		for i = 2, n do
			if lens[i] >= d then
				local s = lens[i] - lens[i - 1]
				local u = s > 1e-4 and (d - lens[i - 1]) / s or 0
				return g[i - 1]:Lerp(g[i], u), (g[i] - g[i - 1])
			end
		end
		return g[n], g[n] - g[n - 1]
	end
	if style == "classic" then
		local col = classicCol or COL.Line
		local A = CFG.AgentPathAlpha or 0.5
		for i = 1, n - 1 do
			seg(g[i], g[i + 1], COL.Ink, 0.55 * A, 2.2, 41)
			seg(g[i], g[i + 1], col, A, 1.3, 42)
		end
		for k = 1, 3 do
			local p, tang = atDist(total * (0.22 + (k - 1) * 0.28))
			if tang.Magnitude > 0.05 then
				local dir = tang.Unit
				local r = Vector3.new(-dir.Z, 0, dir.X)
				local tip, base = p + dir * 0.65, p - dir * 0.18
				seg(tip, base + r * 0.4, COL.Paper, A, 1.5, 43)
				seg(tip, base - r * 0.4, COL.Paper, A, 1.5, 43)
			end
		end
		return
	end
	local pal = Mark.agentPalette[key] or Mark.agentPalette.route
	local function grad(f)
		f = f % 1
		local k = f * 3
		local i = math.floor(k)
		return pal[i % 3 + 1]:Lerp(pal[(i + 1) % 3 + 1], k - i)
	end
	local ink = Color3.fromRGB(12, 14, 18)
	local pathA = CFG.AgentPathAlpha or 0.5
	-- dock into the corner frame: the path stops at its edge instead of running through the middle
	local dock = total > 3.4 and 2.0 or 0
	local len = total - dock
	-- with the phantom position rings on, the path leaves from the ring edge (live ring r 1.0 / server ring r 1.12)
	-- instead of running through them
	local startTrim = (CFG.PosStyle == "phantom" and len > 3.5) and 1.25 or 0
	local span = len - startTrim
	local steps = math.clamp(math.floor(span / 1.4), 3, 34)
	local flowSpeed = key == "route" and 0.35 or 0.7
	local prev = atDist(startTrim)
	for i = 1, steps do
		local f1 = i / steps
		local p = atDist(startTrim + span * f1)
		local k = f1
		-- brighter and a touch thicker toward the destination, tail fades out behind us
		seg(prev, p, ink, (0.35 + 0.2 * k) * pathA, 2.8, 41)
		seg(prev, p, grad(f1 * 0.9 - t * flowSpeed), (0.3 + 0.65 * k) * pathA, 1.1 + 0.5 * k, 42)
		prev = p
	end
	local hot = Color3.fromRGB(255, 255, 255)
	local period = key == "route" and 1.2 or 0.7
	for q = 0, 2 do
		local f = ((t / period) + q / 3) % 1
		local a0 = atDist(startTrim + span * f)
		local a1 = atDist(startTrim + span * math.min(f + 0.07, 1))
		seg(a0, a1, hot:Lerp(grad(f), 0.35 * f), (1 - f * 0.5) * pathA, 1.8, 44)
	end
end

-- One entry for every agent-spot look (live route).
-- corners: 4 corner arcs of a squircle (superellipse n = 4: a rounded square that almost reads as a circle), each
-- arc a gradient across the palette, ink under-stroke, slow spin, the radius breathes (+-8 %, 1.2 s) and snaps in a
-- little when the destination is fresh. ripple / kick: the water-drop rings, squircle or round.
Mark.agentSpot = function(seg, center, style, key, t)
	local pal = Mark.agentPalette[key] or Mark.agentPalette.route
	if style == "ripple" or style == "kick" then
		local phase = Mark.rippleStep("agent-" .. style, key == "route" and 1 / 0.7 or 1 / 0.5)
		Mark.kickRipple(seg, center, 2.2, pal, phase, t, style == "ripple" and 4 or 2)
		return
	end
	local R = 1.9 * (1 + 0.08 * math.sin(t * math.pi * 2 / 1.2))
	local spin = t * (key == "route" and 0.6 or 1.3)
	local ex = 2 / 4
	local function pt(a)
		local c, s = math.cos(a), math.sin(a)
		return center + Vector3.new((c >= 0 and 1 or -1) * math.abs(c) ^ ex * R, 0, (s >= 0 and 1 or -1) * math.abs(s) ^ ex * R)
	end
	local function grad(f)
		f = f % 1
		local k = f * 3
		local i = math.floor(k)
		local a, b = pal[i % 3 + 1], pal[(i + 1) % 3 + 1]
		return a:Lerp(b, k - i)
	end
	local ink = Color3.fromRGB(12, 14, 18)
	local N = 7
	local span = math.rad(52)
	local rot = CFrame.fromAxisAngle(Vector3.yAxis, -spin) -- one rotation per frame, not one CFrame per point
	for q = 0, 3 do
		local mid = spin + math.pi / 4 + q * math.pi / 2
		local prev = nil
		for s = 0, N do
			local a = mid - span * 0.5 + span * s / N
			local p = pt(a - spin) -- arcs sit on the squircle's corners in its own frame; the whole frame spins
			p = center + rot:VectorToWorldSpace(p - center)
			if prev then
				seg(prev, p, ink, 0.5, 3.4, 42)
				seg(prev, p, grad(q / 4 + s / N * 0.25 + t * 0.35), 0.95, 1.8, 43)
			end
			prev = p
		end
	end
	-- centre pip
	seg(center + Vector3.new(-0.18, 0, 0), center + Vector3.new(0.18, 0, 0), pal[1], 0.9, 2, 43)
	seg(center + Vector3.new(0, 0, -0.18), center + Vector3.new(0, 0, 0.18), pal[1], 0.9, 2, 43)
end

-- ===== VISUAL TEST GALLERY (key P, no UI) ===========================================================================
-- Every new overlay as a station frozen in the world: placed once when P turns it on (14 studs ahead of us, stations
-- along the camera's right), never re-anchored to the character. Each station runs the REAL renderer of its overlay on a
-- scripted loop that walks through its states. P again hides it.
Mark.galToggle = function()
	local G = Mark.gal
	if G and G.on then
		G.on = false
		G.pool.finish()
		for _, tri in G.tris or {} do
			tri.Visible = false
		end
		for _, st in G.st do
			if st.area then
				Mark.areaDraw(nil, 0, nil, true, st.area)
			end
		end
		for _, tx in G.text do
			tx.Visible = false
		end
		return
	end
	local root = ActorTargeting.GetActorRoot(LocalPlayer)
	local cam = Workspace.CurrentCamera
	if not (root and cam) then
		return
	end
	if not G then
		G = { lines = makeLines(900, 1.4, 41), text = {}, st = {} }
		G.pool = Mark.segPool(G.lines)
		Mark.gal = G
	end
	local fw = unitOrNil(flat(cam.CFrame.LookVector)) or Vector3.new(0, 0, -1)
	G.right = Vector3.new(-fw.Z, 0, fw.X)
	G.fw = fw
	G.gy = root.Position.Y - 3.15
	G.O = Vector3.new(root.Position.X, G.gy, root.Position.Z) + fw * 26
	G.t0 = os.clock()
	G.on = true
	for _, st in G.st do
		st.path = nil -- built from the old anchor
	end
	logFile("gallery on", "at", fmtV(G.O))
end

-- stations: x = offset along G.right, art(seg, C, t, st, G) with C the station's ground centre

Mark.galStations = {
	{ name = "Fake aim: spring brackets", x = -30, art = function(seg, C, t, st, G)
		local up = Vector3.new(0, 1, 0)
		local m0 = C + G.fw * 6
		local W, H = 16, 7
		local lb, rb = m0 - G.right * (W / 2), m0 + G.right * (W / 2)
		seg(lb, lb + up * H, COL.Chalk, 0.35, 1, 43)
		seg(rb, rb + up * H, COL.Chalk, 0.35, 1, 43)
		seg(lb + up * H, rb + up * H, COL.Chalk, 0.35, 1, 43)
		local ph = t % 1.6
		if ph < 0.6 then
			local spots = { { -0.75, 0.75 }, { 0.7, 0.25 }, { -0.6, 0.3 } }
			local sp = spots[math.floor(ph / 0.2) + 1]
			local q = m0 + G.right * (sp[1] * W / 2) + up * (sp[2] * H)
			Mark.bracketArt(seg, q, G.right, 1 - ph / 0.6, os.clock(), st)
		else
			st.bq = nil
		end
	end },
	{ name = "Boomerang: ribbon", x = 10, art = function(seg, C, t, st, G)
		local f = G.fw
		local side = Vector3.new(f.Z, 0, -f.X)
		local S = C - f * 14 + Vector3.new(0, 3.5, 0)
		local pts = { S - side * 1.2 - f * 1.5 }
		for i = 0, 22 do
			local th = i / 76 * math.pi * 2
			pts[#pts + 1] = S + f * (30 * math.sin(th)) + side * (-18 * (1 - math.cos(th))) + Vector3.new(0, 1.2 * math.sin(th * 0.5), 0)
		end
		local P = pts[#pts]
		Mark.ribbonArt(seg, pts, Color3.fromRGB(90, 220, 255), os.clock(), Vector3.new(P.X, G.gy, P.Z))
	end },
	{ name = "AutoBox: photo finish", x = 90, art = function(seg, C, t, st, G)
		local f, side = G.fw, G.right
		local k = math.floor(t / 3.2) % 3
		local u = (t % 3.2) / 3.2
		local P = C + f * 8
		local me = C - f * (16 - u * 8) - side * 4
		local rv = { pos = C - f * (4 + 0) + side * 14 - f * u * 10, speed = 16, closing = true }
		rv.eta = (P - rv.pos).Magnitude / 16
		local v = { gy = G.gy, me = me, myV = 16, myEta = (P - me).Magnitude / 16, P = P, R = 3.5, others = { C - f * 20 + side * 18 }, rivals = { rv } }
		if k == 0 then
			rv.pos = C - f * (14 - u * 3) + side * 20 -- far behind: we go
			rv.eta = (P - rv.pos).Magnitude / 16
			v.plan = "go"
		elseif k == 1 then
			rv.pos = C + f * (1 - u * 3) + side * 8 -- nearer than us: skip
			rv.eta = (P - rv.pos).Magnitude / 16
			v.plan = "skip"
			v.who = "rival"
		else
			rv.pos = C + f * 0 + side * 4 + side * 0 -- inside slide reach: stun
			rv.eta = (P - rv.pos).Magnitude / 16
			v.plan = "stun"
			v.who = rv
			v.stunAt = rv.pos + f * 2
			v.me = C - f * 6 - side * 4
			v.myEta = (P - v.me).Magnitude / 16
		end
		Mark.boxArt(seg, v, os.clock())
	end },
	{ name = "Projectile: fuse rail", x = 50, art = function(seg, C, t, st, G)
		local A = C + G.fw * 40 + G.right * 8 + Vector3.new(0, 4, 0)
		local u = (t % 1.4) / 1.1
		local hit = Vector3.new(C.X, G.gy + 0.1, C.Z)
		if u < 1 then
			local pts = {}
			for k = math.floor(u * 20), 20 do
				local s = k / 20
				pts[#pts + 1] = A:Lerp(C + Vector3.new(0, 1, 0), s) + Vector3.new(0, 6 * math.sin(s * math.pi), 0)
			end
			Mark.fuseArt(seg, { pts = pts, hit = hit, frac = 1 - u, speed = 60 }, os.clock())
		else
			local age = (t % 1.4) - 1.1
			local pal = Mark.kickPalette.armed
			local r, prev = 3.2 + age * 14, nil
			for k = 0, 22 do
				local a = k / 22 * math.pi * 2
				local p = hit + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
				if prev then
					seg(prev, p, pal[1], math.max(0, 1 - age / 0.3), 2, 44)
				end
				prev = p
			end
		end
	end },
}

Mark.galDraw = function()
	local G = Mark.gal
	if not (G and G.on) then
		return
	end
	local pool = G.pool
	pool.i = 1
	if not G.tris then
		G.tris = {}
		for k = 1, 64 do
			G.tris[k] = newTri(42)
		end
	end
	G.triN = 0
	local t = os.clock() - G.t0
	local cam = Mark.frameCam or Workspace.CurrentCamera
	for i, s in Mark.galStations do
		local C = G.O + G.right * s.x
		G.st[i] = G.st[i] or {}
		local sti = G.st[i]
		sti.used = 0
		s.art(pool.seg, C, t, sti, G)
		G.triN += sti.used
		local tx = G.text[i]
		if not tx then
			tx = newDraw("Text", 46)
			tx.Size, tx.Center, tx.Outline, tx.Font, tx.Color = 14, true, true, FONT, COL.Paper
			tx.Text = s.name
			G.text[i] = tx
		end
		local p = cam:WorldToViewportPoint(C - G.fw * 16 + Vector3.new(0, 0.2, 0))
		tx.Position = Vector2.new(p.X, p.Y)
		tx.Visible = p.Z > 0.5
	end
	for k = G.triN + 1, #G.tris do
		G.tris[k].Visible = false
	end
	if pool.i > #G.lines and os.clock() - (G.fullAt or 0) > 5 then
		G.fullAt = os.clock()
		logFile("gallery lines full", #G.lines)
	end
	pool.finish()
end

UserInputService.InputBegan:Connect(function(input, gp)
	if not gp and input.KeyCode == Enum.KeyCode.P then
		Mark.galToggle()
	end
	if Controls.IsInput("Kick", input) then
		Mark.realKick = { down = true, at = os.clock(), input = input }
	end
	if Controls.IsInput("RainbowFlick", input) then
		Mark.armFlickWindow()
		if CFG.AutoFlick ~= false then
			Mark.startAerial()
		end
	end
end)
UserInputService.InputEnded:Connect(function(input)
	if Controls.IsInput("Kick", input) then
		Mark.realKick = { down = false, upAt = os.clock(), input = input }
	end
end)

Mark.paInstall()
dbg("boot", "drawing.new", true, "reach", CFG.TackleReach, "track", CFG.TrackStuds, "dribble", "slide-predict", "speed", CFG.TackleSpeed, "dump", "H", "corner", CFG.PreferCornerCurl, "trick", CFG.OnlyTrick)

-- perf probe wrappers: installed last, after every Mark.* function exists
Mark.perfNames = { "tickGk", "tickSkill", "tickHazard", "tickVolley", "tickBlock", "tickBall", "tickBike", "tickAerial", "tickKickDodge", "moveTick", "drawRoute", "drawOil", "drawKickBox", "kickThreat", "saDraw", "homeSlide", "ballPath", "gkOwnDive", "gkDiveSearch", "airSolve", "tickAir", "drawFlight", "drawShadow", "drawScar", "dodgeSteer", "silentArt", "trajArt", "posArt", "sightArt", "passTick", "paDraw", "shieldTick", "gunTick", "gunPushTick", "stateWatch", "chargeWatch", "sprintWatch", "slideAudit", "slideTrackTick", "teleTick", "evadeTick", "tickBox", "drawBox" }
Mark.perfSet(CFG.Perf)

-- ============================================================================================================
-- Syllinse loader contract (loaderv10.lua): the chunk above has already run; the loader calls this with
-- (Lib, Core), then M.start() and M.buildUI(ctx). The UI only READS / WRITES CFG, COL and Mark.artPal (all read
-- live by the script) and calls a few Mark.* actions. No new top-level locals: the chunk sits at Luau's limit.
-- No key is bound by default: every keybind below is created empty.
-- Layout: every function is one card: Enabled + the settings you touch, the rest behind its own "Show Advanced".
-- ============================================================================================================
return function(_Lib, _Core)
	local M = {}

	local FEATURES = {
		"AutoTackle", "AutoDribble", "AutoShoot", "AutoKick", "AutoGK", "AutoWall", "AgentAddon", "AutoDodge",
		"AutoBlock", "AutoBall", "CounterJump", "AirIntercept", "SilentAim", "PassAssist", "ManualTackle", "Draw",
		"Speed", "JumpBoost", "InfStamina", "NoKnockback", "NoRagdoll", "NoStun",
	}

	function M.start() end

	function M.stop()
		for _, k in ipairs(FEATURES) do
			CFG[k] = false
		end
	end

	function M.buildUI(ctx)
		local uiReady = false
		local T = ctx.tabs
		-- while set, every element the helpers create is also collected here (one "Show Advanced" group)
		local cap = nil

		local function notify(title, body)
			if uiReady then
				ctx.notify(title, body)
			end
		end
		local function fl(key)
			return ctx.flag("IS_" .. key)
		end
		local function round(v, p)
			local m = 10 ^ (p or 0)
			return math.floor(v * m + 0.5) / m
		end
		local function keep(el)
			if cap and el then
				cap[#cap + 1] = el
			end
			return el
		end
		-- fresh[sec] = nothing in the card yet: its first header needs no divider, every later one gets one
		local fresh = {}
		local function card(tab, s)
			local sec = tab:Section({ Side = s })
			fresh[sec] = true
			return sec
		end
		-- the first header of a card names its function; every later header is a PART of it and says so ("AutoBall · Rival
		-- Slide"): a function with its own switch gets its own card, so a row is never read as the setting of the wrong one
		local owner = {}
		local function head(sec, name)
			if not fresh[sec] then
				keep(sec:Divider())
			end
			fresh[sec] = false
			local label = name
			if owner[sec] then
				label = owner[sec] .. " · " .. name
			else
				owner[sec] = name
			end
			return keep(sec:Header({ Name = label }))
		end
		local function note(sec, text)
			return keep(sec:SubLabel({ Text = text }))
		end

		-- Enabled switch of a function. Notifies like AutoParry does.
		local function feature(sec, title, key, set)
			return sec:Toggle({
				Name = "Enabled",
				Default = CFG[key] == true,
				Callback = function(v)
					CFG[key] = v and true or false
					if set then
						set(CFG[key])
					end
					notify(title, v and "Enabled" or "Disabled")
				end,
			}, fl(key))
		end

		local function tog(sec, name, key, text, set)
			local el = keep(sec:Toggle({
				Name = name,
				Default = CFG[key] == true,
				Callback = function(v)
					CFG[key] = v and true or false
					if set then
						set(CFG[key])
					end
				end,
			}, fl(key)))
			if text then
				note(sec, text)
			end
			return el
		end

		-- o.scale: the slider shows CFG * scale (percent / ms); o.prec decimals; o.text = one short hint
		local function sld(sec, name, key, mn, mx, o)
			o = o or {}
			local sc = o.scale or 1
			local cur = CFG[key]
			if cur == nil then
				cur = mn / sc
			end
			local el = keep(sec:Slider({
				Name = name,
				Default = math.clamp(round(cur * sc, o.prec or 0), mn, mx),
				Minimum = mn,
				Maximum = mx,
				Precision = o.prec or 0,
				Suffix = o.suffix,
				Callback = function(v)
					CFG[key] = v / sc
					if o.set then
						o.set(CFG[key])
					end
				end,
			}, fl(key)))
			if o.text then
				note(sec, o.text)
			end
			return el
		end

		local function drop(sec, name, key, opts, text)
			local el = keep(sec:Dropdown({
				Name = name,
				Options = opts,
				Default = CFG[key],
				Callback = function(v)
					if type(v) == "string" and v ~= "" then
						CFG[key] = v
					end
				end,
			}, fl(key)))
			if text then
				note(sec, text)
			end
			return el
		end

		-- dropdown with a label per value: list = { { label, value }, ... }; onChange(value) for dependent controls
		local function pick(sec, name, key, list, text, onChange, current)
			local opts, byLabel, def = {}, {}, list[1][1]
			-- `current` given = the control is virtual (no CFG key of its own): onChange does the writing
			local virtual = current ~= nil
			local cur = current
			if cur == nil then
				cur = CFG[key]
			end
			if cur == nil then
				cur = true
			end
			for _, e in ipairs(list) do
				opts[#opts + 1] = e[1]
				byLabel[e[1]] = e[2]
				if e[2] == cur then
					def = e[1]
				end
			end
			local el = keep(sec:Dropdown({
				Name = name,
				Options = opts,
				Default = def,
				Callback = function(v)
					if byLabel[v] ~= nil then
						if not virtual then
							CFG[key] = byLabel[v]
						end
						if onChange then
							onChange(byLabel[v])
						end
					end
				end,
			}, fl(key)))
			if text then
				note(sec, text)
			end
			return el
		end

		-- multi dropdown over { { key, label }, ... } writing { [key] = true } of the UNCHECKED ones into CFG[banKey]
		local function typeList(sec, name, banKey, flag, items, text)
			local keyOf, opts, def = {}, {}, {}
			for _, t in ipairs(items) do
				keyOf[t[2]] = t[1]
				opts[#opts + 1] = t[2]
				if not (CFG[banKey] and CFG[banKey][t[1]]) then
					def[#def + 1] = t[2]
				end
			end
			local el = keep(sec:Dropdown({
				Name = name,
				Options = opts,
				Multi = true,
				Default = def,
				Callback = function(sel)
					local allowed = {}
					if type(sel) == "table" then
						for k, v in pairs(sel) do
							if v == true and keyOf[k] then
								allowed[keyOf[k]] = true
							elseif type(v) == "string" and keyOf[v] then
								allowed[keyOf[v]] = true
							end
						end
					end
					local ban = {}
					for _, t in ipairs(items) do
						if not allowed[t[1]] then
							ban[t[1]] = true
						end
					end
					CFG[banKey] = ban
				end,
			}, fl(flag)))
			if text then
				note(sec, text)
			end
			return el
		end

		-- keybinds are created empty (ctx.keybind passes no Default): nothing is bound until the user does it
		local function bind(sec, name, key, fn)
			return keep(ctx.keybind(sec, { Name = name, Flag = fl(key), Toggle = fn }))
		end

		local function color(sec, name, role)
			return keep(sec:Colorpicker({
				Name = name,
				Default = COL[role],
				Callback = function(c)
					COL[role] = c
				end,
			}, fl("COL_" .. role)))
		end

		-- art palettes: a 48-step LUT is cached per palette TABLE, so a colour change swaps in a new table
		local function palette(sec, kind, names)
			local pal = Mark.artPal and Mark.artPal[kind]
			if not pal then
				return
			end
			for i = 1, 3 do
				keep(sec:Colorpicker({
					Name = names[i],
					Default = pal[i],
					Callback = function(c)
						local old = Mark.artPal[kind]
						local new = { old[1], old[2], old[3] }
						new[i] = c
						Mark.artPal[kind] = new
					end,
				}, fl("PAL_" .. kind .. i)))
			end
		end

		-- Everything built inside fn() sits behind one toggle at the bottom of the card. Hidden controls keep
		-- their value and stay in the config; the toggle itself is saved too, so the card opens as you left it.
		local function advanced(sec, key, fn, label)
			local els, shown = {}, false
			local function apply()
				for _, e in ipairs(els) do
					Mark.try(function()
						e:SetVisibility(shown)
					end)
				end
			end
			keep(sec:Divider())
			sec:Toggle({
				Name = label or "Show Advanced Settings",
				Default = false,
				Callback = function(v)
					shown = v and true or false
					apply()
				end,
			}, fl("ADV_" .. key))
			local outer = cap
			cap = els
			local ok, err = Mark.try(fn)
			cap = outer
			if not ok then
				logFile("ui advanced", key, tostring(err))
			end
			apply()
		end

		local function block(name, fn)
			local ok, err = Mark.try(fn)
			if not ok then
				logFile("ui block failed", name, tostring(err))
			end
		end

		-- ==================================================================================================
		-- AUTOSHOOT
		-- ==================================================================================================
		-- band key -> label. "high" also covers the low-landing high shots the solver relabels "mid".
		local SHOT_TYPES = {
			{ "high", "High" },
			{ "corner", "Corner Curl" },
			{ "trick", "Trick" },
			{ "trickLow", "Dip" },
			{ "dipCorner", "Dip Corner" },
			{ "flat", "Flat" },
			{ "chip", "Lob" },
			{ "bounceHigh", "Bounce High" },
			{ "bounceLow", "Bounce Low" },
			{ "airHigh", "Air High" },
			{ "airLow", "Air Low" },
		}

		block("AutoShoot", function()
			local tab = T.AutoShoot

			-- left column ------------------------------------------------------------------------------------
			local s = card(tab, "Left")
			head(s, "AutoShoot")
			feature(s, "AutoShoot", "AutoShoot")
			tog(s, "Quick Solve", "ShootQuick", "Faster shot search for weak PCs.")
			tog(s, "Learn From Misses", "ShootCalib", "Aims lower after shots that flew over.")
			sld(s, "Max Distance", "ShootMaxDist", 20, 160, { suffix = " st" })
			sld(s, "Keeper Margin", "ShotReachMargin", -0.2, 0.5, { prec = 2, suffix = " s", text = "How late the keeper must be for a shot to count." })
			drop(s, "Shot Curve", "ShotCurve", { "Full", "Light", "Off" }, "How much a shot may bend. Off = straight shots only.")

			local pr = card(tab, "Left")
			head(pr, "AutoShoot · Priority")
			pick(pr, "Try First", "TryFirst", { { "FAKE", "FAKE" }, { "Normal Shot", "NORMAL" }, { "Bounce FAKE", "BOUNCE" } }, "The rest follow it, the normal shot comes last.", function(v)
				CFG.PriorityFAKE = v == "FAKE"
				CFG.PriorityBounceFAKE = v == "BOUNCE"
			end, (CFG.PriorityBounceFAKE and "BOUNCE") or (CFG.PriorityFAKE and "FAKE") or "NORMAL")
			sld(pr, "FAKE Chance", "FakeFirstChance", 0, 100, { scale = 100, suffix = "%", text = "When a teammate is open and FAKE is tried first." })
			tog(pr, "Wait For Keeper Dive", "FakeAfterDiveBan", "No FAKE while the enemy keeper's dive is on cooldown.")
			tog(pr, "Shoot After Bounce FAKE", "FakeOnceThenShoot", "After one worked, no fakes until the ball is lost.")

			-- Feint: the controls that do not apply to the chosen mode are hidden
			local fe = card(tab, "Left")
			head(fe, "Feint")
			local chanceEl, countEl, atEl, atNote, skipEl, smartEl, smartNote, compEl
			local function feintVis(mode)
				mode = mode or CFG.FeintMode or "Off"
				local rows = { { chanceEl, mode == "Chance" }, { countEl, mode == "Count" }, { atEl, mode ~= "Off" }, { skipEl, mode ~= "Off" }, { smartEl, mode ~= "Off" }, { atNote, mode ~= "Off" }, { smartNote, mode ~= "Off" }, { compEl, mode ~= "Off" } }
				for i = 1, 8 do
					local el, on = rows[i][1], rows[i][2]
					if el then
						Mark.try(function()
							el:SetVisibility(on)
						end)
					end
				end
			end
			pick(fe, "Mode", "FeintMode", { { "Off", "Off" }, { "Chance", "Chance" }, { "Count", "Count" } }, "Chance: rolled per charge. Count: N feints, then a real shot.", feintVis)
			chanceEl = sld(fe, "Chance", "FeintChance", 0, 100, { scale = 100, suffix = "%" })
			countEl = sld(fe, "Feints In A Row", "FeintCount", 1, 5)
			atEl = sld(fe, "Cancel At", "FeintAt", 0.2, 0.38, { prec = 2, suffix = " s" })
			atNote = note(fe, "Or when you release, if that comes first.")
			smartEl = tog(fe, "Smart Select", "FeintSmart")
			smartNote = note(fe, "No feint once the keeper has dived: the shot goes.")
			compEl = tog(fe, "Competitor", "FeintCompetitor", "No feint while an outfield enemy is within 10 studs of the ball.")
			do
				local def = {}
				if CFG.FeintSkipFake ~= false then
					def[#def + 1] = "FAKE"
				end
				if CFG.FeintSkipBounce ~= false then
					def[#def + 1] = "Bounce FAKE"
				end
				skipEl = fe:Dropdown({
					Name = "Never Feint On",
					Options = { "FAKE", "Bounce FAKE" },
					Multi = true,
					Default = def,
					Callback = function(sel)
						local on = {}
						if type(sel) == "table" then
							for k, v in pairs(sel) do
								if v == true then
									on[k] = true
								elseif type(v) == "string" then
									on[v] = true
								end
							end
						end
						CFG.FeintSkipFake = on["FAKE"] == true
						CFG.FeintSkipBounce = on["Bounce FAKE"] == true
					end,
				}, fl("FeintSkip"))
			end
			feintVis()

			local ds = card(tab, "Right")
			head(ds, "Direction Spoof")
			tog(ds, "Enabled", "DirSpoof", "Fake aim shown to the keeper while charging, then the real shot.")
			sld(ds, "Chance", "DirSpoofChance", 0, 100, { scale = 100, suffix = "%" })
			sld(ds, "Fake Speed", "DirSpoofSpeed", 2, 40, { suffix = " /s", text = "Slowest fake move; it speeds up to arrive." })
			tog(ds, "Show Fake Marker", "DrawSpoof", "Marks the fake aim point on the goal.")
			drop(ds, "Preset", "DirSpoofPreset", { "Safe", "Normal", "Long", "Custom" }, "How long the fake aim and the body lie.")
			tog(ds, "Smart Select", "DirSpoofSmart", "No spoof once the keeper has dived.")
			tog(ds, "Pro Patterns", "DirSpoofPro", "Human-like fake patterns only.")
			advanced(ds, "Spoof", function()
				sld(ds, "Custom Fake Time", "DirSpoofTime", 0.04, 0.24, { prec = 2, suffix = " s", text = "Preset Custom: how long the fake aim shows." })
			end)

			local bs = card(tab, "Right")
			head(bs, "Body Spoof")
			tog(bs, "Enabled", "FaceSpoof", "Your body faces the wrong way to fool the keeper.")
			drop(bs, "Mode", "FaceSpoofMode", { "smart", "spin", "side", "lookoff", "away", "decoy" })
			sld(bs, "Turn Speed", "FaceSpoofSpeed", 90, 1440, { suffix = " °/s", text = "How fast the body turns. Max = instant." })
			drop(bs, "When", "FaceSpoofWhen", { "charge", "ball", "always" }, "Charge: while you charge a shot. Ball: while you have it.")
			sld(bs, "Spin Speed", "FaceSpinSpeed", 1, 6, { prec = 1, suffix = " /s" })
			advanced(bs, "BodySpoof", function()
				sld(bs, "Custom Body Time", "FaceSpoofTime", 0.04, 0.24, { prec = 2, suffix = " s", text = "Preset Custom: how long the body lies." })
			end)

			local b = card(tab, "Left")
			head(b, "Bounce FAKE")
			tog(b, "Enabled", "BounceFAKE", "A shot that bounces off a wall and comes back to you.")
			sld(b, "Chance", "BounceFakeChance", 0, 100, { scale = 100, suffix = "%" })
			sld(b, "Extra Height", "BounceFakeHeight", 0, 10, { prec = 1, suffix = " st", text = "Raises the aim points, out of the keeper's jump." })
			sld(b, "Max Distance To Goal", "BounceFakeRange", 30, 160, { suffix = " st" })
			advanced(b, "BounceFake", function()
				sld(b, "Run Allowance", "BounceFakeRun", 4, 24, { suffix = " st", text = "How far you may run for the returning ball." })
				sld(b, "Return Slack", "BounceFakeSlack", 0.5, 8, { prec = 1, suffix = " st" })
				sld(b, "Walls Tried", "BounceFakeMaxSim", 2, 20, { text = "Higher finds more, delays the preview." })
				sld(b, "Flight Steps", "BounceFakeSteps", 20, 90)
			end)

			local v = card(tab, "Left")
			head(v, "AutoShoot · Shot Preview")
			tog(v, "Show Preview", "DrawShot")
			drop(v, "Style", "ShotStyle", { "aurora", "classic" }, "Classic uses the colors from Visuals.")
			if Mark.artPal then
				head(v, "High Shots")
				palette(v, "hi", { "Color 1", "Color 2", "Color 3" })
				head(v, "Low Shots")
				palette(v, "lo", { "Color 1", "Color 2", "Color 3" })
				head(v, "Curled Shots")
				palette(v, "curl", { "Color 1", "Color 2", "Color 3" })
			end

			-- right column -----------------------------------------------------------------------------------
			local ty = card(tab, "Right")
			head(ty, "AutoShoot · Shot Types")
			typeList(ty, "Allowed Types", "ShotBan", "ShotTypes", SHOT_TYPES, "Unchecked types are never used.")
			tog(ty, "Prefer Corner Curl", "PreferCornerCurl")
			tog(ty, "Only Trick / Dip", "OnlyTrick")
			advanced(ty, "Weights", function()
				note(ty, "All 100% = default mix. Move one and your weights decide. 0% = never.")
				local W_TYPES = { { "curl", "High Curl (top corner)" }, { "high", "High (straight)" } }
				for _, t in ipairs(SHOT_TYPES) do
					if t[1] ~= "high" then
						W_TYPES[#W_TYPES + 1] = t
					end
				end
				for _, t in ipairs(W_TYPES) do
					keep(ty:Slider({
						Name = t[2],
						Default = math.clamp(round(((CFG.ShotWeight and CFG.ShotWeight[t[1]]) or 1) * 100, 0), 0, 300),
						Minimum = 0,
						Maximum = 300,
						Precision = 0,
						Suffix = "%",
						Callback = function(x)
							CFG.ShotWeight = CFG.ShotWeight or {}
							CFG.ShotWeight[t[1]] = x / 100
						end,
					}, fl("W_" .. t[1])))
				end
			end, "Edit Weights")

			local f = card(tab, "Right")
			head(f, "FAKE")
			tog(f, "Enabled", "FakeShot", "A shot through a teammate in front of goal.")
			tog(f, "Friends First", "PrioritizeFriends")
			tog(f, "Curved FAKE", "FakeCurve")
			tog(f, "Corner Name", "FakeCorner", "Labels it FAKE CORNER when it lands in a corner.")
			advanced(f, "Fake", function()
				head(f, "Teammate Rules")
				sld(f, "Max Distance To Goal", "FakeMaxDepth", 30, 160, { suffix = " st" })
				sld(f, "Defender Clearance", "FakeFoeRadius", 2, 14, { suffix = " st", text = "An enemy this close to him takes the ball." })
				sld(f, "Side Tolerance", "FakeLatMul", 1, 3, { prec = 1, suffix = "x", text = "How far off the goal his line may be. Curves bend it back." })
				sld(f, "Slack", "FakeSlop", 1, 12, { suffix = " st" })
				sld(f, "Fallback Chance", "FakeChance", 0, 100, { scale = 100, suffix = "%", text = "Used when FAKE is not tried first." })
			end)

			local fk = card(tab, "Right")
			head(fk, "Flick")
			tog(fk, "Auto Flick", "AutoFlick", "The flick key runs flick, jump and volley for you.")
			tog(fk, "Auto Jump", "FlickAutoJump")
			tog(fk, "Auto Kick", "FlickAutoKick", "Off: you kick, the aim stays locked.")
			typeList(fk, "Flick Shot Types", "FlickBan", "FlickTypes", SHOT_TYPES, "Used while a flick or volley is aimed.")
			advanced(fk, "Flick", function()
				sld(fk, "Jump Timing", "AerialJumpLead", 0.1, 0.5, { prec = 2, suffix = " s", text = "Jumps this long before the ball arrives." })
			end)
		end)

		-- ==================================================================================================
		-- DEFENSE
		-- ==================================================================================================
		block("Defense", function()
			local tab = T.Defense

			-- AutoTackle -----------------------------------------------------------------------------------
			local s = card(tab, "Left")
			head(s, "AutoTackle")
			feature(s, "AutoTackle", "AutoTackle")
			sld(s, "Confidence", "TackleConfidence", 0, 100, { scale = 100, suffix = "%", text = "Hit chance needed while his dribble is ready." })
			sld(s, "Confidence (Dribble Spent)", "TackleNakedConf", 0, 100, { scale = 100, suffix = "%", text = "Hit chance needed after he used his dribble." })
			sld(s, "Reach", "TackleReach", 8, 30, { suffix = " st" })
			sld(s, "Slide Power", "TackleSpeed", 0.8, 1.6, {
				prec = 2, suffix = "x",
				set = function(x)
					SlideTackle.SetSpeedMultiplier(x)
				end,
			})
			pick(s, "Priority", "TackleVsBlock", { { "Block First", "block" }, { "Smart", "smart" }, { "Tackle First", "tackle" } }, "Block First: waits for AutoBlock while it is on him.")
			tog(s, "Competitor Check", "TackleCompetitor", "Skips a carrier a teammate is already on.")
			tog(s, "Perfect Mode", "TacklePerfect", "Slide only when his dribble can't save him.")
			sld(s, "Competitor Radius", "TackleCompetitorRadius", 3, 25, { suffix = " st" })
			head(s, "Visual")
			tog(s, "Show Prediction", "DrawTackle")
			drop(s, "Sight Style", "SightStyle", { "reticle", "classic" })
			advanced(s, "Tackle", function()
				sld(s, "Goal Zone", "TackleGoalZone", 0, 80, { suffix = " st", text = "Near our goal, tackle without waiting for AutoBlock." })
				sld(s, "Max Block Wait", "TackleHoldMax", 0.2, 2, { prec = 1, suffix = " s", text = "Block First: longest the tackle waits for the block." })
				sld(s, "Track Radius", "TrackStuds", 30, 160, { suffix = " st" })
				sld(s, "Min Slide Power", "TackleMinSpeed", 0.3, 1.2, { prec = 2, suffix = "x" })
			end)

			local mt = card(tab, "Left")
			head(mt, "Manual Tackle")
			tog(mt, "Enabled", "ManualTackle", "Your own tackle press is aimed at the carrier.")
			bind(mt, "Manual Tackle Key", "KB_ManualTackle", function()
				Mark.manualFire()
			end)
			sld(mt, "Radius", "ManualRadius", 8, 50, { suffix = " st" })

			-- AutoBlock ------------------------------------------------------------------------------------
			local b = card(tab, "Left")
			head(b, "AutoBlock")
			feature(b, "AutoBlock", "AutoBlock")
			note(b, "Team defence: press the carrier, or mark the enemy nobody covers.")
			tog(b, "Respect Mates' Roles", "BlockCompetitor", "Off: you always press the carrier.")
			sld(b, "Competitor Radius", "CompetitorRadius", 4, 30, { suffix = " st" })
			sld(b, "Ignore Near Goals", "CompetitorGoalZone", 0, 120, { suffix = " st", text = "Near either goal: ignore teammates. 0 = off." })
			sld(b, "Ignore With Enemy Near", "CompetitorEnemyNear", 0, 40, { suffix = " st", text = "An enemy this close to the ball: no competitor checks." })
			tog(b, "Yield To Enemy Keeper", "BallYieldKeeper", "AutoBall stops when their keeper gets to the ball first.")
			sld(b, "Press Distance", "RolePressGap", 2, 14, { prec = 1, suffix = " st", text = "Gap in front of the carrier." })
			tog(b, "Full Defense", "FullDefensive", "2+ enemies at the goal: hold it like a keeper.")
			tog(b, "Show Marking", "DrawBlock", "Shows your spot.")

			-- AutoKick -------------------------------------------------------------------------------------
			local k = card(tab, "Left")
			head(k, "AutoKick")
			feature(k, "AutoKick", "AutoKick")
			note(k, "Kicks the ball off the carrier.")
			tog(k, "Run To Kick", "AutoKickMove", "Moves you to the carrier while a kick charges, yours too.")
			tog(k, "Always Full Charge", "AutoKickFull", "Always charges the kick fully.")
			sld(k, "Confidence", "AutoKickConf", 0.3, 0.95, { prec = 2, text = "How sure the hit must be." })
			sld(k, "Range", "AutoKickRange", 2, 30, { prec = 1, suffix = " st" })
			sld(k, "Walk Me On My Kick", "AutoKickUserRange", 5, 60, { prec = 0, suffix = " st", text = "Walks you to a carrier this close while you charge." })
			advanced(k, "Kick", function()
				sld(k, "Cooldown", "AutoKickCooldown", 0.2, 2, { prec = 2, suffix = " s" })
				sld(k, "Run-Up", "AutoKickLead", 0.1, 1, { prec = 2, suffix = " s" })
				sld(k, "Cancel Under", "AutoKickCancel", 0.05, 0.6, { prec = 2 })
			end)

			-- Kick Helper -----------------------------------------------------------------------------------
			local kh = card(tab, "Right")
			head(kh, "Kick Helper")
			tog(kh, "Enabled", "KickHelper", "Turns you to the carrier while you charge a kick.")
			sld(kh, "Range", "KickHelperRange", 10, 80, { suffix = " st" })

			-- AutoDribble ----------------------------------------------------------------------------------
			local d = card(tab, "Right")
			head(d, "AutoDribble")
			feature(d, "AutoDribble", "AutoDribble")
			tog(d, "Agent Addon", "AgentAddon", "Dodges through the tackler.")
			tog(d, "Show Threat", "DrawDanger")
			advanced(d, "Dribble", function()
				sld(d, "React Range", "DribbleReact", 10, 40, { suffix = " st" })
				sld(d, "Close Range", "DribbleClose", 5, 25, { suffix = " st" })
				sld(d, "Margin", "DribbleSlop", 1, 8, { prec = 1, suffix = " st" })
			end)

			-- AutoDodge ------------------------------------------------------------------------------------
			local dg = card(tab, "Right")
			head(dg, "AutoDodge")
			feature(dg, "AutoDodge", "AutoDodge")
			note(dg, "Dodges tackles and keeps you out of blasts.")
			pick(dg, "Dodge Mode", "DodgeTeleport", { { "Teleport + Movement", true }, { "Movement Only", false } }, "Movement Only never moves the character by CFrame.")
			tog(dg, "Pass Instead", "PassAssistSync", "Passes the ball away when you can't escape.")
			tog(dg, "Show Danger Zones", "DrawHazard", "Shows where blasts and projectiles will hit.")
			advanced(dg, "Dodge", function()
				head(dg, "Projectiles")
				sld(dg, "Safe Margin", "ProjSafeMargin", 0, 4, { prec = 1, suffix = " st" })
				sld(dg, "Punch Radius", "ProjHitRadius", 2, 10, { prec = 1, suffix = " st" })
				head(dg, "Hazards")
				sld(dg, "Blast Margin", "BlastMargin", 0, 5, { prec = 1, suffix = " st" })
				sld(dg, "Pass Before Blast", "HazPassSlack", 0, 6, { prec = 1, suffix = " st", text = "Passes if the escape is this close." })
				sld(dg, "Mine Margin", "MineMargin", 0, 6, { prec = 1, suffix = " st" })
			end)

			-- CounterJump ----------------------------------------------------------------------------------
			local c = card(tab, "Right")
			head(c, "CounterJump")
			feature(c, "CounterJump", "CounterJump")
			note(c, "Stops enemies in the air and their flicks.")
			tog(c, "Show Plan", "DrawDuel", "Shows the counter as lightning.")
			tog(c, "Move To Him", "CounterMove", "Runs you to the take-off point.")
			tog(c, "Counter Tackle", "CounterTackle", "Uses a tackle for the counter.")
			tog(c, "Competitor Check", "CounterCompetitor", "Stops when a teammate is already on him.")
			sld(c, "Competitor Radius", "CounterCompetitorRadius", 4, 30, { suffix = " st" })
			advanced(c, "Counter", function()
				sld(c, "Range", "CounterJumpRange", 8, 40, { suffix = " st" })
				sld(c, "Air Slide Range", "CounterAirSlide", 4, 60, { suffix = " st", text = "Max range of an air slide." })
			end)

			-- Air Intercept -------------------------------------------------------------------------------
			local ai = card(tab, "Right")
			head(ai, "Air Intercept")
			feature(ai, "Air Intercept", "AirIntercept")
			note(ai, "Volley or bicycle a flying ball before anyone.")
			advanced(ai, "Air", function()
				sld(ai, "Reach Slack", "AirSlack", 0, 3, { prec = 1, suffix = " st", text = "Extra studs over the game's miss tolerance." })
				sld(ai, "Tolerance Time", "AirTolT", 0.1, 0.4, { prec = 2, suffix = " s" })
			end)
		end)

		-- ==================================================================================================
		-- GOALKEEPER
		-- ==================================================================================================
